// 僅供 P17 歷史證據的唯讀 Git 查核；不可退回系統的 xcrun launcher。
fn verified_review_git(root: &Path) -> Result<Command, String> {
    #[cfg(target_os = "macos")]
    let executable = {
        const GIT: &str = "/Library/Developer/CommandLineTools/usr/bin/git";
        const DIGEST: &str = "a73bf622a2e470d5d57a4b1d5aef1e8680e67278018d4858a2f93825b7d595c7";
        let path = Path::new(GIT);
        if fs::canonicalize(path).map_err(|error| error.to_string())? != path
            || !fs::symlink_metadata(path)
                .map_err(|error| error.to_string())?
                .file_type()
                .is_file()
            || manifest::sha256(path)? != DIGEST
        {
            return Err("P17 唯讀 Git 實體路徑／SHA 不符".into());
        }
        // no-index diff 與 ls-tree 不需要 hooks；拒絕可能轉交外部程式的本地設定。
        review_git_metadata(root)?;
        path
    };
    #[cfg(not(target_os = "macos"))]
    let executable = Path::new("git");
    let mut command = Command::new(executable);
    command
        .env_clear()
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env("GIT_CONFIG_GLOBAL", "/dev/null")
        .env("GIT_ATTR_NOSYSTEM", "1")
        .arg("--no-pager")
        .args(["-c", "color.ui=false"])
        .current_dir(root);
    Ok(command)
}

#[cfg(target_os = "macos")]
fn review_git_single_line(path: &Path) -> Result<String, String> {
    if !fs::symlink_metadata(path)
        .map_err(|error| error.to_string())?
        .file_type()
        .is_file()
    {
        return Err(format!("P17 Git metadata 非一般檔案：{}", path.display()));
    }
    let body = fs::read_to_string(path).map_err(|error| error.to_string())?;
    let line = body.strip_suffix('\n').unwrap_or(&body);
    if line.is_empty() || line.chars().any(|ch| matches!(ch, '\n' | '\r' | '\0')) {
        return Err(format!("P17 Git metadata 非單行：{}", path.display()));
    }
    Ok(line.into())
}

#[cfg(target_os = "macos")]
fn review_git_optional_config(path: &Path) -> Result<(), String> {
    match fs::symlink_metadata(path) {
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error.to_string()),
        Ok(metadata) if metadata.file_type().is_file() => {
            if review_git_config_safe(&fs::read_to_string(path).map_err(|error| error.to_string())?) {
                Ok(())
            } else {
                Err(format!("P17 Git config 含未驗證啟動鏈：{}", path.display()))
            }
        }
        Ok(_) => Err(format!("P17 Git config 非一般檔案：{}", path.display())),
    }
}

#[cfg(target_os = "macos")]
fn review_git_no_attributes(path: &Path) -> Result<(), String> {
    match fs::symlink_metadata(path) {
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(error.to_string()),
        Ok(_) => Err(format!("P17 Git attributes 未驗證：{}", path.display())),
    }
}

#[cfg(target_os = "macos")]
fn review_git_metadata(root: &Path) -> Result<(), String> {
    let marker = root.join(".git");
    let kind = fs::symlink_metadata(&marker)
        .map_err(|error| error.to_string())?
        .file_type();
    let (common, admin) = if kind.is_dir() {
        if fs::canonicalize(&marker).map_err(|error| error.to_string())? != marker {
            return Err("P17 Git common dir 非原路徑".into());
        }
        (marker, None)
    } else if kind.is_file() {
        let pointer = review_git_single_line(&marker)?;
        let admin = PathBuf::from(pointer.strip_prefix("gitdir: ").ok_or("P17 Git worktree pointer 格式不符")?);
        if !admin.is_absolute()
            || admin
                .components()
                .any(|part| !matches!(part, Component::RootDir | Component::Normal(_)))
            || !fs::symlink_metadata(&admin)
                .map_err(|error| error.to_string())?
                .file_type()
                .is_dir()
            || fs::canonicalize(&admin).map_err(|error| error.to_string())? != admin
        {
            return Err("P17 Git worktree admin 越界／非一般目錄".into());
        }
        let evidence = runner::environment(root)?.evidence_dir;
        let baseline = evidence.join("p17-exit-before-20261011-1/manifest.json");
        sha(&baseline, EXIT_PRODUCT_BASELINE_SHA)?;
        let value = StrictJsonParser::parse(
            &fs::read_to_string(&baseline).map_err(|error| error.to_string())?,
        )?;
        if string(&value, "schema")? != "rivetlua-p17-exit-producer-baseline-v1" {
            return Err("P17 Git worktree 原repo baseline 不符".into());
        }
        let original = PathBuf::from(string(&value, "root")?);
        let common = fs::canonicalize(original.join(".git"))
            .map_err(|error| error.to_string())?;
        let worktrees = common.join("worktrees");
        let relative = admin
            .strip_prefix(&worktrees)
            .map_err(|_| "P17 Git worktree admin 非原repo子目錄")?;
        if !fs::symlink_metadata(&common)
            .map_err(|error| error.to_string())?
            .file_type()
            .is_dir()
            || !fs::symlink_metadata(&worktrees)
                .map_err(|error| error.to_string())?
                .file_type()
                .is_dir()
            || relative.components().count() != 1
            || !matches!(relative.components().next(), Some(Component::Normal(_)))
            || review_git_single_line(&admin.join("gitdir"))? != marker.display().to_string()
            || review_git_single_line(&admin.join("commondir"))? != "../.."
            || fs::canonicalize(admin.join("../.."))
                .map_err(|error| error.to_string())?
                != common
        {
            return Err("P17 Git worktree 反向指標／common dir 不符".into());
        }
        (common, Some(admin))
    } else {
        return Err("P17 Git metadata 非一般目錄／worktree檔案".into());
    };
    let common_config = common.join("config");
    if !fs::symlink_metadata(&common_config)
        .map_err(|error| error.to_string())?
        .file_type()
        .is_file()
    {
        return Err("P17 Git common config 非一般檔案".into());
    }
    review_git_optional_config(&common_config)?;
    review_git_optional_config(&common.join("config.worktree"))?;
    if let Some(admin) = &admin {
        review_git_optional_config(&admin.join("config.worktree"))?;
        review_git_no_attributes(&admin.join("info/attributes"))?;
    }
    review_git_no_attributes(&root.join(".gitattributes"))?;
    review_git_no_attributes(&common.join("info/attributes"))
}

fn review_git_config_safe(config: &str) -> bool {
    if config.contains('\0') || config.contains('\r') {
        return false;
    }
    let mut section = "";
    let mut sections = BTreeSet::new();
    let mut keys = BTreeSet::new();
    for line in config.lines() {
        if line.is_empty() {
            continue;
        }
        if line.starts_with('[') {
            if !["[core]", "[remote \"origin\"]", "[branch \"main\"]"].contains(&line)
                || !sections.insert(line)
            {
                return false;
            }
            section = line;
            continue;
        }
        let entry = line.strip_prefix('\t').unwrap_or(line);
        let Some((key, value)) = entry.split_once(" = ") else {
            return false;
        };
        if !keys.insert((section, key))
            || !matches!(
                (section, key, value),
                ("[core]", "repositoryformatversion", "0")
                    | ("[core]", "filemode", "true")
                    | ("[core]", "bare", "false")
                    | ("[core]", "logallrefupdates", "true")
                    | ("[core]", "precomposeunicode", "true")
                    | (
                        "[remote \"origin\"]",
                        "url",
                        "git@github.com:SDpower/RivetLua.git"
                    )
                    | (
                        "[remote \"origin\"]",
                        "fetch",
                        "+refs/heads/*:refs/remotes/origin/*"
                    )
                    | ("[branch \"main\"]", "remote", "origin")
                    | ("[branch \"main\"]", "merge", "refs/heads/main")
            )
        {
            return false;
        }
    }
    true
}

