fn object<'a>(
    value: &'a StrictJsonValue,
    keys: &[&str],
) -> Result<&'a [(String, StrictJsonValue)], String> {
    let StrictJsonValue::Object(entries) = value else {
        return Err("P17 B03 JSON 非物件".into());
    };
    let actual = entries
        .iter()
        .map(|(name, _)| name.as_str())
        .collect::<BTreeSet<_>>();
    if entries.len() != keys.len() || actual != keys.iter().copied().collect() {
        return Err(format!("P17 B03 JSON 欄位不符：預期 {keys:?}"));
    }
    Ok(entries)
}

fn field<'a>(value: &'a StrictJsonValue, key: &str) -> Result<&'a StrictJsonValue, String> {
    value.get(key).ok_or_else(|| format!("P17 B03 缺少 {key}"))
}

fn string<'a>(value: &'a StrictJsonValue, key: &str) -> Result<&'a str, String> {
    field(value, key)?
        .as_str()
        .ok_or_else(|| format!("P17 B03 {key} 非字串"))
}

fn array<'a>(value: &'a StrictJsonValue, key: &str) -> Result<&'a [StrictJsonValue], String> {
    field(value, key)?
        .as_array()
        .ok_or_else(|| format!("P17 B03 {key} 非陣列"))
}

fn integer(value: &StrictJsonValue, key: &str) -> Result<u64, String> {
    match field(value, key)? {
        StrictJsonValue::Number(value) if !value.contains(['.', 'e', 'E']) => value
            .parse::<u64>()
            .map_err(|_| format!("P17 B03 {key} 非非負整數")),
        _ => Err(format!("P17 B03 {key} 非整數")),
    }
}

fn boolean(value: &StrictJsonValue, key: &str) -> Result<bool, String> {
    match field(value, key)? {
        StrictJsonValue::Bool(value) => Ok(*value),
        _ => Err(format!("P17 B03 {key} 非布林值")),
    }
}

fn strings(value: &StrictJsonValue, key: &str) -> Result<Vec<String>, String> {
    array(value, key)?
        .iter()
        .map(|item| {
            item.as_str()
                .map(str::to_owned)
                .ok_or_else(|| format!("P17 B03 {key} 元素非字串"))
        })
        .collect()
}

fn integers(value: &StrictJsonValue, key: &str) -> Result<Vec<u64>, String> {
    array(value, key)?
        .iter()
        .map(|item| match item {
            StrictJsonValue::Number(number) if !number.contains(['.', 'e', 'E']) => number
                .parse::<u64>()
                .map_err(|_| format!("P17 B03 {key} 元素非非負整數")),
            _ => Err(format!("P17 B03 {key} 元素非整數")),
        })
        .collect()
}

#[track_caller]
fn input(value: &StrictJsonValue) -> Result<report::Input, String> {
    object(value, &["path", "sha256"])?;
    let path = string(value, "path")?;
    if !Path::new(path).is_absolute() {
        return Err("P17 B03 input 非絕對路徑".into());
    }
    let result = report::Input::from_path(Path::new(path))?;
    let expected_sha256 = string(value, "sha256")?;
    if result.sha256 != expected_sha256 {
        let caller = std::panic::Location::caller();
        return Err(format!(
            "P17 B03 input SHA 不符：{path}；actual={}；expected={expected_sha256}；caller={}:{}",
            result.sha256,
            caller.file(),
            caller.line()
        ));
    }
    Ok(result)
}

fn json_strings(items: &[String]) -> String {
    items
        .iter()
        .map(|value| report::q(value))
        .collect::<Vec<_>>()
        .join(",")
}

fn sha(path: &Path, expected: &str) -> Result<(), String> {
    if manifest::sha256(path)? != expected {
        return Err(format!("P17 B03 SHA 不符：{}", path.display()));
    }
    Ok(())
}

fn repo_source(root: &Path, value: &str) -> Result<PathBuf, String> {
    let relative = Path::new(value);
    if relative.is_absolute()
        || relative
            .components()
            .any(|part| !matches!(part, Component::Normal(_)))
    {
        return Err(format!("P17 B03 source path 越界：{value}"));
    }
    let path = root.join(relative);
    if !path.is_file() {
        return Err(format!("P17 B03 source 缺失：{value}"));
    }
    Ok(path)
}

#[derive(Clone)]
struct CorpusFamily {
    case_id: String,
    seed: u64,
    budget: u32,
    limits: String,
    fixtures: Vec<report::Input>,
}

struct Registry {
    corpus: report::Input,
    capabilities: report::Input,
    families: Vec<CorpusFamily>,
}

fn canonical_json(value: &StrictJsonValue) -> String {
    match value {
        StrictJsonValue::Object(entries) => format!(
            "{{{}}}",
            entries
                .iter()
                .map(|(key, value)| format!("{}:{}", report::q(key), canonical_json(value)))
                .collect::<Vec<_>>()
                .join(",")
        ),
        StrictJsonValue::Array(items) => format!(
            "[{}]",
            items
                .iter()
                .map(canonical_json)
                .collect::<Vec<_>>()
                .join(",")
        ),
        StrictJsonValue::String(value) => report::q(value),
        StrictJsonValue::Number(value) => value.clone(),
        StrictJsonValue::Bool(value) => value.to_string(),
        StrictJsonValue::Null => "null".into(),
    }
}

fn positive_limit_tree(value: &StrictJsonValue) -> Result<(), String> {
    match value {
        StrictJsonValue::Object(entries) if !entries.is_empty() => {
            for (_, child) in entries {
                positive_limit_tree(child)?;
            }
            Ok(())
        }
        StrictJsonValue::Number(value)
            if value.parse::<u64>().ok().is_some_and(|number| number > 0) =>
        {
            Ok(())
        }
        _ => Err("P17 B03 fuzz limits 必須是正整數樹".into()),
    }
}

fn parse_registry(root: &Path, target: &str) -> Result<Registry, String> {
    let corpus_path = root.join("tests/p17/stress/fuzz-corpus.json");
    let capabilities_path = root.join("tests/p17/stress/platform-capabilities.json");
    let corpus_value = StrictJsonParser::parse(
        &fs::read_to_string(&corpus_path).map_err(|error| error.to_string())?,
    )?;
    object(&corpus_value, &["schema", "families"])?;
    if string(&corpus_value, "schema")? != "rivetlua-p17-fuzz-corpus-v1" {
        return Err("P17 B03 corpus schema 不符".into());
    }
    let expected = [
        ("p17_fuzz_parser", SEED_PARSER),
        ("p17_fuzz_rvlu", SEED_RVLU),
        ("p17_fuzz_official_chunk", SEED_OFFICIAL),
    ];
    let source_families = array(&corpus_value, "families")?;
    if source_families.len() != expected.len() {
        return Err("P17 B03 corpus family 數不符".into());
    }
    let mut families = Vec::new();
    for (entry, (case_id, seed)) in source_families.iter().zip(expected) {
        object(entry, &["case_id", "seed", "budget", "limits", "fixtures"])?;
        if string(entry, "case_id")? != case_id
            || integer(entry, "seed")? != seed
            || integer(entry, "budget")? != 128
        {
            return Err(format!("P17 B03 corpus seed/budget 不符：{case_id}"));
        }
        let limits = field(entry, "limits")?;
        positive_limit_tree(limits)?;
        let mut fixtures = Vec::new();
        let mut paths = BTreeSet::new();
        for (fixture_index, fixture) in array(entry, "fixtures")?.iter().enumerate() {
            object(fixture, &["path", "sha256"])?;
            let relative = string(fixture, "path")?;
            let path = repo_source(root, relative)?;
            if case_id == "p17_fuzz_official_chunk" {
                let (expected_path, expected_sha) = OFFICIAL_FIXTURES
                    .get(fixture_index)
                    .ok_or("P17 B03 official fixture 超額")?;
                if relative != *expected_path || string(fixture, "sha256")? != *expected_sha {
                    return Err("P17 B03 official golden fixture 不符".into());
                }
            }
            if !paths.insert(relative) {
                return Err("P17 B03 corpus fixture 重複".into());
            }
            sha(&path, string(fixture, "sha256")?)?;
            fixtures.push(report::Input::from_path(&path)?);
        }
        if (case_id == "p17_fuzz_official_chunk" && fixtures.len() != 6)
            || (case_id != "p17_fuzz_official_chunk" && !fixtures.is_empty())
        {
            return Err(format!("P17 B03 corpus fixture 數不符：{case_id}"));
        }
        families.push(CorpusFamily {
            case_id: case_id.into(),
            seed,
            budget: 128,
            limits: canonical_json(limits),
            fixtures,
        });
    }
    let capabilities = StrictJsonParser::parse(
        &fs::read_to_string(&capabilities_path).map_err(|error| error.to_string())?,
    )?;
    object(
        &capabilities,
        &["schema", "profiles", "target", "case_ids", "expected"],
    )?;
    if string(&capabilities, "schema")? != "rivetlua-p17-platform-capabilities-v1"
        || strings(&capabilities, "profiles")? != PROFILES
        || string(&capabilities, "target")? != target
        || strings(&capabilities, "case_ids")? != ["p17_platform_cli", "p17_platform_c"]
    {
        return Err("P17 B03 platform registry 主鍵不符".into());
    }
    let platform_expected = field(&capabilities, "expected")?;
    object(platform_expected, &["cli", "c"])?;
    let cli = field(platform_expected, "cli")?;
    object(
        cli,
        &[
            "os_tmpname",
            "os_time",
            "os_execute",
            "os_difftime",
            "package_loadlib",
        ],
    )?;
    for name in ["os_tmpname", "os_execute", "package_loadlib"] {
        if string(cli, name)? != "denied" {
            return Err(format!("P17 B03 {name} 預期拒絕不符"));
        }
    }
    if string(cli, "os_time")? != "available" || string(cli, "os_difftime")? != "available" {
        return Err("P17 B03 time/difftime 預期不符".into());
    }
    let c = field(platform_expected, "c")?;
    object(c, &["tmpnam"])?;
    if string(c, "tmpnam")? != "probed" {
        return Err("P17 B03 tmpnam 預期不符".into());
    }
    Ok(Registry {
        corpus: report::Input::from_path(&corpus_path)?,
        capabilities: report::Input::from_path(&capabilities_path)?,
        families,
    })
}

#[derive(Clone)]
struct ProcessResult {
    command: Vec<String>,
    cwd: String,
    environment: Vec<(String, String)>,
    exit_code: Option<i32>,
    timed_out: bool,
    log: report::Input,
    body: String,
}

fn invoke(
    cwd: &Path,
    argv: Vec<String>,
    log: &Path,
    timeout: Duration,
    lua_environment: Option<&Path>,
) -> Result<ProcessResult, String> {
    let (program, args) = argv.split_first().ok_or("P17 B03 空命令")?;
    let mut command = Command::new(program);
    command.args(args).current_dir(cwd);
    let environment = if let Some(grant) = lua_environment {
        runner::effective_native_environment(grant)
    } else {
        runner::effective_no_native_environment()
    };
    for (key, value) in &environment {
        if value == "unset" {
            command.env_remove(key);
        } else {
            command.env(key, value);
        }
    }
    let out = File::create(log).map_err(|error| format!("P17 B03 log 建立失敗：{error}"))?;
    let err = out.try_clone().map_err(|error| error.to_string())?;
    let mut child = command
        .stdout(Stdio::from(out))
        .stderr(Stdio::from(err))
        .spawn()
        .map_err(|error| format!("P17 B03 子行程啟動失敗：{program}: {error}"))?;
    let start = Instant::now();
    let (status, timed_out) = loop {
        if let Some(status) = child.try_wait().map_err(|error| error.to_string())? {
            break (status, false);
        }
        if start.elapsed() >= timeout {
            if let Err(error) = child.kill() {
                if let Some(status) = child
                    .try_wait()
                    .map_err(|wait_error| wait_error.to_string())?
                {
                    break (status, false);
                }
                return Err(format!("P17 B03 timeout kill 失敗：{error}"));
            }
            break (child.wait().map_err(|error| error.to_string())?, true);
        }
        thread::sleep(Duration::from_millis(20));
    };
    let body = fs::read_to_string(log).map_err(|error| format!("P17 B03 log 不可讀：{error}"))?;
    Ok(ProcessResult {
        command: argv,
        cwd: cwd.display().to_string(),
        environment,
        exit_code: status.code(),
        timed_out,
        log: report::Input::from_path(log)?,
        body,
    })
}

#[derive(Default, Debug, PartialEq)]
struct NamedCounts {
    matched: u32,
    passed: u32,
    failed: u32,
    ignored: u32,
}

fn parse_named_log(
    body: &str,
    names: &[&str],
) -> Result<(NamedCounts, BTreeMap<String, &'static str>), String> {
    parse_named_log_with_filter(body, names, false)
}

fn parse_named_log_with_filter(
    body: &str,
    names: &[&str],
    allow_filtered: bool,
) -> Result<(NamedCounts, BTreeMap<String, &'static str>), String> {
    parse_named_log_with_native_progress(body, names, allow_filtered, None)
}

fn parse_named_log_with_native_progress(
    body: &str,
    names: &[&str],
    allow_filtered: bool,
    native_progress: Option<(&str, &Path)>,
) -> Result<(NamedCounts, BTreeMap<String, &'static str>), String> {
    let expected = names.iter().copied().collect::<BTreeSet<_>>();
    if expected.len() != names.len() || expected.is_empty() {
        return Err("P17 B03 空白／重複 selector".into());
    }
    let mut seen = BTreeMap::<String, &'static str>::new();
    let mut pending: Option<String> = None;
    let mut native_pending = false;
    let mut native_seen = 0;
    let mut repl_stdout_pending = 0u8;
    let mut summary = None;
    for line in body.lines() {
        let trimmed = line.trim_start();
        if native_pending {
            if trimmed.trim() != "ok" {
                return Err("P17 Exit native build 後缺精確 ok".into());
            }
            seen.insert(
                pending.take().ok_or("P17 Exit native build 未收尾 selector")?,
                "ok",
            );
            native_pending = false;
            continue;
        }
        if repl_stdout_pending != 0 {
            let expected_line = if repl_stdout_pending == 1 { "true" } else { "ok" };
            if trimmed != expected_line {
                return Err("P17 REPL stdout 交錯後缺精確結果".into());
            }
            if repl_stdout_pending == 1 {
                repl_stdout_pending = 2;
            } else {
                seen.insert(
                    pending.take().ok_or("P17 REPL stdout 未收尾 selector")?,
                    "ok",
                );
                repl_stdout_pending = 0;
            }
            continue;
        }
        if let Some(part) = trimmed
            .strip_prefix("test ")
            .filter(|part| !part.starts_with("result:"))
        {
            let (name, tail) = part.split_once(" ... ").ok_or("P17 B03 test 行格式不符")?;
            if pending.is_some() || !expected.contains(name) || seen.contains_key(name) {
                return Err(format!("P17 B03 重複／未知／未收尾 selector：{name}"));
            }
            if let Some(progress) = tail.strip_prefix("P17_EXIT_NATIVE_BUILD ") {
                let (profile, evidence) = native_progress
                    .ok_or("P17 Exit native build 非授權的具名測試進度")?;
                let fields = progress.split(' ').collect::<Vec<_>>();
                let valid_profile = fields
                    .first()
                    .and_then(|value| value.strip_prefix("profile="))
                    == Some(profile);
                let log = fields
                    .get(1)
                    .and_then(|value| value.strip_prefix("log="))
                    .map(Path::new);
                let digest = fields
                    .get(2)
                    .and_then(|value| value.strip_prefix("sha256="));
                let valid_log = log
                    .and_then(|path| path.strip_prefix(evidence.join("p17-exit-native-fixtures")).ok())
                    .is_some_and(|relative| {
                        relative.components().count() == 2
                            && relative
                                .components()
                                .all(|part| matches!(part, Component::Normal(_)))
                            && relative.file_name().and_then(|name| name.to_str())
                                == Some("exit-probe-build.json")
                    });
                let valid_digest = digest.is_some_and(|value| {
                    value.len() == 64
                        && value
                            .bytes()
                            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
                });
                if name != "p17_exit_uncatchable_boundaries"
                    || native_seen != 0
                    || fields.len() != 3
                    || !valid_profile
                    || !valid_log
                    || !valid_digest
                {
                    return Err("P17 Exit native build 進度欄位不符".into());
                }
                native_seen += 1;
                native_pending = true;
                pending = Some(name.into());
            } else {
                let outcome = tail.split(MARKER).next().unwrap_or("").trim();
                if name == CONSOLE_REPL_SELECTORS[1] && tail == "true" {
                    pending = Some(name.into());
                    repl_stdout_pending = 1;
                } else if outcome.is_empty() {
                    pending = Some(name.into());
                } else {
                    let result = match outcome {
                        "ok" => Some("ok"),
                        "FAILED" => Some("FAILED"),
                        "ignored" => Some("ignored"),
                        _ => None,
                    };
                    if let Some(result) = result {
                        seen.insert(name.into(), result);
                    } else {
                        pending = Some(name.into());
                    }
                }
            }
        } else if let Some(name) = pending.take() {
            let result = match trimmed.trim() {
                "ok" => "ok",
                "FAILED" => "FAILED",
                "ignored" => "ignored",
                _ => {
                    pending = Some(name);
                    continue;
                }
            };
            seen.insert(name, result);
        } else if matches!(trimmed.trim(), "ok" | "FAILED" | "ignored") {
            return Err("P17 B03 孤立 test outcome".into());
        }
        if let Some(rest) = trimmed.strip_prefix("test result: ") {
            if summary.is_some() || pending.is_some() {
                return Err("P17 B03 重複 summary／未收尾 test".into());
            }
            let mut words = rest.split_whitespace();
            let status = words.next().ok_or("P17 B03 summary 空白")?;
            if !["ok.", "FAILED."].contains(&status) {
                return Err("P17 B03 summary outcome 不符".into());
            }
            let items = words.collect::<Vec<_>>();
            let values = [
                "passed;",
                "failed;",
                "ignored;",
                "measured;",
                "filtered out;",
            ];
            let mut numbers = Vec::new();
            let mut index = 0;
            for label in values {
                let number = items
                    .get(index)
                    .ok_or("P17 B03 summary 缺 count")?
                    .parse::<u32>()
                    .map_err(|_| "P17 B03 summary count 不符")?;
                index += 1;
                if label == "filtered out;" {
                    if items.get(index) != Some(&"filtered")
                        || items.get(index + 1) != Some(&"out;")
                    {
                        return Err("P17 B03 summary filtered 不符".into());
                    }
                    index += 2;
                } else if items.get(index) != Some(&label) {
                    return Err("P17 B03 summary label 不符".into());
                } else {
                    index += 1;
                }
                numbers.push(number);
            }
            if numbers[3] != 0 || (!allow_filtered && numbers[4] != 0) {
                return Err("P17 B03 measured/filtered 非零".into());
            }
            summary = Some((status == "ok.", numbers));
        }
    }
    if pending.is_some() || seen.len() != expected.len() {
        return Err("P17 B03 named test 零匹配／缺失".into());
    }
    if native_seen != usize::from(native_progress.is_some())
        || body.matches("P17_EXIT_NATIVE_BUILD ").count() != native_seen
    {
        return Err("P17 Exit native build 進度次數不符".into());
    }
    let (summary_pass, values) = summary.ok_or("P17 B03 缺 libtest summary")?;
    let counts = NamedCounts {
        matched: seen.len() as u32,
        passed: seen.values().filter(|value| **value == "ok").count() as u32,
        failed: seen.values().filter(|value| **value == "FAILED").count() as u32,
        ignored: seen.values().filter(|value| **value == "ignored").count() as u32,
    };
    if values[0] != counts.passed
        || values[1] != counts.failed
        || values[2] != counts.ignored
        || summary_pass != (counts.failed == 0)
    {
        return Err("P17 B03 libtest summary 與具名結果不符".into());
    }
    Ok((counts, seen))
}

fn marker_records(
    body: &str,
    expected: &[&str],
    require_all: bool,
) -> Result<BTreeMap<String, StrictJsonValue>, String> {
    let expected = expected.iter().copied().collect::<BTreeSet<_>>();
    let mut records = BTreeMap::new();
    for line in body.lines() {
        if let Some((_, payload)) = line.split_once(MARKER) {
            let value = StrictJsonParser::parse(payload.trim())?;
            let id = string(&value, "case_id")?;
            if !expected.contains(id) || records.contains_key(id) {
                return Err(format!("P17 B03 未知／重複 marker：{id}"));
            }
            records.insert(id.to_owned(), value);
        }
    }
    if require_all && records.len() != expected.len() {
        return Err("P17 B03 marker 零匹配／缺失".into());
    }
    Ok(records)
}

fn require_number(value: &StrictJsonValue, key: &str, expected: u64) -> Result<(), String> {
    if integer(value, key)? != expected {
        return Err(format!("P17 B03 {key} 值不符"));
    }
    Ok(())
}

fn validate_record(
    value: &StrictJsonValue,
    spec: CaseSpec,
    profile: &str,
    registry: &Registry,
    historical_main_root: bool,
) -> Result<(), String> {
    if string(value, "case_id")? != spec.id
        || string(value, "profile")? != profile
        || string(value, "outcome")? != "PASS"
    {
        return Err(format!("P17 B03 {} identity/outcome 不符", spec.id));
    }
    require_number(value, "seed", spec.seed)?;
    require_number(value, "iterations", spec.iterations.into())?;
    match spec.id {
        "p17_allocator_failure" => {
            object(
                value,
                &[
                    "case_id",
                    "profile",
                    "seed",
                    "iterations",
                    "outcome",
                    "failure_injections",
                    "error_checks",
                    "recovery_checks",
                    "gc_checks",
                    "outstanding_blocks",
                ],
            )?;
            require_number(value, "failure_injections", 129)?;
            for key in ["error_checks", "recovery_checks", "gc_checks"] {
                require_number(value, key, 128)?;
            }
            require_number(value, "outstanding_blocks", 0)?;
        }
        "p17_nested_callback" => {
            object(
                value,
                &[
                    "case_id",
                    "profile",
                    "seed",
                    "iterations",
                    "outcome",
                    "normal_checks",
                    "error_checks",
                    "inner_successes",
                    "inner_errors",
                    "gc_checks",
                    "outstanding_blocks",
                ],
            )?;
            for key in [
                "normal_checks",
                "error_checks",
                "inner_successes",
                "inner_errors",
            ] {
                require_number(value, key, 128)?;
            }
            require_number(value, "gc_checks", 16)?;
            require_number(value, "outstanding_blocks", 0)?;
        }
        "p17_stress_gc_long_run" | "p17_stress_coroutine_debug" => {
            for key in ["guest_operations", "gc_cycles", "peak_committed"] {
                if integer(value, key)? == 0 {
                    return Err(format!("P17 B03 {key} 零值"));
                }
            }
            require_number(value, "ledger_committed", 0)?;
            require_number(value, "ledger_reserved", 0)?;
            require_number(value, "root_count", if spec.id == "p17_stress_coroutine_debug"
                && !historical_main_root { 1 } else { 0 })?;
            if spec.id == "p17_stress_gc_long_run" {
                object(
                    value,
                    &[
                        "case_id",
                        "profile",
                        "seed",
                        "iterations",
                        "outcome",
                        "guest_operations",
                        "normal_operations",
                        "error_operations",
                        "gc_cycles",
                        "root_count",
                        "ledger_committed",
                        "ledger_reserved",
                        "peak_committed",
                    ],
                )?;
                require_number(value, "guest_operations", 8192)?;
                require_number(value, "normal_operations", 4096)?;
                require_number(value, "error_operations", 4096)?;
                require_number(value, "gc_cycles", 384)?;
            } else {
                object(
                    value,
                    &[
                        "case_id",
                        "profile",
                        "seed",
                        "iterations",
                        "outcome",
                        "guest_operations",
                        "gc_cycles",
                        "root_count",
                        "ledger_committed",
                        "ledger_reserved",
                        "peak_committed",
                    ],
                )?;
                require_number(value, "guest_operations", 640)?;
                require_number(value, "gc_cycles", 384)?;
            }
        }
        "p17_fuzz_parser" | "p17_fuzz_rvlu" | "p17_fuzz_official_chunk" => {
            let accepted = integer(value, "accepted")?;
            let rejected = integer(value, "rejected")?;
            if accepted == 0 || rejected == 0 || accepted + rejected != 128 {
                return Err("P17 B03 fuzz 計數不符".into());
            }
            let family = registry
                .families
                .iter()
                .find(|item| item.case_id == spec.id)
                .ok_or("P17 B03 fuzz family 缺失")?;
            if family.seed != spec.seed || family.budget != spec.iterations {
                return Err("P17 B03 fuzz seed/budget registry 不符".into());
            }
            if spec.id != "p17_fuzz_official_chunk" {
                let limits = field(value, "limits")?;
                if canonical_json(limits) != family.limits {
                    return Err("P17 B03 fuzz limits 與 registry 不符".into());
                }
                let baseline = string(value, "baseline_source")?;
                if baseline.trim().len() < 8 {
                    return Err("P17 B03 fuzz baseline 缺失".into());
                }
                let (flag, minimum) = if spec.id == "p17_fuzz_parser" {
                    ("counts_include_baseline_and_four_explicit_rejections", 4)
                } else {
                    (
                        "counts_include_baseline_and_twelve_explicit_negative_cases",
                        12,
                    )
                };
                if !boolean(value, flag)? || integer(value, "explicit_negative_rejects")? < minimum
                {
                    return Err("P17 B03 fuzz explicit negative 缺失".into());
                }
                object(
                    value,
                    &[
                        "case_id",
                        "profile",
                        "seed",
                        "iterations",
                        "outcome",
                        "accepted",
                        "rejected",
                        "limits",
                        "baseline_source",
                        "explicit_negative_rejects",
                        flag,
                    ],
                )?;
            } else {
                let official = field(value, "official")?;
                object(
                    official,
                    &[
                        "version_marker",
                        "chunk_limits",
                        "verify_limits",
                        "work_budget",
                        "baseline_fixtures",
                    ],
                )?;
                require_number(
                    official,
                    "version_marker",
                    if profile == PROFILES[0] { 0x55 } else { 0x54 },
                )?;
                require_number(official, "work_budget", 1_000_000)?;
                require_number(official, "baseline_fixtures", 3)?;
                let registry_limits = StrictJsonParser::parse(&family.limits)?;
                let limits = field(&registry_limits, "official_chunk_limits")?;
                if field(official, "chunk_limits")? != limits {
                    return Err("P17 B03 official chunk limits 不符".into());
                }
                if field(official, "verify_limits")? != field(&registry_limits, "verify_limits")?
                    || integer(&registry_limits, "work_budget_units")?
                        != integer(official, "work_budget")?
                {
                    return Err("P17 B03 official verify/work limits 不符".into());
                }
                if !boolean(
                    value,
                    "counts_include_baseline_and_seven_explicit_negative_cases",
                )? || integer(value, "explicit_negative_rejects")? < 7
                {
                    return Err("P17 B03 official negative 缺失".into());
                }
                object(
                    value,
                    &[
                        "case_id",
                        "profile",
                        "seed",
                        "iterations",
                        "outcome",
                        "accepted",
                        "rejected",
                        "official",
                        "explicit_negative_rejects",
                        "counts_include_baseline_and_seven_explicit_negative_cases",
                    ],
                )?;
            }
        }
        "p17_platform_cli" => {
            object(
                value,
                &[
                    "case_id",
                    "profile",
                    "seed",
                    "iterations",
                    "outcome",
                    "capabilities",
                ],
            )?;
            let capabilities = field(value, "capabilities")?;
            object(
                capabilities,
                &[
                    "os_tmpname",
                    "os_tmpname_error",
                    "os_time",
                    "os_time_result_type",
                    "os_execute",
                    "os_execute_error",
                    "os_difftime",
                    "package_loadlib",
                    "package_loadlib_error",
                    "package_loadlib_when",
                ],
            )?;
            for key in ["os_tmpname", "os_execute", "package_loadlib"] {
                if string(capabilities, key)? != "denied" {
                    return Err(format!("P17 B03 {key} 未拒絕"));
                }
            }
            for key in ["os_tmpname_error", "os_execute_error"] {
                if string(capabilities, key)? != "E_HOST_POLICY_OS" {
                    return Err(format!("P17 B03 {key} 類別不符"));
                }
            }
            if string(capabilities, "os_time")? != "available"
                || string(capabilities, "os_time_result_type")? != "number"
                || string(capabilities, "os_difftime")? != "available"
                || string(capabilities, "package_loadlib_error")? != "native-grant: preflight"
                || string(capabilities, "package_loadlib_when")? != "open"
            {
                return Err("P17 B03 platform CLI capability 不符".into());
            }
        }
        "p17_platform_c" => {
            object(
                value,
                &[
                    "case_id",
                    "profile",
                    "seed",
                    "iterations",
                    "outcome",
                    "platform",
                    "compiler",
                    "sizes",
                    "capabilities",
                ],
            )?;
            if string(value, "platform")? != "aarch64-apple-darwin"
                || string(value, "compiler")?.is_empty()
            {
                return Err("P17 B03 C platform identity 不符".into());
            }
            let sizes = field(value, "sizes")?;
            object(
                sizes,
                &[
                    "int",
                    "long",
                    "long_long",
                    "pointer",
                    "float",
                    "double",
                    "long_double",
                ],
            )?;
            for key in [
                "int",
                "long",
                "long_long",
                "pointer",
                "float",
                "double",
                "long_double",
            ] {
                if integer(sizes, key)? == 0 {
                    return Err("P17 B03 C size 零值".into());
                }
            }
            let capabilities = field(value, "capabilities")?;
            object(
                capabilities,
                &[
                    "tmpnam",
                    "tmpnam_category",
                    "tmpnam_errno",
                    "tmpnam_diagnostic",
                ],
            )?;
            let outcome = string(capabilities, "tmpnam")?;
            let category = string(capabilities, "tmpnam_category")?;
            let diagnostic = string(capabilities, "tmpnam_diagnostic")?;
            if !((outcome == "available" && category == "name-returned" && diagnostic.is_empty())
                || (outcome == "unsupported"
                    && category == "C_TMPNAM_UNAVAILABLE"
                    && !diagnostic.is_empty()))
            {
                return Err("P17 B03 tmpnam probe 診斷缺失".into());
            }
            integer(capabilities, "tmpnam_errno")?;
        }
        _ => return Err("P17 B03 範圍外 case".into()),
    }
    Ok(())
}

