        || string(value, "prior_gc_review_sha256")? != DEBUG_HOOK_PRIOR_GC_REVIEW_SHA
        || string(value, "prior_producer_review_sha256")? != DEBUG_HOOK_PRIOR_PRODUCER_REVIEW_SHA
        || string(value, "gate35_report_path")? != gate.display().to_string()
        || string(value, "gate35_report_sha256")?
            != "095d3925791b821d7957174cc78c603ded6b9b337826128194bb9b61f1fa4416"
        || string(value, "proof_path")?
