fn debug_hook_live_source(current_root: &Path, evidence: &Path) -> Result<bool, String> {
    debug_hook_live_source_with_verified(current_root, evidence, None)
}

fn debug_hook_live_source_with_verified(
    current_root: &Path,
    evidence: &Path,
    verified: Option<&FinalVerifiedContext>,
) -> Result<bool, String> {
    let verified = verified.filter(|verified| verified.check(current_root, evidence).is_ok());
    let path = evidence.join(DEBUG_HOOK_REVIEW_FILE);
    if !path.exists() {
        return Ok(false);
    }
    console_cli_public_file(&path, evidence)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    debug_hook_review_shape(&value, evidence)?;
    let change = field(&value, "change")?;
    for (key, digest) in [("before_snapshot_path", DEBUG_VM_AFTER_SHA),
        ("after_snapshot_path", DEBUG_HOOK_VM_AFTER_SHA)]
    {
        let snapshot = Path::new(string(change, key)?);
        console_cli_public_file(snapshot, &evidence.join(DEBUG_HOOK_SOURCE_DIR))?;
        sha(snapshot, digest)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 debug hook 歷史來源快照非 0444".into());
        }
    }
    sha(&current_root.join(DEBUG_VM_PATH),
        final_debug_current_vm_sha_with_verified(current_root, evidence,
            DEBUG_HOOK_VM_AFTER_SHA, verified)?)?;
    sha(&current_root.join(DEBUG_HOOK_TEST_PATH), DEBUG_HOOK_TEST_SHA)?;
    Ok(true)
}

fn debug_hook_relocated_source(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    recorded: &str,
    digest: &str,
) -> Result<PathBuf, String> {
    debug_hook_relocated_source_with_verified(
        original_root, current_root, evidence, recorded, digest, None)
}

fn debug_hook_relocated_source_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    recorded: &str,
    digest: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<PathBuf, String> {
    if let Some(verified) = verified {
        verified.check(current_root, evidence)?;
    }
    if recorded == original_root.join(DEBUG_VM_PATH).display().to_string()
        && digest == DEBUG_HOOK_VM_AFTER_SHA
        && (verified.is_some()
            || final_debug_successor_tool_source(current_root, evidence)?.is_some())
    {
        let mapped = final_debug_current_vm_sha_with_verified(current_root, evidence,
            DEBUG_HOOK_VM_AFTER_SHA, verified)?;
        let expected_live = if let Some(verified) = verified {
            let pinned = verified.source_shas.get(&current_root.join(DEBUG_VM_PATH))
                .ok_or("P17 debug hook final VM context source 缺失")?;
            if pinned.as_str() != mapped {
                return Err("P17 debug hook final VM context source SHA 不符".into());
            }
            pinned.as_str()
        } else {
            mapped
        };
        return report::phase_relocated_source(original_root, current_root, recorded, expected_live);
    }
    if recorded == original_root.join(DEBUG_VM_PATH).display().to_string()
        && digest == DEBUG_VM_AFTER_SHA
        && debug_hook_live_source_with_verified(current_root, evidence, verified)?
    {
        return report::phase_relocated_source(
            original_root, current_root, recorded,
            final_debug_current_vm_sha_with_verified(current_root, evidence,
                DEBUG_HOOK_VM_AFTER_SHA, verified)?,
        );
    }
    debug_vm_relocated_source_with_verified(
        original_root, current_root, evidence, recorded, digest, verified)
}

fn debug_hook_review_source(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<DebugHookReview>, String> {
    let verified = verified.filter(|verified| verified.check(current_root, evidence).is_ok());
    let path = evidence.join(DEBUG_HOOK_REVIEW_FILE);
    if !path.exists() {
        if matches!(manifest::sha256(&current_root.join(DEBUG_VM_PATH))?.as_str(),
            DEBUG_VM_BEFORE_SHA | DEBUG_VM_AFTER_SHA)
            && !current_root.join(DEBUG_HOOK_TEST_PATH).exists()
        {
            return Ok(None);
        }
        return Err("P17 debug hook 來源已變但缺 typed review".into());
    }
    console_cli_public_file(&path, evidence)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    debug_hook_review_shape(&value, evidence)?;
    for (file, digest) in [
        (DEBUG_VM_REVIEW_FILE, DEBUG_HOOK_PRIOR_DEBUG_REVIEW_SHA),
        ("p17-phase-gc-source-impact-review-v12.json", DEBUG_HOOK_PRIOR_GC_REVIEW_SHA),
        ("p17-phase-producer-source-impact-review-v4.json", DEBUG_HOOK_PRIOR_PRODUCER_REVIEW_SHA),
    ] {
        sha(&evidence.join(file), digest)?;
    }
    let gate_path = Path::new(string(&value, "gate35_report_path")?);
    sha(gate_path, string(&value, "gate35_report_sha256")?)?;
    let gate = StrictJsonParser::parse(&fs::read_to_string(gate_path)
        .map_err(|error| error.to_string())?)?;
    let old_vm_path = original_root.join(DEBUG_VM_PATH).display().to_string();
    let new_test_path = original_root.join(DEBUG_HOOK_TEST_PATH).display().to_string();
    let checks = array(&gate, "checks")?;
    if string(&gate, "status")? != "FAIL"
        || checks.len() != 4
        || checks.iter().map(|item| string(item, "status")).collect::<Result<Vec<_>, _>>()?
            != ["FAIL", "PASS", "FAIL", "PASS"]
        || array(&gate, "source_inputs")?.iter().filter(|item| {
            string(item, "path").ok() == Some(old_vm_path.as_str())
                && string(item, "sha256").ok() == Some(DEBUG_VM_AFTER_SHA)
        }).count() != 1
        || array(&gate, "source_inputs")?.iter().any(|item| {
            string(item, "path").ok() == Some(new_test_path.as_str())
        })
        || array(&gate, "source_inputs")?.len() != 256
    {
        return Err("P17 debug hook Gate35 前態／新測試缺席不符".into());
    }
    let change = field(&value, "change")?;
    let before = Path::new(string(change, "before_snapshot_path")?);
    let after = Path::new(string(change, "after_snapshot_path")?);
    sha(&evidence.join(DEBUG_VM_SOURCE_DIR).join(format!(
        "after-{}", DEBUG_VM_PATH.replace('/', "__"))), DEBUG_VM_AFTER_SHA)?;
    for (snapshot, digest) in [(before, DEBUG_VM_AFTER_SHA),
        (after, DEBUG_HOOK_VM_AFTER_SHA)]
    {
        console_cli_public_file(snapshot, &evidence.join(DEBUG_HOOK_SOURCE_DIR))?;
        sha(snapshot, digest)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 debug hook source 快照非 0444".into());
        }
    }
    sha(&current_root.join(DEBUG_VM_PATH),
        final_debug_current_vm_sha_with_verified(current_root, evidence,
            DEBUG_HOOK_VM_AFTER_SHA, verified)?)?;
    gc_raw_diff(current_root, evidence, change, DEBUG_VM_PATH,
        before, DEBUG_VM_AFTER_SHA, after, DEBUG_HOOK_VM_AFTER_SHA)?;
    let test = field(&value, "new_test")?;
    let test_snapshot = Path::new(string(test, "snapshot_path")?);
    console_cli_public_file(test_snapshot, &evidence.join(DEBUG_HOOK_SOURCE_DIR))?;
    sha(test_snapshot, DEBUG_HOOK_TEST_SHA)?;
    if fs::metadata(test_snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 debug hook test 快照非 0444".into());
    }
    sha(&current_root.join(DEBUG_HOOK_TEST_PATH), DEBUG_HOOK_TEST_SHA)?;
    assert_warning_new_test_absent(current_root, DEBUG_HOOK_TEST_PATH)?;
    debug_hook_proof(original_root, current_root, evidence, &value, verified)?;
    Ok(Some(DebugHookReview { input: report::Input::from_path(&path)? }))
}

fn final_successor_review_shape(value: &StrictJsonValue, evidence: &Path) -> Result<(), String> {
    object(value, &["schema", "status", "prior_freeze_path", "prior_freeze_sha256",
        "prior_final_review_path", "prior_final_review_sha256", "vm_handoff_path",
        "vm_handoff_sha256", "root_integration_review_path",
        "root_integration_review_sha256", "vm_final_diff_path", "vm_final_diff_sha256",
        "changes", "review_note"])?;
    let vm_dir = evidence.join("p17-final-dump-quota-count-fix-20261013-1");
    if string(value, "schema")? != "rivetlua-p17-dump-count-successor-v1"
        || string(value, "status")? != "PASS_TYPED_SUCCESSOR"
        || string(value, "prior_freeze_path")? != evidence.join(
            "p17-exit-integrated-source-freeze-20261013-36/manifest.json"
        ).display().to_string()
        || string(value, "prior_freeze_sha256")? != FINAL_SUCCESSOR_FREEZE_SHA
        || string(value, "prior_final_review_path")? != evidence.join(
            FINAL_SOURCE_REVIEW_FILE).display().to_string()
        || string(value, "prior_final_review_sha256")? != FINAL_SUCCESSOR_TYPED_FINAL_SHA
        || string(value, "vm_handoff_path")? != vm_dir.join("final-handoff.json").display().to_string()
        || string(value, "vm_handoff_sha256")? != FINAL_SUCCESSOR_VM_HANDOFF_SHA
        || string(value, "root_integration_review_path")? != vm_dir.join(
            "root-final-integration-review.json").display().to_string()
        || string(value, "root_integration_review_sha256")? != FINAL_SUCCESSOR_ROOT_REVIEW_SHA
        || string(value, "vm_final_diff_path")? != vm_dir.join("final-scope.diff").display().to_string()
        || string(value, "vm_final_diff_sha256")? != FINAL_SUCCESSOR_VM_DIFF_SHA
        || string(value, "review_note")?.trim().is_empty()
    {
        return Err("P17 dump/count successor 主鍵不符".into());
    }
    let changes = array(value, "changes")?;
    if changes.len() != FINAL_SUCCESSOR_CHANGES.len() {
        return Err("P17 dump/count successor change 數不符".into());
    }
    for (change, (relative, before, after, before_name, after_name)) in
        changes.iter().zip(FINAL_SUCCESSOR_CHANGES)
    {
        object(change, &["path", "before_sha256", "after_sha256", "before_snapshot_path",
            "after_snapshot_path", "diff_path", "diff_sha256"])?;
        if string(change, "path")? != relative
            || string(change, "before_sha256")? != before
            || string(change, "after_sha256")? != after
            || string(change, "before_snapshot_path")? != vm_dir.join(before_name).display().to_string()
            || string(change, "after_snapshot_path")? != vm_dir.join(after_name).display().to_string()
            || string(change, "diff_path")? != evidence.join(FINAL_SUCCESSOR_DIR).join(format!(
                "diff-{}.patch", relative.replace('/', "__")
            )).display().to_string()
        {
            return Err(format!("P17 dump/count successor edge 不符：{relative}"));
        }
        exit_digest(string(change, "diff_sha256")?)?;
    }
    Ok(())
}

fn final_successor_review_source(
    current_root: &Path,
    evidence: &Path,
) -> Result<Option<report::Input>, String> {
    let path = evidence.join(FINAL_SUCCESSOR_REVIEW_FILE);
    if !path.exists() {
        if FINAL_SUCCESSOR_CHANGES.iter().all(|(relative, before, _, _, _)| {
            manifest::sha256(&current_root.join(relative)).ok().as_deref() == Some(*before)
        }) {
            return Ok(None);
        }
        return Err("P17 dump/count 來源已變但缺 typed successor".into());
    }
    console_cli_public_file(&path, &evidence.join(FINAL_SUCCESSOR_DIR))?;
    sha(&path, FINAL_SUCCESSOR_REVIEW_SHA)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    final_successor_review_shape(&value, evidence)?;
    for (key, digest) in [
        ("prior_freeze_path", FINAL_SUCCESSOR_FREEZE_SHA),
        ("prior_final_review_path", FINAL_SUCCESSOR_TYPED_FINAL_SHA),
        ("vm_handoff_path", FINAL_SUCCESSOR_VM_HANDOFF_SHA),
        ("root_integration_review_path", FINAL_SUCCESSOR_ROOT_REVIEW_SHA),
        ("vm_final_diff_path", FINAL_SUCCESSOR_VM_DIFF_SHA),
    ] {
        sha(Path::new(string(&value, key)?), digest)?;
    }
    let freeze = StrictJsonParser::parse(&fs::read_to_string(string(&value, "prior_freeze_path")?)
        .map_err(|error| error.to_string())?)?;
    let frozen = array(&freeze, "source_files")?;
    if frozen.len() != 63 {
        return Err("P17 dump/count freeze36 source 數不符".into());
    }
    let recorded_root = Path::new(string(&freeze, "repository_root")?);
    let root_review = StrictJsonParser::parse(&fs::read_to_string(
        string(&value, "root_integration_review_path")?)
        .map_err(|error| error.to_string())?)?;
    if string(&root_review, "status")?
        != "PASS root file-only integrated source/result review; phase acceptance pending"
    {
        return Err("P17 dump/count root review 未通過".into());
    }
    let reviewed_sources = array(&root_review, "sources")?;
    if reviewed_sources.len() != FINAL_SUCCESSOR_CHANGES.len() {
        return Err("P17 dump/count root review source 數不符".into());
    }
    for (change, (relative, before, after, _, _)) in
        array(&value, "changes")?.iter().zip(FINAL_SUCCESSOR_CHANGES)
    {
        let expected_path = recorded_root.join(relative).display().to_string();
        let frozen_source = frozen.iter().filter(|row| {
            string(row, "path").ok() == Some(expected_path.as_str())
        }).collect::<Vec<_>>();
        if frozen_source.len() != 1 || string(frozen_source[0], "sha256")? != before {
            return Err(format!("P17 dump/count freeze36 endpoint 不符：{relative}"));
        }
        let reviewed = reviewed_sources.iter().filter(|row| {
            string(row, "path").ok() == Some(relative)
        }).collect::<Vec<_>>();
        if reviewed.len() != 1
            || string(reviewed[0], "before_sha256")? != before
            || string(reviewed[0], "after_sha256")? != after
            || string(reviewed[0], "before_path")? != string(change, "before_snapshot_path")?
            || string(reviewed[0], "after_path")? != string(change, "after_snapshot_path")?
        {
            return Err(format!("P17 dump/count root review edge 不符：{relative}"));
        }
        for (key, digest) in [("before_snapshot_path", before), ("after_snapshot_path", after)] {
            let snapshot = Path::new(string(change, key)?);
            console_cli_public_file(snapshot, &evidence.join("p17-final-dump-quota-count-fix-20261013-1"))?;
            sha(snapshot, digest)?;
            if fs::metadata(snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444
            {
                return Err(format!("P17 dump/count snapshot 非 0444：{relative}"));
            }
        }
        let diff = Path::new(string(change, "diff_path")?);
        console_cli_public_file(diff, &evidence.join(FINAL_SUCCESSOR_DIR))?;
        sha(diff, string(change, "diff_sha256")?)?;
        // 歷史 freeze36→40 邊僅由固定快照與 root proof 驗證。
    }
    let tests = array(&root_review, "final_exact_tests")?;
    if tests.len() != 13 || tests.iter().any(|row| {
        integer(row, "matched").ok() != Some(1)
            || integer(row, "passed").ok() != Some(1)
            || integer(row, "failed").ok() != Some(0)
    }) || ![
        "p17_full_db_dump_obeys_cli_finite_quota",
        "p17_db_prefix_native_context_preserves_empty_for_count",
    ].iter().all(|required| tests.iter().any(|row| {
        string(row, "selector").ok() == Some(*required)
    })) {
        return Err("P17 dump/count final exact proof 不完整".into());
    }
    Ok(Some(report::Input::from_path(&path)?))
}

fn final_successor_sha<'a>(relative: &str, original: &'a str, successor: bool) -> &'a str {
    if successor {
        for (path, before, after, _, _) in FINAL_SUCCESSOR_CHANGES {
            if relative == path && original == before {
                return after;
            }
        }
    }
    original
}

fn final_count_successor_sha<'a>(relative: &str, original: &'a str, successor: bool) -> &'a str {
    if successor {
        for (path, before, after, _, _, _) in FINAL_COUNT_SUCCESSOR_CHANGES {
            if relative == path && original == before {
                return after;
            }
        }
    }
    original
}

fn final_current_source_sha<'a>(
    current_root: &Path,
    evidence: &Path,
    relative: &str,
    original: &'a str,
    old_successor: bool,
) -> Result<&'a str, String> {
    let old = final_successor_sha(relative, original, old_successor);
    let latest = final_count_successor_tool_source(current_root, evidence)?.is_some();
    let counted = final_count_successor_sha(relative, old, latest);
    let debug = final_debug_successor_tool_source(current_root, evidence)?.is_some();
    let prior = final_debug_successor_sha(relative, counted, debug);
    let repair = final_repair_proof_source(current_root, evidence)?;
    Ok(current_repair_sha(relative, prior, repair.is_some(),
        repair.as_ref().is_some_and(|proof| proof.core_successor_active),
        repair.as_ref().is_some_and(|proof| proof.heap_successor_active),
        repair.as_ref().is_some_and(|proof| proof.product_successor_active)))
}

fn final_current_source_sha_with_verified<'a>(
    current_root: &Path,
    evidence: &Path,
    relative: &str,
    original: &'a str,
    old_successor: bool,
    verified: Option<&'a FinalVerifiedContext>,
) -> Result<&'a str, String> {
    let Some(verified) = verified else {
        return final_current_source_sha(current_root, evidence, relative, original, old_successor);
    };
    verified.check(current_root, evidence)?;
    let old = final_successor_sha(relative, original, old_successor);
    let counted = final_count_successor_sha(relative, old, true);
    let prior = final_debug_successor_sha(relative, counted, true);
    let mapped = current_repair_sha(relative, prior, verified.repair_active,
        verified.core_successor_active, verified.heap_successor_active,
        verified.product_successor_active);
    let pinned = verified.source_shas.get(&current_root.join(relative))
        .ok_or_else(|| format!("P17 final current source 缺失：{relative}"))?;
    if pinned.as_str() != mapped {
        return Err(format!("P17 final current source SHA 不符：{relative}"));
    }
    Ok(pinned)
}

fn final_successor_recorded_relative<'a>(recorded_root: &Path, path: &'a str) -> Result<&'a Path, String> {
    let relative = Path::new(path).strip_prefix(recorded_root)
        .map_err(|_| "P17 dump/count freeze40 source 越界")?;
    if relative.as_os_str().is_empty()
        || relative.components().any(|part| !matches!(part, Component::Normal(_)))
    {
        return Err("P17 dump/count freeze40 source 越界".into());
    }
    Ok(relative)
}

fn final_successor_tool_source(current_root: &Path, evidence: &Path) -> Result<Option<String>, String> {
    if final_successor_review_source(current_root, evidence)?.is_none() {
        return Ok(None);
    }
    let path = evidence.join(FINAL_SUCCESSOR_FREEZE_FILE);
    let directory = path.parent().ok_or("P17 dump/count freeze 目錄缺失")?;
    console_cli_public_file(&path, directory)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    object(&value, &["schema", "repository_root", "parent_manifest_path",
        "parent_manifest_sha256", "changed_paths", "new_paths", "source_files"])?;
    let parent_path = evidence.join("p17-exit-integrated-source-freeze-20261013-36/manifest.json");
    let expected_changed = [PRODUCER_NATIVE_PATH, PRODUCER_SDK_TEST_PATH,
        FINAL_COUNT_TEST_PATH, GC_TOOL_PATH].into_iter().map(str::to_owned)
        .collect::<Vec<_>>();
    sha(&parent_path, FINAL_SUCCESSOR_FREEZE_SHA)?;
    let parent = StrictJsonParser::parse(&fs::read_to_string(&parent_path)
        .map_err(|error| error.to_string())?)?;
    let recorded_root = Path::new(string(&parent, "repository_root")?);
    if string(&value, "schema")? != "rivetlua-p17-integrated-source-freeze-v1"
        || string(&value, "repository_root")? != recorded_root.display().to_string()
        || string(&value, "parent_manifest_path")? != parent_path.display().to_string()
        || string(&value, "parent_manifest_sha256")? != FINAL_SUCCESSOR_FREEZE_SHA
        || strings(&value, "changed_paths")? != expected_changed
        || !array(&value, "new_paths")?.is_empty()
    {
        return Err("P17 dump/count freeze40 主鍵不符".into());
    }
    let prior_rows = array(&parent, "source_files")?;
    let rows = array(&value, "source_files")?;
    if rows.len() != 63 || prior_rows.len() != rows.len() {
        return Err("P17 dump/count freeze40 inventory 數不符".into());
    }
    let successor = StrictJsonParser::parse(&fs::read_to_string(
        evidence.join(FINAL_SUCCESSOR_REVIEW_FILE)).map_err(|error| error.to_string())?)?;
    let changes = array(&successor, "changes")?;
    let mut tool_sha = None;
    for (row, prior) in rows.iter().zip(prior_rows) {
        object(row, &["path", "sha256", "snapshot_path"])?;
        object(prior, &["path", "sha256", "snapshot_path"])?;
        let row_path = string(row, "path")?;
        let digest = string(row, "sha256")?;
        let snapshot = Path::new(string(row, "snapshot_path")?);
        if row_path != string(prior, "path")? {
            return Err("P17 dump/count freeze40 inventory 路徑不符".into());
        }
        let relative = final_successor_recorded_relative(recorded_root, row_path)?
            .to_str().ok_or("P17 dump/count freeze40 source 非 UTF-8")?;
        if relative == GC_TOOL_PATH {
            if string(prior, "sha256")? != "dd13b1183db6acf38cfa13996383edb4d42e6ad2d663cd3843f315baf8d851d7"
                || snapshot != directory.join("xtask__src__p17__b03.rs")
                || digest == string(prior, "sha256")?
            {
                return Err("P17 dump/count freeze40 tool self-edge 不符".into());
            }
            tool_sha = Some(digest.to_owned());
        } else if let Some((index, (_, before, after, _, _))) = FINAL_SUCCESSOR_CHANGES
            .iter().enumerate().find(|(_, (path, _, _, _, _))| *path == relative)
        {
            if string(prior, "sha256")? != *before || digest != *after
                || snapshot != Path::new(string(&changes[index], "after_snapshot_path")?)
            {
                return Err(format!("P17 dump/count freeze40 successor edge 不符：{relative}"));
            }
        } else if digest != string(prior, "sha256")?
            || snapshot != Path::new(string(prior, "snapshot_path")?)
        {
            return Err(format!("P17 dump/count freeze40 非範圍來源變更：{relative}"));
        }
        if relative == GC_TOOL_PATH || FINAL_SUCCESSOR_CHANGES.iter().any(|(path, _, _, _, _)| *path == relative) {
            sha(snapshot, digest)?;
            if fs::metadata(snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444
            {
                return Err(format!("P17 dump/count freeze40 snapshot 非 0444：{relative}"));
            }
            // freeze40 是歷史端點；目前來源由後繼 freeze 另行驗證。
        }
    }
    tool_sha.map(Some).ok_or_else(|| "P17 dump/count freeze40 tool 缺失".into())
}

fn final_count_successor_review_shape(value: &StrictJsonValue, evidence: &Path) -> Result<(), String> {
    object(value, &["schema", "status", "prior_freeze_path", "prior_freeze_sha256",
        "vm_handoff_path", "vm_handoff_sha256", "root_integration_review_path",
        "root_integration_review_sha256", "vm_final_diff_path", "vm_final_diff_sha256",
        "changes", "review_note"])?;
    let vm_dir = evidence.join("p17-full-db-count-assert-fix-20261013-1");
    if string(value, "schema")? != "rivetlua-p17-full-db-count-successor-v1"
        || string(value, "status")? != "PASS_TYPED_SUCCESSOR"
        || string(value, "prior_freeze_path")? != evidence.join(
            FINAL_SUCCESSOR_FREEZE_FILE).display().to_string()
        || string(value, "prior_freeze_sha256")? != FINAL_COUNT_SUCCESSOR_PARENT_FREEZE_SHA
        || string(value, "vm_handoff_path")? != vm_dir.join("final-handoff.json").display().to_string()
        || string(value, "vm_handoff_sha256")? != FINAL_COUNT_SUCCESSOR_VM_HANDOFF_SHA
        || string(value, "root_integration_review_path")? != vm_dir.join(
            "root-final-integration-review.json").display().to_string()
        || string(value, "root_integration_review_sha256")? != FINAL_COUNT_SUCCESSOR_ROOT_REVIEW_SHA
        || string(value, "vm_final_diff_path")? != vm_dir.join("final-scope.diff").display().to_string()
        || string(value, "vm_final_diff_sha256")? != FINAL_COUNT_SUCCESSOR_VM_DIFF_SHA
        || string(value, "review_note")?.trim().is_empty()
    {
        return Err("P17 full-db count successor 主鍵不符".into());
    }
    let changes = array(value, "changes")?;
    if changes.len() != FINAL_COUNT_SUCCESSOR_CHANGES.len() {
        return Err("P17 full-db count successor change 數不符".into());
    }
    for (change, (relative, before, after, before_name, after_name, diff_sha)) in
        changes.iter().zip(FINAL_COUNT_SUCCESSOR_CHANGES)
    {
        object(change, &["path", "before_sha256", "after_sha256", "before_snapshot_path",
            "after_snapshot_path", "diff_path", "diff_sha256"])?;
        if string(change, "path")? != relative
            || string(change, "before_sha256")? != before
            || string(change, "after_sha256")? != after
            || string(change, "before_snapshot_path")? != vm_dir.join(before_name).display().to_string()
            || string(change, "after_snapshot_path")? != vm_dir.join(after_name).display().to_string()
            || string(change, "diff_path")? != evidence.join(FINAL_COUNT_SUCCESSOR_DIR).join(
                format!("diff-{}.patch", relative.replace('/', "__"))).display().to_string()
            || string(change, "diff_sha256")? != diff_sha
        {
            return Err(format!("P17 full-db count successor edge 不符：{relative}"));
        }
    }
    Ok(())
}

fn final_count_successor_review_source(
    current_root: &Path,
    evidence: &Path,
) -> Result<Option<report::Input>, String> {
    let historical = final_debug_successor_review_source(current_root, evidence)?.is_some();
    final_count_successor_review_source_with_historical(current_root, evidence, historical)
}

fn final_count_successor_review_source_with_historical(
    current_root: &Path,
    evidence: &Path,
    historical: bool,
) -> Result<Option<report::Input>, String> {
    let path = evidence.join(FINAL_COUNT_SUCCESSOR_REVIEW_FILE);
    if !path.exists() {
        if FINAL_COUNT_SUCCESSOR_CHANGES.iter().all(|(relative, before, _, _, _, _)| {
            manifest::sha256(&current_root.join(relative)).ok().as_deref() == Some(*before)
        }) {
            return Ok(None);
        }
        return Err("P17 full-db count 來源已變但缺 typed successor".into());
    }
    console_cli_public_file(&path, &evidence.join(FINAL_COUNT_SUCCESSOR_DIR))?;
    sha(&path, FINAL_COUNT_SUCCESSOR_REVIEW_SHA)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    final_count_successor_review_shape(&value, evidence)?;
    if final_successor_tool_source(current_root, evidence)?.as_deref()
        != Some(FINAL_COUNT_SUCCESSOR_PRIOR_TOOL_SHA)
    {
        return Err("P17 full-db count freeze40 前態 tool 不符".into());
    }
    for (key, digest) in [
        ("prior_freeze_path", FINAL_COUNT_SUCCESSOR_PARENT_FREEZE_SHA),
        ("vm_handoff_path", FINAL_COUNT_SUCCESSOR_VM_HANDOFF_SHA),
        ("root_integration_review_path", FINAL_COUNT_SUCCESSOR_ROOT_REVIEW_SHA),
        ("vm_final_diff_path", FINAL_COUNT_SUCCESSOR_VM_DIFF_SHA),
    ] {
        sha(Path::new(string(&value, key)?), digest)?;
    }
    let freeze = StrictJsonParser::parse(&fs::read_to_string(
        string(&value, "prior_freeze_path")?).map_err(|error| error.to_string())?)?;
    let recorded_root = Path::new(string(&freeze, "repository_root")?);
    let frozen = array(&freeze, "source_files")?;
    if frozen.len() != 63 {
        return Err("P17 full-db count freeze40 source 數不符".into());
    }
    let root_review = StrictJsonParser::parse(&fs::read_to_string(
        string(&value, "root_integration_review_path")?).map_err(|error| error.to_string())?)?;
    if string(&root_review, "schema")? != "rivetlua-p17-full-db-count-root-integration-v1"
        || string(&root_review, "status")?
            != "PASS root file-only integrated source/result review; phase acceptance pending"
    {
        return Err("P17 full-db count root review 未通過".into());
    }
    let source_guard = field(&root_review, "source_guard")?;
    if string(source_guard, "prior_freeze_path")? != string(&value, "prior_freeze_path")?
        || string(source_guard, "prior_freeze_sha256")? != FINAL_COUNT_SUCCESSOR_PARENT_FREEZE_SHA
        || integer(source_guard, "source_rows")? != 63
        || integer(source_guard, "unchanged_rows")? != 61
        || strings(source_guard, "changed_paths")? != FINAL_COUNT_SUCCESSOR_CHANGES
            .iter().map(|(relative, _, _, _, _, _)| (*relative).to_owned()).collect::<Vec<_>>()
        || !array(source_guard, "unexpected_changes")?.is_empty()
    {
        return Err("P17 full-db count root source guard 不符".into());
    }
    let reviewed = array(&root_review, "sources")?;
    if reviewed.len() != FINAL_COUNT_SUCCESSOR_CHANGES.len()
        || array(&root_review, "unchanged_sources")?.len() != 1
    {
        return Err("P17 full-db count root source 數不符".into());
    }
    for (index, (relative, before, after, _, _, diff_sha)) in
        FINAL_COUNT_SUCCESSOR_CHANGES.iter().enumerate()
    {
        let change = &array(&value, "changes")?[index];
        let frozen_path = recorded_root.join(relative).display().to_string();
        let prior = frozen.iter().filter(|row| {
            string(row, "path").ok() == Some(frozen_path.as_str())
        }).collect::<Vec<_>>();
        if prior.len() != 1 || string(prior[0], "sha256")? != *before {
            return Err(format!("P17 full-db count freeze40 endpoint 不符：{relative}"));
        }
        let root_change = &reviewed[index];
        if string(root_change, "path")? != *relative
            || string(root_change, "before_sha256")? != *before
            || string(root_change, "after_sha256")? != *after
            || string(root_change, "before_path")? != string(change, "before_snapshot_path")?
            || string(root_change, "after_path")? != string(change, "after_snapshot_path")?
            || string(root_change, "mode")? != "0444"
        {
            return Err(format!("P17 full-db count root edge 不符：{relative}"));
        }
        for (key, digest) in [("before_snapshot_path", *before), ("after_snapshot_path", *after)] {
            let snapshot = Path::new(string(change, key)?);
            console_cli_public_file(snapshot, &evidence.join("p17-full-db-count-assert-fix-20261013-1"))?;
            sha(snapshot, digest)?;
            if fs::metadata(snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444
            {
                return Err(format!("P17 full-db count snapshot 非 0444：{relative}"));
            }
        }
        let diff = Path::new(string(change, "diff_path")?);
        console_cli_public_file(diff, &evidence.join(FINAL_COUNT_SUCCESSOR_DIR))?;
        sha(diff, diff_sha)?;
        if !historical || *relative != PRODUCER_NATIVE_PATH {
            sha(&current_root.join(relative), after)?;
        }
    }
    let tests = array(&root_review, "final_exact_tests")?;
    if tests.len() != 14 || tests.iter().any(|row| {
        integer(row, "matched").ok() != Some(1)
            || integer(row, "passed").ok() != Some(1)
            || integer(row, "failed").ok() != Some(0)
            || integer(row, "ignored").ok() != Some(0)
            || integer(row, "exit_code").ok() != Some(0)
    }) || !["p17_full_db_dump_obeys_cli_finite_quota",
        "p17_gettabup_env_metatable_and_error_match_native"].iter().all(|required| {
            tests.iter().any(|row| string(row, "selector").ok() == Some(*required))
        })
    {
        return Err("P17 full-db count exact proof 不完整".into());
    }
    Ok(Some(report::Input::from_path(&path)?))
}

fn final_count_successor_tool_source(
    current_root: &Path,
    evidence: &Path,
) -> Result<Option<String>, String> {
    let historical = final_debug_successor_review_source(current_root, evidence)?.is_some();
    final_count_successor_tool_source_with_historical(current_root, evidence, historical, None)
}

fn final_count_successor_historical_live_sha<'a>(
    relative: &str,
    digest: &'a str,
    historical: bool,
    repair_active: bool,
) -> Option<&'a str> {
    if historical && matches!(relative, PRODUCER_NATIVE_PATH | DEBUG_VM_PATH | GC_HEAP_PATH
        | FINAL_DEBUG_SUCCESSOR_PENDING_PATH | GC_TOOL_PATH) {
        return None;
    }
    Some(final_repair_sha(relative, digest, historical && repair_active))
}

fn final_count_product_live_sha<'a>(
    relative: &str,
    historical: &'a str,
    product_active: bool,
) -> Result<&'a str, String> {
    if !product_active {
        return Ok(historical);
    }
    if relative == DEBUG_VM_TEST_PATH {
        if historical != DEBUG_VM_TEST_SHA {
            return Err("P17 product names test freeze41 前態 SHA 不符".into());
        }
        return Ok(PRODUCT_NAMES_AFTER_SHA);
    }
    if relative != FINAL_COUNT_TEST_PATH {
        return Ok(historical);
    }
    if historical != FINAL_SUCCESSOR_COUNT_TEST_SHA {
        return Err("P17 product count test freeze41 前態 SHA 不符".into());
    }
    Ok(PRODUCT_COUNT_TEST_AFTER_SHA)
}

fn final_count_successor_tool_source_with_historical(
    current_root: &Path,
    evidence: &Path,
    historical: bool,
    repair: Option<&FinalRepairProof>,
) -> Result<Option<String>, String> {
    if final_count_successor_review_source_with_historical(
        current_root, evidence, historical)?.is_none() {
        return Ok(None);
    }
    let path = evidence.join(FINAL_COUNT_SUCCESSOR_FREEZE_FILE);
    let directory = path.parent().ok_or("P17 full-db count freeze 目錄缺失")?;
    console_cli_public_file(&path, directory)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    object(&value, &["schema", "repository_root", "parent_manifest_path",
        "parent_manifest_sha256", "changed_paths", "new_paths", "source_files"])?;
    let parent_path = evidence.join(FINAL_SUCCESSOR_FREEZE_FILE);
    sha(&parent_path, FINAL_COUNT_SUCCESSOR_PARENT_FREEZE_SHA)?;
    let parent = StrictJsonParser::parse(&fs::read_to_string(&parent_path)
        .map_err(|error| error.to_string())?)?;
    let recorded_root = Path::new(string(&parent, "repository_root")?);
    let expected_changed = [PRODUCER_NATIVE_PATH, PRODUCER_SDK_TEST_PATH, GC_TOOL_PATH]
        .into_iter().map(str::to_owned).collect::<Vec<_>>();
    if string(&value, "schema")? != "rivetlua-p17-integrated-source-freeze-v1"
        || string(&value, "repository_root")? != recorded_root.display().to_string()
        || string(&value, "parent_manifest_path")? != parent_path.display().to_string()
        || string(&value, "parent_manifest_sha256")? != FINAL_COUNT_SUCCESSOR_PARENT_FREEZE_SHA
        || strings(&value, "changed_paths")? != expected_changed
        || !array(&value, "new_paths")?.is_empty()
    {
        return Err("P17 full-db count freeze 主鍵不符".into());
    }
    let prior_rows = array(&parent, "source_files")?;
    let rows = array(&value, "source_files")?;
    if rows.len() != 63 || prior_rows.len() != rows.len() {
        return Err("P17 full-db count freeze inventory 數不符".into());
    }
    let successor = StrictJsonParser::parse(&fs::read_to_string(
        evidence.join(FINAL_COUNT_SUCCESSOR_REVIEW_FILE)).map_err(|error| error.to_string())?)?;
    let changes = array(&successor, "changes")?;
    let mut tool_sha = None;
    for (row, prior) in rows.iter().zip(prior_rows) {
        object(row, &["path", "sha256", "snapshot_path"])?;
        object(prior, &["path", "sha256", "snapshot_path"])?;
        let row_path = string(row, "path")?;
        let digest = string(row, "sha256")?;
        let snapshot = Path::new(string(row, "snapshot_path")?);
        if row_path != string(prior, "path")? {
            return Err("P17 full-db count freeze inventory 路徑不符".into());
        }
        let relative = final_successor_recorded_relative(recorded_root, row_path)?
            .to_str().ok_or("P17 full-db count source 非 UTF-8")?;
        if relative == GC_TOOL_PATH {
            if string(prior, "sha256")? != FINAL_COUNT_SUCCESSOR_PRIOR_TOOL_SHA
                || snapshot != directory.join("xtask__src__p17__b03.rs")
                || digest == string(prior, "sha256")?
            {
                return Err("P17 full-db count tool self-edge 不符".into());
            }
            tool_sha = Some(digest.to_owned());
        } else if let Some((index, (_, before, after, _, _, _))) = FINAL_COUNT_SUCCESSOR_CHANGES
            .iter().enumerate().find(|(_, (path, _, _, _, _, _))| *path == relative)
        {
            if string(prior, "sha256")? != *before || digest != *after
                || snapshot != Path::new(string(&changes[index], "after_snapshot_path")?)
            {
                return Err(format!("P17 full-db count successor edge 不符：{relative}"));
            }
        } else if digest != string(prior, "sha256")?
            || snapshot != Path::new(string(prior, "snapshot_path")?)
        {
            return Err(format!("P17 full-db count 非範圍來源變更：{relative}"));
        }
        console_cli_public_file(snapshot, evidence)?;
        sha(snapshot, digest)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err(format!("P17 full-db count snapshot 非 0444：{relative}"));
        }
        if let Some(expected_live) = final_count_successor_historical_live_sha(
            relative, digest, historical, repair.is_some()) {
            let product_active = repair.is_some_and(|proof| proof.product_successor_active);
            let current = product_successor_sha(relative, expected_live, product_active);
            sha(&current_root.join(relative), final_count_product_live_sha(
                relative, current, product_active)?)?;
        }
    }
    tool_sha.map(Some).ok_or_else(|| "P17 full-db count tool 缺失".into())
}

fn final_debug_successor_bound() -> Result<(), String> {
    if FINAL_DEBUG_SUCCESSOR_FREEZE_FILE == "PENDING"
        || [FINAL_DEBUG_SUCCESSOR_REVIEW_SHA, FINAL_DEBUG_SUCCESSOR_ROOT_REVIEW_SHA,
            FINAL_DEBUG_SUCCESSOR_NATIVE_AFTER_SHA, FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA,
            FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA, FINAL_DEBUG_SUCCESSOR_STDLIB_AFTER_SHA,
            FINAL_DEBUG_SUCCESSOR_PENDING_AFTER_SHA,
            FINAL_DEBUG_SUCCESSOR_TEST_AFTER_SHA,
            FINAL_DEBUG_SUCCESSOR_NATIVE_DIFF_SHA, FINAL_DEBUG_SUCCESSOR_VM_DIFF_SHA,
            FINAL_DEBUG_SUCCESSOR_HEAP_DIFF_SHA, FINAL_DEBUG_SUCCESSOR_STDLIB_DIFF_SHA,
            FINAL_DEBUG_SUCCESSOR_PENDING_DIFF_SHA]
            .iter().any(|digest| exit_digest(digest).is_err())
    {
        return Err("P17 final debug successor 尚未綁定最終證據".into());
    }
    Ok(())
}

fn final_debug_successor_parent_freeze(
    evidence: &Path,
) -> Result<StrictJsonValue, String> {
    let old_path = evidence.join(FINAL_COUNT_SUCCESSOR_FREEZE_FILE);
    let base_path = evidence.join(FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_FILE);
    let review_path = evidence.join(FINAL_DEBUG_SUCCESSOR_BASE_REVIEW_FILE);
    for (path, digest) in [
        (&old_path, FINAL_DEBUG_SUCCESSOR_PRE_EXTENSION_FREEZE_SHA),
        (&base_path, FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_SHA),
        (&review_path, FINAL_DEBUG_SUCCESSOR_BASE_REVIEW_SHA),
    ] {
        console_cli_public_file(path, evidence)?;
        sha(path, digest)?;
        if fs::metadata(path).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 final debug inventory 擴充證據非 0444".into());
        }
    }
    let old = StrictJsonParser::parse(&fs::read_to_string(&old_path)
        .map_err(|error| error.to_string())?)?;
    let base = StrictJsonParser::parse(&fs::read_to_string(&base_path)
        .map_err(|error| error.to_string())?)?;
    let review = StrictJsonParser::parse(&fs::read_to_string(&review_path)
        .map_err(|error| error.to_string())?)?;
    object(&base, &["schema", "repository_root", "parent_manifest_path",
        "parent_manifest_sha256", "changed_paths", "new_paths", "source_files"])?;
    object(&review, &["schema", "status", "parent_manifest_path",
        "parent_manifest_sha256", "manifest_path", "manifest_sha256",
        "prior_source_rows", "source_rows", "unchanged_prior_rows",
        "added_existing_source", "changes_to_prior_rows", "note"])?;
    let recorded_root = Path::new(string(&old, "repository_root")?);
    if string(&base, "schema")? != "rivetlua-p17-integrated-source-freeze-v1"
        || string(&base, "repository_root")? != recorded_root.display().to_string()
        || string(&base, "parent_manifest_path")? != old_path.display().to_string()
        || string(&base, "parent_manifest_sha256")?
            != FINAL_DEBUG_SUCCESSOR_PRE_EXTENSION_FREEZE_SHA
        || !array(&base, "changed_paths")?.is_empty()
        || strings(&base, "new_paths")?
            != [FINAL_DEBUG_SUCCESSOR_STDLIB_PATH.to_owned()]
        || string(&review, "schema")?
            != "rivetlua-p17-existing-source-inventory-extension-v1"
        || string(&review, "status")?
            != "PASS_FILE_ONLY_EXISTING_SOURCE_INVENTORY_EXTENSION"
        || string(&review, "parent_manifest_path")? != old_path.display().to_string()
        || string(&review, "parent_manifest_sha256")?
            != FINAL_DEBUG_SUCCESSOR_PRE_EXTENSION_FREEZE_SHA
        || string(&review, "manifest_path")? != base_path.display().to_string()
        || string(&review, "manifest_sha256")? != FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_SHA
        || integer(&review, "prior_source_rows")? != 63
        || integer(&review, "source_rows")? != 64
        || integer(&review, "unchanged_prior_rows")? != 63
        || !array(&review, "changes_to_prior_rows")?.is_empty()
        || string(&review, "note")?.trim().is_empty()
    {
        return Err("P17 final debug 64-row inventory 擴充主鍵不符".into());
    }
    let old_rows = array(&old, "source_files")?;
    let rows = array(&base, "source_files")?;
    if old_rows.len() != 63 || rows.len() != 64
        || old_rows.iter().any(|row| string(row, "path").ok()
            == Some(recorded_root.join(FINAL_DEBUG_SUCCESSOR_STDLIB_PATH)
                .display().to_string().as_str()))
    {
        return Err("P17 final debug 64-row inventory 來源數不符".into());
    }
    let added = field(&review, "added_existing_source")?;
    object(added, &["path", "sha256", "snapshot_path", "snapshot_mode",
        "existed_before_hook_fix", "absent_from_prior_inventory"])?;
    let added_path = recorded_root.join(FINAL_DEBUG_SUCCESSOR_STDLIB_PATH)
        .display().to_string();
    let added_snapshot = evidence.join(
        "p17-exit-integrated-source-freeze-20261013-41-hook-base/before-stdlib-debug.rs");
    if string(added, "path")? != added_path.as_str()
        || string(added, "sha256")? != FINAL_DEBUG_SUCCESSOR_STDLIB_BEFORE_SHA
        || string(added, "snapshot_path")? != added_snapshot.display().to_string()
        || string(added, "snapshot_mode")? != "0444"
        || !boolean(added, "existed_before_hook_fix")?
        || !boolean(added, "absent_from_prior_inventory")?
    {
        return Err("P17 final debug 既存 stdlib 來源證據不符".into());
    }
    console_cli_public_file(&added_snapshot, evidence)?;
    sha(&added_snapshot, FINAL_DEBUG_SUCCESSOR_STDLIB_BEFORE_SHA)?;
    if fs::metadata(&added_snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 final debug stdlib 前態快照非 0444".into());
    }
    let mut old_index = 0;
    let mut added_count = 0;
    let mut last_path = None::<String>;
    for row in rows {
        object(row, &["path", "sha256", "snapshot_path"])?;
        let path = string(row, "path")?;
        if last_path.as_deref().is_some_and(|last| last >= path) {
            return Err("P17 final debug inventory 路徑未排序或重複".into());
        }
        last_path = Some(path.to_owned());
        if path == added_path.as_str() {
            added_count += 1;
            if string(row, "sha256")? != FINAL_DEBUG_SUCCESSOR_STDLIB_BEFORE_SHA
                || string(row, "snapshot_path")? != added_snapshot.display().to_string()
            {
                return Err("P17 final debug stdlib inventory row 不符".into());
            }
        } else {
            let old_row = old_rows.get(old_index)
                .ok_or("P17 final debug inventory 多餘舊 row")?;
            old_index += 1;
            if canonical_json(row) != canonical_json(old_row) {
                return Err("P17 final debug 歷史63列遭改寫".into());
            }
        }
    }
    if old_index != 63 || added_count != 1 {
        return Err("P17 final debug 64-row inventory 對照不完整".into());
    }
    Ok(base)
}

fn final_debug_successor_review_shape(
    value: &StrictJsonValue,
    evidence: &Path,
) -> Result<(), String> {
    object(value, &["schema", "status", "prior_freeze_path", "prior_freeze_sha256",
        "root_integration_review_path", "root_integration_review_sha256", "changes",
        "new_test", "review_note"])?;
    if string(value, "schema")? != "rivetlua-p17-final-debug-successor-v1"
        || string(value, "status")? != "PASS_TYPED_SUCCESSOR"
        || string(value, "prior_freeze_path")? != evidence.join(
            FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_FILE).display().to_string()
        || string(value, "prior_freeze_sha256")? != FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_SHA
        || string(value, "root_integration_review_path")? != evidence.join(
            FINAL_DEBUG_SUCCESSOR_ROOT_REVIEW_FILE).display().to_string()
        || string(value, "root_integration_review_sha256")?
            != FINAL_DEBUG_SUCCESSOR_ROOT_REVIEW_SHA
        || string(value, "review_note")?.trim().is_empty()
    {
        return Err("P17 final debug successor 主鍵不符".into());
    }
    let changes = array(value, "changes")?;
    if changes.len() != FINAL_DEBUG_SUCCESSOR_CHANGES.len() {
        return Err("P17 final debug source edge 數不符".into());
    }
    for (change, (relative, before, after, diff_sha)) in
        changes.iter().zip(FINAL_DEBUG_SUCCESSOR_CHANGES)
    {
        object(change, &["path", "before_sha256", "after_sha256",
            "before_snapshot_path", "after_snapshot_path", "diff_path", "diff_sha256"])?;
        if string(change, "path")? != relative
            || string(change, "before_sha256")? != before
            || string(change, "after_sha256")? != after
            || string(change, "diff_sha256")? != diff_sha
        {
            return Err(format!("P17 final debug source edge 不符：{relative}"));
        }
    }
    let test = field(value, "new_test")?;
    object(test, &["path", "before_absent", "after_sha256", "snapshot_path"])?;
    if string(test, "path")? != FINAL_DEBUG_SUCCESSOR_TEST_PATH
        || !boolean(test, "before_absent")?
        || string(test, "after_sha256")? != FINAL_DEBUG_SUCCESSOR_TEST_AFTER_SHA
    {
        return Err("P17 final debug 新測試 edge 不符".into());
    }
    Ok(())
}

struct FinalDebugGcInputReuse {
    tested_vm_sha: String,
    tested_native_sha: Option<String>,
    tested_heap_sha: Option<String>,
}

fn final_debug_gc_input_reuse_shape(
    value: &StrictJsonValue,
    evidence: &Path,
    root_dir: &Path,
) -> Result<(), String> {
    let mut keys = vec!["status", "tested_vm_sha256", "tested_vm_snapshot_path",
        "final_vm_sha256", "diff_path", "diff_sha256", "changed_symbols",
        "reason", "unchanged_heap_sha256"];
    if value.get("native_edge").is_some() {
        keys.push("native_edge");
    }
    if value.get("heap_edge").is_some() {
        keys.push("heap_edge");
    }
    object(value, &keys)?;
    let symbols = strings(value, "changed_symbols")?;
    let names = symbols.iter().collect::<BTreeSet<_>>();
    let expected_heap = if value.get("heap_edge").is_some() {
        FINAL_DEBUG_GC_TESTED_HEAP_SHA
    } else {
        FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA
    };
    if string(value, "status")? != "PASS_FILE_ONLY_GC_INPUT_REUSE"
        || string(value, "tested_vm_sha256")? != FINAL_DEBUG_GC_TESTED_VM_SHA
        || string(value, "final_vm_sha256")? != FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA
        || string(value, "unchanged_heap_sha256")? != expected_heap
        || FINAL_DEBUG_GC_TESTED_VM_SHA == FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA
        || symbols.is_empty() || names.len() != symbols.len()
        || symbols.iter().any(|name| !name.rsplit("::").next()
            .is_some_and(|part| (part.starts_with("debug_") && part.len() > 6)
                || matches!(part, "dispatch_with_debug_hook" | "start_debug_hook_event"
                    | "start_debug_hook_event_with_followup" | "resume_basic_pending")))
        || !string(value, "reason")?.contains("GC")
        || string(value, "reason")?.trim().len() < 20
    {
        return Err("P17 final GC input reuse 主鍵／debug 範圍不符".into());
    }
    let tested = Path::new(string(value, "tested_vm_snapshot_path")?);
    let diff = Path::new(string(value, "diff_path")?);
    if !tested.is_absolute() || !tested.starts_with(evidence)
        || tested.components().any(|part| matches!(part, Component::ParentDir))
        || !diff.is_absolute() || !diff.starts_with(root_dir)
        || diff.components().any(|part| matches!(part, Component::ParentDir))
    {
        return Err("P17 final GC input reuse 快照／diff 路徑不符".into());
    }
    exit_digest(string(value, "diff_sha256")?)?;
    if let Some(native) = value.get("native_edge") {
        object(native, &["tested_native_sha256", "tested_native_snapshot_path",
            "final_native_sha256", "diff_path", "diff_sha256", "changed_symbols", "reason"])?;
        let native_symbols = strings(native, "changed_symbols")?;
        let unique_native_symbols = native_symbols.iter().collect::<BTreeSet<_>>();
        if string(native, "tested_native_sha256")? != FINAL_DEBUG_SUCCESSOR_NATIVE_BEFORE_SHA
            || string(native, "final_native_sha256")? != FINAL_DEBUG_SUCCESSOR_NATIVE_AFTER_SHA
            || unique_native_symbols.len() != native_symbols.len()
            || !native_symbols.iter().any(|name| name.as_str() == "native_prototype")
            || native_symbols.iter().any(|name| !matches!(name.as_str(),
                "native_prototype" | "stripped_native_header_lines"
                    | "tests::stripped_header_lines_preserve_span_and_charge_lookup"))
            || string(native, "reason")?.trim().len() < 20
            || !string(native, "reason")?.contains("GC")
        {
            return Err("P17 final GC native reuse 主鍵／symbol 不符".into());
        }
        for (key, scope) in [("tested_native_snapshot_path", evidence), ("diff_path", root_dir)] {
            let path = Path::new(string(native, key)?);
            if !path.is_absolute() || !path.starts_with(scope)
                || path.components().any(|part| matches!(part, Component::ParentDir))
            {
                return Err("P17 final GC native reuse 路徑不符".into());
            }
        }
        exit_digest(string(native, "diff_sha256")?)?;
    }
    if let Some(heap) = value.get("heap_edge") {
        object(heap, &["tested_heap_sha256", "tested_heap_snapshot_path",
            "final_heap_sha256", "diff_path", "diff_sha256", "changed_symbols", "reason"])?;
        let heap_symbols = strings(heap, "changed_symbols")?;
        let unique_heap_symbols = heap_symbols.iter().collect::<BTreeSet<_>>();
        if string(heap, "tested_heap_sha256")? != FINAL_DEBUG_GC_TESTED_HEAP_SHA
            || string(heap, "final_heap_sha256")? != FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA
            || FINAL_DEBUG_GC_TESTED_HEAP_SHA == FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA
            || unique_heap_symbols.len() != heap_symbols.len()
            || !heap_symbols.iter().any(|name| name.as_str() == "debug_hook_event")
            || heap_symbols.iter().any(|name| {
                name.as_str() != "debug_hook_event"
                    && !(name.starts_with("tests::") && name.contains("debug_hook"))
            })
            || string(heap, "reason")?.trim().len() < 20
            || !string(heap, "reason")?.contains("GC")
            || !string(heap, "reason")?.contains("hook")
        {
            return Err("P17 final GC heap reuse 主鍵／hook 範圍不符".into());
        }
        for (key, scope) in [("tested_heap_snapshot_path", evidence), ("diff_path", root_dir)] {
            let path = Path::new(string(heap, key)?);
            if !path.is_absolute() || !path.starts_with(scope)
                || path.components().any(|part| matches!(part, Component::ParentDir))
            {
                return Err("P17 final GC heap reuse 路徑不符".into());
            }
        }
        exit_digest(string(heap, "diff_sha256")?)?;
    }
    Ok(())
}

fn final_debug_gc_input_reuse(
    current_root: &Path,
    evidence: &Path,
    root_dir: &Path,
    verification: &StrictJsonValue,
    changes: &[StrictJsonValue],
) -> Result<Option<FinalDebugGcInputReuse>, String> {
    let repair = final_repair_proof_source(current_root, evidence)?;
    final_debug_gc_input_reuse_with_repair(
        current_root, evidence, root_dir, verification, changes, repair.is_some(),
        repair.as_ref().is_some_and(|proof| proof.core_successor_active),
        repair.as_ref().is_some_and(|proof| proof.heap_successor_active),
        repair.as_ref().is_some_and(|proof| proof.product_successor_active))
}

fn final_debug_gc_input_reuse_with_repair(
    current_root: &Path,
    evidence: &Path,
    root_dir: &Path,
    verification: &StrictJsonValue,
    changes: &[StrictJsonValue],
    repaired: bool,
    core_active: bool,
    heap_active: bool,
    product_active: bool,
) -> Result<Option<FinalDebugGcInputReuse>, String> {
    let Some(value) = verification.get("gc_input_reuse") else {
        return Ok(None);
    };
    final_debug_gc_input_reuse_shape(value, evidence, root_dir)?;
    let tested = Path::new(string(value, "tested_vm_snapshot_path")?);
    console_cli_public_file(tested, evidence)?;
    sha(tested, FINAL_DEBUG_GC_TESTED_VM_SHA)?;
    if fs::metadata(tested).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 final GC tested VM 快照非 0444".into());
    }
    let vm_change = changes.iter().find(|change| {
        string(change, "path").ok() == Some(DEBUG_VM_PATH)
    }).ok_or("P17 final GC reuse 缺 VM typed edge")?;
    let final_snapshot = Path::new(string(vm_change, "after_snapshot_path")?);
    console_cli_public_file(final_snapshot, root_dir)?;
    sha(final_snapshot, FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA)?;
    if fs::metadata(final_snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 final GC final VM 快照非 0444".into());
    }
    let diff = Path::new(string(value, "diff_path")?);
    console_cli_public_file(diff, root_dir)?;
    sha(diff, string(value, "diff_sha256")?)?;
    if fs::metadata(diff).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 final GC VM raw diff 非 0444".into());
    }
    let output = verified_review_git(current_root)?
        .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
        .arg(tested).arg(final_snapshot).output().map_err(|error| error.to_string())?;
    if output.status.code() != Some(1) || !output.stderr.is_empty()
        || output.stdout != fs::read(diff).map_err(|error| error.to_string())?
    {
        return Err("P17 final GC tested→final VM raw diff 不符".into());
    }
    let mut tested_native_sha = None;
    if let Some(native) = value.get("native_edge") {
        let tested_native = Path::new(string(native, "tested_native_snapshot_path")?);
        console_cli_public_file(tested_native, evidence)?;
        sha(tested_native, FINAL_DEBUG_SUCCESSOR_NATIVE_BEFORE_SHA)?;
        if fs::metadata(tested_native).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 final GC tested native 快照非 0444".into());
        }
        let native_change = changes.iter().find(|change| {
            string(change, "path").ok() == Some(PRODUCER_NATIVE_PATH)
        }).ok_or("P17 final GC reuse 缺 native typed edge")?;
        let final_native = Path::new(string(native_change, "after_snapshot_path")?);
        console_cli_public_file(final_native, root_dir)?;
        sha(final_native, FINAL_DEBUG_SUCCESSOR_NATIVE_AFTER_SHA)?;
        if fs::metadata(final_native).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 final GC final native 快照非 0444".into());
        }
        let native_diff = Path::new(string(native, "diff_path")?);
        console_cli_public_file(native_diff, root_dir)?;
        sha(native_diff, string(native, "diff_sha256")?)?;
        if fs::metadata(native_diff).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 final GC native raw diff 非 0444".into());
        }
        let native_output = verified_review_git(current_root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(tested_native).arg(final_native).output().map_err(|error| error.to_string())?;
        if native_output.status.code() != Some(1) || !native_output.stderr.is_empty()
            || native_output.stdout != fs::read(native_diff).map_err(|error| error.to_string())?
        {
            return Err("P17 final GC tested→final native raw diff 不符".into());
        }
        sha(&current_root.join(PRODUCER_NATIVE_PATH), product_successor_sha(
            PRODUCER_NATIVE_PATH, core_successor_sha(PRODUCER_NATIVE_PATH,
                final_repair_sha(PRODUCER_NATIVE_PATH,
                    FINAL_DEBUG_SUCCESSOR_NATIVE_AFTER_SHA, repaired), core_active),
            product_active))?;
        tested_native_sha = Some(FINAL_DEBUG_SUCCESSOR_NATIVE_BEFORE_SHA.into());
    }
    let mut tested_heap_sha = None;
    if let Some(heap) = value.get("heap_edge") {
        let tested_heap = Path::new(string(heap, "tested_heap_snapshot_path")?);
        console_cli_public_file(tested_heap, evidence)?;
        sha(tested_heap, FINAL_DEBUG_GC_TESTED_HEAP_SHA)?;
        if fs::metadata(tested_heap).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 final GC tested heap 快照非 0444".into());
        }
        let heap_change = changes.iter().find(|change| {
            string(change, "path").ok() == Some(GC_HEAP_PATH)
        }).ok_or("P17 final GC reuse 缺 heap typed edge")?;
        let final_heap = Path::new(string(heap_change, "after_snapshot_path")?);
        console_cli_public_file(final_heap, root_dir)?;
        sha(final_heap, FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA)?;
        if fs::metadata(final_heap).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 final GC final heap 快照非 0444".into());
        }
        let heap_diff = Path::new(string(heap, "diff_path")?);
        console_cli_public_file(heap_diff, root_dir)?;
        sha(heap_diff, string(heap, "diff_sha256")?)?;
        if fs::metadata(heap_diff).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 final GC heap raw diff 非 0444".into());
        }
        let heap_output = verified_review_git(current_root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(tested_heap).arg(final_heap).output().map_err(|error| error.to_string())?;
        if heap_output.status.code() != Some(1) || !heap_output.stderr.is_empty()
            || heap_output.stdout != fs::read(heap_diff).map_err(|error| error.to_string())?
        {
            return Err("P17 final GC tested→final heap raw diff 不符".into());
        }
        sha(&current_root.join(GC_HEAP_PATH), current_repair_sha(
            GC_HEAP_PATH, FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA,
            repaired, core_active, heap_active, product_active))?;
        tested_heap_sha = Some(FINAL_DEBUG_GC_TESTED_HEAP_SHA.into());
    }
    sha(&current_root.join(DEBUG_VM_PATH), product_successor_sha(DEBUG_VM_PATH,
        final_repair_sha(DEBUG_VM_PATH, FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA, repaired),
        product_active))?;
    sha(&current_root.join(GC_HEAP_PATH), current_repair_sha(
        GC_HEAP_PATH, FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA,
        repaired, core_active, heap_active, product_active))?;
    if heap_active {
        sha(&current_root.join(GC_MOD_PATH), GC_MOD_AFTER_SHA)?;
    }
    Ok(Some(FinalDebugGcInputReuse {
        tested_vm_sha: FINAL_DEBUG_GC_TESTED_VM_SHA.into(),
        tested_native_sha,
        tested_heap_sha,
    }))
}

fn final_debug_verified_source_input(
    recorded_root: &Path,
    current_root: &Path,
    input: &StrictJsonValue,
    kind: &str,
    gc_reuse: Option<&FinalDebugGcInputReuse>,
) -> Result<PathBuf, String> {
    final_debug_verified_source_input_with_repair(
        recorded_root, current_root, input, kind, gc_reuse, false, false, false, false)
}

fn final_debug_verified_source_input_with_repair(
    recorded_root: &Path,
    current_root: &Path,
    input: &StrictJsonValue,
    kind: &str,
    gc_reuse: Option<&FinalDebugGcInputReuse>,
    repaired: bool,
    core_active: bool,
    heap_active: bool,
    product_active: bool,
) -> Result<PathBuf, String> {
    object(input, &["path", "sha256"])?;
    let recorded = string(input, "path")?;
    let digest = string(input, "sha256")?;
    exit_digest(digest)?;
    let relative = final_successor_recorded_relative(recorded_root, recorded)?;
    if kind != "debug" && relative == Path::new(DEBUG_VM_PATH)
        && gc_reuse.is_some_and(|reuse| digest == reuse.tested_vm_sha.as_str())
    {
        sha(&current_root.join(DEBUG_VM_PATH), product_successor_sha(DEBUG_VM_PATH,
            final_repair_sha(DEBUG_VM_PATH, FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA, repaired),
            product_active))?;
        return Ok(relative.to_path_buf());
    }
    if kind != "debug" && relative == Path::new(PRODUCER_NATIVE_PATH)
        && gc_reuse.is_some_and(|reuse| reuse.tested_native_sha.as_deref() == Some(digest))
    {
        sha(&current_root.join(PRODUCER_NATIVE_PATH), product_successor_sha(
            PRODUCER_NATIVE_PATH, core_successor_sha(PRODUCER_NATIVE_PATH,
                final_repair_sha(PRODUCER_NATIVE_PATH,
                    FINAL_DEBUG_SUCCESSOR_NATIVE_AFTER_SHA, repaired), core_active),
            product_active))?;
        return Ok(relative.to_path_buf());
    }
    if kind != "debug" && relative == Path::new(GC_HEAP_PATH)
        && gc_reuse.is_some_and(|reuse| reuse.tested_heap_sha.as_deref() == Some(digest))
    {
        sha(&current_root.join(GC_HEAP_PATH), current_repair_sha(
            GC_HEAP_PATH, FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA,
            repaired, core_active, heap_active, product_active))?;
        return Ok(relative.to_path_buf());
    }
    if repaired {
        for (path, before, after) in FINAL_REPAIR_PRODUCT_CHANGES {
            if relative == Path::new(path) && digest == before {
                sha(&current_root.join(path),
                    product_successor_sha(path, heap_successor_sha(path,
                        core_successor_sha(path, after, core_active), heap_active), product_active))?;
                return Ok(relative.to_path_buf());
            }
        }
    }
    let mapped = report::phase_relocated_source(
        recorded_root, current_root, recorded, digest)?;
    if mapped != relative {
        return Err("P17 final debug clean source 映射不符".into());
    }
    Ok(mapped)
}

fn final_debug_successor_review_source(
    current_root: &Path,
    evidence: &Path,
) -> Result<Option<report::Input>, String> {
    let repair = final_repair_proof_source(current_root, evidence)?;
    final_debug_successor_review_source_with_repair(current_root, evidence, repair.is_some(),
        repair.as_ref().is_some_and(|proof| proof.core_successor_active),
        repair.as_ref().is_some_and(|proof| proof.heap_successor_active),
        repair.as_ref().is_some_and(|proof| proof.product_successor_active))
}

fn final_debug_successor_review_source_with_repair(
    current_root: &Path,
    evidence: &Path,
    repaired: bool,
    core_active: bool,
    heap_active: bool,
    product_active: bool,
) -> Result<Option<report::Input>, String> {
    let path = evidence.join(FINAL_DEBUG_SUCCESSOR_REVIEW_FILE);
    if !path.exists() {
        if manifest::sha256(&current_root.join(DEBUG_VM_PATH))? == DEBUG_HOOK_VM_AFTER_SHA
            && manifest::sha256(&current_root.join(GC_HEAP_PATH))? == DEBUG_HOOK_HEAP_SHA
            && manifest::sha256(&current_root.join(PRODUCER_NATIVE_PATH))?
                == FINAL_DEBUG_SUCCESSOR_NATIVE_BEFORE_SHA
            && manifest::sha256(&current_root.join(FINAL_DEBUG_SUCCESSOR_STDLIB_PATH))?
                == FINAL_DEBUG_SUCCESSOR_STDLIB_BEFORE_SHA
            && manifest::sha256(&current_root.join(FINAL_DEBUG_SUCCESSOR_PENDING_PATH))?
                == FINAL_DEBUG_SUCCESSOR_PENDING_BEFORE_SHA
            && !current_root.join(FINAL_DEBUG_SUCCESSOR_TEST_PATH).exists()
            && manifest::sha256(&current_root.join(GC_TOOL_PATH))?
                == FINAL_DEBUG_SUCCESSOR_PRIOR_TOOL_SHA
        {
            return Ok(None);
        }
        return Err("P17 final debug 來源已變但缺 typed successor".into());
    }
    final_debug_successor_bound()?;
    console_cli_public_file(&path, &evidence.join(FINAL_DEBUG_SUCCESSOR_DIR))?;
    sha(&path, FINAL_DEBUG_SUCCESSOR_REVIEW_SHA)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    final_debug_successor_review_shape(&value, evidence)?;
    final_count_successor_review_source_with_historical(current_root, evidence, true)?
        .ok_or("P17 final debug 缺 freeze40→41 typed proof")?;
    let parent_path = evidence.join(FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_FILE);
    let parent = final_debug_successor_parent_freeze(evidence)?;
    let recorded_root = Path::new(string(&parent, "repository_root")?);
    let prior_rows = array(&parent, "source_files")?;
    if prior_rows.len() != 64 || FINAL_DEBUG_SUCCESSOR_CHANGES.iter().any(|(relative, before, _, _)| {
        prior_rows.iter().filter(|row| {
            string(row, "path").ok() == Some(recorded_root.join(relative)
                .display().to_string().as_str())
                && string(row, "sha256").ok() == Some(*before)
        }).count() != 1
    }) || prior_rows.iter().any(|row| {
        string(row, "path").ok() == Some(recorded_root.join(FINAL_DEBUG_SUCCESSOR_TEST_PATH)
            .display().to_string().as_str())
    }) {
        return Err("P17 final debug hook-base source／新測試前態不符".into());
    }
    let tool_prior = prior_rows.iter().find(|row| {
        string(row, "path").ok() == Some(recorded_root.join(GC_TOOL_PATH)
            .display().to_string().as_str())
    }).ok_or("P17 final debug freeze41 B03 缺失")?;
    if string(tool_prior, "sha256")? != FINAL_DEBUG_SUCCESSOR_PRIOR_TOOL_SHA
        || prior_rows.iter().filter(|row| {
            string(row, "path").ok() == Some(recorded_root.join(GC_TOOL_PATH)
                .display().to_string().as_str())
        }).count() != 1
    {
        return Err("P17 final debug freeze41 B03 endpoint 不符".into());
    }
    let root_dir = evidence.join(FINAL_DEBUG_SUCCESSOR_ROOT_DIR);
    let changes = array(&value, "changes")?;
    for (change, (relative, before_sha, after_sha, diff_sha)) in
        changes.iter().zip(FINAL_DEBUG_SUCCESSOR_CHANGES)
    {
        let prior = prior_rows.iter().find(|row| {
            string(row, "path").ok() == Some(recorded_root.join(relative)
                .display().to_string().as_str())
        }).ok_or_else(|| format!("P17 final debug freeze41 前態缺失：{relative}"))?;
        let before = Path::new(string(change, "before_snapshot_path")?);
        let after = Path::new(string(change, "after_snapshot_path")?);
        let diff = Path::new(string(change, "diff_path")?);
        if before != Path::new(string(prior, "snapshot_path")?) {
            return Err(format!("P17 final debug before snapshot 不符：{relative}"));
        }
        for (snapshot, digest, directory) in [
            (before, before_sha, evidence),
            (after, after_sha, root_dir.as_path()),
        ] {
            console_cli_public_file(snapshot, directory)?;
            sha(snapshot, digest)?;
            if fs::metadata(snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444
            {
                return Err(format!("P17 final debug snapshot 非 0444：{relative}"));
            }
        }
        console_cli_public_file(diff, &root_dir)?;
        sha(diff, diff_sha)?;
        gc_raw_diff(current_root, evidence, change, relative,
            before, before_sha, after, after_sha)?;
    }
    let test = field(&value, "new_test")?;
    let test_snapshot = Path::new(string(test, "snapshot_path")?);
    console_cli_public_file(test_snapshot, &root_dir)?;
    sha(test_snapshot, FINAL_DEBUG_SUCCESSOR_TEST_AFTER_SHA)?;
    if fs::metadata(test_snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 final debug 新測試 snapshot 非 0444".into());
    }
    let root_review_path = Path::new(string(&value, "root_integration_review_path")?);
    console_cli_public_file(root_review_path, &root_dir)?;
    sha(root_review_path, FINAL_DEBUG_SUCCESSOR_ROOT_REVIEW_SHA)?;
    let root_review = StrictJsonParser::parse(&fs::read_to_string(root_review_path)
        .map_err(|error| error.to_string())?)?;
    if string(&root_review, "schema")? != "rivetlua-p17-final-debug-root-integration-v1"
        || string(&root_review, "status")?
            != "PASS_FILE_ONLY_FINAL_CORE_DEBUG_GC_INTEGRATION"
    {
        return Err("P17 final debug root review 未通過".into());
    }
    let guard = field(&root_review, "source_guard")?;
    if string(guard, "prior_freeze_path")? != parent_path.display().to_string()
        || string(guard, "prior_freeze_sha256")? != FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_SHA
        || integer(guard, "prior_source_rows")? != 64
        || strings(guard, "changed_paths")?
            != [PRODUCER_NATIVE_PATH.to_owned(), GC_HEAP_PATH.to_owned(),
                FINAL_DEBUG_SUCCESSOR_PENDING_PATH.to_owned(),
                FINAL_DEBUG_SUCCESSOR_STDLIB_PATH.to_owned(), DEBUG_VM_PATH.to_owned()]
        || strings(guard, "new_paths")? != [FINAL_DEBUG_SUCCESSOR_TEST_PATH.to_owned()]
        || integer(guard, "unchanged_prior_rows")? != 59
        || !array(guard, "unexpected_changes")?.is_empty()
        || string(guard, "b03_still_parent_sha256")? != FINAL_DEBUG_SUCCESSOR_PRIOR_TOOL_SHA
    {
        return Err("P17 final debug root source guard 不符".into());
    }
    let fixed = field(guard, "fixed_unchanged_sha256")?;
    for (relative, digest) in [
        (PRODUCER_SDK_TEST_PATH, "7659c01d242e84d9037bbb873a65a2bedcf608f86a42be8c72f78928ce0fd134"),
        (FINAL_COUNT_TEST_PATH, FINAL_SUCCESSOR_COUNT_TEST_SHA),
    ] {
        if string(fixed, relative)? != digest {
            return Err(format!("P17 final debug 固定來源 SHA 不符：{relative}"));
        }
        let current = if product_active && relative == FINAL_COUNT_TEST_PATH {
            PRODUCT_COUNT_TEST_AFTER_SHA
        } else { digest };
        sha(&current_root.join(relative), current)?;
    }
    let reviewed = array(&root_review, "sources")?;
    if reviewed.len() != FINAL_DEBUG_SUCCESSOR_CHANGES.len() {
        return Err("P17 final debug root source edge 數不符".into());
    }
    for ((root_change, change), (relative, before_sha, after_sha, _)) in
        reviewed.iter().zip(changes).zip(FINAL_DEBUG_SUCCESSOR_CHANGES)
    {
        if string(root_change, "path")? != relative
            || string(root_change, "before_sha256")? != before_sha
            || string(root_change, "after_sha256")? != after_sha
            || string(root_change, "before_snapshot_path")?
                != string(change, "before_snapshot_path")?
            || string(root_change, "after_snapshot_path")?
                != string(change, "after_snapshot_path")?
            || string(root_change, "snapshot_mode")? != "0444"
        {
            return Err(format!("P17 final debug root source edge 不符：{relative}"));
        }
    }
    let root_new = field(&root_review, "new_test")?;
    if string(root_new, "path")? != FINAL_DEBUG_SUCCESSOR_TEST_PATH
        || !boolean(root_new, "before_absent")?
        || !boolean(root_new, "parent_inventory_absent")?
        || string(root_new, "after_sha256")? != FINAL_DEBUG_SUCCESSOR_TEST_AFTER_SHA
        || string(root_new, "after_snapshot_path")? != test_snapshot.display().to_string()
        || string(root_new, "snapshot_mode")? != "0444"
    {
        return Err("P17 final debug root 新測試不符".into());
    }
    let root_diffs = array(&root_review, "diffs")?;
    if root_diffs.len() != FINAL_DEBUG_SUCCESSOR_CHANGES.len() {
        return Err("P17 final debug root raw diff 數不符".into());
    }
    for ((root_diff, change), (relative, _, _, diff_sha)) in
        root_diffs.iter().zip(changes).zip(FINAL_DEBUG_SUCCESSOR_CHANGES)
    {
        if string(root_diff, "source_path")? != relative
            || string(root_diff, "path")? != string(change, "diff_path")?
            || string(root_diff, "sha256")? != diff_sha
        {
            return Err(format!("P17 final debug root raw diff 不符：{relative}"));
        }
    }
    let verification = field(&root_review, "verification")?;
    let gc_reuse = final_debug_gc_input_reuse_with_repair(
        current_root, evidence, &root_dir, verification, changes, repaired, core_active,
        heap_active, product_active)?;
    let tests = array(verification, "exact_tests")?;
    let gc_regressions = array(verification, "gc_regressions")?;
    if tests.is_empty() || gc_regressions.is_empty() {
        return Err("P17 final debug／GC 最終驗證缺失".into());
    }
    let mut debug_seen = false;
    let mut gc_kinds = BTreeSet::new();
    let mut gc_reuse_used = false;
    let mut native_reuse_used = false;
    let mut heap_reuse_used = false;
    for (group, rows) in [("debug", tests), ("gc", gc_regressions)] {
        for row in rows {
            object(row, &["kind", "profile", "features", "selector", "test_names",
                "command", "source_inputs", "matched", "passed",
                "failed", "ignored", "exit_code", "log_path", "log_sha256",
                "binary_path", "binary_sha256"])?;
            let kind = string(row, "kind")?;
            let selector = string(row, "selector")?;
            let command = strings(row, "command")?;
            let names = strings(row, "test_names")?;
            if !matches!((group, kind), ("debug", "debug")
                | ("gc", "private") | ("gc", "public"))
                || string(row, "profile")?.trim().is_empty()
                || string(row, "features")?.trim().is_empty()
                || selector.trim().is_empty() || command.is_empty()
                || names.is_empty() || integer(row, "matched")? != names.len() as u64
                || integer(row, "matched")? < 1
                || integer(row, "matched")? != integer(row, "passed")?
                || integer(row, "failed")? != 0
                || integer(row, "ignored")? != 0
                || integer(row, "exit_code")? != 0
            {
                return Err(format!("P17 final {kind} 回歸結果不符：{selector}"));
            }
            if kind == "debug" {
                debug_seen |= selector.starts_with("p17_debug_traceback")
                    && names.iter().any(|name| name.contains("traceback"))
                    && names.iter().any(|name| name.contains("getinfo"));
            } else {
                gc_kinds.insert(kind);
            }
            let inputs = array(row, "source_inputs")?;
            let recorded_vm = recorded_root.join(DEBUG_VM_PATH).display().to_string();
            let recorded_native = recorded_root.join(PRODUCER_NATIVE_PATH).display().to_string();
            let recorded_heap = recorded_root.join(GC_HEAP_PATH).display().to_string();
            let uses_gc_reuse = kind != "debug" && gc_reuse.as_ref().is_some_and(|reuse| {
                inputs.iter().any(|input| {
                    string(input, "path").ok() == Some(recorded_vm.as_str())
                        && string(input, "sha256").ok() == Some(reuse.tested_vm_sha.as_str())
                })
            });
            gc_reuse_used |= uses_gc_reuse;
            let uses_native_reuse = kind != "debug" && gc_reuse.as_ref().is_some_and(|reuse| {
                inputs.iter().any(|input| {
                    string(input, "path").ok() == Some(recorded_native.as_str())
                        && reuse.tested_native_sha.as_deref() == string(input, "sha256").ok()
                })
            });
            native_reuse_used |= uses_native_reuse;
            let uses_heap_reuse = kind != "debug" && gc_reuse.as_ref().is_some_and(|reuse| {
                inputs.iter().any(|input| {
                    string(input, "path").ok() == Some(recorded_heap.as_str())
                        && reuse.tested_heap_sha.as_deref() == string(input, "sha256").ok()
                })
            });
            heap_reuse_used |= uses_heap_reuse;
            let vm_sha = if uses_gc_reuse { FINAL_DEBUG_GC_TESTED_VM_SHA }
                else { FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA };
            let heap_sha = if uses_heap_reuse { FINAL_DEBUG_GC_TESTED_HEAP_SHA }
                else { FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA };
            let expected = match kind {
                "debug" => vec![
                    (DEBUG_VM_PATH, FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA),
                    (GC_HEAP_PATH, FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA),
                    (FINAL_DEBUG_SUCCESSOR_PENDING_PATH, FINAL_DEBUG_SUCCESSOR_PENDING_AFTER_SHA),
                    (FINAL_DEBUG_SUCCESSOR_STDLIB_PATH, FINAL_DEBUG_SUCCESSOR_STDLIB_AFTER_SHA),
                    (FINAL_DEBUG_SUCCESSOR_TEST_PATH, FINAL_DEBUG_SUCCESSOR_TEST_AFTER_SHA),
                ],
                "private" => vec![
                    (DEBUG_VM_PATH, vm_sha),
                    (GC_HEAP_PATH, heap_sha),
                ],
                "public" => vec![
                    (DEBUG_VM_PATH, vm_sha),
                    (GC_HEAP_PATH, heap_sha),
                    (GC_TEST_PATH, GC_TEST_SHA),
                ],
                _ => unreachable!(),
            };
            if inputs.len() < expected.len() {
                return Err(format!("P17 final {kind} 回歸來源數不符：{selector}"));
            }
            let mut seen_inputs = BTreeSet::new();
            for input in inputs {
                let path = Path::new(string(input, "path")?);
                final_debug_verified_source_input_with_repair(
                    recorded_root, current_root, input, kind, gc_reuse.as_ref(),
                    repaired, core_active, heap_active, product_active)?;
                if !seen_inputs.insert(path.to_path_buf()) {
                    return Err(format!("P17 final {kind} 回歸 source 重複：{selector}"));
                }
            }
            for (relative, digest) in expected {
                let path = recorded_root.join(relative);
                if inputs.iter().filter(|input| {
                    string(input, "path").ok() == Some(path.display().to_string().as_str())
                        && string(input, "sha256").ok() == Some(digest)
                }).count() != 1 {
                    return Err(format!("P17 final {kind} 必要 source 不符：{selector}／{relative}"));
                }
            }
            for (path_key, sha_key) in [
                ("log_path", "log_sha256"), ("binary_path", "binary_sha256")]
            {
                let artifact = Path::new(string(row, path_key)?);
                let digest = string(row, sha_key)?;
                exit_digest(digest)?;
                console_cli_public_file(artifact, evidence)?;
                sha(artifact, digest)?;
            }
            let log = fs::read_to_string(string(row, "log_path")?)
                .map_err(|error| error.to_string())?;
            let names = names.iter().map(String::as_str).collect::<Vec<_>>();
            let (counts, named) = parse_named_log_with_filter(&log, &names, true)?;
            if u64::from(counts.matched) != integer(row, "matched")?
                || u64::from(counts.passed) != integer(row, "passed")?
                || counts.failed != 0 || counts.ignored != 0
                || named.values().any(|result| *result != "ok")
            {
                return Err(format!("P17 final {kind} raw log 與具名結果不符：{selector}"));
            }
        }
    }
    if !debug_seen || gc_kinds != BTreeSet::from(["private", "public"]) {
        return Err("P17 final debug／GC 回歸種類不完整".into());
    }
    if gc_reuse.is_some() && !gc_reuse_used {
        return Err("P17 final GC input reuse 無實際受測舊 VM row".into());
    }
    if gc_reuse.as_ref().is_some_and(|reuse| reuse.tested_native_sha.is_some())
        && !native_reuse_used
    {
        return Err("P17 final GC native reuse 無實際受測舊 native row".into());
    }
    if gc_reuse.as_ref().is_some_and(|reuse| reuse.tested_heap_sha.is_some())
        && !heap_reuse_used
    {
        return Err("P17 final GC heap reuse 無實際受測舊 heap row".into());
    }
    let original_db = field(&root_review, "original_db_direct")?;
    object(original_db, &["runs"])?;
    let direct_runs = array(original_db, "runs")?;
    if direct_runs.len() != 2 {
        return Err("P17 final debug 原始 db.lua 雙 profile 紀錄缺失".into());
    }
    for (run, profile) in direct_runs.iter().zip(["lua55-i64f64", "lua54-i64f64"]) {
        object(run, &["profile", "command", "exit_code", "log_path", "log_sha256"])?;
        let command = strings(run, "command")?;
        if string(run, "profile")? != profile
            || command.is_empty() || command.iter().any(|arg| arg.trim().is_empty())
            || integer(run, "exit_code")? != 0
        {
            return Err(format!("P17 final debug 原始 db.lua direct 結果不符：{profile}"));
        }
        let log = Path::new(string(run, "log_path")?);
        let digest = string(run, "log_sha256")?;
        exit_digest(digest)?;
        console_cli_public_file(log, evidence)?;
        sha(log, digest)?;
    }
    if !string(&root_review, "acceptance_limits")?.contains("P17 phase acceptance pending") {
        return Err("P17 final debug phase acceptance 限制缺失".into());
    }
    sha(&current_root.join(DEBUG_VM_PATH), if repaired {
        product_successor_sha(DEBUG_VM_PATH,
            final_repair_sha(DEBUG_VM_PATH, FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA, true),
            product_active)
    } else { FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA })?;
    sha(&current_root.join(GC_HEAP_PATH), if repaired {
        current_repair_sha(GC_HEAP_PATH, FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA,
            true, core_active, heap_active, product_active)
    } else { FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA })?;
    sha(&current_root.join(FINAL_DEBUG_SUCCESSOR_PENDING_PATH),
        FINAL_DEBUG_SUCCESSOR_PENDING_AFTER_SHA)?;
    sha(&current_root.join(PRODUCER_NATIVE_PATH), if repaired {
        product_successor_sha(PRODUCER_NATIVE_PATH, core_successor_sha(PRODUCER_NATIVE_PATH,
            final_repair_sha(PRODUCER_NATIVE_PATH,
                FINAL_DEBUG_SUCCESSOR_NATIVE_AFTER_SHA, true), core_active), product_active)
    } else { FINAL_DEBUG_SUCCESSOR_NATIVE_AFTER_SHA })?;
    sha(&current_root.join(FINAL_DEBUG_SUCCESSOR_STDLIB_PATH),
        FINAL_DEBUG_SUCCESSOR_STDLIB_AFTER_SHA)?;
    sha(&current_root.join(FINAL_DEBUG_SUCCESSOR_TEST_PATH),
        FINAL_DEBUG_SUCCESSOR_TEST_AFTER_SHA)?;
    Ok(Some(report::Input::from_path(&path)?))
}

fn final_debug_successor_freeze_shape(
    value: &StrictJsonValue,
    parent: &StrictJsonValue,
    evidence: &Path,
) -> Result<(), String> {
    object(&value, &["schema", "repository_root", "parent_manifest_path",
        "parent_manifest_sha256", "changed_paths", "new_paths", "source_files"])?;
    let parent_path = evidence.join(FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_FILE);
    let recorded_root = Path::new(string(&parent, "repository_root")?);
    if string(&value, "schema")? != "rivetlua-p17-integrated-source-freeze-v1"
        || string(&value, "repository_root")? != recorded_root.display().to_string()
        || string(&value, "parent_manifest_path")? != parent_path.display().to_string()
        || string(&value, "parent_manifest_sha256")? != FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_SHA
        || strings(&value, "changed_paths")?
            != [PRODUCER_NATIVE_PATH.to_owned(), GC_HEAP_PATH.to_owned(),
                FINAL_DEBUG_SUCCESSOR_PENDING_PATH.to_owned(),
                FINAL_DEBUG_SUCCESSOR_STDLIB_PATH.to_owned(),
                DEBUG_VM_PATH.to_owned(), GC_TOOL_PATH.to_owned()]
        || strings(&value, "new_paths")? != [FINAL_DEBUG_SUCCESSOR_TEST_PATH.to_owned()]
    {
        return Err("P17 final debug freeze 主鍵不符".into());
    }
    if array(&value, "source_files")?.len() != 65 {
        return Err("P17 final debug freeze inventory 數不符".into());
    }
    Ok(())
}

fn final_debug_successor_tool_source(
    current_root: &Path,
    evidence: &Path,
) -> Result<Option<String>, String> {
    let repair = final_repair_proof_source(current_root, evidence)?;
    final_debug_successor_tool_source_with_repair(current_root, evidence, repair.as_ref())
}

fn final_debug_successor_tool_source_with_repair(
    current_root: &Path,
    evidence: &Path,
    repair: Option<&FinalRepairProof>,
) -> Result<Option<String>, String> {
    if final_debug_successor_review_source_with_repair(
        current_root, evidence, repair.is_some(),
        repair.is_some_and(|proof| proof.core_successor_active),
        repair.is_some_and(|proof| proof.heap_successor_active),
        repair.is_some_and(|proof| proof.product_successor_active))?.is_none() {
        return Ok(None);
    }
    let parent_path = evidence.join(FINAL_DEBUG_SUCCESSOR_PARENT_FREEZE_FILE);
    let parent = final_debug_successor_parent_freeze(evidence)?;
    let prior_rows = array(&parent, "source_files")?;
    if prior_rows.len() != 64 || final_count_successor_tool_source_with_historical(
        current_root, evidence, true, repair)?
        .as_deref() != Some(FINAL_DEBUG_SUCCESSOR_PRIOR_TOOL_SHA)
    {
        return Err("P17 final debug freeze41 前態不符".into());
    }
    let path = evidence.join(FINAL_DEBUG_SUCCESSOR_FREEZE_FILE);
    let directory = path.parent().ok_or("P17 final debug freeze 目錄缺失")?;
    console_cli_public_file(&path, directory)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    final_debug_successor_freeze_shape(&value, &parent, evidence)?;
    let recorded_root = Path::new(string(&parent, "repository_root")?);
    let rows = array(&value, "source_files")?;
    let successor = StrictJsonParser::parse(&fs::read_to_string(
        evidence.join(FINAL_DEBUG_SUCCESSOR_REVIEW_FILE))
        .map_err(|error| error.to_string())?)?;
    let changes = array(&successor, "changes")?;
    let new_test = field(&successor, "new_test")?;
    let mut prior_index = 0;
    let mut last_path = None::<String>;
    let mut tool_sha = None;
    let mut changed = BTreeSet::new();
    let mut saw_new = false;
    for row in rows {
        object(row, &["path", "sha256", "snapshot_path"])?;
        let row_path = string(row, "path")?;
        if last_path.as_deref().is_some_and(|last| last >= row_path) {
            return Err("P17 final debug freeze 路徑未排序或重複".into());
        }
        last_path = Some(row_path.to_owned());
        let relative = final_successor_recorded_relative(recorded_root, row_path)?
            .to_str().ok_or("P17 final debug source 非 UTF-8")?;
        let digest = string(row, "sha256")?;
        let snapshot = Path::new(string(row, "snapshot_path")?);
        if relative == FINAL_DEBUG_SUCCESSOR_TEST_PATH {
            if saw_new || digest != FINAL_DEBUG_SUCCESSOR_TEST_AFTER_SHA
                || snapshot != Path::new(string(new_test, "snapshot_path")?)
            {
                return Err("P17 final debug 新測試 row 不符".into());
            }
            saw_new = true;
        } else {
            let prior = prior_rows.get(prior_index)
                .ok_or("P17 final debug freeze 多餘舊來源")?;
            prior_index += 1;
            if row_path != string(prior, "path")? {
                return Err(format!("P17 final debug freeze 舊 row 路徑不符：{relative}"));
            }
            if let Some((index, (_, before, after, _))) = FINAL_DEBUG_SUCCESSOR_CHANGES
                .iter().enumerate().find(|(_, (path, _, _, _))| *path == relative)
            {
                if !changed.insert(relative.to_owned())
                    || string(prior, "sha256")? != *before
                    || digest != *after
                    || snapshot != Path::new(string(&changes[index], "after_snapshot_path")?)
                {
                    return Err(format!("P17 final debug source edge row 不符：{relative}"));
                }
            } else if relative == GC_TOOL_PATH {
                if string(prior, "sha256")? != FINAL_DEBUG_SUCCESSOR_PRIOR_TOOL_SHA
                    || digest == FINAL_DEBUG_SUCCESSOR_PRIOR_TOOL_SHA
                    || snapshot != directory.join("xtask__src__p17__b03.rs")
                {
                    return Err("P17 final debug B03 self-edge 不符".into());
                }
                tool_sha = Some(digest.to_owned());
            } else if digest != string(prior, "sha256")?
                || snapshot != Path::new(string(prior, "snapshot_path")?)
            {
                return Err(format!("P17 final debug 非範圍來源變更：{relative}"));
            }
        }
        console_cli_public_file(snapshot, evidence)?;
        sha(snapshot, digest)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err(format!("P17 final debug snapshot 非 0444：{relative}"));
        }
        if repair.is_none() {
            sha(&current_root.join(relative), digest)?;
        }
    }
    if prior_index != prior_rows.len() || changed.len() != FINAL_DEBUG_SUCCESSOR_CHANGES.len()
        || !saw_new
    {
        return Err("P17 final debug freeze 65 筆封口不完整".into());
    }
    tool_sha.map(Some).ok_or_else(|| "P17 final debug B03 row 缺失".into())
}

fn final_debug_successor_sha<'a>(relative: &str, original: &'a str, successor: bool) -> &'a str {
    if successor {
        for (path, before, after, _) in FINAL_DEBUG_SUCCESSOR_CHANGES {
            if relative == path && original == before {
                return after;
            }
        }
    }
    original
}

fn final_debug_current_vm_sha(
    current_root: &Path,
    evidence: &Path,
    original: &'static str,
) -> Result<&'static str, String> {
    final_debug_current_vm_sha_with_verified(current_root, evidence, original, None)
}

fn final_debug_current_vm_sha_with_verified(
    current_root: &Path,
    evidence: &Path,
    original: &'static str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<&'static str, String> {
    let successor = if let Some(verified) = verified {
        verified.check(current_root, evidence)?;
        true
    } else {
        final_debug_successor_tool_source(current_root, evidence)?.is_some()
    };
    let prior = final_debug_successor_sha(DEBUG_VM_PATH, original, successor);
    let repaired = if let Some(verified) = verified {
        verified.repair_active
    } else {
        final_repair_proof_source(current_root, evidence)?.is_some()
    };
    let mapped = product_successor_sha(DEBUG_VM_PATH,
        final_repair_sha(DEBUG_VM_PATH, prior, repaired),
        verified.is_some_and(|context| context.product_successor_active)
            || (verified.is_none() && final_repair_proof_source(current_root, evidence)?
                .is_some_and(|proof| proof.product_successor_active)));
    if let Some(verified) = verified {
        let pinned = verified.source_shas.get(&current_root.join(DEBUG_VM_PATH))
            .ok_or("P17 final debug VM current source 缺失")?;
        if pinned.as_str() != mapped {
            return Err("P17 final debug VM current source SHA 不符".into());
        }
    }
    Ok(mapped)
}

fn final_current_tool_sha(current_root: &Path, evidence: &Path, old_sha: &str) -> Result<String, String> {
    if let Some(repair) = final_repair_proof_source(current_root, evidence)? {
        return Ok(repair.tool_sha);
    }
    if let Some(latest) = final_debug_successor_tool_source(current_root, evidence)? {
        return Ok(latest);
    }
    if let Some(latest) = final_count_successor_tool_source(current_root, evidence)? {
        return Ok(latest);
    }
    Ok(final_successor_tool_source(current_root, evidence)?
        .unwrap_or_else(|| old_sha.to_owned()))
}

fn final_current_tool_sha_with_verified(
    current_root: &Path,
    evidence: &Path,
    old_sha: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<String, String> {
    if let Some(verified) = verified {
        verified.check(current_root, evidence)?;
        Ok(verified.tool_sha.clone())
    } else {
        final_current_tool_sha(current_root, evidence, old_sha)
    }
}

fn final_source_review_shape(value: &StrictJsonValue, evidence: &Path) -> Result<(), String> {
    object(value, &["schema", "status", "prior_producer_review_sha256",
        "prior_gc_review_sha256", "prior_debug_hook_review_sha256",
        "root_integration_review_path", "root_integration_review_sha256",
        "changes", "new_test", "p16_absence_review_path",
        "p16_absence_review_sha256", "review_note"])?;
    if string(value, "schema")? != "rivetlua-p17-final-source-update-v1"
        || string(value, "status")? != "PASS"
        || string(value, "prior_producer_review_sha256")? != FINAL_PRIOR_PRODUCER_REVIEW_SHA
        || string(value, "prior_gc_review_sha256")? != FINAL_PRIOR_GC_REVIEW_SHA
        || string(value, "prior_debug_hook_review_sha256")? != FINAL_PRIOR_HOOK_REVIEW_SHA
        || string(value, "root_integration_review_path")? != evidence.join(
            "p17-db-count-hook-fix-20261013-1/root-alias-final-integration-review.json"
        ).display().to_string()
        || string(value, "root_integration_review_sha256")? != FINAL_ROOT_REVIEW_SHA
        || string(value, "p16_absence_review_path")? != evidence.join(
            "p17-count-test-p16-absence-20261013-1/review.json"
        ).display().to_string()
        || string(value, "p16_absence_review_sha256")? != FINAL_ABSENCE_REVIEW_SHA
        || string(value, "review_note")?.trim().is_empty()
    {
        return Err("P17 final source review 主鍵不符".into());
    }
    let changes = array(value, "changes")?;
    if changes.len() != FINAL_SOURCE_CHANGES.len() {
        return Err("P17 final source change 數不符".into());
    }
    for (change, (relative, before, after)) in changes.iter().zip(FINAL_SOURCE_CHANGES) {
        object(change, &["path", "before_sha256", "after_sha256",
            "before_snapshot_path", "after_snapshot_path", "diff_path", "diff_sha256"])?;
        let name = relative.replace('/', "__");
        if string(change, "path")? != relative
            || string(change, "before_sha256")? != before
            || string(change, "after_sha256")? != after
            || string(change, "before_snapshot_path")? != evidence.join(FINAL_SOURCE_DIR)
                .join(format!("before-{name}")).display().to_string()
            || string(change, "after_snapshot_path")? != evidence.join(FINAL_SOURCE_DIR)
                .join(format!("after-{name}")).display().to_string()
            || string(change, "diff_path")? != evidence.join(format!(
                "p17-phase-final-impact-{name}.diff")).display().to_string()
        {
            return Err(format!("P17 final source edge 不符：{relative}"));
        }
        exit_digest(string(change, "diff_sha256")?)?;
    }
    let test = field(value, "new_test")?;
    object(test, &["path", "after_sha256", "snapshot_path", "baseline_commit"])?;
    if string(test, "path")? != FINAL_COUNT_TEST_PATH
        || string(test, "after_sha256")? != FINAL_COUNT_TEST_SHA
        || string(test, "snapshot_path")? != evidence.join(FINAL_SOURCE_DIR)
            .join(format!("after-{}", FINAL_COUNT_TEST_PATH.replace('/', "__")))
            .display().to_string()
        || string(test, "baseline_commit")? != CONSOLE_BASELINE_COMMIT
    {
        return Err("P17 final count test 身分／P16 前態不符".into());
    }
    Ok(())
}

fn final_source_live_source(current_root: &Path, evidence: &Path) -> Result<bool, String> {
    final_source_live_source_with_verified(current_root, evidence, None)
}

fn final_source_live_source_with_verified(
    current_root: &Path,
    evidence: &Path,
    verified: Option<&FinalVerifiedContext>,
) -> Result<bool, String> {
    let verified = verified.filter(|verified| verified.check(current_root, evidence).is_ok());
    let review = evidence.join(FINAL_SOURCE_REVIEW_FILE);
    if !review.exists() {
        return Ok(false);
    }
    console_cli_public_file(&review, evidence)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&review)
        .map_err(|error| error.to_string())?)?;
    final_source_review_shape(&value, evidence)?;
    let successor = if let Some(verified) = verified {
        if verified.check(current_root, evidence).is_ok() {
            true
        } else {
            return final_source_live_source_with_verified(current_root, evidence, None);
        }
    } else {
        final_successor_review_source(current_root, evidence)?.is_some()
    };
    for (change, (relative, before, after)) in
        array(&value, "changes")?.iter().zip(FINAL_SOURCE_CHANGES)
    {
        for (key, digest) in [("before_snapshot_path", before),
            ("after_snapshot_path", after)]
        {
            let snapshot = Path::new(string(change, key)?);
            console_cli_public_file(snapshot, &evidence.join(FINAL_SOURCE_DIR))?;
            sha(snapshot, digest)?;
            if fs::metadata(snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444
            {
                return Err(format!("P17 final source 快照非 0444：{relative}"));
            }
        }
        sha(&current_root.join(relative),
            final_current_source_sha_with_verified(current_root, evidence,
                relative, after, successor, verified)?)?;
    }
    let snapshot = Path::new(string(field(&value, "new_test")?, "snapshot_path")?);
    console_cli_public_file(snapshot, &evidence.join(FINAL_SOURCE_DIR))?;
    sha(snapshot, FINAL_COUNT_TEST_SHA)?;
    if fs::metadata(snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 final count test 快照非 0444".into());
    }
    if let Some(context) = verified.filter(|context| context.product_successor_active) {
        let current = product_count_current_sha_with_verified(current_root, evidence,
            FINAL_SUCCESSOR_COUNT_TEST_SHA, Some(context))?;
        sha(&current_root.join(FINAL_COUNT_TEST_PATH), current)?;
    } else {
        sha(&current_root.join(FINAL_COUNT_TEST_PATH),
            final_current_source_sha_with_verified(current_root, evidence,
                FINAL_COUNT_TEST_PATH, FINAL_COUNT_TEST_SHA, successor, verified)?)?;
    }
    Ok(true)
}

fn final_source_review_source(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
) -> Result<Option<FinalSourceReview>, String> {
    let (review, scoped, mut scope) = final_source_review_source_scoped(
        original_root, current_root, evidence)?;
    if let (Some(scope), Some(context)) = (&mut scope, scoped.as_ref()) {
        scope.finish(context, current_root, evidence)?;
    }
    Ok(review)
}

fn final_source_review_source_scoped(
    _original_root: &Path,
    current_root: &Path,
    evidence: &Path,
) -> Result<(Option<FinalSourceReview>, Option<FinalVerifiedContext>,
    Option<FinalVerifiedScope>), String> {
    let path = evidence.join(FINAL_SOURCE_REVIEW_FILE);
    if !path.exists() {
        if FINAL_SOURCE_CHANGES.iter().all(|(relative, before, _)| {
            manifest::sha256(&current_root.join(relative)).ok().as_deref() == Some(*before)
        }) && !current_root.join(FINAL_COUNT_TEST_PATH).exists() {
            return Ok((None, None, None));
        }
        return Err("P17 final source 已變但缺 typed review".into());
    }
    let verified = FinalVerifiedContext::verify(current_root, evidence)?;
    let (scoped_verified, local_scope) = match verified.as_ref() {
        Some(context) => {
            let (scoped, scope) = context.begin_phase_scope(current_root, evidence)?;
            (Some(scoped), Some(scope))
        }
        None => (None, None),
    };
    let active = scoped_verified.as_ref();
    if !final_source_live_source_with_verified(current_root, evidence, active)? {
        return Err("P17 final source typed review 缺失".into());
    }
    let value = StrictJsonParser::parse(&fs::read_to_string(&path)
        .map_err(|error| error.to_string())?)?;
    for (prior, digest) in [
        ("p17-phase-producer-source-impact-review-v5.json", FINAL_PRIOR_PRODUCER_REVIEW_SHA),
        ("p17-phase-gc-source-impact-review-v13.json", FINAL_PRIOR_GC_REVIEW_SHA),
        (DEBUG_HOOK_REVIEW_FILE, FINAL_PRIOR_HOOK_REVIEW_SHA),
    ] {
        sha(&evidence.join(prior), digest)?;
    }
    let root_review = Path::new(string(&value, "root_integration_review_path")?);
    let absence = Path::new(string(&value, "p16_absence_review_path")?);
    sha(root_review, FINAL_ROOT_REVIEW_SHA)?;
    sha(absence, FINAL_ABSENCE_REVIEW_SHA)?;
    let root_value = StrictJsonParser::parse(&fs::read_to_string(root_review)
        .map_err(|error| error.to_string())?)?;
    let absence_value = StrictJsonParser::parse(&fs::read_to_string(absence)
        .map_err(|error| error.to_string())?)?;
    if string(&root_value, "status")? != "PASS_FINAL_PRODUCT_INTEGRATION_REVIEW"
        || string(&absence_value, "status")? != "ABSENT"
        || string(&absence_value, "relative_path")? != FINAL_COUNT_TEST_PATH
        || string(&absence_value, "fixed_commit")? != CONSOLE_BASELINE_COMMIT
    {
        return Err("P17 final source root/P16 absence 前態不符".into());
    }
    for (change, (relative, before, after)) in
        array(&value, "changes")?.iter().zip(FINAL_SOURCE_CHANGES)
    {
        let before_path = Path::new(string(change, "before_snapshot_path")?);
        let after_path = Path::new(string(change, "after_snapshot_path")?);
        gc_raw_diff(current_root, evidence, change, relative,
            before_path, before, after_path, after)?;
    }
    assert_warning_new_test_absent(current_root, FINAL_COUNT_TEST_PATH)?;
    let old_error = evidence.join(FINAL_SOURCE_DIR).join(format!(
        "before-{}", ERROR_NEW_TEST.replace('/', "__")));
    sha(&old_error, FINAL_ERROR_TEST_BEFORE_SHA)?;
    let result = FinalSourceReview {
        input: report::Input::from_path(&path)?,
        successor: if let Some(verified) = active {
            verified.check(current_root, evidence)?;
            Some(verified.successor.clone())
        } else {
            final_successor_review_source(current_root, evidence)?
        },
        count_successor: if let Some(verified) = active {
            verified.check(current_root, evidence)?;
            Some(verified.count_successor.clone())
        } else if final_count_successor_tool_source(current_root, evidence)?.is_some() {
            final_count_successor_review_source(current_root, evidence)?
        } else {
            None
        },
        debug_successor: if let Some(verified) = active {
            verified.check(current_root, evidence)?;
            Some(verified.debug_successor.clone())
        } else if final_debug_successor_tool_source(current_root, evidence)?.is_some() {
            final_debug_successor_review_source(current_root, evidence)?
        } else {
            None
        },
        verified,
    };
    Ok((Some(result), scoped_verified, local_scope))
}

fn final_source_relocated_source(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    recorded: &str,
    digest: &str,
) -> Result<PathBuf, String> {
    final_source_relocated_source_with_verified(
        original_root, current_root, evidence, recorded, digest, None)
}

fn final_source_relocated_source_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    recorded: &str,
    digest: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<PathBuf, String> {
    if let Some(verified) = verified {
        verified.check(current_root, evidence)?;
    }
    if let Some(context) = verified.filter(|context| context.repair_active) {
        for (relative, before, after) in FINAL_REPAIR_PRODUCT_CHANGES {
            if recorded == original_root.join(relative).display().to_string()
                && digest == before
            {
                let pinned = context.source_shas.get(&current_root.join(relative))
                    .ok_or_else(|| format!("P17 final repair current source 缺失：{relative}"))?;
                if pinned.as_str() != product_successor_sha(relative, heap_successor_sha(relative,
                    core_successor_sha(relative, after, context.core_successor_active),
                    context.heap_successor_active), context.product_successor_active) {
                    return Err(format!("P17 final repair current source SHA 不符：{relative}"));
                }
                return report::phase_relocated_source(
                    original_root, current_root, recorded, pinned);
            }
        }
    }
    for (relative, before, after) in FINAL_SOURCE_CHANGES {
        if recorded == original_root.join(relative).display().to_string() && digest == before {
            if !final_source_live_source_with_verified(current_root, evidence, verified)? {
                return Err(format!("P17 final source 缺 typed bridge：{relative}"));
            }
            let successor = if verified.is_some() { true } else {
                final_successor_review_source(current_root, evidence)?.is_some()
            };
            return report::phase_relocated_source(original_root, current_root, recorded,
                final_current_source_sha_with_verified(current_root, evidence,
                    relative, after, successor, verified)?);
        }
    }
    for (relative, before, after, _, _) in FINAL_SUCCESSOR_CHANGES {
        if recorded == original_root.join(relative).display().to_string() && digest == before
            && (verified.is_some()
                || final_successor_review_source(current_root, evidence)?.is_some())
        {
            return report::phase_relocated_source(original_root, current_root, recorded,
                final_current_source_sha_with_verified(current_root, evidence,
                    relative, after, true, verified)?);
        }
    }
    for (relative, before, after, _, _, _) in FINAL_COUNT_SUCCESSOR_CHANGES {
        if recorded == original_root.join(relative).display().to_string() && digest == before
            && (verified.is_some()
                || final_count_successor_tool_source(current_root, evidence)?.is_some())
        {
            let prior = final_debug_successor_sha(relative, after,
                verified.is_some()
                    || final_debug_successor_tool_source(current_root, evidence)?.is_some());
            let repaired = if let Some(verified) = verified {
                verified.repair_active
            } else { final_repair_proof_source(current_root, evidence)?.is_some() };
            return report::phase_relocated_source(original_root, current_root, recorded,
                current_repair_sha(relative, prior, repaired,
                    verified.is_some_and(|context| context.core_successor_active)
                        || (verified.is_none() && final_repair_proof_source(current_root, evidence)?
                            .is_some_and(|proof| proof.core_successor_active)),
                    verified.is_some_and(|context| context.heap_successor_active)
                        || (verified.is_none() && final_repair_proof_source(current_root, evidence)?
                            .is_some_and(|proof| proof.heap_successor_active)), verified.is_some_and(|context| context.product_successor_active) || (verified.is_none() && final_repair_proof_source(current_root, evidence)?.is_some_and(|proof| proof.product_successor_active))));
        }
    }
    for (relative, before, after, _) in FINAL_DEBUG_SUCCESSOR_CHANGES {
        if recorded == original_root.join(relative).display().to_string()
            && digest == before
            && (verified.is_some()
                || final_debug_successor_tool_source(current_root, evidence)?.is_some())
        {
            let repaired = if let Some(verified) = verified {
                verified.repair_active
            } else { final_repair_proof_source(current_root, evidence)?.is_some() };
            return report::phase_relocated_source(original_root, current_root, recorded,
                current_repair_sha(relative, after, repaired,
                    verified.is_some_and(|context| context.core_successor_active)
                        || (verified.is_none() && final_repair_proof_source(current_root, evidence)?
                            .is_some_and(|proof| proof.core_successor_active)),
                    verified.is_some_and(|context| context.heap_successor_active)
                        || (verified.is_none() && final_repair_proof_source(current_root, evidence)?
                            .is_some_and(|proof| proof.heap_successor_active)), verified.is_some_and(|context| context.product_successor_active) || (verified.is_none() && final_repair_proof_source(current_root, evidence)?.is_some_and(|proof| proof.product_successor_active))));
        }
    }
    if let Some(verified) = verified {
        for (relative, _, after, _) in FINAL_DEBUG_SUCCESSOR_CHANGES {
            if recorded == original_root.join(relative).display().to_string() && digest == after {
                return report::phase_relocated_source(original_root, current_root, recorded,
                    current_repair_sha(relative, after, verified.repair_active,
                        verified.core_successor_active, verified.heap_successor_active, verified.product_successor_active));
            }
        }
    }
    if let Some(context) = verified.filter(|context| context.product_successor_active) {
        if recorded == original_root.join(PRODUCT_BASIC_PATH).display().to_string()
            && digest == "9e18df7a5a90d6022dc1003a14c2b842ce9b6d7e7406d3bab080df4e364b1b7b"
        {
            let current = current_repair_sha(PRODUCT_BASIC_PATH, digest,
                context.repair_active, context.core_successor_active,
                context.heap_successor_active, context.product_successor_active);
            if context.source_shas.get(&current_root.join(PRODUCT_BASIC_PATH))
                .map(String::as_str) != Some(current) {
                return Err("P17 product basic current source SHA 不符".into());
            }
            return report::phase_relocated_source(original_root, current_root, recorded, current);
        }
        if recorded == original_root.join(DEBUG_VM_TEST_PATH).display().to_string() {
            if digest != DEBUG_VM_TEST_SHA {
                return Err("P17 product names test 歷史 source SHA 不符".into());
            }
            return report::phase_relocated_source(original_root, current_root, recorded,
                product_names_current_sha_with_verified(current_root, evidence, Some(context))?);
        }
        for (relative, before, _, _) in PRODUCT_SUCCESSOR_NEW_SOURCE_EDGES {
            if recorded == original_root.join(relative).display().to_string() {
                let current_after = product_successor_sha(relative, before, true);
                if digest != before
                    || context.source_shas.get(&current_root.join(relative))
                        .map(String::as_str) != Some(current_after) {
                    return Err(format!("P17 product successor historical endpoint 不符：{relative}"));
                }
                return report::phase_relocated_source(original_root, current_root, recorded,
                    current_after);
            }
        }
    }
    debug_hook_relocated_source_with_verified(
        original_root, current_root, evidence, recorded, digest, verified)
}

fn final_source_historical_input(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
) -> Result<Option<report::Input>, String> {
    final_source_historical_input_with_verified(
        original_root, current_root, evidence, value, None)
}

fn final_source_historical_input_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<report::Input>, String> {
    let path = string(value, "path")?;
    let digest = string(value, "sha256")?;
    for (relative, before, _) in FINAL_SOURCE_CHANGES {
        if path == original_root.join(relative).display().to_string() && digest == before {
            final_source_relocated_source_with_verified(
                original_root, current_root, evidence, path, digest, verified)?;
            let snapshot = evidence.join(FINAL_SOURCE_DIR).join(format!(
                "before-{}", relative.replace('/', "__")));
            sha(&snapshot, before)?;
            return Ok(Some(report::Input { path: path.into(), sha256: digest.into() }));
        }
    }
    for (relative, before, _, _) in FINAL_DEBUG_SUCCESSOR_CHANGES {
        if path == original_root.join(relative).display().to_string() && digest == before {
            final_source_relocated_source_with_verified(
                original_root, current_root, evidence, path, digest, verified)?;
            let parent = final_debug_successor_parent_freeze(evidence)?;
            let recorded_path = Path::new(string(&parent, "repository_root")?)
                .join(relative).display().to_string();
            let row = array(&parent, "source_files")?.iter()
                .find(|row| string(row, "path").ok() == Some(recorded_path.as_str()))
                .ok_or_else(|| format!("P17 final debug 舊來源 inventory 缺失：{relative}"))?;
            if string(row, "sha256")? != before {
                return Err(format!("P17 final debug 舊來源 inventory SHA 不符：{relative}"));
            }
            let snapshot = Path::new(string(row, "snapshot_path")?);
            console_cli_public_file(snapshot, evidence)?;
            sha(snapshot, before)?;
            if fs::metadata(snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444
            {
                return Err(format!("P17 final debug 舊來源 snapshot 非 0444：{relative}"));
            }
            return Ok(Some(report::Input { path: path.into(), sha256: digest.into() }));
        }
    }
    final_manifest_historical_input(
        original_root, current_root, evidence, value, verified)
}

fn final_manifest_historical_input(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<report::Input>, String> {
    const RELATIVE: &str = "xtask/src/p17/manifest.rs";
    const BEFORE: &str = "3a90b8ce8e04e4323f7ba828abf708fa89c9060002f7bbf7194f05501c1c7155";
    const AFTER: &str = "69af1ef83b674251a816bf9b88cf37317cb742e3804a6638154960ea0c855c8e";
    const REVIEW_SHA: &str = "e4715b601ba09f6ce3f3de86f2623e194988e3ae6575251532e48021b9622f6b";
    const DIFF_SHA: &str = "57e5fd88642d1e910a61cc76867f8a57114e7a1b9cf277fb71d9057dc6dede4a";
    let path = string(value, "path")?;
    let digest = string(value, "sha256")?;
    if path != original_root.join(RELATIVE).display().to_string() || digest != BEFORE {
        return Ok(None);
    }
    let Some(verified) = verified else {
        return Ok(None);
    };
    verified.check(current_root, evidence)?;
    let directory = evidence.join("p17-inprocess-sha256-final-20261013-1");
    let review_path = directory.join("review.json");
    let before = directory.join("manifest-before.rs");
    let after = directory.join("manifest-after.rs");
    let diff = directory.join("manifest.diff");
    for (file, expected) in [
        (&review_path, REVIEW_SHA), (&before, BEFORE), (&after, AFTER), (&diff, DIFF_SHA),
    ] {
        console_cli_public_file(file, evidence)?;
        sha(file, expected)?;
        if fs::metadata(file).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 manifest SHA 歷史證據非 0444".into());
        }
    }
    let review = StrictJsonParser::parse(&fs::read_to_string(&review_path)
        .map_err(|error| error.to_string())?)?;
    object(&review, &["added_lines", "after_sha256", "before_sha256",
        "constants_match_existing_std_rust_algorithm", "diff_bytes", "diff_sha256",
        "evidence_dir", "expected_vector_file_sha256", "only_manifest_changed_in_this_task",
        "removed_lines", "sha256_tool_call_removed"])?;
    if string(&review, "before_sha256")? != BEFORE
        || string(&review, "after_sha256")? != AFTER
        || string(&review, "diff_sha256")? != DIFF_SHA
        || string(&review, "evidence_dir")? != directory.display().to_string()
        || !boolean(&review, "only_manifest_changed_in_this_task")?
        || !boolean(&review, "sha256_tool_call_removed")?
    {
        return Err("P17 manifest SHA 歷史 typed edge 不符".into());
    }
    sha(&current_root.join(RELATIVE), AFTER)?;
    report::phase_relocated_source(original_root, current_root, path, AFTER)?;
    Ok(Some(report::Input { path: path.into(), sha256: digest.into() }))
}

fn bind_final_manifest_report_view(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    view: &mut report::PhaseSourceView,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    const RELATIVE: &str = "xtask/src/p17/manifest.rs";
    const BEFORE: &str = "3a90b8ce8e04e4323f7ba828abf708fa89c9060002f7bbf7194f05501c1c7155";
    let path = original_root.join(RELATIVE).display().to_string();
    let record = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"sha256\":{}}}", report::q(&path), report::q(BEFORE),
    ))?;
    if report::historical_input(&record, view)?.is_some() {
        return Err("P17 final manifest 報告 endpoint 已存在".into());
    }
    if final_manifest_historical_input(
        original_root, current_root, evidence, &record, verified,
    )?.is_none() {
        return Err("P17 final manifest 報告缺已驗 typed edge".into());
    }
    view.insert(path, report::HistoricalSource {
        before_sha256: BEFORE.into(),
        snapshot: evidence.join("p17-inprocess-sha256-final-20261013-1/manifest-before.rs"),
    });
    Ok(())
}

fn gc_review_shape(
    value: &StrictJsonValue,
    root: &Path,
    evidence: &Path,
) -> Result<(), String> {
    object(value, &[
        "schema", "status", "old_exit_review_sha256", "old_host_review_sha256",
        "changes", "tool_changes", "test_path", "test_sha256",
        "public_proof_path", "public_proof_sha256", "private_proof_path",
        "private_proof_sha256", "reuse_review_path", "reuse_review_sha256",
    ])?;
    if string(value, "schema")? != "rivetlua-p17-gc-update-v1"
        || string(value, "status")? != "PASS"
        || string(value, "old_exit_review_sha256")? != GC_OLD_EXIT_SHA
        || string(value, "old_host_review_sha256")? != GC_OLD_HOST_SHA
        || string(value, "test_path")? != GC_TEST_PATH
        || string(value, "test_sha256")? != GC_TEST_SHA
    {
        return Err("P17 GC review 主鍵不符".into());
    }
    let changes = array(value, "changes")?;
    let tools = array(value, "tool_changes")?;
    if changes.len() != 4 || tools.len() != 1 {
        return Err("P17 GC 必須恰有四個產品與一個工具 source edge".into());
    }
    gc_change_shape(&changes[0], evidence, GC_BASIC_PATH, GC_BASIC_BEFORE_SHA, None, None)?;
    gc_change_shape(&changes[1], evidence, GC_TABLE_PATH, GC_TABLE_BEFORE_SHA, None, None)?;
    gc_change_shape(&changes[2], evidence, GC_METAMETHOD_PATH, GC_METAMETHOD_BEFORE_SHA, None, None)?;
    gc_change_shape(&changes[3], evidence, GC_HEAP_PATH, GC_HEAP_BEFORE_SHA, None, None)?;
    gc_change_shape(&tools[0], evidence, GC_TOOL_PATH, GC_TOOL_BEFORE_SHA, None, None)?;
    for (path_key, digest_key, path) in [
        ("public_proof_path", "public_proof_sha256", evidence.join(GC_PROOF_DIR).join("public/result.json")),
        ("private_proof_path", "private_proof_sha256", evidence.join(GC_PROOF_DIR).join("private/result.json")),
        ("reuse_review_path", "reuse_review_sha256", evidence.join(GC_PROOF_DIR).join("reuse-review.json")),
    ] {
        if string(value, path_key)? != path.display().to_string() {
            return Err(format!("P17 GC {path_key} 路徑不符"));
        }
        exit_digest(string(value, digest_key)?)?;
    }
    sha(&root.join(GC_TEST_PATH), GC_TEST_SHA)?;
    Ok(())
}

fn gc_change_projection(change: &StrictJsonValue) -> Result<StrictJsonValue, String> {
    StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"before_sha256\":{},\"after_sha256\":{},\"diff_path\":{},\"diff_sha256\":{}}}",
        report::q(string(change, "path")?),
        report::q(string(change, "before_sha256")?),
        report::q(string(change, "after_sha256")?),
        report::q(string(change, "diff_path")?),
        report::q(string(change, "diff_sha256")?),
    ))
}

fn gc_raw_diff(
    current_root: &Path,
    evidence: &Path,
    change: &StrictJsonValue,
    relative: &str,
    before: &Path,
    before_sha: &str,
    after: &Path,
    after_sha: &str,
) -> Result<(), String> {
    let diff = Path::new(string(change, "diff_path")?);
    console_cli_public_file(diff, evidence)?;
    console_change_identity(
        &gc_change_projection(change)?, relative, Some(before_sha), after_sha, diff,
    )?;
    sha(diff, string(change, "diff_sha256")?)?;
    let output = verified_review_git(current_root)?
        .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
        .arg(before).arg(after).output().map_err(|error| error.to_string())?;
    let stored = fs::read(diff).map_err(|error| error.to_string())?;
    if output.status.code() != Some(1) || !output.stderr.is_empty() || output.stdout != stored {
        return Err(format!("P17 GC raw diff 不符：{relative}"));
    }
    Ok(())
}

fn gc_change_source(
    current_root: &Path,
    evidence: &Path,
    change: &StrictJsonValue,
    relative: &str,
    before_sha: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let before = gc_before_source_with_verified(current_root, evidence, relative, verified)?;
    let after_sha = string(change, "after_sha256")?;
    let after_snapshot = Path::new(string(change, "after_snapshot_path")?);
    let directory = evidence.join(if relative == GC_TOOL_PATH { GC_TOOL_SOURCE_DIR } else { GC_SOURCE_DIR });
    console_cli_public_file(after_snapshot, &directory)?;
    sha(after_snapshot, after_sha)?;
    if fs::metadata(after_snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err(format!("P17 GC 新快照非 0444：{relative}"));
    }
    let current_after = if relative == GC_TOOL_PATH {
        final_current_tool_sha_with_verified(current_root, evidence, after_sha, verified)?
    } else if relative == GC_HEAP_PATH {
        let prior = final_debug_successor_sha(relative, after_sha,
            if let Some(verified) = verified {
                verified.check(current_root, evidence).is_ok()
                    || final_debug_successor_tool_source(current_root, evidence)?.is_some()
            } else {
                final_debug_successor_tool_source(current_root, evidence)?.is_some()
            });
        let repair = if verified.is_none() {
            final_repair_proof_source(current_root, evidence)?
        } else { None };
        current_repair_sha(relative, prior,
            verified.is_some_and(|context| context.repair_active) || repair.is_some(),
            verified.is_some_and(|context| context.core_successor_active)
                || repair.as_ref().is_some_and(|proof| proof.core_successor_active),
            verified.is_some_and(|context| context.heap_successor_active)
                || repair.as_ref().is_some_and(|proof| proof.heap_successor_active), verified.is_some_and(|context| context.product_successor_active) || repair.as_ref().is_some_and(|proof| proof.product_successor_active)).into()
    } else if let Some(context) = verified {
        current_repair_sha(relative, after_sha, context.repair_active,
            context.core_successor_active, context.heap_successor_active,
            context.product_successor_active).to_owned()
    } else {
        after_sha.to_owned()
    };
    sha(&current_root.join(relative), &current_after)?;
    gc_raw_diff(
        current_root, evidence, change, relative,
        &before, before_sha, after_snapshot, after_sha,
    )?;
    Ok(())
}

fn gc_reuse_review(root: &Path, evidence: &Path, value: &StrictJsonValue) -> Result<(), String> {
    let directory = evidence.join(GC_PROOF_DIR);
    let path = directory.join("reuse-review.json");
    if string(value, "reuse_review_path")? != path.display().to_string() {
        return Err("P17 GC reuse review 路徑不符".into());
    }
    console_cli_public_file(&path, &directory)?;
    sha(&path, string(value, "reuse_review_sha256")?)?;
    let review = StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    object(&review, &[
        "schema", "status", "repository_root", "old_exit_review_sha256",
        "old_host_review_sha256", "before_sources", "after_sources",
        "new_test_path", "new_test_sha256", "required_new_checks",
        "historical_scope", "review_note",
    ])?;
    if string(&review, "schema")? != "rivetlua-p17-gc-reuse-v1"
        || string(&review, "status")? != "PASS"
        || string(&review, "repository_root")? != root.display().to_string()
        || string(&review, "old_exit_review_sha256")? != GC_OLD_EXIT_SHA
        || string(&review, "old_host_review_sha256")? != GC_OLD_HOST_SHA
        || string(&review, "new_test_path")? != GC_TEST_PATH
        || string(&review, "new_test_sha256")? != GC_TEST_SHA
        || strings(&review, "required_new_checks")? != [
            "public-lua55", "public-lua54", "private-basic", "private-weak-table",
            "private-metamethod", "private-heap-basic", "private-heap-complete",
            "final-phase-gate",
        ]
        || string(&review, "historical_scope")? != "OLD_PROOFS_NOT_CURRENT_SOURCE_PASS"
        || string(&review, "review_note")?.trim().is_empty()
    {
        return Err("P17 GC reuse review 主鍵不符".into());
    }
    let before = field(&review, "before_sources")?;
    let after = field(&review, "after_sources")?;
    object(before, &[GC_BASIC_PATH, GC_TABLE_PATH, GC_METAMETHOD_PATH, GC_HEAP_PATH])?;
    object(after, &[GC_BASIC_PATH, GC_TABLE_PATH, GC_METAMETHOD_PATH, GC_HEAP_PATH])?;
    for (index, (relative, digest)) in [
        (GC_BASIC_PATH, GC_BASIC_BEFORE_SHA),
        (GC_TABLE_PATH, GC_TABLE_BEFORE_SHA),
        (GC_METAMETHOD_PATH, GC_METAMETHOD_BEFORE_SHA),
        (GC_HEAP_PATH, GC_HEAP_BEFORE_SHA),
    ].into_iter().enumerate() {
        if string(before, relative)? != digest
            || string(after, relative)? != string(&array(value, "changes")?[index], "after_sha256")?
        {
            return Err(format!("P17 GC reuse endpoint 不符：{relative}"));
        }
    }
    Ok(())
}

fn gc_review_source(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    producer: Option<&ProducerUpdateReview>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<GcReview>, String> {
    let verified = verified.filter(|verified| verified.check(current_root, evidence).is_ok());
    let path = evidence.join(GC_REVIEW_FILE);
    if !path.exists() {
        if manifest::sha256(&current_root.join(GC_BASIC_PATH))? == GC_BASIC_BEFORE_SHA
            && manifest::sha256(&current_root.join(GC_TABLE_PATH))? == GC_TABLE_BEFORE_SHA
            && manifest::sha256(&current_root.join(GC_METAMETHOD_PATH))? == GC_METAMETHOD_BEFORE_SHA
            && manifest::sha256(&current_root.join(GC_HEAP_PATH))? == GC_HEAP_BEFORE_SHA
            && manifest::sha256(&current_root.join(GC_TOOL_PATH))? == GC_TOOL_BEFORE_SHA
        {
            return Ok(None);
        }
        return Err("P17 GC 來源已變但缺 typed sidecar".into());
    }
    console_cli_public_file(&path, evidence)?;
    let value = StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    gc_review_shape(&value, current_root, evidence)?;
    let prior_path = evidence.join("p17-phase-gc-source-impact-review-v9.json");
    sha(&prior_path, GC_PRIOR_REVIEW_SHA)?;
    let prior_v10_path = evidence.join("p17-phase-gc-source-impact-review-v10.json");
    sha(&prior_v10_path, GC_PRIOR_V10_REVIEW_SHA)?;
    let prior_v10 = StrictJsonParser::parse(&fs::read_to_string(&prior_v10_path)
        .map_err(|error| error.to_string())?)?;
    if string(&array(&prior_v10, "tool_changes")?[0], "after_sha256")? != PRODUCER_V2_TOOL_AFTER_SHA {
        return Err("P17 GC v10 工具前史不符".into());
    }
    let prior_v11_path = evidence.join("p17-phase-gc-source-impact-review-v11.json");
    sha(&prior_v11_path, GC_PRIOR_V11_REVIEW_SHA)?;
    let prior_v11 = StrictJsonParser::parse(&fs::read_to_string(&prior_v11_path)
        .map_err(|error| error.to_string())?)?;
    if string(&array(&prior_v11, "tool_changes")?[0], "after_sha256")? != PRIOR_BRIDGE_TOOL_SHA {
        return Err("P17 GC v11 工具前史不符".into());
    }
    let prior_v12_path = evidence.join("p17-phase-gc-source-impact-review-v12.json");
    sha(&prior_v12_path, GC_PRIOR_V12_REVIEW_SHA)?;
    let prior_v12 = StrictJsonParser::parse(&fs::read_to_string(&prior_v12_path)
        .map_err(|error| error.to_string())?)?;
    if string(&array(&prior_v12, "tool_changes")?[0], "after_sha256")? != DEBUG_HOOK_PRIOR_TOOL_SHA {
        return Err("P17 GC v12 工具前史不符".into());
    }
    let prior_v13_path = evidence.join("p17-phase-gc-source-impact-review-v13.json");
    sha(&prior_v13_path, GC_PRIOR_V13_REVIEW_SHA)?;
    let prior_v13 = StrictJsonParser::parse(&fs::read_to_string(&prior_v13_path)
        .map_err(|error| error.to_string())?)?;
    if string(&array(&prior_v13, "tool_changes")?[0], "after_sha256")? != FINAL_PRIOR_TOOL_SHA {
        return Err("P17 GC v13 工具前史不符".into());
    }
    let prior_v14_path = evidence.join("p17-phase-gc-source-impact-review-v14.json");
    sha(&prior_v14_path, GC_PRIOR_V14_REVIEW_SHA)?;
    let prior_v14 = StrictJsonParser::parse(&fs::read_to_string(&prior_v14_path)
        .map_err(|error| error.to_string())?)?;
    if string(&array(&prior_v14, "tool_changes")?[0], "after_sha256")? != INTERMEDIATE_FINAL_TOOL_SHA {
        return Err("P17 GC v14 工具前史不符".into());
    }
    let prior_v15_path = evidence.join("p17-phase-gc-source-impact-review-v15.json");
    sha(&prior_v15_path, GC_PRIOR_V15_REVIEW_SHA)?;
    let prior_v15 = StrictJsonParser::parse(&fs::read_to_string(&prior_v15_path)
        .map_err(|error| error.to_string())?)?;
    if string(&array(&prior_v15, "tool_changes")?[0], "after_sha256")? != FINAL_BRIDGE_TOOL_SHA {
        return Err("P17 GC v15 工具前史不符".into());
    }
    let prior_v16_path = evidence.join("p17-phase-gc-source-impact-review-v16.json");
    sha(&prior_v16_path, GC_PRIOR_V16_REVIEW_SHA)?;
    let prior_v16 = StrictJsonParser::parse(&fs::read_to_string(&prior_v16_path)
        .map_err(|error| error.to_string())?)?;
    if string(&array(&prior_v16, "tool_changes")?[0], "after_sha256")? != FINAL_REPAIR1_TOOL_SHA {
        return Err("P17 GC v16 工具前史不符".into());
    }
    let prior_v17_path = evidence.join("p17-phase-gc-source-impact-review-v17.json");
    sha(&prior_v17_path, GC_PRIOR_V17_REVIEW_SHA)?;
    let prior_v17 = StrictJsonParser::parse(&fs::read_to_string(&prior_v17_path)
        .map_err(|error| error.to_string())?)?;
    if string(&array(&prior_v17, "tool_changes")?[0], "after_sha256")? != FINAL_REPAIR2_TOOL_SHA {
        return Err("P17 GC v17 工具前史不符".into());
    }
    let prior = StrictJsonParser::parse(&fs::read_to_string(&prior_path).map_err(|error| error.to_string())?)?;
    if canonical_json(field(&prior, "changes")?) != canonical_json(field(&value, "changes")?) {
        return Err("P17 GC v10 產品 edges 與 v9 不符".into());
    }
    for key in ["old_exit_review_sha256", "old_host_review_sha256", "test_path", "test_sha256",
        "public_proof_path", "public_proof_sha256", "private_proof_path", "private_proof_sha256",
        "reuse_review_path", "reuse_review_sha256"] {
        if string(&prior, key)? != string(&value, key)? {
            return Err(format!("P17 GC v10 原證據鏈不符：{key}"));
        }
    }
    for key in ["old_exit_review_sha256", "old_host_review_sha256", "test_path", "test_sha256",
        "public_proof_path", "public_proof_sha256", "private_proof_path", "private_proof_sha256",
        "reuse_review_path", "reuse_review_sha256"] {
        if string(&prior_v11, key)? != string(&value, key)? {
            return Err(format!("P17 GC v12 舊證據鏈不符：{key}"));
        }
        if string(&prior_v12, key)? != string(&value, key)? {
            return Err(format!("P17 GC v13 舊證據鏈不符：{key}"));
        }
        if string(&prior_v13, key)? != string(&value, key)? {
            return Err(format!("P17 GC v14 舊證據鏈不符：{key}"));
        }
        if string(&prior_v14, key)? != string(&value, key)? {
            return Err(format!("P17 GC v15 舊證據鏈不符：{key}"));
        }
        if string(&prior_v15, key)? != string(&value, key)? {
            return Err(format!("P17 GC v16 舊證據鏈不符：{key}"));
        }
        if string(&prior_v16, key)? != string(&value, key)? {
            return Err(format!("P17 GC v17 舊證據鏈不符：{key}"));
        }
        if string(&prior_v17, key)? != string(&value, key)? {
            return Err(format!("P17 GC v18 舊證據鏈不符：{key}"));
        }
    }
    if string(&array(&prior, "tool_changes")?[0], "after_sha256")? != PRODUCER_PRIOR_TOOL_AFTER_SHA {
        return Err("P17 GC v9 工具前史不符".into());
    }
    let producer = producer.ok_or("P17 GC 缺 15-source producer typed bridge")?;
    sha(&evidence.join("p17-phase-exit-source-impact-review.json"), GC_OLD_EXIT_SHA)?;
    sha(&evidence.join("p17-phase-host-entry-source-impact-review.json"), GC_OLD_HOST_SHA)?;
    for (change, (relative, before)) in array(&value, "changes")?.iter().zip([
        (GC_BASIC_PATH, GC_BASIC_BEFORE_SHA), (GC_TABLE_PATH, GC_TABLE_BEFORE_SHA),
        (GC_METAMETHOD_PATH, GC_METAMETHOD_BEFORE_SHA),
        (GC_HEAP_PATH, GC_HEAP_BEFORE_SHA),
    ]) {
        gc_change_source(current_root, evidence, change, relative, before, verified)?;
    }
    let gc_tool = &array(&value, "tool_changes")?[0];
    if string(gc_tool, "after_sha256")? != producer.tool_after_sha {
        return Err("P17 GC 新工具 endpoint 與 producer self-edge 不符".into());
    }
    gc_change_source(
        current_root, evidence, gc_tool, GC_TOOL_PATH, GC_TOOL_BEFORE_SHA, verified,
    )?;
    gc_reuse_review(original_root, evidence, &value)?;
    for kind in ["public", "private"] {
        gc_proof_leaf(original_root, current_root, evidence, &value, producer, kind, verified)?;
    }
    Ok(Some(GcReview { input: report::Input::from_path(&path)? }))
}

fn gc_source_hashes(
    value: &StrictJsonValue,
    producer: &ProducerUpdateReview,
) -> Result<Vec<String>, String> {
    let changes = array(value, "changes")?;
    if changes.len() != 4 {
        return Err("P17 GC source hash 四個產品端點缺失".into());
    }
    Ok(vec![
        string(&changes[3], "after_sha256")?.into(), EXIT_CTRL_VM_AFTER_SHA.into(),
        EXIT_CTRL_CLI_AFTER_SHA.into(), EXIT_CTRL_BIN_AFTER_SHA.into(),
        EXIT_CTRL_MANIFEST_AFTER_SHA.into(), EXIT_CTRL_LOCK_AFTER_SHA.into(),
        string(&changes[0], "after_sha256")?.into(),
        string(&changes[1], "after_sha256")?.into(),
        string(&changes[2], "after_sha256")?.into(),
        GC_TEST_SHA.into(),
        "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff".into(),
        EXIT_PARSER_AFTER_SHA.into(),
        "1495457f26a517b8a89014b1b3bb227289605e01b325f8fcbada323dd95a3959".into(),
        producer.after_hashes[0].clone(), producer.after_hashes[1].clone(),
    ])
}

fn gc_row_shape(row: &StrictJsonValue, kind: &str) -> Result<(), String> {
    let mut keys = vec![
        "profile", "command", "cwd", "environment_mode", "environment",
        "exit_code", "matched", "passed", "failed", "ignored", "filtered",
        "log_path", "log_sha256", "running_binary_path", "snapshot_path",
        "snapshot_sha256", "source_inputs",
    ];
    match kind {
        "public" => keys.extend(["cli_running_binary_path", "cli_snapshot_path", "cli_snapshot_sha256"]),
        "private" => keys.push("case"),
        _ => return Err("P17 GC proof 類別不符".into()),
    }
    object(row, &keys)?;
    Ok(())
}

fn gc_row_counts(row: &StrictJsonValue, matched: u64, public: bool) -> Result<(), String> {
    if integer(row, "exit_code")? != 0
        || integer(row, "matched")? != matched
        || integer(row, "passed")? != matched
        || integer(row, "failed")? != 0
        || integer(row, "ignored")? != 0
        || (public && integer(row, "filtered")? != 0)
    {
        return Err("P17 GC proof 測試數／結果不符".into());
    }
    integer(row, "filtered")?;
    Ok(())
}

struct GcLeaf {
    directory: PathBuf,
    proof: StrictJsonValue,
    environment: StrictJsonValue,
}

fn gc_proof_leaf_header(
    root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    producer: &ProducerUpdateReview,
    kind: &str,
) -> Result<GcLeaf, String> {
    let (path_key, sha_key, reported_by) = match kind {
        "public" => ("public_proof_path", "public_proof_sha256", "/root/p17_binary_prefix_verify"),
        "private" => ("private_proof_path", "private_proof_sha256", "/root/p17_warn_argument_core"),
        _ => return Err("P17 GC proof 類別不符".into()),
    };
    let directory = evidence.join(GC_PROOF_DIR).join(kind);
    let result = directory.join("result.json");
    if string(value, path_key)? != result.display().to_string() {
        return Err(format!("P17 GC {kind} result 路徑不符"));
    }
    console_cli_public_file(&result, &directory)?;
    sha(&result, string(value, sha_key)?)?;
    let proof = StrictJsonParser::parse(&fs::read_to_string(&result).map_err(|error| error.to_string())?)?;
    object(&proof, &[
        "status", "reported_by", "root_review", "readiness_path",
        "readiness_sha256", "rows",
    ])?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    const READY_SHA: &str = "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb";
    sha(&readiness, READY_SHA)?;
    if string(&proof, "status")? != "PASS"
        || string(&proof, "reported_by")? != reported_by
        || string(&proof, "readiness_path")? != readiness.display().to_string()
        || string(&proof, "readiness_sha256")? != READY_SHA
        || array(&proof, "rows")?.len() != if kind == "public" { 2 } else { 5 }
    {
        return Err(format!("P17 GC {kind} proof 主鍵不符"));
    }
    let root_review = directory.join("root-review.json");
    console_cli_public_file(&root_review, &directory)?;
    let root_sha = manifest::sha256(&root_review)?;
    if string(&proof, "root_review")?
        != format!("{} SHA-256 {root_sha}", root_review.display())
    {
        return Err(format!("P17 GC {kind} root-review 引用不符"));
    }
    let review = StrictJsonParser::parse(
        &fs::read_to_string(&root_review).map_err(|error| error.to_string())?,
    )?;
    object(&review, &[
        "schema", "status", "kind", "repository_root", "source_paths",
        "source_hashes", "terminal_records", "artifact_checks", "input_basis",
        "checks", "review_note",
    ])?;
    let hashes = field(&review, "source_hashes")?;
    object(hashes, &GC_SOURCE_PATHS)?;
    let expected_hashes = gc_source_hashes(value, producer)?;
    if string(&review, "schema")? != "rivetlua-p17-gc-root-review-v1"
        || string(&review, "status")? != "PASS"
        || string(&review, "kind")? != kind
        || string(&review, "repository_root")? != root.display().to_string()
        || strings(&review, "source_paths")?
            != GC_SOURCE_PATHS.iter().map(|path| (*path).to_owned()).collect::<Vec<_>>()
        || array(&review, "terminal_records")?.len() != 2
        || array(&review, "artifact_checks")?.is_empty()
        || array(&review, "input_basis")?.is_empty()
        || array(&review, "checks")?.is_empty()
        || string(&review, "review_note")?.trim().is_empty()
    {
        return Err(format!("P17 GC {kind} root-review 主鍵不符"));
    }
    for (relative, digest) in GC_SOURCE_PATHS.iter().zip(&expected_hashes) {
        if string(hashes, relative)? != digest {
            return Err(format!("P17 GC {kind} root source SHA 不符：{relative}"));
        }
    }
    let mut terminals = BTreeSet::new();
    for item in array(&review, "terminal_records")? {
        object(item, &["path", "sha256"])?;
        let path = Path::new(string(item, "path")?);
        let digest = string(item, "sha256")?;
        exit_digest(digest)?;
        if !path.starts_with(evidence.join(GC_PROOF_DIR))
            || !terminals.insert(path.to_path_buf())
            || path == root_review || path == result
        {
            return Err(format!("P17 GC {kind} terminal 來源不符"));
        }
        console_cli_public_file(path, &evidence.join(GC_PROOF_DIR))?;
        sha(path, digest)?;
        let terminal = StrictJsonParser::parse(
            &fs::read_to_string(path).map_err(|error| error.to_string())?,
        )?;
        if !matches!(string(&terminal, "status")?, "PASS" | "COMPLETE") {
            return Err(format!("P17 GC {kind} terminal 未完成"));
        }
    }
    let readiness_value = StrictJsonParser::parse(
        &fs::read_to_string(&readiness).map_err(|error| error.to_string())?,
    )?;
    let environment = StrictJsonParser::parse(&canonical_json(
        field(field(&readiness_value, "phase_launch")?, "required_environment")?,
    ))?;
    object(&environment, &[
        "PATH", "CC", "AR", "SDKROOT", "MACOSX_DEPLOYMENT_TARGET",
        "CARGO_TARGET_AARCH64_APPLE_DARWIN_LINKER", "RUSTFLAGS",
        "LLVM_DISABLE_SYMBOLIZATION", "RUST_BACKTRACE", "CFLAGS", "ARFLAGS",
        "CARGO_TARGET_DIR", "TMPDIR", "RIVETLUA_P17_EVIDENCE_DIR",
        "GIT_CONFIG_NOSYSTEM", "GIT_CONFIG_GLOBAL",
    ])?;
    Ok(GcLeaf { directory, proof, environment })
}

fn gc_proof_leaf_sources(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    producer: &ProducerUpdateReview,
    row: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let inputs = array(row, "source_inputs")?;
    let hashes = gc_source_hashes(value, producer)?;
    if inputs.len() != GC_SOURCE_PATHS.len() {
        return Err("P17 GC proof 15-source 數量不符".into());
    }
    for ((source, relative), digest) in inputs.iter().zip(GC_SOURCE_PATHS).zip(hashes) {
        object(source, &["path", "sha256", "snapshot_path"])?;
        let path = original_root.join(relative).display().to_string();
        let snapshot = Path::new(string(source, "snapshot_path")?);
        if string(source, "path")? != path || string(source, "sha256")? != digest {
            return Err(format!("P17 GC proof source 順序／SHA 不符：{relative}"));
        }
        console_cli_public_file(snapshot, &evidence.join(GC_PROOF_DIR))?;
        sha(snapshot, &digest)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err(format!("P17 GC proof source 快照非 0444：{relative}"));
        }
        final_source_relocated_source_with_verified(
            original_root, current_root, evidence, &path, &digest, verified)?;
    }
    Ok(())
}

fn gc_driver_identity(
    row: &StrictJsonValue,
    target: &Path,
    snapshot_dir: &Path,
    prefix: &str,
) -> Result<(), String> {
    let running = Path::new(string(row, "running_binary_path")?);
    let digest = string(row, "snapshot_sha256")?;
    exit_digest(digest)?;
    let snapshot = Path::new(string(row, "snapshot_path")?);
    if running.parent() != Some(target.join("debug/deps").as_path())
        || !running.file_name().and_then(|name| name.to_str())
            .is_some_and(|name| name.starts_with(prefix))
    {
        return Err("P17 GC driver 身分不符".into());
    }
    console_cli_public_file(snapshot, snapshot_dir)?;
    sha(snapshot, digest)?;
    if fs::metadata(snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o555
    {
        return Err("P17 GC driver 快照非 0555".into());
    }
    report::mach_type(snapshot, "EXECUTE")
}

fn gc_proof_leaf(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    producer: &ProducerUpdateReview,
    kind: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let leaf = gc_proof_leaf_header(original_root, evidence, value, producer, kind)?;
    let cargo = exit_safe_cargo(evidence)?;
    let target = Path::new(string(&leaf.environment, "CARGO_TARGET_DIR")?);
    for (index, row) in array(&leaf.proof, "rows")?.iter().enumerate() {
        gc_proof_row(original_root, current_root, evidence, value, producer, &leaf,
            kind, index, row, cargo, target, verified)?;
    }
    Ok(())
}

fn gc_environment_matches(
    actual: &StrictJsonValue,
    expected: &StrictJsonValue,
) -> Result<bool, String> {
    let StrictJsonValue::Object(entries) = expected else {
        return Err("P17 GC 預期環境非物件".into());
    };
    if entries.len() != 16 {
        return Err("P17 GC 預期環境欄位數不符".into());
    }
    let keys = entries.iter().map(|(key, _)| key.as_str()).collect::<Vec<_>>();
    object(actual, &keys)?;
    for key in keys {
        if string(actual, key)? != string(expected, key)? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn gc_proof_row(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    producer: &ProducerUpdateReview,
    leaf: &GcLeaf,
    kind: &str,
    index: usize,
    row: &StrictJsonValue,
    cargo: &str,
    target: &Path,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
        gc_row_shape(row, kind)?;
        let (profile, case, selector, name, matched, public) = match (kind, index) {
            ("public", 0) => ("lua55", None, "", "", 2, true),
            ("public", 1) => ("lua54", None, "", "", 2, true),
            ("private", 0) => (
                "lua54-and-lua55", Some("basic"),
                "stdlib::basic::gc_running_tests::p17_lua54_collectgarbage_legacy_parameters_preserve_previous_and_atomicity",
                "stdlib::basic::gc_running_tests::p17_lua54_collectgarbage_legacy_parameters_preserve_previous_and_atomicity",
                1, false,
            ),
            ("private", 1) => (
                "lua54-and-lua55", Some("weak-table"),
                "table::tests::p17_weak_table_drops_deleted_long_string_tombstone_at_gc",
                "table::tests::p17_weak_table_drops_deleted_long_string_tombstone_at_gc",
                1, false,
            ),
            ("private", 2) => (
                "default-profile", Some("metamethod"),
                "metamethod::tests::p17_metamethod_lookup_uses_borrowed_key_without_lua_allocation",
                "metamethod::tests::p17_metamethod_lookup_uses_borrowed_key_without_lua_allocation",
                1, false,
            ),
            ("private", 3) => (
                "lua54-and-lua55", Some("heap-basic"),
                "heap::p17_gc_indirect_payload_tests::p17_indirect_payload_basic_charges_and_failure_rollback",
                "heap::p17_gc_indirect_payload_tests::p17_indirect_payload_basic_charges_and_failure_rollback",
                1, false,
            ),
            ("private", 4) => (
                "lua54-and-lua55", Some("heap-complete"),
                "heap::p17_gc_indirect_payload_tests::p17_indirect_payload_complete_reachable_graph_finalizer_and_reclaim",
                "heap::p17_gc_indirect_payload_tests::p17_indirect_payload_complete_reachable_graph_finalizer_and_reclaim",
                1, false,
            ),
            _ => return Err("P17 GC proof row 類別／順序不符".into()),
        };
        let features = if profile == "lua55" { "native-lua55" } else { "native-lua54,default-lua54" };
        let command = if public {
            vec![cargo, "test", "--locked", "-p", "rivetlua-cli", "--features",
                features, "--test", "p17_gc_compat"]
        } else {
            vec![cargo, "test", "--locked", "-p", "rivetlua-runtime", "--lib",
                selector, "--", "--exact", "--nocapture", "--test-threads=1"]
        };
        if string(row, "profile")? != profile
            || case.is_some_and(|expected| string(row, "case").ok() != Some(expected))
            || strings(row, "command")?
                != command.into_iter().map(str::to_owned).collect::<Vec<_>>()
            || string(row, "cwd")? != original_root.display().to_string()
            || string(row, "environment_mode")? != "env -i"
            || !gc_environment_matches(field(row, "environment")?, &leaf.environment)?
            || gc_row_counts(row, matched, public).is_err()
        {
            return Err(format!("P17 GC {kind}/{index} 命令／count 不符"));
        }
        let log = Path::new(string(row, "log_path")?);
        if !log.starts_with(evidence.join(GC_PROOF_DIR))
            || log == leaf.directory.join("result.json")
            || log == leaf.directory.join("root-review.json")
        {
            return Err(format!("P17 GC {kind}/{index} log 路徑不符"));
        }
        console_cli_public_file(log, &evidence.join(GC_PROOF_DIR))?;
        sha(log, string(row, "log_sha256")?)?;
        let prefix = if public { "p17_gc_compat-" } else { "rivetlua_runtime-" };
        gc_driver_identity(row, target, &evidence.join(GC_PROOF_DIR), prefix)?;
        let names: Vec<&str> = if public {
            vec![
                "p17_gc_lua54_basic_mode_and_parameters",
                "p17_gc_weak_long_string_keys_are_collected",
            ]
        } else {
            vec![name]
        };
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(&body, &names, !public)?;
        let runner = if public { "tests/p17_gc_compat.rs" } else { "unittests src/lib.rs" };
        let running = Path::new(string(row, "running_binary_path")?);
        if counts.matched != matched as u32
            || counts.passed != matched as u32
            || counts.failed != 0 || counts.ignored != 0
            || !body.contains(&format!("0 measured; {} filtered out;", integer(row, "filtered")?))
            || !body.contains(&format!("Running {runner} ({})", running.display()))
        {
            return Err(format!("P17 GC {kind}/{index} 具名 log／driver 不符"));
        }
        if public {
            let cli_running = Path::new(string(row, "cli_running_binary_path")?);
            let cli_snapshot = Path::new(string(row, "cli_snapshot_path")?);
            let cli_sha = string(row, "cli_snapshot_sha256")?;
            exit_digest(cli_sha)?;
            if cli_running != target.join("debug/rivetlua") {
                return Err("P17 GC public CLI product binary 身分不符".into());
            }
            console_cli_public_file(cli_snapshot, &evidence.join(GC_PROOF_DIR))?;
            sha(cli_snapshot, cli_sha)?;
            if fs::metadata(cli_snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o555
            {
                return Err("P17 GC public CLI product binary 非 0555".into());
            }
            report::mach_type(cli_snapshot, "EXECUTE")?;
        }
        gc_proof_leaf_sources(original_root, current_root, evidence,
            value, producer, row, verified)?;
    Ok(())
}

fn exit_ctrl_c_source_index(relative: &str) -> Option<usize> {
    EXIT_CTRL_CHANGES.iter().position(|(path, _, _)| *path == relative)
}

fn gc_declared_after(current_root: &Path, evidence: &Path, relative: &str) -> Result<String, String> {
    let path = evidence.join(GC_REVIEW_FILE);
    let value = StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    gc_review_shape(&value, current_root, evidence)?;
    let row = match relative {
        GC_BASIC_PATH => &array(&value, "changes")?[0],
        GC_TABLE_PATH => &array(&value, "changes")?[1],
        GC_METAMETHOD_PATH => &array(&value, "changes")?[2],
        GC_HEAP_PATH => &array(&value, "changes")?[3],
        GC_TOOL_PATH => &array(&value, "tool_changes")?[0],
        _ => return Err(format!("P17 GC 範圍外 source endpoint：{relative}")),
    };
    Ok(string(row, "after_sha256")?.into())
}

fn gc_before_source(current_root: &Path, evidence: &Path, relative: &str) -> Result<PathBuf, String> {
    gc_before_source_with_verified(current_root, evidence, relative, None)
}

fn gc_before_source_with_verified(
    current_root: &Path,
    evidence: &Path,
    relative: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<PathBuf, String> {
    let (directory, before) = match relative {
        GC_BASIC_PATH => (GC_SOURCE_DIR, GC_BASIC_BEFORE_SHA),
        GC_TABLE_PATH => (GC_SOURCE_DIR, GC_TABLE_BEFORE_SHA),
        GC_METAMETHOD_PATH => (GC_SOURCE_DIR, GC_METAMETHOD_BEFORE_SHA),
        GC_HEAP_PATH => (GC_SOURCE_DIR, GC_HEAP_BEFORE_SHA),
        GC_TOOL_PATH => (GC_TOOL_SOURCE_DIR, GC_TOOL_BEFORE_SHA),
        _ => return Err(format!("P17 GC 範圍外歷史來源：{relative}")),
    };
    if let Some(verified) = verified {
        verified.check(current_root, evidence)?;
    }
    let declared_after = gc_declared_after(current_root, evidence, relative)?;
    let current_after = if relative == GC_TOOL_PATH {
        final_current_tool_sha_with_verified(current_root, evidence, &declared_after, verified)?
    } else if relative == GC_HEAP_PATH
        && (verified.is_some()
            || final_debug_successor_tool_source(current_root, evidence)?.is_some())
    {
        if declared_after != DEBUG_HOOK_HEAP_SHA {
            return Err("P17 GC heap 歷史 endpoint 與 final typed edge 不符".into());
        }
        FINAL_DEBUG_SUCCESSOR_HEAP_AFTER_SHA.into()
    } else {
        declared_after
    };
    let expected_live = if let Some(verified) = verified {
        let mapped = current_repair_sha(relative, &current_after, verified.repair_active,
            verified.core_successor_active, verified.heap_successor_active, verified.product_successor_active);
        let pinned = verified.source_shas.get(&current_root.join(relative))
            .ok_or_else(|| format!("P17 GC final context 缺 live source：{relative}"))?;
        if pinned.as_str() != mapped {
            return Err(format!("P17 GC final context source SHA 不符：{relative}"));
        }
        pinned.as_str()
    } else {
        current_after.as_str()
    };
    sha(&current_root.join(relative), expected_live)?;
    let snapshot = evidence.join(directory)
        .join(format!("before-{}", relative.replace('/', "__")));
    console_cli_public_file(&snapshot, &evidence.join(directory))?;
    sha(&snapshot, before)?;
    if fs::metadata(&snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err(format!("P17 GC 舊快照非 0444：{relative}"));
    }
    Ok(snapshot)
}

fn gc_historical_input(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
) -> Result<Option<report::Input>, String> {
    gc_historical_input_with_verified(
        original_root, current_root, evidence, value, None)
}

fn gc_historical_input_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<report::Input>, String> {
    let path = string(value, "path")?;
    let Ok(relative) = Path::new(path).strip_prefix(original_root) else {
        return Ok(None);
    };
    let relative = relative.display().to_string();
    let before = match relative.as_str() {
        GC_BASIC_PATH => GC_BASIC_BEFORE_SHA,
        GC_TABLE_PATH => GC_TABLE_BEFORE_SHA,
        GC_METAMETHOD_PATH => GC_METAMETHOD_BEFORE_SHA,
        GC_HEAP_PATH => GC_HEAP_BEFORE_SHA,
        GC_TOOL_PATH => GC_TOOL_BEFORE_SHA,
        _ => return Ok(None),
    };
    if string(value, "sha256")? != before {
        return Ok(None);
    }
    gc_before_source_with_verified(current_root, evidence, &relative, verified)?;
    Ok(Some(report::Input { path: path.into(), sha256: before.into() }))
}

fn sparse_gc_historical_input_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<report::Input>, String> {
    let path = string(value, "path")?;
    if path != original_root.join(GC_MOD_PATH).display().to_string() {
        return Ok(None);
    }
    let Some(context) = verified.filter(|context|
        context.repair_active && context.core_successor_active && context.heap_successor_active)
    else {
        return Ok(None);
    };
    object(value, &["path", "sha256"])?;
    if string(value, "sha256")? != GC_MOD_BEFORE_SHA {
        return Err("P17 sparse GC module 歷史 input SHA 不符".into());
    }
    context.check(current_root, evidence)?;
    if context.source_shas.len() != (if context.product_successor_active { 69 } else { 66 })
        || context.source_shas.get(&current_root.join(GC_MOD_PATH)).map(String::as_str)
            != Some(GC_MOD_AFTER_SHA)
    {
        return Err("P17 sparse GC module current row 缺失／SHA不符".into());
    }
    let snapshot = evidence.join(
        "p17-xtask-final-debug-successor-20261013-22/p17-gc-sparse-before-gc-mod.rs");
    console_cli_public_file(&snapshot, evidence)?;
    sha(&snapshot, GC_MOD_BEFORE_SHA)?;
    if fs::metadata(&snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 sparse GC module 歷史 snapshot 非0444".into());
    }
    Ok(Some(report::Input { path: path.into(), sha256: GC_MOD_BEFORE_SHA.into() }))
}

fn gc_heap_historical_input(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
) -> Result<Option<report::Input>, String> {
    gc_heap_historical_input_with_verified(
        original_root, current_root, evidence, value, None)
}

fn gc_heap_historical_input_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<report::Input>, String> {
    if !evidence.join(GC_REVIEW_FILE).exists()
        || string(value, "path")? != original_root.join(GC_HEAP_PATH).display().to_string()
        || string(value, "sha256")? != GC_HEAP_BEFORE_SHA
    {
        return Ok(None);
    }
    gc_historical_input_with_verified(
        original_root, current_root, evidence, value, verified)?
        .ok_or_else(|| "P17 GC heap 前態歷史來源缺失".into())
        .map(Some)
}

fn exit_ctrl_c_before_source(
    current_root: &Path,
    evidence: &Path,
    relative: &str,
) -> Result<PathBuf, String> {
    exit_ctrl_c_before_source_with_verified(current_root, evidence, relative, None)
}

fn exit_ctrl_c_before_source_with_verified(
    current_root: &Path,
    evidence: &Path,
    relative: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<PathBuf, String> {
    let index = exit_ctrl_c_source_index(relative)
        .ok_or_else(|| format!("P17 Ctrl-C 範圍外歷史來源：{relative}"))?;
    let (_, before_sha, after_sha) = EXIT_CTRL_CHANGES[index];
    if relative == GC_HEAP_PATH && evidence.join(GC_REVIEW_FILE).exists() {
        sha(&gc_before_source_with_verified(
            current_root, evidence, relative, verified)?, after_sha)?;
    } else if relative == DEBUG_VM_PATH
        && debug_vm_live_source_with_verified(current_root, evidence, verified)? {
        sha(&evidence.join(DEBUG_VM_SOURCE_DIR).join(format!(
            "before-{}", DEBUG_VM_PATH.replace('/', "__"))), after_sha)?;
    } else if relative == EXIT_CTRL_CLI_PATH
        && final_repair_cli_current_with_verified(current_root, evidence, verified)? {
        let historical_after = evidence.join(EXIT_CTRL_SOURCE_DIR)
            .join(format!("after-{}", relative.replace('/', "__")));
        console_cli_public_file(&historical_after, &evidence.join(EXIT_CTRL_SOURCE_DIR))?;
        sha(&historical_after, after_sha)?;
    } else {
        sha(&current_root.join(relative), after_sha)?;
    }
    let snapshot = evidence.join(EXIT_CTRL_SOURCE_DIR)
        .join(format!("before-{}", relative.replace('/', "__")));
    console_cli_public_file(&snapshot, &evidence.join(EXIT_CTRL_SOURCE_DIR))?;
    sha(&snapshot, before_sha)?;
    if fs::metadata(&snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err(format!("P17 Ctrl-C 舊快照非 0444：{relative}"));
    }
    Ok(snapshot)
}

fn exit_ctrl_c_virtual_current_sha(
    current_root: &Path,
    evidence: &Path,
    relative: &str,
) -> Result<String, String> {
    exit_ctrl_c_virtual_current_sha_with_verified(current_root, evidence, relative, None)
}

fn exit_ctrl_c_virtual_current_sha_with_verified(
    current_root: &Path,
    evidence: &Path,
    relative: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<String, String> {
    if relative == EXIT_PARSER_PATH {
        if let Some(verified) = verified {
            verified.check(current_root, evidence)?;
            if verified.repair_active {
                let current = current_root.join(relative);
                let mapped = current_repair_sha(relative, EXIT_PARSER_AFTER_SHA, true,
                    verified.core_successor_active, verified.heap_successor_active,
                    verified.product_successor_active);
                if verified.source_shas.get(&current).map(String::as_str) != Some(mapped) {
                    return Err("P17 parser 歷史 view final source SHA 不符".into());
                }
                sha(&current, mapped)?;
                return Ok(EXIT_PARSER_AFTER_SHA.into());
            }
        }
    }
    let current = if relative == EXIT_PUBLIC_REPL_TEST_PATH
        && final_repair_repl_test_current_with_verified(current_root, evidence, verified)? {
        EXIT_PUBLIC_REPL_SHA.into()
    } else if relative == EXIT_CTRL_CLI_PATH
        && final_repair_cli_current_with_verified(current_root, evidence, verified)? {
        EXIT_CTRL_CLI_AFTER_SHA.into()
    } else if relative == DEBUG_VM_PATH
        && debug_vm_live_source_with_verified(current_root, evidence, verified)? {
        DEBUG_VM_BEFORE_SHA.into()
    } else {
        manifest::sha256(&current_root.join(relative))?
    };
    if let Some(index) = exit_ctrl_c_source_index(relative) {
        let (_, before, after) = EXIT_CTRL_CHANGES[index];
        let gc_heap = if relative == GC_HEAP_PATH && evidence.join(GC_REVIEW_FILE).exists() {
            sha(&gc_before_source_with_verified(
                current_root, evidence, relative, verified)?, after)?;
            true
        } else {
            false
        };
        if current == after || gc_heap {
            exit_ctrl_c_before_source_with_verified(current_root, evidence, relative, verified)?;
            return Ok(before.into());
        }
    }
    Ok(current)
}

fn exit_ctrl_c_unchanged_sources(current_root: &Path) -> Result<(), String> {
    for (relative, before, _) in EXIT_CTRL_CHANGES {
        sha(&current_root.join(relative), before)?;
    }
    Ok(())
}

fn exit_ctrl_c_host_historical_input(
    root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
) -> Result<Option<report::Input>, String> {
    exit_ctrl_c_host_historical_input_with_verified(root, evidence, value, None)
}

fn exit_ctrl_c_host_historical_input_with_verified(
    root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<report::Input>, String> {
    let path = string(value, "path")?;
    for relative in [EXIT_CTRL_BIN_PATH, EXIT_CTRL_MANIFEST_PATH, EXIT_CTRL_LOCK_PATH] {
        if path != root.join(relative).display().to_string() {
            continue;
        }
        let index = exit_ctrl_c_source_index(relative).ok_or("P17 Ctrl-C host source 範圍缺失")?;
        let before = EXIT_CTRL_CHANGES[index].1;
        if string(value, "sha256")? != before {
            return Err(format!("P17 Ctrl-C host 舊 source SHA 不符：{relative}"));
        }
        exit_ctrl_c_before_source_with_verified(root, evidence, relative, verified)?;
        return Ok(Some(report::Input { path: path.into(), sha256: before.into() }));
    }
    Ok(None)
}

fn exit_ctrl_c_source_update(
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
) -> Result<(), String> {
    exit_ctrl_c_source_update_with_verified(current_root, evidence, update, None)
}

fn exit_ctrl_c_source_update_with_verified(
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    exit_ctrl_c_update_shape(update)?;
    let source_dir = evidence.join(EXIT_CTRL_SOURCE_DIR);
    let manifest = source_dir.join("physical-git-raw-diffs.json");
    console_cli_public_file(&manifest, &source_dir)?;
    sha(&manifest, "5600d26ae5a950edca752b4c97bf178594fe20b04f0ba6600a20a3f4e91592f3")?;
    let recorded = StrictJsonParser::parse(
        &fs::read_to_string(&manifest).map_err(|error| error.to_string())?,
    )?;
    object(&recorded, &["schema", "status", "rows"])?;
    if string(&recorded, "schema")? != "rivetlua-p17-ctrl-c-physical-git-raw-diffs-v1"
        || string(&recorded, "status")? != "PASS_DIFFS_PRESENT"
        || array(&recorded, "rows")?.len() != EXIT_CTRL_CHANGES.len()
    {
        return Err("P17 Ctrl-C physical Git raw diff manifest 不符".into());
    }
    let primary = source_dir.join("primary-source-review.json");
    console_cli_public_file(&primary, &source_dir)?;
    sha(&primary, "1cded3b9afb18fd7e03ac19e7c2c3df3e235aa73e978643df42197d5352f237c")?;
    for (index, (change, row)) in array(update, "changes")?.iter()
        .zip(array(&recorded, "rows")?).enumerate()
    {
        let (relative, before_sha, after_sha) = EXIT_CTRL_CHANGES[index];
        let name = relative.replace('/', "__");
        let before = source_dir.join(format!("before-{name}"));
        let after = source_dir.join(format!("after-{name}"));
        let diff = evidence.join(format!("p17-phase-ctrl-c-impact-{name}.diff"));
        object(row, &[
            "path", "before_sha256", "after_sha256", "before_path", "after_path",
            "diff_path", "diff_sha256", "command", "return_code",
        ])?;
        if string(change, "before_snapshot_path")? != before.display().to_string()
            || string(change, "after_snapshot_path")? != after.display().to_string()
            || string(change, "diff_path")? != diff.display().to_string()
            || string(row, "path")? != relative
            || string(row, "before_sha256")? != before_sha
            || string(row, "after_sha256")? != after_sha
            || string(row, "before_path")? != before.display().to_string()
            || string(row, "after_path")? != after.display().to_string()
            || string(row, "diff_path")? != diff.display().to_string()
            || string(row, "diff_sha256")? != EXIT_CTRL_DIFF_SHAS[index]
            || integer(row, "return_code")? != 1
        {
            return Err(format!("P17 Ctrl-C raw diff 來源身分不符：{relative}"));
        }
        let command = vec![
            "/Library/Developer/CommandLineTools/usr/bin/git".to_owned(),
            "--no-pager".into(), "-c".into(), "color.ui=false".into(),
            "diff".into(), "--no-index".into(), "--no-ext-diff".into(),
            "--no-textconv".into(), "--".into(),
            before.display().to_string(), after.display().to_string(),
        ];
        if strings(row, "command")? != command {
            return Err(format!("P17 Ctrl-C physical Git 命令不符：{relative}"));
        }
        for (path, digest) in [(&before, before_sha), (&after, after_sha)] {
            console_cli_public_file(path, &source_dir)?;
            sha(path, digest)?;
            if fs::metadata(path).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444
            {
                return Err(format!("P17 Ctrl-C source 快照非 0444：{relative}"));
            }
        }
        let effective_after = if relative == GC_HEAP_PATH && evidence.join(GC_REVIEW_FILE).exists() {
            gc_before_source_with_verified(current_root, evidence, relative, verified)?
        } else if relative == DEBUG_VM_PATH
            && debug_vm_live_source_with_verified(current_root, evidence, verified)? {
            evidence.join(DEBUG_VM_SOURCE_DIR).join(format!(
                "before-{}", DEBUG_VM_PATH.replace('/', "__")))
        } else if relative == EXIT_CTRL_CLI_PATH
            && final_repair_cli_current_with_verified(current_root, evidence, verified)? {
            after.clone()
        } else {
            current_root.join(relative)
        };
        sha(&effective_after, after_sha)?;
        console_cli_public_file(&diff, evidence)?;
        sha(&diff, EXIT_CTRL_DIFF_SHAS[index])?;
        let output = verified_review_git(current_root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(&before).arg(&effective_after)
            .output().map_err(|error| error.to_string())?;
        let stored = fs::read(&diff).map_err(|error| error.to_string())?;
        if output.status.code() != Some(1)
            || !output.stderr.is_empty()
            || !console_old_diff_matches(
                &output.stdout, &stored, &before, &after, &effective_after,
            )?
        {
            return Err(format!("P17 Ctrl-C raw diff 內容不符：{relative}"));
        }
    }
    sha(&current_root.join(EXIT_CTRL_TEST_PATH), EXIT_CTRL_TEST_SHA)?;
    Ok(())
}

fn exit_ctrl_c_reuse_review(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
) -> Result<(), String> {
    exit_ctrl_c_reuse_review_with_verified(
        original_root, current_root, evidence, update, None)
}

fn exit_ctrl_c_reuse_review_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let directory = evidence.join(EXIT_CTRL_PROOF_DIR);
    let path = directory.join("reuse-review.json");
    if string(update, "reuse_review_path")? != path.display().to_string() {
        return Err("P17 Ctrl-C reuse review 路徑不符".into());
    }
    if string(update, "reuse_review_sha256")?
        != "fd6bc2c07c813dba904d3a5529ac83946a153e33deb447b43a574ef7ee41e908"
    {
        return Err("P17 Ctrl-C reuse review SHA 不符".into());
    }
    console_cli_public_file(&path, &directory)?;
    sha(&path, string(update, "reuse_review_sha256")?)?;
    let review = StrictJsonParser::parse(
        &fs::read_to_string(&path).map_err(|error| error.to_string())?,
    )?;
    object(&review, &[
        "schema", "status", "repository_root", "old_exit_review_sha256",
        "old_host_review_sha256", "before_sources", "after_sources",
        "new_test_path", "new_test_sha256", "required_new_checks",
        "historical_scope", "review_note",
    ])?;
    if string(&review, "schema")? != "rivetlua-p17-ctrl-c-reuse-v1"
        || string(&review, "status")? != "PASS"
        || string(&review, "repository_root")? != original_root.display().to_string()
        || string(&review, "old_exit_review_sha256")?
            != "fd5d65299d08c29f8e2b79e915f33fcece027c3b3b681faf4d34affc1a04eedd"
        || string(&review, "old_host_review_sha256")?
            != "07c9164db2baf97ee5f0dfdc75d856cbde2b6c1f0619c8cd4e34fb9a3692714f"
        || string(&review, "new_test_path")? != EXIT_CTRL_TEST_PATH
        || string(&review, "new_test_sha256")? != EXIT_CTRL_TEST_SHA
        || string(&review, "historical_scope")? != "OLD_PROOFS_NOT_CURRENT_SOURCE_PASS"
        || strings(&review, "required_new_checks")? != [
            "public-lua55", "public-lua54", "private-vm-basic",
            "private-vm-pcall-gc", "private-cli-lua55", "private-cli-lua54",
            "final-phase-gate",
        ]
        || string(&review, "review_note")?.trim().is_empty()
    {
        return Err("P17 Ctrl-C reuse review 主鍵／範圍不符".into());
    }
    let before = field(&review, "before_sources")?;
    let after = field(&review, "after_sources")?;
    let paths = EXIT_CTRL_CHANGES.map(|(relative, _, _)| relative);
    object(before, &paths)?;
    object(after, &paths)?;
    let source_dir = evidence.join(EXIT_CTRL_SOURCE_DIR);
    for (relative, old, new) in EXIT_CTRL_CHANGES {
        let name = relative.replace('/', "__");
        if string(before, relative)? != old || string(after, relative)? != new {
            return Err(format!("P17 Ctrl-C reuse source endpoint 不符：{relative}"));
        }
        for (expected_path, expected_sha) in [
            (source_dir.join(format!("before-{name}")), old),
            (source_dir.join(format!("after-{name}")), new),
        ] {
            console_cli_public_file(&expected_path, &source_dir)?;
            sha(&expected_path, expected_sha)?;
        }
        if relative == GC_HEAP_PATH && evidence.join(GC_REVIEW_FILE).exists() {
            sha(&gc_before_source_with_verified(
                current_root, evidence, relative, verified)?, new)?;
        } else if relative == DEBUG_VM_PATH
            && debug_vm_live_source_with_verified(current_root, evidence, verified)? {
            sha(&evidence.join(DEBUG_VM_SOURCE_DIR).join(format!(
                "before-{}", DEBUG_VM_PATH.replace('/', "__"))), new)?;
        } else if relative != EXIT_CTRL_CLI_PATH
            || !final_repair_cli_current_with_verified(current_root, evidence, verified)? {
            sha(&current_root.join(relative), new)?;
        }
    }
    for (file, expected) in [
        ("p17-phase-exit-source-impact-review.json",
            "fd5d65299d08c29f8e2b79e915f33fcece027c3b3b681faf4d34affc1a04eedd"),
        ("p17-phase-host-entry-source-impact-review.json",
            "07c9164db2baf97ee5f0dfdc75d856cbde2b6c1f0619c8cd4e34fb9a3692714f"),
    ] {
        let archive = directory.join("canonical-before").join(file);
        console_cli_public_file(&archive, &directory)?;
        sha(&archive, expected)?;
        if fs::metadata(&archive).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 Ctrl-C 舊 canonical 快照非 0444".into());
        }
    }
    Ok(())
}

struct CtrlLeaf {
    directory: PathBuf,
    proof: StrictJsonValue,
    environment: StrictJsonValue,
}

fn exit_ctrl_c_leaf_header(
    original_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    kind: &str,
) -> Result<CtrlLeaf, String> {
    let (path_key, sha_key, producer) = match kind {
        "public" => ("public_proof_path", "public_proof_sha256", "/root/p17_binary_prefix_verify"),
        "private-vm" => ("private_vm_proof_path", "private_vm_proof_sha256", "/root/p17_warn_argument_core"),
        "private-cli" => ("private_cli_proof_path", "private_cli_proof_sha256", "/root/p17_warn_argument_core"),
        _ => return Err("P17 Ctrl-C 未知 proof 類別".into()),
    };
    let directory = evidence.join(EXIT_CTRL_PROOF_DIR).join(kind);
    let result = directory.join("result.json");
    let fixed_sha = match kind {
        "public" => Some("67af7dd4bea8ece7bd65470923c97aa0ce94a089321a053ef42d205c7dd576be"),
        "private-vm" => Some("a57c0c8d7db12e67b7430931bde350814b1be792c929db00750852885878781f"),
        "private-cli" => Some("b9cb6edced0d94373612271d5e594c8d48321c2ad351da482e24d22f59efd236"),
        _ => None,
    };
    if string(update, path_key)? != result.display().to_string() {
        return Err(format!("P17 Ctrl-C {kind} result 路徑不符"));
    }
    if fixed_sha.is_some_and(|expected| string(update, sha_key).ok() != Some(expected)) {
        return Err(format!("P17 Ctrl-C {kind} result SHA 不符"));
    }
    console_cli_public_file(&result, &directory)?;
    sha(&result, string(update, sha_key)?)?;
    let proof = StrictJsonParser::parse(
        &fs::read_to_string(&result).map_err(|error| error.to_string())?,
    )?;
    object(&proof, &[
        "status", "reported_by", "root_review", "readiness_path",
        "readiness_sha256", "rows",
    ])?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    const READY_SHA: &str = "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb";
    sha(&readiness, READY_SHA)?;
    if string(&proof, "status")? != "PASS"
        || string(&proof, "reported_by")? != producer
        || string(&proof, "readiness_path")? != readiness.display().to_string()
        || string(&proof, "readiness_sha256")? != READY_SHA
        || array(&proof, "rows")?.len() != 2
    {
        return Err(format!("P17 Ctrl-C {kind} proof 主鍵不符"));
    }
    let root_review = directory.join("root-review.json");
    console_cli_public_file(&root_review, &directory)?;
    let root_sha = manifest::sha256(&root_review)?;
    let fixed_root_sha = match kind {
        "public" => Some("b74b24632985c3d5fa6348bb5792c9ccd0f9aafc448186f012e654dfecd4e3fe"),
        "private-vm" => Some("fdad1523a2dbd666b9c4214da79e338c123baf3505873190abc619ad561ff8d3"),
        "private-cli" => Some("77e09b8cce6ea0f202e207d7da34668ca8d42dfa9786f13e7ca2948e3f91c0a1"),
        _ => None,
    };
    if fixed_root_sha.is_some_and(|expected| root_sha != expected) {
        return Err(format!("P17 Ctrl-C {kind} root-review SHA 不符"));
    }
    if !string(&proof, "root_review")?.contains(&root_review.display().to_string())
        || !string(&proof, "root_review")?.contains(&root_sha)
    {
        return Err(format!("P17 Ctrl-C {kind} root-review 引用不符"));
    }
    let review = StrictJsonParser::parse(
        &fs::read_to_string(&root_review).map_err(|error| error.to_string())?,
    )?;
    object(&review, &[
        "schema", "status", "kind", "repository_root", "source_paths",
        "source_hashes", "terminal_records", "artifact_checks", "input_basis",
        "checks", "review_note",
    ])?;
    let hashes = field(&review, "source_hashes")?;
    object(hashes, &EXIT_CTRL_SOURCE_PATHS)?;
    if string(&review, "schema")? != "rivetlua-p17-ctrl-c-root-review-v1"
        || string(&review, "status")? != "PASS"
        || string(&review, "kind")? != kind
        || string(&review, "repository_root")? != original_root.display().to_string()
        || strings(&review, "source_paths")?
            != EXIT_CTRL_SOURCE_PATHS.iter().map(|path| (*path).to_owned()).collect::<Vec<_>>()
        || array(&review, "terminal_records")?.len() != 2
        || array(&review, "artifact_checks")?.is_empty()
        || array(&review, "input_basis")?.is_empty()
        || array(&review, "checks")?.is_empty()
        || string(&review, "review_note")?.trim().is_empty()
    {
        return Err(format!("P17 Ctrl-C {kind} root-review 主鍵不符"));
    }
    for (relative, digest) in EXIT_CTRL_SOURCE_PATHS.iter().zip(EXIT_CTRL_SOURCE_SHAS) {
        if string(hashes, relative)? != digest {
            return Err(format!("P17 Ctrl-C {kind} root source SHA 不符：{relative}"));
        }
    }
    let mut terminals = BTreeSet::new();
    for item in array(&review, "terminal_records")? {
        object(item, &["path", "sha256"])?;
        let path = Path::new(string(item, "path")?);
        let digest = string(item, "sha256")?;
        exit_digest(digest)?;
        if !path.starts_with(evidence.join(EXIT_CTRL_PROOF_DIR))
            || !terminals.insert(path.to_path_buf())
            || path == root_review || path == result
        {
            return Err(format!("P17 Ctrl-C {kind} terminal 來源不符"));
        }
        console_cli_public_file(path, &evidence.join(EXIT_CTRL_PROOF_DIR))?;
        sha(path, digest)?;
        let terminal = StrictJsonParser::parse(
            &fs::read_to_string(path).map_err(|error| error.to_string())?,
        )?;
        if !matches!(string(&terminal, "status")?, "PASS" | "COMPLETE") {
            return Err(format!("P17 Ctrl-C {kind} terminal 未完成"));
        }
    }
    let readiness_value = StrictJsonParser::parse(
        &fs::read_to_string(&readiness).map_err(|error| error.to_string())?,
    )?;
    let environment = StrictJsonParser::parse(&canonical_json(
        field(field(&readiness_value, "phase_launch")?, "required_environment")?,
    ))?;
    Ok(CtrlLeaf { directory, proof, environment })
}

fn exit_ctrl_c_leaf_sources(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    row: &StrictJsonValue,
) -> Result<(), String> {
    exit_ctrl_c_leaf_sources_with_verified(
        original_root, current_root, evidence, row, None)
}

fn exit_ctrl_c_leaf_sources_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    row: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let inputs = array(row, "source_inputs")?;
    if inputs.len() != EXIT_CTRL_SOURCE_PATHS.len() {
        return Err("P17 Ctrl-C proof 11-source 數量不符".into());
    }
    for ((source, relative), digest) in inputs.iter()
        .zip(EXIT_CTRL_SOURCE_PATHS).zip(EXIT_CTRL_SOURCE_SHAS)
    {
        object(source, &["path", "sha256", "snapshot_path"])?;
        let snapshot = Path::new(string(source, "snapshot_path")?);
        if string(source, "path")? != original_root.join(relative).display().to_string()
            || string(source, "sha256")? != digest
        {
            return Err(format!("P17 Ctrl-C proof source 順序／SHA 不符：{relative}"));
        }
        console_cli_public_file(snapshot, &evidence.join(EXIT_CTRL_PROOF_DIR))?;
        sha(snapshot, digest)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 Ctrl-C proof source snapshot 非 0444".into());
        }
        if ((relative == GC_BASIC_PATH && digest == GC_BASIC_BEFORE_SHA)
            || (relative == GC_HEAP_PATH && digest == GC_HEAP_BEFORE_SHA))
            && evidence.join(GC_REVIEW_FILE).exists()
        {
            sha(&gc_before_source_with_verified(
                current_root, evidence, relative, verified)?, digest)?;
        } else if verified.is_some_and(|context| context.repair_active)
            && FINAL_REPAIR_PRODUCT_CHANGES.iter().any(|(path, before, _)|
                *path == relative && *before == digest)
        {
            final_source_relocated_source_with_verified(
                original_root, current_root, evidence,
                &original_root.join(relative).display().to_string(), digest,
                verified,
            ).map_err(|error| format!("P17 Ctrl-C proof final historical source {relative}/{digest}: {error}"))?;
        } else {
            debug_vm_relocated_source_with_verified(
                original_root, current_root, evidence,
                &original_root.join(relative).display().to_string(), digest,
                verified,
            ).map_err(|error| format!("P17 Ctrl-C proof historical source {relative}/{digest}: {error}"))?;
        }
    }
    Ok(())
}

fn exit_ctrl_c_row_shape(row: &StrictJsonValue, kind: &str) -> Result<(), String> {
    let mut keys = vec![
        "profile", "command", "cwd", "environment_mode", "environment",
        "exit_code", "matched", "passed", "failed", "ignored", "filtered",
        "log_path", "log_sha256", "running_binary_path", "snapshot_path",
        "snapshot_sha256", "source_inputs",
    ];
    if kind == "public" {
        keys.extend(["cli_running_binary_path", "cli_snapshot_path", "cli_snapshot_sha256"]);
    } else {
        keys.push("case");
    }
    object(row, &keys)?;
    Ok(())
}

fn exit_ctrl_c_row_counts(
    row: &StrictJsonValue,
    matched: u64,
    public: bool,
) -> Result<(), String> {
    if integer(row, "exit_code")? != 0
        || integer(row, "matched")? != matched
        || integer(row, "passed")? != matched
        || integer(row, "failed")? != 0
        || integer(row, "ignored")? != 0
        || (public && integer(row, "filtered")? != 0)
    {
        return Err("P17 Ctrl-C proof 實際測試 count 不符".into());
    }
    Ok(())
}

fn exit_ctrl_c_driver_identity(
    row: &StrictJsonValue,
    target: &Path,
    evidence: &Path,
    prefix: &str,
) -> Result<(), String> {
    let running = Path::new(string(row, "running_binary_path")?);
    let driver_sha = string(row, "snapshot_sha256")?;
    exit_digest(driver_sha)?;
    let snapshot = Path::new(string(row, "snapshot_path")?);
    if running.parent() != Some(target.join("debug/deps").as_path())
        || !running.file_name().and_then(|name| name.to_str())
            .is_some_and(|name| name.starts_with(prefix))
    {
        return Err("P17 Ctrl-C driver 身分不符".into());
    }
    console_cli_public_file(snapshot, &evidence.join(EXIT_CTRL_PROOF_DIR))?;
    sha(snapshot, driver_sha)?;
    if fs::metadata(snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o555
    {
        return Err("P17 Ctrl-C driver snapshot 非 0555".into());
    }
    report::mach_type(snapshot, "EXECUTE")
}

fn exit_ctrl_c_leaf(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    kind: &str,
) -> Result<(), String> {
    exit_ctrl_c_leaf_with_verified(
        original_root, current_root, evidence, update, kind, None)
}

fn exit_ctrl_c_leaf_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    kind: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let leaf = exit_ctrl_c_leaf_header(original_root, evidence, update, kind)?;
    exit_safe_cargo(evidence)?;
    let target = Path::new(string(&leaf.environment, "CARGO_TARGET_DIR")?);
    for (index, row) in array(&leaf.proof, "rows")?.iter().enumerate() {
        exit_ctrl_c_row_shape(row, kind)?;
        let (profile, case, tag, selector, fullname, matched, driver, public) = match (kind, index) {
            ("public", 0) => ("lua55", None, "lua55", "", "", 3, "p17_ctrl_c-", true),
            ("public", 1) => ("lua54", None, "lua54", "", "", 3, "p17_ctrl_c-", true),
            ("private-vm", 0) => (
                "lua54-and-lua55", Some("basic"), "basic",
                "p17_interrupt_basic_typed_message_and_allocation_cleanup",
                "vm::tests::p17_interrupt_basic_typed_message_and_allocation_cleanup",
                1, "rivetlua_runtime-", false,
            ),
            ("private-vm", 1) => (
                "lua54-and-lua55", Some("pcall-gc"), "pcall-gc",
                "p17_interrupt_complete_pcall_close_and_gc_roots",
                "vm::tests::p17_interrupt_complete_pcall_close_and_gc_roots",
                1, "rivetlua_runtime-", false,
            ),
            ("private-cli", 0) => (
                "lua55", Some("epoch"), "lua55",
                "p17_standalone_signal_epoch_preserves_second_interrupt",
                "cli_unit_tests::p17_standalone_signal_epoch_preserves_second_interrupt",
                1, "rivetlua_cli-", false,
            ),
            ("private-cli", 1) => (
                "lua54", Some("epoch"), "lua54",
                "p17_standalone_signal_epoch_preserves_second_interrupt",
                "cli_unit_tests::p17_standalone_signal_epoch_preserves_second_interrupt",
                1, "rivetlua_cli-", false,
            ),
            _ => return Err("P17 Ctrl-C proof row 類別／順序不符".into()),
        };
        let features = if profile == "lua55" { "native-lua55" } else { "native-lua54,default-lua54" };
        let mut command = vec![EXIT_SAFE_CARGO, "test", "--locked", "-p"];
        match kind {
            "public" => command.extend([
                "rivetlua-cli", "--features", features, "--test", "p17_ctrl_c",
            ]),
            "private-vm" => command.extend([
                "rivetlua-runtime", "--lib", selector, "--", "--nocapture", "--test-threads=1",
            ]),
            "private-cli" => command.extend([
                "rivetlua-cli", "--features", features, "--lib", selector,
                "--", "--nocapture", "--test-threads=1",
            ]),
            _ => return Err("P17 Ctrl-C proof 未知類別".into()),
        }
        if string(row, "profile")? != profile
            || case.is_some_and(|expected| string(row, "case").ok() != Some(expected))
            || strings(row, "command")?
                != command.into_iter().map(str::to_owned).collect::<Vec<_>>()
            || string(row, "cwd")? != original_root.display().to_string()
            || string(row, "environment_mode")? != "env -i"
            || canonical_json(field(row, "environment")?) != canonical_json(&leaf.environment)
            || exit_ctrl_c_row_counts(row, matched, public).is_err()
        {
            return Err(format!("P17 Ctrl-C {kind}/{tag} 命令／count 不符"));
        }
        let log = leaf.directory.join(format!(
            "green-{}{}.log", profile,
            case.map_or(String::new(), |value| format!("-{value}")),
        ));
        if string(row, "log_path")? != log.display().to_string() {
            return Err(format!("P17 Ctrl-C {kind}/{tag} log 路徑不符"));
        }
        console_cli_public_file(&log, &leaf.directory)?;
        sha(&log, string(row, "log_sha256")?)?;
        let running = Path::new(string(row, "running_binary_path")?);
        exit_ctrl_c_driver_identity(row, target, evidence, driver)?;
        let names: Vec<&str> = if public {
            vec![
                "p17_ctrl_c_protected_loop_recovers_after_first_signal",
                "p17_ctrl_c_unprotected_loop_reports_interrupt",
                "p17_ctrl_c_native_pattern_exits_after_second_signal",
            ]
        } else {
            vec![fullname]
        };
        let body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(&body, &names, !public)?;
        let runner = if public { "tests/p17_ctrl_c.rs" } else { "unittests src/lib.rs" };
        if counts.matched != matched as u32
            || counts.passed != matched as u32
            || counts.failed != 0 || counts.ignored != 0
            || !body.contains(&format!("0 measured; {} filtered out;", integer(row, "filtered")?))
            || !body.contains(&format!("Running {runner} ({})", running.display()))
        {
            return Err(format!("P17 Ctrl-C {kind}/{tag} 具名 log／driver 不符"));
        }
        if public {
            let cli_running = Path::new(string(row, "cli_running_binary_path")?);
            let cli_sha = string(row, "cli_snapshot_sha256")?;
            exit_digest(cli_sha)?;
            let cli_snapshot = Path::new(string(row, "cli_snapshot_path")?);
            if cli_running != target.join("debug/rivetlua")
            {
                return Err("P17 Ctrl-C public CLI product binary 身分不符".into());
            }
            console_cli_public_file(cli_snapshot, &evidence.join(EXIT_CTRL_PROOF_DIR))?;
            sha(cli_snapshot, cli_sha)?;
            if fs::metadata(cli_snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o555
            {
                return Err("P17 Ctrl-C public CLI product binary 非 0555".into());
            }
            report::mach_type(cli_snapshot, "EXECUTE")?;
        }
        exit_ctrl_c_leaf_sources_with_verified(
            original_root, current_root, evidence, row, verified,
        )?;
    }
    Ok(())
}

fn exit_warn_argument_reuse_review(
    original_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
) -> Result<(), String> {
    let path = evidence.join(EXIT_WARN_PROOF_DIR).join("reuse-review.json");
    if string(update, "reuse_review_path")? != path.display().to_string()
        || string(update, "reuse_review_sha256")?
            != "c110517790d5efb0950ff7dadac76fee07641b2b74507705e315a3493cd304ee"
    {
        return Err("P17 warn argument reuse 證據身分不符".into());
    }
    console_cli_public_file(&path, &evidence.join(EXIT_WARN_PROOF_DIR))?;
    sha(&path, string(update, "reuse_review_sha256")?)?;
    let review = StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    object(&review, &[
        "schema", "status", "repository_root", "old_exit_review_sha256",
        "old_host_review_sha256", "before_sources", "after_sources", "new_test_path",
        "new_test_sha256", "historical_vm_basic_endpoints", "required_new_validation",
        "review_note",
    ])?;
    if string(&review, "schema")? != "rivetlua-p17-warn-argument-reuse-v1"
        || string(&review, "status")? != "PASS"
        || string(&review, "repository_root")? != original_root.display().to_string()
        || string(&review, "old_exit_review_sha256")?
            != "184e6aa464a2f211439e2730337ebbdb65334820376df625a99de22787ef5cdb"
        || string(&review, "old_host_review_sha256")?
            != "5d00f061e554795628541bb34d923eb02e8c65928f33fd1ce6db9e1fa805724b"
        || string(&review, "new_test_path")? != EXIT_WARN_TEST_PATH
        || string(&review, "new_test_sha256")? != EXIT_WARN_TEST_SHA
        || strings(&review, "required_new_validation")? != [
            "warn-argument-public-lua55", "warn-argument-public-lua54",
            "warn-argument-private-lua55", "warn-argument-private-lua54",
            "P17-final-phase-state",
        ]
        || !string(&review, "review_note")?.contains("Gate22")
        || !string(&review, "review_note")?.contains("不將它們改標新來源PASS")
    {
        return Err("P17 warn argument reuse 主鍵／沿用範圍不符".into());
    }
    let before = array(&review, "before_sources")?;
    let after = array(&review, "after_sources")?;
    let historical = array(&review, "historical_vm_basic_endpoints")?;
    if before.len() != 2 || after.len() != 2 || historical.len() != 2 {
        return Err("P17 warn argument reuse source 數量不符".into());
    }
    for (index, (relative, old, new, filename)) in [
        (EXIT_WARN_VM_PATH, EXIT_WARN_VM_BEFORE_SHA, EXIT_WARN_VM_AFTER_SHA,
            "before-crates__rivetlua-runtime__src__vm__mod.rs"),
        (EXIT_WARN_BASIC_PATH, EXIT_WARN_BASIC_BEFORE_SHA, EXIT_WARN_BASIC_AFTER_SHA,
            "before-crates__rivetlua-runtime__src__stdlib__basic.rs"),
    ].into_iter().enumerate() {
        object(&before[index], &["path", "sha256"])?;
        object(&after[index], &["path", "sha256"])?;
        object(&historical[index], &["path", "before_sha256", "before_snapshot_path"])?;
        let snapshot = evidence.join(EXIT_WARN_SOURCE_DIR).join(filename);
        if string(&before[index], "path")? != relative
            || string(&before[index], "sha256")? != old
            || string(&after[index], "path")? != relative
            || string(&after[index], "sha256")? != new
            || string(&historical[index], "path")? != relative
            || string(&historical[index], "before_sha256")? != old
            || string(&historical[index], "before_snapshot_path")? != snapshot.display().to_string()
        {
            return Err("P17 warn argument reuse 兩源歷史 endpoint 不符".into());
        }
        sha(&snapshot, old)?;
    }
    Ok(())
}

fn exit_warn_argument_update(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    ctrl_c_updated: bool,
) -> Result<(), String> {
    exit_warn_argument_update_with_verified(
        original_root, current_root, evidence, update, ctrl_c_updated, None)
}

fn exit_warn_argument_update_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    ctrl_c_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    exit_warn_argument_update_shape(update)?;
    let source_dir = evidence.join(EXIT_WARN_SOURCE_DIR);
    for (change, (relative, old, new, filename, diff_sha)) in array(update, "changes")?.iter().zip([
        (EXIT_WARN_VM_PATH, EXIT_WARN_VM_BEFORE_SHA, EXIT_WARN_VM_AFTER_SHA,
            "crates__rivetlua-runtime__src__vm__mod.rs", EXIT_WARN_VM_DIFF_SHA),
        (EXIT_WARN_BASIC_PATH, EXIT_WARN_BASIC_BEFORE_SHA, EXIT_WARN_BASIC_AFTER_SHA,
            "crates__rivetlua-runtime__src__stdlib__basic.rs", EXIT_WARN_BASIC_DIFF_SHA),
    ]) {
        let before = source_dir.join(format!("before-{filename}"));
        let after = source_dir.join(format!("after-{filename}"));
        let diff = evidence.join(format!("p17-phase-warn-argument-impact-{filename}.diff"));
        if string(change, "before_snapshot_path")? != before.display().to_string()
            || string(change, "after_snapshot_path")? != after.display().to_string()
            || string(change, "diff_path")? != diff.display().to_string()
            || string(change, "diff_sha256")? != diff_sha
        {
            return Err(format!("P17 warn argument 固定兩源證據路徑不符：{relative}"));
        }
        for (path, digest) in [(&before, old), (&after, new)] {
            console_cli_public_file(path, &source_dir)?;
            sha(path, digest)?;
            if fs::metadata(path).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
                return Err("P17 warn argument source 快照權限不符".into());
            }
        }
        let current = if ctrl_c_updated && relative == EXIT_WARN_VM_PATH {
            exit_ctrl_c_before_source_with_verified(
                current_root, evidence, relative, verified)?
        } else if relative == GC_BASIC_PATH && evidence.join(GC_REVIEW_FILE).exists() {
            gc_before_source_with_verified(current_root, evidence, relative, verified)?
        } else {
            current_root.join(relative)
        };
        sha(&current, new)?;
        let projected = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"before_sha256\":{},\"after_sha256\":{},\"diff_path\":{},\"diff_sha256\":{}}}",
            report::q(string(change, "path")?),
            report::q(string(change, "before_sha256")?),
            report::q(string(change, "after_sha256")?),
            report::q(string(change, "diff_path")?),
            report::q(string(change, "diff_sha256")?),
        ))?;
        console_change_identity(&projected, relative, Some(old), new, &diff)?;
        sha(&diff, diff_sha)?;
        let output = verified_review_git(current_root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(&before)
            .arg(&current)
            .output()
            .map_err(|error| error.to_string())?;
        let stored = fs::read(&diff).map_err(|error| error.to_string())?;
        if output.status.code() != Some(1)
            || !output.stderr.is_empty()
            || !console_old_diff_matches(&output.stdout, &stored, &before, &after, &current)?
        {
            return Err(format!("P17 warn argument raw diff 不符：{relative}"));
        }
    }
    sha(&current_root.join(EXIT_WARN_TEST_PATH), EXIT_WARN_TEST_SHA)?;
    let primary = source_dir.join("primary-source-review.json");
    console_cli_public_file(&primary, &source_dir)?;
    sha(&primary, "591e43a790dacf0e97a361c740d398c8138ddaa991bac8406711c8a1b1a6081f")?;
    exit_warn_argument_public_leaf_with_verified(
        original_root, current_root, evidence, update, verified)?;
    exit_warn_argument_private_leaf_with_verified(
        original_root, current_root, evidence, update, verified)?;
    exit_warn_argument_reuse_review(original_root, evidence, update)?;
    Ok(())
}

fn exit_warn_argument_root_review(
    review: &StrictJsonValue,
    original_root: &Path,
    evidence: &Path,
    kind: &str,
    source_paths: &[&str],
) -> Result<(), String> {
    object(review, &[
        "schema", "status", "kind", "repository_root", "vm_sha256", "basic_sha256",
        "source_paths", "terminal_records", "artifact_checks", "input_basis", "checks", "review_note",
    ])?;
    if string(review, "schema")? != "rivetlua-p17-warn-argument-root-review-v1"
        || string(review, "status")? != "PASS"
        || string(review, "kind")? != kind
        || string(review, "repository_root")? != original_root.display().to_string()
        || string(review, "vm_sha256")? != EXIT_WARN_VM_AFTER_SHA
        || string(review, "basic_sha256")? != EXIT_WARN_BASIC_AFTER_SHA
        || strings(review, "source_paths")? != source_paths.iter().map(|p| (*p).to_owned()).collect::<Vec<_>>()
        || array(review, "artifact_checks")?.is_empty()
        || array(review, "input_basis")?.is_empty()
        || array(review, "checks")?.is_empty()
        || string(review, "review_note")?.trim().is_empty()
    {
        return Err(format!("P17 warn argument {kind} root-review 主鍵不符"));
    }
    let proof_dir = evidence.join(EXIT_WARN_PROOF_DIR);
    let runtime = if kind == "public" {
        proof_dir.join("public-runtime")
    } else {
        proof_dir.join("private-runtime/lib-only")
    };
    let expected = if kind == "public" {
        [runtime.join("actor-result-final.json"), runtime.join("terminal-completion.json")]
    } else {
        [runtime.join("actor-result.json"), runtime.join("terminal-completion.json")]
    };
    let records = array(review, "terminal_records")?;
    if records.len() != 2 { return Err("P17 warn argument terminal 數量不符".into()); }
    let mut seen = BTreeSet::new();
    for record in records {
        object(record, &["path", "sha256"])?;
        let path = Path::new(string(record, "path")?);
        let digest = string(record, "sha256")?;
        exit_digest(digest)?;
        if !expected.iter().any(|fixed| fixed == path) || !seen.insert(path.to_path_buf()) {
            return Err("P17 warn argument terminal 路徑不符".into());
        }
        console_cli_public_file(path, &runtime)?;
        sha(path, digest)?;
        let value = StrictJsonParser::parse(&fs::read_to_string(path).map_err(|error| error.to_string())?)?;
        let accepted = if path.file_name().is_some_and(|name| name == "terminal-completion.json") {
            "COMPLETE"
        } else {
            "PASS"
        };
        if string(&value, "status")? != accepted {
            return Err("P17 warn argument terminal 完成狀態不符".into());
        }
    }
    Ok(())
}

fn exit_warn_argument_leaf_header(
    evidence: &Path,
    update: &StrictJsonValue,
    kind: &str,
) -> Result<(PathBuf, StrictJsonValue, StrictJsonValue), String> {
    let proof_dir = evidence.join(EXIT_WARN_PROOF_DIR).join(kind);
    let result = proof_dir.join("result.json");
    let path_key = format!("{kind}_proof_path");
    let sha_key = format!("{kind}_proof_sha256");
    let fixed_sha = if kind == "public" {
        "ce8f99b617d4201b04c9caa4622cd9fd2bd6ed632c918b963fdafbeb10f0aa08"
    } else {
        "cb486e65d965b52e063ead0f1601732030eb7e7f69b06b26fcc1e218f4100f00"
    };
    if string(update, &path_key)? != result.display().to_string() {
        return Err(format!("P17 warn argument {kind} proof 路徑不符"));
    }
    if string(update, &sha_key)? != fixed_sha {
        return Err(format!("P17 warn argument {kind} proof SHA 不符"));
    }
    console_cli_public_file(&result, &proof_dir)?;
    sha(&result, string(update, &sha_key)?)?;
    let proof = StrictJsonParser::parse(&fs::read_to_string(&result).map_err(|error| error.to_string())?)?;
    object(&proof, &["status", "reported_by", "root_review", "readiness_path", "readiness_sha256", "rows"])?;
    let producer = if kind == "public" {
        "/root/p17_binary_prefix_verify"
    } else {
        "/root/p17_warn_argument_core"
    };
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    sha(&readiness, "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb")?;
    if string(&proof, "status")? != "PASS"
        || string(&proof, "reported_by")? != producer
        || string(&proof, "readiness_path")? != readiness.display().to_string()
        || string(&proof, "readiness_sha256")? != "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb"
        || array(&proof, "rows")?.len() != 2
    {
        return Err(format!("P17 warn argument {kind} proof 主鍵不符"));
    }
    let root_review = proof_dir.join("root-review.json");
    console_cli_public_file(&root_review, &proof_dir)?;
    sha(&root_review, if kind == "public" {
        "43fab432fac3b55b6e58966e135eb2bb1f56273129c69f955d9b09c5cbbeb9f3"
    } else {
        "34943ba8daade1591ba554c25956c34e73ca02be982f8bc74d81080987d36219"
    })?;
    let root_sha = manifest::sha256(&root_review)?;
    let claim = string(&proof, "root_review")?;
    if !claim.contains(&root_review.display().to_string()) || !claim.contains(&root_sha) {
        return Err("P17 warn argument root-review 引用不符".into());
    }
    let review = StrictJsonParser::parse(&fs::read_to_string(&root_review).map_err(|error| error.to_string())?)?;
    let readiness_value = StrictJsonParser::parse(&fs::read_to_string(&readiness).map_err(|error| error.to_string())?)?;
    Ok((proof_dir, proof, StrictJsonParser::parse(&format!(
        "{{\"review\":{},\"environment\":{}}}",
        canonical_json(&review), canonical_json(field(field(&readiness_value, "phase_launch")?, "required_environment")?),
    ))?))
}

fn exit_warn_argument_leaf_sources(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    proof_dir: &Path,
    row: &StrictJsonValue,
    paths: &[&str],
    digests: &[&str],
) -> Result<(), String> {
    exit_warn_argument_leaf_sources_with_verified(
        original_root, current_root, evidence, proof_dir, row, paths, digests, None)
}

fn exit_warn_argument_leaf_sources_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    proof_dir: &Path,
    row: &StrictJsonValue,
    paths: &[&str],
    digests: &[&str],
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let sources = array(row, "source_inputs")?;
    if sources.len() != paths.len() || paths.len() != digests.len() {
        return Err("P17 warn argument leaf source 數量不符".into());
    }
    for (index, ((source, relative), digest)) in sources.iter().zip(paths).zip(digests).enumerate() {
        object(source, &["path", "sha256", "snapshot_path"])?;
        let snapshot = proof_dir.join(format!(
            "{index}-{}", Path::new(relative).file_name().ok_or("P17 warn argument source 檔名缺失")?.to_string_lossy(),
        ));
        if string(source, "path")? != original_root.join(relative).display().to_string()
            || string(source, "sha256")? != *digest
            || string(source, "snapshot_path")? != snapshot.display().to_string()
        {
            return Err(format!("P17 warn argument leaf source 順序／SHA 不符：{relative}"));
        }
        console_cli_public_file(&snapshot, proof_dir)?;
        sha(&snapshot, digest)?;
        if fs::metadata(&snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
            return Err("P17 warn argument leaf source snapshot 非 0444".into());
        }
        exit_warn_historical_source_with_verified(
            original_root, current_root, evidence, relative, digest, Some(&snapshot),
            verified,
        )?;
    }
    Ok(())
}

fn exit_warn_argument_row_counts(row: &StrictJsonValue, matched: u64, filtered: u64) -> Result<(), String> {
    if integer(row, "exit_code")? != 0
        || integer(row, "matched")? != matched || integer(row, "passed")? != matched
        || integer(row, "failed")? != 0 || integer(row, "ignored")? != 0
        || integer(row, "filtered")? != filtered
    {
        return Err("P17 warn argument leaf 實際測試 count 不符".into());
    }
    Ok(())
}

fn exit_warn_argument_private_leaf(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
) -> Result<(), String> {
    exit_warn_argument_private_leaf_with_verified(
        original_root, current_root, evidence, update, None)
}

fn exit_warn_argument_private_leaf_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let (proof_dir, proof, context) = exit_warn_argument_leaf_header(evidence, update, "private")?;
    let paths = [EXIT_WARN_VM_PATH, EXIT_WARN_BASIC_PATH];
    let digests = [EXIT_WARN_VM_AFTER_SHA, EXIT_WARN_BASIC_AFTER_SHA];
    exit_warn_argument_root_review(field(&context, "review")?, original_root, evidence, "private", &paths)?;
    let environment = field(&context, "environment")?;
    let target = Path::new(string(environment, "CARGO_TARGET_DIR")?);
    exit_safe_cargo(evidence)?;
    for (row, (case, selector, fullname)) in array(&proof, "rows")?.iter().zip([
        ("basic", "p17_warn_argument_keeps_typed_error_and_releases_message_root",
            "stdlib::basic::p13_a_tests::p17_warn_argument_keeps_typed_error_and_releases_message_root"),
        ("pcall-gc", "p17_warn_argument_pcall_keeps_message_alive_until_result",
            "vm::tests::p17_warn_argument_pcall_keeps_message_alive_until_result"),
    ]) {
        object(row, &[
            "profile", "case", "command", "cwd", "environment_mode", "environment",
            "exit_code", "matched", "passed", "failed", "ignored", "filtered",
            "log_path", "log_sha256", "running_binary_path", "snapshot_path",
            "snapshot_sha256", "source_inputs",
        ])?;
        let command = [
            EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-runtime", "--lib",
            selector, "--", "--nocapture", "--test-threads=1",
        ];
        if string(row, "profile")? != "lua54-and-lua55"
            || string(row, "case")? != case
            || strings(row, "command")? != command.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>()
            || string(row, "cwd")? != original_root.display().to_string()
            || string(row, "environment_mode")? != "env -i"
            || canonical_json(field(row, "environment")?) != canonical_json(environment)
        {
            return Err(format!("P17 warn argument private {case} 命令／count 不符"));
        }
        exit_warn_argument_row_counts(row, 1, 323)?;
        let log = proof_dir.join(format!("green-{case}.log"));
        if string(row, "log_path")? != log.display().to_string() {
            return Err("P17 warn argument private log 路徑不符".into());
        }
        console_cli_public_file(&log, &proof_dir)?;
        sha(&log, string(row, "log_sha256")?)?;
        let running = Path::new(string(row, "running_binary_path")?);
        let driver_sha = string(row, "snapshot_sha256")?;
        exit_digest(driver_sha)?;
        let snapshot = proof_dir.join(format!("executed-{case}-{driver_sha}"));
        if running.parent() != Some(target.join("debug/deps").as_path())
            || !running.file_name().and_then(|name| name.to_str()).is_some_and(|name| name.starts_with("rivetlua_runtime-"))
            || string(row, "snapshot_path")? != snapshot.display().to_string()
        {
            return Err("P17 warn argument private driver 身分不符".into());
        }
        console_cli_public_file(&snapshot, &proof_dir)?;
        sha(&snapshot, driver_sha)?;
        if fs::metadata(&snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 warn argument private driver 非 0555".into());
        }
        report::mach_type(&snapshot, "EXECUTE")?;
        let body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(&body, &[fullname], true)?;
        if counts.matched != 1 || counts.passed != 1 || counts.failed != 0 || counts.ignored != 0
            || !body.contains("323 filtered out;")
            || !body.contains(&format!("Running unittests src/lib.rs ({})", running.display()))
        {
            return Err("P17 warn argument private log 結果／driver 不符".into());
        }
        exit_warn_argument_leaf_sources_with_verified(
            original_root, current_root, evidence, &proof_dir, row, &paths, &digests, verified)?;
    }
    Ok(())
}

fn exit_warn_argument_public_leaf(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
) -> Result<(), String> {
    exit_warn_argument_public_leaf_with_verified(
        original_root, current_root, evidence, update, None)
}

fn exit_warn_argument_public_leaf_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let (proof_dir, proof, context) = exit_warn_argument_leaf_header(evidence, update, "public")?;
    let paths = [
        EXIT_WARN_TEST_PATH, EXIT_CLI_BINARY_PATH, EXIT_WARN_VM_PATH, EXIT_WARN_BASIC_PATH,
        "crates/rivetlua/src/lib.rs", EXIT_PARSER_PATH, "crates/rivetlua-core/src/bytecode/input.rs",
    ];
    let digests = [
        EXIT_WARN_TEST_SHA, EXIT_CLI_DIAGNOSTICS_AFTER_SHA, EXIT_WARN_VM_AFTER_SHA,
        EXIT_WARN_BASIC_AFTER_SHA,
        "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
        EXIT_PARSER_AFTER_SHA,
        "1495457f26a517b8a89014b1b3bb227289605e01b325f8fcbada323dd95a3959",
    ];
    exit_warn_argument_root_review(field(&context, "review")?, original_root, evidence, "public", &paths)?;
    let environment = field(&context, "environment")?;
    let target = Path::new(string(environment, "CARGO_TARGET_DIR")?);
    exit_safe_cargo(evidence)?;
    let names = [
        "p17_warn_missing_argument_reports_string_expected",
        "p17_warn_invalid_argument_does_not_leak_pending_warning",
        "p17_warn_numeric_arguments_and_controls_remain_supported",
    ];
    for (row, profile) in array(&proof, "rows")?.iter().zip(["lua55", "lua54"]) {
        object(row, &[
            "profile", "command", "cwd", "environment_mode", "environment",
            "exit_code", "matched", "passed", "failed", "ignored", "filtered",
            "log_path", "log_sha256", "running_binary_path", "snapshot_path",
            "snapshot_sha256", "source_inputs", "cli_running_binary_path",
            "cli_snapshot_path", "cli_snapshot_sha256",
        ])?;
        let features = if profile == "lua55" { "native-lua55" } else { "native-lua54,default-lua54" };
        let command = [
            EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-cli", "--no-default-features",
            "--features", features, "--test", "p17_warn_arguments", "--", "--nocapture", "--test-threads=1",
        ];
        if string(row, "profile")? != profile
            || strings(row, "command")? != command.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>()
            || string(row, "cwd")? != original_root.display().to_string()
            || string(row, "environment_mode")? != "env -i"
            || canonical_json(field(row, "environment")?) != canonical_json(environment)
        {
            return Err(format!("P17 warn argument public {profile} 命令／count 不符"));
        }
        exit_warn_argument_row_counts(row, 3, 0)?;
        let log = proof_dir.join(format!("green-{profile}.log"));
        if string(row, "log_path")? != log.display().to_string() {
            return Err("P17 warn argument public log 路徑不符".into());
        }
        console_cli_public_file(&log, &proof_dir)?;
        sha(&log, string(row, "log_sha256")?)?;
        let running = Path::new(string(row, "running_binary_path")?);
        let driver_sha = string(row, "snapshot_sha256")?;
        exit_digest(driver_sha)?;
        let snapshot = proof_dir.join(format!("executed-{profile}-{driver_sha}"));
        if running.parent() != Some(target.join("debug/deps").as_path())
            || !running.file_name().and_then(|name| name.to_str()).is_some_and(|name| name.starts_with("p17_warn_arguments-"))
            || string(row, "snapshot_path")? != snapshot.display().to_string()
        {
            return Err("P17 warn argument public driver 身分不符".into());
        }
        console_cli_public_file(&snapshot, &proof_dir)?;
        sha(&snapshot, driver_sha)?;
        if fs::metadata(&snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 warn argument public driver 非 0555".into());
        }
        report::mach_type(&snapshot, "EXECUTE")?;
        let body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(&body, &names, false)?;
        if counts.matched != 3 || counts.passed != 3 || counts.failed != 0 || counts.ignored != 0
            || !body.contains(&format!("Running tests/p17_warn_arguments.rs ({})", running.display()))
        {
            return Err("P17 warn argument public log 結果／driver 不符".into());
        }
        let cli_running = Path::new(string(row, "cli_running_binary_path")?);
        let cli_sha = string(row, "cli_snapshot_sha256")?;
        exit_digest(cli_sha)?;
        let cli_snapshot = proof_dir.join(format!("cli-executed-{profile}-{cli_sha}"));
        if cli_running != target.join("debug/rivetlua")
            || string(row, "cli_snapshot_path")? != cli_snapshot.display().to_string()
        {
            return Err("P17 warn argument public product binary 身分不符".into());
        }
        console_cli_public_file(&cli_snapshot, &proof_dir)?;
        sha(&cli_snapshot, cli_sha)?;
        if fs::metadata(&cli_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 warn argument public product binary 非 0555".into());
        }
        report::mach_type(&cli_snapshot, "EXECUTE")?;
        exit_warn_argument_leaf_sources_with_verified(
            original_root, current_root, evidence, &proof_dir, row, &paths, &digests, verified)?;
    }
    Ok(())
}

fn exit_cli_binary_update_shape(update: &StrictJsonValue) -> Result<(), String> {
    object(update, &[
        "path", "before_sha256", "after_sha256", "before_snapshot_path",
        "after_snapshot_path", "diff_path", "diff_sha256", "test_path",
        "test_sha256", "unit_proof_path", "unit_proof_sha256",
        "public_proof_path", "public_proof_sha256", "reuse_review_path",
        "reuse_review_sha256",
    ])?;
    if string(update, "path")? != EXIT_CLI_BINARY_PATH
        || string(update, "before_sha256")? != EXIT_CLI_LIB_TEST_ONLY_SHA
        || string(update, "after_sha256")? != EXIT_CLI_BINARY_AFTER_SHA
        || string(update, "test_path")? != EXIT_CLI_BINARY_TEST_PATH
        || string(update, "test_sha256")? != EXIT_CLI_BINARY_TEST_SHA
    {
        return Err("P17 CLI binary prefix 來源 endpoint 不符".into());
    }
    for key in [
        "before_sha256", "after_sha256", "diff_sha256", "test_sha256",
        "unit_proof_sha256", "public_proof_sha256", "reuse_review_sha256",
    ] {
        exit_digest(string(update, key)?)?;
    }
    for key in [
        "before_snapshot_path", "after_snapshot_path", "diff_path",
        "unit_proof_path", "public_proof_path", "reuse_review_path",
    ] {
        let path = Path::new(string(update, key)?);
        if !path.is_absolute()
            || path
                .components()
                .any(|part| !matches!(part, Component::RootDir | Component::Normal(_)))
        {
            return Err(format!("P17 CLI binary prefix {key} 非正規絕對路徑"));
        }
    }
    Ok(())
}

