fn exit_cli_diagnostics_reuse_review_shape(
    review: &StrictJsonValue,
    before: &Path,
    after: &Path,
) -> Result<(), String> {
    object(review, &[
        "schema", "path", "before_sha256", "after_sha256", "before_snapshot_path",
        "after_snapshot_path", "test_path", "test_sha256", "historical_cli_shas",
        "reuse_basis", "required_new_validation", "review_note",
    ])?;
    if string(review, "schema")? != "rivetlua-p17-cli-diagnostics-reuse-v1"
        || string(review, "path")? != EXIT_CLI_BINARY_PATH
        || string(review, "before_sha256")? != EXIT_CLI_VERSION_AFTER_SHA
        || string(review, "after_sha256")? != EXIT_CLI_DIAGNOSTICS_AFTER_SHA
        || string(review, "before_snapshot_path")? != before.display().to_string()
        || string(review, "after_snapshot_path")? != after.display().to_string()
        || string(review, "test_path")? != EXIT_CLI_DIAGNOSTICS_TEST_PATH
        || string(review, "test_sha256")? != EXIT_CLI_DIAGNOSTICS_TEST_SHA
        || strings(review, "historical_cli_shas")? != [
            EXIT_CLI_LIB_SHA, EXIT_CLI_LIB_TEST_ONLY_SHA,
            EXIT_CLI_BINARY_AFTER_SHA, EXIT_CLI_VERSION_AFTER_SHA,
        ]
        || strings(review, "required_new_validation")? != [
            "cli-diagnostics-public-lua55", "cli-diagnostics-public-lua54",
            "cli-diagnostics-unit-lua55", "cli-diagnostics-unit-lua54",
            "P17-final-phase-state",
        ]
        || string(review, "review_note")?.trim().is_empty()
    {
        return Err("P17 CLI diagnostics reuse review 主鍵不符".into());
    }
    let bases = array(review, "reuse_basis")?;
    if bases.is_empty() {
        return Err("P17 CLI diagnostics reuse basis 缺失".into());
    }
    for basis in bases {
        object(basis, &["scope", "basis"])?;
        if string(basis, "scope")?.trim().is_empty() || string(basis, "basis")?.trim().is_empty() {
            return Err("P17 CLI diagnostics reuse basis 空白".into());
        }
    }
    Ok(())
}

