fn exit_cli_version_root_review_shape(
    review: &StrictJsonValue,
    original_root: &Path,
    evidence: &Path,
    after_sha: &str,
    source_paths: &[&str],
) -> Result<(), String> {
    object(review, &[
        "schema", "status", "kind", "repository_root", "cli_sha256",
        "source_paths", "terminal_records", "artifact_checks", "input_basis",
        "checks", "review_note",
    ])?;
    if string(review, "schema")? != "rivetlua-p17-cli-version-banner-root-review-v1"
        || string(review, "status")? != "PASS"
        || string(review, "kind")? != "public"
        || string(review, "repository_root")? != original_root.display().to_string()
        || string(review, "cli_sha256")? != after_sha
        || strings(review, "source_paths")?
            != source_paths.iter().map(|path| (*path).to_owned()).collect::<Vec<_>>()
        || string(review, "review_note")?.trim().is_empty()
    {
        return Err("P17 CLI version banner root-review 主鍵不符".into());
    }
    let terminals = array(review, "terminal_records")?;
    if terminals.is_empty()
        || array(review, "artifact_checks")?.is_empty()
        || array(review, "input_basis")?.is_empty()
        || array(review, "checks")?.is_empty()
    {
        return Err("P17 CLI version banner root-review 實證紀錄缺失".into());
    }
    let fixed_terminal = evidence.join(EXIT_CLI_VERSION_PROOF_DIR).join("terminal-completion.json");
    let mut seen_fixed_terminal = false;
    for item in terminals {
        object(item, &["path", "sha256"])?;
        let path = Path::new(string(item, "path")?);
        let digest = string(item, "sha256")?;
        exit_digest(digest)?;
        console_cli_public_file(path, evidence)?;
        sha(path, digest)?;
        if path == fixed_terminal {
            if seen_fixed_terminal {
                return Err("P17 CLI version banner terminal attestation 重複".into());
            }
            seen_fixed_terminal = true;
        }
    }
    if !seen_fixed_terminal {
        return Err("P17 CLI version banner terminal attestation 缺失".into());
    }
    Ok(())
}

fn exit_cli_version_leaf_shape(proof: &StrictJsonValue, readiness: &Path) -> Result<(), String> {
    object(proof, &["status", "reported_by", "root_review", "readiness_path", "readiness_sha256", "rows"])?;
    if string(proof, "status")? != "PASS"
        || string(proof, "reported_by")? != "primary root"
        || string(proof, "root_review")?.is_empty()
        || string(proof, "readiness_path")? != readiness.display().to_string()
        || string(proof, "readiness_sha256")? != "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb"
        || array(proof, "rows")?.len() != 2
    {
        return Err("P17 CLI version banner proof 主鍵／row 數不符".into());
    }
    for row in array(proof, "rows")? {
        object(row, &[
            "profile", "command", "cwd", "environment_mode", "environment",
            "exit_code", "matched", "passed", "failed", "ignored", "filtered",
            "log_path", "log_sha256", "running_binary_path", "snapshot_path",
            "snapshot_sha256", "source_inputs", "cli_running_binary_path",
            "cli_snapshot_path", "cli_snapshot_sha256",
        ])?;
    }
    Ok(())
}

fn exit_cli_version_row_identity(
    row: &StrictJsonValue,
    profile: &str,
    original_root: &Path,
    environment: &StrictJsonValue,
) -> Result<(), String> {
    if !["lua55", "lua54"].contains(&profile) {
        return Err("P17 CLI version banner 未知 profile".into());
    }
    let features = if profile == "lua55" { "native-lua55" } else { "native-lua54,default-lua54" };
    let command = [
        EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-cli", "--no-default-features",
        "--features", features, "--test", "p17_version_banner", "--", "--nocapture", "--test-threads=1",
    ];
    if string(row, "profile")? != profile
        || strings(row, "command")? != command.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>()
        || string(row, "cwd")? != original_root.display().to_string()
        || string(row, "environment_mode")? != "env -i"
        || canonical_json(field(row, "environment")?) != canonical_json(environment)
        || integer(row, "exit_code")? != 0
        || integer(row, "matched")? != 3
        || integer(row, "passed")? != 3
        || integer(row, "failed")? != 0
        || integer(row, "ignored")? != 0
        || integer(row, "filtered")? != 0
    {
        return Err(format!("P17 CLI version banner {profile} 命令／count 不符"));
    }
    Ok(())
}

fn exit_cli_version_public_leaf(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_diagnostics_updated: bool,
) -> Result<(), String> {
    exit_cli_version_public_leaf_with_verified(
        original_root, current_root, evidence, update, cli_diagnostics_updated, None)
}

fn exit_cli_version_public_leaf_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_diagnostics_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let proof_dir = evidence.join(EXIT_CLI_VERSION_PROOF_DIR).join("public");
    let result = proof_dir.join("result.json");
    if string(update, "public_proof_path")? != result.display().to_string() {
        return Err("P17 CLI version banner proof 路徑不符".into());
    }
    console_cli_public_file(&result, &proof_dir)?;
    sha(&result, string(update, "public_proof_sha256")?)?;
    let proof = StrictJsonParser::parse(&fs::read_to_string(&result).map_err(|error| error.to_string())?)?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    sha(&readiness, "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb")?;
    exit_cli_version_leaf_shape(&proof, &readiness)?;
    let root_review = proof_dir.join("root-review.json");
    console_cli_public_file(&root_review, &proof_dir)?;
    let root_sha = manifest::sha256(&root_review)?;
    let claim = string(&proof, "root_review")?;
    if !claim.contains(&root_review.display().to_string()) || !claim.contains(&root_sha) {
        return Err("P17 CLI version banner root-review 引用不符".into());
    }
    let readiness_value = StrictJsonParser::parse(
        &fs::read_to_string(&readiness).map_err(|error| error.to_string())?,
    )?;
    let environment = field(field(&readiness_value, "phase_launch")?, "required_environment")?;
    exit_safe_cargo(evidence)?;
    let source_paths = [
        EXIT_CLI_VERSION_TEST_PATH,
        EXIT_CLI_BINARY_PATH,
        "crates/rivetlua-runtime/src/vm/mod.rs",
        "crates/rivetlua/src/lib.rs",
        EXIT_PARSER_PATH,
        "crates/rivetlua-core/src/bytecode/input.rs",
    ];
    let source_digests = [
        EXIT_CLI_VERSION_TEST_SHA,
        string(update, "after_sha256")?,
        "fcf16b4b24c26aef22da6d653b1b19a5412fbeb852ec25b850b19edaba33c088",
        "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
        EXIT_PARSER_AFTER_SHA,
        "1495457f26a517b8a89014b1b3bb227289605e01b325f8fcbada323dd95a3959",
    ];
    let root_value = StrictJsonParser::parse(
        &fs::read_to_string(&root_review).map_err(|error| error.to_string())?,
    )?;
    exit_cli_version_root_review_shape(
        &root_value, original_root, evidence, string(update, "after_sha256")?, &source_paths,
    )?;
    let names = [
        "p17_version_flag_with_execute_prints_full_banner_then_program_output",
        "p17_version_flag_does_not_execute_stdin",
        "p17_repl_eof_prints_full_banner_and_exact_prompt_termination",
    ];
    for (row, profile) in array(&proof, "rows")?.iter().zip(["lua55", "lua54"]) {
        exit_cli_version_row_identity(row, profile, original_root, environment)?;
        let log = Path::new(string(row, "log_path")?);
        if log != proof_dir.join(format!("green-{profile}.log")) {
            return Err("P17 CLI version banner log 路徑不符".into());
        }
        console_cli_public_file(log, &proof_dir)?;
        sha(log, string(row, "log_sha256")?)?;
        let target = Path::new(string(environment, "CARGO_TARGET_DIR")?);
        let running = Path::new(string(row, "running_binary_path")?);
        if running.parent() != Some(target.join("debug/deps").as_path())
            || !running.file_name().and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with("p17_version_banner-"))
        {
            return Err("P17 CLI version banner driver 身分不符".into());
        }
        let driver_sha = string(row, "snapshot_sha256")?;
        exit_digest(driver_sha)?;
        let snapshot = Path::new(string(row, "snapshot_path")?);
        if snapshot != proof_dir.join(format!("executed-{profile}-{driver_sha}")) {
            return Err("P17 CLI version banner driver snapshot 路徑不符".into());
        }
        console_cli_public_file(snapshot, &proof_dir)?;
        sha(snapshot, driver_sha)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 CLI version banner driver 權限不符".into());
        }
        report::mach_type(snapshot, "EXECUTE")?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(&body, &names, false)?;
        if counts.matched != 3 || counts.passed != 3 || counts.failed != 0 || counts.ignored != 0
            || !body.contains(&format!("Running tests/p17_version_banner.rs ({})", running.display()))
        {
            return Err("P17 CLI version banner log 結果／driver 不符".into());
        }
        let cli_running = Path::new(string(row, "cli_running_binary_path")?);
        let cli_sha = string(row, "cli_snapshot_sha256")?;
        exit_digest(cli_sha)?;
        let cli_snapshot = Path::new(string(row, "cli_snapshot_path")?);
        if cli_running != target.join("debug/rivetlua")
            || cli_snapshot != proof_dir.join(format!("cli-executed-{profile}-{cli_sha}"))
        {
            return Err("P17 CLI version banner product binary 路徑不符".into());
        }
        console_cli_public_file(cli_snapshot, &proof_dir)?;
        sha(cli_snapshot, cli_sha)?;
        if fs::metadata(cli_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 CLI version banner product binary 權限不符".into());
        }
        report::mach_type(cli_snapshot, "EXECUTE")?;
        let sources = array(row, "source_inputs")?;
        if sources.len() != source_paths.len() {
            return Err("P17 CLI version banner source 數量不符".into());
        }
        for (index, ((source, relative), digest)) in sources.iter().zip(source_paths).zip(source_digests).enumerate() {
            object(source, &["path", "sha256", "snapshot_path"])?;
            let source_snapshot = Path::new(string(source, "snapshot_path")?);
            if string(source, "path")? != original_root.join(relative).display().to_string()
                || string(source, "sha256")? != digest
                || source_snapshot != proof_dir.join(format!(
                    "{index}-{}", Path::new(relative).file_name().unwrap().to_string_lossy(),
                ))
            {
                return Err("P17 CLI version banner source 身分／順序不符".into());
            }
            console_cli_public_file(source_snapshot, &proof_dir)?;
            sha(source_snapshot, digest)?;
            if fs::metadata(source_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
                return Err("P17 CLI version banner source snapshot 權限不符".into());
            }
            if cli_diagnostics_updated && relative == EXIT_CLI_BINARY_PATH {
                exit_cli_lib_historical_input(original_root, source, source_snapshot, EXIT_CLI_VERSION_AFTER_SHA)?;
            } else {
                exit_warn_historical_source_with_verified(
                    original_root, current_root, evidence, relative, digest, Some(source_snapshot),
                    verified,
                )?;
            }
        }
    }
    Ok(())
}

fn exit_cli_version_banner_update(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_diagnostics_updated: bool,
    ctrl_c_updated: bool,
) -> Result<(), String> {
    exit_cli_version_banner_update_with_verified(
        original_root, current_root, evidence, update, cli_diagnostics_updated,
        ctrl_c_updated, None)
}

fn exit_cli_version_banner_update_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_diagnostics_updated: bool,
    ctrl_c_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    exit_cli_version_update_shape(update)?;
    let proof_dir = evidence.join(EXIT_CLI_VERSION_PROOF_DIR);
    let before = evidence.join("p17-binary-prefix-budget-order-20261011-1/source-final.rs");
    let after = proof_dir.join("source-final.rs");
    let diff = evidence.join("p17-phase-cli-version-banner-impact-crates__rivetlua-cli__src__lib.rs.diff");
    let reuse = proof_dir.join("reuse-review.json");
    if string(update, "before_snapshot_path")? != before.display().to_string()
        || string(update, "after_snapshot_path")? != after.display().to_string()
        || string(update, "diff_path")? != diff.display().to_string()
        || string(update, "reuse_review_path")? != reuse.display().to_string()
    {
        return Err("P17 CLI version banner 證據路徑不符".into());
    }
    console_cli_public_file(&before, &evidence.join("p17-binary-prefix-budget-order-20261011-1"))?;
    console_cli_public_file(&after, &proof_dir)?;
    console_cli_public_file(&diff, evidence)?;
    sha(&before, EXIT_CLI_BINARY_AFTER_SHA)?;
    sha(&after, string(update, "after_sha256")?)?;
    if fs::metadata(&before).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444
        || fs::metadata(&after).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 CLI version banner 來源 snapshot 權限不符".into());
    }
    let current_final = if ctrl_c_updated {
        exit_ctrl_c_before_source_with_verified(
            current_root, evidence, EXIT_CLI_BINARY_PATH, verified)?
    } else {
        current_root.join(EXIT_CLI_BINARY_PATH)
    };
    sha(
        &current_final,
        if cli_diagnostics_updated { EXIT_CLI_DIAGNOSTICS_AFTER_SHA } else { EXIT_CLI_VERSION_AFTER_SHA },
    )?;
    sha(&current_root.join(EXIT_CLI_VERSION_TEST_PATH), EXIT_CLI_VERSION_TEST_SHA)?;
    let old_cli_test = evidence.join("p17-version-banner-producer-20261011-1/before-cli.rs");
    console_cli_public_file(&old_cli_test, &evidence.join("p17-version-banner-producer-20261011-1"))?;
    sha(&old_cli_test, CONSOLE_CLI_REPL_SHA)?;
    sha(&current_root.join(CONSOLE_CLI_TEST_PATH), CONSOLE_CLI_VERSION_SHA)?;
    exit_cli_version_test_delta(
        &fs::read(&old_cli_test).map_err(|error| error.to_string())?,
        &fs::read(current_root.join(CONSOLE_CLI_TEST_PATH)).map_err(|error| error.to_string())?,
    )?;
    exit_cli_version_source_delta(
        &fs::read(&before).map_err(|error| error.to_string())?,
        &fs::read(&after).map_err(|error| error.to_string())?,
    )?;
    let change = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"before_sha256\":{},\"after_sha256\":{},\"diff_path\":{},\"diff_sha256\":{}}}",
        report::q(EXIT_CLI_BINARY_PATH),
        report::q(EXIT_CLI_BINARY_AFTER_SHA),
        report::q(string(update, "after_sha256")?),
        report::q(&diff.display().to_string()),
        report::q(string(update, "diff_sha256")?),
    ))?;
    let current_cli = current_root.join(EXIT_CLI_BINARY_PATH);
    let version_after = if cli_diagnostics_updated { after.as_path() } else { current_cli.as_path() };
    exit_raw_diff(
        current_root, original_root, evidence, &change, "cli-version-banner", EXIT_CLI_BINARY_PATH,
        &before, Some(EXIT_CLI_BINARY_AFTER_SHA), version_after,
        string(update, "after_sha256")?,
    )?;
    exit_cli_version_public_leaf_with_verified(
        original_root, current_root, evidence, update, cli_diagnostics_updated, verified)?;
    console_cli_public_file(&reuse, &proof_dir)?;
    sha(&reuse, string(update, "reuse_review_sha256")?)?;
    let reuse_value = StrictJsonParser::parse(
        &fs::read_to_string(&reuse).map_err(|error| error.to_string())?,
    )?;
    exit_cli_version_reuse_review_shape(&reuse_value, &before, &after, update)?;
    Ok(())
}

fn exit_cli_diagnostics_update(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    ctrl_c_updated: bool,
) -> Result<(), String> {
    exit_cli_diagnostics_update_with_verified(
        original_root, current_root, evidence, update, ctrl_c_updated, None)
}

fn exit_cli_diagnostics_update_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    ctrl_c_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    exit_cli_diagnostics_update_shape(update)?;
    let source_dir = evidence.join("p17-cli-diagnostics-source-20261011-1");
    let before = source_dir.join("before-crates__rivetlua-cli__src__lib.rs");
    let after = source_dir.join("source-final.rs");
    let diff = evidence.join("p17-phase-cli-diagnostics-impact-crates__rivetlua-cli__src__lib.rs.diff");
    let proof_dir = evidence.join(EXIT_CLI_DIAGNOSTICS_PROOF_DIR);
    let public = proof_dir.join("public/result.json");
    let reuse = proof_dir.join("reuse-review.json");
    if string(update, "before_snapshot_path")? != before.display().to_string()
        || string(update, "after_snapshot_path")? != after.display().to_string()
        || string(update, "diff_path")? != diff.display().to_string()
        || string(update, "diff_sha256")? != "1666d76f3421a9e587bde8070d6dd4b4b1e85854d62418a74c2793e8f9040d39"
        || string(update, "public_proof_path")? != public.display().to_string()
        || string(update, "public_proof_sha256")? != "2ab2fa8289292de6e1cb3808843081c759e0d2686b62faf12a071ec8aee40bfa"
        || string(update, "reuse_review_path")? != reuse.display().to_string()
        || string(update, "reuse_review_sha256")? != "8ec9162b1062c5b68440a281b9fe071c328c5af1990144cb3054d8d80815bc63"
    {
        return Err("P17 CLI diagnostics 固定證據路徑／diff 不符".into());
    }
    for (path, digest) in [
        (&before, EXIT_CLI_VERSION_AFTER_SHA),
        (&after, EXIT_CLI_DIAGNOSTICS_AFTER_SHA),
    ] {
        console_cli_public_file(path, &source_dir)?;
        sha(path, digest)?;
        if fs::metadata(path).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
            return Err("P17 CLI diagnostics source snapshot 權限不符".into());
        }
    }
    let current = if ctrl_c_updated {
        exit_ctrl_c_before_source_with_verified(
            current_root, evidence, EXIT_CLI_BINARY_PATH, verified)?
    } else {
        current_root.join(EXIT_CLI_BINARY_PATH)
    };
    sha(&current, EXIT_CLI_DIAGNOSTICS_AFTER_SHA)?;
    sha(&current_root.join(EXIT_CLI_DIAGNOSTICS_TEST_PATH), EXIT_CLI_DIAGNOSTICS_TEST_SHA)?;
    console_cli_public_file(&diff, evidence)?;
    let primary = source_dir.join("primary-source-review.json");
    console_cli_public_file(&primary, &source_dir)?;
    sha(&primary, "68c2795c9e86f992ccc4f50041eaa2c9caa2262e20bc186742c48df3496be8f6")?;
    let change = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"before_sha256\":{},\"after_sha256\":{},\"diff_path\":{},\"diff_sha256\":{}}}",
        report::q(EXIT_CLI_BINARY_PATH), report::q(EXIT_CLI_VERSION_AFTER_SHA),
        report::q(EXIT_CLI_DIAGNOSTICS_AFTER_SHA), report::q(&diff.display().to_string()),
        report::q(string(update, "diff_sha256")?),
    ))?;
    exit_raw_diff(
        current_root, original_root, evidence, &change, "cli-diagnostics", EXIT_CLI_BINARY_PATH,
        &before, Some(EXIT_CLI_VERSION_AFTER_SHA), &current,
        EXIT_CLI_DIAGNOSTICS_AFTER_SHA,
    )?;
    exit_cli_diagnostics_public_leaf_with_verified(
        original_root, current_root, evidence, update, verified)?;
    console_cli_public_file(&reuse, &proof_dir)?;
    sha(&reuse, string(update, "reuse_review_sha256")?)?;
    let reuse_value = StrictJsonParser::parse(
        &fs::read_to_string(&reuse).map_err(|error| error.to_string())?,
    )?;
    exit_cli_diagnostics_reuse_review_shape(&reuse_value, &before, &after)?;
    Ok(())
}

fn exit_cli_diagnostics_root_review_shape(
    review: &StrictJsonValue,
    original_root: &Path,
    evidence: &Path,
    source_paths: &[&str],
) -> Result<(), String> {
    object(review, &[
        "schema", "status", "kind", "repository_root", "cli_sha256",
        "source_paths", "terminal_records", "artifact_checks", "input_basis",
        "checks", "review_note",
    ])?;
    if string(review, "schema")? != "rivetlua-p17-cli-diagnostics-root-review-v1"
        || string(review, "status")? != "PASS"
        || string(review, "kind")? != "public"
        || string(review, "repository_root")? != original_root.display().to_string()
        || string(review, "cli_sha256")? != EXIT_CLI_DIAGNOSTICS_AFTER_SHA
        || strings(review, "source_paths")?
            != source_paths.iter().map(|path| (*path).to_owned()).collect::<Vec<_>>()
        || string(review, "review_note")?.trim().is_empty()
        || array(review, "artifact_checks")?.is_empty()
        || array(review, "input_basis")?.is_empty()
        || array(review, "checks")?.is_empty()
    {
        return Err("P17 CLI diagnostics root-review 主鍵／紀錄不符".into());
    }
    let proof_dir = evidence.join(EXIT_CLI_DIAGNOSTICS_PROOF_DIR);
    let expected = [
        proof_dir.join("actor-result-final.json"),
        proof_dir.join("terminal-completion.json"),
    ];
    let terminals = array(review, "terminal_records")?;
    if terminals.len() != expected.len() {
        return Err("P17 CLI diagnostics terminal attestation 數量不符".into());
    }
    let mut seen = BTreeSet::new();
    for item in terminals {
        object(item, &["path", "sha256"])?;
        let path = Path::new(string(item, "path")?);
        let digest = string(item, "sha256")?;
        exit_digest(digest)?;
        if !expected.iter().any(|fixed| fixed == path) || !seen.insert(path.to_path_buf()) {
            return Err("P17 CLI diagnostics terminal attestation 身分不符".into());
        }
        console_cli_public_file(path, &proof_dir)?;
        sha(path, digest)?;
        let terminal = StrictJsonParser::parse(
            &fs::read_to_string(path).map_err(|error| error.to_string())?,
        )?;
        if string(&terminal, "status")? != "PASS" {
            return Err("P17 CLI diagnostics terminal 未完成 PASS".into());
        }
    }
    Ok(())
}

fn exit_cli_diagnostics_leaf_shape(proof: &StrictJsonValue, readiness: &Path) -> Result<(), String> {
    object(proof, &[
        "status", "reported_by", "root_review", "readiness_path", "readiness_sha256", "rows",
    ])?;
    if string(proof, "status")? != "PASS"
        || string(proof, "reported_by")? != "primary root"
        || string(proof, "root_review")?.is_empty()
        || string(proof, "readiness_path")? != readiness.display().to_string()
        || string(proof, "readiness_sha256")? != "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb"
        || array(proof, "rows")?.len() != 2
    {
        return Err("P17 CLI diagnostics proof 主鍵／row 數不符".into());
    }
    for row in array(proof, "rows")? {
        object(row, &[
            "profile", "command", "cwd", "environment_mode", "environment",
            "exit_code", "matched", "passed", "failed", "ignored", "filtered",
            "log_path", "log_sha256", "running_binary_path", "snapshot_path",
            "snapshot_sha256", "source_inputs", "cli_running_binary_path",
            "cli_snapshot_path", "cli_snapshot_sha256",
        ])?;
    }
    Ok(())
}

fn exit_cli_diagnostics_row_identity(
    row: &StrictJsonValue,
    profile: &str,
    original_root: &Path,
    environment: &StrictJsonValue,
) -> Result<(), String> {
    if !["lua55", "lua54"].contains(&profile) {
        return Err("P17 CLI diagnostics 未知 profile".into());
    }
    let features = if profile == "lua55" { "native-lua55" } else { "native-lua54,default-lua54" };
    let command = [
        EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-cli", "--no-default-features",
        "--features", features, "--test", "p17_cli_diagnostics", "--", "--nocapture", "--test-threads=1",
    ];
    if string(row, "profile")? != profile
        || strings(row, "command")? != command.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>()
        || string(row, "cwd")? != original_root.display().to_string()
        || string(row, "environment_mode")? != "env -i"
        || canonical_json(field(row, "environment")?) != canonical_json(environment)
        || integer(row, "exit_code")? != 0
        || integer(row, "matched")? != 3
        || integer(row, "passed")? != 3
        || integer(row, "failed")? != 0
        || integer(row, "ignored")? != 0
        || integer(row, "filtered")? != 0
    {
        return Err(format!("P17 CLI diagnostics {profile} 命令／count 不符"));
    }
    Ok(())
}

fn exit_cli_diagnostics_public_leaf(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
) -> Result<(), String> {
    exit_cli_diagnostics_public_leaf_with_verified(
        original_root, current_root, evidence, update, None)
}

fn exit_cli_diagnostics_public_leaf_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let proof_dir = evidence.join(EXIT_CLI_DIAGNOSTICS_PROOF_DIR).join("public");
    let result = proof_dir.join("result.json");
    if string(update, "public_proof_path")? != result.display().to_string() {
        return Err("P17 CLI diagnostics public proof 路徑不符".into());
    }
    console_cli_public_file(&result, &proof_dir)?;
    sha(&result, string(update, "public_proof_sha256")?)?;
    let proof = StrictJsonParser::parse(
        &fs::read_to_string(&result).map_err(|error| error.to_string())?,
    )?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    sha(&readiness, "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb")?;
    exit_cli_diagnostics_leaf_shape(&proof, &readiness)?;
    let root_review = proof_dir.join("root-review.json");
    console_cli_public_file(&root_review, &proof_dir)?;
    let root_sha = manifest::sha256(&root_review)?;
    let claim = string(&proof, "root_review")?;
    if !claim.contains(&root_review.display().to_string()) || !claim.contains(&root_sha) {
        return Err("P17 CLI diagnostics root-review 引用不符".into());
    }
    let readiness_value = StrictJsonParser::parse(
        &fs::read_to_string(&readiness).map_err(|error| error.to_string())?,
    )?;
    let environment = field(field(&readiness_value, "phase_launch")?, "required_environment")?;
    exit_safe_cargo(evidence)?;
    let source_paths = [
        EXIT_CLI_DIAGNOSTICS_TEST_PATH,
        EXIT_CLI_BINARY_PATH,
        "crates/rivetlua-runtime/src/vm/mod.rs",
        "crates/rivetlua/src/lib.rs",
        EXIT_PARSER_PATH,
        "crates/rivetlua-core/src/bytecode/input.rs",
    ];
    let source_digests = [
        EXIT_CLI_DIAGNOSTICS_TEST_SHA,
        EXIT_CLI_DIAGNOSTICS_AFTER_SHA,
        "fcf16b4b24c26aef22da6d653b1b19a5412fbeb852ec25b850b19edaba33c088",
        "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
        EXIT_PARSER_AFTER_SHA,
        "1495457f26a517b8a89014b1b3bb227289605e01b325f8fcbada323dd95a3959",
    ];
    let root_value = StrictJsonParser::parse(
        &fs::read_to_string(&root_review).map_err(|error| error.to_string())?,
    )?;
    exit_cli_diagnostics_root_review_shape(&root_value, original_root, evidence, &source_paths)?;
    let names = [
        "p17_cli_unknown_options_report_lua_compatible_diagnostics",
        "p17_cli_missing_option_arguments_report_lua_compatible_diagnostics",
        "p17_cli_syntax_and_missing_file_diagnostics_identify_failure",
    ];
    for (row, profile) in array(&proof, "rows")?.iter().zip(["lua55", "lua54"]) {
        exit_cli_diagnostics_row_identity(row, profile, original_root, environment)?;
        let log = Path::new(string(row, "log_path")?);
        if log != proof_dir.join(format!("green-{profile}.log")) {
            return Err("P17 CLI diagnostics log 路徑不符".into());
        }
        console_cli_public_file(log, &proof_dir)?;
        sha(log, string(row, "log_sha256")?)?;
        let target = Path::new(string(environment, "CARGO_TARGET_DIR")?);
        let running = Path::new(string(row, "running_binary_path")?);
        if running.parent() != Some(target.join("debug/deps").as_path())
            || !running.file_name().and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with("p17_cli_diagnostics-"))
        {
            return Err("P17 CLI diagnostics driver 身分不符".into());
        }
        let driver_sha = string(row, "snapshot_sha256")?;
        exit_digest(driver_sha)?;
        let snapshot = Path::new(string(row, "snapshot_path")?);
        if snapshot != proof_dir.join(format!("executed-{profile}-{driver_sha}")) {
            return Err("P17 CLI diagnostics driver snapshot 路徑不符".into());
        }
        console_cli_public_file(snapshot, &proof_dir)?;
        sha(snapshot, driver_sha)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 CLI diagnostics driver 權限不符".into());
        }
        report::mach_type(snapshot, "EXECUTE")?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(&body, &names, false)?;
        if counts.matched != 3 || counts.passed != 3 || counts.failed != 0 || counts.ignored != 0
            || !body.contains(&format!("Running tests/p17_cli_diagnostics.rs ({})", running.display()))
        {
            return Err("P17 CLI diagnostics log 結果／driver 不符".into());
        }
        let cli_running = Path::new(string(row, "cli_running_binary_path")?);
        let cli_sha = string(row, "cli_snapshot_sha256")?;
        exit_digest(cli_sha)?;
        let cli_snapshot = Path::new(string(row, "cli_snapshot_path")?);
        if cli_running != target.join("debug/rivetlua")
            || cli_snapshot != proof_dir.join(format!("cli-executed-{profile}-{cli_sha}"))
        {
            return Err("P17 CLI diagnostics product binary 路徑不符".into());
        }
        console_cli_public_file(cli_snapshot, &proof_dir)?;
        sha(cli_snapshot, cli_sha)?;
        if fs::metadata(cli_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 CLI diagnostics product binary 權限不符".into());
        }
        report::mach_type(cli_snapshot, "EXECUTE")?;
        let sources = array(row, "source_inputs")?;
        if sources.len() != source_paths.len() {
            return Err("P17 CLI diagnostics source 數量不符".into());
        }
        for (index, ((source, relative), digest)) in sources.iter().zip(source_paths).zip(source_digests).enumerate() {
            object(source, &["path", "sha256", "snapshot_path"])?;
            let source_snapshot = Path::new(string(source, "snapshot_path")?);
            if string(source, "path")? != original_root.join(relative).display().to_string()
                || string(source, "sha256")? != digest
                || source_snapshot != proof_dir.join(format!(
                    "{index}-{}", Path::new(relative).file_name().unwrap().to_string_lossy(),
                ))
            {
                return Err("P17 CLI diagnostics source 身分／順序不符".into());
            }
            console_cli_public_file(source_snapshot, &proof_dir)?;
            sha(source_snapshot, digest)?;
            if fs::metadata(source_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
                return Err("P17 CLI diagnostics source snapshot 權限不符".into());
            }
            exit_warn_historical_source_with_verified(
                original_root, current_root, evidence, relative, digest, Some(source_snapshot),
                verified,
            )?;
        }
    }
    exit_cli_diagnostics_unit_evidence_with_verified(
        original_root, current_root, evidence, environment, &proof, verified)?;
    Ok(())
}

fn exit_cli_diagnostics_unit_evidence(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    environment: &StrictJsonValue,
    proof: &StrictJsonValue,
) -> Result<(), String> {
    exit_cli_diagnostics_unit_evidence_with_verified(
        original_root, current_root, evidence, environment, proof, None)
}

fn exit_cli_diagnostics_unit_evidence_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    environment: &StrictJsonValue,
    proof: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let proof_dir = evidence.join(EXIT_CLI_DIAGNOSTICS_PROOF_DIR);
    let actor_path = proof_dir.join("actor-result-final.json");
    let terminal_path = proof_dir.join("terminal-completion.json");
    let actor = StrictJsonParser::parse(
        &fs::read_to_string(&actor_path).map_err(|error| error.to_string())?,
    )?;
    let terminal = StrictJsonParser::parse(
        &fs::read_to_string(&terminal_path).map_err(|error| error.to_string())?,
    )?;
    if string(&actor, "schema")? != "rivetlua-p17-cli-diagnostics-actor-result-final-v1"
        || string(&actor, "status")? != "PASS"
        || integer(&actor, "commands_planned")? != 4
        || integer(&actor, "commands_completed")? != 4
        || integer(&actor, "actual_cargo_invocations")? != 5
        || integers(&actor, "accepted_command_order")? != [1, 2, 3, 4]
        || integers(&actor, "commands_reused_without_rerun")? != [2, 3, 4]
        || array(&actor, "commands")?.len() != 4
        || array(&actor, "live_handles")?.len() != 0
        || !matches!(field(&actor, "final_source_drift")?, StrictJsonValue::Object(map) if map.is_empty())
        || string(&actor, "terminal_completion_path")? != terminal_path.display().to_string()
    {
        return Err("P17 CLI diagnostics actor 完成／重用紀錄不符".into());
    }
    let ordinals = field(&actor, "accepted_command_attempt_ordinals")?;
    object(ordinals, &["1", "2", "3", "4"])?;
    if integer(ordinals, "1")? != 5 || integer(ordinals, "2")? != 2
        || integer(ordinals, "3")? != 3 || integer(ordinals, "4")? != 4
    {
        return Err("P17 CLI diagnostics 補跑 ordinal 不符".into());
    }
    let nonaccepted = array(&actor, "nonaccepted_attempts")?;
    if nonaccepted.len() != 1
        || integer(&nonaccepted[0], "attempt_ordinal")? != 1
        || integer(&nonaccepted[0], "command_index")? != 1
        || boolean(&nonaccepted[0], "accepted")?
        || string(&nonaccepted[0], "status")? != "NONACCEPTED_CARGO_EXIT_UNKNOWN"
        || !matches!(field(&nonaccepted[0], "cargo_exit_code")?, StrictJsonValue::Null)
    {
        return Err("P17 CLI diagnostics 未知 exit 首次紀錄遺失".into());
    }
    let archived = Path::new(string(&nonaccepted[0], "archive_snapshot_path")?);
    if archived != proof_dir.join("pre-resume/row-01-original-unknown-exit.json") {
        return Err("P17 CLI diagnostics 未知 exit archive 路徑不符".into());
    }
    console_cli_public_file(archived, &proof_dir)?;
    sha(archived, string(&nonaccepted[0], "archive_snapshot_sha256")?)?;
    if string(&terminal, "schema")? != "rivetlua-p17-cli-diagnostics-actual-terminal-completion-v2"
        || string(&terminal, "status")? != "PASS"
        || integer(&terminal, "accepted_commands_planned")? != 4
        || integer(&terminal, "accepted_commands_completed")? != 4
        || !array(&terminal, "accepted_commands_unrun")?.is_empty()
        || integer(&terminal, "accepted_tests_reported_passed")? != 8
        || integer(&terminal, "accepted_tests_failed")? != 0
        || integer(&terminal, "accepted_tests_ignored")? != 0
        || integers(&terminal, "accepted_command_cargo_exit_codes")? != [0, 0, 0, 0]
        || integer(&terminal, "actual_cargo_invocations_total")? != 5
        || array(&terminal, "nonaccepted_attempts")?.len() != 1
        || canonical_json(field(&terminal, "nonaccepted_attempts")?)
            != canonical_json(field(&actor, "nonaccepted_attempts")?)
        || canonical_json(field(&terminal, "actual_invocation_order")?)
            != canonical_json(field(&actor, "actual_invocation_order")?)
        || array(&terminal, "live_handles")?.len() != 0
        || !matches!(field(&terminal, "source_drift")?, StrictJsonValue::Object(map) if map.is_empty())
        || string(&terminal, "actor_result_path")? != actor_path.display().to_string()
        || string(&terminal, "actor_result_sha256")? != manifest::sha256(&actor_path)?
        || array(&terminal, "commands")?.len() != 4
    {
        return Err("P17 CLI diagnostics terminal 完成／count 不符".into());
    }
    let invocation_order = array(&terminal, "actual_invocation_order")?;
    let expected_order = [(1, 1, false, None), (2, 2, true, Some(0)),
        (3, 3, true, Some(0)), (4, 4, true, Some(0)), (5, 1, true, Some(0))];
    if invocation_order.len() != expected_order.len() {
        return Err("P17 CLI diagnostics 實際 invocation 數量不符".into());
    }
    for (row, (ordinal, index, accepted, exit)) in invocation_order.iter().zip(expected_order) {
        object(row, &["attempt_ordinal", "command_index", "accepted", "cargo_exit_code"])?;
        if integer(row, "attempt_ordinal")? != ordinal
            || integer(row, "command_index")? != index
            || boolean(row, "accepted")? != accepted
            || match exit {
                Some(code) => integer(row, "cargo_exit_code")? != code,
                None => !matches!(field(row, "cargo_exit_code")?, StrictJsonValue::Null),
            }
        {
            return Err("P17 CLI diagnostics 實際 invocation 順序不符".into());
        }
    }
    let affected = proof_dir.join("affected");
    let snapshot_manifest = affected.join("source-snapshots.json");
    console_cli_public_file(&snapshot_manifest, &affected)?;
    let snapshots = StrictJsonParser::parse(
        &fs::read_to_string(&snapshot_manifest).map_err(|error| error.to_string())?,
    )?;
    object(&snapshots, &["launch_review_sha256", "source_inputs"])?;
    if string(&snapshots, "launch_review_sha256")? != string(&actor, "launch_review_sha256")? {
        return Err("P17 CLI diagnostics private source snapshot launch 不符".into());
    }
    let source_paths = [
        EXIT_CLI_DIAGNOSTICS_TEST_PATH, EXIT_CLI_BINARY_PATH,
        "crates/rivetlua-runtime/src/vm/mod.rs", "crates/rivetlua/src/lib.rs",
        EXIT_PARSER_PATH, "crates/rivetlua-core/src/bytecode/input.rs", CONSOLE_CLI_TEST_PATH,
    ];
    let source_digests = [
        EXIT_CLI_DIAGNOSTICS_TEST_SHA, EXIT_CLI_DIAGNOSTICS_AFTER_SHA,
        "fcf16b4b24c26aef22da6d653b1b19a5412fbeb852ec25b850b19edaba33c088",
        "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
        EXIT_PARSER_AFTER_SHA,
        "1495457f26a517b8a89014b1b3bb227289605e01b325f8fcbada323dd95a3959",
        CONSOLE_CLI_VERSION_SHA,
    ];
    let source_snapshots = array(&snapshots, "source_inputs")?;
    if source_snapshots.len() != source_paths.len() {
        return Err("P17 CLI diagnostics private source snapshot 數量不符".into());
    }
    for (index, ((source, relative), digest)) in source_snapshots.iter().zip(source_paths).zip(source_digests).enumerate() {
        object(source, &["path", "sha256", "snapshot_path", "mode"])?;
        let snapshot = Path::new(string(source, "snapshot_path")?);
        if string(source, "path")? != original_root.join(relative).display().to_string()
            || string(source, "sha256")? != digest
            || string(source, "mode")? != "0o444"
            || snapshot != affected.join(format!(
                "{index}-{}", Path::new(relative).file_name().unwrap().to_string_lossy(),
            ))
        {
            return Err("P17 CLI diagnostics private source snapshot 身分不符".into());
        }
        console_cli_public_file(snapshot, &affected)?;
        sha(snapshot, digest)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
            return Err("P17 CLI diagnostics private source snapshot 權限不符".into());
        }
    }
    let commands = array(&actor, "commands")?;
    for (index, (command, summary)) in commands.iter().zip(array(&terminal, "commands")?).enumerate() {
        if integer(command, "index")? != (index + 1) as u64
            || integer(summary, "index")? != (index + 1) as u64
            || string(command, "profile")? != string(summary, "profile")?
            || string(command, "kind")? != string(summary, "kind")?
            || string(command, "status")? != "PASS"
            || string(summary, "status")? != "PASS"
            || integer(command, "exit_code")? != 0
            || integer(summary, "cargo_exit_code")? != 0
            || canonical_json(field(command, "counts")?) != canonical_json(field(summary, "counts")?)
            || string(command, "combined_log_path")? != string(summary, "combined_log_path")?
            || string(command, "combined_log_sha256")? != string(summary, "combined_log_sha256")?
        {
            return Err("P17 CLI diagnostics actor／terminal accepted row 不符".into());
        }
    }
    for (index, profile, proof_index) in [(0, "lua55", 0), (2, "lua54", 1)] {
        let row = &commands[index];
        let normalized = &array(proof, "rows")?[proof_index];
        if string(row, "status")? != "PASS" || integer(row, "exit_code")? != 0
            || integer(field(row, "counts")?, "matched")? != 3
            || integer(field(row, "counts")?, "passed")? != 3
            || strings(row, "argv")? != strings(normalized, "command")?
            || string(row, "combined_log_sha256")? != string(normalized, "log_sha256")?
            || canonical_json(field(row, "environment")?) != canonical_json(environment)
        {
            return Err("P17 CLI diagnostics public actor 真實 exit 缺失".into());
        }
        if string(row, "profile")? != format!("{profile}-i64f64") {
            return Err("P17 CLI diagnostics public actor profile 不符".into());
        }
        let actor_sources = array(row, "source_inputs")?;
        let normalized_sources = array(normalized, "source_inputs")?;
        if actor_sources.len() != 7 || normalized_sources.len() != 6 {
            return Err("P17 CLI diagnostics public actor source 數量不符".into());
        }
        for (actual, normalized) in actor_sources.iter().zip(normalized_sources) {
            if string(actual, "path")? != string(normalized, "path")?
                || string(actual, "sha256")? != string(normalized, "sha256")?
            {
                return Err("P17 CLI diagnostics public actor source 與leaf不符".into());
            }
        }
    }
    for (index, profile) in [(1, "lua55"), (3, "lua54")] {
        exit_cli_diagnostics_unit_row_with_verified(
            &commands[index], index + 1, profile, original_root, current_root,
            &proof_dir, environment, verified,
        )?;
    }
    Ok(())
}

fn exit_cli_diagnostics_unit_row(
    row: &StrictJsonValue,
    index: usize,
    profile: &str,
    original_root: &Path,
    current_root: &Path,
    proof_dir: &Path,
    environment: &StrictJsonValue,
) -> Result<(), String> {
    exit_cli_diagnostics_unit_row_with_verified(
        row, index, profile, original_root, current_root, proof_dir, environment, None)
}

fn exit_cli_diagnostics_unit_row_with_verified(
    row: &StrictJsonValue,
    index: usize,
    profile: &str,
    original_root: &Path,
    current_root: &Path,
    proof_dir: &Path,
    environment: &StrictJsonValue,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let selector = "cli_unit_tests::p17_preprocess_cli_lexical_error_format";
    let features = if profile == "lua55" { "native-lua55" } else { "native-lua54,default-lua54" };
    let command = [
        EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-cli", "--no-default-features",
        "--features", features, "--lib", selector, "--", "--exact", "--nocapture", "--test-threads=1",
    ];
    if integer(row, "index")? != index as u64
        || string(row, "kind")? != "affected-unit"
        || string(row, "profile")? != format!("{profile}-i64f64")
        || string(row, "selector")? != selector
        || strings(row, "argv")? != command.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>()
        || string(row, "cwd")? != original_root.display().to_string()
        || string(row, "environment_mode")? != "env -i"
        || canonical_json(field(row, "environment")?) != canonical_json(environment)
        || string(row, "status")? != "PASS"
        || integer(row, "exit_code")? != 0
        || !matches!(field(row, "source_drift")?, StrictJsonValue::Object(map) if map.is_empty())
    {
        return Err(format!("P17 CLI diagnostics {profile} private unit 身分不符"));
    }
    let counts = field(row, "counts")?;
    if integer(counts, "matched")? != 1 || integer(counts, "passed")? != 1
        || integer(counts, "failed")? != 0 || integer(counts, "ignored")? != 0
        || integer(counts, "filtered")? != 37 || string(counts, "summary_status")? != "ok"
        || integer(counts, "running")? != 1
    {
        return Err("P17 CLI diagnostics private unit count 不符".into());
    }
    let log = Path::new(string(row, "combined_log_path")?);
    if log != proof_dir.join(format!("affected/row-{index:02}-{profile}-i64f64-affected-unit.combined.log")) {
        return Err("P17 CLI diagnostics private unit log 路徑不符".into());
    }
    console_cli_public_file(log, proof_dir)?;
    sha(log, string(row, "combined_log_sha256")?)?;
    let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
    let (parsed, _) = parse_named_log_with_filter(&body, &[selector], true)?;
    let running = Path::new(string(row, "running_binary_path")?);
    let target = Path::new(string(environment, "CARGO_TARGET_DIR")?);
    if parsed.matched != 1 || parsed.passed != 1 || parsed.failed != 0 || parsed.ignored != 0
        || !body.contains("37 filtered out;")
        || !body.contains(&format!("Running unittests src/lib.rs ({})", running.display()))
        || running.parent() != Some(target.join("debug/deps").as_path())
        || !running.file_name().and_then(|name| name.to_str())
            .is_some_and(|name| name.starts_with("rivetlua_cli-"))
    {
        return Err("P17 CLI diagnostics private unit log／driver 不符".into());
    }
    let source_paths = [
        EXIT_CLI_DIAGNOSTICS_TEST_PATH, EXIT_CLI_BINARY_PATH,
        "crates/rivetlua-runtime/src/vm/mod.rs", "crates/rivetlua/src/lib.rs",
        EXIT_PARSER_PATH, "crates/rivetlua-core/src/bytecode/input.rs", CONSOLE_CLI_TEST_PATH,
    ];
    let source_digests = [
        EXIT_CLI_DIAGNOSTICS_TEST_SHA, EXIT_CLI_DIAGNOSTICS_AFTER_SHA,
        "fcf16b4b24c26aef22da6d653b1b19a5412fbeb852ec25b850b19edaba33c088",
        "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
        EXIT_PARSER_AFTER_SHA,
        "1495457f26a517b8a89014b1b3bb227289605e01b325f8fcbada323dd95a3959",
        CONSOLE_CLI_VERSION_SHA,
    ];
    let sources = array(row, "source_inputs")?;
    if sources.len() != source_paths.len() {
        return Err("P17 CLI diagnostics private unit source 數量不符".into());
    }
    for ((source, relative), digest) in sources.iter().zip(source_paths).zip(source_digests) {
        object(source, &["path", "sha256"])?;
        if string(source, "path")? != original_root.join(relative).display().to_string()
            || string(source, "sha256")? != digest
        {
            return Err("P17 CLI diagnostics private unit source 身分不符".into());
        }
        exit_warn_historical_source_with_verified(
            original_root, current_root, proof_dir.parent().ok_or("P17 CLI diagnostics proof 根目錄缺失")?,
            relative, digest, None, verified,
        )?;
    }
    Ok(())
}

fn exit_cli_binary_file_prefix_update(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    ctrl_c_updated: bool,
) -> Result<(), String> {
    exit_cli_binary_file_prefix_update_with_verified(
        original_root, current_root, evidence, update, cli_version_updated,
        cli_diagnostics_updated, ctrl_c_updated, None)
}

fn exit_cli_binary_file_prefix_update_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    ctrl_c_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    exit_cli_binary_update_shape(update)?;
    let relative = EXIT_CLI_BINARY_PATH;
    let before_dir = evidence.join(EXIT_CLI_UNIT_GREEN_DIR);
    let before = before_dir.join("0-lib.rs");
    let after_dir = evidence.join("p17-binary-prefix-budget-order-20261011-1");
    let after = after_dir.join("source-final.rs");
    let diff = evidence.join(format!(
        "p17-phase-cli-binary-file-prefix-impact-{}.diff",
        relative.replace('/', "__"),
    ));
    let proof_dir = evidence.join(EXIT_CLI_BINARY_PROOF_DIR);
    let unit = proof_dir.join("unit/result.json");
    let public = proof_dir.join("public/result.json");
    let reuse = proof_dir.join("reuse-review.json");
    if string(update, "before_snapshot_path")? != before.display().to_string()
        || string(update, "after_snapshot_path")? != after.display().to_string()
        || string(update, "diff_path")? != diff.display().to_string()
        || string(update, "unit_proof_path")? != unit.display().to_string()
        || string(update, "public_proof_path")? != public.display().to_string()
        || string(update, "reuse_review_path")? != reuse.display().to_string()
    {
        return Err("P17 CLI binary prefix 證據路徑不符".into());
    }
    console_cli_public_file(&before, &before_dir)?;
    console_cli_public_file(&after, &after_dir)?;
    console_cli_public_file(&unit, &proof_dir)?;
    console_cli_public_file(&public, &proof_dir)?;
    console_cli_public_file(&reuse, &proof_dir)?;
    console_cli_public_file(&diff, evidence)?;
    sha(&before, EXIT_CLI_LIB_TEST_ONLY_SHA)?;
    sha(&after, EXIT_CLI_BINARY_AFTER_SHA)?;
    let current_final = if ctrl_c_updated {
        exit_ctrl_c_before_source_with_verified(current_root, evidence, relative, verified)?
    } else {
        current_root.join(relative)
    };
    sha(
        &current_final,
        if cli_diagnostics_updated { EXIT_CLI_DIAGNOSTICS_AFTER_SHA }
        else if cli_version_updated { EXIT_CLI_VERSION_AFTER_SHA }
        else { EXIT_CLI_BINARY_AFTER_SHA },
    )?;
    sha(&current_root.join(EXIT_CLI_BINARY_TEST_PATH), EXIT_CLI_BINARY_TEST_SHA)?;
    let change = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"before_sha256\":{},\"after_sha256\":{},\"diff_path\":{},\"diff_sha256\":{}}}",
        report::q(relative),
        report::q(EXIT_CLI_LIB_TEST_ONLY_SHA),
        report::q(EXIT_CLI_BINARY_AFTER_SHA),
        report::q(&diff.display().to_string()),
        report::q(string(update, "diff_sha256")?),
    ))?;
    exit_raw_diff(
        current_root,
        original_root,
        evidence,
        &change,
        "cli-binary-file-prefix",
        relative,
        &before,
        Some(EXIT_CLI_LIB_TEST_ONLY_SHA),
        &after,
        EXIT_CLI_BINARY_AFTER_SHA,
    )?;
    exit_cli_binary_leaf_with_verified(
        original_root, current_root, evidence, update, false,
        cli_version_updated || cli_diagnostics_updated, verified)?;
    exit_cli_binary_leaf_with_verified(
        original_root, current_root, evidence, update, true,
        cli_version_updated || cli_diagnostics_updated, verified)?;
    console_cli_public_file(&reuse, &proof_dir)?;
    sha(&reuse, string(update, "reuse_review_sha256")?)?;
    let reuse_value = StrictJsonParser::parse(
        &fs::read_to_string(&reuse).map_err(|error| error.to_string())?,
    )?;
    exit_cli_binary_reuse_review_shape(&reuse_value, original_root, &before, &after)?;
    Ok(())
}

fn exit_cli_binary_reuse_review_shape(
    review: &StrictJsonValue,
    original_root: &Path,
    before: &Path,
    after: &Path,
) -> Result<(), String> {
    object(review, &[
        "schema", "path", "before_sha256", "after_sha256", "before_snapshot_path",
        "after_snapshot_path", "test_path", "test_sha256", "historical_cli_shas",
        "reuse_basis", "required_new_validation", "review_note",
    ])?;
    if string(review, "schema")? != "rivetlua-p17-cli-binary-prefix-reuse-v1"
        || string(review, "path")? != EXIT_CLI_BINARY_PATH
        || string(review, "before_sha256")? != EXIT_CLI_LIB_TEST_ONLY_SHA
        || string(review, "after_sha256")? != EXIT_CLI_BINARY_AFTER_SHA
        || string(review, "before_snapshot_path")? != before.display().to_string()
        || string(review, "after_snapshot_path")? != after.display().to_string()
        || string(review, "test_path")? != EXIT_CLI_BINARY_TEST_PATH
        || string(review, "test_sha256")? != EXIT_CLI_BINARY_TEST_SHA
        || strings(review, "historical_cli_shas")? != [EXIT_CLI_LIB_SHA, EXIT_CLI_LIB_TEST_ONLY_SHA]
        || strings(review, "required_new_validation")? != [
            "binary-prefix-unit-lua55", "binary-prefix-unit-lua54",
            "binary-prefix-public-lua55", "binary-prefix-public-lua54", "P17-final-phase-state",
        ]
        || string(review, "review_note")?.trim().is_empty()
    {
        return Err("P17 CLI binary prefix reuse review 主鍵不符".into());
    }
    let bases = array(review, "reuse_basis")?;
    if bases.is_empty() {
        return Err("P17 CLI binary prefix reuse basis 缺失".into());
    }
    for basis in bases {
        object(basis, &["scope", "basis"])?;
        if string(basis, "scope")?.trim().is_empty() || string(basis, "basis")?.trim().is_empty() {
            return Err("P17 CLI binary prefix reuse basis 空白".into());
        }
    }
    if !original_root.is_absolute() {
        return Err("P17 CLI binary prefix 原 repo 路徑非絕對".into());
    }
    Ok(())
}

fn exit_cli_binary_root_review_shape(
    review: &StrictJsonValue,
    original_root: &Path,
    evidence: &Path,
    public: bool,
    source_paths: &[&str],
) -> Result<(), String> {
    object(review, &[
        "schema", "status", "kind", "repository_root", "cli_sha256",
        "source_paths", "terminal_records", "artifact_checks", "input_basis",
        "checks", "review_note",
    ])?;
    if string(review, "schema")? != "rivetlua-p17-cli-binary-prefix-root-review-v1"
        || string(review, "status")? != "PASS"
        || string(review, "kind")? != (if public { "public" } else { "unit" })
        || string(review, "repository_root")? != original_root.display().to_string()
        || string(review, "cli_sha256")? != EXIT_CLI_BINARY_AFTER_SHA
        || strings(review, "source_paths")?
            != source_paths.iter().map(|path| (*path).to_owned()).collect::<Vec<_>>()
        || string(review, "review_note")?.trim().is_empty()
    {
        return Err("P17 CLI binary prefix root-review 主鍵不符".into());
    }
    let terminals = array(review, "terminal_records")?;
    if terminals.is_empty()
        || array(review, "artifact_checks")?.is_empty()
        || array(review, "input_basis")?.is_empty()
        || array(review, "checks")?.is_empty()
    {
        return Err("P17 CLI binary prefix root-review 實證紀錄缺失".into());
    }
    let mut unit_terminal = false;
    for item in terminals {
        object(item, &["path", "sha256"])?;
        let path = Path::new(string(item, "path")?);
        let digest = string(item, "sha256")?;
        exit_digest(digest)?;
        console_cli_public_file(path, evidence)?;
        sha(path, digest)?;
        if path == evidence.join("p17-binary-prefix-budget-order-20261011-1/terminal-completion.json")
            && digest == "a113cd5eb32f99604cdcb33fa5a4babe1fecc8befd84715986761ced284e8394"
        {
            unit_terminal = true;
        }
    }
    if !public && !unit_terminal {
        return Err("P17 CLI binary prefix unit terminal attestation 缺失".into());
    }
    Ok(())
}

fn exit_cli_binary_leaf_shape(
    proof: &StrictJsonValue,
    readiness: &Path,
    public: bool,
) -> Result<(), String> {
    object(proof, &["status", "reported_by", "root_review", "readiness_path", "readiness_sha256", "rows"])?;
    if string(proof, "status")? != "PASS"
        || string(proof, "reported_by")? != "primary root"
        || string(proof, "root_review")?.is_empty()
        || string(proof, "readiness_path")? != readiness.display().to_string()
        || string(proof, "readiness_sha256")? != "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb"
        || array(proof, "rows")?.len() != 2
    {
        return Err("P17 CLI binary prefix proof 主鍵／row 數不符".into());
    }
    let mut keys = vec![
        "profile", "command", "cwd", "environment_mode", "environment",
        "exit_code", "matched", "passed", "failed", "ignored", "filtered",
        "log_path", "log_sha256", "running_binary_path", "snapshot_path",
        "snapshot_sha256", "source_inputs",
    ];
    if public {
        keys.extend(["cli_running_binary_path", "cli_snapshot_path", "cli_snapshot_sha256"]);
    }
    for row in array(proof, "rows")? {
        object(row, &keys)?;
    }
    Ok(())
}

fn exit_cli_binary_leaf(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    public: bool,
    cli_version_updated: bool,
) -> Result<(), String> {
    exit_cli_binary_leaf_with_verified(
        original_root, current_root, evidence, update, public, cli_version_updated, None)
}

fn exit_cli_binary_leaf_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    public: bool,
    cli_version_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let leaf = if public { "public" } else { "unit" };
    let proof_dir = evidence.join(EXIT_CLI_BINARY_PROOF_DIR).join(leaf);
    let result = proof_dir.join("result.json");
    let (path_key, sha_key) = if public {
        ("public_proof_path", "public_proof_sha256")
    } else {
        ("unit_proof_path", "unit_proof_sha256")
    };
    if string(update, path_key)? != result.display().to_string()
        || (!public && string(update, sha_key)? != EXIT_CLI_BINARY_UNIT_SHA)
    {
        return Err("P17 CLI binary prefix leaf 路徑不符".into());
    }
    console_cli_public_file(&result, &proof_dir)?;
    sha(&result, string(update, sha_key)?)?;
    let proof = StrictJsonParser::parse(&fs::read_to_string(&result).map_err(|error| error.to_string())?)?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    sha(&readiness, "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb")?;
    exit_cli_binary_leaf_shape(&proof, &readiness, public)?;
    let root_review = proof_dir.join("root-review.json");
    console_cli_public_file(&root_review, &proof_dir)?;
    let root_sha = manifest::sha256(&root_review)?;
    if !public && root_sha != EXIT_CLI_BINARY_UNIT_ROOT_SHA {
        return Err("P17 CLI binary prefix unit root-review SHA 不符".into());
    }
    let claim = string(&proof, "root_review")?;
    if !claim.contains(&root_review.display().to_string()) || !claim.contains(&root_sha) {
        return Err("P17 CLI binary prefix root-review 引用不符".into());
    }
    let readiness_value = StrictJsonParser::parse(
        &fs::read_to_string(&readiness).map_err(|error| error.to_string())?,
    )?;
    let environment = field(field(&readiness_value, "phase_launch")?, "required_environment")?;
    exit_safe_cargo(evidence)?;
    let source_paths = if public {
        vec![
            EXIT_CLI_BINARY_TEST_PATH,
            EXIT_CLI_BINARY_PATH,
            "crates/rivetlua-runtime/src/vm/mod.rs",
            "crates/rivetlua/src/lib.rs",
            EXIT_PARSER_PATH,
            "crates/rivetlua-core/src/bytecode/input.rs",
        ]
    } else {
        vec![
            EXIT_CLI_BINARY_PATH,
            "crates/rivetlua-runtime/src/vm/mod.rs",
            "crates/rivetlua/src/lib.rs",
            EXIT_PARSER_PATH,
        ]
    };
    let source_digests = if public {
        vec![
            EXIT_CLI_BINARY_TEST_SHA,
            EXIT_CLI_BINARY_AFTER_SHA,
            "fcf16b4b24c26aef22da6d653b1b19a5412fbeb852ec25b850b19edaba33c088",
            "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
            EXIT_PARSER_AFTER_SHA,
            "1495457f26a517b8a89014b1b3bb227289605e01b325f8fcbada323dd95a3959",
        ]
    } else {
        vec![
            EXIT_CLI_BINARY_AFTER_SHA,
            "fcf16b4b24c26aef22da6d653b1b19a5412fbeb852ec25b850b19edaba33c088",
            "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
            EXIT_PARSER_AFTER_SHA,
        ]
    };
    let root_value = StrictJsonParser::parse(
        &fs::read_to_string(&root_review).map_err(|error| error.to_string())?,
    )?;
    exit_cli_binary_root_review_shape(&root_value, original_root, evidence, public, &source_paths)?;
    let names = if public {
        vec![
            "p17_binary_file_prefix_loads_dumped_chunk",
            "p17_binary_file_prefix_keeps_source_and_binary_errors",
        ]
    } else {
        vec!["cli_unit_tests::p17_binary_file_prefix_load_preserves_binary_validation"]
    };
    let matched = if public { 2 } else { 1 };
    let filtered = if public { 0 } else { 37 };
    for (row, profile) in array(&proof, "rows")?.iter().zip(["lua55", "lua54"]) {
        let features = if profile == "lua55" { "native-lua55" } else { "native-lua54,default-lua54" };
        let mut command = vec![
            EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-cli",
            "--no-default-features", "--features", features,
        ];
        if public {
            command.extend(["--test", "p17_binary_prefix", "--", "--nocapture", "--test-threads=1"]);
        } else {
            command.extend([
                "--lib", "cli_unit_tests::p17_binary_file_prefix_load_preserves_binary_validation",
                "--", "--exact", "--nocapture", "--test-threads=1",
            ]);
        }
        if string(row, "profile")? != profile
            || strings(row, "command")? != command.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>()
            || string(row, "cwd")? != original_root.display().to_string()
            || string(row, "environment_mode")? != "env -i"
            || canonical_json(field(row, "environment")?) != canonical_json(environment)
            || integer(row, "exit_code")? != 0
            || integer(row, "matched")? != matched
            || integer(row, "passed")? != matched
            || integer(row, "failed")? != 0
            || integer(row, "ignored")? != 0
            || integer(row, "filtered")? != filtered
        {
            return Err(format!("P17 CLI binary prefix {leaf}/{profile} 命令／count 不符"));
        }
        let log = Path::new(string(row, "log_path")?);
        if log != proof_dir.join(format!("green-{profile}.log")) {
            return Err("P17 CLI binary prefix log 路徑不符".into());
        }
        console_cli_public_file(log, &proof_dir)?;
        sha(log, string(row, "log_sha256")?)?;
        let target = Path::new(string(environment, "CARGO_TARGET_DIR")?);
        let running = Path::new(string(row, "running_binary_path")?);
        let prefix = if public { "p17_binary_prefix-" } else { "rivetlua_cli-" };
        if running.parent() != Some(target.join("debug/deps").as_path())
            || !running.file_name().and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with(prefix))
        {
            return Err("P17 CLI binary prefix driver 身分不符".into());
        }
        let driver_sha = string(row, "snapshot_sha256")?;
        exit_digest(driver_sha)?;
        let snapshot = Path::new(string(row, "snapshot_path")?);
        if snapshot != proof_dir.join(format!("executed-{profile}-{driver_sha}")) {
            return Err("P17 CLI binary prefix driver snapshot 路徑不符".into());
        }
        console_cli_public_file(snapshot, &proof_dir)?;
        sha(snapshot, driver_sha)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 CLI binary prefix driver 權限不符".into());
        }
        report::mach_type(snapshot, "EXECUTE")?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(&body, &names, !public)?;
        let runner_name = if public { "tests/p17_binary_prefix.rs" } else { "unittests src/lib.rs" };
        if counts.matched != matched as u32 || counts.passed != matched as u32
            || counts.failed != 0 || counts.ignored != 0
            || (filtered != 0 && !body.contains("37 filtered out;"))
            || !body.contains(&format!("Running {runner_name} ({})", running.display()))
        {
            return Err("P17 CLI binary prefix log 結果／driver 不符".into());
        }
        if public {
            let cli_running = Path::new(string(row, "cli_running_binary_path")?);
            let cli_sha = string(row, "cli_snapshot_sha256")?;
            exit_digest(cli_sha)?;
            let cli_snapshot = Path::new(string(row, "cli_snapshot_path")?);
            if cli_running != target.join("debug/rivetlua")
                || cli_snapshot != proof_dir.join(format!("cli-executed-{profile}-{cli_sha}"))
            {
                return Err("P17 CLI binary prefix product binary 路徑不符".into());
            }
            console_cli_public_file(cli_snapshot, &proof_dir)?;
            sha(cli_snapshot, cli_sha)?;
            if fs::metadata(cli_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
                return Err("P17 CLI binary prefix product binary 權限不符".into());
            }
            report::mach_type(cli_snapshot, "EXECUTE")?;
        }
        let sources = array(row, "source_inputs")?;
        if sources.len() != source_paths.len() {
            return Err("P17 CLI binary prefix source 數量不符".into());
        }
        for (index, ((source, relative), digest)) in sources.iter().zip(&source_paths).zip(&source_digests).enumerate() {
            object(source, &["path", "sha256", "snapshot_path"])?;
            let source_snapshot = Path::new(string(source, "snapshot_path")?);
            if string(source, "path")? != original_root.join(relative).display().to_string()
                || string(source, "sha256")? != *digest
                || source_snapshot != proof_dir.join(format!(
                    "{index}-{}",
                    Path::new(relative).file_name().unwrap().to_string_lossy(),
                ))
            {
                return Err("P17 CLI binary prefix source 身分／順序不符".into());
            }
            console_cli_public_file(source_snapshot, &proof_dir)?;
            sha(source_snapshot, digest)?;
            if fs::metadata(source_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
                return Err("P17 CLI binary prefix source snapshot 權限不符".into());
            }
            if cli_version_updated && *relative == EXIT_CLI_BINARY_PATH {
                exit_cli_lib_historical_input(
                    original_root, source, source_snapshot, EXIT_CLI_BINARY_AFTER_SHA,
                )?;
            } else {
                exit_warn_historical_source_with_verified(
                    original_root, current_root, evidence, relative, digest, Some(source_snapshot),
                    verified,
                )?;
            }
        }
    }
    Ok(())
}

fn exit_cli_unit_test_only_update(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_binary_updated: bool,
) -> Result<(), String> {
    exit_cli_unit_test_only_update_with_verified(
        original_root, current_root, evidence, update, cli_binary_updated, None)
}

fn exit_cli_unit_test_only_update_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_binary_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let relative = "crates/rivetlua-cli/src/lib.rs";
    let before = evidence.join(EXIT_PUBLIC_FINAL_DIR).join("lua-init/3-lib.rs");
    let current = if cli_binary_updated {
        evidence.join(EXIT_CLI_UNIT_GREEN_DIR).join("0-lib.rs")
    } else {
        current_root.join(relative)
    };
    let diff = evidence.join(format!(
        "p17-phase-cli-unit-test-only-impact-{}.diff",
        relative.replace('/', "__"),
    ));
    let failed = evidence.join("p17-exit-final-capture-20261011-1/row-25.log");
    const FAILED_SHA: &str = "87813dea341ba1592552a18395b2a854c44e155b3371a0ca5c9834d13d82d522";
    if string(update, "path")? != relative
        || string(update, "before_sha256")? != EXIT_CLI_LIB_SHA
        || string(update, "after_sha256")? != EXIT_CLI_LIB_TEST_ONLY_SHA
        || string(update, "before_snapshot_path")? != before.display().to_string()
        || string(update, "diff_path")? != diff.display().to_string()
        || string(update, "failed_log_path")? != failed.display().to_string()
        || string(update, "failed_log_sha256")? != FAILED_SHA
    {
        return Err("P17 CLI unit test-only 更新身分不符".into());
    }
    console_cli_public_file(&before, &evidence.join(EXIT_PUBLIC_FINAL_DIR))?;
    sha(&before, EXIT_CLI_LIB_SHA)?;
    if cli_binary_updated {
        console_cli_public_file(&current, &evidence.join(EXIT_CLI_UNIT_GREEN_DIR))?;
    }
    sha(&current, EXIT_CLI_LIB_TEST_ONLY_SHA)?;
    exit_cli_unit_test_only_delta(
        &fs::read(&before).map_err(|error| error.to_string())?,
        &fs::read(&current).map_err(|error| error.to_string())?,
    )?;
    let change = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"before_sha256\":{},\"after_sha256\":{},\"diff_path\":{},\"diff_sha256\":{}}}",
        report::q(relative),
        report::q(EXIT_CLI_LIB_SHA),
        report::q(EXIT_CLI_LIB_TEST_ONLY_SHA),
        report::q(&diff.display().to_string()),
        report::q(string(update, "diff_sha256")?),
    ))?;
    exit_raw_diff(
        current_root,
        original_root,
        evidence,
        &change,
        "cli-unit-test-only",
        relative,
        &before,
        Some(EXIT_CLI_LIB_SHA),
        &current,
        EXIT_CLI_LIB_TEST_ONLY_SHA,
    )?;
    console_cli_public_file(&failed, &evidence.join("p17-exit-final-capture-20261011-1"))?;
    sha(&failed, FAILED_SHA)?;
    let body = fs::read_to_string(&failed).map_err(|error| error.to_string())?;
    if !body.contains("running 1 test\n")
        || !body.contains("test cli_unit_tests::p17_interactive_locals_warning ... ")
        || !body.contains("assertion failed: stdout[version.len()..].iter().all")
        || !body.contains("test result: FAILED. 0 passed; 1 failed; 0 ignored;")
    {
        return Err("P17 CLI unit test-only 真實紅燈 log 不符".into());
    }
    exit_cli_unit_test_only_green_with_verified(
        original_root, current_root, evidence, update, cli_binary_updated, verified)?;
    Ok(())
}

fn exit_cli_unit_test_only_green(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_binary_updated: bool,
) -> Result<(), String> {
    exit_cli_unit_test_only_green_with_verified(
        original_root, current_root, evidence, update, cli_binary_updated, None)
}

fn exit_cli_unit_test_only_green_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_binary_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let directory = evidence.join(EXIT_CLI_UNIT_GREEN_DIR);
    let result = directory.join("result.json");
    if string(update, "green_proof_path")? != result.display().to_string()
        || string(update, "green_proof_sha256")? != EXIT_CLI_UNIT_GREEN_SHA
    {
        return Err("P17 CLI unit test-only green proof 路徑不符".into());
    }
    console_cli_public_file(&result, &directory)?;
    sha(&result, EXIT_CLI_UNIT_GREEN_SHA)?;
    let proof = StrictJsonParser::parse(
        &fs::read_to_string(&result).map_err(|error| error.to_string())?,
    )?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    const READINESS_SHA: &str = "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb";
    sha(&readiness, READINESS_SHA)?;
    exit_public_cli_leaf_shape(&proof, &readiness, true)?;
    let review = directory.join("root-review.json");
    console_cli_public_file(&review, &directory)?;
    sha(&review, EXIT_CLI_UNIT_ROOT_REVIEW_SHA)?;
    if !string(&proof, "root_review")?.contains(&review.display().to_string())
        || !string(&proof, "root_review")?.contains(EXIT_CLI_UNIT_ROOT_REVIEW_SHA)
    {
        return Err("P17 CLI unit test-only root review 引用不符".into());
    }
    let readiness_value = StrictJsonParser::parse(
        &fs::read_to_string(&readiness).map_err(|error| error.to_string())?,
    )?;
    let environment = field(field(&readiness_value, "phase_launch")?, "required_environment")?;
    let specs = [("lua55", 25), ("lua54", 26)];
    let paths = [
        "crates/rivetlua-cli/src/lib.rs",
        "crates/rivetlua-runtime/src/vm/mod.rs",
        "crates/rivetlua/src/lib.rs",
        EXIT_PARSER_PATH,
    ];
    let digests = [
        EXIT_CLI_LIB_TEST_ONLY_SHA,
        "fcf16b4b24c26aef22da6d653b1b19a5412fbeb852ec25b850b19edaba33c088",
        "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
        EXIT_PARSER_AFTER_SHA,
    ];
    let ready_rows = array(&readiness_value, "regressions")?;
    for (row, (profile, index)) in array(&proof, "rows")?.iter().zip(specs) {
        let expected = ready_rows.get(index).ok_or("P17 CLI unit test-only readiness row 缺失")?;
        let command = strings(expected, "expected_command")?;
        if string(row, "profile")? != profile
            || strings(row, "command")? != command
            || string(row, "cwd")? != original_root.display().to_string()
            || string(row, "environment_mode")? != "env -i"
            || canonical_json(field(row, "environment")?) != canonical_json(environment)
            || integer(row, "exit_code")? != 0
            || integer(row, "matched")? != 1
            || integer(row, "passed")? != 1
            || integer(row, "failed")? != 0
            || integer(row, "ignored")? != 0
            || integer(row, "filtered")? != 36
        {
            return Err(format!("P17 CLI unit test-only {profile} 命令／count 不符"));
        }
        let log = Path::new(string(row, "log_path")?);
        if log != directory.join(format!("green-{profile}.log")) {
            return Err("P17 CLI unit test-only green log 路徑不符".into());
        }
        console_cli_public_file(log, &directory)?;
        sha(log, string(row, "log_sha256")?)?;
        let running = Path::new(string(row, "running_binary_path")?);
        let target_dir = Path::new(string(environment, "CARGO_TARGET_DIR")?);
        if running.parent() != Some(target_dir.join("debug/deps").as_path())
            || !running.file_name().and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with("rivetlua_cli-"))
        {
            return Err("P17 CLI unit test-only driver 身分不符".into());
        }
        let driver_sha = string(row, "snapshot_sha256")?;
        let snapshot = Path::new(string(row, "snapshot_path")?);
        if snapshot != directory.join(format!("executed-{profile}-{driver_sha}")) {
            return Err("P17 CLI unit test-only driver snapshot 路徑不符".into());
        }
        console_cli_public_file(snapshot, &directory)?;
        sha(snapshot, driver_sha)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 CLI unit test-only driver 權限不符".into());
        }
        report::mach_type(snapshot, "EXECUTE")?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        let selector = "cli_unit_tests::p17_interactive_locals_warning";
        let (counts, _) = parse_named_log_with_filter(&body, &[selector], true)?;
        if counts.matched != 1 || counts.passed != 1 || counts.failed != 0 || counts.ignored != 0
            || !body.contains("36 filtered out;")
            || !body.contains(&format!("Running unittests src/lib.rs ({})", running.display()))
        {
            return Err("P17 CLI unit test-only green log 測試／driver 不符".into());
        }
        let inputs = array(row, "source_inputs")?;
        if inputs.len() != paths.len() {
            return Err("P17 CLI unit test-only 來源數量不符".into());
        }
        for (source_index, ((source, relative), digest)) in inputs.iter().zip(paths).zip(digests).enumerate() {
            object(source, &["path", "sha256", "snapshot_path"])?;
            let expected_snapshot = directory.join(format!(
                "{source_index}-{}",
                Path::new(relative).file_name().unwrap().to_string_lossy(),
            ));
            let source_snapshot = Path::new(string(source, "snapshot_path")?);
            if string(source, "path")? != original_root.join(relative).display().to_string()
                || string(source, "sha256")? != digest
                || source_snapshot != expected_snapshot
            {
                return Err("P17 CLI unit test-only 來源身分／順序不符".into());
            }
            console_cli_public_file(source_snapshot, &directory)?;
            sha(source_snapshot, digest)?;
            if fs::metadata(source_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
                return Err("P17 CLI unit test-only 來源 snapshot 權限不符".into());
            }
            if source_index == 0 && cli_binary_updated {
                exit_cli_lib_historical_input(
                    original_root,
                    source,
                    source_snapshot,
                    EXIT_CLI_LIB_TEST_ONLY_SHA,
                )?;
            } else {
                exit_warn_historical_source_with_verified(
                    original_root, current_root, evidence, relative, digest, Some(source_snapshot),
                    verified,
                )?;
            }
        }
    }
    Ok(())
}

fn exit_cli_exit_repl_test_only_update(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_binary_updated: bool,
) -> Result<(), String> {
    exit_cli_exit_repl_test_only_update_with_verified(
        original_root, current_root, evidence, update, cli_binary_updated, None)
}

fn exit_cli_exit_repl_test_only_update_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: &StrictJsonValue,
    cli_binary_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let before = evidence.join("p17-exit-cli-os-exit-test-only-20261011-1/before-p17_os_exit.rs");
    let current = current_root.join(EXIT_CLI_EXIT_TEST_PATH);
    let diff = evidence.join("p17-phase-cli-exit-repl-test-only-impact-crates__rivetlua-cli__tests__p17_os_exit.rs.diff");
    let failed = evidence.join("p17-exit-final-capture-20261011-2/row-27.log");
    const FAILED_SHA: &str = "35cce37f509c05dccc9d593fe7bfba9bf19947233703974afa4938f8d4d60a2e";
    let green_dir = evidence.join(EXIT_CLI_EXIT_GREEN_DIR);
    let green = green_dir.join("result.json");
    if string(update, "path")? != EXIT_CLI_EXIT_TEST_PATH
        || string(update, "before_sha256")? != EXIT_CLI_EXIT_TEST_BEFORE_SHA
        || string(update, "after_sha256")? != EXIT_CLI_EXIT_TEST_AFTER_SHA
        || string(update, "before_snapshot_path")? != before.display().to_string()
        || string(update, "diff_path")? != diff.display().to_string()
        || string(update, "failed_log_path")? != failed.display().to_string()
        || string(update, "failed_log_sha256")? != FAILED_SHA
        || string(update, "green_proof_path")? != green.display().to_string()
        || string(update, "green_proof_sha256")? != EXIT_CLI_EXIT_GREEN_SHA
    {
        return Err("P17 CLI os.exit REPL test-only 更新身分不符".into());
    }
    console_cli_public_file(&before, &evidence.join("p17-exit-cli-os-exit-test-only-20261011-1"))?;
    sha(&before, EXIT_CLI_EXIT_TEST_BEFORE_SHA)?;
    sha(&current, EXIT_CLI_EXIT_TEST_AFTER_SHA)?;
    exit_cli_exit_repl_test_only_delta(
        &fs::read(&before).map_err(|error| error.to_string())?,
        &fs::read(&current).map_err(|error| error.to_string())?,
    )?;
    let change = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"before_sha256\":{},\"after_sha256\":{},\"diff_path\":{},\"diff_sha256\":{}}}",
        report::q(EXIT_CLI_EXIT_TEST_PATH),
        report::q(EXIT_CLI_EXIT_TEST_BEFORE_SHA),
        report::q(EXIT_CLI_EXIT_TEST_AFTER_SHA),
        report::q(&diff.display().to_string()),
        report::q(string(update, "diff_sha256")?),
    ))?;
    exit_raw_diff(
        current_root,
        original_root,
        evidence,
        &change,
        "cli-exit-repl-test-only",
        EXIT_CLI_EXIT_TEST_PATH,
        &before,
        Some(EXIT_CLI_EXIT_TEST_BEFORE_SHA),
        &current,
        EXIT_CLI_EXIT_TEST_AFTER_SHA,
    )?;
    console_cli_public_file(&failed, &evidence.join("p17-exit-final-capture-20261011-2"))?;
    sha(&failed, FAILED_SHA)?;
    let red = fs::read_to_string(&failed).map_err(|error| error.to_string())?;
    if !red.contains("running 4 tests\n")
        || !red.contains("test p17_exit_cli_control_flow ... ")
        || !red.contains("exit_stops_repl_input stdout 不符")
        || !red.contains("test result: FAILED. 3 passed; 1 failed; 0 ignored;")
    {
        return Err("P17 CLI os.exit REPL test-only 真實紅燈 log 不符".into());
    }
    console_cli_public_file(&green, &green_dir)?;
    sha(&green, EXIT_CLI_EXIT_GREEN_SHA)?;
    let proof = StrictJsonParser::parse(&fs::read_to_string(&green).map_err(|error| error.to_string())?)?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    sha(&readiness, "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb")?;
    exit_public_cli_leaf_shape(&proof, &readiness, true)?;
    let root_review = green_dir.join("root-review.json");
    console_cli_public_file(&root_review, &green_dir)?;
    sha(&root_review, EXIT_CLI_EXIT_ROOT_REVIEW_SHA)?;
    if !string(&proof, "root_review")?.contains(&root_review.display().to_string())
        || !string(&proof, "root_review")?.contains(EXIT_CLI_EXIT_ROOT_REVIEW_SHA)
    {
        return Err("P17 CLI os.exit REPL test-only root review 引用不符".into());
    }
    let readiness_value = StrictJsonParser::parse(
        &fs::read_to_string(&readiness).map_err(|error| error.to_string())?,
    )?;
    let environment = field(field(&readiness_value, "phase_launch")?, "required_environment")?;
    let ready_rows = array(&readiness_value, "regressions")?;
    let source_paths = [
        EXIT_CLI_EXIT_TEST_PATH,
        "crates/rivetlua-runtime/src/vm/mod.rs",
        "crates/rivetlua/src/lib.rs",
        "crates/rivetlua-cli/src/lib.rs",
        EXIT_PARSER_PATH,
    ];
    let source_digests = [
        EXIT_CLI_EXIT_TEST_AFTER_SHA,
        "fcf16b4b24c26aef22da6d653b1b19a5412fbeb852ec25b850b19edaba33c088",
        "5f53891e8d5a3c84eef81a07560b71ef1e2e2dd02b41177a29b81968719a00ff",
        EXIT_CLI_LIB_TEST_ONLY_SHA,
        EXIT_PARSER_AFTER_SHA,
    ];
    let selectors = [
        "p17_exit_status_and_arguments",
        "p17_exit_uncatchable_boundaries",
        "p17_exit_close_lifecycle",
        "p17_exit_cli_control_flow",
    ];
    for (row, (profile, index)) in array(&proof, "rows")?.iter().zip([
        ("lua55-i64f64", 27),
        ("lua54-i64f64", 28),
    ]) {
        let spec = ready_rows.get(index).ok_or("P17 CLI os.exit readiness row 缺失")?;
        if string(row, "profile")? != profile
            || strings(row, "command")? != strings(spec, "expected_command")?
            || string(row, "cwd")? != original_root.display().to_string()
            || string(row, "environment_mode")? != "env -i"
            || canonical_json(field(row, "environment")?) != canonical_json(environment)
            || integer(row, "exit_code")? != 0
            || integer(row, "matched")? != 4
            || integer(row, "passed")? != 4
            || integer(row, "failed")? != 0
            || integer(row, "ignored")? != 0
            || integer(row, "filtered")? != 0
        {
            return Err(format!("P17 CLI os.exit {profile} green 命令／count 不符"));
        }
        let short = if index == 27 { "lua55" } else { "lua54" };
        let log = Path::new(string(row, "log_path")?);
        if log != green_dir.join(format!("green-{short}.log")) {
            return Err("P17 CLI os.exit green log 路徑不符".into());
        }
        console_cli_public_file(log, &green_dir)?;
        sha(log, string(row, "log_sha256")?)?;
        let running = Path::new(string(row, "running_binary_path")?);
        let target_dir = Path::new(string(environment, "CARGO_TARGET_DIR")?);
        if running.parent() != Some(target_dir.join("debug/deps").as_path())
            || !running.file_name().and_then(|part| part.to_str())
                .is_some_and(|part| part.starts_with("p17_os_exit-"))
        {
            return Err("P17 CLI os.exit driver 路徑不符".into());
        }
        let driver_sha = string(row, "snapshot_sha256")?;
        let snapshot = Path::new(string(row, "snapshot_path")?);
        if snapshot != green_dir.join(format!("executed-{short}-{driver_sha}")) {
            return Err("P17 CLI os.exit driver 快照路徑不符".into());
        }
        console_cli_public_file(snapshot, &green_dir)?;
        sha(snapshot, driver_sha)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 CLI os.exit driver 權限不符".into());
        }
        report::mach_type(snapshot, "EXECUTE")?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_native_progress(
            &body,
            &selectors,
            true,
            Some((profile, evidence)),
        )?;
        if counts.matched != 4 || counts.passed != 4 || counts.failed != 0 || counts.ignored != 0
            || !body.contains("0 filtered out;")
            || !body.contains(&format!("Running tests/p17_os_exit.rs ({})", running.display()))
            || !body.contains(&format!("P17_EXIT_NATIVE_BUILD profile={profile}"))
        {
            return Err("P17 CLI os.exit green log 測試／driver 不符".into());
        }
        let inputs = array(row, "source_inputs")?;
        if inputs.len() != source_paths.len() {
            return Err("P17 CLI os.exit green source 數量不符".into());
        }
        for (source_index, ((source, relative), digest)) in inputs.iter().zip(source_paths).zip(source_digests).enumerate() {
            object(source, &["path", "sha256", "snapshot_path"])?;
            let expected_snapshot = green_dir.join(format!(
                "{source_index}-{}",
                Path::new(relative).file_name().unwrap().to_string_lossy(),
            ));
            let source_snapshot = Path::new(string(source, "snapshot_path")?);
            if string(source, "path")? != original_root.join(relative).display().to_string()
                || string(source, "sha256")? != digest
                || source_snapshot != expected_snapshot
            {
                return Err("P17 CLI os.exit green source 身分／順序不符".into());
            }
            console_cli_public_file(source_snapshot, &green_dir)?;
            sha(source_snapshot, digest)?;
            if fs::metadata(source_snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o444 {
                return Err("P17 CLI os.exit green source 權限不符".into());
            }
            if source_index == 3 && cli_binary_updated {
                exit_cli_lib_historical_input(
                    original_root,
                    source,
                    source_snapshot,
                    EXIT_CLI_LIB_TEST_ONLY_SHA,
                )?;
            } else {
                exit_warn_historical_source_with_verified(
                    original_root, current_root, evidence, relative, digest, Some(source_snapshot),
                    verified,
                )?;
            }
        }
    }
    Ok(())
}

fn exit_parser_update_shape(
    update: &StrictJsonValue,
    evidence: &Path,
    after_sha: &str,
) -> Result<(), String> {
    object(
        update,
        &[
            "gate18_report_path",
            "gate18_report_sha256",
            "before_snapshot_path",
            "change",
            "unit_log_sha256",
            "contract_log_sha256",
            "root_verified_path",
            "root_verified_sha256",
        ],
    )?;
    let gate18 = evidence.join("p17-phase-gate18-1791695119443493000/phase-report-after.json");
    let before = evidence.join(EXIT_PARSER_EVIDENCE_DIR).join("parser-mod-before.rs");
    let root_verified = evidence.join("p17-parser-root-verified-1791696490264915000/result.json");
    let diff = evidence.join(format!(
        "p17-phase-parser-update-impact-{}.diff",
        EXIT_PARSER_PATH.replace('/', "__")
    ));
    if string(update, "gate18_report_path")? != gate18.display().to_string()
        || string(update, "gate18_report_sha256")? != EXIT_GATE18_REPORT_SHA
        || string(update, "before_snapshot_path")? != before.display().to_string()
        || string(update, "root_verified_path")? != root_verified.display().to_string()
        || string(update, "root_verified_sha256")? != EXIT_PARSER_ROOT_PROOF_SHA
        || after_sha == EXIT_PARSER_BEFORE_SHA
    {
        return Err("P17 parser update 前後來源身分不符".into());
    }
    exit_digest(after_sha)?;
    console_change_identity(
        field(update, "change")?,
        EXIT_PARSER_PATH,
        Some(EXIT_PARSER_BEFORE_SHA),
        after_sha,
        &diff,
    )?;
    exit_digest(string(field(update, "change")?, "diff_sha256")?)?;
    for key in ["unit_log_sha256", "contract_log_sha256"] {
        exit_digest(string(update, key)?)?;
    }
    Ok(())
}

fn exit_parser_update(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    update: Option<&StrictJsonValue>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let parser = current_root.join(EXIT_PARSER_PATH);
    let Some(update) = update else {
        return sha(&parser, EXIT_PARSER_BEFORE_SHA);
    };
    let historical_after = if let Some(verified) = verified {
        verified.check(current_root, evidence)?;
        let mapped = current_repair_sha(EXIT_PARSER_PATH, EXIT_PARSER_AFTER_SHA,
            verified.repair_active, verified.core_successor_active,
            verified.heap_successor_active, verified.product_successor_active);
        if verified.source_shas.get(&parser).map(String::as_str) != Some(mapped) {
            return Err("P17 parser update final context source SHA 不符".into());
        }
        sha(&parser, mapped)?;
        if verified.repair_active {
            let parent_path = evidence.join(FINAL_REPAIR_PARENT_FILE);
            sha(&parent_path, FINAL_REPAIR_PARENT_SHA)?;
            let parent = StrictJsonParser::parse(&fs::read_to_string(&parent_path)
                .map_err(|error| error.to_string())?)?;
            let recorded_root = Path::new(string(&parent, "repository_root")?);
            let rows = array(&parent, "source_files")?.iter().filter(|row| {
                string(row, "path").ok() == Some(recorded_root.join(EXIT_PARSER_PATH)
                    .display().to_string().as_str())
            }).collect::<Vec<_>>();
            if rows.len() != 1 || string(rows[0], "sha256")? != EXIT_PARSER_AFTER_SHA {
                return Err("P17 parser update F64 歷史 row 不符".into());
            }
            let snapshot = Path::new(string(rows[0], "snapshot_path")?);
            console_cli_public_file(snapshot, evidence)?;
            sha(snapshot, EXIT_PARSER_AFTER_SHA)?;
            if fs::metadata(snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444 {
                return Err("P17 parser update F64 歷史快照非 0444".into());
            }
            snapshot.to_path_buf()
        } else {
            parser.clone()
        }
    } else {
        parser.clone()
    };
    let after_sha = manifest::sha256(&historical_after)?;
    exit_parser_update_shape(update, evidence, &after_sha)?;
    let gate18 = Path::new(string(update, "gate18_report_path")?);
    console_cli_public_file(gate18, &evidence.join("p17-phase-gate18-1791695119443493000"))?;
    sha(gate18, EXIT_GATE18_REPORT_SHA)?;
    let report = StrictJsonParser::parse(
        &fs::read_to_string(gate18).map_err(|error| error.to_string())?,
    )?;
    if string(&report, "phase")? != "P17" || string(&report, "status")? != "FAIL" {
        return Err("P17 parser update Gate18 報告身分不符".into());
    }
    let historical_path = original_root.join(EXIT_PARSER_PATH).display().to_string();
    let historical = array(&report, "source_inputs")?
        .iter()
        .filter(|item| string(item, "path").ok() == Some(historical_path.as_str()))
        .collect::<Vec<_>>();
    if historical.len() != 1
        || string(historical[0], "sha256")? != EXIT_PARSER_BEFORE_SHA
    {
        return Err("P17 parser update Gate18 舊來源不符".into());
    }
    let before = Path::new(string(update, "before_snapshot_path")?);
    let parser_evidence = evidence.join(EXIT_PARSER_EVIDENCE_DIR);
    console_cli_public_file(before, &parser_evidence)?;
    sha(before, EXIT_PARSER_BEFORE_SHA)?;
    let root_verified = Path::new(string(update, "root_verified_path")?);
    console_cli_public_file(
        root_verified,
        &evidence.join("p17-parser-root-verified-1791696490264915000"),
    )?;
    sha(root_verified, EXIT_PARSER_ROOT_PROOF_SHA)?;
    let verified = StrictJsonParser::parse(
        &fs::read_to_string(root_verified).map_err(|error| error.to_string())?,
    )?;
    if string(&verified, "schema")? != "rivetlua-p17-parser-root-reviewed-v1"
        || string(&verified, "status")? != "LOCAL_REGRESSION_PASS_NOT_PHASE_PASS"
        || string(&verified, "before_snapshot_path")? != before.display().to_string()
        || string(&verified, "before_sha256")? != EXIT_PARSER_BEFORE_SHA
        || string(&verified, "after_sha256")? != after_sha
        || array(&verified, "rows")?.len() != 2
    {
        return Err("P17 parser update root proof 身分不符".into());
    }
    for (row, (log_name, digest_key, matched)) in array(&verified, "rows")?.iter().zip([
        ("green-unit.log", "unit_log_sha256", 2),
        ("green-existing-contract.log", "contract_log_sha256", 1),
    ]) {
        let sources = array(row, "source_inputs")?;
        if string(row, "log_path")? != parser_evidence.join(log_name).display().to_string()
            || string(row, "log_sha256")? != string(update, digest_key)?
            || integer(row, "exit_code")? != 0
            || integer(row, "matched")? != matched
            || integer(row, "passed")? != matched
            || integer(row, "failed")? != 0
            || integer(row, "ignored")? != 0
            || sources.len() != 1
            || string(&sources[0], "path")? != historical_path.as_str()
            || string(&sources[0], "sha256")? != after_sha.as_str()
        {
            return Err("P17 parser update root regression proof 不符".into());
        }
    }
    exit_raw_diff(
        current_root,
        original_root,
        evidence,
        field(update, "change")?,
        "parser-update",
        EXIT_PARSER_PATH,
        before,
        Some(EXIT_PARSER_BEFORE_SHA),
        &historical_after,
        &after_sha,
    )?;
    for (name, key, selectors) in [
        (
            "green-unit.log",
            "unit_log_sha256",
            &[
                "parser::tests::nested_return_at_eof_reports_missing_block_terminator",
                "parser::tests::return_last_contract_still_accepts_root_and_rejects_following_statement",
            ][..],
        ),
        (
            "green-existing-contract.log",
            "contract_log_sha256",
            &["public_parser_requires_return_to_end_block"][..],
        ),
    ] {
        let log = parser_evidence.join(name);
        console_cli_public_file(&log, &parser_evidence)?;
        sha(&log, string(update, key)?)?;
        let body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(&body, selectors, true)?;
        if counts.matched != selectors.len() as u32
            || counts.passed != selectors.len() as u32
            || counts.failed != 0
            || counts.ignored != 0
        {
            return Err("P17 parser update regression log 不符".into());
        }
    }
    Ok(())
}

fn exit_new_test_shape(value: &StrictJsonValue) -> Result<(), String> {
    let tests = array(value, "new_tests")?;
    if tests.len() != EXIT_NEW_TESTS.len() {
        return Err("P17 Exit 新測試數量不符".into());
    }
    for (item, relative) in tests.iter().zip(EXIT_NEW_TESTS) {
        object(
            item,
            &[
                "path",
                "before_sha256",
                "after_sha256",
                "diff_path",
                "diff_sha256",
            ],
        )?;
        if string(item, "path")? != relative
            || !matches!(field(item, "before_sha256")?, StrictJsonValue::Null)
        {
            return Err(format!("P17 Exit 新測試原始身分不符：{relative}"));
        }
        exit_digest(string(item, "after_sha256")?)?;
        exit_digest(string(item, "diff_sha256")?)?;
    }
    Ok(())
}

fn exit_review_baselines(
    root: &Path,
    evidence: &Path,
) -> Result<ExitReview, String> {
    let (product_baseline, mut pre_exit) = exit_product_baseline(root, evidence)?;
    let (proof_baseline, proof) = exit_proof_baseline(root, evidence)?;
    let v1_review_path = evidence.join("p17-phase-assert-warning-source-impact-review.json");
    sha(&v1_review_path, EXIT_ACCEPTED_V1_SHA)?;
    let accepted_v1 = StrictJsonParser::parse(
        &fs::read_to_string(&v1_review_path).map_err(|error| error.to_string())?,
    )?;
    for (original, source) in &proof {
        // 舊 review 與 rawdiff 必須仍是當時原始檔；工具和測試源可在其後改動。
        if original == &v1_review_path.display().to_string() || original.ends_with(".diff") {
            sha(Path::new(original), &source.before_sha256)?;
        }
    }
    let archive_path = evidence.join("p17-phase-assert-warning-suite-fail/manifest.json");
    sha(&archive_path, EXIT_PHASE_ARCHIVE_SHA)?;
    let archive = StrictJsonParser::parse(
        &fs::read_to_string(&archive_path).map_err(|error| error.to_string())?,
    )?;
    object(
        &archive,
        &[
            "schema",
            "phase_attempt",
            "status",
            "command",
            "formal_report_sha256",
            "formal_receipt_sha256",
            "files",
            "check_summary",
            "next_repair_scope",
        ],
    )?;
    if string(&archive, "schema")? != "rivetlua-p17-phase-failure-archive-v1"
        || string(&archive, "status")? != "FAIL"
        || array(&archive, "files")?.len() != 18
    {
        return Err("P17 Exit phase10 archive 主鍵不符".into());
    }
    let mut archived = BTreeMap::new();
    for file in array(&archive, "files")? {
        object(file, &["original_path", "archived_path", "sha256"])?;
        let original = string(file, "original_path")?;
        let snapshot = PathBuf::from(string(file, "archived_path")?);
        let digest = string(file, "sha256")?;
        if !snapshot.starts_with(evidence.join("p17-phase-assert-warning-suite-fail")) {
            return Err("P17 Exit phase10 snapshot 越界".into());
        }
        sha(&snapshot, digest)?;
        if archived
            .insert(
                original.to_owned(),
                report::HistoricalSource {
                    before_sha256: digest.into(),
                    snapshot,
                },
            )
            .is_some()
        {
            return Err("P17 Exit phase10 snapshot 重複".into());
        }
    }
    let report_key = root.join("target/rivetlua-reports/gate-P17.json");
    let receipt_key = root.join("target/rivetlua-reports/gate-P17.sha256");
    let report_source = archived
        .get(&report_key.display().to_string())
        .ok_or("P17 Exit phase10 report 缺失")?;
    let receipt_source = archived
        .get(&receipt_key.display().to_string())
        .ok_or("P17 Exit phase10 receipt 缺失")?;
    if string(&archive, "formal_report_sha256")? != report_source.before_sha256
        || string(&archive, "formal_receipt_sha256")? != receipt_source.before_sha256
    {
        return Err("P17 Exit phase10 report／receipt SHA 不符".into());
    }
    let old_report = StrictJsonParser::parse(
        &fs::read_to_string(&report_source.snapshot).map_err(|error| error.to_string())?,
    )?;
    let mut old_inputs = BTreeMap::new();
    for item in array(&old_report, "source_inputs")? {
        object(item, &["path", "sha256"])?;
        if old_inputs
            .insert(string(item, "path")?.to_owned(), string(item, "sha256")?.to_owned())
            .is_some()
        {
            return Err("P17 Exit phase10 source 重複".into());
        }
    }
    let mut v1_endpoints = BTreeMap::new();
    for relative in EXIT_PRODUCT_PATHS {
        let pre = pre_exit.get(relative).ok_or("P17 Exit producer 前態缺失")?;
        let old = if matches!(
            relative,
            "crates/rivetlua-runtime/src/heap.rs" | "crates/rivetlua-cli/src/lib.rs"
        ) {
            archived
                .get(&root.join(relative).display().to_string())
                .ok_or("P17 Exit pre-exit 變更舊bytes缺失")?
        } else {
            pre
        };
        if old_inputs.get(&root.join(relative).display().to_string())
            != Some(&old.before_sha256)
        {
            return Err(format!("P17 Exit phase10 source 不符：{relative}"));
        }
        v1_endpoints.insert(
            relative.into(),
            report::HistoricalSource {
                before_sha256: old.before_sha256.clone(),
                snapshot: old.snapshot.clone(),
            },
        );
    }
    for relative in EXIT_TOOL_PATHS.into_iter().take(2) {
        let source = proof
            .get(&root.join(relative).display().to_string())
            .ok_or("P17 Exit 舊工具 snapshot 缺失")?;
        if old_inputs.get(&root.join(relative).display().to_string())
            != Some(&source.before_sha256)
        {
            return Err(format!("P17 Exit 舊工具 source 不符：{relative}"));
        }
        v1_endpoints.insert(
            relative.into(),
            report::HistoricalSource {
                before_sha256: source.before_sha256.clone(),
                snapshot: source.snapshot.clone(),
            },
        );
    }
    let warning_helper = EXIT_TOOL_PATHS[2];
    let (warning_helper_baseline, warning_helper_source) =
        exit_warning_helper_baseline(root, evidence)?;
    exit_warning_helper_backpointer(root, &accepted_v1, &old_inputs)?;
    v1_endpoints.insert(warning_helper.into(), warning_helper_source);
    let warning_test = "crates/rivetlua-runtime/tests/p17_warnings.rs";
    let old_test = proof.get(warning_test).ok_or("P17 Exit v1 warning test 缺失")?;
    let pre_test = proof
        .get(&root.join(warning_test).display().to_string())
        .ok_or("P17 Exit pre-exit warning test 缺失")?;
    if old_inputs.get(&root.join(warning_test).display().to_string())
        != Some(&old_test.before_sha256)
    {
        return Err("P17 Exit phase10 warning test SHA 不符".into());
    }
    v1_endpoints.insert(
        warning_test.into(),
        report::HistoricalSource {
            before_sha256: old_test.before_sha256.clone(),
            snapshot: old_test.snapshot.clone(),
        },
    );
    pre_exit.insert(
        warning_test.into(),
        report::HistoricalSource {
            before_sha256: pre_test.before_sha256.clone(),
            snapshot: pre_test.snapshot.clone(),
        },
    );
    Ok(ExitReview {
        original_root: root.to_path_buf(),
        current_root: root.to_path_buf(),
        input: report::Input { path: String::new(), sha256: String::new() },
        product_baseline,
        proof_baseline,
        warning_helper_baseline,
        phase_archive: report::Input::from_path(&archive_path)?,
        safe_environment: {
            exit_safe_cargo(evidence)?;
            report::Input::from_path(&evidence.join("p17-safe-launch-environment-v1.json"))?
        },
        v1_endpoints,
        producer_before: [None, None],
        pre_exit,
        warn_argument_updated: false,
        ctrl_c_updated: false,
        verified: None,
    })
}

fn exit_review_changes(
    root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    exit: &mut ExitReview,
) -> Result<(), String> {
    let verified = exit.verified.clone();
    let pending_relative = FINAL_DEBUG_SUCCESSOR_PENDING_PATH;
    let pending_effective = if manifest::sha256(&root.join(pending_relative))?
        == FINAL_DEBUG_SUCCESSOR_PENDING_AFTER_SHA
    {
        let checked = verified.as_ref().filter(|context|
            context.check(root, evidence).is_ok());
        let historical = exit.original_root.join(pending_relative);
        if final_source_relocated_source_with_verified(
            &exit.original_root, root, evidence, &historical.display().to_string(),
            FINAL_DEBUG_SUCCESSOR_PENDING_BEFORE_SHA, checked)?
            != PathBuf::from(pending_relative)
        {
            return Err("P17 Exit pending final typed edge 缺失".into());
        }
        let snapshot = evidence.join(
            "p17-host-entry-integrated-source-freeze-20261011-1/23-crates__rivetlua-runtime__src__pending_op.rs");
        console_cli_public_file(
            &snapshot, &evidence.join("p17-host-entry-integrated-source-freeze-20261011-1"))?;
        sha(&snapshot, FINAL_DEBUG_SUCCESSOR_PENDING_BEFORE_SHA)?;
        if fs::metadata(&snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444
        {
            return Err("P17 Exit pending 歷史 snapshot 權限不符".into());
        }
        Some(snapshot)
    } else {
        None
    };
    let stack_effective = if let Some(context) = verified.as_ref()
        .filter(|context| context.product_successor_active) {
        context.check(root, evidence)?;
        if context.source_shas.get(&root.join(PRODUCT_STACK_PATH))
            .map(String::as_str) != Some(PRODUCT_STACK_CURRENT_SHA) {
            return Err("P17 Exit stack current source SHA 不符".into());
        }
        let snapshot = evidence.join(
            "p17-exit-integrated-source-freeze-20261011-3/crates__rivetlua-capi__src__stack.rs");
        console_cli_public_file(&snapshot, evidence)?;
        sha(&snapshot, PRODUCT_STACK_BEFORE_SHA)?;
        if fs::metadata(&snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444 {
            return Err("P17 Exit stack 歷史 snapshot 權限不符".into());
        }
        Some(snapshot)
    } else {
        None
    };
    let effective_product = |relative: &str| {
        if relative == pending_relative && pending_effective.is_some() {
            pending_effective.as_ref().unwrap().clone()
        } else if relative == PRODUCT_STACK_PATH && stack_effective.is_some() {
            stack_effective.as_ref().unwrap().clone()
        } else if relative == EXIT_WARN_VM_PATH && value.get("warn_argument_update").is_some() {
            evidence.join(EXIT_WARN_SOURCE_DIR)
                .join("before-crates__rivetlua-runtime__src__vm__mod.rs")
        } else if value.get("ctrl_c_update").is_some()
            && matches!(relative, EXIT_CTRL_HEAP_PATH | EXIT_CTRL_CLI_PATH)
        {
            evidence.join(EXIT_CTRL_SOURCE_DIR)
                .join(format!("before-{}", relative.replace('/', "__")))
        } else {
            root.join(relative)
        }
    };
    let effective_tool = |relative: &str| -> Result<PathBuf, String> {
        if relative == GC_TOOL_PATH && evidence.join(GC_REVIEW_FILE).exists() {
            gc_before_source_with_verified(root, evidence, relative, verified.as_ref())
        } else if relative == EXIT_TOOL_PATHS[1] {
            let old = exit.v1_endpoints.get(relative).ok_or("P17 Exit report 舊工具缺失")?;
            Ok(exit_report_historical_tool_with_verified(
                root, evidence, relative, old, verified.as_ref())?
                .unwrap_or_else(|| root.join(relative)))
        } else {
            Ok(root.join(relative))
        }
    };
    let pre_exit_paths = [
        "crates/rivetlua-runtime/src/heap.rs",
        "crates/rivetlua-cli/src/lib.rs",
        "crates/rivetlua-runtime/tests/p17_warnings.rs",
    ];
    let changes = array(value, "pre_exit_changes")?;
    if changes.len() != pre_exit_paths.len() {
        return Err("P17 Exit pre-exit changes 數量不符".into());
    }
    for (item, relative) in changes.iter().zip(pre_exit_paths) {
        let old = exit
            .v1_endpoints
            .get(relative)
            .ok_or("P17 Exit v1 source 缺失")?;
        let pre = exit.pre_exit.get(relative).ok_or("P17 Exit pre-exit source 缺失")?;
        if old.before_sha256 == pre.before_sha256 {
            return Err(format!("P17 Exit pre-exit 非實際變更：{relative}"));
        }
        exit_raw_diff(
            root,
            &exit.original_root,
            evidence,
            item,
            "pre-exit",
            relative,
            &old.snapshot,
            Some(&old.before_sha256),
            &pre.snapshot,
            &pre.before_sha256,
        )?;
    }
    let changed = EXIT_PRODUCT_PATHS
        .iter()
        .filter_map(|relative| {
            let previous = exit.pre_exit.get(*relative)?;
            let current = manifest::sha256(&effective_product(relative)).ok()?;
            (current != previous.before_sha256).then_some((*relative, current))
        })
        .collect::<Vec<_>>();
    if changed.is_empty() || changed.len() != array(value, "exit_changes")?.len() {
        return Err("P17 Exit producer changed subset 缺失／多餘／不可讀".into());
    }
    for (item, (relative, current)) in array(value, "exit_changes")?.iter().zip(changed) {
        let pre = exit.pre_exit.get(relative).ok_or("P17 Exit producer baseline 缺失")?;
        exit_raw_diff(
            root,
            &exit.original_root,
            evidence,
            item,
            "exit",
            relative,
            &pre.snapshot,
            Some(&pre.before_sha256),
            &effective_product(relative),
            &current,
        )?;
    }
    for relative in EXIT_PRODUCT_PATHS {
        let pre = exit.pre_exit.get(relative).ok_or("P17 Exit producer baseline 缺失")?;
        if !array(value, "exit_changes")?
            .iter()
            .any(|item| string(item, "path").is_ok_and(|path| path == relative))
        {
            sha(&effective_product(relative), &pre.before_sha256)?;
        }
    }
    let tool_changes = EXIT_TOOL_PATHS
        .iter()
        .map(|relative| {
            let previous = exit.v1_endpoints.get(*relative)
                .ok_or_else(|| format!("P17 Exit 舊工具缺失：{relative}"))?;
            let current = manifest::sha256(&effective_tool(relative)?)?;
            Ok((current != previous.before_sha256).then_some((*relative, current)))
        })
        .collect::<Result<Vec<_>, String>>()?
        .into_iter().flatten().collect::<Vec<_>>();
    exit_tool_change_rows(&tool_changes, array(value, "tool_changes")?)?;
    for (item, (relative, current)) in array(value, "tool_changes")?.iter().zip(tool_changes) {
        let old = exit.v1_endpoints.get(relative).ok_or("P17 Exit 舊工具缺失")?;
        exit_raw_diff(
            root,
            &exit.original_root,
            evidence,
            item,
            "exit-tool",
            relative,
            &old.snapshot,
            Some(&old.before_sha256),
            &effective_tool(relative)?,
            &current,
        )?;
    }
    for relative in EXIT_TOOL_PATHS {
        if !array(value, "tool_changes")?
            .iter()
            .any(|item| string(item, "path").is_ok_and(|path| path == relative))
        {
            let old = exit.v1_endpoints.get(relative).ok_or("P17 Exit 舊工具缺失")?;
            sha(&effective_tool(relative)?, &old.before_sha256)?;
        }
    }
    exit_new_test_shape(value)?;
    let tests = array(value, "new_tests")?;
    for (item, relative) in tests.iter().zip(EXIT_NEW_TESTS) {
        assert_warning_new_test_absent(root, relative)?;
        let current = root.join(relative);
        if !current.is_file() {
            return Err(format!("P17 Exit 新測試缺失：{relative}"));
        }
        let digest = manifest::sha256(&current)?;
        exit_raw_diff(
            root,
            &exit.original_root,
            evidence,
            item,
            "exit-new-test",
            relative,
            Path::new("/dev/null"),
            None,
            &current,
            &digest,
        )?;
    }
    Ok(())
}

fn exit_review_sources(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    producer: Option<&ProducerUpdateReview>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<(ExitReview, StrictJsonValue)>, String> {
    let path = evidence.join("p17-phase-exit-source-impact-review.json");
    if !path.exists() {
        return Ok(None);
    }
    if !fs::symlink_metadata(&path)
        .map_err(|error| error.to_string())?
        .file_type()
        .is_file()
    {
        return Err("P17 Exit v2 review 非一般檔案".into());
    }
    let value = StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|e| e.to_string())?)?;
    exit_review_header(&value)?;
    let mut exit = exit_review_baselines(original_root, evidence)?;
    exit.current_root = current_root.to_path_buf();
    exit.verified = verified.cloned();
    if let Some(review) = producer {
        exit.producer_before = [
            Some(producer_historical_source_with_verified(
                original_root, current_root, evidence, review, 0, verified)?),
            Some(producer_historical_source_with_verified(
                original_root, current_root, evidence, review, 1, verified)?),
        ];
    }
    exit_parser_update(
        original_root,
        current_root,
        evidence,
        value.get("parser_update"),
        verified,
    )?;
    if let Some(update) = value.get("parser_update") {
        let change = field(update, "change")?;
        if string(change, "path")? != EXIT_PARSER_PATH
            || string(change, "before_sha256")? != EXIT_PARSER_BEFORE_SHA
            || exit.v1_endpoints.contains_key(EXIT_PARSER_PATH)
        {
            return Err("P17 parser 舊 source endpoint 身分／重複不符".into());
        }
        let snapshot = PathBuf::from(string(update, "before_snapshot_path")?);
        sha(&snapshot, EXIT_PARSER_BEFORE_SHA)?;
        exit.v1_endpoints.insert(
            EXIT_PARSER_PATH.into(),
            report::HistoricalSource {
                before_sha256: EXIT_PARSER_BEFORE_SHA.into(),
                snapshot,
            },
        );
    }
    if let Some(update) = value.get("ctrl_c_update") {
        exit_ctrl_c_source_update_with_verified(
            current_root, evidence, update, verified)?;
        exit.ctrl_c_updated = true;
    } else if value.get("warn_argument_update").is_some() {
        exit_ctrl_c_unchanged_sources(current_root)?;
    }
    if let Some(update) = value.get("warn_argument_update") {
        exit_warn_argument_update_with_verified(
            original_root, current_root, evidence, update, exit.ctrl_c_updated, verified,
        )?;
        exit.warn_argument_updated = true;
    } else {
        sha(&current_root.join(EXIT_WARN_VM_PATH), EXIT_WARN_VM_BEFORE_SHA)?;
        sha(&current_root.join(EXIT_WARN_BASIC_PATH), EXIT_WARN_BASIC_BEFORE_SHA)?;
    }
    let cli_diagnostics_updated = value.get("cli_diagnostics_update").is_some();
    if let Some(update) = value.get("cli_diagnostics_update") {
        exit_cli_diagnostics_update_with_verified(
            original_root, current_root, evidence, update, exit.ctrl_c_updated, verified,
        )?;
    } else if value.get("cli_version_banner_update").is_some()
        && manifest::sha256(&current_root.join(EXIT_CLI_BINARY_PATH))? != EXIT_CLI_VERSION_AFTER_SHA
    {
        return Err("P17 CLI diagnostics 來源更新證據缺失".into());
    }
    let cli_version_updated = value.get("cli_version_banner_update").is_some();
    if let Some(update) = value.get("cli_version_banner_update") {
        exit_cli_version_banner_update_with_verified(
            original_root, current_root, evidence, update,
            cli_diagnostics_updated, exit.ctrl_c_updated, verified,
        )?;
    }
    let cli_binary_updated = value.get("cli_binary_file_prefix_update").is_some();
    if let Some(update) = value.get("cli_binary_file_prefix_update") {
        exit_cli_binary_file_prefix_update_with_verified(
            original_root, current_root, evidence, update, cli_version_updated,
            cli_diagnostics_updated, exit.ctrl_c_updated, verified,
        )?;
    } else if manifest::sha256(&current_root.join(EXIT_CLI_BINARY_PATH))?
        != EXIT_CLI_LIB_TEST_ONLY_SHA
        && value.get("cli_unit_test_only_update").is_some()
    {
        return Err("P17 CLI binary prefix 來源更新證據缺失".into());
    }
    if let Some(update) = value.get("cli_unit_test_only_update") {
        exit_cli_unit_test_only_update_with_verified(
            original_root, current_root, evidence, update, cli_binary_updated, verified)?;
    }
    let cli_exit_test_sha = manifest::sha256(&current_root.join(EXIT_CLI_EXIT_TEST_PATH))?;
    if cli_exit_test_sha != EXIT_CLI_EXIT_TEST_BEFORE_SHA
        && value.get("cli_exit_repl_test_only_update").is_none()
    {
        return Err("P17 CLI os.exit test-only 更新證據缺失".into());
    }
    if let Some(update) = value.get("cli_exit_repl_test_only_update") {
        exit_cli_exit_repl_test_only_update_with_verified(
            original_root, current_root, evidence, update, cli_binary_updated, verified)?;
    }
    if value.get("parser_update").is_some() {
        exit_public_cli_leaf_with_verified(
            original_root,
            current_root,
            evidence,
            field(&value, "public_repl_test_update")?,
            true,
            value.get("cli_unit_test_only_update").is_some(),
            cli_binary_updated,
            cli_version_updated,
            cli_diagnostics_updated,
            verified,
        )?;
        exit_public_cli_leaf_with_verified(
            original_root,
            current_root,
            evidence,
            field(&value, "public_cli_repl_test_update")?,
            false,
            value.get("cli_unit_test_only_update").is_some(),
            cli_binary_updated,
            cli_version_updated,
            cli_diagnostics_updated,
            verified,
        )?;
    }
    exit_review_changes(current_root, evidence, &value, &mut exit)?;
    if let Some(update) = value.get("ctrl_c_update") {
        exit_ctrl_c_reuse_review_with_verified(
            original_root, current_root, evidence, update, verified)?;
        for kind in ["public", "private-vm", "private-cli"] {
            exit_ctrl_c_leaf_with_verified(
                original_root, current_root, evidence, update, kind, verified)?;
        }
    }
    exit.input = report::Input::from_path(&path)?;
    Ok(Some((exit, value)))
}

fn host_entry_review_header(value: &StrictJsonValue, exit_sha: &str) -> Result<(), String> {
    object(
        value,
        &[
            "schema",
            "baseline_manifest_sha256",
            "coroutine_baseline_sha256",
            "unwind_baseline_sha256",
            "gate14_archive_sha256",
            "gate14_report_sha256",
            "exit_review_sha256",
            "changes",
            "review_note",
        ],
    )?;
    if string(value, "schema")? != "rivetlua-p17-host-entry-impact-v1"
        || string(value, "baseline_manifest_sha256")? != HOST_ENTRY_BASELINE_SHA
        || string(value, "coroutine_baseline_sha256")? != HOST_ENTRY_COROUTINE_BASELINE_SHA
        || string(value, "unwind_baseline_sha256")? != HOST_ENTRY_UNWIND_BASELINE_SHA
        || string(value, "gate14_archive_sha256")? != HOST_ENTRY_GATE14_ARCHIVE_SHA
        || string(value, "gate14_report_sha256")? != HOST_ENTRY_GATE14_REPORT_SHA
        || string(value, "exit_review_sha256")? != exit_sha
        || string(value, "review_note")?.trim().len() < 8
    {
        return Err("P17 host-entry impact 主鍵不符".into());
    }
    Ok(())
}

fn host_entry_changed_rows(
    changed: &[(&str, String)],
    supplied: &[StrictJsonValue],
) -> Result<(), String> {
    if changed.is_empty() || changed.len() != supplied.len() {
        return Err("P17 host-entry changed subset 缺失／多餘".into());
    }
    for (item, (relative, _)) in supplied.iter().zip(changed) {
        if !HOST_ENTRY_PATHS.contains(relative) || string(item, "path")? != *relative {
            return Err("P17 host-entry changed subset 路徑／順序不符".into());
        }
    }
    Ok(())
}

fn host_entry_review(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    exit: &ExitReview,
    verified: Option<&FinalVerifiedContext>,
) -> Result<HostEntryReview, String> {
    let baseline_path = evidence.join("p17-host-entry-before-20261011-1/manifest.json");
    sha(&baseline_path, HOST_ENTRY_BASELINE_SHA)?;
    let baseline = StrictJsonParser::parse(
        &fs::read_to_string(&baseline_path).map_err(|error| error.to_string())?,
    )?;
    object(
        &baseline,
        &[
            "schema",
            "root",
            "pre_p17_commit",
            "gate14_archive_sha256",
            "gate14_report_sha256",
            "warning_baseline_sha256",
            "callback",
            "errors",
        ],
    )?;
    if string(&baseline, "schema")? != "rivetlua-p17-host-entry-baseline-v1"
        || string(&baseline, "root")? != original_root.display().to_string()
        || string(&baseline, "pre_p17_commit")? != HOST_ENTRY_PRE_P17_COMMIT
        || string(&baseline, "gate14_archive_sha256")? != HOST_ENTRY_GATE14_ARCHIVE_SHA
        || string(&baseline, "gate14_report_sha256")? != HOST_ENTRY_GATE14_REPORT_SHA
        || string(&baseline, "warning_baseline_sha256")?
            != "f5d22ad19da99d28fe810af1eb091dc396fdcf65ae359279db47f4ed3527d21c"
    {
        return Err("P17 host-entry baseline 主鍵不符".into());
    }
    let archive_path = evidence.join("p17-phase-repl-gate14-suite-fail-20261011-1/manifest.json");
    sha(&archive_path, HOST_ENTRY_GATE14_ARCHIVE_SHA)?;
    let archive = StrictJsonParser::parse(
        &fs::read_to_string(&archive_path).map_err(|error| error.to_string())?,
    )?;
    if string(&archive, "schema")? != "rivetlua-p17-phase-gate14-fail-archive-v1"
        || string(&archive, "status")? != "HISTORICAL_FAIL"
        || string(&archive, "phase_report_sha256")? != HOST_ENTRY_GATE14_REPORT_SHA
        || array(&archive, "files")?.len() != 12
    {
        return Err("P17 host-entry Gate14 archive 不符".into());
    }
    let report_path =
        evidence.join("p17-phase-repl-gate14-suite-fail-20261011-1/02-phase-report.json");
    let report_file = array(&archive, "files")?
        .iter()
        .find(|file| string(file, "kind").is_ok_and(|kind| kind == "phase-report"))
        .ok_or("P17 host-entry Gate14 report 缺失")?;
    if string(report_file, "snapshot_path")? != report_path.display().to_string()
        || string(report_file, "sha256")? != HOST_ENTRY_GATE14_REPORT_SHA
    {
        return Err("P17 host-entry Gate14 report 指紋不符".into());
    }
    sha(&report_path, HOST_ENTRY_GATE14_REPORT_SHA)?;
    let old_report = StrictJsonParser::parse(
        &fs::read_to_string(&report_path).map_err(|error| error.to_string())?,
    )?;
    let mut recorded = BTreeMap::new();
    for source in array(&old_report, "source_inputs")? {
        object(source, &["path", "sha256"])?;
        if recorded
            .insert(string(source, "path")?, string(source, "sha256")?)
            .is_some()
        {
            return Err("P17 host-entry Gate14 source 重複".into());
        }
    }
    let warning_path = evidence.join("p17-warning-before/manifest.json");
    sha(
        &warning_path,
        "f5d22ad19da99d28fe810af1eb091dc396fdcf65ae359279db47f4ed3527d21c",
    )?;
    let coroutine_baseline_path =
        evidence.join("p17-host-entry-coroutine-before-20261011-1/manifest.json");
    sha(&coroutine_baseline_path, HOST_ENTRY_COROUTINE_BASELINE_SHA)?;
    let coroutine_baseline = StrictJsonParser::parse(
        &fs::read_to_string(&coroutine_baseline_path).map_err(|error| error.to_string())?,
    )?;
    object(
        &coroutine_baseline,
        &[
            "schema",
            "status",
            "root",
            "relative_path",
            "snapshot_path",
            "before_sha256",
            "bytes",
            "gate14_report_path",
            "gate14_report_sha256",
            "gate14_archive_sha256",
        ],
    )?;
    let coroutine_snapshot =
        evidence.join("p17-host-entry-coroutine-before-20261011-1/coroutine.rs");
    if string(&coroutine_baseline, "schema")?
        != "rivetlua-p17-host-entry-coroutine-baseline-v1"
        || string(&coroutine_baseline, "status")? != "VERIFIED_PRE_REPAIR"
        || string(&coroutine_baseline, "root")? != original_root.display().to_string()
        || string(&coroutine_baseline, "relative_path")? != HOST_ENTRY_PATHS[2]
        || string(&coroutine_baseline, "snapshot_path")? != coroutine_snapshot.display().to_string()
        || string(&coroutine_baseline, "before_sha256")? != HOST_ENTRY_COROUTINE_BEFORE_SHA
        || integer(&coroutine_baseline, "bytes")? != 9793
        || string(&coroutine_baseline, "gate14_report_path")? != report_path.display().to_string()
        || string(&coroutine_baseline, "gate14_report_sha256")? != HOST_ENTRY_GATE14_REPORT_SHA
        || string(&coroutine_baseline, "gate14_archive_sha256")? != HOST_ENTRY_GATE14_ARCHIVE_SHA
        || recorded.get(original_root.join(HOST_ENTRY_PATHS[2]).display().to_string().as_str())
            != Some(&HOST_ENTRY_COROUTINE_BEFORE_SHA)
    {
        return Err("P17 host-entry coroutine baseline 身分不符".into());
    }
    sha(&coroutine_snapshot, HOST_ENTRY_COROUTINE_BEFORE_SHA)?;
    let unwind_baseline_path = evidence.join("p17-host-entry-unwind-before-20261011-1/manifest.json");
    sha(&unwind_baseline_path, HOST_ENTRY_UNWIND_BASELINE_SHA)?;
    let unwind_baseline = StrictJsonParser::parse(
        &fs::read_to_string(&unwind_baseline_path).map_err(|error| error.to_string())?,
    )?;
    object(
        &unwind_baseline,
        &[
            "schema",
            "status",
            "root",
            "relative_path",
            "snapshot_path",
            "before_sha256",
            "bytes",
            "gate14_report_path",
            "gate14_report_sha256",
            "gate14_archive_sha256",
        ],
    )?;
    let unwind_snapshot = evidence.join("p17-host-entry-unwind-before-20261011-1/unwind.rs");
    if string(&unwind_baseline, "schema")? != "rivetlua-p17-host-entry-unwind-baseline-v1"
        || string(&unwind_baseline, "status")? != "VERIFIED_PRE_REPAIR"
        || string(&unwind_baseline, "root")? != original_root.display().to_string()
        || string(&unwind_baseline, "relative_path")? != HOST_ENTRY_PATHS[3]
        || string(&unwind_baseline, "snapshot_path")? != unwind_snapshot.display().to_string()
        || string(&unwind_baseline, "before_sha256")? != HOST_ENTRY_UNWIND_BEFORE_SHA
        || integer(&unwind_baseline, "bytes")? != 904
        || string(&unwind_baseline, "gate14_report_path")? != report_path.display().to_string()
        || string(&unwind_baseline, "gate14_report_sha256")? != HOST_ENTRY_GATE14_REPORT_SHA
        || string(&unwind_baseline, "gate14_archive_sha256")? != HOST_ENTRY_GATE14_ARCHIVE_SHA
        || recorded.get(original_root.join(HOST_ENTRY_PATHS[3]).display().to_string().as_str())
            != Some(&HOST_ENTRY_UNWIND_BEFORE_SHA)
    {
        return Err("P17 host-entry unwind baseline 身分不符".into());
    }
    sha(&unwind_snapshot, HOST_ENTRY_UNWIND_BEFORE_SHA)?;
    let mut old_sources = BTreeMap::new();
    for (name, expected_sha) in [
        (HOST_ENTRY_PATHS[0], HOST_ENTRY_CALLBACK_BEFORE_SHA),
        (HOST_ENTRY_PATHS[1], HOST_ENTRY_ERRORS_BEFORE_SHA),
    ] {
        let item = field(
            &baseline,
            if name == HOST_ENTRY_PATHS[0] {
                "callback"
            } else {
                "errors"
            },
        )?;
        object(item, &["path", "snapshot", "sha256"])?;
        let snapshot = PathBuf::from(string(item, "snapshot")?);
        let expected_snapshot = if name == HOST_ENTRY_PATHS[0] {
            evidence.join("p17-host-entry-before-20261011-1/callback-p16.rs")
        } else {
            evidence.join("p17-warning-before/crates__rivetlua-runtime__src__errors.rs")
        };
        if string(item, "path")? != name
            || snapshot != expected_snapshot
            || string(item, "sha256")? != expected_sha
            || recorded.get(original_root.join(name).display().to_string().as_str()) != Some(&expected_sha)
        {
            return Err(format!("P17 host-entry before 身分不符：{name}"));
        }
        sha(&snapshot, expected_sha)?;
        old_sources.insert(
            name.into(),
            report::HistoricalSource {
                before_sha256: expected_sha.into(),
                snapshot,
            },
        );
    }
    old_sources.insert(
        HOST_ENTRY_PATHS[2].into(),
        report::HistoricalSource {
            before_sha256: HOST_ENTRY_COROUTINE_BEFORE_SHA.into(),
            snapshot: coroutine_snapshot,
        },
    );
    old_sources.insert(
        HOST_ENTRY_PATHS[3].into(),
        report::HistoricalSource {
            before_sha256: HOST_ENTRY_UNWIND_BEFORE_SHA.into(),
            snapshot: unwind_snapshot,
        },
    );
    let callback = old_sources.get(HOST_ENTRY_PATHS[0]).ok_or("P17 callback 前態缺失")?;
    let historical_blob = verified_review_git(current_root)?
        .arg("show")
        .arg(format!("{HOST_ENTRY_PRE_P17_COMMIT}:{}", HOST_ENTRY_PATHS[0]))
        .output()
        .map_err(|error| error.to_string())?;
    if historical_blob.status.code() != Some(0)
        || !historical_blob.stderr.is_empty()
        || historical_blob.stdout != fs::read(&callback.snapshot).map_err(|error| error.to_string())?
    {
        return Err("P17 callback 固定 P16 blob 與 Gate14 前態不符".into());
    }
    let path = evidence.join("p17-phase-host-entry-source-impact-review.json");
    if !fs::symlink_metadata(&path)
        .map_err(|error| error.to_string())?
        .file_type()
        .is_file()
    {
        return Err("P17 host-entry review 非一般檔案".into());
    }
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    host_entry_review_header(&value, &exit.input.sha256)?;
    // Host-entry 的 errors 後態是固定 F64 歷史快照；最終修補另由 scoped current row 驗證。
    let repaired_errors = if let Some(context) = verified.filter(|context| context.repair_active) {
        context.check(current_root, evidence)?;
        let (_, historical_after, current_after) = FINAL_REPAIR_PRODUCT_CHANGES.iter()
            .find(|(relative, _, _)| *relative == HOST_ENTRY_PATHS[1])
            .ok_or("P17 host-entry errors final repair 邊缺失")?;
        let live = current_root.join(HOST_ENTRY_PATHS[1]);
        let current_typed = current_repair_sha(HOST_ENTRY_PATHS[1], current_after,
            context.repair_active, context.core_successor_active,
            context.heap_successor_active, context.product_successor_active);
        if context.source_shas.get(&live).map(String::as_str) != Some(current_typed) {
            return Err("P17 host-entry errors current verified row 不符".into());
        }
        sha(&live, current_typed)?;
        let parent_path = evidence.join(FINAL_REPAIR_PARENT_FILE);
        sha(&parent_path, FINAL_REPAIR_PARENT_SHA)?;
        let parent = StrictJsonParser::parse(&fs::read_to_string(&parent_path)
            .map_err(|error| error.to_string())?)?;
        let recorded = Path::new(string(&parent, "repository_root")?)
            .join(HOST_ENTRY_PATHS[1]).display().to_string();
        let rows = array(&parent, "source_files")?.iter()
            .filter(|row| string(row, "path").ok() == Some(recorded.as_str()))
            .collect::<Vec<_>>();
        if rows.len() != 1 || string(rows[0], "sha256")? != *historical_after {
            return Err("P17 host-entry errors F64 歷史後態不符".into());
        }
        let snapshot = PathBuf::from(string(rows[0], "snapshot_path")?);
        console_cli_public_file(&snapshot, evidence)?;
        sha(&snapshot, historical_after)?;
        if fs::metadata(&snapshot).map_err(|error| error.to_string())?
            .permissions().mode() & 0o777 != 0o444 {
            return Err("P17 host-entry errors F64 快照非 0444".into());
        }
        Some(snapshot)
    } else {
        None
    };
    let changed = HOST_ENTRY_PATHS
        .into_iter()
        .map(|name| {
            let old = old_sources.get(name).ok_or("P17 host-entry 舊bytes缺失")?;
            let effective = if name == HOST_ENTRY_PATHS[1] {
                repaired_errors.clone().unwrap_or_else(|| current_root.join(name))
            } else {
                current_root.join(name)
            };
            let after = manifest::sha256(&effective)?;
            Ok((name, old.before_sha256 != after, after))
        })
        .collect::<Result<Vec<_>, String>>()?
        .into_iter()
        .filter_map(|(name, changed, after)| changed.then_some((name, after)))
        .collect::<Vec<_>>();
    host_entry_changed_rows(&changed, array(&value, "changes")?)?;
    let mut changed_after = BTreeMap::new();
    for (item, (name, after)) in array(&value, "changes")?.iter().zip(changed) {
        let old = old_sources.get(name).ok_or("P17 host-entry 舊bytes缺失")?;
        let effective = if name == HOST_ENTRY_PATHS[1] {
            repaired_errors.clone().unwrap_or_else(|| current_root.join(name))
        } else {
            current_root.join(name)
        };
        exit_raw_diff(
            current_root,
            original_root,
            evidence,
            item,
            "host-entry",
            name,
            &old.snapshot,
            Some(&old.before_sha256),
            &effective,
            &after,
        )?;
        changed_after.insert(name.into(), after);
    }
    for name in HOST_ENTRY_PATHS {
        if !changed_after.contains_key(name) {
            sha(&current_root.join(name), &old_sources[name].before_sha256)?;
        }
    }
    Ok(HostEntryReview {
        input: report::Input::from_path(&path)?,
        baseline: report::Input::from_path(&baseline_path)?,
        coroutine_baseline: report::Input::from_path(&coroutine_baseline_path)?,
        unwind_baseline: report::Input::from_path(&unwind_baseline_path)?,
        gate14_archive: report::Input::from_path(&archive_path)?,
        old_sources,
        changed_after,
    })
}

fn exit_review_proofs(
    root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    exit: &ExitReview,
) -> Result<(), String> {
    if array(value, "builds")?.len() != PROFILES.len()
        || array(value, "regressions")?.len() != 32
    {
        return Err("P17 Exit v2 缺兩版fresh build／32筆具名回歸".into());
    }
    let original_path = evidence.join("p17-phase-assert-warning-source-impact-review.json");
    sha(&original_path, EXIT_ACCEPTED_V1_SHA)?;
    let original = StrictJsonParser::parse(
        &fs::read_to_string(&original_path).map_err(|error| error.to_string())?,
    )?;
    let mut used_logs = BTreeSet::new();
    let builds = exit_builds(
        &exit.original_root, root, evidence, value, &mut used_logs,
        exit.verified.as_ref())?;
    let cargo = exit_safe_cargo(evidence)?;
    exit_retest_existing(
        &exit.original_root,
        root,
        evidence,
        value,
        &original,
        &builds,
        &mut used_logs,
        "p17_shutdown_close_registration_lifecycle",
        cargo,
        exit.verified.as_ref(),
    )?;
    exit_retest_new(
        &exit.original_root,
        root,
        evidence,
        value,
        &original,
        &builds,
        &mut used_logs,
        cargo,
        exit.verified.as_ref(),
    )?;
    Ok(())
}

struct AssertWarningReview {
    input: report::Input,
    baselines: [report::Input; 3],
    archive_manifest: report::Input,
    accepted_report: report::Input,
    accepted_receipt: report::Input,
    historical_environment: Vec<(String, String)>,
    console_sources: BTreeMap<String, report::HistoricalSource>,
    warning_sources: BTreeMap<String, report::HistoricalSource>,
    portability_sources: BTreeMap<String, report::HistoricalSource>,
    exit_sources: BTreeMap<String, report::HistoricalSource>,
    ctrl_c_updated: bool,
    current_root: PathBuf,
    verified: Option<FinalVerifiedContext>,
}

impl AssertWarningReview {
    fn console_endpoint(&self, root: &Path, relative: &str) -> PathBuf {
        let path = root.join(relative);
        self.console_sources
            .get(&path.display().to_string())
            .or_else(|| self.portability_sources.get(&path.display().to_string()))
            .or_else(|| self.exit_sources.get(&path.display().to_string()))
            .map_or(path, |source| source.snapshot.clone())
    }

    fn console_input(&self, root: &Path, value: &StrictJsonValue) -> Result<report::Input, String> {
        let path = string(value, "path")?;
        if let Some(evidence) = Path::new(&self.input.path).parent() {
            if let Some(source) = gc_heap_historical_input_with_verified(
                root, &self.current_root, evidence, value, self.verified.as_ref())? {
                return Ok(source);
            }
        }
        if let Some(source) = self
            .console_sources
            .get(path)
            .or_else(|| self.portability_sources.get(path))
            .or_else(|| self.exit_sources.get(path))
        {
            if string(value, "sha256")? != source.before_sha256 {
                return Err(format!(
                    "P17 Assert/Warning 舊 Console input SHA 不符：{path}"
                ));
            }
            sha(&source.snapshot, &source.before_sha256)?;
            return Ok(report::Input {
                path: path.into(),
                sha256: source.before_sha256.clone(),
            });
        }
        if self.ctrl_c_updated {
            let evidence = Path::new(&self.input.path)
                .parent().ok_or("P17 Ctrl-C Assert/Warning evidence 根目錄缺失")?;
            if let Some(source) = exit_ctrl_c_host_historical_input_with_verified(
                root, evidence, value, self.verified.as_ref())? {
                return Ok(source);
            }
        }
        let evidence = Path::new(&self.input.path)
            .parent().ok_or("P17 GC Assert/Warning evidence 根目錄缺失")?;
        if evidence.join(GC_REVIEW_FILE).exists() {
            if let Some(source) = gc_historical_input_with_verified(
                root, &self.current_root, evidence, value, self.verified.as_ref())? {
                return Ok(source);
            }
        }
        if let Some(source) = final_source_historical_input_with_verified(
            root, &self.current_root, evidence, value, self.verified.as_ref(),
        )? {
            return Ok(source);
        }
        input(value)
    }
}

struct ConsoleReview {
    input: report::Input,
    baselines: [report::Input; 4],
    accepted_report: report::Input,
    accepted_receipt: report::Input,
    old_sources: BTreeMap<String, report::HistoricalSource>,
    original_root: PathBuf,
    current_root: PathBuf,
    ctrl_c_updated: bool,
    verified: Option<FinalVerifiedContext>,
}

impl ConsoleReview {
    fn endpoint(&self, root: &Path, relative: &str) -> PathBuf {
        self.old_sources
            .get(&root.join(relative).display().to_string())
            .map_or_else(|| root.join(relative), |source| source.snapshot.clone())
    }

    fn historical_input(&self, value: &StrictJsonValue) -> Result<report::Input, String> {
        let path = string(value, "path")?;
        if let Some(evidence) = Path::new(&self.input.path).parent() {
            if let Some(source) = gc_heap_historical_input_with_verified(
                &self.original_root, &self.current_root, evidence, value,
                self.verified.as_ref(),
            )? {
                return Ok(source);
            }
        }
        if let Some(source) = self.old_sources.get(path) {
            if string(value, "sha256")? != source.before_sha256 {
                return Err(format!("P17 Console 舊 proof source SHA 不符：{path}"));
            }
            sha(&source.snapshot, &source.before_sha256)?;
            return Ok(report::Input {
                path: path.into(),
                sha256: source.before_sha256.clone(),
            });
        }
        if self.ctrl_c_updated {
            let evidence = Path::new(&self.input.path)
                .parent().ok_or("P17 Ctrl-C Console evidence 根目錄缺失")?;
            if let Some(source) = exit_ctrl_c_host_historical_input_with_verified(
                &self.original_root, evidence, value, self.verified.as_ref(),
            )? {
                return Ok(source);
            }
        }
        let evidence = Path::new(&self.input.path)
            .parent().ok_or("P17 GC Console evidence 根目錄缺失")?;
        if evidence.join(GC_REVIEW_FILE).exists() {
            if let Some(source) = gc_historical_input_with_verified(
                &self.original_root, &self.current_root, evidence, value,
                self.verified.as_ref(),
            )? {
                return Ok(source);
            }
        }
        if let Some(source) = final_source_historical_input_with_verified(
            &self.original_root, &self.current_root, evidence, value,
            self.verified.as_ref(),
        )? {
            return Ok(source);
        }
        input(value)
    }
}

fn bind_host_exit_endpoint(
    root: &Path,
    console: &mut ConsoleReview,
    source: Option<&report::HistoricalSource>,
    host_change: &StrictJsonValue,
) -> Result<(), String> {
    object(
        host_change,
        &[
            "path",
            "before_sha256",
            "after_sha256",
            "diff_path",
            "diff_sha256",
        ],
    )?;
    let source = source.ok_or("P17 Exit Host 歷史前態缺失")?;
    if string(host_change, "path")? != HOST_CHANGES[1]
        || !matches!(field(host_change, "before_sha256")?, StrictJsonValue::Null)
        || string(host_change, "after_sha256")? != source.before_sha256
    {
        return Err("P17 Exit Host 歷史 endpoint 身分不符".into());
    }
    sha(&source.snapshot, &source.before_sha256)?;
    let path = root.join(HOST_CHANGES[1]).display().to_string();
    if console.old_sources.contains_key(&path) {
        return Err("P17 Exit Host 歷史 endpoint 已有不同映射".into());
    }
    // 只把已驗證的 Host 前態接入既有 endpoint/input 共用查核，不覆蓋 Console 基線。
    console.old_sources.insert(
        path,
        report::HistoricalSource {
            before_sha256: source.before_sha256.clone(),
            snapshot: source.snapshot.clone(),
        },
    );
    Ok(())
}

fn console_old_diff_matches(
    generated: &[u8],
    stored: &[u8],
    before: &Path,
    current: &Path,
    effective: &Path,
) -> Result<bool, String> {
    if current == effective {
        return Ok(generated == stored);
    }
    let headers = |left: &Path, right: &Path| -> [String; 3] {
        let left = left.display().to_string();
        let right = right.display().to_string();
        let right = right.trim_start_matches('/');
        if left == "/dev/null" {
            [
                format!("diff --git a/{right} b/{right}"),
                "--- /dev/null".into(),
                format!("+++ b/{right}"),
            ]
        } else {
            [
                format!("diff --git a/{} b/{right}", left.trim_start_matches('/')),
                format!("--- a/{}", left.trim_start_matches('/')),
                format!("+++ b/{right}"),
            ]
        }
    };
    let normalize = |bytes: &[u8], expected: [String; 3]| -> Result<Vec<u8>, String> {
        let text = std::str::from_utf8(bytes).map_err(|error| error.to_string())?;
        let lines = text.split_inclusive('\n').collect::<Vec<_>>();
        let first_hunk = lines
            .iter()
            .position(|line| line.starts_with("@@ "))
            .ok_or("P17 Console 舊 diff 缺 hunk")?;
        let positions = (0..first_hunk)
            .filter(|index| lines[*index].starts_with("--- ") || lines[*index].starts_with("+++ "))
            .collect::<Vec<_>>();
        if lines
            .first()
            .is_none_or(|line| line.trim_end_matches('\n') != expected[0])
            || positions.len() != 2
            || lines[positions[0]].trim_end_matches('\n') != expected[1]
            || lines[positions[1]].trim_end_matches('\n') != expected[2]
        {
            return Err("P17 Console 舊 diff 路徑 header 不符".into());
        }
        let mut normalized = Vec::new();
        for (index, line) in lines.iter().enumerate() {
            if index == 0 {
                normalized.extend_from_slice(b"diff --git a/HISTORICAL b/CURRENT\n");
            } else if index == positions[0] {
                normalized.extend_from_slice(b"--- a/HISTORICAL\n");
            } else if index == positions[1] {
                normalized.extend_from_slice(b"+++ b/CURRENT\n");
            } else {
                normalized.extend_from_slice(line.as_bytes());
            }
        }
        Ok(normalized)
    };
    Ok(normalize(generated, headers(before, effective))?
        == normalize(stored, headers(before, current))?)
}

struct HostReview {
    input: report::Input,
    baseline: report::Input,
    accepted_review: report::Input,
    accepted_reuse: report::Input,
    current_sources: [report::Input; 3],
}

struct ErrorReview {
    input: report::Input,
    baseline: report::Input,
    archive_manifest: report::Input,
    archive_executables: [report::Input; 2],
}

fn console_snapshot_manifest(
    root: &Path,
    evidence: &Path,
    directory: &str,
    digest: &str,
    repair: &str,
    expected: &[(&str, &str)],
    accepted_reviews: &[(&str, &str)],
    old_sources: &mut BTreeMap<String, report::HistoricalSource>,
) -> Result<report::Input, String> {
    let baseline = evidence.join(directory);
    let path = baseline.join("manifest.json");
    sha(&path, digest)?;
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    object(&value, &["schema", "repair", "files"])?;
    if string(&value, "schema")? != "rivetlua-p17-repair-snapshot-v1"
        || string(&value, "repair")? != repair
    {
        return Err(format!("P17 Console {repair} baseline schema 不符"));
    }
    let files = array(&value, "files")?;
    if files.len() != expected.len() + accepted_reviews.len() {
        return Err(format!("P17 Console {repair} baseline 數不符"));
    }
    for (item, (relative, before_sha256)) in files.iter().zip(expected) {
        object(item, &["source", "snapshot", "sha256"])?;
        let source = root.join(relative);
        let snapshot = baseline.join(relative.replace('/', "__"));
        if string(item, "source")? != source.display().to_string()
            || string(item, "snapshot")? != snapshot.display().to_string()
            || string(item, "sha256")? != *before_sha256
        {
            return Err(format!("P17 Console baseline identity 不符：{relative}"));
        }
        sha(&snapshot, before_sha256)?;
        if old_sources
            .insert(
                source.display().to_string(),
                report::HistoricalSource {
                    before_sha256: (*before_sha256).into(),
                    snapshot,
                },
            )
            .is_some()
        {
            return Err(format!("P17 Console baseline 重複來源：{relative}"));
        }
    }
    for (item, (name, digest)) in files[expected.len()..].iter().zip(accepted_reviews) {
        object(item, &["source", "snapshot", "sha256"])?;
        let source = evidence.join(name);
        let snapshot = baseline.join(name);
        if string(item, "source")? != source.display().to_string()
            || string(item, "snapshot")? != snapshot.display().to_string()
            || string(item, "sha256")? != *digest
        {
            return Err(format!("P17 Console review baseline identity 不符：{name}"));
        }
        sha(&source, digest)?;
        sha(&snapshot, digest)?;
        if fs::read(source).map_err(|error| error.to_string())?
            != fs::read(snapshot).map_err(|error| error.to_string())?
        {
            return Err(format!("P17 Console review baseline bytes 不符：{name}"));
        }
    }
    Ok(report::Input::from_path(&path)?)
}

fn console_review_header(value: &StrictJsonValue) -> Result<(), String> {
    object(
        value,
        &[
            "schema",
            "main_baseline_manifest_sha256",
            "pending_baseline_manifest_sha256",
            "heap_baseline_manifest_sha256",
            "tools_baseline_manifest_sha256",
            "accepted_phase_report_sha256",
            "accepted_phase_receipt_sha256",
            "accepted_export_review_sha256",
            "accepted_host_review_sha256",
            "accepted_error_review_sha256",
            "b01_report_sha256",
            "b02_report_sha256",
            "b03_report_sha256",
            "changes",
            "builds",
            "regressions",
            "reuse_basis",
            "review_note",
        ],
    )?;
    if string(value, "schema")? != "rivetlua-p17-debug-console-impact-v1"
        || string(value, "main_baseline_manifest_sha256")? != CONSOLE_MAIN_BASELINE_SHA
        || string(value, "pending_baseline_manifest_sha256")? != CONSOLE_PENDING_BASELINE_SHA
        || string(value, "heap_baseline_manifest_sha256")? != CONSOLE_HEAP_BASELINE_SHA
        || string(value, "tools_baseline_manifest_sha256")? != CONSOLE_TOOLS_BASELINE_SHA
        || string(value, "accepted_phase_report_sha256")? != CONSOLE_ACCEPTED_PHASE_SHA
        || string(value, "accepted_phase_receipt_sha256")? != CONSOLE_ACCEPTED_RECEIPT_SHA
        || string(value, "accepted_export_review_sha256")? != CONSOLE_EXPORT_SHA
        || string(value, "accepted_host_review_sha256")? != CONSOLE_HOST_SHA
        || string(value, "accepted_error_review_sha256")? != CONSOLE_ERROR_SHA
        || string(value, "b01_report_sha256")? != B01_SHA
        || string(value, "b02_report_sha256")? != B02_SHA
        || string(value, "b03_report_sha256")? != B03_SHA
        || string(value, "review_note")?.trim().len() < 8
        || string(value, "reuse_basis")?.trim().len() < 8
    {
        return Err("P17 Console impact 主鍵／重用說明不符".into());
    }
    Ok(())
}

fn console_effective_source_with_verified(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    relative: &str,
    repair: Option<&AssertWarningReview>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<PathBuf, String> {
    let live = root.join(relative);
    let effective = repair.map_or_else(
        || live.clone(), |repair| repair.console_endpoint(root, relative));
    if relative == HOST_ENTRY_PATHS[1] && effective == live {
        if let Some(context) = verified.filter(|context| context.product_successor_active) {
            context.check(current_root, evidence)?;
            let (_, _, after) = FINAL_REPAIR_PRODUCT_CHANGES.iter()
                .find(|(path, _, _)| *path == relative)
                .ok_or("P17 Console errors final repair 邊缺失")?;
            let current = current_repair_sha(relative, after, context.repair_active,
                context.core_successor_active, context.heap_successor_active,
                context.product_successor_active);
            if context.source_shas.get(&current_root.join(relative))
                .map(String::as_str) != Some(current) {
                return Err("P17 Console errors current source SHA 不符".into());
            }
            sha(&current_root.join(relative), current)?;
            let snapshot = evidence.join(
                "p17-warning-before/crates__rivetlua-runtime__src__errors.rs");
            console_cli_public_file(&snapshot, evidence)?;
            sha(&snapshot, HOST_ENTRY_ERRORS_BEFORE_SHA)?;
            if fs::metadata(&snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444 {
                return Err("P17 Console errors 歷史 snapshot 權限不符".into());
            }
            return Ok(snapshot);
        }
    }
    if relative != FINAL_DEBUG_SUCCESSOR_STDLIB_PATH || effective != live
        || manifest::sha256(&current_root.join(relative))?
            != FINAL_DEBUG_SUCCESSOR_STDLIB_AFTER_SHA
    {
        return Ok(effective);
    }
    if final_source_relocated_source_with_verified(
        root, current_root, evidence, &live.display().to_string(),
        FINAL_DEBUG_SUCCESSOR_STDLIB_BEFORE_SHA, verified)?
        != PathBuf::from(relative)
    {
        return Err("P17 Console stdlib final typed edge 缺失".into());
    }
    final_debug_successor_parent_freeze(evidence)?;
    let snapshot = evidence.join(
        "p17-exit-integrated-source-freeze-20261013-41-hook-base/before-stdlib-debug.rs");
    console_cli_public_file(&snapshot, evidence)?;
    sha(&snapshot, FINAL_DEBUG_SUCCESSOR_STDLIB_BEFORE_SHA)?;
    if fs::metadata(&snapshot).map_err(|error| error.to_string())?
        .permissions().mode() & 0o777 != 0o444
    {
        return Err("P17 Console stdlib stage snapshot 非 0444".into());
    }
    Ok(snapshot)
}

fn console_change_schema(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    value: &StrictJsonValue,
    old_sources: &BTreeMap<String, report::HistoricalSource>,
    repair: Option<&AssertWarningReview>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let mut expected = Vec::new();
    for relative in CONSOLE_CHANGE_PATHS {
        let path = root.join(relative);
        if relative == CONSOLE_NEW_TEST {
            if !path.is_file() {
                return Err("P17 Console 新 Runtime test 缺失".into());
            }
            let tracked = verified_review_git(root)?
                .args([
                    "ls-tree",
                    "-r",
                    "--name-only",
                    CONSOLE_BASELINE_COMMIT,
                    "--",
                    relative,
                ])
                .output()
                .map_err(|error| error.to_string())?;
            console_baseline_absence(tracked.status.code(), &tracked.stdout)?;
            expected.push(relative);
            continue;
        }
        let old = old_sources
            .get(&path.display().to_string())
            .ok_or_else(|| format!("P17 Console 缺 baseline：{relative}"))?;
        let effective = console_effective_source_with_verified(
            root, current_root, evidence, relative, repair, verified)?;
        if manifest::sha256(&effective)? != old.before_sha256 {
            expected.push(relative);
        }
    }
    let changes = array(value, "changes")?;
    if changes.len() != expected.len() {
        return Err("P17 Console changes 數量不符".into());
    }
    for (item, relative) in changes.iter().zip(expected) {
        let current = root.join(relative);
        let effective = console_effective_source_with_verified(
            root, current_root, evidence, relative, repair, verified)?;
        let old = old_sources.get(&current.display().to_string());
        let before = old.map_or_else(
            || PathBuf::from("/dev/null"),
            |source| source.snapshot.clone(),
        );
        let diff = evidence.join(format!(
            "p17-phase-debug-console-impact-{}.diff",
            relative.replace('/', "__")
        ));
        console_change_identity(
            item,
            relative,
            old.map(|source| source.before_sha256.as_str()),
            &manifest::sha256(&effective)?,
            &diff,
        )?;
        sha(&diff, string(item, "diff_sha256")?)?;
        let output = verified_review_git(root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(&before)
            .arg(&effective)
            .output()
            .map_err(|error| error.to_string())?;
        if output.status.code() != Some(1)
            || !console_old_diff_matches(
                &output.stdout,
                &fs::read(&diff).map_err(|error| error.to_string())?,
                &before,
                &current,
                &effective,
            )?
        {
            return Err(format!("P17 Console raw diff 不符：{relative}"));
        }
    }
    Ok(())
}

fn console_baseline_absence(exit_code: Option<i32>, stdout: &[u8]) -> Result<(), String> {
    if exit_code != Some(0) || !stdout.is_empty() {
        return Err("P17 Console 無法確認新 Runtime test 於固定 pre-P17 commit 缺席".into());
    }
    Ok(())
}

fn console_change_identity(
    item: &StrictJsonValue,
    relative: &str,
    before_sha256: Option<&str>,
    after_sha256: &str,
    diff: &Path,
) -> Result<(), String> {
    object(
        item,
        &[
            "path",
            "before_sha256",
            "after_sha256",
            "diff_path",
            "diff_sha256",
        ],
    )?;
    if string(item, "path")? != relative
        || string(item, "after_sha256")? != after_sha256
        || string(item, "diff_path")? != diff.display().to_string()
        || match before_sha256 {
            Some(before) => string(item, "before_sha256")? != before,
            None => !matches!(field(item, "before_sha256")?, StrictJsonValue::Null),
        }
    {
        return Err(format!("P17 Console change identity 不符：{relative}"));
    }
    Ok(())
}

fn console_review(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    repair: Option<&AssertWarningReview>,
    public_cli_test_update: Option<&StrictJsonValue>,
    parser_updated: bool,
    cli_unit_updated: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    ctrl_c_updated: bool,
) -> Result<Option<ConsoleReview>, String> {
    console_review_with_verified(
        root, current_root, evidence, repair, public_cli_test_update, parser_updated,
        cli_unit_updated, cli_binary_updated, cli_version_updated,
        cli_diagnostics_updated, ctrl_c_updated, None)
}

fn console_review_with_verified(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    repair: Option<&AssertWarningReview>,
    public_cli_test_update: Option<&StrictJsonValue>,
    parser_updated: bool,
    cli_unit_updated: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    ctrl_c_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<ConsoleReview>, String> {
    let path = evidence.join("p17-phase-debug-console-source-impact-review.json");
    if !path.exists() {
        return Ok(None);
    }
    let mut old_sources = BTreeMap::new();
    let main = console_snapshot_manifest(
        root,
        evidence,
        "p17-debug-console-before",
        CONSOLE_MAIN_BASELINE_SHA,
        "debug-console",
        &CONSOLE_MAIN_FILES,
        &[
            ("p17-phase-host-source-impact-review.json", CONSOLE_HOST_SHA),
            (
                "p17-phase-error-position-source-impact-review.json",
                CONSOLE_ERROR_SHA,
            ),
            ("p17-phase-source-impact-review.json", CONSOLE_EXPORT_SHA),
        ],
        &mut old_sources,
    )?;
    let pending = console_snapshot_manifest(
        root,
        evidence,
        "p17-debug-console-pending-before",
        CONSOLE_PENDING_BASELINE_SHA,
        "debug-console-pending",
        &CONSOLE_PENDING_FILES,
        &[],
        &mut old_sources,
    )?;
    let heap = console_snapshot_manifest(
        root,
        evidence,
        "p17-debug-console-heap-before",
        CONSOLE_HEAP_BASELINE_SHA,
        "debug-console-heap",
        &CONSOLE_HEAP_FILES,
        &[],
        &mut old_sources,
    )?;
    let tools = console_snapshot_manifest(
        root,
        evidence,
        "p17-debug-console-tools-before",
        CONSOLE_TOOLS_BASELINE_SHA,
        "debug-console-tools",
        &CONSOLE_TOOLS_FILES,
        &[],
        &mut old_sources,
    )?;
    let accepted = evidence.join("p17-phase-repl-print-suite-fail");
    let accepted_report = accepted.join("gate-P17.json");
    let accepted_receipt = accepted.join("gate-P17.sha256");
    sha(&accepted_report, CONSOLE_ACCEPTED_PHASE_SHA)?;
    sha(&accepted_receipt, CONSOLE_ACCEPTED_RECEIPT_SHA)?;
    receipt(&accepted_report)?;
    let accepted_value = StrictJsonParser::parse(
        &fs::read_to_string(&accepted_report).map_err(|error| error.to_string())?,
    )?;
    let new_test_path = root.join(CONSOLE_NEW_TEST).display().to_string();
    if string(&accepted_value, "phase")? != "P17"
        || string(&accepted_value, "status")? != "FAIL"
        || !matches!(field(&accepted_value, "batch")?, StrictJsonValue::Null)
        || array(&accepted_value, "checks")?.len() != PROFILES.len()
        || array(&accepted_value, "source_inputs")?
            .iter()
            .any(|item| string(item, "path").ok() == Some(new_test_path.as_str()))
    {
        return Err("P17 Console accepted phase FAIL 基線／新測試缺席不符".into());
    }
    for (batch, digest) in [("B01", B01_SHA), ("B02", B02_SHA), ("B03", B03_SHA)] {
        let report_path = root.join(format!("target/rivetlua-reports/gate-P17-{batch}.json"));
        sha(&report_path, digest)?;
        receipt(&report_path)?;
    }
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    console_review_header(&value)?;
    console_change_schema(root, current_root, evidence, &value, &old_sources,
        repair, verified)?;
    for (path, source) in &old_sources {
        let relative = Path::new(path)
            .strip_prefix(root)
            .map_err(|_| "P17 Console snapshot path 越界")?
            .to_str()
            .ok_or("P17 Console snapshot path 非 UTF-8")?;
        if !CONSOLE_CHANGE_PATHS.contains(&relative) {
            if relative == CONSOLE_CLI_TEST_PATH && public_cli_test_update.is_some() {
                console_cli_public_test_update_with_verified(
                    root,
                    current_root,
                    evidence,
                    source,
                    public_cli_test_update.unwrap(),
                    parser_updated,
                    cli_unit_updated,
                    cli_binary_updated,
                    cli_version_updated,
                    cli_diagnostics_updated,
                    verified,
                )?;
            } else {
                sha(Path::new(path), &source.before_sha256)?;
            }
        }
    }
    validate_console_proofs(root, evidence, &value, repair)?;
    Ok(Some(ConsoleReview {
        input: report::Input::from_path(&path)?,
        baselines: [main, pending, heap, tools],
        accepted_report: report::Input::from_path(&accepted_report)?,
        accepted_receipt: report::Input::from_path(&accepted_receipt)?,
        old_sources,
        original_root: root.to_path_buf(),
        current_root: current_root.to_path_buf(),
        ctrl_c_updated,
        verified: verified.cloned(),
    }))
}

