fn exit_cli_version_source_delta(before: &[u8], after: &[u8]) -> Result<(), String> {
    let before = std::str::from_utf8(before).map_err(|error| error.to_string())?;
    let after = std::str::from_utf8(after).map_err(|error| error.to_string())?;
    let replacements = [
        (r#"LuaProfile::Lua54 => b"RivetLua 0.0.0 (Lua 5.4.9)\n","#,
         r#"LuaProfile::Lua54 => b"RivetLua 0.0.0 (Lua 5.4.9); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n","#),
        (r#"LuaProfile::Lua55 => b"RivetLua 0.0.0 (Lua 5.5.1)\n","#,
         r#"LuaProfile::Lua55 => b"RivetLua 0.0.0 (Lua 5.5.1); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n","#),
        (r#"let version = b"RivetLua 0.0.0 (Lua 5.4.9)\n";"#,
         r#"let version = b"RivetLua 0.0.0 (Lua 5.4.9); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n";"#),
        (r#"let version = b"RivetLua 0.0.0 (Lua 5.5.1)\n";"#,
         r#"let version = b"RivetLua 0.0.0 (Lua 5.5.1); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n";"#),
        (r#"b"RivetLua 0.0.0 (Lua 5.4.9)\n".as_slice()"#,
         r#"b"RivetLua 0.0.0 (Lua 5.4.9); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n".as_slice()"#),
        (r#"b"RivetLua 0.0.0 (Lua 5.5.1)\n".as_slice()"#,
         r#"b"RivetLua 0.0.0 (Lua 5.5.1); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n".as_slice()"#),
    ];
    let mut expected = before.to_owned();
    for (old, new) in replacements {
        if expected.matches(old).count() != 1 {
            return Err("P17 CLI version banner 六個舊來源錨點不唯一".into());
        }
        expected = expected.replacen(old, new, 1);
    }
    if expected != after {
        return Err("P17 CLI version banner 超出 source-only 六個字面值替換".into());
    }
    Ok(())
}

fn exit_cli_version_test_delta(before: &[u8], after: &[u8]) -> Result<(), String> {
    let before = std::str::from_utf8(before).map_err(|error| error.to_string())?;
    let after = std::str::from_utf8(after).map_err(|error| error.to_string())?;
    let old_format = r#""RivetLua 0.0.0 (Lua {})\n","#;
    let new_format = r#""RivetLua 0.0.0 (Lua {}); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n","#;
    if before.matches(old_format).count() != 2 {
        return Err("P17 CLI version banner cli.rs 雙版 format 錨點不符".into());
    }
    let mut expected = before.replace(old_format, new_format);
    let replacements = [
        (r#"assert!(version.stdout.starts_with(b"RivetLua 0.0.0 (Lua 5.4.9)\n"));"#,
         r#"assert_eq!(version.stdout, b"RivetLua 0.0.0 (Lua 5.4.9); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n");"#),
        (r#"b"RivetLua 0.0.0 (Lua 5.5.1)\n> type({})\ntable\n> tonumber('12')\n12\n> \n""#,
         r#"b"RivetLua 0.0.0 (Lua 5.5.1); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n> type({})\ntable\n> tonumber('12')\n12\n> \n""#),
        (r#"b"RivetLua 0.0.0 (Lua 5.4.9)\n> =1+2\n3\n> \n""#,
         r#"b"RivetLua 0.0.0 (Lua 5.4.9); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n> =1+2\n3\n> \n""#),
        (r#"b"RivetLua 0.0.0 (Lua 5.5.1)\n> =1+2\n> \n""#,
         r#"b"RivetLua 0.0.0 (Lua 5.5.1); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n> =1+2\n> \n""#),
        (r#""lua54" => b"RivetLua 0.0.0 (Lua 5.4.9)\n".as_slice(),"#,
         r#""lua54" => b"RivetLua 0.0.0 (Lua 5.4.9); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n".as_slice(),"#),
        (r#"_ => b"RivetLua 0.0.0 (Lua 5.5.1)\n".as_slice(),"#,
         r#"_ => b"RivetLua 0.0.0 (Lua 5.5.1); Lua language: Copyright (C) 1994-2026 Lua.org, PUC-Rio\n".as_slice(),"#),
    ];
    for (old, new) in replacements {
        if expected.matches(old).count() != 1 {
            return Err("P17 CLI version banner cli.rs 六個其餘錨點不唯一".into());
        }
        expected = expected.replacen(old, new, 1);
    }
    if expected != after {
        return Err("P17 CLI version banner cli.rs 超出 fixture 更新".into());
    }
    Ok(())
}

fn exit_cli_unit_test_only_delta(before: &[u8], after: &[u8]) -> Result<(), String> {
    let before = std::str::from_utf8(before).map_err(|error| error.to_string())?;
    let after = std::str::from_utf8(after).map_err(|error| error.to_string())?;
    let boundary = "#[cfg(test)]\nmod cli_unit_tests {";
    if before.matches(boundary).count() != 1
        || after.matches(boundary).count() != 1
        || before.split_once(boundary).unwrap().0 != after.split_once(boundary).unwrap().0
    {
        return Err("P17 CLI unit test-only 產品前綴不符".into());
    }
    let old_assertion = r##"        assert!(
            stdout[version.len()..]
                .iter()
                .all(|byte| matches!(byte, b'>' | b' '))
        );
"##;
    let new_assertion = r##"        assert_eq!(&stdout[version.len()..], b">   \t\tlocal x\n> \n");
"##;
    let first = before.find("run_interactive_repl_case(\"lua55\", b\"  \\t\\tlocal x\\n\")")
        .ok_or("P17 CLI unit test-only lua55 錨點缺失")?;
    let second = before.find("run_interactive_repl_case(\"lua54\", b\"  \\t\\tlocal x\\n\")")
        .ok_or("P17 CLI unit test-only lua54 錨點缺失")?;
    let positions = before.match_indices(old_assertion).map(|(index, _)| index).collect::<Vec<_>>();
    if before.matches("run_interactive_repl_case(\"lua55\", b\"  \\t\\tlocal x\\n\")").count() != 1
        || before.matches("run_interactive_repl_case(\"lua54\", b\"  \\t\\tlocal x\\n\")").count() != 1
        || positions.len() != 2
        || !(first < positions[0] && positions[0] < second && second < positions[1])
    {
        return Err("P17 CLI unit test-only 兩個斷言錨點不唯一".into());
    }
    let mut expected = before.to_owned();
    for position in positions.into_iter().rev() {
        expected.replace_range(position..position + old_assertion.len(), new_assertion);
    }
    if expected != after {
        return Err("P17 CLI unit test-only 超出兩個斷言替換".into());
    }
    Ok(())
}

fn exit_cli_exit_repl_test_only_delta(before: &[u8], after: &[u8]) -> Result<(), String> {
    let before = std::str::from_utf8(before).map_err(|error| error.to_string())?;
    let after = std::str::from_utf8(after).map_err(|error| error.to_string())?;
    let old = r#"    expected_stdout.extend_from_slice(b"> repl-before-exit\n> ");"#;
    let new = r#"    expected_stdout.extend_from_slice(b"> print('repl-before-exit')\nrepl-before-exit\n> os.exit(53, false)\n");"#;
    if before.matches(old).count() != 1 || before.replacen(old, new, 1) != after {
        return Err("P17 CLI os.exit REPL test-only 超出唯一 stdout 預期替換".into());
    }
    Ok(())
}
