fn console_cli_repl_assertion_delta(mid: &[u8], current: &[u8]) -> Result<(), String> {
    let mut expected = String::from_utf8(mid.to_vec()).map_err(|error| error.to_string())?;
    for (before, after) in [
        (
            r##"        b"RivetLua 0.0.0 (Lua 5.5.1)\ntable\n12\n"
"##,
            r##"        b"RivetLua 0.0.0 (Lua 5.5.1)\n> type({})\ntable\n> tonumber('12')\n12\n> \n"
"##,
        ),
        (
            r##"    assert_eq!(lua54_equals.stdout, b"RivetLua 0.0.0 (Lua 5.4.9)\n3\n");
"##,
            r##"    assert_eq!(
        lua54_equals.stdout,
        b"RivetLua 0.0.0 (Lua 5.4.9)\n> =1+2\n3\n> \n"
    );
"##,
        ),
        (
            r##"    assert_eq!(lua55_equals.stdout, b"RivetLua 0.0.0 (Lua 5.5.1)\n");
"##,
            r##"    assert_eq!(
        lua55_equals.stdout,
        b"RivetLua 0.0.0 (Lua 5.5.1)\n> =1+2\n> \n"
    );
"##,
        ),
        (
            r##"        expected.extend_from_slice(&normal_print.stdout);
"##,
            r##"        let mut printed_values = normal_print.stdout.split_inclusive(|byte| *byte == b'\n');
        expected.extend_from_slice(b"> 1/0\n");
        expected.extend_from_slice(
            printed_values
                .next()
                .expect("normal print 輸出第一個除法結果"),
        );
        expected.extend_from_slice(b"> 0/0\n");
        expected.extend_from_slice(
            printed_values
                .next()
                .expect("normal print 輸出第二個除法結果"),
        );
        assert!(printed_values.next().is_none(), "profile={profile}");
        expected.extend_from_slice(b"> \n");
"##,
        ),
        (
            r##"        expected.extend_from_slice(b"seen\n");
"##,
            r##"        expected.extend_from_slice(b"> t\nseen\n> \n");
"##,
        ),
        (
            r##"        expected.extend_from_slice(b"replacement\t3\t1\tnil\t3\n");
"##,
            r##"        expected.extend_from_slice(
            b"> select(1, 1, nil, 3)\nreplacement\t3\t1\tnil\t3\n> \n",
        );
"##,
        ),
    ] {
        if expected.matches(before).count() != 1 {
            return Err("P17 Console CLI REPL 斷言舊端點不唯一".into());
        }
        expected = expected.replacen(before, after, 1);
    }
    if expected.as_bytes() != current {
        return Err("P17 Console CLI REPL 斷言差異不符".into());
    }
    Ok(())
}

fn console_cli_public_file(path: &Path, directory: &Path) -> Result<(), String> {
    if !path.is_absolute()
        || path.components().any(|part| matches!(part, Component::ParentDir))
        || !path.starts_with(directory)
        || fs::canonicalize(path).map_err(|error| error.to_string())? != path
        || !fs::symlink_metadata(path)
            .map_err(|error| error.to_string())?
            .file_type()
            .is_file()
    {
        return Err("P17 Console CLI 公開證據路徑不符".into());
    }
    Ok(())
}

fn exit_public_final_root_review(
    proof: &StrictJsonValue,
    evidence: &Path,
) -> Result<(), String> {
    let base = evidence.join(EXIT_PUBLIC_FINAL_DIR);
    let review = base.join("root-review.json");
    console_cli_public_file(&review, &base)?;
    sha(&review, EXIT_PUBLIC_ROOT_REVIEW_SHA)?;
    let claim = string(proof, "root_review")?;
    if !claim.contains(&review.display().to_string())
        || !claim.contains(EXIT_PUBLIC_ROOT_REVIEW_SHA)
    {
        return Err("P17 REPL 最終 root review 引用不符".into());
    }
    Ok(())
}

fn exit_cli_unit_historical_input(
    original_root: &Path,
    evidence: &Path,
    source: &StrictJsonValue,
) -> Result<(), String> {
    let snapshot = evidence.join(EXIT_PUBLIC_FINAL_DIR).join("lua-init/3-lib.rs");
    console_cli_public_file(&snapshot, &evidence.join(EXIT_PUBLIC_FINAL_DIR))?;
    sha(&snapshot, EXIT_CLI_LIB_SHA)?;
    exit_cli_lib_historical_input(original_root, source, &snapshot, EXIT_CLI_LIB_SHA)
}

fn exit_cli_lib_historical_input(
    original_root: &Path,
    source: &StrictJsonValue,
    snapshot: &Path,
    digest: &str,
) -> Result<(), String> {
    let historical = original_root.join(EXIT_CLI_BINARY_PATH).display().to_string();
    sha(snapshot, digest)?;
    if string(source, "path")? != historical || string(source, "sha256")? != digest {
        return Err("P17 CLI unit test-only 舊proof來源不符".into());
    }
    let mut view = report::PhaseSourceView::new();
    view.insert(
        historical.clone(),
        report::HistoricalSource {
            before_sha256: digest.into(),
            snapshot: snapshot.to_path_buf(),
        },
    );
    if report::historical_input(source, &view)? != Some(historical) {
        return Err("P17 CLI unit test-only 歷史來源映射缺失".into());
    }
    Ok(())
}

fn exit_warn_historical_source(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    relative: &str,
    digest: &str,
    proof_snapshot: Option<&Path>,
) -> Result<(), String> {
    exit_warn_historical_source_with_verified(
        original_root, current_root, evidence, relative, digest, proof_snapshot, None)
}

fn exit_warn_historical_source_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    relative: &str,
    digest: &str,
    proof_snapshot: Option<&Path>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    if let Some(context) = verified {
        context.check(current_root, evidence)?;
    }
    if let Some(verified) = verified.filter(|verified| verified.repair_active) {
        if FINAL_REPAIR_PRODUCT_CHANGES.iter().any(|(path, before, _)|
            *path == relative && *before == digest) {
            let mapped = current_repair_sha(relative, digest, true,
                verified.core_successor_active, verified.heap_successor_active, verified.product_successor_active);
            if verified.source_shas.get(&current_root.join(relative)).map(String::as_str)
                != Some(mapped) {
                return Err(format!("P17 Exit historical final source SHA 不符：{relative}"));
            }
            if let Some(snapshot) = proof_snapshot {
                sha(snapshot, digest)?;
            }
            final_source_relocated_source_with_verified(
                original_root, current_root, evidence,
                &original_root.join(relative).display().to_string(), digest, Some(verified))?;
            return Ok(());
        }
    }
    if let Some(index) = exit_ctrl_c_source_index(relative) {
        let (_, before_sha, after_sha) = EXIT_CTRL_CHANGES[index];
        let current_after = if relative == GC_HEAP_PATH && evidence.join(GC_REVIEW_FILE).exists() {
            sha(&gc_before_source_with_verified(
                current_root, evidence, relative, verified)?, after_sha)?;
            true
        } else if relative == DEBUG_VM_PATH
            && debug_vm_live_source_with_verified(current_root, evidence, verified)? {
            sha(&evidence.join(DEBUG_VM_SOURCE_DIR).join(format!(
                "before-{}", DEBUG_VM_PATH.replace('/', "__"))), after_sha)?;
            true
        } else if relative == EXIT_CTRL_CLI_PATH
            && final_repair_cli_current_with_verified(current_root, evidence, verified)? {
            let historical_after = evidence.join(EXIT_CTRL_SOURCE_DIR)
                .join(format!("after-{}", relative.replace('/', "__")));
            console_cli_public_file(&historical_after, &evidence.join(EXIT_CTRL_SOURCE_DIR))?;
            sha(&historical_after, after_sha)?;
            true
        } else {
            manifest::sha256(&current_root.join(relative))? == after_sha
        };
        if digest == before_sha && current_after {
            let before = exit_ctrl_c_before_source_with_verified(
                current_root, evidence, relative, verified)?;
            sha(&before, digest)?;
            if let Some(snapshot) = proof_snapshot {
                sha(snapshot, digest)?;
            }
            return Ok(());
        }
    }
    let historical = match relative {
        EXIT_WARN_VM_PATH if digest == EXIT_WARN_VM_BEFORE_SHA =>
            Some((EXIT_WARN_VM_AFTER_SHA, "before-crates__rivetlua-runtime__src__vm__mod.rs")),
        EXIT_WARN_BASIC_PATH if digest == EXIT_WARN_BASIC_BEFORE_SHA =>
            Some((EXIT_WARN_BASIC_AFTER_SHA, "before-crates__rivetlua-runtime__src__stdlib__basic.rs")),
        _ => None,
    };
    if let Some((after, filename)) = historical {
        let current_sha = manifest::sha256(&current_root.join(relative))?;
        let compatible = current_sha == after
            || (relative == EXIT_WARN_VM_PATH
                && (current_sha == EXIT_CTRL_VM_AFTER_SHA
                    || (current_sha == DEBUG_VM_AFTER_SHA
                        && debug_vm_live_source_with_verified(current_root, evidence, verified)?)
                    || (current_sha == DEBUG_HOOK_VM_AFTER_SHA
                        && debug_vm_live_source_with_verified(current_root, evidence, verified)?
                        && debug_hook_live_source_with_verified(current_root, evidence, verified)?)
                    || (current_sha == FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA
                        && (verified.is_some()
                            || final_debug_successor_tool_source(current_root, evidence)?.is_some())
                        && debug_vm_live_source_with_verified(current_root, evidence, verified)?
                        && debug_hook_live_source_with_verified(current_root, evidence, verified)?)
                    || (verified.is_some_and(|context| context.repair_active
                        && context.source_shas.get(&current_root.join(relative))
                            .map(String::as_str) == Some(current_sha.as_str())
                        && current_sha == product_successor_sha(DEBUG_VM_PATH,
                            final_repair_sha(DEBUG_VM_PATH, FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA, true),
                            context.product_successor_active))
                        && debug_vm_live_source_with_verified(current_root, evidence, verified)?
                        && debug_hook_live_source_with_verified(current_root, evidence, verified)?))
                && exit_ctrl_c_before_source_with_verified(
                    current_root, evidence, relative, verified)
                    .is_ok_and(|snapshot| sha(&snapshot, after).is_ok()))
            || (relative == GC_BASIC_PATH && evidence.join(GC_REVIEW_FILE).exists()
                && gc_before_source_with_verified(current_root, evidence, relative, verified)
                    .is_ok_and(|snapshot| sha(&snapshot, after).is_ok()));
        if compatible {
            let before = evidence.join(EXIT_WARN_SOURCE_DIR).join(filename);
            console_cli_public_file(&before, &evidence.join(EXIT_WARN_SOURCE_DIR))?;
            sha(&before, digest)?;
            if let Some(snapshot) = proof_snapshot {
                sha(snapshot, digest)?;
            }
            return Ok(());
        }
    }
    if evidence.join(GC_REVIEW_FILE).exists()
        && matches!(
            (relative, digest),
            (GC_BASIC_PATH, GC_BASIC_BEFORE_SHA)
                | (GC_TABLE_PATH, GC_TABLE_BEFORE_SHA)
                | (GC_METAMETHOD_PATH, GC_METAMETHOD_BEFORE_SHA)
                | (GC_HEAP_PATH, GC_HEAP_BEFORE_SHA)
                | (GC_TOOL_PATH, GC_TOOL_BEFORE_SHA)
        )
    {
        sha(&gc_before_source_with_verified(
            current_root, evidence, relative, verified)?, digest)?;
        if let Some(snapshot) = proof_snapshot {
            sha(snapshot, digest)?;
        }
        return Ok(());
    }
    if FINAL_SOURCE_CHANGES.iter().any(|(path, before, _)|
        *path == relative && *before == digest)
    {
        if let Some(snapshot) = proof_snapshot {
            sha(snapshot, digest)?;
        }
        final_source_relocated_source_with_verified(
            original_root, current_root, evidence,
            &original_root.join(relative).display().to_string(), digest,
            verified,
        )?;
        return Ok(());
    }
    debug_vm_relocated_source_with_verified(
        original_root,
        current_root,
        evidence,
        &original_root.join(relative).display().to_string(),
        digest,
        verified,
    ).map_err(|error| format!("P17 Exit/Warning historical source {relative}/{digest}: {error}"))?;
    Ok(())
}

fn exit_cli_version_test_historical_input(
    original_root: &Path,
    source: &StrictJsonValue,
    snapshot: &Path,
) -> Result<(), String> {
    let historical = original_root.join(CONSOLE_CLI_TEST_PATH).display().to_string();
    sha(snapshot, CONSOLE_CLI_REPL_SHA)?;
    if string(source, "path")? != historical
        || string(source, "sha256")? != CONSOLE_CLI_REPL_SHA
    {
        return Err("P17 CLI version banner 舊 cli.rs proof source 不符".into());
    }
    let mut view = report::PhaseSourceView::new();
    view.insert(
        historical.clone(),
        report::HistoricalSource {
            before_sha256: CONSOLE_CLI_REPL_SHA.into(),
            snapshot: snapshot.to_path_buf(),
        },
    );
    if report::historical_input(source, &view)? != Some(historical) {
        return Err("P17 CLI version banner 舊 cli.rs 來源映射缺失".into());
    }
    Ok(())
}

fn console_cli_public_row_shape(
    row: &StrictJsonValue,
    profile: &str,
    original_root: &Path,
    expected_environment: &StrictJsonValue,
) -> Result<(), String> {
    object(
        row,
        &[
            "profile", "command", "cwd", "environment_mode", "environment",
            "exit_code", "matched", "passed", "failed", "ignored", "filtered",
            "log_path", "log_sha256", "running_binary_path", "snapshot_path",
            "snapshot_sha256", "source_inputs",
        ],
    )?;
    let features = match profile {
        "lua55" => "native-lua55",
        "lua54" => "native-lua54,default-lua54",
        _ => return Err("P17 Console CLI 公開證據 profile 不符".into()),
    };
    let expected = [
        EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-cli", "--features",
        features, "--test", "cli",
        "cli_reports_unversioned_init_error_with_default_source_line", "--", "--exact",
        "--nocapture", "--test-threads=1",
    ];
    if string(row, "profile")? != profile
        || strings(row, "command")? != expected.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>()
        || string(row, "cwd")? != original_root.display().to_string()
        || string(row, "environment_mode")? != "env -i"
        || canonical_json(field(row, "environment")?) != canonical_json(expected_environment)
        || integer(row, "exit_code")? != 0
        || integer(row, "matched")? != 1
        || integer(row, "passed")? != 1
        || integer(row, "failed")? != 0
        || integer(row, "ignored")? != 0
        || integer(row, "filtered")? != 54
    {
        return Err(format!("P17 Console CLI {profile} 公開測試 command/count 不符"));
    }
    Ok(())
}

fn console_cli_public_source_shape(
    row: &StrictJsonValue,
    original_root: &Path,
    proof_dir: &Path,
    current_digest: &str,
    parser_updated: bool,
) -> Result<Vec<&'static str>, String> {
    let mut expected = vec![
        CONSOLE_CLI_TEST_PATH,
        "crates/rivetlua-runtime/src/vm/mod.rs",
        "crates/rivetlua/src/lib.rs",
        "crates/rivetlua-cli/src/lib.rs",
    ];
    if parser_updated {
        expected.push(EXIT_PARSER_PATH);
    }
    let inputs = array(row, "source_inputs")?;
    if inputs.len() != expected.len() {
        return Err("P17 Console CLI 公開來源數量不符".into());
    }
    for (index, (item, relative)) in inputs.iter().zip(&expected).enumerate() {
        object(item, &["path", "sha256", "snapshot_path"])?;
        let digest = string(item, "sha256")?;
        exit_digest(digest)?;
        let recorded = original_root.join(*relative).display().to_string();
        let snapshot = proof_dir.join(format!(
            "{index}-{}",
            Path::new(*relative).file_name().unwrap().to_string_lossy()
        ));
        if string(item, "path")? != recorded
            || (index == 0 && digest != current_digest)
            || string(item, "snapshot_path")? != snapshot.display().to_string()
        {
            return Err("P17 Console CLI 公開來源身分／順序不符".into());
        }
    }
    Ok(expected)
}

fn console_cli_public_test_update(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    old: &report::HistoricalSource,
    reference: &StrictJsonValue,
    parser_updated: bool,
    cli_unit_updated: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
) -> Result<(), String> {
    console_cli_public_test_update_with_verified(
        original_root, current_root, evidence, old, reference, parser_updated,
        cli_unit_updated, cli_binary_updated, cli_version_updated,
        cli_diagnostics_updated, None)
}

fn console_cli_public_test_update_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    old: &report::HistoricalSource,
    reference: &StrictJsonValue,
    parser_updated: bool,
    cli_unit_updated: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    object(reference, &["path", "sha256"])?;
    let path = Path::new(string(reference, "path")?);
    let proof_dir = path.parent().ok_or("P17 Console CLI 公開證據無目錄")?;
    let final_path = evidence.join(EXIT_PUBLIC_FINAL_DIR).join("lua-init/result.json");
    if path.file_name().and_then(|name| name.to_str()) != Some("result.json")
        || (parser_updated
            && (path != final_path || string(reference, "sha256")? != EXIT_PUBLIC_LUA_INIT_SHA))
        || (!parser_updated && proof_dir.parent() != Some(evidence))
        || old.before_sha256 != CONSOLE_MAIN_FILES[4].1
    {
        return Err("P17 Console CLI 公開證據／舊端點身分不符".into());
    }
    console_cli_public_file(path, evidence)?;
    sha(path, string(reference, "sha256")?)?;
    sha(&old.snapshot, &old.before_sha256)?;
    let current_digest = if parser_updated { CONSOLE_CLI_REPL_SHA } else { CONSOLE_CLI_MID_SHA };
    let actual_digest = manifest::sha256(&current_root.join(CONSOLE_CLI_TEST_PATH))?;
    if actual_digest != (if cli_version_updated { CONSOLE_CLI_VERSION_SHA } else { current_digest }) {
        return Err("P17 Console CLI REPL 斷言目前來源 SHA 不符".into());
    }
    let current = if cli_version_updated {
        evidence.join(EXIT_PUBLIC_FINAL_DIR).join("cli-repl/0-cli.rs")
    } else {
        let relative = report::phase_relocated_source(
            original_root,
            current_root,
            &original_root.join(CONSOLE_CLI_TEST_PATH).display().to_string(),
            current_digest,
        )?;
        current_root.join(relative)
    };
    if cli_version_updated {
        console_cli_public_file(&current, &evidence.join(EXIT_PUBLIC_FINAL_DIR))?;
        sha(&current, CONSOLE_CLI_REPL_SHA)?;
    }
    let old_bytes = fs::read(&old.snapshot).map_err(|error| error.to_string())?;
    let current_bytes = fs::read(&current).map_err(|error| error.to_string())?;
    if parser_updated {
        let mid_dir = evidence.join("p17-lua-init-public-verified-1791691957949435000");
        let mid = mid_dir.join("0-cli.rs");
        console_cli_public_file(&mid, &mid_dir)?;
        sha(&mid, CONSOLE_CLI_MID_SHA)?;
        let mid_bytes = fs::read(&mid).map_err(|error| error.to_string())?;
        console_cli_public_test_delta(&old_bytes, &mid_bytes)?;
        console_cli_repl_assertion_delta(&mid_bytes, &current_bytes)?;
    } else {
        console_cli_public_test_delta(&old_bytes, &current_bytes)?;
    }
    let proof = StrictJsonParser::parse(&fs::read_to_string(path).map_err(|error| error.to_string())?)?;
    object(
        &proof,
        &["status", "reported_by", "root_review", "readiness_path", "readiness_sha256", "rows"],
    )?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    const READINESS_SHA: &str = "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb";
    sha(&readiness, READINESS_SHA)?;
    if string(&proof, "status")? != "PASS"
        || string(&proof, "reported_by")?.is_empty()
        || string(&proof, "root_review")?.is_empty()
        || string(&proof, "readiness_path")? != readiness.display().to_string()
        || string(&proof, "readiness_sha256")? != READINESS_SHA
    {
        return Err("P17 Console CLI 公開證據主鍵不符".into());
    }
    if parser_updated {
        exit_public_final_root_review(&proof, evidence)?;
    }
    let readiness_value = StrictJsonParser::parse(&fs::read_to_string(&readiness).map_err(|error| error.to_string())?)?;
    let environment = field(field(&readiness_value, "phase_launch")?, "required_environment")?;
    exit_safe_cargo(evidence)?;
    let rows = array(&proof, "rows")?;
    if rows.len() != PROFILES.len() {
        return Err("P17 Console CLI 公開證據雙版本數量不符".into());
    }
    for (row, profile) in rows.iter().zip(["lua55", "lua54"]) {
        console_cli_public_row_shape(row, profile, original_root, environment)?;
        let log = Path::new(string(row, "log_path")?);
        let expected_log = if parser_updated {
            let (run, ordinal) = if profile == "lua55" { (3, 4) } else { (2, 8) };
            evidence.join(format!(
                "p17-public-repl-validation-20261011-{run}/logs/{ordinal:02}-{profile}-cli-unversioned-init-error.log"
            ))
        } else {
            evidence.join(format!("p17-lua-init-error-cli-{profile}.log"))
        };
        if log != expected_log {
            return Err("P17 Console CLI 公開 log 路徑不符".into());
        }
        console_cli_public_file(log, evidence)?;
        sha(log, string(row, "log_sha256")?)?;
        let running = Path::new(string(row, "running_binary_path")?);
        let target = Path::new(string(environment, "CARGO_TARGET_DIR")?);
        if running.parent() != Some(target.join("debug/deps").as_path())
            || !running.file_name().and_then(|name| name.to_str()).is_some_and(|name| name.starts_with("cli-"))
        {
            return Err("P17 Console CLI Running binary 身分不符".into());
        }
        let snapshot = Path::new(string(row, "snapshot_path")?);
        let digest = string(row, "snapshot_sha256")?;
        if snapshot != proof_dir.join(format!("executed-{profile}-{digest}")) {
            return Err("P17 Console CLI binary snapshot 路徑不符".into());
        }
        console_cli_public_file(snapshot, proof_dir)?;
        sha(snapshot, digest)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 Console CLI binary snapshot 權限不符".into());
        }
        report::mach_type(snapshot, "EXECUTE")?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        let (counts, _) = parse_named_log_with_filter(
            &body,
            &["cli_reports_unversioned_init_error_with_default_source_line"],
            true,
        )?;
        if counts.matched != 1 || counts.passed != 1 || counts.failed != 0 || counts.ignored != 0
            || !body.contains(&format!("Running tests/cli.rs ({})", running.display()))
        {
            return Err("P17 Console CLI 公開 log 結果／binary 不符".into());
        }
        let expected = console_cli_public_source_shape(
            row,
            original_root,
            proof_dir,
            current_digest,
            parser_updated,
        )?;
        let inputs = array(row, "source_inputs")?;
        for (item, relative) in inputs.iter().zip(expected) {
            let digest = string(item, "sha256")?;
            let source_snapshot = Path::new(string(item, "snapshot_path")?);
            console_cli_public_file(source_snapshot, proof_dir)?;
            sha(source_snapshot, digest)?;
            if relative == CONSOLE_CLI_TEST_PATH && cli_version_updated {
                exit_cli_version_test_historical_input(original_root, item, source_snapshot)?;
            } else if relative == "crates/rivetlua-cli/src/lib.rs" && cli_unit_updated {
                exit_cli_unit_historical_input(original_root, evidence, item)?;
                if cli_binary_updated {
                    if exit_ctrl_c_virtual_current_sha_with_verified(
                        current_root, evidence, relative, verified)?
                        != if cli_diagnostics_updated { EXIT_CLI_DIAGNOSTICS_AFTER_SHA }
                        else if cli_version_updated { EXIT_CLI_VERSION_AFTER_SHA }
                        else { EXIT_CLI_BINARY_AFTER_SHA }
                    {
                        return Err("P17 Console CLI 舊 CLI source endpoint 不符".into());
                    }
                }
            } else {
                exit_warn_historical_source_with_verified(
                    original_root, current_root, evidence, relative, digest, Some(source_snapshot),
                    verified,
                )?;
            }
        }
    }
    Ok(())
}

fn exit_public_cli_leaf_shape(
    proof: &StrictJsonValue,
    readiness: &Path,
    repl_file: bool,
) -> Result<(), String> {
    object(
        proof,
        &["status", "reported_by", "root_review", "readiness_path", "readiness_sha256", "rows"],
    )?;
    const READINESS_SHA: &str = "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb";
    if string(proof, "status")? != "PASS"
        || string(proof, "reported_by")?.is_empty()
        || string(proof, "root_review")?.is_empty()
        || string(proof, "readiness_path")? != readiness.display().to_string()
        || string(proof, "readiness_sha256")? != READINESS_SHA
        || array(proof, "rows")?.len() != (if repl_file { 2 } else { 4 })
    {
        return Err("P17 REPL 公開證據主鍵／row 數不符".into());
    }
    for row in array(proof, "rows")? {
        object(row, &[
            "profile", "command", "cwd", "environment_mode", "environment",
            "exit_code", "matched", "passed", "failed", "ignored", "filtered",
            "log_path", "log_sha256", "running_binary_path", "snapshot_path",
            "snapshot_sha256", "source_inputs",
        ])?;
    }
    Ok(())
}

fn exit_public_cli_leaf(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    reference: &StrictJsonValue,
    repl_file: bool,
    cli_unit_updated: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
) -> Result<(), String> {
    exit_public_cli_leaf_with_verified(
        original_root, current_root, evidence, reference, repl_file, cli_unit_updated,
        cli_binary_updated, cli_version_updated, cli_diagnostics_updated, None)
}

fn exit_public_cli_leaf_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    reference: &StrictJsonValue,
    repl_file: bool,
    cli_unit_updated: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    object(reference, &["path", "sha256"])?;
    let path = Path::new(string(reference, "path")?);
    let proof_dir = path.parent().ok_or("P17 REPL 公開證據無目錄")?;
    let final_leaf = if repl_file { "repl" } else { "cli-repl" };
    let final_sha = if repl_file { EXIT_PUBLIC_REPL_LEAF_SHA } else { EXIT_PUBLIC_CLI_REPL_SHA };
    if path.file_name().and_then(|name| name.to_str()) != Some("result.json")
        || path != evidence.join(EXIT_PUBLIC_FINAL_DIR).join(final_leaf).join("result.json")
        || string(reference, "sha256")? != final_sha
    {
        return Err("P17 REPL 公開證據路徑不符".into());
    }
    console_cli_public_file(path, evidence)?;
    sha(path, string(reference, "sha256")?)?;
    let proof = StrictJsonParser::parse(
        &fs::read_to_string(path).map_err(|error| error.to_string())?,
    )?;
    let readiness = evidence.join("p17-exit-v2-readiness-20261011-1.json");
    const READINESS_SHA: &str = "2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb";
    sha(&readiness, READINESS_SHA)?;
    exit_public_cli_leaf_shape(&proof, &readiness, repl_file)?;
    exit_public_final_root_review(&proof, evidence)?;
    let readiness_value = StrictJsonParser::parse(
        &fs::read_to_string(&readiness).map_err(|error| error.to_string())?,
    )?;
    let environment = field(field(&readiness_value, "phase_launch")?, "required_environment")?;
    exit_safe_cargo(evidence)?;
    let specs = if repl_file {
        vec![("lua55", None), ("lua54", None)]
    } else {
        vec![
            ("lua55", Some("cli_repl_tries_expressions_before_statements_and_matches_profile_equals_syntax")),
            ("lua55", Some("cli_repl_prints_returned_values_through_vm_local_print_for_both_profiles")),
            ("lua54", Some("cli_repl_tries_expressions_before_statements_and_matches_profile_equals_syntax")),
            ("lua54", Some("cli_repl_prints_returned_values_through_vm_local_print_for_both_profiles")),
        ]
    };
    let rows = array(&proof, "rows")?;
    debug_assert_eq!(rows.len(), specs.len());
    let first = if repl_file { EXIT_PUBLIC_REPL_TEST_PATH } else { CONSOLE_CLI_TEST_PATH };
    let source_paths = [
        first,
        "crates/rivetlua-runtime/src/vm/mod.rs",
        "crates/rivetlua/src/lib.rs",
        "crates/rivetlua-cli/src/lib.rs",
        EXIT_PARSER_PATH,
    ];
    let mut used_logs = BTreeSet::new();
    for (row, (profile, selector)) in rows.iter().zip(specs) {
        let features = match profile {
            "lua55" => "native-lua55",
            "lua54" => "native-lua54,default-lua54",
            _ => return Err("P17 REPL 公開 profile 不符".into()),
        };
        let target = if repl_file { "p17_repl" } else { "cli" };
        let mut command = vec![
            EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-cli", "--features",
            features, "--test", target,
        ];
        if let Some(selector) = selector {
            command.extend([selector, "--", "--exact"]);
        } else {
            command.push("--");
        }
        command.extend(["--nocapture", "--test-threads=1"]);
        let matched = if repl_file { 2 } else { 1 };
        let filtered = if repl_file { 0 } else { 54 };
        if string(row, "profile")? != profile
            || strings(row, "command")? != command.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>()
            || string(row, "cwd")? != original_root.display().to_string()
            || string(row, "environment_mode")? != "env -i"
            || canonical_json(field(row, "environment")?) != canonical_json(environment)
            || integer(row, "exit_code")? != 0
            || integer(row, "matched")? != matched
            || integer(row, "passed")? != matched
            || integer(row, "failed")? != 0
            || integer(row, "ignored")? != 0
            || integer(row, "filtered")? != filtered
        {
            return Err(format!("P17 REPL {profile} 公開命令／count 不符"));
        }
        let log = Path::new(string(row, "log_path")?);
        let (run, ordinal, log_name) = match (repl_file, profile, selector) {
            (true, "lua55", _) => (3, 1, "p17_repl"),
            (true, "lua54", _) => (2, 5, "p17_repl"),
            (false, "lua55", Some("cli_repl_tries_expressions_before_statements_and_matches_profile_equals_syntax")) => (3, 2, "cli-repl-expressions"),
            (false, "lua55", Some("cli_repl_prints_returned_values_through_vm_local_print_for_both_profiles")) => (3, 3, "cli-repl-return-values"),
            (false, "lua54", Some("cli_repl_tries_expressions_before_statements_and_matches_profile_equals_syntax")) => (2, 6, "cli-repl-expressions"),
            (false, "lua54", Some("cli_repl_prints_returned_values_through_vm_local_print_for_both_profiles")) => (2, 7, "cli-repl-return-values"),
            _ => return Err("P17 REPL 公開 selector 身分不符".into()),
        };
        if log != evidence.join(format!(
            "p17-public-repl-validation-20261011-{run}/logs/{ordinal:02}-{profile}-{log_name}.log"
        )) {
            return Err("P17 REPL 公開 log 路徑不符".into());
        }
        if !used_logs.insert(log.to_path_buf()) {
            return Err("P17 REPL 公開 log 重複".into());
        }
        console_cli_public_file(log, evidence)?;
        sha(log, string(row, "log_sha256")?)?;
        let running = Path::new(string(row, "running_binary_path")?);
        let target_dir = Path::new(string(environment, "CARGO_TARGET_DIR")?);
        let prefix = if repl_file { "p17_repl-" } else { "cli-" };
        if running.parent() != Some(target_dir.join("debug/deps").as_path())
            || !running.file_name().and_then(|name| name.to_str()).is_some_and(|name| name.starts_with(prefix))
        {
            return Err("P17 REPL 公開測試 driver 身分不符".into());
        }
        let snapshot = Path::new(string(row, "snapshot_path")?);
        let binary_sha = string(row, "snapshot_sha256")?;
        if snapshot != proof_dir.join(format!("executed-{profile}-{binary_sha}")) {
            return Err("P17 REPL 公開 driver snapshot 路徑不符".into());
        }
        console_cli_public_file(snapshot, proof_dir)?;
        sha(snapshot, binary_sha)?;
        if fs::metadata(snapshot).map_err(|error| error.to_string())?.permissions().mode() & 0o777 != 0o555 {
            return Err("P17 REPL 公開 driver snapshot 權限不符".into());
        }
        report::mach_type(snapshot, "EXECUTE")?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        let names = if let Some(selector) = selector {
            vec![selector]
        } else {
            vec![
                "p17_repl_multiline_chunks_allow_arbitrary_whitespace",
                "p17_repl_stringifies_non_string_prompt_for_each_input_and_eof",
            ]
        };
        let (counts, _) = parse_named_log_with_filter(&body, &names, !repl_file)?;
        if counts.matched != matched as u32
            || counts.passed != matched as u32
            || counts.failed != 0
            || counts.ignored != 0
            || (filtered != 0 && !body.contains("54 filtered out;"))
            || !body.contains(&format!("Running tests/{target}.rs ({})", running.display()))
        {
            return Err("P17 REPL 公開 log 結果／driver 不符".into());
        }
        let inputs = array(row, "source_inputs")?;
        if inputs.len() != source_paths.len() {
            return Err("P17 REPL 公開來源數量不符".into());
        }
        for (index, (item, relative)) in inputs.iter().zip(source_paths).enumerate() {
            object(item, &["path", "sha256", "snapshot_path"])?;
            let digest = string(item, "sha256")?;
            let current_digest = exit_ctrl_c_virtual_current_sha_with_verified(
                current_root, evidence, relative, verified)?;
            let expected_current = if index == 1 && current_digest == EXIT_WARN_VM_AFTER_SHA {
                EXIT_WARN_VM_AFTER_SHA
            } else if index == 0 && !repl_file && cli_version_updated {
                CONSOLE_CLI_VERSION_SHA
            } else if index == 3 && cli_binary_updated {
                if cli_diagnostics_updated { EXIT_CLI_DIAGNOSTICS_AFTER_SHA }
                else if cli_version_updated { EXIT_CLI_VERSION_AFTER_SHA }
                else { EXIT_CLI_BINARY_AFTER_SHA }
            } else if index == 3 && cli_unit_updated {
                EXIT_CLI_LIB_TEST_ONLY_SHA
            } else {
                digest
            };
            if string(item, "path")? != original_root.join(relative).display().to_string()
                || current_digest != expected_current
                || (index == 0
                    && digest != (if repl_file { EXIT_PUBLIC_REPL_SHA } else { CONSOLE_CLI_REPL_SHA }))
                || (index == 3 && digest != EXIT_CLI_LIB_SHA)
                || (index == 4 && digest != EXIT_PARSER_AFTER_SHA)
            {
                return Err(format!("P17 REPL 公開來源身分／SHA 不符：{relative}"));
            }
            let expected_snapshot = proof_dir.join(format!(
                "{index}-{}",
                Path::new(relative).file_name().unwrap().to_string_lossy(),
            ));
            let source_snapshot = Path::new(string(item, "snapshot_path")?);
            if source_snapshot != expected_snapshot {
                return Err("P17 REPL 公開來源 snapshot 路徑不符".into());
            }
            console_cli_public_file(source_snapshot, proof_dir)?;
            sha(source_snapshot, digest)?;
            if index == 0 && !repl_file && cli_version_updated {
                exit_cli_version_test_historical_input(original_root, item, source_snapshot)?;
            } else if index == 3 && cli_unit_updated {
                exit_cli_unit_historical_input(original_root, evidence, item)?;
            } else {
                exit_warn_historical_source_with_verified(
                    original_root, current_root, evidence, relative, digest, Some(source_snapshot),
                    verified,
                )?;
            }
        }
    }
    Ok(())
}

fn console_evidence_file(path: &Path, evidence: &Path) -> Result<(), String> {
    let directory = evidence.join("p17-debug-console-regressions");
    let canonical_directory = fs::canonicalize(&directory).map_err(|error| error.to_string())?;
    let canonical = fs::canonicalize(path).map_err(|error| error.to_string())?;
    if !path.is_absolute()
        || !path.starts_with(&directory)
        || path
            .components()
            .any(|part| matches!(part, Component::ParentDir))
        || !canonical.starts_with(&canonical_directory)
        || !fs::symlink_metadata(path)
            .map_err(|error| error.to_string())?
            .file_type()
            .is_file()
    {
        return Err(format!(
            "P17 Console evidence path 不符：{}",
            path.display()
        ));
    }
    Ok(())
}

fn console_sources(
    root: &Path,
    record: &StrictJsonValue,
    expected: &[&str],
    repair: Option<&AssertWarningReview>,
) -> Result<(), String> {
    let sources = array(record, "source_inputs")?;
    if sources.len() != expected.len() {
        return Err("P17 Console source input 數不符".into());
    }
    for (source, relative) in sources.iter().zip(expected) {
        let actual = if let Some(repair) = repair {
            repair.console_input(root, source)?
        } else {
            input(source)?
        };
        if actual.path != root.join(relative).display().to_string() {
            return Err(format!("P17 Console source input 路徑不符：{relative}"));
        }
    }
    Ok(())
}

fn exit_v1_sources(
    root: &Path,
    record: &StrictJsonValue,
    expected: &[&str],
    exit: Option<&ExitReview>,
    host_sources: Option<&BTreeMap<String, report::HistoricalSource>>,
) -> Result<(), String> {
    let sources = array(record, "source_inputs")?;
    if sources.len() != expected.len() {
        return Err("P17 Exit v1 source input 數不符".into());
    }
    for (source, relative) in sources.iter().zip(expected) {
        object(source, &["path", "sha256"])?;
        let actual = assert_warning_phase9_input(root, source, exit, host_sources)?;
        if actual.path != root.join(relative).display().to_string() {
            return Err(format!("P17 Exit v1 source 路徑不符：{relative}"));
        }
    }
    Ok(())
}

fn console_builds(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    used_logs: &mut BTreeSet<String>,
    repair: Option<&AssertWarningReview>,
) -> Result<Vec<BTreeMap<String, report::Input>>, String> {
    let builds = array(review, "builds")?;
    if builds.len() != PROFILES.len() {
        return Err("P17 Console CAPI build profile 數不符".into());
    }
    let environment = runner::environment(root)?;
    let sources = [
        CONSOLE_MAIN_FILES[0].0,
        CONSOLE_MAIN_FILES[1].0,
        CONSOLE_MAIN_FILES[2].0,
        CONSOLE_HEAP_FILES[0].0,
        CONSOLE_PENDING_FILES[0].0,
        CONSOLE_PENDING_FILES[1].0,
        "crates/rivetlua-capi/Cargo.toml",
        "Cargo.lock",
        "crates/rivetlua-capi/tests/p17_internal_replacements.rs",
        "crates/rivetlua-capi/tests/p17_lifecycle.rs",
    ];
    let mut result = Vec::new();
    for (build, profile) in builds.iter().zip(PROFILES) {
        object(
            build,
            &[
                "profile",
                "features",
                "command",
                "cwd",
                "environment",
                "exit_code",
                "log_path",
                "log_sha256",
                "artifacts",
                "source_inputs",
            ],
        )?;
        let log = Path::new(string(build, "log_path")?);
        if string(build, "profile")? != profile
            || string(build, "features")?
                != if profile == PROFILES[0] {
                    "lua55"
                } else {
                    "lua54"
                }
            || strings(build, "command")? != error_build_command(profile)
            || string(build, "cwd")? != root.display().to_string()
            || integer(build, "exit_code")? != 0
            || !used_logs.insert(log.display().to_string())
        {
            return Err(format!("P17 Console CAPI build command 不符：{profile}"));
        }
        error_environment(build, &[])?;
        console_sources(root, build, &sources, repair)?;
        console_evidence_file(log, evidence)?;
        sha(log, string(build, "log_sha256")?)?;
        let found = error_artifacts(&fs::read_to_string(log).map_err(|error| error.to_string())?)?;
        let artifacts = array(build, "artifacts")?;
        if artifacts.len() != 2 {
            return Err("P17 Console CAPI artifacts 數不符".into());
        }
        let mut snapshots = BTreeMap::new();
        for (item, target) in artifacts
            .iter()
            .zip(["p17_internal_replacements", "p17_lifecycle"])
        {
            object(
                item,
                &[
                    "target",
                    "artifact_path",
                    "artifact_sha256",
                    "executable_path",
                    "executable_sha256",
                    "post_sha256",
                ],
            )?;
            let original = found
                .get(target)
                .ok_or("P17 Console CAPI Cargo artifact 缺失")?;
            let snapshot = Path::new(string(item, "executable_path")?);
            let original_path = Path::new(string(item, "artifact_path")?);
            if string(item, "target")? != target
                || original_path != original
                || !original_path.starts_with(&environment.target_dir)
                || original_path
                    .components()
                    .any(|part| matches!(part, Component::ParentDir))
                || string(item, "artifact_sha256")? != string(item, "executable_sha256")?
                || string(item, "post_sha256")? != string(item, "executable_sha256")?
                || snapshot.file_name().and_then(|name| name.to_str())
                    != Some(format!("{profile}-{target}").as_str())
            {
                return Err(format!(
                    "P17 Console CAPI artifact identity 不符：{profile}/{target}"
                ));
            }
            console_evidence_file(snapshot, evidence)?;
            sha(snapshot, string(item, "executable_sha256")?)?;
            if fs::metadata(snapshot)
                .map_err(|error| error.to_string())?
                .permissions()
                .mode()
                & 0o777
                != 0o555
            {
                return Err("P17 Console CAPI snapshot 非 0555".into());
            }
            report::mach_type(snapshot, "EXECUTE")?;
            if snapshots
                .insert(target.into(), report::Input::from_path(snapshot)?)
                .is_some()
            {
                return Err("P17 Console CAPI snapshot 重複 target".into());
            }
        }
        result.push(snapshots);
    }
    Ok(result)
}

fn console_regressions(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    builds: &[BTreeMap<String, report::Input>],
    used_logs: &mut BTreeSet<String>,
    repair: Option<&AssertWarningReview>,
) -> Result<(), String> {
    if CONSOLE_RUNTIME_SELECTORS.is_empty() {
        return Err("P17 Console Runtime 具名 selectors 尚未凍結".into());
    }
    let records = array(review, "regressions")?;
    if records.len() != 19 {
        return Err("P17 Console regression 數不符".into());
    }
    let runtime_sources = [
        CONSOLE_MAIN_FILES[0].0,
        CONSOLE_MAIN_FILES[1].0,
        CONSOLE_MAIN_FILES[2].0,
        CONSOLE_HEAP_FILES[0].0,
        CONSOLE_PENDING_FILES[0].0,
        CONSOLE_PENDING_FILES[1].0,
        "crates/rivetlua-runtime/Cargo.toml",
        "Cargo.lock",
    ];
    let capi_sources = [
        CONSOLE_MAIN_FILES[0].0,
        CONSOLE_MAIN_FILES[1].0,
        CONSOLE_MAIN_FILES[2].0,
        CONSOLE_HEAP_FILES[0].0,
        CONSOLE_PENDING_FILES[0].0,
        CONSOLE_PENDING_FILES[1].0,
        "crates/rivetlua-capi/Cargo.toml",
        "Cargo.lock",
    ];
    let host_sources = [
        CONSOLE_MAIN_FILES[3].0,
        HOST_CHANGES[1],
        HOST_BASELINE_FILES[1].0,
        HOST_BASELINE_FILES[2].0,
        HOST_BASELINE_FILES[3].0,
        HOST_BASELINE_FILES[4].0,
        CONSOLE_MAIN_FILES[0].0,
        CONSOLE_MAIN_FILES[1].0,
        CONSOLE_MAIN_FILES[2].0,
        CONSOLE_HEAP_FILES[0].0,
        CONSOLE_PENDING_FILES[0].0,
        CONSOLE_PENDING_FILES[1].0,
    ];
    let environment = runner::environment(root)?;
    let registry = parse_registry(root, &environment.target)?;
    for (index, record) in records.iter().enumerate() {
        object(
            record,
            &[
                "kind",
                "profile",
                "features",
                "command",
                "cwd",
                "environment",
                "exit_code",
                "matched",
                "passed",
                "failed",
                "ignored",
                "log_path",
                "log_sha256",
                "source_inputs",
                "selectors",
                "build_index",
                "marker",
            ],
        )?;
        let (kind, profile, names, sources, build_index, target, public) = match index {
            0 => (
                "runtime-console",
                "both",
                CONSOLE_RUNTIME_SELECTORS.to_vec(),
                [runtime_sources.as_slice(), &[CONSOLE_NEW_TEST]].concat(),
                None,
                None,
                false,
            ),
            1 => (
                "runtime-error",
                "both",
                vec![
                    "p17_error_position_basic",
                    "p17_error_position_dispatch_lifecycle",
                ],
                [runtime_sources.as_slice(), &[ERROR_NEW_TEST]].concat(),
                None,
                None,
                false,
            ),
            2 => (
                "runtime-export",
                "both",
                vec!["p17_export_open_call_runtime_semantics"],
                [
                    runtime_sources.as_slice(),
                    &["crates/rivetlua-runtime/tests/official_chunk_runtime.rs"],
                ]
                .concat(),
                None,
                None,
                false,
            ),
            3 | 4 => (
                "b02-cstack",
                PROFILES[index - 3],
                vec!["p17_internal_c_stack_errors"],
                [
                    capi_sources.as_slice(),
                    &["crates/rivetlua-capi/tests/p17_internal_replacements.rs"],
                ]
                .concat(),
                Some(index - 3),
                Some("p17_internal_replacements"),
                false,
            ),
            5..=8 => {
                let profile_index = if index <= 6 { 0 } else { 1 };
                let kind = if index == 5 || index == 7 {
                    "b03-gc"
                } else {
                    "b03-coroutine"
                };
                let name = if kind == "b03-gc" {
                    "p17_stress_gc_long_run"
                } else {
                    "p17_stress_coroutine_debug"
                };
                (
                    kind,
                    PROFILES[profile_index],
                    vec![name],
                    [
                        capi_sources.as_slice(),
                        &["crates/rivetlua-capi/tests/p17_lifecycle.rs"],
                    ]
                    .concat(),
                    Some(profile_index),
                    Some("p17_lifecycle"),
                    false,
                )
            }
            9 | 10 => (
                "host-unit",
                PROFILES[index - 9],
                HOST_UNIT_SELECTORS.to_vec(),
                host_sources.to_vec(),
                None,
                None,
                false,
            ),
            11 | 12 => (
                "host-public",
                PROFILES[index - 11],
                HOST_PUBLIC_SELECTORS.to_vec(),
                [host_sources.as_slice(), &[HOST_CHANGES[2]]].concat(),
                None,
                None,
                true,
            ),
            13 | 14 => (
                "args-private",
                PROFILES[index - 13],
                CONSOLE_ARGS_SELECTORS.to_vec(),
                host_sources.to_vec(),
                None,
                None,
                false,
            ),
            15 | 16 => (
                "repl-private",
                PROFILES[index - 15],
                CONSOLE_REPL_SELECTORS.to_vec(),
                host_sources.to_vec(),
                None,
                None,
                false,
            ),
            _ => (
                "console-optin-private",
                PROFILES[index - 17],
                CONSOLE_OPTIN_SELECTORS.to_vec(),
                host_sources.to_vec(),
                None,
                None,
                false,
            ),
        };
        let command = if let Some(build_index) = build_index {
            let binary = builds
                .get(build_index)
                .and_then(|build| build.get(target.expect("fixed target")))
                .ok_or("P17 Console fresh CAPI binary 缺失")?;
            vec![
                binary.path.clone(),
                names[0].into(),
                "--exact".into(),
                "--nocapture".into(),
                "--test-threads=1".into(),
            ]
        } else if index <= 2 {
            let target = match index {
                0 => "p17_debug_console",
                1 => "p17_error_position",
                _ => "official_chunk_runtime",
            };
            let filter = match index {
                0 => "p17_debug_console_",
                1 => "p17_error_position_",
                _ => "p17_export_open_call_runtime_semantics",
            };
            let mut command = vec![
                "cargo",
                "test",
                "--locked",
                "-p",
                "rivetlua-runtime",
                "--test",
                target,
                filter,
                "--",
            ]
            .into_iter()
            .map(str::to_owned)
            .collect::<Vec<_>>();
            if index == 2 {
                command.push("--exact".into());
            }
            command.extend(["--nocapture".into(), "--test-threads=1".into()]);
            command
        } else {
            let feature = if profile == PROFILES[0] {
                "native-lua55"
            } else {
                "default-lua54,native-lua54"
            };
            let mut command = vec![
                "cargo",
                "test",
                "--locked",
                "-p",
                "rivetlua-cli",
                "--features",
                feature,
            ]
            .into_iter()
            .map(str::to_owned)
            .collect::<Vec<_>>();
            if public {
                command.extend(["--test".into(), "p17_host_services".into()]);
            } else {
                command.push("--lib".into());
            }
            let filter = match index {
                13 | 14 => "p17_script_args_",
                15 | 16 => "p17_repl_",
                17 | 18 => "p17_debug_console_trusted_optin",
                _ => "p17_host_",
            };
            command.extend([
                filter.into(),
                "--".into(),
                "--nocapture".into(),
                "--test-threads=1".into(),
            ]);
            command
        };
        let observed_build = field(record, "build_index")?;
        let valid_build = match build_index {
            Some(expected) => {
                matches!(observed_build, StrictJsonValue::Number(value) if value.parse::<usize>().ok() == Some(expected))
            }
            None => matches!(observed_build, StrictJsonValue::Null),
        };
        let log = Path::new(string(record, "log_path")?);
        let expected_features = if index <= 2 {
            "default"
        } else if index <= 8 {
            if profile == PROFILES[0] {
                "lua55"
            } else {
                "lua54"
            }
        } else if profile == PROFILES[0] {
            "native-lua55"
        } else {
            "default-lua54,native-lua54"
        };
        if string(record, "kind")? != kind
            || string(record, "profile")? != profile
            || string(record, "features")? != expected_features
            || strings(record, "command")? != command
            || string(record, "cwd")? != root.display().to_string()
            || integer(record, "exit_code")? != 0
            || integer(record, "matched")? != names.len() as u64
            || integer(record, "passed")? != names.len() as u64
            || integer(record, "failed")? != 0
            || integer(record, "ignored")? != 0
            || strings(record, "selectors")? != names
            || !valid_build
            || !used_logs.insert(log.display().to_string())
        {
            return Err(format!(
                "P17 Console regression command/count 不符：{kind}/{profile}"
            ));
        }
        let expected_environment = if build_index.is_some() {
            runner::effective_no_native_environment()
        } else {
            Vec::new()
        };
        error_environment(record, &expected_environment)?;
        console_sources(root, record, &sources, repair)?;
        console_evidence_file(log, evidence)?;
        sha(log, string(record, "log_sha256")?)?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        if index >= 9 {
            host_regression_log(&body, &names)?;
        } else {
            error_named_log(&body, &names)?;
        }
        if (5..=8).contains(&index) {
            let markers = marker_records(&body, &names, true)?;
            let marker = markers.get(names[0]).ok_or("P17 Console B03 marker 缺失")?;
            if canonical_json(field(record, "marker")?) != canonical_json(marker) {
                return Err("P17 Console B03 marker 與 log 不符".into());
            }
            let spec = CASES
                .iter()
                .copied()
                .find(|spec| spec.id == names[0])
                .ok_or("P17 Console B03 case 未宣告")?;
            validate_record(marker, spec, profile, &registry, true)?;
        } else if !matches!(field(record, "marker")?, StrictJsonValue::Null)
            || body.contains(MARKER)
        {
            return Err("P17 Console 非 B03 marker 不符".into());
        }
    }
    Ok(())
}

fn validate_console_proofs(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    repair: Option<&AssertWarningReview>,
) -> Result<(), String> {
    let mut used_logs = BTreeSet::new();
    let builds = console_builds(root, evidence, review, &mut used_logs, repair)?;
    console_regressions(root, evidence, review, &builds, &mut used_logs, repair)
}

fn assert_warning_header(value: &StrictJsonValue) -> Result<(), String> {
    object(
        value,
        &[
            "schema",
            "assert_baseline_manifest_sha256",
            "warning_baseline_manifest_sha256",
            "portability_baseline_manifest_sha256",
            "accepted_console_review_sha256",
            "accepted_phase_archive_manifest_sha256",
            "accepted_phase_report_sha256",
            "accepted_phase_receipt_sha256",
            "b01_report_sha256",
            "b02_report_sha256",
            "b03_report_sha256",
            "assert_change",
            "warning_changes",
            "portability_changes",
            "new_tests",
            "builds",
            "regressions",
            "reuse_basis",
            "review_note",
        ],
    )?;
    if string(value, "schema")? != "rivetlua-p17-assert-warning-impact-v1"
        || string(value, "assert_baseline_manifest_sha256")? != ASSERT_BASELINE_SHA
        || string(value, "warning_baseline_manifest_sha256")? != WARNING_BASELINE_SHA
        || string(value, "portability_baseline_manifest_sha256")?
            != WARNING_PORTABILITY_BASELINE_SHA
        || string(value, "accepted_console_review_sha256")? != ASSERT_WARNING_CONSOLE_SHA
        || string(value, "accepted_phase_archive_manifest_sha256")? != ASSERT_WARNING_ARCHIVE_SHA
        || string(value, "accepted_phase_report_sha256")? != ASSERT_WARNING_PHASE_SHA
        || string(value, "accepted_phase_receipt_sha256")? != ASSERT_WARNING_RECEIPT_SHA
        || string(value, "b01_report_sha256")? != B01_SHA
        || string(value, "b02_report_sha256")? != B02_SHA
        || string(value, "b03_report_sha256")? != B03_SHA
        || string(value, "review_note")?.trim().len() < 8
    {
        return Err("P17 Assert/Warning 來源影響 review 主鍵不符".into());
    }
    let reuse = field(value, "reuse_basis")?;
    object(
        reuse,
        &["compiler_export", "fuzz_platform", "batch_reports"],
    )?;
    for key in ["compiler_export", "fuzz_platform", "batch_reports"] {
        if string(reuse, key)?.trim().len() < 8 {
            return Err(format!("P17 Assert/Warning 重用依據缺失：{key}"));
        }
    }
    Ok(())
}

fn assert_warning_archive(
    root: &Path,
    evidence: &Path,
) -> Result<(report::Input, report::Input, report::Input, StrictJsonValue), String> {
    let archive = evidence.join("p17-phase-debug-console-suite-fail");
    let manifest_path = archive.join("manifest.json");
    sha(&manifest_path, ASSERT_WARNING_ARCHIVE_SHA)?;
    let manifest = StrictJsonParser::parse(
        &fs::read_to_string(&manifest_path).map_err(|error| error.to_string())?,
    )?;
    object(&manifest, &["schema", "phase_attempt", "outcome", "files"])?;
    if string(&manifest, "schema")? != "rivetlua-p17-phase-fail-archive-v1"
        || integer(&manifest, "phase_attempt")? != 9
        || string(&manifest, "outcome")? != "FAIL"
    {
        return Err("P17 Assert/Warning 第九次 phase archive 主鍵不符".into());
    }
    let files = array(&manifest, "files")?;
    if files.len() != ASSERT_WARNING_ARCHIVE_FILES.len() {
        return Err("P17 Assert/Warning 第九次 phase archive 檔案數不符".into());
    }
    for (item, (name, digest)) in files.iter().zip(ASSERT_WARNING_ARCHIVE_FILES) {
        object(item, &["original", "snapshot", "sha256"])?;
        let snapshot = archive.join(name);
        if string(item, "snapshot")? != snapshot.display().to_string()
            || string(item, "sha256")? != digest
            || !Path::new(string(item, "original")?).is_absolute()
        {
            return Err(format!("P17 Assert/Warning archive identity 不符：{name}"));
        }
        sha(&snapshot, digest)?;
    }
    let report_path = archive.join("gate-P17.json");
    let receipt_path = archive.join("gate-P17.sha256");
    receipt(&report_path)?;
    let report = StrictJsonParser::parse(
        &fs::read_to_string(&report_path).map_err(|error| error.to_string())?,
    )?;
    if string(&report, "phase")? != "P17"
        || string(&report, "status")? != "FAIL"
        || !matches!(field(&report, "batch")?, StrictJsonValue::Null)
    {
        return Err("P17 Assert/Warning 第九次 phase FAIL identity 不符".into());
    }
    let checks = array(&report, "checks")?;
    if checks.len() != PROFILES.len() {
        return Err("P17 Assert/Warning 第九次 phase checks 數不符".into());
    }
    for (check, (profile, (_, digest))) in checks.iter().zip(
        PROFILES
            .iter()
            .zip(ASSERT_WARNING_ARCHIVE_FILES[7..].iter()),
    ) {
        if string(check, "profile")? != *profile
            || string(check, "status")? != "FAIL"
            || integer(check, "matched")? != 1
            || integer(check, "passed")? != 0
            || integer(check, "failed")? != 1
            || integer(check, "ignored")? != 0
            || string(check, "log_sha256")? != *digest
        {
            return Err(format!(
                "P17 Assert/Warning 第九次 suite FAIL 證據不符：{profile}"
            ));
        }
    }
    let old_console = input(field(
        field(&report, "phase_evidence")?,
        "debug_console_source_impact_review",
    )?)?;
    if old_console.path
        != evidence
            .join("p17-phase-debug-console-source-impact-review.json")
            .display()
            .to_string()
        || old_console.sha256 != ASSERT_WARNING_CONSOLE_SHA
    {
        return Err("P17 Assert/Warning 第九次 phase Console review 不符".into());
    }
    for (batch, digest) in [("B01", B01_SHA), ("B02", B02_SHA), ("B03", B03_SHA)] {
        let path = root.join(format!("target/rivetlua-reports/gate-P17-{batch}.json"));
        sha(&path, digest)?;
        receipt(&path)?;
    }
    Ok((
        report::Input::from_path(&manifest_path)?,
        report::Input::from_path(&report_path)?,
        report::Input::from_path(&receipt_path)?,
        report,
    ))
}

fn assert_warning_diff_matches(
    stage: &str,
    generated: &[u8],
    stored: &[u8],
    before: &Path,
    current: &Path,
    after: &Path,
) -> Result<bool, String> {
    if stage == "assert" {
        // assert 階段的右端是已驗證的歷史中間態快照，不是目前工作樹來源。
        console_old_diff_matches(generated, stored, before, after, after)
    } else {
        console_old_diff_matches(generated, stored, before, current, after)
    }
}

fn assert_warning_raw_diff(
    root: &Path,
    evidence: &Path,
    item: &StrictJsonValue,
    stage: &str,
    relative: &str,
    before: &Path,
    before_sha: Option<&str>,
    after: &Path,
    after_sha: &str,
) -> Result<(), String> {
    let diff = evidence.join(format!(
        "p17-phase-{stage}-impact-{}.diff",
        relative.replace('/', "__")
    ));
    console_change_identity(item, relative, before_sha, after_sha, &diff)?;
    sha(&diff, string(item, "diff_sha256")?)?;
    let output = verified_review_git(root)?
        .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
        .arg(before)
        .arg(after)
        .output()
        .map_err(|error| error.to_string())?;
    if output.status.code() != Some(1)
        || !assert_warning_diff_matches(
            stage,
            &output.stdout,
            &fs::read(&diff).map_err(|error| error.to_string())?,
            before,
            &root.join(relative),
            after,
        )?
    {
        return Err(format!("P17 Assert/Warning raw diff 不符：{relative}"));
    }
    Ok(())
}

fn assert_warning_new_test_absent(root: &Path, relative: &str) -> Result<(), String> {
    let output = verified_review_git(root)?
        .args([
            "ls-tree",
            "-r",
            "--name-only",
            CONSOLE_BASELINE_COMMIT,
            "--",
            relative,
        ])
        .output()
        .map_err(|error| error.to_string())?;
    console_baseline_absence(output.status.code(), &output.stdout)
}

fn assert_warning_original_root(root: &Path, evidence: &Path) -> Result<PathBuf, String> {
    if !evidence
        .join("p17-phase-assert-warning-source-impact-review.json")
        .exists()
    {
        return Ok(root.to_path_buf());
    }
    let path = evidence.join("p17-warning-portability-before/manifest.json");
    sha(&path, WARNING_PORTABILITY_BASELINE_SHA)?;
    let manifest =
        StrictJsonParser::parse(&fs::read_to_string(path).map_err(|error| error.to_string())?)?;
    object(&manifest, &["schema", "repair", "files"])?;
    if string(&manifest, "schema")? != "rivetlua-p17-repair-snapshot-v1"
        || string(&manifest, "repair")? != "warning-portability"
    {
        return Err("P17 portability baseline schema 不符".into());
    }
    let files = array(&manifest, "files")?;
    if files.len() != WARNING_PORTABILITY_FILES.len() {
        return Err("P17 portability baseline 來源數不符".into());
    }
    let mut original_root = None;
    for (item, (relative, digest)) in files.iter().zip(WARNING_PORTABILITY_FILES) {
        object(item, &["source", "snapshot", "sha256"])?;
        let source = Path::new(string(item, "source")?);
        let snapshot = evidence
            .join("p17-warning-portability-before")
            .join(relative.replace('/', "__"));
        assert_warning_baseline_root(&mut original_root, source, relative)?;
        if string(item, "snapshot")? != snapshot.display().to_string()
            || string(item, "sha256")? != digest
        {
            return Err("P17 portability original root／baseline 不一致".into());
        }
        sha(&snapshot, digest)?;
    }
    original_root.ok_or_else(|| "P17 portability original root 缺失".into())
}

fn assert_warning_baseline_root(
    original_root: &mut Option<PathBuf>,
    source: &Path,
    relative: &str,
) -> Result<(), String> {
    let mut candidate = source.to_path_buf();
    for _ in Path::new(relative).components() {
        if !candidate.pop() {
            return Err("P17 portability original root 無法推導".into());
        }
    }
    if !source.is_absolute()
        || candidate.join(relative) != source
        || original_root
            .as_ref()
            .is_some_and(|prior| prior != &candidate)
    {
        return Err("P17 portability original root 不一致".into());
    }
    *original_root = Some(candidate);
    Ok(())
}

fn assert_warning_relative<'a>(
    original_root: &Path,
    recorded: &'a str,
) -> Result<&'a Path, String> {
    let path = Path::new(recorded);
    let relative = path
        .strip_prefix(original_root)
        .map_err(|_| format!("P17 portability source 越出原repo：{recorded}"))?;
    if relative.as_os_str().is_empty()
        || relative
            .components()
            .any(|part| !matches!(part, Component::Normal(_)))
        || original_root.join(relative) != path
    {
        return Err(format!(
            "P17 portability source 非固定 repo 路徑：{recorded}"
        ));
    }
    Ok(relative)
}

fn host_entry_overlay_current_sources(
    expected: &mut BTreeMap<PathBuf, String>,
    host_entry: &HostEntryReview,
) -> Result<(), String> {
    for (relative, after) in &host_entry.changed_after {
        if !HOST_ENTRY_PATHS.contains(&relative.as_str()) {
            return Err(format!("P17 host-entry phase 範圍外來源：{relative}"));
        }
        let path = Path::new(relative);
        let before = &host_entry
            .old_sources
            .get(relative)
            .ok_or("P17 host-entry phase 前態缺失")?
            .before_sha256;
        if expected.get(path) != Some(before) {
            return Err(format!("P17 host-entry phase 舊endpoint 衝突：{relative}"));
        }
        expected.insert(path.to_path_buf(), after.clone());
    }
    Ok(())
}

fn gc_phase_source_transition(
    expected: &mut BTreeMap<PathBuf, String>,
    index: usize,
    relative: &str,
    before: &str,
    after: &str,
) -> Result<(), String> {
    match expected.get(Path::new(relative)).map(String::as_str) {
        Some(prior) if prior == before => {}
        None if index == 1 || index == 2 => {}
        _ => return Err(format!("P17 GC 舊 phase source endpoint 衝突：{relative}")),
    }
    expected.insert(PathBuf::from(relative), after.into());
    Ok(())
}

fn assert_warning_current_sources(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    exit: Option<&ExitReview>,
    host_entry: Option<&HostEntryReview>,
    gc: Option<&GcReview>,
    producer: Option<&ProducerUpdateReview>,
    debug_vm: Option<&DebugVmReview>,
    debug_hook: Option<&DebugHookReview>,
    final_source: Option<&FinalSourceReview>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    if final_source.and_then(|review| review.verified.as_ref()).is_some() != verified.is_some() {
        return Err("P17 portability final context 傳遞不一致".into());
    }
    if let Some(verified) = verified {
        verified.check(current_root, evidence)?;
    }
    let archived = StrictJsonParser::parse(
        &fs::read_to_string(evidence.join("p17-phase-debug-console-suite-fail/gate-P17.json"))
            .map_err(|error| error.to_string())?,
    )?;
    let review = StrictJsonParser::parse(
        &fs::read_to_string(evidence.join("p17-phase-assert-warning-source-impact-review.json"))
            .map_err(|error| error.to_string())?,
    )?;
    let mut expected = BTreeMap::<PathBuf, String>::new();
    for item in array(&archived, "source_inputs")? {
        object(item, &["path", "sha256"])?;
        let relative = assert_warning_relative(original_root, string(item, "path")?)?;
        if expected
            .insert(relative.to_path_buf(), string(item, "sha256")?.into())
            .is_some()
        {
            return Err("P17 portability 舊phase重複來源".into());
        }
    }
    for (relative, before) in WARNING_FILES.into_iter().chain(WARNING_PORTABILITY_FILES) {
        let path = Path::new(relative);
        if !expected.contains_key(path) {
            return Err(format!("P17 portability 舊phase 缺受影響來源：{relative}"));
        }
        let endpoint = assert_warning_warning_endpoint(
            original_root,
            relative,
            before,
            exit,
            host_entry.map(|review| &review.old_sources),
        )?;
        expected.insert(
            path.to_path_buf(),
            manifest::sha256(&endpoint)?,
        );
    }
    for proof in array(&review, "builds")?
        .iter()
        .chain(array(&review, "regressions")?)
    {
        for item in array(proof, "source_inputs")? {
            object(item, &["path", "sha256"])?;
            let relative = assert_warning_relative(original_root, string(item, "path")?)?;
            let digest = string(item, "sha256")?;
            if expected.get(relative).is_some_and(|prior| prior != digest) {
                return Err(format!(
                    "P17 portability fresh source 衝突：{}",
                    relative.display()
                ));
            }
            expected.insert(relative.to_path_buf(), digest.into());
        }
    }
    for item in array(&review, "new_tests")? {
        let relative = Path::new(string(item, "path")?);
        if ![ASSERT_NEW_TEST]
            .into_iter()
            .chain(WARNING_NEW_TESTS)
            .any(|allowed| relative == Path::new(allowed))
        {
            return Err("P17 portability 範圍外新測試".into());
        }
        let digest = string(item, "after_sha256")?;
        if expected.get(relative).is_some_and(|prior| prior != digest) {
            return Err("P17 portability 新測試 SHA 與proof衝突".into());
        }
        expected.insert(relative.to_path_buf(), digest.into());
    }
    if let Some(host_entry) = host_entry {
        host_entry_overlay_current_sources(&mut expected, host_entry)?;
    }
    if let Some(exit) = exit {
        let v2 = StrictJsonParser::parse(
            &fs::read_to_string(&exit.input.path).map_err(|error| error.to_string())?,
        )?;
        if let Some(parser_update) = v2.get("parser_update") {
            let parser = Path::new(EXIT_PARSER_PATH);
            if expected.get(parser).map(String::as_str) != Some(EXIT_PARSER_BEFORE_SHA) {
                return Err("P17 parser update phase 舊 endpoint 不符".into());
            }
            expected.insert(
                parser.to_path_buf(),
                string(field(parser_update, "change")?, "after_sha256")?.into(),
            );
        }
        let changed = array(&v2, "pre_exit_changes")?
            .iter()
            .chain(array(&v2, "exit_changes")?)
            .chain(array(&v2, "tool_changes")?)
            .chain(array(&v2, "new_tests")?);
        for item in changed {
            let relative = Path::new(string(item, "path")?);
            expected.insert(relative.to_path_buf(), string(item, "after_sha256")?.into());
        }
        for (proof_index, proof) in array(&v2, "builds")?
            .iter()
            .chain(array(&v2, "regressions")?)
            .enumerate()
        {
            for item in array(proof, "source_inputs")? {
                object(item, &["path", "sha256"])?;
                let relative = assert_warning_relative(original_root, string(item, "path")?)?;
                let digest = string(item, "sha256")?;
                if v2.get("cli_unit_test_only_update").is_some()
                    && (15..=26).contains(&proof_index)
                    && relative == Path::new(EXIT_CLI_BINARY_PATH)
                    && expected.get(relative).map(String::as_str) == Some(
                        if v2.get("cli_diagnostics_update").is_some() {
                            EXIT_CLI_DIAGNOSTICS_AFTER_SHA
                        } else if v2.get("cli_version_banner_update").is_some() {
                            EXIT_CLI_VERSION_AFTER_SHA
                        } else if v2.get("cli_binary_file_prefix_update").is_some() {
                            EXIT_CLI_BINARY_AFTER_SHA
                        } else {
                            EXIT_CLI_LIB_TEST_ONLY_SHA
                        },
                    )
                    && digest == EXIT_CLI_LIB_SHA
                {
                    exit_cli_unit_historical_input(original_root, evidence, item)?;
                    continue;
                }
                if v2.get("cli_binary_file_prefix_update").is_some()
                    && (27..=33).contains(&proof_index)
                    && relative == Path::new(EXIT_CLI_BINARY_PATH)
                    && expected.get(relative).map(String::as_str) == Some(
                        if v2.get("cli_diagnostics_update").is_some() {
                            EXIT_CLI_DIAGNOSTICS_AFTER_SHA
                        } else if v2.get("cli_version_banner_update").is_some() {
                            EXIT_CLI_VERSION_AFTER_SHA
                        } else {
                            EXIT_CLI_BINARY_AFTER_SHA
                        },
                    )
                    && digest == EXIT_CLI_LIB_TEST_ONLY_SHA
                {
                    let snapshot = evidence.join(EXIT_CLI_UNIT_GREEN_DIR).join("0-lib.rs");
                    console_cli_public_file(&snapshot, &evidence.join(EXIT_CLI_UNIT_GREEN_DIR))?;
                    exit_cli_lib_historical_input(
                        original_root,
                        item,
                        &snapshot,
                        EXIT_CLI_LIB_TEST_ONLY_SHA,
                    )?;
                    continue;
                }
                if expected.get(relative).is_some_and(|prior| prior != digest) {
                    return Err(format!("P17 Exit fresh source 衝突：{}", relative.display()));
                }
                expected.insert(relative.to_path_buf(), digest.into());
            }
        }
        if v2.get("warn_argument_update").is_some() {
            for (relative, before, after) in [
                (EXIT_WARN_VM_PATH, EXIT_WARN_VM_BEFORE_SHA, EXIT_WARN_VM_AFTER_SHA),
                (EXIT_WARN_BASIC_PATH, EXIT_WARN_BASIC_BEFORE_SHA, EXIT_WARN_BASIC_AFTER_SHA),
            ] {
                let path = PathBuf::from(relative);
                if expected.get(&path).map(String::as_str) != Some(before) {
                    return Err(format!("P17 warn argument 舊 phase source endpoint 衝突：{relative}"));
                }
                expected.insert(path, after.into());
            }
        }
        if v2.get("ctrl_c_update").is_some() {
            for (relative, before, after) in EXIT_CTRL_CHANGES {
                let path = PathBuf::from(relative);
                if expected.get(&path).map(String::as_str) != Some(before) {
                    return Err(format!("P17 Ctrl-C 舊 phase source endpoint 衝突：{relative}"));
                }
                expected.insert(path, after.into());
            }
            if expected.insert(PathBuf::from(EXIT_CTRL_TEST_PATH), EXIT_CTRL_TEST_SHA.into()).is_some() {
                return Err("P17 Ctrl-C 公開測試舊 phase inventory 重複".into());
            }
        }
        if let Some(reference) = v2.get("public_cli_test_update") {
            let proof = StrictJsonParser::parse(
                &fs::read_to_string(string(reference, "path")?)
                    .map_err(|error| error.to_string())?,
            )?;
            let rows = array(&proof, "rows")?;
            if rows.len() != 2 {
                return Err("P17 Console CLI 公開 phase 來源雙版缺失".into());
            }
            let mut digest = None;
            for row in rows {
                let source = array(row, "source_inputs")?
                    .first()
                    .ok_or("P17 Console CLI 公開 phase 來源缺失")?;
                if string(source, "path")?
                    != original_root.join(CONSOLE_CLI_TEST_PATH).display().to_string()
                {
                    return Err("P17 Console CLI 公開 phase 來源路徑不符".into());
                }
                let current = string(source, "sha256")?;
                if digest.replace(current).is_some_and(|prior| prior != current) {
                    return Err("P17 Console CLI 公開 phase 來源雙版 SHA 不符".into());
                }
            }
            if v2.get("parser_update").is_some() && digest != Some(CONSOLE_CLI_REPL_SHA) {
                return Err("P17 Console CLI 公開 phase 舊來源 SHA 不符".into());
            }
            if expected
                .insert(
                    PathBuf::from(CONSOLE_CLI_TEST_PATH),
                    if v2.get("cli_version_banner_update").is_some() {
                        CONSOLE_CLI_VERSION_SHA.into()
                    } else {
                        digest.ok_or("P17 Console CLI 公開 phase 來源缺失")?.into()
                    },
                )
                .is_some()
            {
                return Err("P17 Console CLI 公開 phase 來源重複".into());
            }
        }
        if v2.get("public_repl_test_update").is_some()
            && expected
                .insert(PathBuf::from(EXIT_PUBLIC_REPL_TEST_PATH), EXIT_PUBLIC_REPL_SHA.into())
                .is_some()
        {
            return Err("P17 REPL 公開 phase 來源重複".into());
        }
        if v2.get("cli_binary_file_prefix_update").is_some()
            && expected
                .insert(PathBuf::from(EXIT_CLI_BINARY_TEST_PATH), EXIT_CLI_BINARY_TEST_SHA.into())
                .is_some()
        {
            return Err("P17 CLI binary prefix 公開 phase 來源重複".into());
        }
        if v2.get("cli_version_banner_update").is_some()
            && expected
                .insert(PathBuf::from(EXIT_CLI_VERSION_TEST_PATH), EXIT_CLI_VERSION_TEST_SHA.into())
                .is_some()
        {
            return Err("P17 CLI version banner 公開 phase 來源重複".into());
        }
        if v2.get("cli_diagnostics_update").is_some()
            && expected
                .insert(PathBuf::from(EXIT_CLI_DIAGNOSTICS_TEST_PATH), EXIT_CLI_DIAGNOSTICS_TEST_SHA.into())
                .is_some()
        {
            return Err("P17 CLI diagnostics 公開 phase 來源重複".into());
        }
        if v2.get("warn_argument_update").is_some()
            && expected.insert(PathBuf::from(EXIT_WARN_TEST_PATH), EXIT_WARN_TEST_SHA.into()).is_some()
        {
            return Err("P17 warn argument 公開 phase 來源重複".into());
        }
    }
    if let Some(gc) = gc {
        let value = StrictJsonParser::parse(
            &fs::read_to_string(&gc.input.path).map_err(|error| error.to_string())?,
        )?;
        gc_review_shape(&value, current_root, evidence)?;
        for (index, (relative, before)) in [
            (GC_BASIC_PATH, GC_BASIC_BEFORE_SHA),
            (GC_TABLE_PATH, GC_TABLE_BEFORE_SHA),
            (GC_METAMETHOD_PATH, GC_METAMETHOD_BEFORE_SHA),
            (GC_HEAP_PATH, GC_HEAP_BEFORE_SHA),
        ].into_iter().enumerate() {
            sha(&gc_before_source_with_verified(current_root, evidence,
                relative, verified)?, before)?;
            gc_phase_source_transition(
                &mut expected,
                index,
                relative,
                before,
                string(&array(&value, "changes")?[index], "after_sha256")?,
            )?;
        }
        if expected.get(Path::new(GC_TOOL_PATH)).map(String::as_str) != Some(GC_TOOL_BEFORE_SHA) {
            return Err("P17 GC 舊工具 phase endpoint 衝突".into());
        }
        expected.insert(
            PathBuf::from(GC_TOOL_PATH),
            string(&array(&value, "tool_changes")?[0], "after_sha256")?.into(),
        );
        if expected.insert(PathBuf::from(GC_TEST_PATH), GC_TEST_SHA.into()).is_some() {
            return Err("P17 GC 新測試 phase inventory 重複".into());
        }
    }
    if let Some(producer) = producer {
        if expected.get(Path::new(GC_TOOL_PATH)).map(String::as_str)
            != Some(producer.tool_after_sha.as_str())
        {
            return Err("P17 producer 新 tool phase endpoint 衝突".into());
        }
        for ((relative, before), after) in [
            (PRODUCER_STRING_PATH, PRODUCER_STRING_BEFORE_SHA),
            (PRODUCER_NATIVE_PATH, PRODUCER_NATIVE_BEFORE_SHA),
        ].into_iter().zip(&producer.after_hashes) {
            if expected.get(Path::new(relative)).map(String::as_str) != Some(before) {
                return Err(format!("P17 producer 舊 phase endpoint 衝突：{relative}"));
            }
            expected.insert(PathBuf::from(relative), after.clone());
        }
        if expected.insert(PathBuf::from(PRODUCER_SDK_TEST_PATH), PRODUCER_SDK_TEST_SHA.into()).is_some() {
            return Err("P17 producer 新 SDK 測試 inventory 重複".into());
        }
    }
    if debug_vm.is_some() {
        if expected.get(Path::new(DEBUG_VM_PATH)).map(String::as_str)
            != Some(DEBUG_VM_BEFORE_SHA)
        {
            return Err("P17 debug VM 舊 phase endpoint 衝突".into());
        }
        expected.insert(PathBuf::from(DEBUG_VM_PATH), DEBUG_VM_AFTER_SHA.into());
        if expected.insert(PathBuf::from(DEBUG_VM_TEST_PATH), DEBUG_VM_TEST_SHA.into()).is_some() {
            return Err("P17 debug VM 新測試 inventory 重複".into());
        }
    }
    if debug_hook.is_some() {
        if expected.get(Path::new(DEBUG_VM_PATH)).map(String::as_str)
            != Some(DEBUG_VM_AFTER_SHA)
        {
            return Err("P17 debug hook 舊 phase endpoint 衝突".into());
        }
        expected.insert(PathBuf::from(DEBUG_VM_PATH), DEBUG_HOOK_VM_AFTER_SHA.into());
        if expected.insert(PathBuf::from(DEBUG_HOOK_TEST_PATH), DEBUG_HOOK_TEST_SHA.into()).is_some() {
            return Err("P17 debug hook 新測試 inventory 重複".into());
        }
    }
    if final_source.is_some() {
        for (relative, before, after) in FINAL_SOURCE_CHANGES {
            if expected.get(Path::new(relative)).map(String::as_str) != Some(before) {
                return Err(format!("P17 final source 舊 phase endpoint 衝突：{relative}"));
            }
            expected.insert(PathBuf::from(relative), after.into());
        }
        if expected.insert(PathBuf::from(FINAL_COUNT_TEST_PATH),
            FINAL_COUNT_TEST_SHA.into()).is_some()
        {
            return Err("P17 final count test inventory 重複".into());
        }
    }
    if final_source.is_some_and(|review| review.successor.is_some()) {
        for (relative, before, after, _, _) in FINAL_SUCCESSOR_CHANGES {
            if expected.get(Path::new(relative)).map(String::as_str) != Some(before) {
                return Err(format!("P17 dump/count successor 舊 phase endpoint 衝突：{relative}"));
            }
            expected.insert(PathBuf::from(relative), after.into());
        }
        let tool = if verified.is_some() {
            FINAL_COUNT_SUCCESSOR_PRIOR_TOOL_SHA.to_owned()
        } else {
            final_successor_tool_source(current_root, evidence)?
                .ok_or("P17 dump/count successor 缺 tool self-edge")?
        };
        if expected.get(Path::new(GC_TOOL_PATH)).map(String::as_str)
            != producer.map(|review| review.tool_after_sha.as_str())
        {
            return Err("P17 dump/count successor 舊 tool endpoint 衝突".into());
        }
        expected.insert(PathBuf::from(GC_TOOL_PATH), tool);
    }
    if final_source.is_some_and(|review| review.count_successor.is_some()) {
        for (relative, before, after, _, _, _) in FINAL_COUNT_SUCCESSOR_CHANGES {
            if expected.get(Path::new(relative)).map(String::as_str) != Some(before) {
                return Err(format!("P17 full-db count successor 舊 phase endpoint 衝突：{relative}"));
            }
            expected.insert(PathBuf::from(relative), after.into());
        }
        let tool = if verified.is_some() {
            FINAL_DEBUG_SUCCESSOR_PRIOR_TOOL_SHA.to_owned()
        } else {
            final_count_successor_tool_source(current_root, evidence)?
                .ok_or("P17 full-db count successor 缺 tool self-edge")?
        };
        if expected.get(Path::new(GC_TOOL_PATH)).map(String::as_str)
            != Some(FINAL_COUNT_SUCCESSOR_PRIOR_TOOL_SHA)
        {
            return Err("P17 full-db count successor 舊 tool endpoint 衝突".into());
        }
        expected.insert(PathBuf::from(GC_TOOL_PATH), tool);
    }
    if final_source.is_some_and(|review| review.debug_successor.is_some()) {
        for (relative, before, after, _) in FINAL_DEBUG_SUCCESSOR_CHANGES {
            if expected.get(Path::new(relative)).map(String::as_str) != Some(before) {
                return Err(format!("P17 final debug 舊 source endpoint 衝突：{relative}"));
            }
            expected.insert(PathBuf::from(relative), after.into());
        }
        if expected.insert(PathBuf::from(FINAL_DEBUG_SUCCESSOR_TEST_PATH),
            FINAL_DEBUG_SUCCESSOR_TEST_AFTER_SHA.into()).is_some()
        {
            return Err("P17 final debug 新測試 inventory 重複".into());
        }
        let tool = if let Some(verified) = verified {
            verified.check(current_root, evidence)?;
            verified.tool_sha.clone()
        } else {
            final_debug_successor_tool_source(current_root, evidence)?
                .ok_or("P17 final debug 缺 B03 self-edge")?
        };
        if expected.get(Path::new(GC_TOOL_PATH)).map(String::as_str)
            != Some(FINAL_DEBUG_SUCCESSOR_PRIOR_TOOL_SHA)
        {
            return Err("P17 final debug 舊 B03 endpoint 衝突".into());
        }
        expected.insert(PathBuf::from(GC_TOOL_PATH), tool);
    }
    if let Some(verified) = verified.filter(|verified| verified.repair_active) {
        for (relative, before, after) in FINAL_REPAIR_PRODUCT_CHANGES {
            if expected.get(Path::new(relative)).map(String::as_str) != Some(before) {
                return Err(format!("P17 final repair 舊 source endpoint 衝突：{relative}"));
            }
            let pinned = verified.source_shas.get(&current_root.join(relative))
                .ok_or_else(|| format!("P17 final repair current source 缺失：{relative}"))?;
            if pinned.as_str() != product_successor_sha(relative, heap_successor_sha(relative,
                core_successor_sha(relative, after, verified.core_successor_active),
                verified.heap_successor_active), verified.product_successor_active) {
                return Err(format!("P17 final repair current source SHA 不符：{relative}"));
            }
            expected.insert(PathBuf::from(relative), pinned.clone());
        }
    }
    if let Some(verified) = verified {
        let relative = Path::new("xtask/src/p17/manifest.rs");
        let before = "3a90b8ce8e04e4323f7ba828abf708fa89c9060002f7bbf7194f05501c1c7155";
        if expected.get(relative).map(String::as_str) != Some(before) {
            return Err("P17 manifest SHA 舊 phase endpoint 不符".into());
        }
        let recorded = original_root.join(relative).display().to_string();
        let historical = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}", report::q(&recorded), report::q(before),
        ))?;
        final_manifest_historical_input(
            original_root, current_root, evidence, &historical, Some(verified))?
            .ok_or("P17 manifest SHA 缺 typed edge")?;
        expected.insert(relative.to_path_buf(),
            "69af1ef83b674251a816bf9b88cf37317cb742e3804a6638154960ea0c855c8e".into());
    }
    if verified.is_some_and(|context| context.heap_successor_active) {
        sparse_gc_current_expected(&mut expected, current_root, evidence, verified)?;
    }
    let environment = runner::environment(current_root)?;
    let registry = parse_registry(current_root, &environment.target)?;
    let mut inventory = phase_source_paths_with_gc(
        current_root, true, true, true, true, exit.is_some(),
        exit.is_some_and(|review| review.ctrl_c_updated),
        gc.is_some(),
        producer.is_some(),
        debug_vm.is_some(),
        debug_hook.is_some(),
        final_source.is_some(),
        final_source.is_some_and(|review| review.debug_successor.is_some()),
    )?
        .into_iter()
        .map(|path| {
            path.strip_prefix(current_root)
                .map(Path::to_path_buf)
                .map_err(|_| "P17 portability current inventory 越界".into())
        })
        .collect::<Result<BTreeSet<_>, String>>()?;
    if verified.is_some_and(|context| context.product_successor_active) {
        let context = verified.unwrap();
        if expected.get(Path::new(PRODUCT_SCANNER_PATH)).map(String::as_str) != Some(PRODUCT_SCANNER_BEFORE_SHA) {
            return Err("P17 product successor scanner 舊 current row 不符".into());
        }
        if context.source_shas.get(&current_root.join(PRODUCT_SCANNER_PATH)).map(String::as_str)
            != Some(PRODUCT_SCANNER_CURRENT_SHA) {
            return Err("P17 product successor scanner current row 缺失".into());
        }
        expected.insert(PathBuf::from(PRODUCT_SCANNER_PATH), PRODUCT_SCANNER_CURRENT_SHA.into());
        for (relative, before, after) in [
            (FINAL_CODEC_PATH, FINAL_CODEC_SHA, PRODUCT_CODEC_AFTER_SHA),
            (PRODUCT_BUDGET_PATH, PRODUCT_BUDGET_BEFORE_SHA, PRODUCT_BUDGET_AFTER_SHA),
            (PRODUCT_RESOLVE_PATH, PRODUCT_RESOLVE_BEFORE_SHA, PRODUCT_RESOLVE_AFTER_SHA),
        ] {
            if expected.get(Path::new(relative)).map(String::as_str) != Some(before)
                || context.source_shas.get(&current_root.join(relative)).map(String::as_str)
                    != Some(after) {
                return Err(format!("P17 product successor current row 缺失／衝突：{relative}"));
            }
            expected.insert(PathBuf::from(relative), after.into());
        }
        for (relative, before, after) in [
            (PRODUCT_STACK_PATH, PRODUCT_STACK_BEFORE_SHA, PRODUCT_STACK_CURRENT_SHA),
            (PRODUCT_BASIC_PATH,
                "9e18df7a5a90d6022dc1003a14c2b842ce9b6d7e7406d3bab080df4e364b1b7b",
                PRODUCT_BASIC_CURRENT_SHA),
        ] {
            if expected.get(Path::new(relative)).map(String::as_str) != Some(before)
                || context.source_shas.get(&current_root.join(relative)).map(String::as_str)
                    != Some(after) {
                return Err(format!("P17 product current row 缺失／衝突：{relative}"));
            }
            expected.insert(PathBuf::from(relative), after.into());
        }
    }
    if let Some(context) = verified.filter(|context| context.product_successor_active) {
        let names = expected.get(Path::new(DEBUG_VM_TEST_PATH))
            .ok_or("P17 product names test inventory 歷史端點缺失")?;
        if names != DEBUG_VM_TEST_SHA { return Err("P17 product names test 舊端點衝突".into()); }
        let current = product_names_current_sha_with_verified(current_root, evidence, Some(context))?;
        expected.insert(PathBuf::from(DEBUG_VM_TEST_PATH), current.into());
        let before = expected.get(Path::new(FINAL_COUNT_TEST_PATH))
            .ok_or("P17 product count test inventory 歷史端點缺失")?;
        let current = product_count_current_sha_with_verified(current_root, evidence,
            before, Some(context))?;
        expected.insert(PathBuf::from(FINAL_COUNT_TEST_PATH), current.into());
    }
    if verified.is_some_and(|context| context.heap_successor_active)
        && !inventory.contains(Path::new(GC_MOD_PATH)) {
        return Err("P17 sparse GC module current inventory 缺失".into());
    }
    for family in &registry.families {
        for fixture in &family.fixtures {
            inventory.insert(
                Path::new(&fixture.path)
                    .strip_prefix(current_root)
                    .map_err(|_| "P17 portability fixture 越界")?
                    .to_path_buf(),
            );
        }
    }
    assert_warning_inventory_matches(&expected, &inventory)?;
    if let Some(verified) = verified {
        for (path, digest) in &expected {
            if let Some(pinned) = verified.source_shas.get(&current_root.join(path)) {
                if pinned != digest {
                    return Err(format!("P17 portability final current SHA 不符：{}", path.display()));
                }
            }
        }
        if verified.repair_active {
            for (relative, _, after) in FINAL_REPAIR_PRODUCT_CHANGES {
                let current_after = product_successor_sha(relative, heap_successor_sha(relative,
                    core_successor_sha(relative, after, verified.core_successor_active),
                    verified.heap_successor_active), verified.product_successor_active);
                if expected.get(Path::new(relative)).map(String::as_str) != Some(current_after)
                    || verified.source_shas.get(&current_root.join(relative))
                        .map(String::as_str) != Some(current_after) {
                    return Err(format!("P17 portability final product 映射不符：{relative}"));
                }
            }
            if expected.get(Path::new(GC_TOOL_PATH)).map(String::as_str)
                != Some(verified.tool_sha.as_str())
                || verified.source_shas.get(&current_root.join(GC_TOOL_PATH))
                    .map(String::as_str) != Some(verified.tool_sha.as_str()) {
                return Err("P17 portability final tool self-edge 映射不符".into());
            }
        }
    }
    for (relative, digest) in expected {
        let recorded = original_root.join(&relative);
        report::phase_relocated_source(
            original_root,
            current_root,
            &recorded.display().to_string(),
            &digest,
        )?;
    }
    Ok(())
}

fn sparse_gc_current_expected(
    expected: &mut BTreeMap<PathBuf, String>,
    current_root: &Path,
    evidence: &Path,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let context = verified.filter(|context| context.heap_successor_active)
        .ok_or("P17 sparse GC module 缺已驗後繼 context")?;
    context.check(current_root, evidence)?;
    if context.source_shas.len() != (if context.product_successor_active { 69 } else { 66 })
        || context.source_shas.get(&current_root.join(GC_MOD_PATH)).map(String::as_str)
            != Some(GC_MOD_AFTER_SHA)
    {
        return Err("P17 sparse GC module current row 缺失／SHA不符".into());
    }
    let relative = PathBuf::from(GC_MOD_PATH);
    match expected.get(&relative).map(String::as_str) {
        Some(GC_MOD_BEFORE_SHA) | Some(GC_MOD_AFTER_SHA) => {
            expected.insert(relative, GC_MOD_AFTER_SHA.into());
            Ok(())
        }
        Some(_) => Err("P17 sparse GC module current source 舊 SHA 不符".into()),
        None => Err("P17 sparse GC module current source 原列缺失".into()),
    }
}

fn assert_warning_inventory_matches(
    expected: &BTreeMap<PathBuf, String>,
    inventory: &BTreeSet<PathBuf>,
) -> Result<(), String> {
    if *inventory != expected.keys().cloned().collect::<BTreeSet<_>>() {
        return Err("P17 portability current source inventory 缺失／範圍外".into());
    }
    Ok(())
}

fn assert_warning_phase9_input(
    root: &Path,
    value: &StrictJsonValue,
    exit: Option<&ExitReview>,
    host_sources: Option<&BTreeMap<String, report::HistoricalSource>>,
) -> Result<report::Input, String> {
    if let Some(exit) = exit {
        let path = string(value, "path")?;
        if let Ok(relative) = Path::new(path).strip_prefix(root) {
            let relative = relative.display().to_string();
            // 已存在的 v1 endpoint 必須先驗；它的錯誤不可改由後批快照掩蓋。
            if exit.v1_endpoints.contains_key(&relative) {
                return exit.v1_input(value);
            }
            if exit.warn_argument_updated && relative == EXIT_WARN_BASIC_PATH
                && string(value, "sha256")? == EXIT_WARN_BASIC_BEFORE_SHA
            {
                let snapshot = PathBuf::from(
                    exit.safe_environment.path.as_str()
                ).parent().ok_or("P17 warn argument evidence 根目錄缺失")?
                    .join(EXIT_WARN_SOURCE_DIR)
                    .join("before-crates__rivetlua-runtime__src__stdlib__basic.rs");
                sha(&snapshot, EXIT_WARN_BASIC_BEFORE_SHA)?;
                return Ok(report::Input { path: path.into(), sha256: EXIT_WARN_BASIC_BEFORE_SHA.into() });
            }
            if exit.ctrl_c_updated {
                if let Some(index) = exit_ctrl_c_source_index(&relative) {
                    let (_, before, _) = EXIT_CTRL_CHANGES[index];
                    if string(value, "sha256")? == before {
                        let evidence = Path::new(&exit.safe_environment.path)
                            .parent().ok_or("P17 Ctrl-C evidence 根目錄缺失")?;
                        exit_ctrl_c_before_source_with_verified(
                            &exit.current_root, evidence, &relative,
                            exit.verified.as_ref())?;
                        return Ok(report::Input {
                            path: path.into(), sha256: before.into(),
                        });
                    }
                }
            }
            if HOST_ENTRY_PATHS.contains(&relative.as_str()) {
                if let Some(source) = host_sources.and_then(|sources| sources.get(&relative)) {
                    if string(value, "sha256")? != source.before_sha256 {
                        return Err(format!("P17 host-entry 第九次 phase source 前態不符：{path}"));
                    }
                    sha(&source.snapshot, &source.before_sha256)?;
                    return Ok(report::Input {
                        path: path.into(),
                        sha256: source.before_sha256.clone(),
                    });
                }
            }
        }
        exit.v1_input(value)
    } else {
        input(value)
    }
}

fn assert_warning_warning_endpoint(
    root: &Path,
    relative: &str,
    before: &str,
    exit: Option<&ExitReview>,
    host_sources: Option<&BTreeMap<String, report::HistoricalSource>>,
) -> Result<PathBuf, String> {
    if let Some(exit) = exit {
        // Warning 的當時終點先取已驗 v1；錯誤快照不得由後批host補救。
        if let Some(source) = exit.v1_endpoints.get(relative) {
            sha(&source.snapshot, &source.before_sha256)?;
            return Ok(source.snapshot.clone());
        }
        if exit.warn_argument_updated && relative == EXIT_WARN_BASIC_PATH {
            if before != WARNING_FILES[1].1 {
                return Err("P17 warn argument basic Warning 前態不符".into());
            }
            let evidence = Path::new(&exit.safe_environment.path)
                .parent().ok_or("P17 warn argument evidence 根目錄缺失")?;
            let snapshot = evidence.join(EXIT_WARN_SOURCE_DIR)
                .join("before-crates__rivetlua-runtime__src__stdlib__basic.rs");
            sha(&snapshot, EXIT_WARN_BASIC_BEFORE_SHA)?;
            return Ok(snapshot);
        }
        // errors.rs 在Warning批次未變；後續host-entry修補才改動它。
        if relative == HOST_ENTRY_PATHS[1] {
            if let Some(sources) = host_sources {
                let source = sources
                    .get(relative)
                    .ok_or("P17 Warning host-entry errors 舊來源缺失")?;
                // 呼叫點的 before 來自固定 WARNING_FILES；review 已把舊SHA錨到基線。
                if source.before_sha256 != before {
                    return Err("P17 Warning host-entry errors 前態不符".into());
                }
                sha(&source.snapshot, &source.before_sha256)?;
                return Ok(source.snapshot.clone());
            }
        }
    }
    Ok(root.join(relative))
}

fn assert_warning_review(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    exit: Option<&ExitReview>,
    host_sources: Option<&BTreeMap<String, report::HistoricalSource>>,
) -> Result<Option<AssertWarningReview>, String> {
    let path = evidence.join("p17-phase-assert-warning-source-impact-review.json");
    if !path.exists() {
        return Ok(None);
    }
    if !fs::symlink_metadata(&path)
        .map_err(|error| error.to_string())?
        .file_type()
        .is_file()
    {
        return Err("P17 Assert/Warning review 非固定一般檔案".into());
    }
    let mut assert_sources = BTreeMap::new();
    let assert_baseline = console_snapshot_manifest(
        root,
        evidence,
        "p17-assert-position-before",
        ASSERT_BASELINE_SHA,
        "assert-position",
        &ASSERT_FILES,
        &[],
        &mut assert_sources,
    )?;
    let mut warning_sources = BTreeMap::new();
    let warning_baseline = console_snapshot_manifest(
        root,
        evidence,
        "p17-warning-before",
        WARNING_BASELINE_SHA,
        "warning",
        &WARNING_FILES,
        &[],
        &mut warning_sources,
    )?;
    let mut portability_sources = BTreeMap::new();
    let portability_baseline = console_snapshot_manifest(
        root,
        evidence,
        "p17-warning-portability-before",
        WARNING_PORTABILITY_BASELINE_SHA,
        "warning-portability",
        &WARNING_PORTABILITY_FILES,
        &[],
        &mut portability_sources,
    )?;
    let mut console_sources = BTreeMap::new();
    for (relative, digest) in WARNING_FILES {
        let path = root.join(relative).display().to_string();
        let source = if relative == ASSERT_FILES[0].0 {
            assert_sources
                .get(&path)
                .ok_or("P17 Assert VM 舊前態缺失")?
        } else {
            warning_sources
                .get(&path)
                .ok_or("P17 Warning Console 前態缺失")?
        };
        let expected = if relative == ASSERT_FILES[0].0 {
            ASSERT_FILES[0].1
        } else {
            digest
        };
        if source.before_sha256 != expected {
            return Err(format!("P17 Assert/Warning Console 前態不符：{relative}"));
        }
        console_sources.insert(
            path,
            report::HistoricalSource {
                before_sha256: expected.into(),
                snapshot: source.snapshot.clone(),
            },
        );
    }
    if warning_sources
        .get(&root.join(ASSERT_FILES[0].0).display().to_string())
        .is_none_or(|source| source.before_sha256 != WARNING_FILES[0].1)
        || warning_sources
            .get(&root.join(ASSERT_FILES[1].0).display().to_string())
            .is_none_or(|source| source.before_sha256 != ASSERT_FILES[1].1)
    {
        return Err("P17 Assert 中間態 VM／basic 鏈不符".into());
    }
    sha(
        &evidence.join("p17-phase-debug-console-source-impact-review.json"),
        ASSERT_WARNING_CONSOLE_SHA,
    )?;
    let (archive_manifest, accepted_report, accepted_receipt, accepted) =
        assert_warning_archive(root, evidence)?;
    let historical_environment = report::parse_historical_environment(
        field(field(&accepted, "configuration")?, "environment")?,
        &runner::environment(root)?,
    )?;
    let mut accepted_paths = BTreeSet::new();
    for item in array(&accepted, "source_inputs")? {
        object(item, &["path", "sha256"])?;
        let path = string(item, "path")?;
        if !accepted_paths.insert(path.to_owned()) {
            return Err("P17 Assert/Warning 第九次 phase 重複 source".into());
        }
        if let Some(source) = console_sources
            .get(path)
            .or_else(|| portability_sources.get(path))
        {
            if string(item, "sha256")? != source.before_sha256 {
                return Err(format!(
                    "P17 Assert/Warning 第九次 phase source 前態不符：{path}"
                ));
            }
            sha(&source.snapshot, &source.before_sha256)?;
        } else {
            assert_warning_phase9_input(root, item, exit, host_sources)?;
        }
    }
    for (relative, _) in WARNING_FILES {
        if !accepted_paths.contains(&root.join(relative).display().to_string()) {
            return Err(format!(
                "P17 Assert/Warning 第九次 phase source 缺失：{relative}"
            ));
        }
    }
    for relative in [ASSERT_NEW_TEST].into_iter().chain(WARNING_NEW_TESTS) {
        if accepted_paths.contains(&root.join(relative).display().to_string()) {
            return Err(format!(
                "P17 Assert/Warning 新測試出現在舊phase：{relative}"
            ));
        }
    }
    let environment = runner::environment(root)?;
    let registry = parse_registry(root, &environment.target)?;
    let mut expected_old = phase_source_paths(root, true, true, true, false, false)?
        .into_iter()
        .map(|path| path.display().to_string())
        .collect::<BTreeSet<_>>();
    for family in &registry.families {
        for fixture in &family.fixtures {
            expected_old.insert(fixture.path.clone());
        }
    }
    if accepted_paths != expected_old {
        return Err("P17 Assert/Warning 第九次 phase source inventory 缺失／範圍外".into());
    }
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    assert_warning_header(&value)?;
    let assert_vm = root.join(ASSERT_FILES[0].0);
    let assert_before = &assert_sources
        .get(&assert_vm.display().to_string())
        .ok_or("P17 Assert VM baseline 缺失")?
        .snapshot;
    let assert_after = &warning_sources
        .get(&assert_vm.display().to_string())
        .ok_or("P17 Assert VM 中間態缺失")?
        .snapshot;
    assert_warning_raw_diff(
        root,
        evidence,
        field(&value, "assert_change")?,
        "assert",
        ASSERT_FILES[0].0,
        assert_before,
        Some(ASSERT_FILES[0].1),
        assert_after,
        WARNING_FILES[0].1,
    )?;
    let mut expected_changes = Vec::new();
    for (relative, before) in WARNING_FILES {
        let effective =
            assert_warning_warning_endpoint(root, relative, before, exit, host_sources)?;
        let after = manifest::sha256(&effective)?;
        if after != before {
            expected_changes.push((relative, before, after));
        }
    }
    if !expected_changes
        .iter()
        .any(|(path, _, _)| *path == CONSOLE_TOOLS_FILES[0].0)
        || !expected_changes
            .iter()
            .any(|(path, _, _)| *path != CONSOLE_TOOLS_FILES[0].0)
    {
        return Err("P17 Assert/Warning 缺工具或產品實際變更".into());
    }
    let changes = array(&value, "warning_changes")?;
    if changes.len() != expected_changes.len() {
        return Err("P17 Warning changes 未涵蓋實際固定來源".into());
    }
    for (item, (relative, before, after)) in changes.iter().zip(expected_changes) {
        let current = root.join(relative);
        let snapshot = &warning_sources
            .get(&current.display().to_string())
            .ok_or("P17 Warning 前態缺失")?
            .snapshot;
        let effective =
            assert_warning_warning_endpoint(root, relative, before, exit, host_sources)?;
        assert_warning_raw_diff(
            root,
            evidence,
            item,
            "warning",
            relative,
            snapshot,
            Some(before),
            &effective,
            &after,
        )?;
    }
    let expected_portability = WARNING_PORTABILITY_FILES
        .iter()
        .filter_map(|(relative, before)| {
            let after = manifest::sha256(&exit.map_or_else(
                || root.join(relative),
                |exit| exit.v1_endpoint(root, relative),
            ))
            .ok()?;
            (after != *before).then_some((*relative, *before, after))
        })
        .collect::<Vec<_>>();
    if expected_portability.len() != WARNING_PORTABILITY_FILES.len() {
        return Err("P17 portability 兩個共用工具檔未具實際改動／不可讀".into());
    }
    let portability = array(&value, "portability_changes")?;
    if portability.len() != expected_portability.len() {
        return Err("P17 portability changes 數不符".into());
    }
    for (item, (relative, before, after)) in portability.iter().zip(expected_portability) {
        let current = root.join(relative);
        let snapshot = &portability_sources
            .get(&current.display().to_string())
            .ok_or("P17 portability 前態缺失")?
            .snapshot;
        assert_warning_raw_diff(
            root,
            evidence,
            item,
            "portability",
            relative,
            snapshot,
            Some(before),
            &exit.map_or_else(|| current.clone(), |exit| exit.v1_endpoint(root, relative)),
            &after,
        )?;
    }
    let new_tests = array(&value, "new_tests")?;
    let expected_new = [ASSERT_NEW_TEST]
        .into_iter()
        .chain(WARNING_NEW_TESTS)
        .collect::<Vec<_>>();
    if new_tests.len() != expected_new.len() {
        return Err("P17 Assert/Warning 新測試數不符".into());
    }
    for (item, relative) in new_tests.iter().zip(expected_new) {
        assert_warning_new_test_absent(root, relative)?;
        let current = root.join(relative);
        if !current.is_file() {
            return Err(format!("P17 Assert/Warning 新測試缺失：{relative}"));
        }
        let effective = exit.map_or_else(|| current.clone(), |exit| exit.v1_endpoint(root, relative));
        let after = manifest::sha256(&effective)?;
        if relative == ASSERT_NEW_TEST && after != ASSERT_NEW_TEST_SHA {
            return Err("P17 Assert 定點測試 SHA 漂移".into());
        }
        assert_warning_raw_diff(
            root,
            evidence,
            item,
            "new-test",
            relative,
            Path::new("/dev/null"),
            None,
            &effective,
            &after,
        )?;
    }
    validate_assert_warning_proofs(root, evidence, &value, exit, host_sources)?;
    Ok(Some(AssertWarningReview {
        input: report::Input::from_path(&path)?,
        baselines: [assert_baseline, warning_baseline, portability_baseline],
        archive_manifest,
        accepted_report,
        accepted_receipt,
        historical_environment,
        console_sources,
        warning_sources,
        portability_sources,
        exit_sources: exit.map_or_else(BTreeMap::new, |exit| {
            exit.v1_endpoints
                .iter()
                .map(|(relative, source)| {
                    (
                        root.join(relative).display().to_string(),
                        report::HistoricalSource {
                            before_sha256: source.before_sha256.clone(),
                            snapshot: source.snapshot.clone(),
                        },
                    )
                })
                .collect()
        }),
        ctrl_c_updated: exit.is_some_and(|review| review.ctrl_c_updated),
        current_root: current_root.to_path_buf(),
        verified: exit.and_then(|review| review.verified.clone()),
    }))
}

fn assert_warning_evidence_file(path: &Path, evidence: &Path) -> Result<(), String> {
    let directory = evidence.join("p17-assert-warning-regressions");
    let canonical_directory = fs::canonicalize(&directory).map_err(|error| error.to_string())?;
    let canonical = fs::canonicalize(path).map_err(|error| error.to_string())?;
    if !path.is_absolute()
        || !path.starts_with(&directory)
        || path
            .components()
            .any(|part| matches!(part, Component::ParentDir))
        || !canonical.starts_with(&canonical_directory)
        || !fs::symlink_metadata(path)
            .map_err(|error| error.to_string())?
            .file_type()
            .is_file()
    {
        return Err(format!(
            "P17 Assert/Warning evidence path 不符：{}",
            path.display()
        ));
    }
    Ok(())
}

fn assert_warning_artifacts(body: &str) -> Result<BTreeMap<String, PathBuf>, String> {
    cargo_named_artifacts(
        body,
        &[
        "p17_internal_replacements",
        "p17_lifecycle",
        "warning_callback",
        ],
    )
}

fn cargo_named_artifacts(
    body: &str,
    expected: &[&str],
) -> Result<BTreeMap<String, PathBuf>, String> {
    let mut found = BTreeMap::new();
    for line in body.lines() {
        let Ok(value) = StrictJsonParser::parse(line) else {
            continue;
        };
        if value.get("reason").and_then(StrictJsonValue::as_str) != Some("compiler-artifact") {
            continue;
        }
        let target = value.get("target").ok_or("P17 Warning Cargo target 缺失")?;
        let Some(name) = target.get("name").and_then(StrictJsonValue::as_str) else {
            continue;
        };
        if !expected.contains(&name) {
            continue;
        }
        let kinds = target
            .get("kind")
            .and_then(StrictJsonValue::as_array)
            .ok_or("P17 Warning Cargo kind 缺失")?;
        if !kinds.iter().any(|item| item.as_str() == Some("test")) {
            return Err("P17 Warning Cargo artifact 非 test".into());
        }
        let path = value
            .get("executable")
            .and_then(StrictJsonValue::as_str)
            .ok_or("P17 Warning Cargo executable 缺失")?;
        if found.insert(name.to_owned(), PathBuf::from(path)).is_some() {
            return Err("P17 Warning Cargo 重複 artifact".into());
        }
    }
    if found.len() != expected.len() {
        return Err("P17 Warning Cargo artifact 零匹配／缺失".into());
    }
    Ok(found)
}

fn assert_warning_build_command(profile: &str) -> Vec<String> {
    let mut command = [
        "cargo",
        "test",
        "--locked",
        "-p",
        "rivetlua-capi",
        "--test",
        "p17_internal_replacements",
        "--test",
        "p17_lifecycle",
        "--test",
        "warning_callback",
        "--no-run",
        "--message-format=json-render-diagnostics",
    ]
    .iter()
    .map(|part| (*part).to_owned())
    .collect::<Vec<_>>();
    if profile == PROFILES[0] {
        command.extend(["--features".into(), "lua55".into()]);
    } else {
        command.extend([
            "--no-default-features".into(),
            "--features".into(),
            "lua54".into(),
        ]);
    }
    command
}

fn exit_build_command(profile: &str, cargo: &str) -> Vec<String> {
    let mut command = assert_warning_build_command(profile);
    command[0] = cargo.into();
    let position = command
        .iter()
        .position(|part| part == "--no-run")
        .expect("固定 CAPI build 命令");
    command.splice(position..position, ["--test".into(), "p17_os_exit".into()]);
    command
}

fn exit_digest(value: &str) -> Result<(), String> {
    if value.len() != 64
        || !value
            .bytes()
            .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f'))
    {
        return Err("P17 Exit SHA-256 格式不符".into());
    }
    Ok(())
}

fn exit_safe_cargo(evidence: &Path) -> Result<&'static str, String> {
    let source = evidence.join("p17-safe-launch-environment-v1.json");
    sha(&source, EXIT_SAFE_ENV_SHA)?;
    let value = StrictJsonParser::parse(
        &fs::read_to_string(&source).map_err(|error| error.to_string())?,
    )?;
    let tools = array(&value, "tools")?;
    let cargo = tools.first().ok_or("P17 Exit safeenv 缺 Cargo")?;
    object(cargo, &["path", "canonical_path", "sha256"])?;
    let path = Path::new(EXIT_SAFE_CARGO);
    if string(&value, "schema")? != "rivetlua-p17-safe-launch-environment-v1"
        || string(cargo, "path")? != EXIT_SAFE_CARGO
        || string(cargo, "canonical_path")? != EXIT_SAFE_CARGO
        || string(cargo, "sha256")? != EXIT_SAFE_CARGO_SHA
        || fs::canonicalize(path).map_err(|error| error.to_string())? != path
        || !fs::symlink_metadata(path)
            .map_err(|error| error.to_string())?
            .file_type()
            .is_file()
        || manifest::sha256(path)? != EXIT_SAFE_CARGO_SHA
    {
        return Err("P17 Exit 實際 Cargo executable 路徑／SHA 不符".into());
    }
    Ok(EXIT_SAFE_CARGO)
}

fn exit_evidence_file(path: &Path, evidence: &Path) -> Result<(), String> {
    let directory = evidence.join("p17-exit-regressions");
    let canonical_directory = fs::canonicalize(&directory).map_err(|e| e.to_string())?;
    let canonical = fs::canonicalize(path).map_err(|e| e.to_string())?;
    if canonical != path
        || !canonical.starts_with(&canonical_directory)
        || canonical.parent() != Some(canonical_directory.as_path())
        || !fs::symlink_metadata(path)
            .map_err(|e| e.to_string())?
            .file_type()
            .is_file()
    {
        return Err("P17 Exit evidence 非固定目錄一般檔案".into());
    }
    Ok(())
}

fn exit_current_sources_with_binary_and_ctrl(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    record: &StrictJsonValue,
    expected: &[&str],
    parser_updated: bool,
    cli_unit_reuse: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    warn_argument_updated: bool,
    ctrl_c_updated: bool,
) -> Result<(), String> {
    exit_current_sources_with_binary_and_ctrl_verified(
        original_root, current_root, evidence, record, expected, parser_updated,
        cli_unit_reuse, cli_binary_updated, cli_version_updated,
        cli_diagnostics_updated, warn_argument_updated, ctrl_c_updated, None)
}

fn exit_current_sources_with_binary_and_ctrl_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    record: &StrictJsonValue,
    expected: &[&str],
    parser_updated: bool,
    cli_unit_reuse: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    warn_argument_updated: bool,
    ctrl_c_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let inputs = array(record, "source_inputs")?;
    if inputs.len() != expected.len() + 3 + usize::from(parser_updated)
        || expected.contains(&HOST_ENTRY_PATHS[0])
        || expected.contains(&HOST_ENTRY_PATHS[2])
        || expected.contains(&HOST_ENTRY_PATHS[3])
        || expected.contains(&EXIT_PARSER_PATH)
    {
        return Err("P17 Exit current source 數量不符".into());
    }
    let parser = parser_updated.then_some(EXIT_PARSER_PATH);
    for (item, relative) in inputs
        .iter()
        .zip(
            expected
                .iter()
                .copied()
                .chain([HOST_ENTRY_PATHS[0], HOST_ENTRY_PATHS[2], HOST_ENTRY_PATHS[3]])
                .chain(parser),
        )
    {
        object(item, &["path", "sha256"])?;
        let historical = original_root.join(relative);
        let current = current_root.join(relative);
        let recorded_sha = string(item, "sha256")?;
        let current_sha = if relative == PRODUCT_STACK_PATH
            && verified.is_some_and(|context| context.product_successor_active) {
            let context = verified.ok_or("P17 Exit stack verified context 缺失")?;
            context.check(current_root, evidence)?;
            if recorded_sha != PRODUCT_STACK_BEFORE_SHA
                || context.source_shas.get(&current).map(String::as_str)
                    != Some(PRODUCT_STACK_CURRENT_SHA) {
                return Err("P17 Exit stack 歷史／current source SHA 不符".into());
            }
            sha(&current, PRODUCT_STACK_CURRENT_SHA)?;
            let snapshot = evidence.join(
                "p17-exit-integrated-source-freeze-20261011-3/crates__rivetlua-capi__src__stack.rs");
            console_cli_public_file(&snapshot, evidence)?;
            sha(&snapshot, PRODUCT_STACK_BEFORE_SHA)?;
            if fs::metadata(&snapshot).map_err(|error| error.to_string())?
                .permissions().mode() & 0o777 != 0o444 {
                return Err("P17 Exit stack 歷史 snapshot 權限不符".into());
            }
            PRODUCT_STACK_BEFORE_SHA.into()
        } else if relative == GC_BASIC_PATH && evidence.join(GC_REVIEW_FILE).exists() {
            manifest::sha256(&gc_before_source_with_verified(
                current_root, evidence, relative, verified)?)?
        } else if ctrl_c_updated && exit_ctrl_c_source_index(relative).is_some() {
            manifest::sha256(&exit_ctrl_c_before_source_with_verified(
                current_root, evidence, relative, verified)?)?
        } else if relative == EXIT_CTRL_CLI_PATH
            && final_repair_cli_current_with_verified(current_root, evidence, verified)? {
            EXIT_CTRL_CLI_AFTER_SHA.into()
        } else if relative == EXIT_PUBLIC_REPL_TEST_PATH
            && final_repair_repl_test_current_with_verified(current_root, evidence, verified)? {
            EXIT_PUBLIC_REPL_SHA.into()
        } else {
            manifest::sha256(&current)?
        };
        let accepted_sha = if warn_argument_updated && relative == EXIT_WARN_VM_PATH {
            if recorded_sha != EXIT_WARN_VM_BEFORE_SHA || current_sha != EXIT_WARN_VM_AFTER_SHA {
                return Err("P17 warn argument VM 舊row source endpoint 不符".into());
            }
            EXIT_WARN_VM_AFTER_SHA
        } else if warn_argument_updated && relative == EXIT_WARN_BASIC_PATH {
            if recorded_sha != EXIT_WARN_BASIC_BEFORE_SHA || current_sha != EXIT_WARN_BASIC_AFTER_SHA {
                return Err("P17 warn argument basic 舊row source endpoint 不符".into());
            }
            EXIT_WARN_BASIC_AFTER_SHA
        } else if relative == EXIT_CLI_BINARY_PATH && cli_binary_updated {
            if recorded_sha != (if cli_unit_reuse { EXIT_CLI_LIB_SHA } else { EXIT_CLI_LIB_TEST_ONLY_SHA })
                || current_sha != (if cli_diagnostics_updated { EXIT_CLI_DIAGNOSTICS_AFTER_SHA }
                    else if cli_version_updated { EXIT_CLI_VERSION_AFTER_SHA }
                    else { EXIT_CLI_BINARY_AFTER_SHA })
            {
                return Err("P17 CLI binary prefix 舊row source endpoint 不符".into());
            }
            if cli_diagnostics_updated { EXIT_CLI_DIAGNOSTICS_AFTER_SHA }
            else if cli_version_updated { EXIT_CLI_VERSION_AFTER_SHA }
            else { EXIT_CLI_BINARY_AFTER_SHA }
        } else if cli_unit_reuse && relative == EXIT_CLI_BINARY_PATH {
            if recorded_sha != EXIT_CLI_LIB_SHA || current_sha != EXIT_CLI_LIB_TEST_ONLY_SHA {
                return Err("P17 CLI unit test-only 舊row source endpoint 不符".into());
            }
            EXIT_CLI_LIB_TEST_ONLY_SHA
        } else if let Some(context) = verified.filter(|context| context.repair_active
            && [HOST_ENTRY_PATHS[1], EXIT_PARSER_PATH].contains(&relative)) {
            let (_, before, after) = FINAL_REPAIR_PRODUCT_CHANGES.iter()
                .find(|(path, _, _)| *path == relative)
                .ok_or_else(|| format!("P17 Exit final repair source 範圍外：{relative}"))?;
            if recorded_sha != *before {
                return Err(format!("P17 Exit final repair 舊 source endpoint 不符：{relative}"));
            }
            context.check(current_root, evidence)?;
            let pinned = context.source_shas.get(&current)
                .ok_or_else(|| format!("P17 Exit final repair current source 缺失：{relative}"))?;
            if pinned.as_str() != product_successor_sha(relative, *after,
                context.product_successor_active) {
                return Err(format!("P17 Exit final repair current source SHA 不符：{relative}"));
            }
            pinned.as_str()
        } else if let Some((_, _, after)) = FINAL_SOURCE_CHANGES.iter().find(|(path, before, _)|
            *path == relative && *before == recorded_sha)
        {
            final_source_relocated_source_with_verified(
                original_root, current_root, evidence,
                &historical.display().to_string(), recorded_sha,
                verified,
            )?;
            let successor = verified.is_some_and(|context| context.check(current_root, evidence).is_ok())
                || final_successor_review_source(current_root, evidence)?.is_some();
            final_current_source_sha_with_verified(
                current_root, evidence, relative, after, successor, verified)?
        } else if let Some((_, _, after, _)) = FINAL_DEBUG_SUCCESSOR_CHANGES.iter().find(
            |(path, before, _, _)| *path == relative && *before == recorded_sha)
        {
            final_source_relocated_source_with_verified(
                original_root, current_root, evidence,
                &historical.display().to_string(), recorded_sha, verified)?;
            after
        } else {
            recorded_sha
        };
        if string(item, "path")? != historical.display().to_string()
            || current
                .components()
                .any(|part| matches!(part, Component::ParentDir))
            || fs::symlink_metadata(&current)
                .map_err(|error| error.to_string())?
                .file_type()
                .is_symlink()
            || current_sha != accepted_sha
        {
            return Err(format!("P17 Exit current source 路徑／SHA 不符：{relative}"));
        }
    }
    Ok(())
}

