fn exit_builds(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    used_logs: &mut BTreeSet<String>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Vec<BTreeMap<String, report::Input>>, String> {
    let builds = array(review, "builds")?;
    if builds.len() != PROFILES.len() {
        return Err("P17 Exit fresh CAPI build profile 數不符".into());
    }
    let environment = runner::environment(current_root)?;
    let cargo = exit_safe_cargo(evidence)?;
    let mut sources = WARNING_FILES[..10]
        .iter()
        .map(|(relative, _)| *relative)
        .collect::<Vec<_>>();
    sources.extend([
        "crates/rivetlua-capi/Cargo.toml",
        "Cargo.lock",
        "crates/rivetlua-capi/tests/p17_internal_replacements.rs",
        "crates/rivetlua-capi/tests/p17_lifecycle.rs",
        "crates/rivetlua-capi/tests/warning_callback.rs",
        EXIT_NEW_TESTS[1],
    ]);
    let targets = [
        "p17_internal_replacements",
        "p17_lifecycle",
        "warning_callback",
        "p17_os_exit",
    ];
    let mut result = Vec::new();
    for (build, profile) in builds.iter().zip(PROFILES) {
        object(
            build,
            &[
                "profile",
                "features",
                "command",
                "cwd",
                "environment",
                "exit_code",
                "log_path",
                "log_sha256",
                "artifacts",
                "source_inputs",
            ],
        )?;
        let log_digest = string(build, "log_sha256")?;
        exit_digest(log_digest)?;
        let log = evidence
            .join("p17-exit-regressions")
            .join(format!("build-{profile}-{log_digest}.jsonl"));
        if string(build, "profile")? != profile
            || string(build, "features")?
                != if profile == PROFILES[0] { "lua55" } else { "lua54" }
            || strings(build, "command")? != exit_build_command(profile, cargo)
            || string(build, "cwd")? != original_root.display().to_string()
            || integer(build, "exit_code")? != 0
            || string(build, "log_path")? != log.display().to_string()
            || !used_logs.insert(log.display().to_string())
        {
            return Err(format!("P17 Exit fresh CAPI build identity 不符：{profile}"));
        }
        error_environment(build, &[])?;
        exit_current_sources_with_binary_and_ctrl_verified(
            original_root,
            current_root,
            evidence,
            build,
            &sources,
            review.get("parser_update").is_some(),
            false,
            review.get("cli_binary_file_prefix_update").is_some(),
            review.get("cli_version_banner_update").is_some(),
            review.get("cli_diagnostics_update").is_some(),
            review.get("warn_argument_update").is_some(),
            review.get("ctrl_c_update").is_some(),
            verified,
        )?;
        exit_evidence_file(&log, evidence)?;
        sha(&log, log_digest)?;
        let found = cargo_named_artifacts(
            &fs::read_to_string(&log).map_err(|e| e.to_string())?,
            &targets,
        )?;
        let artifacts = array(build, "artifacts")?;
        if artifacts.len() != targets.len() {
            return Err("P17 Exit fresh CAPI artifact 數不符".into());
        }
        let mut snapshots = BTreeMap::new();
        for (item, target) in artifacts.iter().zip(targets) {
            object(
                item,
                &[
                    "target",
                    "artifact_path",
                    "artifact_sha256",
                    "executable_path",
                    "executable_sha256",
                    "post_sha256",
                ],
            )?;
            let digest = string(item, "executable_sha256")?;
            exit_digest(digest)?;
            let artifact = Path::new(string(item, "artifact_path")?);
            let snapshot = evidence
                .join("p17-exit-regressions")
                .join(format!("{profile}-{target}-{digest}"));
            if string(item, "target")? != target
                || found.get(target) != Some(&artifact.to_path_buf())
                || !artifact.starts_with(&environment.target_dir)
                || artifact
                    .components()
                    .any(|part| matches!(part, Component::ParentDir))
                || string(item, "artifact_sha256")? != digest
                || string(item, "post_sha256")? != digest
                || string(item, "executable_path")? != snapshot.display().to_string()
            {
                return Err(format!("P17 Exit fresh artifact identity 不符：{profile}/{target}"));
            }
            exit_evidence_file(&snapshot, evidence)?;
            sha(&snapshot, digest)?;
            if fs::metadata(&snapshot)
                .map_err(|e| e.to_string())?
                .permissions()
                .mode()
                & 0o777
                != 0o555
            {
                return Err("P17 Exit fresh CAPI snapshot 非 0555".into());
            }
            report::mach_type(&snapshot, "EXECUTE")?;
            if snapshots
                .insert(target.into(), report::Input::from_path(&snapshot)?)
                .is_some()
            {
                return Err("P17 Exit fresh CAPI snapshot 重複 target".into());
            }
        }
        result.push(snapshots);
    }
    Ok(result)
}

struct ExitRecordSpec<'a> {
    kind: &'a str,
    profile: &'a str,
    features: &'a str,
    command: Vec<String>,
    selectors: Vec<&'a str>,
    sources: Vec<&'a str>,
    build_index: Option<usize>,
    marker_case: Option<&'a str>,
    guest_environment: bool,
    unfiltered: bool,
    owner_executed_binary: Option<(&'a report::Input, &'a str)>,
    parser_updated: bool,
    cli_unit_reuse: bool,
    cli_binary_updated: bool,
    cli_version_updated: bool,
    cli_diagnostics_updated: bool,
    warn_argument_updated: bool,
    ctrl_c_updated: bool,
    verified: Option<&'a FinalVerifiedContext>,
}

fn exit_record(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    record: &StrictJsonValue,
    spec: ExitRecordSpec<'_>,
    used_logs: &mut BTreeSet<String>,
    registry: &Registry,
) -> Result<(), String> {
    let mut keys = vec![
        "kind",
        "profile",
        "features",
        "command",
        "cwd",
        "environment",
        "exit_code",
        "matched",
        "passed",
        "failed",
        "ignored",
        "log_path",
        "log_sha256",
        "source_inputs",
        "selectors",
        "build_index",
        "marker",
    ];
    if spec.owner_executed_binary.is_some() {
        keys.push("executed_binary");
    }
    object(record, &keys)?;
    if spec.selectors.is_empty() {
        return Err("P17 Exit 具名 selector 零匹配".into());
    }
    let digest = string(record, "log_sha256")?;
    exit_digest(digest)?;
    let log = evidence
        .join("p17-exit-regressions")
        .join(format!("{}-{}-{digest}.log", spec.kind, spec.profile));
    let valid_build = match spec.build_index {
        Some(index) => matches!(
            field(record, "build_index")?,
            StrictJsonValue::Number(value) if value.parse::<usize>().ok() == Some(index)
        ),
        None => matches!(field(record, "build_index")?, StrictJsonValue::Null),
    };
    if string(record, "kind")? != spec.kind
        || string(record, "profile")? != spec.profile
        || string(record, "features")? != spec.features
        || strings(record, "command")? != spec.command
        || string(record, "cwd")? != original_root.display().to_string()
        || integer(record, "exit_code")? != 0
        || integer(record, "matched")? != spec.selectors.len() as u64
        || integer(record, "passed")? != spec.selectors.len() as u64
        || integer(record, "failed")? != 0
        || integer(record, "ignored")? != 0
        || strings(record, "selectors")? != spec.selectors
        || string(record, "log_path")? != log.display().to_string()
        || !valid_build
        || !used_logs.insert(log.display().to_string())
    {
        return Err(format!("P17 Exit fresh regression identity 不符：{}", spec.kind));
    }
    error_environment(
        record,
        &if spec.guest_environment {
            runner::effective_no_native_environment()
        } else {
            Vec::new()
        },
    )?;
    if spec.cli_unit_reuse {
        let cli_path = original_root.join("crates/rivetlua-cli/src/lib.rs").display().to_string();
        let cli_source = array(record, "source_inputs")?
            .iter()
            .filter(|item| string(item, "path").ok() == Some(cli_path.as_str()))
            .collect::<Vec<_>>();
        if cli_source.len() != 1 {
            return Err("P17 CLI unit test-only 舊row source 數量不符".into());
        }
        exit_cli_unit_historical_input(original_root, evidence, cli_source[0])?;
    }
    if spec.cli_binary_updated && !spec.cli_unit_reuse {
        let cli_path = original_root.join(EXIT_CLI_BINARY_PATH).display().to_string();
        let cli_source = array(record, "source_inputs")?
            .iter()
            .filter(|item| string(item, "path").ok() == Some(cli_path.as_str()))
            .collect::<Vec<_>>();
        if cli_source.len() > 1 {
            return Err("P17 CLI binary prefix 舊row 重複 source".into());
        }
        if let Some(source) = cli_source.first() {
            let snapshot = evidence.join(EXIT_CLI_UNIT_GREEN_DIR).join("0-lib.rs");
            console_cli_public_file(&snapshot, &evidence.join(EXIT_CLI_UNIT_GREEN_DIR))?;
            exit_cli_lib_historical_input(
                original_root,
                source,
                &snapshot,
                EXIT_CLI_LIB_TEST_ONLY_SHA,
            )?;
        }
    }
    exit_current_sources_with_binary_and_ctrl_verified(
        original_root,
        current_root,
        evidence,
        record,
        &spec.sources,
        spec.parser_updated,
        spec.cli_unit_reuse,
        spec.cli_binary_updated,
        spec.cli_version_updated,
        spec.cli_diagnostics_updated,
        spec.warn_argument_updated,
        spec.ctrl_c_updated,
        spec.verified,
    )?;
    if let Some((expected, _)) = spec.owner_executed_binary {
        let value = field(record, "executed_binary")?;
        let snapshot = exit_owner_binary_shape(value, evidence, spec.profile, expected)?;
        let actual = input(value)?;
        if actual.path != snapshot.display().to_string()
            || actual.sha256 != expected.sha256
            || spec.build_index.is_none()
        {
            return Err("P17 Exit owner Cargo-run binary 指紋不符".into());
        }
        exit_evidence_file(&snapshot, evidence)?;
        sha(&snapshot, &expected.sha256)?;
        if fs::metadata(&snapshot)
            .map_err(|error| error.to_string())?
            .permissions()
            .mode()
            & 0o777
            != 0o555
        {
            return Err("P17 Exit owner Cargo-run binary 非0555".into());
        }
        report::mach_type(&snapshot, "EXECUTE")?;
    }
    exit_evidence_file(&log, evidence)?;
    sha(&log, digest)?;
    let body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
    let native_progress = (spec.kind == "cli-exit-public").then_some((spec.profile, evidence));
    if spec.kind.starts_with("cli-") {
        host_regression_log_with_native_progress(&body, &spec.selectors, native_progress)?;
    } else {
        error_named_log(&body, &spec.selectors)?;
    }
    if spec.unfiltered {
        parse_named_log_with_native_progress(&body, &spec.selectors, false, native_progress)?;
    }
    if let Some((_, running_path)) = spec.owner_executed_binary {
        exit_running_binary(&body, running_path)?;
    }
    if let Some(case) = spec.marker_case {
        let markers = marker_records(&body, &spec.selectors, true)?;
        let marker = markers.get(case).ok_or("P17 Exit marker 缺失")?;
        if canonical_json(field(record, "marker")?) != canonical_json(marker) {
            return Err("P17 Exit marker 與 log 不符".into());
        }
        let case_spec = CASES
            .iter()
            .copied()
            .find(|candidate| candidate.id == case)
            .ok_or("P17 Exit marker case 未宣告")?;
        validate_record(marker, case_spec, spec.profile, registry, true)?;
    } else if !matches!(field(record, "marker")?, StrictJsonValue::Null)
        || body.contains(MARKER)
    {
        return Err("P17 Exit 非 B03 marker 不符".into());
    }
    Ok(())
}

fn exit_retest_existing(
    original_root: &Path,
    root: &Path,
    evidence: &Path,
    fresh: &StrictJsonValue,
    original: &StrictJsonValue,
    builds: &[BTreeMap<String, report::Input>],
    used_logs: &mut BTreeSet<String>,
    warning_extra_selector: &str,
    cargo: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    if warning_extra_selector.is_empty() {
        return Err("P17 Exit Runtime warning 新selector尚未固定".into());
    }
    let actual = array(fresh, "regressions")?;
    let old = array(original, "regressions")?;
    if old.len() != 25 || actual.len() < old.len() {
        return Err("P17 Exit 舊25項 fresh regression 缺失".into());
    }
    let registry = parse_registry(root, &runner::environment(root)?.target)?;
    for (index, (record, prior)) in actual.iter().zip(old).enumerate() {
        let kind = string(prior, "kind")?;
        let profile = string(prior, "profile")?;
        let features = string(prior, "features")?;
        let mut selectors = strings(prior, "selectors")?;
        if index == 0 {
            if selectors.iter().any(|name| name == warning_extra_selector) {
                return Err("P17 Exit Runtime warning 新selector與舊case重複".into());
            }
            selectors.push(warning_extra_selector.into());
        }
        let mut command = strings(prior, "command")?;
        let (build_index, target) = match index {
            5 | 6 => (Some(index - 5), Some("warning_callback")),
            7 | 8 => (Some(index - 7), Some("p17_internal_replacements")),
            9..=12 => (
                Some(if index <= 10 { 0 } else { 1 }),
                Some("p17_lifecycle"),
            ),
            _ => (None, None),
        };
        if let (Some(build_index), Some(target)) = (build_index, target) {
            let binary = builds
                .get(build_index)
                .and_then(|build| build.get(target))
                .ok_or("P17 Exit fresh CAPI binary 缺失")?;
            if command.is_empty() {
                return Err("P17 Exit 舊 CAPI command 空值".into());
            }
            command[0] = binary.path.clone();
        } else if command.first().is_some_and(|part| part == "cargo") {
            command[0] = cargo.into();
        } else {
            return Err("P17 Exit 舊具名命令非固定 Cargo／CAPI binary".into());
        }
        let mut sources = Vec::new();
        for item in array(prior, "source_inputs")? {
            let relative = assert_warning_relative(
                original_root,
                string(item, "path")?,
            )?;
            let text = relative
                .to_str()
                .ok_or("P17 Exit 舊source路徑非UTF-8")?;
            sources.push(text.to_owned());
        }
        let marker_case = match index {
            9 | 11 => Some("p17_stress_gc_long_run"),
            10 | 12 => Some("p17_stress_coroutine_debug"),
            _ => None,
        };
        exit_record(
            original_root,
            root,
            evidence,
            record,
            ExitRecordSpec {
                kind,
                profile,
                features,
                command,
                selectors: selectors.iter().map(String::as_str).collect(),
                sources: sources.iter().map(String::as_str).collect(),
                build_index,
                marker_case,
                guest_environment: build_index.is_some(),
                unfiltered: false,
                owner_executed_binary: None,
                parser_updated: fresh.get("parser_update").is_some(),
                cli_unit_reuse: (13..=24).contains(&index)
                    && fresh.get("cli_unit_test_only_update").is_some(),
                cli_binary_updated: fresh.get("cli_binary_file_prefix_update").is_some(),
                cli_version_updated: fresh.get("cli_version_banner_update").is_some(),
                cli_diagnostics_updated: fresh.get("cli_diagnostics_update").is_some(),
                warn_argument_updated: fresh.get("warn_argument_update").is_some(),
                ctrl_c_updated: fresh.get("ctrl_c_update").is_some(),
                verified,
            },
            used_logs,
            &registry,
        )?;
    }
    Ok(())
}

fn exit_prior_sources(
    original_root: &Path,
    prior: &StrictJsonValue,
    old_tail: &[&str],
    new_tail: &[&str],
) -> Result<Vec<String>, String> {
    let mut sources = Vec::new();
    for item in array(prior, "source_inputs")? {
        object(item, &["path", "sha256"])?;
        let relative = assert_warning_relative(original_root, string(item, "path")?)?;
        sources.push(
            relative
                .to_str()
                .ok_or("P17 Exit 舊source路徑非UTF-8")?
                .to_owned(),
        );
    }
    let expected_tail = old_tail.iter().map(|part| (*part).to_owned()).collect::<Vec<_>>();
    if !sources.ends_with(&expected_tail) {
        return Err("P17 Exit 新回歸的舊source尾段不符".into());
    }
    sources.truncate(sources.len() - old_tail.len());
    sources.extend(new_tail.iter().map(|part| (*part).to_owned()));
    if sources.iter().collect::<BTreeSet<_>>().len() != sources.len() {
        return Err("P17 Exit 新回歸source重複".into());
    }
    Ok(sources)
}

fn exit_cargo_command(cargo: &str, tail: &[&str]) -> Vec<String> {
    std::iter::once(cargo.to_owned())
        .chain(tail.iter().map(|part| (*part).to_owned()))
        .collect()
}

fn exit_owner_binary_shape(
    value: &StrictJsonValue,
    evidence: &Path,
    profile: &str,
    expected: &report::Input,
) -> Result<PathBuf, String> {
    object(value, &["path", "sha256"])?;
    let snapshot = evidence.join("p17-exit-regressions").join(format!(
        "executed-capi-{profile}-p17_os_exit-{}",
        expected.sha256
    ));
    if string(value, "path")? != snapshot.display().to_string()
        || string(value, "sha256")? != expected.sha256
    {
        return Err("P17 Exit owner Cargo-run binary 與fresh build 不符".into());
    }
    Ok(snapshot)
}

fn exit_running_binary(body: &str, expected: &str) -> Result<(), String> {
    let running = body
        .lines()
        .filter_map(|line| {
            line.trim()
                .strip_prefix("Running tests/p17_os_exit.rs (")
                .and_then(|value| value.strip_suffix(')'))
        })
        .collect::<Vec<_>>();
    if running != [expected] {
        return Err("P17 Exit owner Cargo-run Running path 與fresh artifact 不符".into());
    }
    Ok(())
}

fn exit_retest_new(
    original_root: &Path,
    root: &Path,
    evidence: &Path,
    fresh: &StrictJsonValue,
    original: &StrictJsonValue,
    builds: &[BTreeMap<String, report::Input>],
    used_logs: &mut BTreeSet<String>,
    cargo: &str,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    const PUBLIC: &[&str] = &[
        "p17_exit_status_and_arguments",
        "p17_exit_uncatchable_boundaries",
        "p17_exit_close_lifecycle",
        "p17_exit_cli_control_flow",
    ];
    const RUNTIME: &[&str] = &[
        "p17_exit_status_and_noncatchable",
        "p17_exit_close_lifecycle",
    ];
    const CAPI: &[&str] = &["p17_native_shutdown_preserves_recursive_exit_request"];
    let actual = array(fresh, "regressions")?;
    let old = array(original, "regressions")?;
    if old.len() != 25 || actual.len() != 32 || builds.len() != PROFILES.len() {
        return Err("P17 Exit 新7項／舊25項回歸或兩版build缺失".into());
    }
    let registry = parse_registry(root, &runner::environment(root)?.target)?;
    for (offset, record) in actual[25..].iter().enumerate() {
        let (
            kind,
            profile,
            features,
            command,
            selectors,
            prior_index,
            old_tail,
            new_tail,
            build_index,
        ): (
            &str,
            &str,
            &str,
            Vec<String>,
            &[&str],
            usize,
            &[&str],
            &[&str],
            Option<usize>,
        ) = match offset {
            0 | 1 => {
                let profile = PROFILES[offset];
                let features = if offset == 0 {
                    "native-lua55"
                } else {
                    "native-lua54,default-lua54"
                };
                (
                    "cli-local-warning",
                    profile,
                    features,
                    exit_cargo_command(
                        cargo,
                        &[
                            "test",
                            "--locked",
                            "-p",
                            "rivetlua-cli",
                            "--no-default-features",
                            "--features",
                            features,
                            "--lib",
                            "cli_unit_tests::p17_interactive_locals_warning",
                            "--",
                            "--exact",
                            "--nocapture",
                            "--test-threads=1",
                        ],
                    ),
                    &["cli_unit_tests::p17_interactive_locals_warning"],
                    13 + offset,
                    &[],
                    &[],
                    None,
                )
            }
            2 | 3 => {
                let profile = PROFILES[offset - 2];
                let features = if offset == 2 {
                    "native-lua55"
                } else {
                    "native-lua54,default-lua54"
                };
                (
                    "cli-exit-public",
                    profile,
                    features,
                    exit_cargo_command(
                        cargo,
                        &[
                            "test",
                            "--locked",
                            "-p",
                            "rivetlua-cli",
                            "--no-default-features",
                            "--features",
                            features,
                            "--test",
                            "p17_os_exit",
                            "--",
                            "--nocapture",
                            "--test-threads=1",
                        ],
                    ),
                    PUBLIC,
                    23 + offset - 2,
                    &[
                        "crates/rivetlua-cli/tests/p17_warnings.rs",
                        "tests/p17/native-fixtures/warning_probe.c",
                    ],
                    &[EXIT_NEW_TESTS[2], EXIT_NEW_TESTS[3]],
                    None,
                )
            }
            4 => (
                "runtime-exit",
                "both",
                "default",
                exit_cargo_command(
                    cargo,
                    &[
                        "test",
                        "--locked",
                        "-p",
                        "rivetlua-runtime",
                        "--test",
                        "p17_os_exit",
                        "--",
                        "--nocapture",
                        "--test-threads=1",
                    ],
                ),
                RUNTIME,
                0,
                &["crates/rivetlua-runtime/tests/p17_warnings.rs"],
                &[EXIT_NEW_TESTS[0]],
                None,
            ),
            5 | 6 => {
                let index = offset - 5;
                let profile = PROFILES[index];
                let features = if index == 0 { "lua55" } else { "lua54" };
                let command = if index == 0 {
                    exit_cargo_command(
                        cargo,
                        &[
                            "test",
                            "--locked",
                            "-p",
                            "rivetlua-capi",
                            "--features",
                            "lua55",
                            "--test",
                            "p17_os_exit",
                            "--",
                            "--nocapture",
                            "--test-threads=1",
                        ],
                    )
                } else {
                    exit_cargo_command(
                        cargo,
                        &[
                            "test",
                            "--locked",
                            "-p",
                            "rivetlua-capi",
                            "--no-default-features",
                            "--features",
                            "lua54",
                            "--test",
                            "p17_os_exit",
                            "--",
                            "--nocapture",
                            "--test-threads=1",
                        ],
                    )
                };
                (
                    "capi-exit",
                    profile,
                    features,
                    command,
                    CAPI,
                    5 + index,
                    &["crates/rivetlua-capi/tests/warning_callback.rs"],
                    &[EXIT_NEW_TESTS[1]],
                    Some(index),
                )
            }
            _ => return Err("P17 Exit 未宣告的回歸row".into()),
        };
        let sources = exit_prior_sources(original_root, &old[prior_index], old_tail, new_tail)?;
        let artifact = if let Some(index) = build_index {
            let row = array(&array(fresh, "builds")?[index], "artifacts")?
                .get(3)
                .ok_or("P17 Exit p17_os_exit build artifact 缺失")?;
            if string(row, "target")? != "p17_os_exit" {
                return Err("P17 Exit p17_os_exit build artifact target不符".into());
            }
            Some(string(row, "artifact_path")?.to_owned())
        } else {
            None
        };
        let owner_executed_binary = if let Some(index) = build_index {
            Some((
                builds[index]
                    .get("p17_os_exit")
                    .ok_or("P17 Exit p17_os_exit fresh snapshot 缺失")?,
                artifact.as_deref().ok_or("P17 Exit owner Running path 缺失")?,
            ))
        } else {
            None
        };
        exit_record(
            original_root,
            root,
            evidence,
            record,
            ExitRecordSpec {
                kind,
                profile,
                features,
                command,
                selectors: selectors.to_vec(),
                sources: sources.iter().map(String::as_str).collect(),
                build_index,
                marker_case: None,
                guest_environment: false,
                unfiltered: offset >= 2,
                owner_executed_binary,
                parser_updated: fresh.get("parser_update").is_some(),
                cli_unit_reuse: false,
                cli_binary_updated: fresh.get("cli_binary_file_prefix_update").is_some(),
                cli_version_updated: fresh.get("cli_version_banner_update").is_some(),
                cli_diagnostics_updated: fresh.get("cli_diagnostics_update").is_some(),
                warn_argument_updated: fresh.get("warn_argument_update").is_some(),
                ctrl_c_updated: fresh.get("ctrl_c_update").is_some(),
                verified,
            },
            used_logs,
            &registry,
        )?;
    }
    Ok(())
}

fn assert_warning_builds(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    used_logs: &mut BTreeSet<String>,
    exit: Option<&ExitReview>,
    host_sources: Option<&BTreeMap<String, report::HistoricalSource>>,
) -> Result<Vec<BTreeMap<String, report::Input>>, String> {
    let builds = array(review, "builds")?;
    if builds.len() != PROFILES.len() {
        return Err("P17 Assert/Warning CAPI build profile 數不符".into());
    }
    let environment = runner::environment(root)?;
    let sources = [
        WARNING_FILES[0].0,
        WARNING_FILES[1].0,
        WARNING_FILES[2].0,
        WARNING_FILES[3].0,
        WARNING_FILES[4].0,
        WARNING_FILES[5].0,
        WARNING_FILES[6].0,
        WARNING_FILES[7].0,
        WARNING_FILES[8].0,
        WARNING_FILES[9].0,
        "crates/rivetlua-capi/Cargo.toml",
        "Cargo.lock",
        "crates/rivetlua-capi/tests/p17_internal_replacements.rs",
        "crates/rivetlua-capi/tests/p17_lifecycle.rs",
        "crates/rivetlua-capi/tests/warning_callback.rs",
    ];
    let targets = [
        "p17_internal_replacements",
        "p17_lifecycle",
        "warning_callback",
    ];
    let mut result = Vec::new();
    for (build, profile) in builds.iter().zip(PROFILES) {
        object(
            build,
            &[
                "profile",
                "features",
                "command",
                "cwd",
                "environment",
                "exit_code",
                "log_path",
                "log_sha256",
                "artifacts",
                "source_inputs",
            ],
        )?;
        let log = Path::new(string(build, "log_path")?);
        let expected_log = evidence
            .join("p17-assert-warning-regressions")
            .join(format!("build-{profile}.jsonl"));
        if string(build, "profile")? != profile
            || string(build, "features")?
                != if profile == PROFILES[0] {
                    "lua55"
                } else {
                    "lua54"
                }
            || strings(build, "command")? != assert_warning_build_command(profile)
            || string(build, "cwd")? != root.display().to_string()
            || integer(build, "exit_code")? != 0
            || log != expected_log
            || !used_logs.insert(log.display().to_string())
        {
            return Err(format!(
                "P17 Assert/Warning CAPI build identity 不符：{profile}"
            ));
        }
        error_environment(build, &[])?;
        exit_v1_sources(root, build, &sources, exit, host_sources)?;
        assert_warning_evidence_file(log, evidence)?;
        sha(log, string(build, "log_sha256")?)?;
        let found =
            assert_warning_artifacts(&fs::read_to_string(log).map_err(|error| error.to_string())?)?;
        let artifacts = array(build, "artifacts")?;
        if artifacts.len() != targets.len() {
            return Err("P17 Assert/Warning CAPI artifact 數不符".into());
        }
        let mut snapshots = BTreeMap::new();
        for (item, target) in artifacts.iter().zip(targets) {
            object(
                item,
                &[
                    "target",
                    "artifact_path",
                    "artifact_sha256",
                    "executable_path",
                    "executable_sha256",
                    "post_sha256",
                ],
            )?;
            let original = found
                .get(target)
                .ok_or("P17 Assert/Warning Cargo artifact 缺失")?;
            let original_path = Path::new(string(item, "artifact_path")?);
            let snapshot = Path::new(string(item, "executable_path")?);
            if string(item, "target")? != target
                || original_path != original
                || !original_path.starts_with(&environment.target_dir)
                || original_path
                    .components()
                    .any(|part| matches!(part, Component::ParentDir))
                || string(item, "artifact_sha256")? != string(item, "executable_sha256")?
                || string(item, "post_sha256")? != string(item, "executable_sha256")?
                || snapshot
                    != evidence
                        .join("p17-assert-warning-regressions")
                        .join(format!("{profile}-{target}"))
            {
                return Err(format!(
                    "P17 Assert/Warning CAPI artifact identity 不符：{profile}/{target}"
                ));
            }
            assert_warning_evidence_file(snapshot, evidence)?;
            sha(snapshot, string(item, "executable_sha256")?)?;
            if fs::metadata(snapshot)
                .map_err(|error| error.to_string())?
                .permissions()
                .mode()
                & 0o777
                != 0o555
            {
                return Err("P17 Assert/Warning CAPI snapshot 非 0555".into());
            }
            report::mach_type(snapshot, "EXECUTE")?;
            if snapshots
                .insert(target.into(), report::Input::from_path(snapshot)?)
                .is_some()
            {
                return Err("P17 Assert/Warning CAPI snapshot 重複 target".into());
            }
        }
        result.push(snapshots);
    }
    Ok(result)
}

fn assert_warning_regressions(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    builds: &[BTreeMap<String, report::Input>],
    used_logs: &mut BTreeSet<String>,
    exit: Option<&ExitReview>,
    host_sources: Option<&BTreeMap<String, report::HistoricalSource>>,
) -> Result<(), String> {
    let records = array(review, "regressions")?;
    if records.len() != 25 {
        return Err("P17 Assert/Warning regression 數不符".into());
    }
    let mut runtime_sources = WARNING_FILES[..7]
        .iter()
        .map(|(path, _)| *path)
        .collect::<Vec<_>>();
    runtime_sources.extend(["crates/rivetlua-runtime/Cargo.toml", "Cargo.lock"]);
    let mut capi_sources = WARNING_FILES[..10]
        .iter()
        .map(|(path, _)| *path)
        .collect::<Vec<_>>();
    capi_sources.extend(["crates/rivetlua-capi/Cargo.toml", "Cargo.lock"]);
    let mut cli_sources = WARNING_FILES[..11]
        .iter()
        .map(|(path, _)| *path)
        .collect::<Vec<_>>();
    cli_sources.extend([
        HOST_CHANGES[1],
        "crates/rivetlua-cli/Cargo.toml",
        "Cargo.lock",
    ]);
    let registry = parse_registry(root, &runner::environment(root)?.target)?;
    for (index, record) in records.iter().enumerate() {
        object(
            record,
            &[
                "kind",
                "profile",
                "features",
                "command",
                "cwd",
                "environment",
                "exit_code",
                "matched",
                "passed",
                "failed",
                "ignored",
                "log_path",
                "log_sha256",
                "source_inputs",
                "selectors",
                "build_index",
                "marker",
            ],
        )?;
        let (kind, profile, names, mut sources, build_index, target, public) = match index {
            0 => (
                "runtime-warning",
                "both",
                WARNING_RUNTIME_SELECTORS.to_vec(),
                runtime_sources.clone(),
                None,
                None,
                false,
            ),
            1 => (
                "runtime-assert",
                "both",
                WARNING_ASSERT_SELECTORS.to_vec(),
                runtime_sources.clone(),
                None,
                None,
                false,
            ),
            2 => (
                "runtime-error",
                "both",
                vec![
                    "p17_error_position_basic",
                    "p17_error_position_dispatch_lifecycle",
                ],
                runtime_sources.clone(),
                None,
                None,
                false,
            ),
            3 => (
                "runtime-console",
                "both",
                CONSOLE_RUNTIME_SELECTORS.to_vec(),
                runtime_sources.clone(),
                None,
                None,
                false,
            ),
            4 => (
                "runtime-export",
                "both",
                vec!["p17_export_open_call_runtime_semantics"],
                runtime_sources.clone(),
                None,
                None,
                false,
            ),
            5 | 6 => (
                "capi-warning",
                PROFILES[index - 5],
                WARNING_CAPI_SELECTORS.to_vec(),
                capi_sources.clone(),
                Some(index - 5),
                Some("warning_callback"),
                false,
            ),
            7 | 8 => (
                "capi-cstack",
                PROFILES[index - 7],
                vec!["p17_internal_c_stack_errors"],
                capi_sources.clone(),
                Some(index - 7),
                Some("p17_internal_replacements"),
                false,
            ),
            9..=12 => {
                let profile_index = if index <= 10 { 0 } else { 1 };
                let gc = index == 9 || index == 11;
                (
                    if gc { "capi-gc" } else { "capi-coroutine" },
                    PROFILES[profile_index],
                    vec![if gc {
                        "p17_stress_gc_long_run"
                    } else {
                        "p17_stress_coroutine_debug"
                    }],
                    capi_sources.clone(),
                    Some(profile_index),
                    Some("p17_lifecycle"),
                    false,
                )
            }
            13 | 14 => (
                "cli-args",
                PROFILES[index - 13],
                CONSOLE_ARGS_SELECTORS.to_vec(),
                cli_sources.clone(),
                None,
                None,
                false,
            ),
            15 | 16 => (
                "cli-repl",
                PROFILES[index - 15],
                CONSOLE_REPL_SELECTORS.to_vec(),
                cli_sources.clone(),
                None,
                None,
                false,
            ),
            17 | 18 => (
                "cli-optin",
                PROFILES[index - 17],
                CONSOLE_OPTIN_SELECTORS.to_vec(),
                cli_sources.clone(),
                None,
                None,
                false,
            ),
            19 | 20 => (
                "cli-host-unit",
                PROFILES[index - 19],
                HOST_UNIT_SELECTORS.to_vec(),
                cli_sources.clone(),
                None,
                None,
                false,
            ),
            21 | 22 => (
                "cli-host-public",
                PROFILES[index - 21],
                HOST_PUBLIC_SELECTORS.to_vec(),
                cli_sources.clone(),
                None,
                None,
                true,
            ),
            _ => (
                "cli-warning-public",
                PROFILES[index - 23],
                WARNING_CLI_SELECTORS.to_vec(),
                cli_sources.clone(),
                None,
                None,
                true,
            ),
        };
        match index {
            0 => sources.push(WARNING_NEW_TESTS[0]),
            1 => sources.push(ASSERT_NEW_TEST),
            2 => sources.push(ERROR_NEW_TEST),
            3 => sources.push(CONSOLE_NEW_TEST),
            4 => sources.push("crates/rivetlua-runtime/tests/official_chunk_runtime.rs"),
            5 | 6 => sources.push("crates/rivetlua-capi/tests/warning_callback.rs"),
            7 | 8 => sources.push("crates/rivetlua-capi/tests/p17_internal_replacements.rs"),
            9..=12 => sources.push("crates/rivetlua-capi/tests/p17_lifecycle.rs"),
            21 | 22 => sources.push(HOST_CHANGES[2]),
            23 | 24 => sources.extend([WARNING_NEW_TESTS[1], WARNING_NEW_TESTS[2]]),
            _ => {}
        }
        let command = if let Some(build_index) = build_index {
            let binary = builds
                .get(build_index)
                .and_then(|build| build.get(target.expect("fixed target")))
                .ok_or("P17 Assert/Warning fresh CAPI binary 缺失")?;
            let filter = if index == 5 || index == 6 {
                "warning_"
            } else {
                names[0]
            };
            let mut command = vec![binary.path.clone(), filter.into()];
            if index != 5 && index != 6 {
                command.push("--exact".into());
            }
            command.extend(["--nocapture".into(), "--test-threads=1".into()]);
            command
        } else if index <= 4 {
            let (test_target, filter) = match index {
                0 => ("p17_warnings", "p17_warning_"),
                1 => ("p17_assert_position", "p17_assert_position_"),
                2 => ("p17_error_position", "p17_error_position_"),
                3 => ("p17_debug_console", "p17_debug_console_"),
                _ => (
                    "official_chunk_runtime",
                    "p17_export_open_call_runtime_semantics",
                ),
            };
            let mut command = [
                "cargo",
                "test",
                "--locked",
                "-p",
                "rivetlua-runtime",
                "--test",
                test_target,
            ]
            .iter()
            .map(|part| (*part).to_owned())
            .collect::<Vec<_>>();
            if index != 0 {
                command.push(filter.into());
            }
            command.push("--".into());
            if index == 4 {
                command.push("--exact".into());
            }
            command.extend(["--nocapture".into(), "--test-threads=1".into()]);
            command
        } else {
            let features = if index >= 23 && profile == PROFILES[1] {
                "native-lua54,default-lua54"
            } else if profile == PROFILES[0] {
                "native-lua55"
            } else {
                "default-lua54,native-lua54"
            };
            let mut command = ["cargo", "test", "--locked", "-p", "rivetlua-cli"]
                .iter()
                .map(|part| (*part).to_owned())
                .collect::<Vec<_>>();
            if index >= 23 {
                command.push("--no-default-features".into());
            }
            command.extend(["--features".into(), features.into()]);
            if public {
                command.extend([
                    "--test".into(),
                    if index >= 23 {
                        "p17_warnings".into()
                    } else {
                        "p17_host_services".into()
                    },
                ]);
            } else {
                command.push("--lib".into());
            }
            let filter = match index {
                13 | 14 => "p17_script_args_",
                15 | 16 => "p17_repl_",
                17 | 18 => "p17_debug_console_trusted_optin",
                19..=22 => "p17_host_",
                _ => "p17_warning_cli_",
            };
            if index < 23 {
                command.push(filter.into());
            }
            command.extend(["--".into(), "--nocapture".into()]);
            if index < 23 {
                command.push("--test-threads=1".into());
            }
            command
        };
        let expected_features = if index <= 4 {
            "default"
        } else if index <= 12 {
            if profile == PROFILES[0] {
                "lua55"
            } else {
                "lua54"
            }
        } else if index >= 23 && profile == PROFILES[1] {
            "native-lua54,default-lua54"
        } else if profile == PROFILES[0] {
            "native-lua55"
        } else {
            "default-lua54,native-lua54"
        };
        let log_digest = string(record, "log_sha256")?;
        if index >= 23
            && (log_digest.len() != 64
                || !log_digest
                    .bytes()
                    .all(|byte| matches!(byte, b'0'..=b'9' | b'a'..=b'f')))
        {
            return Err("P17 Warning public log SHA-256 格式不符".into());
        }
        let log = evidence
            .join("p17-assert-warning-regressions")
            .join(if index >= 23 {
                format!(
                    "p17-warnings-lua{}-final-{log_digest}.log",
                    if profile == PROFILES[0] { "55" } else { "54" },
                )
            } else {
                format!("{kind}-{profile}.log")
            });
        let observed_build = field(record, "build_index")?;
        let valid_build = match build_index {
            Some(expected) => {
                matches!(observed_build, StrictJsonValue::Number(value) if value.parse::<usize>().ok() == Some(expected))
            }
            None => matches!(observed_build, StrictJsonValue::Null),
        };
        if string(record, "kind")? != kind
            || string(record, "profile")? != profile
            || string(record, "features")? != expected_features
            || strings(record, "command")? != command
            || string(record, "cwd")? != root.display().to_string()
            || integer(record, "exit_code")? != 0
            || integer(record, "matched")? != names.len() as u64
            || integer(record, "passed")? != names.len() as u64
            || integer(record, "failed")? != 0
            || integer(record, "ignored")? != 0
            || strings(record, "selectors")? != names
            || string(record, "log_path")? != log.display().to_string()
            || !valid_build
            || !used_logs.insert(log.display().to_string())
        {
            return Err(format!(
                "P17 Assert/Warning regression command/count 不符：{kind}/{profile}"
            ));
        }
        let expected_env = if build_index.is_some() {
            runner::effective_no_native_environment()
        } else {
            Vec::new()
        };
        error_environment(record, &expected_env)?;
        exit_v1_sources(root, record, &sources, exit, host_sources)?;
        assert_warning_evidence_file(&log, evidence)?;
        sha(&log, log_digest)?;
        let body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
        if index >= 13 {
            host_regression_log(&body, &names)?;
        } else {
            error_named_log(&body, &names)?;
        }
        if (9..=12).contains(&index) {
            let markers = marker_records(&body, &names, true)?;
            let marker = markers
                .get(names[0])
                .ok_or("P17 Assert/Warning B03 marker 缺失")?;
            if canonical_json(field(record, "marker")?) != canonical_json(marker) {
                return Err("P17 Assert/Warning B03 marker/log 不符".into());
            }
            let spec = CASES
                .iter()
                .copied()
                .find(|spec| spec.id == names[0])
                .ok_or("P17 Assert/Warning B03 case 未宣告")?;
            validate_record(marker, spec, profile, &registry, true)?;
        } else if !matches!(field(record, "marker")?, StrictJsonValue::Null)
            || body.contains(MARKER)
        {
            return Err("P17 Assert/Warning 非 B03 marker 不符".into());
        }
    }
    Ok(())
}

fn validate_assert_warning_proofs(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    exit: Option<&ExitReview>,
    host_sources: Option<&BTreeMap<String, report::HistoricalSource>>,
) -> Result<(), String> {
    let mut used_logs = BTreeSet::new();
    let builds = assert_warning_builds(root, evidence, review, &mut used_logs, exit, host_sources)?;
    assert_warning_regressions(root, evidence, review, &builds, &mut used_logs, exit, host_sources)
}

fn phase_baseline(root: &Path, evidence: &Path) -> Result<PathBuf, String> {
    let baseline = evidence.join("p17-phase-repair-baseline");
    let manifest_path = baseline.join("manifest.json");
    sha(&manifest_path, PHASE_BASELINE_SHA)?;
    let manifest = StrictJsonParser::parse(
        &fs::read_to_string(&manifest_path).map_err(|error| error.to_string())?,
    )?;
    object(&manifest, &["schema", "files"])?;
    if string(&manifest, "schema")? != "rivetlua-p17-phase-repair-baseline-v1" {
        return Err("P17 phase baseline schema 不符".into());
    }
    let files = array(&manifest, "files")?;
    if files.len() != PHASE_SOURCES.len() {
        return Err("P17 phase baseline file 數不符".into());
    }
    for (item, (relative, expected)) in files.iter().zip(PHASE_SOURCES) {
        object(item, &["path", "snapshot_path", "sha256"])?;
        let snapshot = baseline.join(relative.replace('/', "__"));
        if string(item, "path")? != relative
            || string(item, "snapshot_path")? != snapshot.display().to_string()
            || string(item, "sha256")? != expected
        {
            return Err(format!("P17 phase baseline 路徑／SHA 不符：{relative}"));
        }
        sha(&snapshot, expected)?;
    }
    sha(&root.join("xtask/src/p17/mod.rs"), PHASE_SOURCES[2].1)?;
    for (batch, expected) in [
        ("P17-B01", B01_SHA),
        ("P17-B02", B02_SHA),
        ("P17-B03", B03_SHA),
    ] {
        let name = format!("gate-{batch}.json");
        let current = root.join("target/rivetlua-reports").join(&name);
        sha(&current, expected)?;
        if fs::read(&current).map_err(|error| error.to_string())?
            != fs::read(baseline.join(&name)).map_err(|error| error.to_string())?
            || fs::read(current.with_extension("sha256")).map_err(|error| error.to_string())?
                != fs::read(baseline.join(format!("gate-{batch}.sha256")))
                    .map_err(|error| error.to_string())?
        {
            return Err(format!("P17 phase {batch} report/receipt 原始 bytes 不符"));
        }
    }
    Ok(baseline)
}

fn host_baseline(
    root: &Path,
    evidence: &Path,
    ctrl_c_updated: bool,
) -> Result<(PathBuf, report::Input), String> {
    host_baseline_with_verified(root, root, evidence, ctrl_c_updated, None)
}

fn host_baseline_with_verified(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    ctrl_c_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(PathBuf, report::Input), String> {
    let baseline = evidence.join("p17-phase-host-repair-baseline");
    let path = baseline.join("manifest.json");
    sha(&path, HOST_BASELINE_SHA)?;
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    object(
        &value,
        &[
            "schema",
            "accepted_export_review_sha256",
            "accepted_export_reuse_log_sha256",
            "files",
            "new_files",
        ],
    )?;
    if string(&value, "schema")? != "rivetlua-p17-phase-host-repair-baseline-v1"
        || string(&value, "accepted_export_review_sha256")? != ACCEPTED_EXPORT_REVIEW_SHA
        || string(&value, "accepted_export_reuse_log_sha256")? != ACCEPTED_EXPORT_REUSE_SHA
        || strings(&value, "new_files")? != HOST_CHANGES[1..]
    {
        return Err("P17 phase host baseline 主鍵／新增檔不符".into());
    }
    let files = array(&value, "files")?;
    if files.len() != HOST_BASELINE_FILES.len() {
        return Err("P17 phase host baseline file 數不符".into());
    }
    for (index, (item, (relative, expected))) in files.iter().zip(HOST_BASELINE_FILES).enumerate() {
        object(item, &["path", "snapshot_path", "sha256"])?;
        let snapshot = baseline.join(relative.replace('/', "__"));
        if string(item, "path")? != relative
            || string(item, "snapshot_path")? != snapshot.display().to_string()
            || string(item, "sha256")? != expected
        {
            return Err(format!("P17 phase host baseline identity 不符：{relative}"));
        }
        sha(&snapshot, expected)?;
        if (1..=4).contains(&index) {
            let current = if ctrl_c_updated && exit_ctrl_c_source_index(relative).is_some() {
                exit_ctrl_c_before_source_with_verified(
                    current_root, evidence, relative, verified)?
            } else {
                current_root.join(relative)
            };
            sha(&current, expected)?;
        }
    }
    for relative in &HOST_CHANGES[1..] {
        if baseline.join(relative.replace('/', "__")).exists() {
            return Err(format!(
                "P17 phase host baseline 新檔舊快照不應存在：{relative}"
            ));
        }
    }
    Ok((baseline, report::Input::from_path(&path)?))
}

fn host_review_header(value: &StrictJsonValue) -> Result<(), String> {
    object(
        value,
        &[
            "schema",
            "baseline_manifest_sha256",
            "accepted_export_review_sha256",
            "accepted_export_reuse_log_sha256",
            "b01_report_sha256",
            "b02_report_sha256",
            "b03_report_sha256",
            "changes",
            "regressions",
            "review_note",
        ],
    )?;
    if string(value, "schema")? != "rivetlua-p17-phase-host-impact-v1"
        || string(value, "baseline_manifest_sha256")? != HOST_BASELINE_SHA
        || string(value, "accepted_export_review_sha256")? != ACCEPTED_EXPORT_REVIEW_SHA
        || string(value, "accepted_export_reuse_log_sha256")? != ACCEPTED_EXPORT_REUSE_SHA
        || string(value, "b01_report_sha256")? != B01_SHA
        || string(value, "b02_report_sha256")? != B02_SHA
        || string(value, "b03_report_sha256")? != B03_SHA
        || string(value, "review_note")?.trim().len() < 8
    {
        return Err("P17 phase host review 主鍵不符".into());
    }
    Ok(())
}

fn host_review(
    root: &Path,
    evidence: &Path,
    view: &mut report::PhaseSourceView,
    console: Option<&ConsoleReview>,
    ctrl_c_updated: bool,
) -> Result<Option<HostReview>, String> {
    host_review_with_verified(root, root, evidence, view, console, ctrl_c_updated, None)
}

fn host_review_with_verified(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    view: &mut report::PhaseSourceView,
    console: Option<&ConsoleReview>,
    ctrl_c_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<HostReview>, String> {
    let path = evidence.join("p17-phase-host-source-impact-review.json");
    if !path.exists() {
        return Ok(None);
    }
    let (baseline, baseline_input) = host_baseline_with_verified(
        root, current_root, evidence, ctrl_c_updated, verified)?;
    let accepted_review_path =
        evidence.join("p17-export-repair-accepted-p17-phase-source-impact-review.json");
    let accepted_reuse_path =
        evidence.join("p17-export-repair-accepted-p17-phase-reuse-regression.log");
    sha(&accepted_review_path, ACCEPTED_EXPORT_REVIEW_SHA)?;
    sha(&accepted_reuse_path, ACCEPTED_EXPORT_REUSE_SHA)?;
    let accepted_body =
        fs::read_to_string(&accepted_reuse_path).map_err(|error| error.to_string())?;
    let (counts, named) =
        parse_named_log_with_filter(&accepted_body, &["p17::b03::tests::p17_phase_reuse"], true)?;
    if counts.matched != 1
        || counts.passed != 1
        || counts.failed != 0
        || counts.ignored != 0
        || named.values().any(|outcome| *outcome != "ok")
    {
        return Err("P17 phase accepted exporter reuse 非具名真 PASS".into());
    }
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    host_review_header(&value)?;
    let changes = array(&value, "changes")?;
    if changes.len() != HOST_CHANGES.len() {
        return Err("P17 phase host changes 數不符".into());
    }
    let mut historical_lib = None;
    let mut current_sources = Vec::with_capacity(HOST_CHANGES.len());
    for (index, (change, relative)) in changes.iter().zip(HOST_CHANGES).enumerate() {
        object(
            change,
            &[
                "path",
                "before_sha256",
                "after_sha256",
                "diff_path",
                "diff_sha256",
            ],
        )?;
        let current = root.join(relative);
        let effective = console.map_or_else(
            || current.clone(),
            |console| console.endpoint(root, relative),
        );
        let before = if index == 0 {
            baseline.join(relative.replace('/', "__"))
        } else {
            PathBuf::from("/dev/null")
        };
        let diff = evidence.join(format!(
            "p17-phase-host-impact-{}.diff",
            relative.replace('/', "__")
        ));
        if string(change, "path")? != relative
            || string(change, "after_sha256")? != manifest::sha256(&effective)?
            || string(change, "diff_path")? != diff.display().to_string()
            || (index == 0 && string(change, "before_sha256")? != HOST_BASELINE_FILES[0].1)
            || (index != 0 && !matches!(field(change, "before_sha256")?, StrictJsonValue::Null))
        {
            return Err(format!("P17 phase host change identity 不符：{relative}"));
        }
        sha(&diff, string(change, "diff_sha256")?)?;
        let output = verified_review_git(root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(&before)
            .arg(&effective)
            .output()
            .map_err(|error| error.to_string())?;
        if output.status.code() != Some(1)
            || !console_old_diff_matches(
                &output.stdout,
                &fs::read(&diff).map_err(|error| error.to_string())?,
                &before,
                &current,
                &effective,
            )?
        {
            return Err(format!("P17 phase host raw diff 不符：{relative}"));
        }
        if index == 0 {
            historical_lib = Some((current.display().to_string(), before));
        }
        current_sources.push(report::Input {
            path: current.display().to_string(),
            sha256: string(change, "after_sha256")?.into(),
        });
    }
    validate_host_regressions(root, evidence, &value, console)?;
    let current_sources: [report::Input; 3] = current_sources
        .try_into()
        .map_err(|_| "P17 phase host current source 數不符")?;
    let (lib_path, lib_snapshot) = historical_lib.ok_or("P17 phase host lib 舊來源缺失")?;
    view.insert(
        lib_path,
        report::HistoricalSource {
            before_sha256: HOST_BASELINE_FILES[0].1.into(),
            snapshot: lib_snapshot,
        },
    );
    for relative in &HOST_CHANGES[1..] {
        view.mark_old_absent(root.join(relative).display().to_string());
    }
    Ok(Some(HostReview {
        input: report::Input::from_path(&path)?,
        baseline: baseline_input,
        accepted_review: report::Input::from_path(&accepted_review_path)?,
        accepted_reuse: report::Input::from_path(&accepted_reuse_path)?,
        current_sources,
    }))
}

fn host_regression_log(body: &str, names: &[&str]) -> Result<(), String> {
    host_regression_log_with_native_progress(body, names, None)
}

fn host_regression_log_with_native_progress(
    body: &str,
    names: &[&str],
    native_progress: Option<(&str, &Path)>,
) -> Result<(), String> {
    if names.is_empty() {
        return Err("P17 phase host 具名 selector 尚未凍結".into());
    }
    let (counts, outcomes) =
        parse_named_log_with_native_progress(body, names, true, native_progress)?;
    if counts.matched != names.len() as u32
        || counts.passed != names.len() as u32
        || counts.failed != 0
        || counts.ignored != 0
        || outcomes.values().any(|status| *status != "ok")
    {
        return Err("P17 phase host 具名回歸非全數真 PASS".into());
    }
    Ok(())
}

fn host_source_schema(root: &Path, record: &StrictJsonValue, public: bool) -> Result<(), String> {
    let mut expected = vec![
        HOST_BASELINE_FILES[0].0,
        HOST_BASELINE_FILES[1].0,
        HOST_BASELINE_FILES[2].0,
        HOST_BASELINE_FILES[3].0,
        HOST_BASELINE_FILES[4].0,
        HOST_CHANGES[1],
    ];
    if public {
        expected.push(HOST_CHANGES[2]);
    }
    let sources = array(record, "source_inputs")?;
    if sources.len() != expected.len() {
        return Err("P17 phase host 回歸 source 數不符".into());
    }
    for (source, relative) in sources.iter().zip(expected) {
        object(source, &["path", "sha256"])?;
        let digest = string(source, "sha256")?;
        if string(source, "path")? != root.join(relative).display().to_string()
            || digest.len() != 64
            || !digest
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        {
            return Err(format!(
                "P17 phase host 回歸 source identity 不符：{relative}"
            ));
        }
    }
    Ok(())
}

fn validate_host_regressions(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    console: Option<&ConsoleReview>,
) -> Result<(), String> {
    let regressions = array(review, "regressions")?;
    if regressions.len() != 4 {
        return Err("P17 phase host 回歸數不符".into());
    }
    for (index, record) in regressions.iter().enumerate() {
        object(
            record,
            &[
                "kind",
                "profile",
                "command",
                "cwd",
                "exit_code",
                "matched",
                "passed",
                "failed",
                "ignored",
                "log_path",
                "log_sha256",
                "source_inputs",
                "selectors",
            ],
        )?;
        let (kind, profile, feature, log_name, public) = match index {
            0 => (
                "host-unit",
                PROFILES[0],
                "native-lua55",
                "p17-phase-host-unit-lua55.log",
                false,
            ),
            1 => (
                "host-unit",
                PROFILES[1],
                "default-lua54,native-lua54",
                "p17-phase-host-unit-lua54.log",
                false,
            ),
            2 => (
                "host-public",
                PROFILES[0],
                "native-lua55",
                "p17-phase-host-public-lua55.log",
                true,
            ),
            _ => (
                "host-public",
                PROFILES[1],
                "default-lua54,native-lua54",
                "p17-phase-host-public-lua54.log",
                true,
            ),
        };
        let names = HOST_SELECTORS[index];
        if names.is_empty() {
            return Err("P17 phase host 具名 selector 尚未凍結".into());
        }
        let mut command = vec![
            "cargo",
            "test",
            "--locked",
            "-p",
            "rivetlua-cli",
            "--features",
            feature,
        ];
        if public {
            command.extend(["--test", "p17_host_services"]);
        } else {
            command.push("--lib");
        }
        command.extend(["p17_host_", "--", "--nocapture", "--test-threads=1"]);
        let log = evidence.join(log_name);
        if string(record, "kind")? != kind
            || string(record, "profile")? != profile
            || strings(record, "command")? != command
            || string(record, "cwd")? != root.display().to_string()
            || integer(record, "exit_code")? != 0
            || integer(record, "matched")? != names.len() as u64
            || integer(record, "passed")? != names.len() as u64
            || integer(record, "failed")? != 0
            || integer(record, "ignored")? != 0
            || strings(record, "selectors")? != names
            || string(record, "log_path")? != log.display().to_string()
        {
            return Err(format!(
                "P17 phase host 回歸 command/count 不符：{kind}/{profile}"
            ));
        }
        host_source_schema(root, record, public)?;
        for source in array(record, "source_inputs")? {
            if let Some(console) = console {
                console.historical_input(source)?;
            } else {
                input(source)?;
            }
        }
        sha(&log, string(record, "log_sha256")?)?;
        host_regression_log(
            &fs::read_to_string(&log).map_err(|error| error.to_string())?,
            names,
        )?;
    }
    Ok(())
}

fn error_review_header(value: &StrictJsonValue) -> Result<(), String> {
    object(
        value,
        &[
            "schema",
            "baseline_manifest_sha256",
            "accepted_export_review_sha256",
            "accepted_host_review_sha256",
            "b01_report_sha256",
            "b02_report_sha256",
            "b03_report_sha256",
            "changes",
            "builds",
            "regressions",
            "review_note",
        ],
    )?;
    if string(value, "schema")? != "rivetlua-p17-error-position-impact-v1"
        || string(value, "baseline_manifest_sha256")? != ERROR_BASELINE_SHA
        || string(value, "accepted_export_review_sha256")? != ACCEPTED_ERROR_EXPORT_SHA
        || string(value, "accepted_host_review_sha256")? != ACCEPTED_ERROR_HOST_SHA
        || string(value, "b01_report_sha256")? != B01_SHA
        || string(value, "b02_report_sha256")? != B02_SHA
        || string(value, "b03_report_sha256")? != B03_SHA
        || string(value, "review_note")?.trim().len() < 8
    {
        return Err("P17 phase error-position review 主鍵不符".into());
    }
    Ok(())
}

fn error_change_schema(value: &StrictJsonValue) -> Result<(), String> {
    let changes = array(value, "changes")?;
    if changes.len() != ERROR_CHANGES.len() {
        return Err("P17 phase error-position changes 數不符".into());
    }
    for (index, (item, relative)) in changes.iter().zip(ERROR_CHANGES).enumerate() {
        object(
            item,
            &[
                "path",
                "before_sha256",
                "after_sha256",
                "diff_path",
                "diff_sha256",
            ],
        )?;
        let after = string(item, "after_sha256")?;
        let diff = string(item, "diff_sha256")?;
        if string(item, "path")? != relative
            || (index == 0 && string(item, "before_sha256")? != ERROR_FILES[0].1)
            || (index == 1 && !matches!(field(item, "before_sha256")?, StrictJsonValue::Null))
            || [after, diff].iter().any(|hash| {
                hash.len() != 64
                    || !hash
                        .bytes()
                        .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
            })
        {
            return Err(format!(
                "P17 phase error-position change schema 不符：{relative}"
            ));
        }
    }
    Ok(())
}

fn error_host_sources<'a>(
    root: &Path,
    evidence: &Path,
    host: Option<&'a HostReview>,
) -> Result<&'a [report::Input; 3], String> {
    let host = host.ok_or("P17 phase error-position review 缺已驗 host 鏈")?;
    if host.input.path
        != evidence
            .join("p17-phase-host-source-impact-review.json")
            .display()
            .to_string()
    {
        return Err("P17 phase error-position host review 路徑不符".into());
    }
    for (source, relative) in host.current_sources.iter().zip(HOST_CHANGES) {
        if source.path != root.join(relative).display().to_string()
            || source.sha256.len() != 64
            || !source
                .sha256
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        {
            return Err(format!(
                "P17 phase error-position host source 不符：{relative}"
            ));
        }
    }
    Ok(&host.current_sources)
}

fn error_baseline(
    root: &Path,
    evidence: &Path,
    host: &HostReview,
    console: Option<&ConsoleReview>,
) -> Result<(PathBuf, report::Input), String> {
    let host_sources = error_host_sources(root, evidence, Some(host))?;
    sha(Path::new(&host.input.path), &host.input.sha256)?;
    for source in host_sources {
        if let Some(console) = console {
            console.historical_input(&StrictJsonParser::parse(&source.json())?)?;
        } else {
            sha(Path::new(&source.path), &source.sha256)?;
        }
    }
    let baseline = evidence.join("p17-phase-error-position-baseline");
    let path = baseline.join("manifest.json");
    sha(&path, ERROR_BASELINE_SHA)?;
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    object(
        &value,
        &[
            "schema",
            "accepted_export_review_sha256",
            "accepted_host_review_sha256",
            "files",
            "new_files",
            "reports",
        ],
    )?;
    if string(&value, "schema")? != "rivetlua-p17-error-position-baseline-v1"
        || string(&value, "accepted_export_review_sha256")? != ACCEPTED_ERROR_EXPORT_SHA
        || string(&value, "accepted_host_review_sha256")? != ACCEPTED_ERROR_HOST_SHA
        || strings(&value, "new_files")? != [ERROR_NEW_TEST]
    {
        return Err("P17 phase error-position baseline 主鍵不符".into());
    }
    let files = array(&value, "files")?;
    if files.len() != ERROR_FILES.len() {
        return Err("P17 phase error-position baseline files 數不符".into());
    }
    for (index, (item, (relative, expected))) in files.iter().zip(ERROR_FILES).enumerate() {
        object(item, &["path", "sha256", "snapshot"])?;
        let snapshot = baseline.join(relative.replace('/', "__"));
        if string(item, "path")? != relative
            || string(item, "sha256")? != expected
            || string(item, "snapshot")? != snapshot.display().to_string()
        {
            return Err(format!(
                "P17 phase error-position baseline identity 不符：{relative}"
            ));
        }
        sha(&snapshot, expected)?;
        if index == 1 {
            sha(
                &console.map_or_else(
                    || root.join(relative),
                    |console| console.endpoint(root, relative),
                ),
                expected,
            )?;
        } else if (3..=5).contains(&index) {
            sha(
                &console.map_or_else(
                    || root.join(relative),
                    |console| console.endpoint(root, relative),
                ),
                &host_sources[index - 3].sha256,
            )?;
        }
    }
    if baseline.join(ERROR_NEW_TEST.replace('/', "__")).exists() {
        return Err("P17 phase error-position 新測試舊快照不應存在".into());
    }
    sha(
        &baseline.join("p17-phase-source-impact-review.json"),
        ACCEPTED_ERROR_EXPORT_SHA,
    )?;
    sha(
        &baseline.join("p17-phase-host-source-impact-review.json"),
        ACCEPTED_ERROR_HOST_SHA,
    )?;
    let reports = array(&value, "reports")?;
    if reports.len() != 3 {
        return Err("P17 phase error-position baseline reports 數不符".into());
    }
    for (item, (batch, expected)) in
        reports
            .iter()
            .zip([("B01", B01_SHA), ("B02", B02_SHA), ("B03", B03_SHA)])
    {
        object(item, &["batch", "path", "sha256", "snapshot"])?;
        let report_path = root.join(format!("target/rivetlua-reports/gate-P17-{batch}.json"));
        let snapshot = baseline.join(format!("gate-P17-{batch}.json"));
        if string(item, "batch")? != batch
            || string(item, "path")? != report_path.display().to_string()
            || string(item, "sha256")? != expected
            || string(item, "snapshot")? != snapshot.display().to_string()
        {
            return Err(format!(
                "P17 phase error-position report identity 不符：{batch}"
            ));
        }
        sha(&snapshot, expected)?;
        sha(&report_path, expected)?;
        receipt(&report_path)?;
        if fs::read(&snapshot).map_err(|error| error.to_string())?
            != fs::read(&report_path).map_err(|error| error.to_string())?
        {
            return Err(format!(
                "P17 phase error-position 原 report bytes 不符：{batch}"
            ));
        }
        let report_value = StrictJsonParser::parse(
            &fs::read_to_string(&snapshot).map_err(|error| error.to_string())?,
        )?;
        let mut old_vm = 0;
        for source in array(&report_value, "source_inputs")? {
            let relative = string(source, "path")?;
            if relative == root.join(ERROR_NEW_TEST).display().to_string() {
                return Err("P17 phase error-position 舊報告不可聲稱新測試存在".into());
            }
            if relative == root.join(ERROR_FILES[0].0).display().to_string() {
                if string(source, "sha256")? != ERROR_FILES[0].1 {
                    return Err("P17 phase error-position 舊 VM SHA 不符".into());
                }
                old_vm += 1;
            }
        }
        if old_vm != 1 {
            return Err(format!(
                "P17 phase error-position {batch} 舊 VM input 缺失／重複"
            ));
        }
    }
    Ok((baseline, report::Input::from_path(&path)?))
}

fn b02_archive_schema(
    value: &StrictJsonValue,
    target_dir: &Path,
    archive_dir: &Path,
) -> Result<(), String> {
    object(value, &["schema", "batch", "report_sha256", "artifacts"])?;
    if string(value, "schema")? != "rivetlua-p17-artifact-archive-v1"
        || string(value, "batch")? != "P17-B02"
        || string(value, "report_sha256")? != B02_SHA
    {
        return Err("P17 phase B02 archive 主鍵不符".into());
    }
    let artifacts = array(value, "artifacts")?;
    if artifacts.len() != B02_ARCHIVE_BINARIES.len() {
        return Err("P17 phase B02 archive 雙版 artifact 數不符".into());
    }
    for (item, (_, filename, expected_sha)) in artifacts.iter().zip(B02_ARCHIVE_BINARIES) {
        object(item, &["original_path", "snapshot_path", "sha256"])?;
        if string(item, "original_path")?
            != target_dir
                .join("debug/deps")
                .join(filename)
                .display()
                .to_string()
            || string(item, "snapshot_path")? != archive_dir.join(filename).display().to_string()
            || string(item, "sha256")? != expected_sha
        {
            return Err(format!("P17 phase B02 archive path/SHA 不符：{filename}"));
        }
    }
    Ok(())
}

fn b02_archive_mach_execute_header(header: &[u8; 16]) -> bool {
    header[..4] == [0xcf, 0xfa, 0xed, 0xfe]
        && u32::from_le_bytes(header[4..8].try_into().expect("fixed header length")) == 0x0100_000c
        && u32::from_le_bytes(header[12..16].try_into().expect("fixed header length")) == 2
}

fn b02_archive_mach_execute(path: &Path) -> Result<(), String> {
    let mut header = [0u8; 16];
    File::open(path)
        .and_then(|mut file| file.read_exact(&mut header))
        .map_err(|error| format!("P17 phase B02 archive Mach header 不可讀：{error}"))?;
    if !b02_archive_mach_execute_header(&header) {
        return Err("P17 phase B02 archive 非 arm64 Mach-O EXECUTE".into());
    }
    Ok(())
}

fn b02_archive(
    root: &Path,
    evidence: &Path,
    view: &mut report::PhaseSourceView,
) -> Result<(report::Input, [report::Input; 2]), String> {
    let archive_dir = evidence.join("p17-b02-artifact-baseline");
    let manifest_path = archive_dir.join("manifest.json");
    sha(&manifest_path, B02_ARCHIVE_SHA)?;
    let value = StrictJsonParser::parse(
        &fs::read_to_string(&manifest_path).map_err(|error| error.to_string())?,
    )?;
    let target_dir = runner::environment(root)?.target_dir;
    b02_archive_schema(&value, &target_dir, &archive_dir)?;
    let old_report = root.join("target/rivetlua-reports/gate-P17-B02.json");
    sha(&old_report, B02_SHA)?;
    let old_value = StrictJsonParser::parse(
        &fs::read_to_string(&old_report).map_err(|error| error.to_string())?,
    )?;
    let old_runs = array(field(&old_value, "internal_mapping")?, "runs")?;
    let canonical_archive = fs::canonicalize(&archive_dir).map_err(|error| error.to_string())?;
    let mut snapshots = Vec::new();
    for (item, (profile, filename, expected_sha)) in
        array(&value, "artifacts")?.iter().zip(B02_ARCHIVE_BINARIES)
    {
        let original = target_dir.join("debug/deps").join(filename);
        let snapshot = archive_dir.join(filename);
        sha(&snapshot, expected_sha)?;
        let metadata = fs::symlink_metadata(&snapshot).map_err(|error| error.to_string())?;
        if !metadata.file_type().is_file()
            || metadata.permissions().mode() & 0o777 != 0o555
            || !fs::canonicalize(&snapshot)
                .map_err(|error| error.to_string())?
                .starts_with(&canonical_archive)
        {
            return Err(format!(
                "P17 phase B02 archive 非固定 0555 regular snapshot：{filename}"
            ));
        }
        b02_archive_mach_execute(&snapshot)?;
        let matching = old_runs
            .iter()
            .filter(|run| {
                run.get("target").and_then(StrictJsonValue::as_str)
                    == Some("p17_internal_replacements")
                    && run.get("profile").and_then(StrictJsonValue::as_str) == Some(profile)
            })
            .collect::<Vec<_>>();
        if matching.is_empty() {
            return Err(format!(
                "P17 phase B02 archive 原報告 profile 缺失：{profile}"
            ));
        }
        for run in matching {
            let executable = field(run, "executable")?;
            object(executable, &["path", "sha256"])?;
            if string(executable, "path")? != original.display().to_string()
                || string(executable, "sha256")? != expected_sha
            {
                return Err(format!("P17 phase B02 archive 與舊 run 不符：{profile}"));
            }
        }
        if string(item, "original_path")? != original.display().to_string() {
            return Err("P17 phase B02 archive original path 漂移".into());
        }
        snapshots.push(report::Input::from_path(&snapshot)?);
    }
    let snapshots: [report::Input; 2] = snapshots
        .try_into()
        .map_err(|_| "P17 phase B02 archive snapshot 數不符")?;
    for ((_, filename, expected_sha), snapshot) in B02_ARCHIVE_BINARIES.iter().zip(&snapshots) {
        view.insert(
            target_dir
                .join("debug/deps")
                .join(filename)
                .display()
                .to_string(),
            report::HistoricalSource {
                before_sha256: (*expected_sha).into(),
                snapshot: PathBuf::from(&snapshot.path),
            },
        );
    }
    Ok((report::Input::from_path(&manifest_path)?, snapshots))
}

fn error_review(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    view: &mut report::PhaseSourceView,
    host: Option<&HostReview>,
    console: Option<&ConsoleReview>,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<ErrorReview>, String> {
    let path = evidence.join("p17-phase-error-position-source-impact-review.json");
    if !path.exists() {
        return Ok(None);
    }
    let host = host.ok_or("P17 phase error-position review 缺已驗 host 鏈")?;
    let (baseline, baseline_input) = error_baseline(root, evidence, host, console)?;
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    error_review_header(&value)?;
    error_change_schema(&value)?;
    let changes = array(&value, "changes")?;
    for (index, (item, relative)) in changes.iter().zip(ERROR_CHANGES).enumerate() {
        object(
            item,
            &[
                "path",
                "before_sha256",
                "after_sha256",
                "diff_path",
                "diff_sha256",
            ],
        )?;
        let current = root.join(relative);
        // 舊 Error Position proof 使用快照；現行來源只經 scoped final row 查核。
        if relative == ERROR_NEW_TEST {
            if let Some(context) = verified {
                context.check(current_root, evidence)?;
            }
        }
        let effective = if relative == ERROR_NEW_TEST
            && final_source_live_source_with_verified(current_root, evidence, verified)?
        {
            evidence.join(FINAL_SOURCE_DIR).join(format!(
                "before-{}", relative.replace('/', "__")))
        } else {
            console.map_or_else(
                || current.clone(),
                |console| console.endpoint(root, relative),
            )
        };
        let old = if index == 0 {
            baseline.join(relative.replace('/', "__"))
        } else {
            PathBuf::from("/dev/null")
        };
        let diff = evidence.join(format!(
            "p17-phase-error-position-impact-{}.diff",
            relative.replace('/', "__")
        ));
        if string(item, "path")? != relative
            || string(item, "after_sha256")? != manifest::sha256(&effective)?
            || string(item, "diff_path")? != diff.display().to_string()
            || (index == 0 && string(item, "before_sha256")? != ERROR_FILES[0].1)
            || (index == 1 && !matches!(field(item, "before_sha256")?, StrictJsonValue::Null))
        {
            return Err(format!(
                "P17 phase error-position change identity 不符：{relative}"
            ));
        }
        sha(&diff, string(item, "diff_sha256")?)?;
        let output = verified_review_git(root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(&old)
            .arg(&effective)
            .output()
            .map_err(|error| error.to_string())?;
        if output.status.code() != Some(1)
            || !console_old_diff_matches(
                &output.stdout,
                &fs::read(&diff).map_err(|error| error.to_string())?,
                &old,
                &current,
                &effective,
            )?
        {
            return Err(format!(
                "P17 phase error-position raw diff 不符：{relative}"
            ));
        }
    }
    validate_error_proofs(root, evidence, &value, console)?;
    let (archive_manifest, archive_executables) = b02_archive(root, evidence, view)?;
    view.insert(
        root.join(ERROR_FILES[0].0).display().to_string(),
        report::HistoricalSource {
            before_sha256: ERROR_FILES[0].1.into(),
            snapshot: baseline.join(ERROR_FILES[0].0.replace('/', "__")),
        },
    );
    view.mark_old_absent(root.join(ERROR_NEW_TEST).display().to_string());
    Ok(Some(ErrorReview {
        input: report::Input::from_path(&path)?,
        baseline: baseline_input,
        archive_manifest,
        archive_executables,
    }))
}

fn error_source_schema(
    root: &Path,
    record: &StrictJsonValue,
    expected: &[&str],
) -> Result<(), String> {
    let sources = array(record, "source_inputs")?;
    if sources.len() != expected.len() {
        return Err("P17 phase error-position source input 數不符".into());
    }
    for (source, relative) in sources.iter().zip(expected) {
        object(source, &["path", "sha256"])?;
        let digest = string(source, "sha256")?;
        if string(source, "path")? != root.join(relative).display().to_string()
            || digest.len() != 64
            || !digest
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        {
            return Err(format!(
                "P17 phase error-position source identity 不符：{relative}"
            ));
        }
    }
    Ok(())
}

fn error_sources(
    root: &Path,
    record: &StrictJsonValue,
    expected: &[&str],
    console: Option<&ConsoleReview>,
) -> Result<(), String> {
    error_source_schema(root, record, expected)?;
    for source in array(record, "source_inputs")? {
        if let Some(console) = console {
            console.historical_input(source)?;
        } else {
            input(source)?;
        }
    }
    Ok(())
}

fn error_evidence_file(path: &Path, evidence: &Path) -> Result<(), String> {
    let expected_dir = evidence.join("p17-error-position-regressions");
    let canonical_dir = fs::canonicalize(&expected_dir).map_err(|error| error.to_string())?;
    let canonical = fs::canonicalize(path).map_err(|error| error.to_string())?;
    if !path.is_absolute()
        || !path.starts_with(&expected_dir)
        || !canonical.starts_with(&canonical_dir)
        || path
            .components()
            .any(|part| matches!(part, Component::ParentDir))
        || !fs::symlink_metadata(path)
            .map_err(|error| error.to_string())?
            .file_type()
            .is_file()
    {
        return Err(format!(
            "P17 phase error-position evidence path 不符：{}",
            path.display()
        ));
    }
    Ok(())
}

fn error_artifacts(body: &str) -> Result<BTreeMap<String, PathBuf>, String> {
    let mut found = BTreeMap::new();
    for line in body.lines() {
        let Ok(value) = StrictJsonParser::parse(line) else {
            continue;
        };
        if value.get("reason").and_then(StrictJsonValue::as_str) != Some("compiler-artifact") {
            continue;
        }
        let target = value
            .get("target")
            .ok_or("P17 phase error-position Cargo target 缺失")?;
        let Some(name) = target.get("name").and_then(StrictJsonValue::as_str) else {
            continue;
        };
        if !["p17_internal_replacements", "p17_lifecycle"].contains(&name) {
            continue;
        }
        let kinds = target
            .get("kind")
            .and_then(StrictJsonValue::as_array)
            .ok_or("P17 phase error-position Cargo kind 缺失")?;
        if !kinds.iter().any(|item| item.as_str() == Some("test")) {
            return Err("P17 phase error-position Cargo 非 test artifact".into());
        }
        let path = value
            .get("executable")
            .and_then(StrictJsonValue::as_str)
            .ok_or("P17 phase error-position Cargo executable 缺失")?;
        if found.insert(name.to_owned(), PathBuf::from(path)).is_some() {
            return Err("P17 phase error-position Cargo 重複 artifact".into());
        }
    }
    if found.len() != 2 {
        return Err("P17 phase error-position Cargo artifact 零匹配／缺失".into());
    }
    Ok(found)
}

fn error_named_log(body: &str, names: &[&str]) -> Result<(), String> {
    let running = body
        .lines()
        .filter_map(|line| {
            line.trim().strip_prefix("running ").and_then(|rest| {
                rest.strip_suffix(" tests")
                    .or_else(|| rest.strip_suffix(" test"))
                    .and_then(|count| count.parse::<usize>().ok())
            })
        })
        .collect::<Vec<_>>();
    if running != [names.len()] {
        return Err("P17 phase error-position running count 不符".into());
    }
    let (counts, outcomes) = parse_named_log_with_filter(body, names, true)?;
    if counts.matched != names.len() as u32
        || counts.passed != names.len() as u32
        || counts.failed != 0
        || counts.ignored != 0
        || outcomes.values().any(|outcome| *outcome != "ok")
    {
        return Err("P17 phase error-position 具名結果非真 PASS".into());
    }
    Ok(())
}

fn error_build_command(profile: &str) -> Vec<String> {
    let mut command = [
        "cargo",
        "test",
        "--locked",
        "-p",
        "rivetlua-capi",
        "--test",
        "p17_internal_replacements",
        "--test",
        "p17_lifecycle",
        "--no-run",
        "--message-format=json-render-diagnostics",
    ]
    .iter()
    .map(|part| (*part).to_owned())
    .collect::<Vec<_>>();
    if profile == PROFILES[0] {
        command.extend(["--features".into(), "lua55".into()]);
    } else {
        command.extend([
            "--no-default-features".into(),
            "--features".into(),
            "lua54".into(),
        ]);
    }
    command
}

fn validate_error_builds(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    target_dir: &Path,
    used_logs: &mut BTreeSet<String>,
    console: Option<&ConsoleReview>,
) -> Result<Vec<BTreeMap<String, report::Input>>, String> {
    let builds = array(review, "builds")?;
    if builds.len() != PROFILES.len() {
        return Err("P17 phase error-position build profile 數不符".into());
    }
    let expected_sources = [
        ERROR_FILES[0].0,
        ERROR_FILES[1].0,
        "crates/rivetlua-capi/Cargo.toml",
        "Cargo.lock",
        "crates/rivetlua-capi/tests/p17_internal_replacements.rs",
        "crates/rivetlua-capi/tests/p17_lifecycle.rs",
    ];
    let mut result = Vec::new();
    for (build, profile) in builds.iter().zip(PROFILES) {
        object(
            build,
            &[
                "profile",
                "command",
                "cwd",
                "exit_code",
                "log_path",
                "log_sha256",
                "artifacts",
                "source_inputs",
            ],
        )?;
        let log = Path::new(string(build, "log_path")?);
        if string(build, "profile")? != profile
            || strings(build, "command")? != error_build_command(profile)
            || string(build, "cwd")? != root.display().to_string()
            || integer(build, "exit_code")? != 0
            || !used_logs.insert(log.display().to_string())
        {
            return Err(format!(
                "P17 phase error-position build command/count 不符：{profile}"
            ));
        }
        error_sources(root, build, &expected_sources, console)?;
        error_evidence_file(log, evidence)?;
        sha(log, string(build, "log_sha256")?)?;
        let found = error_artifacts(&fs::read_to_string(log).map_err(|error| error.to_string())?)?;
        let artifacts = array(build, "artifacts")?;
        if artifacts.len() != 2 {
            return Err("P17 phase error-position build artifacts 數不符".into());
        }
        let mut snapshots = BTreeMap::new();
        for (item, target) in artifacts
            .iter()
            .zip(["p17_internal_replacements", "p17_lifecycle"])
        {
            object(
                item,
                &[
                    "target",
                    "artifact_path",
                    "artifact_sha256",
                    "executable_path",
                    "executable_sha256",
                    "post_sha256",
                ],
            )?;
            let original = found
                .get(target)
                .ok_or("P17 phase error-position artifact 缺失")?;
            let snapshot = Path::new(string(item, "executable_path")?);
            let original_path = Path::new(string(item, "artifact_path")?);
            if string(item, "target")? != target
                || original_path != original
                || !original_path.is_absolute()
                || !original_path.starts_with(target_dir)
                || original_path
                    .components()
                    .any(|part| matches!(part, Component::ParentDir))
                || string(item, "artifact_sha256")? != string(item, "executable_sha256")?
                || string(item, "post_sha256")? != string(item, "executable_sha256")?
                || snapshot.file_name().and_then(|name| name.to_str())
                    != Some(format!("{profile}-{target}").as_str())
            {
                return Err(format!(
                    "P17 phase error-position artifact identity 不符：{profile}/{target}"
                ));
            }
            error_evidence_file(snapshot, evidence)?;
            sha(snapshot, string(item, "executable_sha256")?)?;
            if fs::metadata(snapshot)
                .map_err(|error| error.to_string())?
                .permissions()
                .mode()
                & 0o777
                != 0o555
            {
                return Err("P17 phase error-position snapshot 非 0555".into());
            }
            report::mach_type(snapshot, "EXECUTE")?;
            if snapshots
                .insert(target.into(), report::Input::from_path(snapshot)?)
                .is_some()
            {
                return Err("P17 phase error-position snapshot 重複".into());
            }
        }
        result.push(snapshots);
    }
    Ok(result)
}

fn error_environment(
    record: &StrictJsonValue,
    expected: &[(String, String)],
) -> Result<(), String> {
    let observed = array(record, "environment")?
        .iter()
        .map(|item| {
            object(item, &["name", "value"])?;
            Ok((
                string(item, "name")?.to_owned(),
                string(item, "value")?.to_owned(),
            ))
        })
        .collect::<Result<Vec<_>, String>>()?;
    if observed != expected {
        return Err("P17 phase error-position environment 不符".into());
    }
    Ok(())
}

fn validate_error_regressions(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    builds: &[BTreeMap<String, report::Input>],
    used_logs: &mut BTreeSet<String>,
    console: Option<&ConsoleReview>,
) -> Result<(), String> {
    let regressions = array(review, "regressions")?;
    if regressions.len() != 8 {
        return Err("P17 phase error-position regression 數不符".into());
    }
    let runtime_new_sources = [
        ERROR_FILES[0].0,
        ERROR_FILES[1].0,
        "crates/rivetlua-runtime/Cargo.toml",
        "Cargo.lock",
        ERROR_NEW_TEST,
    ];
    let runtime_export_sources = [
        ERROR_FILES[0].0,
        ERROR_FILES[1].0,
        "crates/rivetlua-runtime/Cargo.toml",
        "Cargo.lock",
        "crates/rivetlua-runtime/tests/official_chunk_runtime.rs",
    ];
    let capi_cstack_sources = [
        ERROR_FILES[0].0,
        ERROR_FILES[1].0,
        "crates/rivetlua-capi/Cargo.toml",
        "Cargo.lock",
        "crates/rivetlua-capi/tests/p17_internal_replacements.rs",
    ];
    let capi_lifecycle_sources = [
        ERROR_FILES[0].0,
        ERROR_FILES[1].0,
        "crates/rivetlua-capi/Cargo.toml",
        "Cargo.lock",
        "crates/rivetlua-capi/tests/p17_lifecycle.rs",
    ];
    let environment = runner::environment(root)?;
    let registry = parse_registry(root, &environment.target)?;
    for (index, record) in regressions.iter().enumerate() {
        object(
            record,
            &[
                "kind",
                "profile",
                "command",
                "cwd",
                "environment",
                "exit_code",
                "matched",
                "passed",
                "failed",
                "ignored",
                "log_path",
                "log_sha256",
                "source_inputs",
                "selectors",
                "build_index",
                "marker",
            ],
        )?;
        let (kind, profile, names, sources, build_index, target, log_name) = match index {
            0 => (
                "runtime-new",
                "both",
                vec![
                    "p17_error_position_basic",
                    "p17_error_position_dispatch_lifecycle",
                ],
                &runtime_new_sources[..],
                None,
                None,
                Some("p17-phase-error-position-runtime.log"),
            ),
            1 => (
                "runtime-export",
                "both",
                vec!["p17_export_open_call_runtime_semantics"],
                &runtime_export_sources[..],
                None,
                None,
                Some("p17-phase-error-position-export-runtime.log"),
            ),
            2 => (
                "b02-cstack",
                PROFILES[0],
                vec!["p17_internal_c_stack_errors"],
                &capi_cstack_sources[..],
                Some(0),
                Some("p17_internal_replacements"),
                None,
            ),
            3 => (
                "b02-cstack",
                PROFILES[1],
                vec!["p17_internal_c_stack_errors"],
                &capi_cstack_sources[..],
                Some(1),
                Some("p17_internal_replacements"),
                None,
            ),
            4 => (
                "b03-gc",
                PROFILES[0],
                vec!["p17_stress_gc_long_run"],
                &capi_lifecycle_sources[..],
                Some(0),
                Some("p17_lifecycle"),
                None,
            ),
            5 => (
                "b03-coroutine",
                PROFILES[0],
                vec!["p17_stress_coroutine_debug"],
                &capi_lifecycle_sources[..],
                Some(0),
                Some("p17_lifecycle"),
                None,
            ),
            6 => (
                "b03-gc",
                PROFILES[1],
                vec!["p17_stress_gc_long_run"],
                &capi_lifecycle_sources[..],
                Some(1),
                Some("p17_lifecycle"),
                None,
            ),
            _ => (
                "b03-coroutine",
                PROFILES[1],
                vec!["p17_stress_coroutine_debug"],
                &capi_lifecycle_sources[..],
                Some(1),
                Some("p17_lifecycle"),
                None,
            ),
        };
        let command = if let Some(build_index) = build_index {
            let binary = builds
                .get(build_index)
                .and_then(|artifacts| artifacts.get(target.expect("fixed target")))
                .ok_or("P17 phase error-position fresh binary 缺失")?;
            vec![
                binary.path.clone(),
                names[0].into(),
                "--exact".into(),
                "--nocapture".into(),
                "--test-threads=1".into(),
            ]
        } else if index == 0 {
            [
                "cargo",
                "test",
                "--locked",
                "-p",
                "rivetlua-runtime",
                "--test",
                "p17_error_position",
                "p17_error_position_",
                "--",
                "--nocapture",
                "--test-threads=1",
            ]
            .iter()
            .map(|part| (*part).to_owned())
            .collect()
        } else {
            [
                "cargo",
                "test",
                "--locked",
                "-p",
                "rivetlua-runtime",
                "--test",
                "official_chunk_runtime",
                "p17_export_open_call_runtime_semantics",
                "--",
                "--exact",
                "--nocapture",
                "--test-threads=1",
            ]
            .iter()
            .map(|part| (*part).to_owned())
            .collect()
        };
        let observed_build = field(record, "build_index")?;
        let build_valid = match build_index {
            Some(expected) => {
                matches!(observed_build, StrictJsonValue::Number(number) if number.parse::<usize>().ok() == Some(expected))
            }
            None => matches!(observed_build, StrictJsonValue::Null),
        };
        let log = Path::new(string(record, "log_path")?);
        if string(record, "kind")? != kind
            || string(record, "profile")? != profile
            || strings(record, "command")? != command
            || string(record, "cwd")? != root.display().to_string()
            || integer(record, "exit_code")? != 0
            || integer(record, "matched")? != names.len() as u64
            || integer(record, "passed")? != names.len() as u64
            || integer(record, "failed")? != 0
            || integer(record, "ignored")? != 0
            || strings(record, "selectors")? != names
            || !build_valid
            || !used_logs.insert(log.display().to_string())
        {
            return Err(format!(
                "P17 phase error-position regression command/count 不符：{kind}/{profile}"
            ));
        }
        error_sources(root, record, sources, console)?;
        if let Some(log_name) = log_name {
            if log != evidence.join(log_name) {
                return Err("P17 phase error-position Runtime log path 不符".into());
            }
        } else {
            error_evidence_file(log, evidence)?;
        }
        let expected_environment = if build_index.is_some() {
            runner::effective_no_native_environment()
        } else {
            Vec::new()
        };
        error_environment(record, &expected_environment)?;
        sha(log, string(record, "log_sha256")?)?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        error_named_log(&body, &names)?;
        if index >= 4 {
            let markers = marker_records(&body, &names, true)?;
            let marker = markers
                .get(names[0])
                .ok_or("P17 phase error-position B03 marker 缺失")?;
            if canonical_json(field(record, "marker")?) != canonical_json(marker) {
                return Err("P17 phase error-position B03 marker 與 log 不符".into());
            }
            let spec = CASES
                .iter()
                .copied()
                .find(|spec| spec.id == names[0])
                .ok_or("P17 phase error-position B03 case 未宣告")?;
            validate_record(marker, spec, profile, &registry, true)?;
        } else if !matches!(field(record, "marker")?, StrictJsonValue::Null)
            || body.contains(MARKER)
        {
            return Err("P17 phase error-position 非 B03 marker 不符".into());
        }
    }
    Ok(())
}

fn validate_error_proofs(
    root: &Path,
    evidence: &Path,
    review: &StrictJsonValue,
    console: Option<&ConsoleReview>,
) -> Result<(), String> {
    let target_dir = runner::environment(root)?.target_dir;
    let mut used_logs = BTreeSet::new();
    let builds =
        validate_error_builds(root, evidence, review, &target_dir, &mut used_logs, console)?;
    validate_error_regressions(root, evidence, review, &builds, &mut used_logs, console)
}

fn bind_host_entry_historical_endpoint(
    original_root: &Path,
    view: &mut report::PhaseSourceView,
    relative: &str,
    source: &report::HistoricalSource,
) -> Result<(), String> {
    if ![HOST_ENTRY_PATHS[0], HOST_ENTRY_PATHS[2], HOST_ENTRY_PATHS[3]].contains(&relative) {
        return Err(format!("P17 host-entry 歷史endpoint 範圍外：{relative}"));
    }
    sha(&source.snapshot, &source.before_sha256)?;
    let historical = original_root.join(relative).display().to_string();
    let observed = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"sha256\":{}}}",
        report::q(&historical),
        report::q(&source.before_sha256)
    ))?;
    if report::historical_input(&observed, view)?.is_none() {
        view.insert(
            historical,
            report::HistoricalSource {
                before_sha256: source.before_sha256.clone(),
                snapshot: source.snapshot.clone(),
            },
        );
    }
    Ok(())
}

fn bind_exit_parser_historical_endpoint(
    original_root: &Path,
    view: &mut report::PhaseSourceView,
    source: report::HistoricalSource,
) -> Result<(), String> {
    sha(&source.snapshot, &source.before_sha256)?;
    let historical = original_root.join(EXIT_PARSER_PATH).display().to_string();
    let observed = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"sha256\":{}}}",
        report::q(&historical),
        report::q(&source.before_sha256),
    ))?;
    if report::historical_input(&observed, view)?.is_some() {
        return Err("P17 parser 舊來源 endpoint 衝突".into());
    }
    view.insert(historical, source);
    Ok(())
}

fn bind_exit_ctrl_host_historical_endpoints(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    view: &mut report::PhaseSourceView,
) -> Result<(), String> {
    bind_exit_ctrl_host_historical_endpoints_with_verified(
        original_root, current_root, evidence, view, None)
}

fn bind_exit_ctrl_host_historical_endpoints_with_verified(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    view: &mut report::PhaseSourceView,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let mut endpoints = Vec::new();
    for relative in [EXIT_CTRL_BIN_PATH, EXIT_CTRL_MANIFEST_PATH, EXIT_CTRL_LOCK_PATH] {
        let snapshot = exit_ctrl_c_before_source_with_verified(
            current_root, evidence, relative, verified)?;
        let before = EXIT_CTRL_CHANGES[exit_ctrl_c_source_index(relative)
            .ok_or("P17 Ctrl-C host source 範圍缺失")?].1;
        let historical = original_root.join(relative).display().to_string();
        let observed = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&historical), report::q(before),
        ))?;
        if report::historical_input(&observed, view)?.is_some() {
            return Err(format!("P17 Ctrl-C host 舊來源 endpoint 衝突：{relative}"));
        }
        endpoints.push((historical, report::HistoricalSource {
            before_sha256: before.into(), snapshot,
        }));
    }
    for (path, source) in endpoints {
        view.insert(path, source);
    }
    Ok(())
}

fn phase_review(root: &Path, evidence: &Path) -> Result<Option<PhaseReview>, String> {
    #[cfg(test)]
    let phase_started = std::time::Instant::now();
    let original_root = assert_warning_original_root(root, evidence)?;
    let (final_source, scoped_verified, mut verified_scope) =
        final_source_review_source_scoped(&original_root, root, evidence)?;
    #[cfg(test)]
    eprintln!("P17 phase final_source {:?}", phase_started.elapsed());
    let verified = scoped_verified.as_ref();
    let debug_hook = debug_hook_review_source(&original_root, root, evidence, verified)?;
    let debug_vm = debug_vm_review_source(&original_root, root, evidence, verified)?;
    #[cfg(test)]
    eprintln!("P17 phase debug {:?}", phase_started.elapsed());
    let producer = producer_update_source(&original_root, root, evidence, verified)?;
    let gc = gc_review_source(&original_root, root, evidence, producer.as_ref(), verified)?;
    #[cfg(test)]
    eprintln!("P17 phase producer_gc {:?}", phase_started.elapsed());
    let exit = exit_review_sources(&original_root, root, evidence, producer.as_ref(), verified)?;
    #[cfg(test)]
    eprintln!("P17 phase exit_sources {:?}", phase_started.elapsed());
    let host_entry = exit
        .as_ref()
        .map(|(review, _)| host_entry_review(&original_root, root, evidence, review, verified))
        .transpose()?;
    let assert_warning = assert_warning_review(
        &original_root,
        root,
        evidence,
        exit.as_ref().map(|(review, _)| review),
        host_entry.as_ref().map(|review| &review.old_sources),
    )?;
    #[cfg(test)]
    eprintln!("P17 phase assert_warning {:?}", phase_started.elapsed());
    let mut console = console_review_with_verified(
        &original_root,
        root,
        evidence,
        assert_warning.as_ref(),
        exit.as_ref()
            .and_then(|(_, value)| value.get("public_cli_test_update")),
        exit.as_ref()
            .is_some_and(|(_, value)| value.get("parser_update").is_some()),
        exit.as_ref()
            .is_some_and(|(_, value)| value.get("cli_unit_test_only_update").is_some()),
        exit.as_ref()
            .is_some_and(|(_, value)| value.get("cli_binary_file_prefix_update").is_some()),
        exit.as_ref()
            .is_some_and(|(_, value)| value.get("cli_version_banner_update").is_some()),
        exit.as_ref()
            .is_some_and(|(_, value)| value.get("cli_diagnostics_update").is_some()),
        exit.as_ref().is_some_and(|(review, _)| review.ctrl_c_updated),
        verified,
    )?;
    #[cfg(test)]
    eprintln!("P17 phase console {:?}", phase_started.elapsed());
    if exit.is_some() {
        let repair = assert_warning
            .as_ref()
            .ok_or("P17 Exit Host 缺已驗 Assert/Warning 前態")?;
        let console_view = console.as_mut().ok_or("P17 Exit Host 缺 Console 歷史鏈")?;
        let host_path = evidence.join("p17-phase-host-source-impact-review.json");
        sha(&host_path, CONSOLE_HOST_SHA)?;
        let host_value = StrictJsonParser::parse(
            &fs::read_to_string(&host_path).map_err(|error| error.to_string())?,
        )?;
        host_review_header(&host_value)?;
        let host_change = array(&host_value, "changes")?
            .get(1)
            .ok_or("P17 Exit Host 舊 change 缺失")?;
        let source = repair
            .exit_sources
            .get(&original_root.join(HOST_CHANGES[1]).display().to_string());
        bind_host_exit_endpoint(&original_root, console_view, source, host_change)?;
    }
    let mut phase = phase_review_with_console(
        &original_root,
        root,
        evidence,
        console,
        assert_warning,
        host_entry.as_ref(),
        exit.as_ref().is_some_and(|(review, _)| review.ctrl_c_updated),
        gc.is_some(),
        producer.is_some(),
        verified,
    )?;
    #[cfg(test)]
    eprintln!("P17 phase source_review {:?}", phase_started.elapsed());
    if let Some(phase) = &mut phase {
        if let Some(producer_review) = &producer {
            let native = original_root.join(PRODUCER_NATIVE_PATH).display().to_string();
            let historical = StrictJsonParser::parse(&format!(
                "{{\"path\":{},\"sha256\":{}}}",
                report::q(&native), report::q(PHASE_SOURCES[0].1),
            ))?;
            if report::historical_input(&historical, &phase.view)?.is_none() {
                return Err("P17 producer 原 exporter 歷史 endpoint 缺失".into());
            }
            let string_path = original_root.join(PRODUCER_STRING_PATH).display().to_string();
            let string_old = StrictJsonParser::parse(&format!(
                "{{\"path\":{},\"sha256\":{}}}",
                report::q(&string_path), report::q(PRODUCER_STRING_BEFORE_SHA),
            ))?;
            if report::historical_input(&string_old, &phase.view)?.is_some() {
                return Err("P17 producer string 舊 endpoint 已存在".into());
            }
            phase.view.insert(string_path, report::HistoricalSource {
                before_sha256: PRODUCER_STRING_BEFORE_SHA.into(),
                snapshot: evidence.join(PRODUCER_SOURCE_DIR).join(format!(
                    "before-{}", PRODUCER_STRING_PATH.replace('/', "__"),
                )),
            });
            phase.view.mark_old_absent(original_root.join(PRODUCER_SDK_TEST_PATH).display().to_string());
            phase.producer_update = Some(ProducerUpdateReview {
                input: producer_review.input.clone(),
                after_hashes: producer_review.after_hashes.clone(),
                tool_after_sha: producer_review.tool_after_sha.clone(),
            });
        }
        if let Some(gc) = &gc {
            phase.gc = Some(GcReview { input: gc.input.clone() });
        }
        if let Some(debug_vm) = &debug_vm {
            phase.view.mark_old_absent(
                original_root.join(DEBUG_VM_TEST_PATH).display().to_string(),
            );
            phase.debug_vm = Some(DebugVmReview { input: debug_vm.input.clone() });
        }
        if let Some(debug_hook) = &debug_hook {
            if phase.debug_vm.is_none() {
                return Err("P17 debug hook 缺前一版 debug VM typed bridge".into());
            }
            phase.view.mark_old_absent(
                original_root.join(DEBUG_HOOK_TEST_PATH).display().to_string(),
            );
            phase.debug_hook = Some(DebugHookReview { input: debug_hook.input.clone() });
        }
        if let Some(final_source) = &final_source {
            bind_final_manifest_report_view(
                &original_root, root, evidence, &mut phase.view, verified,
            )?;
            for (relative, before, _) in FINAL_SOURCE_CHANGES {
                if relative == PRODUCER_NATIVE_PATH || relative == ERROR_NEW_TEST {
                    continue;
                }
                let old_path = original_root.join(relative).display().to_string();
                let old_value = StrictJsonParser::parse(&format!(
                    "{{\"path\":{},\"sha256\":{}}}", report::q(&old_path), report::q(before),
                ))?;
                if report::historical_input(&old_value, &phase.view)?.is_some() {
                    return Err(format!("P17 final source 舊 endpoint 已存在：{relative}"));
                }
                phase.view.insert(old_path, report::HistoricalSource {
                    before_sha256: before.into(),
                    snapshot: evidence.join(FINAL_SOURCE_DIR).join(format!(
                        "before-{}", relative.replace('/', "__"))),
                });
            }
            phase.view.mark_old_absent(original_root.join(FINAL_COUNT_TEST_PATH)
                .display().to_string());
            phase.final_source = Some(FinalSourceReview {
                input: final_source.input.clone(),
                successor: final_source.successor.clone(),
                count_successor: final_source.count_successor.clone(),
                debug_successor: final_source.debug_successor.clone(),
                verified: final_source.verified.clone(),
            });
        }
        if let Some((exit, value)) = exit {
            let host_entry = host_entry.ok_or("P17 Exit 缺已驗 host-entry review")?;
            exit_review_proofs(root, evidence, &value, &exit)?;
            if verified.is_some_and(|context| context.product_successor_active) {
                for (relative, before, _, snapshot_relative) in PRODUCT_SUCCESSOR_NEW_SOURCE_EDGES {
                    let historical = original_root.join(relative).display().to_string();
                    let observed = StrictJsonParser::parse(&format!(
                        r#"{{"path":{},"sha256":{}}}"#,
                        report::q(&historical), report::q(before),
                    ))?;
                    let accepted = exit.v1_input(&observed)?;
                    if accepted.path != historical || accepted.sha256 != before
                        || report::historical_input(&observed, &phase.view)?.is_some() {
                        return Err(format!("P17 product phase 歷史 source 衝突：{relative}"));
                    }
                    phase.view.insert(historical.clone(), report::HistoricalSource {
                        before_sha256: before.into(), snapshot: evidence.join(snapshot_relative),
                    });
                    if report::historical_input(&observed, &phase.view)? != Some(historical) {
                        return Err(format!("P17 product phase 歷史 source 缺失：{relative}"));
                    }
                }
            }
            if let Some(parser_update) = value.get("parser_update") {
                let snapshot = PathBuf::from(string(parser_update, "before_snapshot_path")?);
                bind_exit_parser_historical_endpoint(
                    &original_root,
                    &mut phase.view,
                    report::HistoricalSource {
                        before_sha256: EXIT_PARSER_BEFORE_SHA.into(),
                        snapshot,
                    },
                )?;
            }
            if value.get("ctrl_c_update").is_some() {
                bind_exit_ctrl_host_historical_endpoints_with_verified(
                    &original_root, root, evidence, &mut phase.view, verified,
                )?;
                phase.view.mark_old_absent(
                    original_root.join(EXIT_CTRL_TEST_PATH).display().to_string(),
                );
            }
            for relative in [HOST_ENTRY_PATHS[0], HOST_ENTRY_PATHS[2], HOST_ENTRY_PATHS[3]] {
                let old = host_entry
                    .old_sources
                    .get(relative)
                    .ok_or("P17 host-entry 歷史endpoint缺失")?;
                bind_host_entry_historical_endpoint(
                    &original_root,
                    &mut phase.view,
                    relative,
                    old,
                )?;
            }
            // errors.rs 可能已有更早批次的歷史endpoint，不能覆寫它。
            for relative in EXIT_NEW_TESTS {
                phase
                    .view
                    .mark_old_absent(original_root.join(relative).display().to_string());
            }
            phase.view.mark_old_absent(
                original_root
                    .join(EXIT_PUBLIC_REPL_TEST_PATH)
                    .display()
                    .to_string(),
            );
            if value.get("cli_binary_file_prefix_update").is_some() {
                phase.view.mark_old_absent(
                    original_root
                        .join(EXIT_CLI_BINARY_TEST_PATH)
                        .display()
                        .to_string(),
                );
            }
            if value.get("cli_version_banner_update").is_some() {
                phase.view.mark_old_absent(
                    original_root
                        .join(EXIT_CLI_VERSION_TEST_PATH)
                        .display()
                        .to_string(),
                );
            }
            if value.get("cli_diagnostics_update").is_some() {
                phase.view.mark_old_absent(
                    original_root.join(EXIT_CLI_DIAGNOSTICS_TEST_PATH).display().to_string(),
                );
            }
            if value.get("warn_argument_update").is_some() {
                phase.view.mark_old_absent(
                    original_root.join(EXIT_WARN_TEST_PATH).display().to_string(),
                );
            }
            phase.exit = Some(exit);
            phase.host_entry = Some(host_entry);
        }
        if phase.assert_warning.is_some() {
            assert_warning_current_sources(
                &original_root,
                root,
                evidence,
                phase.exit.as_ref(),
                phase.host_entry.as_ref(),
                phase.gc.as_ref(),
                phase.producer_update.as_ref(),
                phase.debug_vm.as_ref(),
                phase.debug_hook.as_ref(),
                phase.final_source.as_ref(),
                verified,
            )?;
        }
        phase.original_root = original_root;
    }
    if let (Some(scope), Some(context)) = (&mut verified_scope, verified) {
        scope.finish(context, root, evidence)?;
    }
    Ok(phase)
}

fn phase_export_endpoint(
    root: &Path,
    relative: &str,
    console: Option<&ConsoleReview>,
    repair: Option<&AssertWarningReview>,
    producer_before_native: Option<&Path>,
) -> PathBuf {
    if relative == PRODUCER_NATIVE_PATH {
        if let Some(snapshot) = producer_before_native {
            return snapshot.to_path_buf();
        }
    }
    let current = root.join(relative);
    if let Some(source) = repair.and_then(|repair| {
        repair
            .portability_sources
            .get(&current.display().to_string())
    }) {
        return source.snapshot.clone();
    }
    console.map_or_else(|| current, |console| console.endpoint(root, relative))
}

fn preserve_prior_error_historical_input(
    root: &Path,
    relative: &str,
    earliest_before: &str,
    warning_before: &str,
    view: &report::PhaseSourceView,
    console_sources: &BTreeMap<String, report::HistoricalSource>,
    host_sources: Option<&BTreeMap<String, report::HistoricalSource>>,
) -> Result<bool, String> {
    if relative != HOST_ENTRY_PATHS[1] {
        return Ok(false);
    }
    let Some(host_sources) = host_sources else {
        return Ok(false);
    };
    let path = root.join(relative).display().to_string();
    let earliest = console_sources
        .get(&path)
        .ok_or("P17 B03 errors 更早的 Console endpoint 缺失")?;
    if earliest.before_sha256 != earliest_before {
        return Err("P17 B03 errors Console 前態 SHA 不符".into());
    }
    sha(&earliest.snapshot, earliest_before)?;
    let warning = host_sources
        .get(relative)
        .ok_or("P17 B03 errors 已驗 host-entry 前態缺失")?;
    if warning.before_sha256 != warning_before {
        return Err("P17 B03 errors Warning／host-entry 前態不符".into());
    }
    sha(&warning.snapshot, warning_before)?;
    let observed = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"sha256\":{}}}",
        report::q(&path),
        report::q(earliest_before),
    ))?;
    if report::historical_input(&observed, view)?.is_none() {
        return Err("P17 B03 errors 更早的歷史 endpoint 未建置".into());
    }
    Ok(true)
}

fn phase_review_with_console(
    root: &Path,
    current_root: &Path,
    evidence: &Path,
    console: Option<ConsoleReview>,
    assert_warning: Option<AssertWarningReview>,
    host_entry: Option<&HostEntryReview>,
    ctrl_c_updated: bool,
    gc_updated: bool,
    producer_updated: bool,
    verified: Option<&FinalVerifiedContext>,
) -> Result<Option<PhaseReview>, String> {
    let path = evidence.join("p17-phase-source-impact-review.json");
    if !path.exists() {
        if console.is_some() || assert_warning.is_some() {
            return Err("P17 Console 缺既有 phase exporter review".into());
        }
        return Ok(None);
    }
    let baseline = phase_baseline(root, evidence)?;
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    object(
        &value,
        &[
            "schema",
            "baseline_manifest_sha256",
            "b01_report_sha256",
            "b02_report_sha256",
            "b03_report_sha256",
            "changes",
            "regression",
            "review_note",
        ],
    )?;
    if string(&value, "schema")? != "rivetlua-p17-phase-source-impact-v1"
        || string(&value, "baseline_manifest_sha256")? != PHASE_BASELINE_SHA
        || string(&value, "b01_report_sha256")? != B01_SHA
        || string(&value, "b02_report_sha256")? != B02_SHA
        || string(&value, "b03_report_sha256")? != B03_SHA
        || string(&value, "review_note")?.trim().len() < 8
    {
        return Err("P17 phase source-impact 主鍵不符".into());
    }
    let mut expected_changes = Vec::new();
    let producer_before_native = producer_updated.then(|| evidence.join(PRODUCER_SOURCE_DIR)
        .join(format!("before-{}", PRODUCER_NATIVE_PATH.replace('/', "__"))));
    for (relative, before_sha256) in PHASE_SOURCES {
        let effective =
            phase_export_endpoint(root, relative, console.as_ref(), assert_warning.as_ref(),
                producer_before_native.as_deref());
        let after_sha256 = manifest::sha256(&effective)?;
        if relative == "xtask/src/p17/mod.rs" {
            if after_sha256 != before_sha256 {
                return Err("P17 phase mod.rs 不得變更".into());
            }
        } else if after_sha256 != before_sha256 {
            expected_changes.push((relative, before_sha256, after_sha256));
        }
    }
    if !expected_changes
        .iter()
        .any(|(path, _, _)| *path == PHASE_SOURCES[0].0)
        || !expected_changes
            .iter()
            .any(|(path, _, _)| *path == PHASE_SOURCES[1].0)
    {
        return Err("P17 phase producer／回歸測試來源未定點修補".into());
    }
    let changes = array(&value, "changes")?;
    if changes.len() != expected_changes.len() {
        return Err("P17 phase changed source 清單不完整／範圍外".into());
    }
    let mut view = report::PhaseSourceView::new();
    for (change, (relative, before_sha256, after_sha256)) in changes.iter().zip(expected_changes) {
        object(
            change,
            &[
                "path",
                "before_sha256",
                "after_sha256",
                "diff_path",
                "diff_sha256",
            ],
        )?;
        let snapshot = baseline.join(relative.replace('/', "__"));
        let current = root.join(relative);
        let effective =
            phase_export_endpoint(root, relative, console.as_ref(), assert_warning.as_ref(),
                producer_before_native.as_deref());
        let diff = evidence.join(format!(
            "p17-phase-impact-{}.diff",
            relative.replace('/', "__")
        ));
        if string(change, "path")? != relative
            || string(change, "before_sha256")? != before_sha256
            || string(change, "after_sha256")? != after_sha256
            || string(change, "diff_path")? != diff.display().to_string()
        {
            return Err(format!("P17 phase source-impact identity 不符：{relative}"));
        }
        sha(&snapshot, before_sha256)?;
        sha(&diff, string(change, "diff_sha256")?)?;
        let output = verified_review_git(root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(&snapshot)
            .arg(&effective)
            .output()
            .map_err(|error| error.to_string())?;
        if output.status.code() != Some(1)
            || !console_old_diff_matches(
                &output.stdout,
                &fs::read(&diff).map_err(|error| error.to_string())?,
                &snapshot,
                &current,
                &effective,
            )?
        {
            return Err(format!("P17 phase source-impact raw diff 不符：{relative}"));
        }
        view.insert(
            current.display().to_string(),
            report::HistoricalSource {
                before_sha256: before_sha256.into(),
                snapshot,
            },
        );
    }
    if gc_updated {
        for (relative, digest) in [
            (GC_TABLE_PATH, GC_TABLE_BEFORE_SHA),
            (GC_METAMETHOD_PATH, GC_METAMETHOD_BEFORE_SHA),
        ] {
            let historical = root.join(relative).display().to_string();
            let observed = StrictJsonParser::parse(&format!(
                "{{\"path\":{},\"sha256\":{}}}", report::q(&historical), report::q(digest),
            ))?;
            if report::historical_input(&observed, &view)?.is_some() {
                return Err(format!("P17 GC 舊 phase 來源 endpoint 衝突：{relative}"));
            }
            view.insert(historical, report::HistoricalSource {
                before_sha256: digest.into(),
                snapshot: gc_before_source_with_verified(current_root, evidence,
                    relative, verified)?,
            });
        }
        view.mark_old_absent(root.join(GC_TEST_PATH).display().to_string());
    }
    let regression = field(&value, "regression")?;
    object(
        regression,
        &[
            "command",
            "cwd",
            "exit_code",
            "matched",
            "passed",
            "failed",
            "ignored",
            "log_path",
            "log_sha256",
            "source_inputs",
            "selectors",
            "related",
        ],
    )?;
    let expected_command = [
        "cargo",
        "test",
        "--locked",
        "-p",
        "rivetlua-compiler",
        "--test",
        "official_chunk_export",
        "p17_",
        "--",
        "--nocapture",
        "--test-threads=1",
    ];
    let names = [
        "p17_native_open_call_pending_values_roundtrip",
        "p17_official_main_chunk_export",
    ];
    let log = evidence.join("p17-phase-dump-regression.log");
    if strings(regression, "command")? != expected_command
        || string(regression, "cwd")? != root.display().to_string()
        || integer(regression, "exit_code")? != 0
        || integer(regression, "matched")? != 2
        || integer(regression, "passed")? != 2
        || integer(regression, "failed")? != 0
        || integer(regression, "ignored")? != 0
        || strings(regression, "selectors")? != names
        || string(regression, "log_path")? != log.display().to_string()
    {
        return Err("P17 phase 具名 dump 回歸欄位不符".into());
    }
    phase_regression_sources(root, regression, producer_before_native.as_deref())?;
    sha(&log, string(regression, "log_sha256")?)?;
    let body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
    phase_regression_log(&body)?;
    let runtime = phase_related_record(regression)?;
    let error_review_present = evidence
        .join("p17-phase-error-position-source-impact-review.json")
        .exists();
    let runtime_log = evidence.join("p17-phase-dump-runtime-regression.log");
    if !phase_runtime_command_matches(runtime, error_review_present)?
        || string(runtime, "cwd")? != root.display().to_string()
        || integer(runtime, "exit_code")? != 0
        || integer(runtime, "matched")? != 1
        || integer(runtime, "passed")? != 1
        || integer(runtime, "failed")? != 0
        || integer(runtime, "ignored")? != 0
        || strings(runtime, "selectors")? != ["p17_export_open_call_runtime_semantics"]
        || string(runtime, "log_path")? != runtime_log.display().to_string()
    {
        return Err("P17 phase runtime 語意回歸欄位不符".into());
    }
    phase_regression_sources(root, runtime, producer_before_native.as_deref())?;
    sha(
        &evidence.join("p17-phase-repair-runtime-test-before.rs"),
        "bc7ce117775a6d8f6eae409ff878dd25105dd3fc56181e60415724b85ecd619b",
    )?;
    sha(&runtime_log, string(runtime, "log_sha256")?)?;
    let runtime_body = fs::read_to_string(&runtime_log).map_err(|error| error.to_string())?;
    phase_runtime_regression_log(&runtime_body)?;
    let host = host_review_with_verified(
        root, current_root, evidence, &mut view, console.as_ref(),
        ctrl_c_updated, verified)?;
    let error = error_review(root, current_root, evidence, &mut view,
        host.as_ref(), console.as_ref(), verified)?;
    if let Some(console) = &console {
        if host.is_none() || error.is_none() {
            return Err("P17 Console 缺完整 host/error 歷史 proof".into());
        }
        for (path, source) in &console.old_sources {
            if !view.was_absent(path)
                && ![
                    ERROR_FILES[0].0,
                    HOST_CHANGES[0],
                    CONSOLE_TOOLS_FILES[0].0,
                    CONSOLE_TOOLS_FILES[1].0,
                ]
                .iter()
                .any(|relative| path == &root.join(relative).display().to_string())
                && manifest::sha256(Path::new(path))? != source.before_sha256
            {
                view.insert(
                    path.clone(),
                    report::HistoricalSource {
                        before_sha256: source.before_sha256.clone(),
                        snapshot: source.snapshot.clone(),
                    },
                );
            }
        }
        view.mark_old_absent(root.join(CONSOLE_NEW_TEST).display().to_string());
    }
    if let Some(repair) = &assert_warning {
        if console.is_none() || host.is_none() || error.is_none() {
            return Err("P17 Assert/Warning 缺完整既有歷史 proof 鏈".into());
        }
        for (relative, before) in WARNING_FILES {
            let path = root.join(relative);
            if manifest::sha256(&path)? == before
                || CONSOLE_CHANGE_PATHS.contains(&relative)
                || PHASE_SOURCES.iter().any(|(name, _)| *name == relative)
                || HOST_CHANGES.contains(&relative)
                || ERROR_CHANGES.contains(&relative)
            {
                continue;
            }
            if preserve_prior_error_historical_input(
                root,
                relative,
                ERROR_FILES[1].1,
                before,
                &view,
                &console.as_ref().ok_or("P17 Warning 缺 Console 歷史來源")?.old_sources,
                host_entry.map(|review| &review.old_sources),
            )? {
                continue;
            }
            let source = repair
                .warning_sources
                .get(&path.display().to_string())
                .ok_or("P17 Warning batch 前態缺失")?;
            view.insert(
                path.display().to_string(),
                report::HistoricalSource {
                    before_sha256: source.before_sha256.clone(),
                    snapshot: source.snapshot.clone(),
                },
            );
        }
        for relative in [ASSERT_NEW_TEST].into_iter().chain(WARNING_NEW_TESTS) {
            view.mark_old_absent(root.join(relative).display().to_string());
        }
        view.set_historical_environment(repair.historical_environment.clone())?;
    }
    if verified.is_some_and(|context| context.heap_successor_active) {
        bind_sparse_gc_phase_view(root, current_root, evidence, &mut view, verified)?;
    }
    Ok(Some(PhaseReview {
        input: report::Input::from_path(&path)?,
        original_root: root.to_path_buf(),
        view,
        host,
        error,
        console,
        assert_warning,
        exit: None,
        host_entry: None,
        gc: None,
        producer_update: None,
        debug_vm: None,
        debug_hook: None,
        final_source: None,
    }))
}

fn bind_sparse_gc_phase_view(
    original_root: &Path,
    current_root: &Path,
    evidence: &Path,
    view: &mut report::PhaseSourceView,
    verified: Option<&FinalVerifiedContext>,
) -> Result<(), String> {
    let path = original_root.join(GC_MOD_PATH).display().to_string();
    let historical = StrictJsonParser::parse(&format!(
        "{{\"path\":{},\"sha256\":{}}}",
        report::q(&path), report::q(GC_MOD_BEFORE_SHA),
    ))?;
    if report::historical_input(&historical, view)?.is_some() {
        return Err("P17 sparse GC phase 歷史 source 重複".into());
    }
    sparse_gc_historical_input_with_verified(
        original_root, current_root, evidence, &historical, verified,
    )?.ok_or("P17 sparse GC phase 缺已驗歷史 source")?;
    view.insert(path, report::HistoricalSource {
        before_sha256: GC_MOD_BEFORE_SHA.into(),
        snapshot: evidence.join(
            "p17-xtask-final-debug-successor-20261013-22/p17-gc-sparse-before-gc-mod.rs"),
    });
    Ok(())
}

fn phase_runtime_command(error_review_present: bool) -> Vec<&'static str> {
    let mut command = vec![
        "cargo",
        "test",
        "--locked",
        "-p",
        "rivetlua-runtime",
        "--test",
        "official_chunk_runtime",
        "p17_export_open_call_runtime_semantics",
        "--",
    ];
    if error_review_present {
        command.push("--exact");
    }
    command.extend(["--nocapture", "--test-threads=1"]);
    command
}

fn phase_runtime_command_matches(
    runtime: &StrictJsonValue,
    error_review_present: bool,
) -> Result<bool, String> {
    Ok(strings(runtime, "command")? == phase_runtime_command(error_review_present))
}

fn phase_related_record(regression: &StrictJsonValue) -> Result<&StrictJsonValue, String> {
    let related = array(regression, "related")?;
    if related.len() != 1 {
        return Err("P17 phase 需精確一項 runtime 語意回歸".into());
    }
    let runtime = &related[0];
    object(
        runtime,
        &[
            "command",
            "cwd",
            "exit_code",
            "matched",
            "passed",
            "failed",
            "ignored",
            "log_path",
            "log_sha256",
            "source_inputs",
            "selectors",
        ],
    )?;
    Ok(runtime)
}

fn phase_regression_sources(
    root: &Path,
    value: &StrictJsonValue,
    producer_before_native: Option<&Path>,
) -> Result<(), String> {
    let sources = array(value, "source_inputs")?;
    let expected = [
        PHASE_SOURCES[0].0,
        PHASE_SOURCES[1].0,
        "crates/rivetlua-runtime/tests/official_chunk_runtime.rs",
    ];
    if sources.len() != expected.len() {
        return Err("P17 phase 回歸 source input 數不符".into());
    }
    for (item, relative) in sources.iter().zip(expected) {
        let expected_path = root.join(relative).display().to_string();
        if relative == PRODUCER_NATIVE_PATH && producer_before_native.is_some() {
            let snapshot = producer_before_native.ok_or("P17 producer native 前態缺失")?;
            object(item, &["path", "sha256"])?;
            sha(snapshot, PRODUCER_NATIVE_BEFORE_SHA)?;
            if string(item, "path")? != expected_path
                || string(item, "sha256")? != PRODUCER_NATIVE_BEFORE_SHA
            {
                return Err("P17 phase 舊 exporter regression native endpoint 不符".into());
            }
        } else if input(item)?.path != expected_path {
            return Err("P17 phase 回歸 source input 路徑不符".into());
        }
    }
    Ok(())
}

fn phase_regression_log(body: &str) -> Result<(), String> {
    let names = [
        "p17_native_open_call_pending_values_roundtrip",
        "p17_official_main_chunk_export",
    ];
    let (counts, named) = parse_named_log_with_filter(body, &names, true)?;
    if counts.matched != 2
        || counts.passed != 2
        || counts.failed != 0
        || counts.ignored != 0
        || named.values().any(|status| *status != "ok")
    {
        return Err("P17 phase 回歸 log 非兩具名真 PASS".into());
    }
    Ok(())
}

fn phase_runtime_regression_log(body: &str) -> Result<(), String> {
    let names = ["p17_export_open_call_runtime_semantics"];
    let (counts, named) = parse_named_log_with_filter(body, &names, true)?;
    if counts.matched != 1
        || counts.passed != 1
        || counts.failed != 0
        || counts.ignored != 0
        || named.values().any(|status| *status != "ok")
    {
        return Err("P17 phase runtime 語意回歸 log 非具名真 PASS".into());
    }
    Ok(())
}

fn validate_review(
    root: &Path,
    evidence: &Path,
    historical_tooling: Option<&Path>,
) -> Result<report::Input, String> {
    let path = evidence.join("p17-b03-source-impact-review.json");
    let value =
        StrictJsonParser::parse(&fs::read_to_string(&path).map_err(|error| error.to_string())?)?;
    object(
        &value,
        &[
            "schema",
            "b01_report_sha256",
            "b02_report_sha256",
            "changes",
            "regression",
            "review_note",
        ],
    )?;
    if string(&value, "schema")? != "rivetlua-b03-source-impact-v1"
        || string(&value, "b01_report_sha256")? != B01_SHA
        || string(&value, "b02_report_sha256")? != B02_SHA
        || string(&value, "review_note")?.trim().len() < 8
    {
        return Err("P17 B03 source-impact 審查主鍵不符".into());
    }
    let changes = array(&value, "changes")?;
    if changes.len() != 3 {
        return Err("P17 B03 source-impact 差異數不符".into());
    }
    let baseline = evidence.join("p17-b02-tooling-baseline");
    for (index, change) in changes.iter().enumerate() {
        object(
            change,
            &[
                "path",
                "before_sha256",
                "after_sha256",
                "diff_path",
                "diff_sha256",
            ],
        )?;
        let (relative, snapshot, diff_name) = TOOLING[index];
        let current = root.join(relative);
        let effective = historical_tooling
            .map(|baseline| baseline.join(snapshot))
            .unwrap_or_else(|| current.clone());
        let before = baseline.join(snapshot);
        let diff = evidence.join(diff_name);
        sha(&before, BASELINE_SHAS[index])?;
        if string(change, "path")? != relative
            || string(change, "before_sha256")? != BASELINE_SHAS[index]
            || string(change, "after_sha256")? != manifest::sha256(&effective)?
            || string(change, "diff_path")? != diff.display().to_string()
        {
            return Err(format!("P17 B03 source-impact identity 不符：{relative}"));
        }
        sha(&diff, string(change, "diff_sha256")?)?;
        let output = verified_review_git(root)?
            .args(["diff", "--no-index", "--no-ext-diff", "--no-textconv", "--"])
            .arg(&before)
            .arg(&effective)
            .output()
            .map_err(|error| error.to_string())?;
        let stored = fs::read(&diff).map_err(|error| error.to_string())?;
        let same_diff = if historical_tooling.is_some() {
            b02::canonical_diff_headers(&output.stdout)? == b02::canonical_diff_headers(&stored)?
        } else {
            output.stdout == stored
        };
        if output.status.code() != Some(1) || !same_diff {
            return Err(format!(
                "P17 B03 source-impact 原始 diff bytes 不符：{relative}"
            ));
        }
    }
    let regression = field(&value, "regression")?;
    object(
        regression,
        &[
            "command",
            "cwd",
            "exit_code",
            "matched",
            "passed",
            "failed",
            "ignored",
            "log_path",
            "log_sha256",
        ],
    )?;
    let command = strings(regression, "command")?;
    let expected = [
        "cargo",
        "test",
        "--locked",
        "-p",
        "rivetlua-xtask",
        "--bin",
        "rivetlua-xtask",
        "p17_b03_reuse",
        "--",
        "--ignored",
        "--test-threads=1",
    ];
    let log = evidence.join("p17-b03-reuse-regression.log");
    if command != expected
        || string(regression, "cwd")? != root.display().to_string()
        || integer(regression, "exit_code")? != 0
        || integer(regression, "matched")? != 1
        || integer(regression, "passed")? != 1
        || integer(regression, "failed")? != 0
        || integer(regression, "ignored")? != 0
        || string(regression, "log_path")? != log.display().to_string()
    {
        return Err("P17 B03 reuse 欄位不符".into());
    }
    sha(&log, string(regression, "log_sha256")?)?;
    let log_body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
    if !log_body.contains("test p17::b03::tests::p17_b03_reuse ... ok")
        && !log_body.contains("test p17_b03_reuse ... ok")
    {
        return Err("P17 B03 reuse 真具名結果缺失".into());
    }
    if !log_body.contains("test result: ok. 1 passed; 0 failed; 0 ignored;") {
        return Err("P17 B03 reuse summary 不符".into());
    }
    report::Input::from_path(&path)
}

fn b01_check<'a>(
    value: &'a StrictJsonValue,
    profile: &str,
    operation: &str,
) -> Result<&'a StrictJsonValue, String> {
    let checks = array(value, "checks")?;
    let mut matching = checks.iter().filter(|check| {
        string(check, "profile").ok() == Some(profile)
            && string(check, "operation").ok() == Some(operation)
    });
    let check = matching
        .next()
        .ok_or_else(|| format!("P17 B03 B01 缺 {profile}/{operation}"))?;
    if matching.next().is_some() {
        return Err("P17 B03 B01 重複 artifact check".into());
    }
    Ok(check)
}

struct B01Artifacts {
    binary: report::Input,
    library: report::Input,
    grant: report::Input,
    suite: PathBuf,
    native_flags: Vec<String>,
}

fn b01_artifacts(root: &Path, profile: &str) -> Result<B01Artifacts, String> {
    let value = StrictJsonParser::parse(
        &fs::read_to_string(root.join("target/rivetlua-reports/gate-P17-B01.json"))
            .map_err(|error| error.to_string())?,
    )?;
    let binary_check = b01_check(&value, profile, "cargo-cli-build")?;
    let library_check = b01_check(&value, profile, "cargo-capi-build")?;
    let driver_check = b01_check(&value, profile, "cc-capi-driver")?;
    let load_check = b01_check(&value, profile, "cli-native-load")?;
    let binary = input(
        array(binary_check, "inputs")?
            .first()
            .ok_or("P17 B03 B01 binary input 缺失")?,
    )?;
    let library = input(
        array(library_check, "inputs")?
            .first()
            .ok_or("P17 B03 B01 library input 缺失")?,
    )?;
    let load_inputs = array(load_check, "inputs")?;
    let grant = input(load_inputs.get(1).ok_or("P17 B03 B01 grant input 缺失")?)?;
    let suite = PathBuf::from(string(load_check, "cwd")?);
    if !suite.is_dir() || !suite.join("all.lua").is_file() {
        return Err("P17 B03 B01 suite 缺失".into());
    }
    let expected_suite_sha = manifest::PROFILES
        .iter()
        .find(|item| item.name == profile)
        .ok_or("P17 B03 profile 缺失")?
        .all_lua_sha256;
    sha(&suite.join("all.lua"), expected_suite_sha)?;
    let command = strings(driver_check, "command")?;
    let start = command
        .iter()
        .position(|part| part == "-Wl,-export_dynamic")
        .ok_or("P17 B03 B01 link flags 缺失")?
        + 1;
    let end = command
        .iter()
        .position(|part| part == "-o")
        .ok_or("P17 B03 B01 output flag 缺失")?;
    if start >= end || !command.contains(&format!("-Wl,-force_load,{}", library.path)) {
        return Err("P17 B03 B01 link flags 不符".into());
    }
    Ok(B01Artifacts {
        binary,
        library,
        grant,
        suite,
        native_flags: command[start..end].to_vec(),
    })
}

fn source_paths(root: &Path) -> Result<Vec<PathBuf>, String> {
    let mut paths = runner::related_sources(root)?;
    for relative in [
        "xtask/src/p17/b02.rs",
        "xtask/src/p17/b03.rs",
        "tests/p17/internal/mapping.json",
        "tests/p17/internal/cases.json",
        "crates/rivetlua-capi/tests/p17_internal_replacements.rs",
        "crates/rivetlua-capi/tests/native_bridge.rs",
        "crates/rivetlua-capi/tests/external_string.rs",
        "tests/p17/stress/lifecycle.c",
        "tests/p17/stress/platform.c",
        "tests/p17/stress/platform.lua",
        "tests/p17/stress/fuzz-corpus.json",
        "tests/p17/stress/platform-capabilities.json",
        "crates/rivetlua-capi/tests/p17_lifecycle.rs",
        "crates/rivetlua-capi/tests/p17_fuzz.rs",
    ] {
        paths.push(root.join(relative));
    }
    paths.sort();
    paths.dedup();
    Ok(paths)
}

fn phase_source_paths_with_ctrl(
    root: &Path,
    include_host_test: bool,
    include_error_test: bool,
    include_console_test: bool,
    include_assert_warning_tests: bool,
    include_exit_tests: bool,
    include_ctrl: bool,
) -> Result<Vec<PathBuf>, String> {
    let mut paths = source_paths(root)?;
    if include_host_test {
        paths.push(root.join(HOST_CHANGES[2]));
    }
    if include_error_test {
        paths.push(root.join(ERROR_NEW_TEST));
    }
    if include_console_test {
        paths.push(root.join(CONSOLE_NEW_TEST));
    }
    if include_assert_warning_tests {
        paths.push(root.join(ASSERT_NEW_TEST));
        paths.extend(WARNING_NEW_TESTS.iter().map(|relative| root.join(relative)));
        paths.push(root.join("crates/rivetlua-capi/tests/warning_callback.rs"));
        paths.push(root.join("crates/rivetlua-runtime/tests/official_chunk_runtime.rs"));
    }
    if include_exit_tests {
        paths.extend(EXIT_NEW_TESTS.iter().map(|relative| root.join(relative)));
        paths.push(root.join(CONSOLE_CLI_TEST_PATH));
        paths.push(root.join(EXIT_PUBLIC_REPL_TEST_PATH));
        paths.push(root.join(EXIT_CLI_BINARY_TEST_PATH));
        paths.push(root.join(EXIT_CLI_VERSION_TEST_PATH));
        paths.push(root.join(EXIT_CLI_DIAGNOSTICS_TEST_PATH));
        paths.push(root.join(EXIT_WARN_TEST_PATH));
        if include_ctrl {
            paths.push(root.join(EXIT_CTRL_BIN_PATH));
            paths.push(root.join(EXIT_CTRL_TEST_PATH));
        }
    }
    paths.sort();
    paths.dedup();
    Ok(paths)
}

fn phase_source_paths_with_gc(
    root: &Path,
    include_host_test: bool,
    include_error_test: bool,
    include_console_test: bool,
    include_assert_warning_tests: bool,
    include_exit_tests: bool,
    include_ctrl: bool,
    include_gc: bool,
    include_producer: bool,
    include_debug_vm: bool,
    include_debug_hook: bool,
    include_final: bool,
    include_final_debug: bool,
) -> Result<Vec<PathBuf>, String> {
    let mut paths = phase_source_paths_with_ctrl(
        root, include_host_test, include_error_test, include_console_test,
        include_assert_warning_tests, include_exit_tests, include_ctrl,
    )?;
    if include_gc {
        paths.push(root.join(GC_TEST_PATH));
    }
    if include_producer {
        paths.push(root.join(PRODUCER_SDK_TEST_PATH));
    }
    if include_debug_vm {
        paths.push(root.join(DEBUG_VM_TEST_PATH));
    }
    if include_debug_hook {
        paths.push(root.join(DEBUG_HOOK_TEST_PATH));
    }
    if include_final {
        paths.push(root.join(FINAL_COUNT_TEST_PATH));
    }
    if include_final_debug {
        paths.push(root.join(FINAL_DEBUG_SUCCESSOR_TEST_PATH));
    }
    paths.sort();
    paths.dedup();
    Ok(paths)
}

fn phase_source_paths(
    root: &Path,
    include_host_test: bool,
    include_error_test: bool,
    include_console_test: bool,
    include_assert_warning_tests: bool,
    include_exit_tests: bool,
) -> Result<Vec<PathBuf>, String> {
    phase_source_paths_with_ctrl(
        root, include_host_test, include_error_test, include_console_test,
        include_assert_warning_tests, include_exit_tests, false,
    )
}

fn work_dir(evidence: &Path, label: &str) -> Result<PathBuf, String> {
    let stamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|error| error.to_string())?
        .as_nanos();
    let work = evidence.join(format!("{label}-{}-{stamp}", std::process::id()));
    fs::create_dir(&work).map_err(|error| error.to_string())?;
    Ok(work)
}

#[derive(Clone)]
pub(super) struct BuildProof {
    profile: String,
    target: String,
    command: Vec<String>,
    cwd: String,
    exit_code: i32,
    log: report::Input,
    executable: report::Input,
}

impl BuildProof {
    fn json(&self) -> String {
        format!(
            "{{\"profile\":{},\"target\":{},\"command\":[{}],\"cwd\":{},\"exit_code\":{},\"log\":{},\"executable\":{}}}",
            report::q(&self.profile),
            report::q(&self.target),
            json_strings(&self.command),
            report::q(&self.cwd),
            self.exit_code,
            self.log.json(),
            self.executable.json()
        )
    }
}

pub(super) struct Evidence {
    corpus: report::Input,
    capabilities: report::Input,
    review: report::Input,
    builds: Vec<BuildProof>,
}

impl Evidence {
    pub(super) fn json(&self) -> String {
        let builds = self
            .builds
            .iter()
            .map(BuildProof::json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"corpus\":{},\"capabilities\":{},\"source_impact_review\":{},\"builds\":[{builds}]}}",
            self.corpus.json(),
            self.capabilities.json(),
            self.review.json()
        )
    }
}

struct PhaseCliBuild {
    profile: String,
    command: Vec<String>,
    cwd: String,
    exit_code: i32,
    log: report::Input,
    artifact_path: String,
    artifact_sha256: String,
    executable: report::Input,
    post_sha256: String,
    producer: report::Input,
    host_sources: Option<[report::Input; 2]>,
    error_source: Option<report::Input>,
    console_sources: Option<Vec<report::Input>>,
    assert_warning_sources: Option<Vec<report::Input>>,
    producer_update_sources: Option<([report::Input; 2], [report::Input; 2])>,
    debug_vm_sources: Option<(report::Input, report::Input)>,
    final_source_sources: Option<(Vec<report::Input>, Vec<report::Input>)>,
}

impl PhaseCliBuild {
    fn json(&self) -> String {
        let host_sources = self
            .host_sources
            .as_ref()
            .map_or_else(String::new, |sources| {
                format!(
                    ",\"host_sources\":[{},{}]",
                    sources[0].json(),
                    sources[1].json()
                )
            });
        let error_source = self
            .error_source
            .as_ref()
            .map_or_else(String::new, |source| {
                format!(",\"error_source\":{}", source.json())
            });
        let console_sources = self
            .console_sources
            .as_ref()
            .map_or_else(String::new, |sources| {
                format!(
                    ",\"console_sources\":[{}]",
                    sources
                        .iter()
                        .map(report::Input::json)
                        .collect::<Vec<_>>()
                        .join(",")
                )
            });
        let assert_warning_sources =
            self.assert_warning_sources
                .as_ref()
                .map_or_else(String::new, |sources| {
                    format!(
                        ",\"assert_warning_sources\":[{}]",
                        sources
                            .iter()
                            .map(report::Input::json)
                            .collect::<Vec<_>>()
                            .join(",")
                    )
                });
        let producer_update_sources = self.producer_update_sources.as_ref().map_or_else(
            String::new,
            |(before, after)| format!(
                ",\"producer_update_sources\":{{\"before\":[{},{}],\"after\":[{},{}]}}",
                before[0].json(), before[1].json(), after[0].json(), after[1].json(),
            ),
        );
        let debug_vm_sources = self.debug_vm_sources.as_ref().map_or_else(
            String::new,
            |(before, after)| format!(
                ",\"debug_vm_sources\":{{\"before\":{},\"after\":{}}}",
                before.json(), after.json(),
            ),
        );
        let final_source_sources = self.final_source_sources.as_ref().map_or_else(
            String::new,
            |(before, after)| format!(
                ",\"final_source_sources\":{{\"before\":[{}],\"after\":[{}]}}",
                before.iter().map(report::Input::json).collect::<Vec<_>>().join(","),
                after.iter().map(report::Input::json).collect::<Vec<_>>().join(","),
            ),
        );
        format!(
            "{{\"profile\":{},\"command\":[{}],\"cwd\":{},\"exit_code\":{},\"log\":{},\"artifact_path\":{},\"artifact_sha256\":{},\"executable\":{},\"post_sha256\":{},\"producer\":{}{host_sources}{error_source}{console_sources}{assert_warning_sources}{producer_update_sources}{debug_vm_sources}{final_source_sources}}}",
            report::q(&self.profile),
            json_strings(&self.command),
            report::q(&self.cwd),
            self.exit_code,
            self.log.json(),
            report::q(&self.artifact_path),
            report::q(&self.artifact_sha256),
            self.executable.json(),
            report::q(&self.post_sha256),
            self.producer.json(),
        )
    }
}

pub(super) struct PhaseEvidence {
    review: report::Input,
    host_review: Option<report::Input>,
    error_review: Option<report::Input>,
    console_review: Option<report::Input>,
    assert_warning_review: Option<report::Input>,
    exit_review: Option<report::Input>,
    host_entry_review: Option<report::Input>,
    gc_review: Option<report::Input>,
    producer_update_review: Option<report::Input>,
    debug_vm_review: Option<report::Input>,
    debug_hook_review: Option<report::Input>,
    final_source_review: Option<report::Input>,
    builds: Vec<PhaseCliBuild>,
}

impl PhaseEvidence {
    pub(super) fn requires_platform(&self) -> bool {
        self.assert_warning_review.is_some()
    }

    pub(super) fn json(&self) -> String {
        let host_review = self.host_review.as_ref().map_or_else(String::new, |input| {
            format!(",\"host_source_impact_review\":{}", input.json())
        });
        let error_review = self
            .error_review
            .as_ref()
            .map_or_else(String::new, |input| {
                format!(",\"error_position_source_impact_review\":{}", input.json())
            });
        let console_review = self
            .console_review
            .as_ref()
            .map_or_else(String::new, |input| {
                format!(",\"debug_console_source_impact_review\":{}", input.json())
            });
        let assert_warning_review = self
            .assert_warning_review
            .as_ref()
            .map_or_else(String::new, |input| {
                format!(",\"assert_warning_source_impact_review\":{}", input.json())
            });
        let exit_review = self.exit_review.as_ref().map_or_else(String::new, |input| {
            format!(",\"exit_source_impact_review\":{}", input.json())
        });
        let host_entry_review = self.host_entry_review.as_ref().map_or_else(String::new, |input| {
            format!(",\"host_entry_source_impact_review\":{}", input.json())
        });
        let gc_review = self.gc_review.as_ref().map_or_else(String::new, |input| {
            format!(",\"gc_source_impact_review\":{}", input.json())
        });
        let producer_update_review = self.producer_update_review.as_ref().map_or_else(
            String::new,
            |input| format!(",\"producer_source_impact_review\":{}", input.json()),
        );
        let debug_vm_review = self.debug_vm_review.as_ref().map_or_else(
            String::new,
            |input| format!(",\"debug_vm_source_impact_review\":{}", input.json()),
        );
        let debug_hook_review = self.debug_hook_review.as_ref().map_or_else(
            String::new,
            |input| format!(",\"debug_hook_source_impact_review\":{}", input.json()),
        );
        let final_source_review = self.final_source_review.as_ref().map_or_else(
            String::new,
            |input| format!(",\"final_source_impact_review\":{}", input.json()),
        );
        format!(
            "{{\"source_impact_review\":{},\"cli_builds\":[{}]{host_review}{error_review}{console_review}{assert_warning_review}{exit_review}{host_entry_review}{gc_review}{producer_update_review}{debug_vm_review}{debug_hook_review}{final_source_review}}}",
            self.review.json(),
            self.builds
                .iter()
                .map(PhaseCliBuild::json)
                .collect::<Vec<_>>()
                .join(","),
        )
    }
}

fn rust_build_command(profile: &str) -> Vec<String> {
    let mut args = vec![
        "cargo",
        "test",
        "--locked",
        "-p",
        "rivetlua-capi",
        "--test",
        "p17_lifecycle",
        "--test",
        "p17_fuzz",
        "--no-run",
        "--message-format=json-render-diagnostics",
    ]
    .into_iter()
    .map(str::to_owned)
    .collect::<Vec<_>>();
    if profile == PROFILES[0] {
        args.extend(["--features".into(), "lua55".into()]);
    } else {
        args.extend([
            "--no-default-features".into(),
            "--features".into(),
            "lua54".into(),
        ]);
    }
    args
}

fn rust_artifacts(log: &str) -> Result<BTreeMap<String, PathBuf>, String> {
    let mut found = BTreeMap::new();
    for line in log.lines() {
        let Ok(value) = StrictJsonParser::parse(line) else {
            continue;
        };
        if value.get("reason").and_then(StrictJsonValue::as_str) != Some("compiler-artifact") {
            continue;
        }
        let target = value.get("target").ok_or("P17 B03 Cargo target 缺失")?;
        let Some(name) = target.get("name").and_then(StrictJsonValue::as_str) else {
            continue;
        };
        if !["p17_lifecycle", "p17_fuzz"].contains(&name) {
            continue;
        }
        let kinds = target
            .get("kind")
            .and_then(StrictJsonValue::as_array)
            .ok_or("P17 B03 Cargo kind 缺失")?;
        if !kinds.iter().any(|item| item.as_str() == Some("test")) {
            return Err("P17 B03 Cargo 非 test artifact".into());
        }
        let path = value
            .get("executable")
            .and_then(StrictJsonValue::as_str)
            .ok_or("P17 B03 Cargo test executable 缺失")?;
        if found.insert(name.to_owned(), PathBuf::from(path)).is_some() {
            return Err("P17 B03 Cargo 重複 test artifact".into());
        }
    }
    if found.len() != 2 {
        return Err("P17 B03 Cargo test artifact 數不符".into());
    }
    Ok(found)
}

fn snapshot_build(
    profile: &str,
    target: &str,
    command: &[String],
    result: &ProcessResult,
    source: &Path,
    work: &Path,
    target_dir: &Path,
) -> Result<BuildProof, String> {
    if result.timed_out || result.exit_code != Some(0) {
        return Err(format!(
            "P17 B03 {target} build 失敗；log={}",
            result.log.path
        ));
    }
    let canonical = fs::canonicalize(source).map_err(|error| error.to_string())?;
    if !canonical.starts_with(target_dir) {
        return Err("P17 B03 artifact 不在共用 target".into());
    }
    let destination = work.join(format!("{profile}-{target}"));
    fs::copy(&canonical, &destination).map_err(|error| error.to_string())?;
    let mut mode = fs::metadata(&destination)
        .map_err(|error| error.to_string())?
        .permissions();
    mode.set_mode(0o555);
    fs::set_permissions(&destination, mode).map_err(|error| error.to_string())?;
    Ok(BuildProof {
        profile: profile.into(),
        target: target.into(),
        command: command.to_vec(),
        cwd: result.cwd.clone(),
        exit_code: 0,
        log: result.log.clone(),
        executable: report::Input::from_path(&destination)?,
    })
}

fn build_rust(
    root: &Path,
    work: &Path,
    profile: &str,
    target_dir: &Path,
) -> Result<Vec<BuildProof>, String> {
    let command = rust_build_command(profile);
    let result = invoke(
        root,
        command.clone(),
        &work.join(format!("build-{profile}-rust.log")),
        BUILD_TIMEOUT,
        None,
    )?;
    if result.timed_out || result.exit_code != Some(0) {
        return Err(format!(
            "P17 B03 Rust build 失敗／逾時；log={}",
            result.log.path
        ));
    }
    let artifacts = rust_artifacts(&result.body)?;
    ["p17_lifecycle", "p17_fuzz"]
        .iter()
        .map(|name| {
            snapshot_build(
                profile,
                name,
                &command,
                &result,
                artifacts.get(*name).ok_or("P17 B03 Cargo artifact 缺失")?,
                work,
                target_dir,
            )
        })
        .collect()
}

fn build_c(
    root: &Path,
    work: &Path,
    profile: manifest::Profile,
    target: &str,
    source: &Path,
    library: Option<&B01Artifacts>,
    native_flags: &[String],
    target_dir: &Path,
) -> Result<BuildProof, String> {
    let destination = work.join(format!("{}-{target}", profile.name));
    let command = if let Some(artifact) = library {
        runner::driver_build_command(
            root,
            profile,
            source,
            Path::new(&artifact.library.path),
            native_flags,
            &destination,
        )
    } else {
        vec![
            "cc".into(),
            "-std=c11".into(),
            "-Wall".into(),
            "-Wextra".into(),
            "-Werror".into(),
            "-Wno-error=deprecated-declarations".into(),
            source.display().to_string(),
            "-o".into(),
            destination.display().to_string(),
        ]
    };
    let result = invoke(
        root,
        command.clone(),
        &work.join(format!("build-{}-{target}.log", profile.name)),
        BUILD_TIMEOUT,
        None,
    )?;
    if result.timed_out || result.exit_code != Some(0) {
        return Err(format!(
            "P17 B03 C build 失敗／逾時；log={}",
            result.log.path
        ));
    }
    let canonical = fs::canonicalize(&destination).map_err(|error| error.to_string())?;
    if !canonical.starts_with(target_dir) && !canonical.starts_with(work) {
        return Err("P17 B03 C artifact 越界".into());
    }
    let mut mode = fs::metadata(&destination)
        .map_err(|error| error.to_string())?
        .permissions();
    mode.set_mode(0o555);
    fs::set_permissions(&destination, mode).map_err(|error| error.to_string())?;
    Ok(BuildProof {
        profile: profile.name.into(),
        target: target.into(),
        command,
        cwd: root.display().to_string(),
        exit_code: 0,
        log: result.log,
        executable: report::Input::from_path(&destination)?,
    })
}

fn case_check(
    spec: CaseSpec,
    profile: &str,
    operation: &'static str,
    execution_path: &'static str,
    result: &ProcessResult,
    build: Option<&BuildProof>,
    marker: Option<&StrictJsonValue>,
    named_outcome: Option<&str>,
    issue: Option<&str>,
) -> report::Check {
    let observed_pass =
        named_outcome.is_none_or(|outcome| outcome == "ok") && marker.is_some() && issue.is_none();
    let ok = !result.timed_out && result.exit_code == Some(0) && observed_pass;
    let diagnostic = if let Some(issue) = issue {
        issue.to_owned()
    } else if result.timed_out {
        "P17 B03 TIMEOUT".into()
    } else if !ok {
        let reproduction = result
            .body
            .lines()
            .find(|line| line.contains("P17_B03_FAILURE ") && line.contains(spec.id))
            .unwrap_or("");
        format!(
            "P17 B03 body 失敗：exit={:?}, named={named_outcome:?} {reproduction}",
            result.exit_code,
        )
    } else {
        canonical_json(marker.expect("checked marker"))
    };
    let mut check = report::Check::pending(spec.facet, Some(profile), &diagnostic);
    check.case_id = spec.case.into();
    check.operation = operation;
    check.execution_path = execution_path;
    check.command = result.command.clone();
    check.cwd = result.cwd.clone();
    check.exit_code = result.exit_code;
    check.matched = u32::from(named_outcome.is_some() || marker.is_some());
    check.passed = u32::from(observed_pass);
    check.ignored = u32::from(named_outcome == Some("ignored"));
    check.failed = u32::from(!observed_pass && named_outcome != Some("ignored"));
    check.status = if ok { "PASS" } else { "FAIL" };
    check.log = Some(result.log.clone());
    check.environment = result.environment.clone();
    if let Some(build) = build {
        check
            .inputs
            .extend([build.executable.clone(), build.log.clone()]);
    }
    check
}

fn invoke_body(
    cwd: &Path,
    argv: Vec<String>,
    log: &Path,
    grant: Option<&Path>,
) -> Result<ProcessResult, String> {
    match invoke(cwd, argv.clone(), log, BODY_TIMEOUT, grant) {
        Ok(result) => Ok(result),
        Err(error) => {
            fs::write(log, &error).map_err(|write_error| {
                format!("P17 B03 launch/log 皆失敗：{error}；{write_error}")
            })?;
            Ok(ProcessResult {
                command: argv,
                cwd: cwd.display().to_string(),
                environment: if let Some(grant) = grant {
                    runner::effective_native_environment(grant)
                } else {
                    runner::effective_no_native_environment()
                },
                exit_code: None,
                timed_out: false,
                log: report::Input::from_path(log)?,
                body: error,
            })
        }
    }
}

fn push_group(
    report: &mut report::Report,
    registry: &Registry,
    profile: &str,
    result: &ProcessResult,
    build: &BuildProof,
    names: &[&str],
    operation: &'static str,
    path: &'static str,
) {
    let parsed = parse_named_log(&result.body, names);
    let records = marker_records(&result.body, names, false);
    for name in names {
        let spec = CASES
            .iter()
            .copied()
            .find(|case| case.id == *name)
            .expect("fixed B03 case");
        let outcome = parsed
            .as_ref()
            .ok()
            .and_then(|(_, items)| items.get(*name).copied());
        let marker = records.as_ref().ok().and_then(|items| items.get(*name));
        let issue = parsed.as_ref().err().or_else(|| records.as_ref().err());
        let validation = marker.map(|value| validate_record(value, spec, profile, registry, false));
        let diagnostic = issue.map(String::as_str).or_else(|| {
            validation
                .as_ref()
                .and_then(|result| result.as_ref().err().map(String::as_str))
        });
        report.checks.push(case_check(
            spec,
            profile,
            operation,
            path,
            result,
            Some(build),
            marker,
            outcome,
            diagnostic,
        ));
    }
}

fn push_marker_group(
    report: &mut report::Report,
    registry: &Registry,
    profile: &str,
    result: &ProcessResult,
    build: Option<&BuildProof>,
    names: &[&str],
    operation: &'static str,
    path: &'static str,
) {
    let records = marker_records(&result.body, names, false);
    for name in names {
        let spec = CASES
            .iter()
            .copied()
            .find(|case| case.id == *name)
            .expect("fixed B03 case");
        let marker = records.as_ref().ok().and_then(|items| items.get(*name));
        let validation = marker.map(|value| validate_record(value, spec, profile, registry, false));
        let issue = records.as_ref().err().map(String::as_str).or_else(|| {
            validation
                .as_ref()
                .and_then(|result| result.as_ref().err().map(String::as_str))
        });
        report.checks.push(case_check(
            spec, profile, operation, path, result, build, marker, None, issue,
        ));
    }
}

pub(super) fn run(root: &Path, report: &mut report::Report) -> Result<(), String> {
    let environment = runner::environment(root)?;
    report.target = environment.target.clone();
    report.environment = runner::related_environment(&environment);
    report.toolchain = runner::toolchain_identity()?;
    let b01 = root.join("target/rivetlua-reports/gate-P17-B01.json");
    let b02_path = root.join("target/rivetlua-reports/gate-P17-B02.json");
    report::validate_b01_for_b03(root, &b01)?;
    b02::validate_b02_for_b03(root, &b02_path)?;
    let review = validate_review(root, &environment.evidence_dir, None)?;
    let registry = parse_registry(root, &environment.target)?;
    for path in source_paths(root)? {
        report.input(&path)?;
    }
    for family in &registry.families {
        for fixture in &family.fixtures {
            report.input(Path::new(&fixture.path))?;
        }
    }
    report.dependencies.extend([
        report::Input::from_path(&b01)?,
        report::Input::from_path(&b02_path)?,
        review.clone(),
    ]);
    let work = work_dir(&environment.evidence_dir, "b03")?;
    let mut builds = Vec::new();
    for profile in manifest::PROFILES {
        let artifact = b01_artifacts(root, profile.name)?;
        let rust = build_rust(root, &work, profile.name, &environment.target_dir)?;
        let lifecycle_c = build_c(
            root,
            &work,
            profile,
            "p17_lifecycle_c",
            &root.join("tests/p17/stress/lifecycle.c"),
            Some(&artifact),
            &artifact.native_flags,
            &environment.target_dir,
        )?;
        let platform_c = build_c(
            root,
            &work,
            profile,
            "p17_platform_c",
            &root.join("tests/p17/stress/platform.c"),
            None,
            &[],
            &environment.target_dir,
        )?;
        let lifecycle_rust = rust
            .iter()
            .find(|item| item.target == "p17_lifecycle")
            .ok_or("P17 B03 lifecycle artifact 缺失")?;
        let fuzz_rust = rust
            .iter()
            .find(|item| item.target == "p17_fuzz")
            .ok_or("P17 B03 fuzz artifact 缺失")?;
        let c_result = invoke_body(
            root,
            vec![lifecycle_c.executable.path.clone(), profile.name.into()],
            &work.join(format!("run-{}-lifecycle-c.log", profile.name)),
            None,
        )?;
        push_marker_group(
            report,
            &registry,
            profile.name,
            &c_result,
            Some(&lifecycle_c),
            &["p17_allocator_failure", "p17_nested_callback"],
            "b03-lifecycle-c",
            "capi-independent-host",
        );
        let lifecycle_result = invoke_body(
            root,
            vec![
                lifecycle_rust.executable.path.clone(),
                "--nocapture".into(),
                "--test-threads=1".into(),
            ],
            &work.join(format!("run-{}-lifecycle-rust.log", profile.name)),
            None,
        )?;
        push_group(
            report,
            &registry,
            profile.name,
            &lifecycle_result,
            lifecycle_rust,
            &["p17_stress_gc_long_run", "p17_stress_coroutine_debug"],
            "b03-lifecycle-rust",
            "capi-public",
        );
        let fuzz_result = invoke_body(
            root,
            vec![
                fuzz_rust.executable.path.clone(),
                "--nocapture".into(),
                "--test-threads=1".into(),
            ],
            &work.join(format!("run-{}-fuzz-rust.log", profile.name)),
            None,
        )?;
        push_group(
            report,
            &registry,
            profile.name,
            &fuzz_result,
            fuzz_rust,
            &[
                "p17_fuzz_parser",
                "p17_fuzz_rvlu",
                "p17_fuzz_official_chunk",
            ],
            "b03-fuzz-rust",
            "capi-public",
        );
        let platform_lua = root.join("tests/p17/stress/platform.lua");
        let platform_result = invoke_body(
            &root.join(profile.suite),
            vec![
                artifact.binary.path.clone(),
                platform_lua.display().to_string(),
            ],
            &work.join(format!("run-{}-platform-cli.log", profile.name)),
            None,
        )?;
        push_marker_group(
            report,
            &registry,
            profile.name,
            &platform_result,
            None,
            &["p17_platform_cli"],
            "b03-platform-cli",
            "cli-rust-vm",
        );
        let platform_c_result = invoke_body(
            root,
            vec![platform_c.executable.path.clone(), profile.name.into()],
            &work.join(format!("run-{}-platform-c.log", profile.name)),
            None,
        )?;
        push_marker_group(
            report,
            &registry,
            profile.name,
            &platform_c_result,
            Some(&platform_c),
            &["p17_platform_c"],
            "b03-platform-c",
            "c-platform",
        );
        for check in report
            .checks
            .iter_mut()
            .filter(|check| check.profile.as_deref() == Some(profile.name))
        {
            if check.operation == "b03-lifecycle-c" {
                check.inputs.push(artifact.library.clone());
            }
            if check.operation == "b03-platform-cli" {
                check.inputs.extend([
                    artifact.binary.clone(),
                    report::Input::from_path(&platform_lua)?,
                ]);
            }
            if check.operation == "b03-fuzz-rust" {
                check.inputs.push(registry.corpus.clone());
                for family in &registry.families {
                    check.inputs.extend(family.fixtures.iter().cloned());
                }
            }
            if check.facet == "platform" {
                check.inputs.push(registry.capabilities.clone());
            }
        }
        builds.extend(rust);
        builds.extend([lifecycle_c, platform_c]);
        for build in builds.iter().filter(|build| build.profile == profile.name) {
            sha(Path::new(&build.executable.path), &build.executable.sha256)?;
            sha(Path::new(&build.log.path), &build.log.sha256)?;
        }
        sha(Path::new(&artifact.binary.path), &artifact.binary.sha256)?;
        sha(Path::new(&artifact.library.path), &artifact.library.sha256)?;
        sha(Path::new(&artifact.grant.path), &artifact.grant.sha256)?;
    }
    report.b03 = Some(Evidence {
        corpus: registry.corpus,
        capabilities: registry.capabilities,
        review,
        builds,
    });
    if report.checks.iter().any(|check| check.status != "PASS") {
        return Err("P17 B03 固定 case 有真實失敗；其餘固定 case 已執行".into());
    }
    Ok(())
}

fn receipt(path: &Path) -> Result<(), String> {
    let digest = manifest::sha256(path)?;
    let name = path
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or("P17 B03 report 名稱缺失")?;
    let recorded =
        fs::read_to_string(path.with_extension("sha256")).map_err(|error| error.to_string())?;
    if recorded != format!("{digest}  {name}\n") {
        return Err("P17 B03 report receipt 不符".into());
    }
    Ok(())
}

fn source_inputs(
    root: &Path,
    value: &StrictJsonValue,
    registry: &Registry,
    phase_view: Option<&report::PhaseSourceView>,
    phase_host_test: bool,
    phase_error_test: bool,
    phase_console_test: bool,
    phase_assert_warning_tests: bool,
    phase_exit_tests: bool,
    phase_ctrl_tests: bool,
    phase_gc_tests: bool,
    phase_producer_tests: bool,
    phase_debug_vm_tests: bool,
    phase_debug_hook_tests: bool,
    phase_final_tests: bool,
    phase_final_debug_tests: bool,
    sparse_gc_active: bool,
) -> Result<(), String> {
    let mut expected = phase_source_paths_with_gc(
        root,
        phase_host_test,
        phase_error_test,
        phase_console_test,
        phase_assert_warning_tests,
        phase_exit_tests,
        phase_ctrl_tests,
        phase_gc_tests,
        phase_producer_tests,
        phase_debug_vm_tests,
        phase_debug_hook_tests,
        phase_final_tests,
        phase_final_debug_tests,
    )?
    .into_iter()
    .map(|path| path.display().to_string())
    .collect::<BTreeSet<_>>();
    if sparse_gc_active
        && !expected.contains(&root.join(GC_MOD_PATH).display().to_string()) {
        return Err("P17 sparse GC module B03 source inventory 缺失".into());
    }
    for family in &registry.families {
        for fixture in &family.fixtures {
            expected.insert(fixture.path.clone());
        }
    }
    if let Some(view) = phase_view {
        expected.retain(|path| !view.was_absent(path));
    }
    let mut observed = BTreeSet::new();
    for item in array(value, "source_inputs")? {
        let path = if let Some(historical) = phase_view
            .map(|view| report::historical_input(item, view))
            .transpose()?
            .flatten()
        {
            historical
        } else {
            input(item)?.path
        };
        if !observed.insert(path) {
            return Err("P17 B03 重複 source input".into());
        }
    }
    if sparse_gc_active {
        sha(&root.join(GC_MOD_PATH), GC_MOD_AFTER_SHA)?;
    }
    if observed != expected {
        return Err("P17 B03 source inventory 缺失／範圍外".into());
    }
    Ok(())
}

fn report_config(
    value: &StrictJsonValue,
    environment: &runner::Environment,
    phase_view: Option<&report::PhaseSourceView>,
) -> Result<(), String> {
    let config = field(value, "configuration")?;
    object(
        config,
        &["profiles", "target", "features", "toolchain", "environment"],
    )?;
    if strings(config, "profiles")? != PROFILES
        || string(config, "target")? != environment.target
        || strings(config, "features")? != ["native-lua55", "default-lua54,native-lua54"]
        || string(config, "toolchain")? != runner::toolchain_identity()?
    {
        return Err("P17 B03 configuration 不符".into());
    }
    let expected = report::expected_environment(environment, phase_view);
    let observed = array(config, "environment")?
        .iter()
        .map(|item| {
            object(item, &["name", "value"])?;
            Ok((
                string(item, "name")?.to_owned(),
                string(item, "value")?.to_owned(),
            ))
        })
        .collect::<Result<Vec<_>, String>>()?;
    if observed != expected {
        return Err("P17 B03 environment 不符".into());
    }
    Ok(())
}

fn dependencies(value: &StrictJsonValue, expected: &[report::Input]) -> Result<(), String> {
    let entries = array(value, "dependencies")?;
    if entries.len() != expected.len() {
        return Err("P17 B03 dependencies 數不符".into());
    }
    for (item, expected) in entries.iter().zip(expected) {
        let actual = input(item)?;
        if actual.path != expected.path || actual.sha256 != expected.sha256 {
            return Err("P17 B03 dependency 不符".into());
        }
    }
    Ok(())
}

fn build_proofs(
    root: &Path,
    value: &StrictJsonValue,
    environment: &runner::Environment,
) -> Result<BTreeMap<(String, String), BuildProof>, String> {
    let entries = array(value, "builds")?;
    if entries.len() != 8 {
        return Err("P17 B03 build proof 數不符".into());
    }
    let mut builds = BTreeMap::new();
    for item in entries {
        object(
            item,
            &[
                "profile",
                "target",
                "command",
                "cwd",
                "exit_code",
                "log",
                "executable",
            ],
        )?;
        let profile = string(item, "profile")?;
        let target = string(item, "target")?;
        if !PROFILES.contains(&profile)
            || ![
                "p17_lifecycle",
                "p17_fuzz",
                "p17_lifecycle_c",
                "p17_platform_c",
            ]
            .contains(&target)
            || integer(item, "exit_code")? != 0
            || string(item, "cwd")? != root.display().to_string()
        {
            return Err("P17 B03 build identity 不符".into());
        }
        let command = strings(item, "command")?;
        let artifact = b01_artifacts(root, profile)?;
        let manifest_profile = manifest::PROFILES
            .iter()
            .copied()
            .find(|item| item.name == profile)
            .ok_or("P17 B03 build profile 缺失")?;
        let executable = input(field(item, "executable")?)?;
        let log = input(field(item, "log")?)?;
        let expected = match target {
            "p17_lifecycle" | "p17_fuzz" => rust_build_command(profile),
            "p17_lifecycle_c" => runner::driver_build_command(
                root,
                manifest_profile,
                &root.join("tests/p17/stress/lifecycle.c"),
                Path::new(&artifact.library.path),
                &artifact.native_flags,
                Path::new(&executable.path),
            ),
            _ => vec![
                "cc".into(),
                "-std=c11".into(),
                "-Wall".into(),
                "-Wextra".into(),
                "-Werror".into(),
                "-Wno-error=deprecated-declarations".into(),
                root.join("tests/p17/stress/platform.c")
                    .display()
                    .to_string(),
                "-o".into(),
                executable.path.clone(),
            ],
        };
        if command != expected
            || !Path::new(&executable.path).starts_with(&environment.evidence_dir)
            || !Path::new(&log.path).starts_with(&environment.evidence_dir)
        {
            return Err("P17 B03 build command/path 不符".into());
        }
        if target.starts_with("p17_") && !target.ends_with("_c") {
            let parsed =
                rust_artifacts(&fs::read_to_string(&log.path).map_err(|error| error.to_string())?)?;
            if !parsed.contains_key(target) {
                return Err("P17 B03 cargo artifact log 缺 test target".into());
            }
        }
        let build = BuildProof {
            profile: profile.into(),
            target: target.into(),
            command,
            cwd: root.display().to_string(),
            exit_code: 0,
            log,
            executable,
        };
        if builds
            .insert((profile.to_owned(), target.to_owned()), build)
            .is_some()
        {
            return Err("P17 B03 重複 build proof".into());
        }
    }
    Ok(builds)
}

fn validate_case_check(
    root: &Path,
    check: &StrictJsonValue,
    registry: &Registry,
    builds: &BTreeMap<(String, String), BuildProof>,
    historical_main_root: bool,
) -> Result<(String, String), String> {
    object(
        check,
        &[
            "case_id",
            "facet",
            "operation",
            "execution_path",
            "profile",
            "command",
            "cwd",
            "exit_code",
            "matched",
            "passed",
            "failed",
            "ignored",
            "status",
            "log_path",
            "log_sha256",
            "inputs",
            "environment",
            "negative_runs",
            "diagnostic",
        ],
    )?;
    let profile = string(check, "profile")?;
    if !PROFILES.contains(&profile) {
        return Err("P17 B03 check profile 範圍外".into());
    }
    let diagnostic = string(check, "diagnostic")?;
    let record = StrictJsonParser::parse(diagnostic)?;
    let logical_id = string(&record, "case_id")?;
    let spec = CASES
        .iter()
        .copied()
        .find(|spec| spec.id == logical_id)
        .ok_or("P17 B03 check case 範圍外")?;
    if string(check, "case_id")? != spec.case
        || string(check, "facet")? != spec.facet
        || string(check, "status")? != "PASS"
        || integer(check, "exit_code")? != 0
        || integer(check, "matched")? != 1
        || integer(check, "passed")? != 1
        || integer(check, "failed")? != 0
        || integer(check, "ignored")? != 0
        || !array(check, "negative_runs")?.is_empty()
    {
        return Err("P17 B03 check 身分／count 不符".into());
    }
    validate_record(&record, spec, profile, registry, historical_main_root)?;
    let (target, operation, path) = match logical_id {
        "p17_allocator_failure" | "p17_nested_callback" => (
            Some("p17_lifecycle_c"),
            "b03-lifecycle-c",
            "capi-independent-host",
        ),
        "p17_stress_gc_long_run" | "p17_stress_coroutine_debug" => {
            (Some("p17_lifecycle"), "b03-lifecycle-rust", "capi-public")
        }
        "p17_fuzz_parser" | "p17_fuzz_rvlu" | "p17_fuzz_official_chunk" => {
            (Some("p17_fuzz"), "b03-fuzz-rust", "capi-public")
        }
        "p17_platform_cli" => (None, "b03-platform-cli", "cli-rust-vm"),
        _ => (Some("p17_platform_c"), "b03-platform-c", "c-platform"),
    };
    if string(check, "operation")? != operation || string(check, "execution_path")? != path {
        return Err("P17 B03 operation/path 不符".into());
    }
    let artifact = b01_artifacts(root, profile)?;
    let build = target
        .map(|target| {
            builds
                .get(&(profile.to_owned(), target.to_owned()))
                .ok_or("P17 B03 check build proof 缺失")
        })
        .transpose()?;
    let command = strings(check, "command")?;
    let expected_command = if logical_id == "p17_platform_cli" {
        vec![
            artifact.binary.path.clone(),
            root.join("tests/p17/stress/platform.lua")
                .display()
                .to_string(),
        ]
    } else if matches!(target, Some("p17_lifecycle" | "p17_fuzz")) {
        vec![
            build
                .ok_or("P17 B03 Rust build 缺失")?
                .executable
                .path
                .clone(),
            "--nocapture".into(),
            "--test-threads=1".into(),
        ]
    } else {
        vec![
            build.ok_or("P17 B03 C build 缺失")?.executable.path.clone(),
            profile.into(),
        ]
    };
    let expected_cwd = if logical_id == "p17_platform_cli" {
        root.join(
            manifest::PROFILES
                .iter()
                .find(|item| item.name == profile)
                .ok_or("P17 B03 suite profile 缺失")?
                .suite,
        )
    } else {
        root.to_path_buf()
    };
    if command != expected_command || string(check, "cwd")? != expected_cwd.display().to_string() {
        return Err("P17 B03 body argv/cwd 不符".into());
    }
    let expected_env = runner::effective_no_native_environment();
    let observed_env = array(check, "environment")?
        .iter()
        .map(|item| {
            object(item, &["name", "value"])?;
            Ok((
                string(item, "name")?.to_owned(),
                string(item, "value")?.to_owned(),
            ))
        })
        .collect::<Result<Vec<_>, String>>()?;
    if observed_env != expected_env {
        return Err("P17 B03 body env 不符".into());
    }
    let log = Path::new(string(check, "log_path")?);
    if !log.starts_with(runner::environment(root)?.evidence_dir) {
        return Err("P17 B03 body log 越界".into());
    }
    sha(log, string(check, "log_sha256")?)?;
    let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
    let names: &[&str] = match target {
        Some("p17_lifecycle_c") => &["p17_allocator_failure", "p17_nested_callback"],
        Some("p17_lifecycle") => &["p17_stress_gc_long_run", "p17_stress_coroutine_debug"],
        Some("p17_fuzz") => &[
            "p17_fuzz_parser",
            "p17_fuzz_rvlu",
            "p17_fuzz_official_chunk",
        ],
        Some("p17_platform_c") => &["p17_platform_c"],
        _ => &["p17_platform_cli"],
    };
    if matches!(target, Some("p17_lifecycle" | "p17_fuzz")) {
        let (counts, outcomes) = parse_named_log(&body, names)?;
        if counts.matched as usize != names.len()
            || counts.passed != counts.matched
            || counts.failed != 0
            || counts.ignored != 0
            || outcomes.get(logical_id) != Some(&"ok")
        {
            return Err("P17 B03 named body 非 PASS".into());
        }
    }
    let records = marker_records(&body, names, true)?;
    let actual = records.get(logical_id).ok_or("P17 B03 body marker 缺失")?;
    if canonical_json(actual) != diagnostic {
        return Err("P17 B03 check detail 與 log 不符".into());
    }
    let mut expected_inputs = Vec::new();
    if let Some(build) = build {
        expected_inputs.extend([build.executable.clone(), build.log.clone()]);
    }
    if operation == "b03-lifecycle-c" {
        expected_inputs.push(artifact.library.clone());
    }
    if operation == "b03-platform-cli" {
        expected_inputs.extend([
            artifact.binary.clone(),
            report::Input::from_path(&root.join("tests/p17/stress/platform.lua"))?,
        ]);
    }
    if operation == "b03-fuzz-rust" {
        expected_inputs.push(registry.corpus.clone());
        for family in &registry.families {
            expected_inputs.extend(family.fixtures.iter().cloned());
        }
    }
    if spec.facet == "platform" {
        expected_inputs.push(registry.capabilities.clone());
    }
    let observed_inputs = array(check, "inputs")?;
    if observed_inputs.len() != expected_inputs.len() {
        return Err("P17 B03 check inputs 數不符".into());
    }
    for (item, expected) in observed_inputs.iter().zip(expected_inputs) {
        let actual = input(item)?;
        if actual.path != expected.path || actual.sha256 != expected.sha256 {
            return Err("P17 B03 check artifact/input 不符".into());
        }
    }
    Ok((profile.into(), logical_id.into()))
}

pub(super) fn validate_report(root: &Path, path: &Path) -> Result<(), String> {
    validate_report_with_view(root, path, None)
}

fn validate_report_for_phase(
    root: &Path,
    path: &Path,
    view: &report::PhaseSourceView,
) -> Result<(), String> {
    sha(path, B03_SHA)?;
    validate_report_with_view(root, path, Some(view))
}

fn validate_report_with_view(
    root: &Path,
    path: &Path,
    phase_view: Option<&report::PhaseSourceView>,
) -> Result<(), String> {
    if path != root.join("target/rivetlua-reports/gate-P17-B03.json") {
        return Err("P17 B03 report path 不符".into());
    }
    receipt(path)?;
    let environment = runner::environment(root)?;
    let b01 = root.join("target/rivetlua-reports/gate-P17-B01.json");
    let b02_path = root.join("target/rivetlua-reports/gate-P17-B02.json");
    if let Some(view) = phase_view {
        report::validate_b01_for_phase(root, &b01, view)?;
        b02::validate_b02_for_phase(root, &b02_path, view)?;
    } else {
        report::validate_b01_for_b03(root, &b01)?;
        b02::validate_b02_for_b03(root, &b02_path)?;
    }
    let historical_tooling =
        phase_view.map(|_| environment.evidence_dir.join("p17-phase-repair-baseline"));
    let review = validate_review(
        root,
        &environment.evidence_dir,
        historical_tooling.as_deref(),
    )?;
    let registry = parse_registry(root, &environment.target)?;
    let value =
        StrictJsonParser::parse(&fs::read_to_string(path).map_err(|error| error.to_string())?)?;
    object(
        &value,
        &[
            "schema",
            "phase",
            "batch",
            "status",
            "diagnostic",
            "scope",
            "source_inputs",
            "configuration",
            "dependencies",
            "checks",
            "stress_evidence",
        ],
    )?;
    if string(&value, "schema")? != "rivetlua-phase-gate-v1"
        || string(&value, "phase")? != "P17"
        || string(&value, "batch")? != "P17-B03"
        || string(&value, "status")? != "PASS"
    {
        return Err("P17 B03 report 主鍵非 PASS".into());
    }
    let scope = field(&value, "scope")?;
    object(
        scope,
        &[
            "phase",
            "batch",
            "declared_cases",
            "declared_facets",
            "selectors",
            "execution_paths",
        ],
    )?;
    if string(scope, "phase")? != "P17"
        || string(scope, "batch")? != "P17-B03"
        || strings(scope, "declared_cases")? != ["COMPLETE-003", "COMPLETE-004", "COMPLETE-006"]
        || strings(scope, "declared_facets")? != ["lifecycle", "stress", "platform", "fuzz"]
        || strings(scope, "selectors")? != ["P17-B03"]
        || strings(scope, "execution_paths")?
            != [
                "capi-independent-host",
                "capi-public",
                "cli-rust-vm",
                "c-platform",
            ]
    {
        return Err("P17 B03 scope 不符".into());
    }
    report_config(&value, &environment, phase_view)?;
    source_inputs(
        root, &value, &registry, phase_view, false, false, false, false, false, false, false, false, false, false, false, false, false,
    )?;
    dependencies(
        &value,
        &[
            report::Input::from_path(&b01)?,
            report::Input::from_path(&b02_path)?,
            review.clone(),
        ],
    )?;
    let evidence = field(&value, "stress_evidence")?;
    object(
        evidence,
        &["corpus", "capabilities", "source_impact_review", "builds"],
    )?;
    for (name, expected) in [
        ("corpus", &registry.corpus),
        ("capabilities", &registry.capabilities),
        ("source_impact_review", &review),
    ] {
        let actual = input(field(evidence, name)?)?;
        if actual.path != expected.path || actual.sha256 != expected.sha256 {
            return Err("P17 B03 registry/review SHA 不符".into());
        }
    }
    let builds = build_proofs(root, evidence, &environment)?;
    let checks = array(&value, "checks")?;
    if checks.len() != 18 {
        return Err("P17 B03 check 數不符".into());
    }
    let mut observed = BTreeSet::new();
    for check in checks {
        if !observed.insert(validate_case_check(root, check, &registry, &builds,
            phase_view.is_some())?) {
            return Err("P17 B03 重複 case/profile".into());
        }
    }
    if !PROFILES.iter().all(|profile| {
        CASES
            .iter()
            .all(|spec| observed.contains(&(profile.to_string(), spec.id.into())))
    }) {
        return Err("P17 B03 case/profile 缺失".into());
    }
    Ok(())
}

fn suite_pass(result: &ProcessResult) -> bool {
    !result.timed_out
        && result.exit_code == Some(0)
        && result
            .body
            .lines()
            .any(|line| line.trim() == "final OK !!!")
        && result.body.contains("total time:")
}

fn final_cli_source_inputs(root: &Path, sparse_gc: bool) -> Result<Vec<report::Input>, String> {
    let mut rows = vec![
        report::Input::from_path(&root.join(PRODUCER_NATIVE_PATH))?,
        report::Input::from_path(&root.join(FINAL_CODEC_PATH))?,
        report::Input::from_path(&root.join(FINAL_TRANSLATION_PATH))?,
        report::Input::from_path(&root.join(FINAL_CODEGEN_PATH))?,
    ];
    if sparse_gc {
        rows.push(report::Input::from_path(&root.join(GC_MOD_PATH))?);
    }
    Ok(rows)
}

fn build_phase_cli(
    root: &Path,
    work: &Path,
    environment: &runner::Environment,
    profile: manifest::Profile,
    host_review: bool,
    error_review: bool,
    console_review: bool,
    assert_warning_review: bool,
    producer_update_review: bool,
    debug_vm_review: bool,
    final_source_review: bool,
    sparse_gc: bool,
) -> Result<PhaseCliBuild, String> {
    let producer_before = if producer_update_review {
        Some([
            report::Input::from_path(&root.join(PRODUCER_STRING_PATH))?,
            report::Input::from_path(&root.join(PRODUCER_NATIVE_PATH))?,
        ])
    } else {
        None
    };
    let debug_vm_before = debug_vm_review.then(||
        report::Input::from_path(&root.join(DEBUG_VM_PATH))).transpose()?;
    let final_source_before = final_source_review.then(||
        final_cli_source_inputs(root, sparse_gc)).transpose()?;
    let command = runner::cli_build_command(profile);
    let result = invoke(
        root,
        command.clone(),
        &work.join(format!("build-{}-cli.log", profile.name)),
        BUILD_TIMEOUT,
        None,
    )?;
    if result.timed_out || result.exit_code != Some(0) {
        return Err(format!(
            "P17 phase CLI build 失敗／逾時：{}",
            result.log.path
        ));
    }
    let producer_after = if producer_update_review {
        Some([
            report::Input::from_path(&root.join(PRODUCER_STRING_PATH))?,
            report::Input::from_path(&root.join(PRODUCER_NATIVE_PATH))?,
        ])
    } else {
        None
    };
    let debug_vm_after = debug_vm_review.then(||
        report::Input::from_path(&root.join(DEBUG_VM_PATH))).transpose()?;
    let final_source_after = final_source_review.then(||
        final_cli_source_inputs(root, sparse_gc)).transpose()?;
    if debug_vm_before.as_ref().zip(debug_vm_after.as_ref()).is_some_and(|(before, after)|
        before.path != after.path || before.sha256 != after.sha256)
    {
        return Err("P17 phase debug VM build 中來源漂移".into());
    }
    if producer_before.as_ref().zip(producer_after.as_ref()).is_some_and(|(before, after)| {
        before.iter().zip(after).any(|(left, right)| left.path != right.path || left.sha256 != right.sha256)
    }) {
        return Err("P17 phase CLI producer build 前後來源漂移".into());
    }
    if final_source_before.as_ref().zip(final_source_after.as_ref()).is_some_and(|(before, after)| {
        before.iter().zip(after).any(|(left, right)|
            left.path != right.path || left.sha256 != right.sha256)
    }) {
        return Err("P17 phase CLI final source build 前後來源漂移".into());
    }
    let artifact = runner::cargo_artifact(&result.body, "rivetlua", "bin")?;
    let canonical = fs::canonicalize(&artifact).map_err(|error| error.to_string())?;
    if !canonical.starts_with(&environment.target_dir) || !canonical.is_file() {
        return Err("P17 phase CLI Cargo artifact 越出共用 target".into());
    }
    report::mach_type(&canonical, "EXECUTE")?;
    let pre_sha = manifest::sha256(&canonical)?;
    let snapshot = work.join(format!("{}-rivetlua", profile.name));
    fs::copy(&canonical, &snapshot).map_err(|error| error.to_string())?;
    fs::set_permissions(&snapshot, fs::Permissions::from_mode(0o555))
        .map_err(|error| error.to_string())?;
    let executable = report::Input::from_path(&snapshot)?;
    if executable.sha256 != pre_sha {
        return Err("P17 phase CLI snapshot 複製前後 SHA 不符".into());
    }
    Ok(PhaseCliBuild {
        profile: profile.name.into(),
        command,
        cwd: root.display().to_string(),
        exit_code: 0,
        log: result.log,
        artifact_path: canonical.display().to_string(),
        artifact_sha256: pre_sha,
        executable,
        post_sha256: String::new(),
        producer: report::Input::from_path(&root.join(PHASE_SOURCES[0].0))?,
        host_sources: if host_review {
            Some([
                report::Input::from_path(&root.join(HOST_CHANGES[0]))?,
                report::Input::from_path(&root.join(HOST_CHANGES[1]))?,
            ])
        } else {
            None
        },
        error_source: if error_review {
            Some(report::Input::from_path(&root.join(ERROR_FILES[0].0))?)
        } else {
            None
        },
        console_sources: if console_review {
            Some(
                CONSOLE_PRODUCERS
                    .iter()
                    .map(|path| report::Input::from_path(&root.join(path)))
                    .collect::<Result<Vec<_>, _>>()?,
            )
        } else {
            None
        },
        assert_warning_sources: if assert_warning_review {
            Some(
                WARNING_FILES[..11]
                    .iter()
                    .map(|(path, _)| report::Input::from_path(&root.join(path)))
                    .collect::<Result<Vec<_>, _>>()?,
            )
        } else {
            None
        },
        producer_update_sources: producer_before.zip(producer_after),
        debug_vm_sources: debug_vm_before.zip(debug_vm_after),
        final_source_sources: final_source_before.zip(final_source_after),
    })
}

fn assert_warning_batch_copies(root: &Path, original_root: &Path) -> Result<(), String> {
    report::phase_copied_report(root, original_root, "B01", B01_SHA)?;
    b02::validate_b02_phase_copy(root, original_root)?;
    report::phase_copied_report(root, original_root, "B03", B03_SHA)?;
    Ok(())
}

fn phase_platform_inputs(
    root: &Path,
    registry: &Registry,
    binary: &report::Input,
    build_log: &report::Input,
    host_active: bool,
    error_active: bool,
    console_active: bool,
) -> Result<Vec<report::Input>, String> {
    let mut inputs = vec![
        binary.clone(),
        build_log.clone(),
        report::Input::from_path(&root.join("tests/p17/stress/platform.lua"))?,
        registry.capabilities.clone(),
        report::Input::from_path(&root.join(PHASE_SOURCES[0].0))?,
    ];
    if host_active {
        for relative in &HOST_CHANGES[..2] {
            inputs.push(report::Input::from_path(&root.join(relative))?);
        }
    }
    if error_active {
        inputs.push(report::Input::from_path(&root.join(ERROR_FILES[0].0))?);
    }
    if console_active {
        for relative in CONSOLE_PRODUCERS {
            inputs.push(report::Input::from_path(&root.join(relative))?);
        }
    }
    for (relative, _) in &WARNING_FILES[..11] {
        inputs.push(report::Input::from_path(&root.join(relative))?);
    }
    Ok(inputs)
}

fn phase_platform_marker(body: &str, profile: &str, registry: &Registry) -> Result<String, String> {
    let markers = marker_records(body, &["p17_platform_cli"], true)?;
    let marker = markers
        .get("p17_platform_cli")
        .ok_or("P17 phase platform marker 缺失")?;
    let spec = CASES
        .iter()
        .copied()
        .find(|spec| spec.id == "p17_platform_cli")
        .ok_or("P17 phase platform case 缺失")?;
    validate_record(marker, spec, profile, registry, false)?;
    Ok(canonical_json(marker))
}

fn phase_platform_check(
    root: &Path,
    registry: &Registry,
    profile: &str,
    binary: &report::Input,
    build_log: &report::Input,
    result: &ProcessResult,
    host_active: bool,
    error_active: bool,
    console_active: bool,
) -> Result<report::Check, String> {
    let marker = phase_platform_marker(&result.body, profile, registry);
    let pass = !result.timed_out && result.exit_code == Some(0) && marker.is_ok();
    let diagnostic = if result.timed_out {
        "P17 phase platform TIMEOUT".to_owned()
    } else if result.exit_code != Some(0) {
        format!("P17 phase platform exit={:?}", result.exit_code)
    } else {
        match &marker {
            Ok(value) => value.clone(),
            Err(error) => error.clone(),
        }
    };
    let mut check = report::Check::pending("platform", Some(profile), &diagnostic);
    check.case_id = "COMPLETE-004".into();
    check.operation = "b03-platform-cli";
    check.execution_path = "cli-rust-vm";
    check.command = result.command.clone();
    check.cwd = result.cwd.clone();
    check.exit_code = result.exit_code;
    check.matched = u32::from(marker.is_ok());
    check.passed = u32::from(pass);
    check.failed = u32::from(!pass);
    check.status = if pass { "PASS" } else { "FAIL" };
    check.log = Some(result.log.clone());
    check.environment = result.environment.clone();
    check.inputs = phase_platform_inputs(
        root,
        registry,
        binary,
        build_log,
        host_active,
        error_active,
        console_active,
    )?;
    Ok(check)
}

pub(super) fn run_phase(root: &Path, report: &mut report::Report) -> Result<(), String> {
    let environment = runner::environment(root)?;
    report.target = environment.target.clone();
    report.environment = runner::related_environment(&environment);
    report.toolchain = runner::toolchain_identity()?;
    let b01 = root.join("target/rivetlua-reports/gate-P17-B01.json");
    let b02_path = root.join("target/rivetlua-reports/gate-P17-B02.json");
    let b03_path = root.join("target/rivetlua-reports/gate-P17-B03.json");
    let phase_review = phase_review(root, &environment.evidence_dir)?;
    if let Some(phase) = &phase_review {
        assert_warning_batch_copies(root, &phase.original_root)?;
        let checked_input_scope = report::begin_checked_input_scope()?;
        let historical = &phase.original_root;
        report::validate_b01_for_phase(
            historical,
            &historical.join("target/rivetlua-reports/gate-P17-B01.json"),
            &phase.view,
        )?;
        b02::validate_b02_for_phase(
            historical,
            &historical.join("target/rivetlua-reports/gate-P17-B02.json"),
            &phase.view,
        )?;
        validate_report_for_phase(
            historical,
            &historical.join("target/rivetlua-reports/gate-P17-B03.json"),
            &phase.view,
        )?;
        checked_input_scope.finish()?;
    } else {
        report::validate_b01_for_b03(root, &b01)?;
        b02::validate_b02_for_b03(root, &b02_path)?;
        validate_report(root, &b03_path)?;
    }
    let historical_tooling = phase_review
        .as_ref()
        .map(|_| environment.evidence_dir.join("p17-phase-repair-baseline"));
    let review = validate_review(
        phase_review
            .as_ref()
            .map_or(root, |phase| phase.original_root.as_path()),
        &environment.evidence_dir,
        historical_tooling.as_deref(),
    )?;
    let registry = parse_registry(root, &environment.target)?;
    let host_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.host.is_some());
    let error_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.error.is_some());
    let console_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.console.is_some());
    let assert_warning_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.assert_warning.is_some());
    let exit_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.exit.is_some());
    for path in phase_source_paths_with_gc(
        root,
        host_active,
        error_active,
        console_active,
        assert_warning_active,
        exit_active,
        phase_review.as_ref().and_then(|phase| phase.exit.as_ref())
            .is_some_and(|exit| exit.ctrl_c_updated),
        phase_review.as_ref().is_some_and(|phase| phase.gc.is_some()),
        phase_review.as_ref().is_some_and(|phase| phase.producer_update.is_some()),
        phase_review.as_ref().is_some_and(|phase| phase.debug_vm.is_some()),
        phase_review.as_ref().is_some_and(|phase| phase.debug_hook.is_some()),
        phase_review.as_ref().is_some_and(|phase| phase.final_source.is_some()),
        phase_review.as_ref().and_then(|phase| phase.final_source.as_ref())
            .is_some_and(|review| review.debug_successor.is_some()),
    )? {
        report.input(&path)?;
    }
    for family in &registry.families {
        for fixture in &family.fixtures {
            report.input(Path::new(&fixture.path))?;
        }
    }
    report.dependencies.extend([
        report::Input::from_path(&b01)?,
        report::Input::from_path(&b02_path)?,
        report::Input::from_path(&b03_path)?,
        review,
    ]);
    if let Some(phase) = &phase_review {
        report.dependencies.push(phase.input.clone());
        if let Some(host) = &phase.host {
            report.dependencies.extend([
                host.baseline.clone(),
                host.accepted_review.clone(),
                host.accepted_reuse.clone(),
                host.input.clone(),
            ]);
        }
        if let Some(error) = &phase.error {
            report.dependencies.extend([
                error.baseline.clone(),
                error.input.clone(),
                error.archive_manifest.clone(),
                error.archive_executables[0].clone(),
                error.archive_executables[1].clone(),
            ]);
        }
        if let Some(console) = &phase.console {
            report
                .dependencies
                .extend(console.baselines.iter().cloned());
            report.dependencies.extend([
                console.accepted_report.clone(),
                console.accepted_receipt.clone(),
                console.input.clone(),
            ]);
        }
        if let Some(repair) = &phase.assert_warning {
            report.dependencies.extend(repair.baselines.iter().cloned());
            report.dependencies.extend([
                repair.archive_manifest.clone(),
                repair.accepted_report.clone(),
                repair.accepted_receipt.clone(),
                repair.input.clone(),
            ]);
        }
        if let Some(exit) = &phase.exit {
            report.dependencies.extend([
                exit.product_baseline.clone(),
                exit.proof_baseline.clone(),
                exit.warning_helper_baseline.clone(),
                exit.phase_archive.clone(),
                exit.safe_environment.clone(),
                exit.input.clone(),
            ]);
        }
        if let Some(host_entry) = &phase.host_entry {
            report.dependencies.extend([
                host_entry.baseline.clone(),
                host_entry.coroutine_baseline.clone(),
                host_entry.unwind_baseline.clone(),
                host_entry.gate14_archive.clone(),
                host_entry.input.clone(),
            ]);
        }
        if let Some(gc) = &phase.gc {
            report.dependencies.push(gc.input.clone());
        }
        if let Some(producer) = &phase.producer_update {
            report.dependencies.push(producer.input.clone());
        }
        if let Some(debug_vm) = &phase.debug_vm {
            report.dependencies.push(debug_vm.input.clone());
        }
        if let Some(debug_hook) = &phase.debug_hook {
            report.dependencies.push(debug_hook.input.clone());
        }
        if let Some(final_source) = &phase.final_source {
            report.dependencies.push(final_source.input.clone());
            if let Some(successor) = &final_source.successor {
                report.dependencies.push(successor.clone());
                report.dependencies.push(report::Input::from_path(
                    &environment.evidence_dir.join(FINAL_SUCCESSOR_FREEZE_FILE))?);
            }
            if let Some(successor) = &final_source.count_successor {
                report.dependencies.push(successor.clone());
                report.dependencies.push(report::Input::from_path(
                    &environment.evidence_dir.join(FINAL_COUNT_SUCCESSOR_FREEZE_FILE))?);
            }
            if let Some(successor) = &final_source.debug_successor {
                report.dependencies.push(successor.clone());
                report.dependencies.push(report::Input::from_path(
                    &environment.evidence_dir.join(FINAL_DEBUG_SUCCESSOR_ROOT_REVIEW_FILE))?);
                report.dependencies.push(report::Input::from_path(
                    &environment.evidence_dir.join(FINAL_DEBUG_SUCCESSOR_FREEZE_FILE))?);
            }
        }
    }
    let work = work_dir(&environment.evidence_dir, "p17-phase")?;
    let mut cli_builds = Vec::new();
    for profile in manifest::PROFILES {
        let artifact = b01_artifacts(root, profile.name)?;
        let build = if phase_review.is_some() {
            Some(build_phase_cli(
                root,
                &work,
                &environment,
                profile,
                host_active,
                error_active,
                console_active,
                assert_warning_active,
                phase_review.as_ref().is_some_and(|phase| phase.producer_update.is_some()),
                phase_review.as_ref().is_some_and(|phase| phase.debug_vm.is_some()),
                phase_review.as_ref().is_some_and(|phase| phase.final_source.is_some()),
                phase_review.as_ref().and_then(|phase| phase.final_source.as_ref())
                    .and_then(|review| review.verified.as_ref())
                    .is_some_and(|context| context.heap_successor_active),
            )?)
        } else {
            None
        };
        let binary = build
            .as_ref()
            .map_or_else(|| artifact.binary.clone(), |item| item.executable.clone());
        let command = vec![binary.path.clone(), "all.lua".into()];
        let log = work.join(format!("suite-{}.log", profile.name));
        let result = invoke(
            &artifact.suite,
            command,
            &log,
            SUITE_TIMEOUT,
            Some(Path::new(&artifact.grant.path)),
        )?;
        let pass = suite_pass(&result);
        let diagnostic = if result.timed_out {
            "P17 完整 suite TIMEOUT"
        } else if pass {
            "P17 完整 suite 實際 exit 0 且 final OK"
        } else {
            "P17 完整 suite 未達 final OK／exit 0"
        };
        let mut check = report::Check::pending("full-suite", Some(profile.name), diagnostic);
        check.case_id = "COMPLETE-001".into();
        check.operation = "cli-all-lua";
        check.execution_path = "cli-rust-vm";
        check.command = result.command;
        check.cwd = result.cwd;
        check.exit_code = result.exit_code;
        check.matched = 1;
        check.passed = u32::from(pass);
        check.failed = u32::from(!pass);
        check.ignored = 0;
        check.status = if pass { "PASS" } else { "FAIL" };
        check.log = Some(result.log);
        check.inputs.extend([
            binary.clone(),
            artifact.grant,
            report::Input::from_path(&artifact.suite.join("all.lua"))?,
        ]);
        check.environment = result.environment;
        report.checks.push(check);
        if assert_warning_active {
            let current_build = build
                .as_ref()
                .ok_or("P17 phase platform 缺 fresh CLI build")?;
            let platform_lua = root.join("tests/p17/stress/platform.lua");
            let platform_result = invoke_body(
                &artifact.suite,
                vec![binary.path.clone(), platform_lua.display().to_string()],
                &work.join(format!("platform-{}.log", profile.name)),
                None,
            )?;
            report.checks.push(phase_platform_check(
                root,
                &registry,
                profile.name,
                &binary,
                &current_build.log,
                &platform_result,
                host_active,
                error_active,
                console_active,
            )?);
        }
        if let Some(mut build) = build {
            build.post_sha256 = manifest::sha256(Path::new(&build.executable.path))?;
            if build.post_sha256 != build.executable.sha256 {
                return Err("P17 phase CLI suite 後 snapshot SHA 改變".into());
            }
            cli_builds.push(build);
        }
    }
    if let Some(phase) = phase_review {
        report.phase = Some(PhaseEvidence {
            review: phase.input,
            host_review: phase.host.map(|host| host.input),
            error_review: phase.error.map(|error| error.input),
            console_review: phase.console.map(|console| console.input),
            assert_warning_review: phase.assert_warning.map(|repair| repair.input),
            exit_review: phase.exit.map(|exit| exit.input),
            host_entry_review: phase.host_entry.map(|entry| entry.input),
            gc_review: phase.gc.map(|gc| gc.input),
            producer_update_review: phase.producer_update.map(|producer| producer.input),
            debug_vm_review: phase.debug_vm.map(|debug_vm| debug_vm.input),
            debug_hook_review: phase.debug_hook.map(|debug_hook| debug_hook.input),
            final_source_review: phase.final_source.map(|final_source| final_source.input),
            builds: cli_builds,
        });
    }
    if report.checks.iter().any(|check| check.status != "PASS") {
        return Err("P17 完整 suite／platform 有實際失敗；雙版均已執行".into());
    }
    Ok(())
}

fn validate_phase_builds(
    root: &Path,
    environment: &runner::Environment,
    value: &StrictJsonValue,
    review: &report::Input,
    host: Option<&HostReview>,
    error: Option<&ErrorReview>,
    console: Option<&ConsoleReview>,
    assert_warning: Option<&AssertWarningReview>,
    exit: Option<&ExitReview>,
    host_entry: Option<&HostEntryReview>,
    gc: Option<&GcReview>,
    producer: Option<&ProducerUpdateReview>,
    debug_vm: Option<&DebugVmReview>,
    debug_hook: Option<&DebugHookReview>,
    final_source: Option<&FinalSourceReview>,
) -> Result<BTreeMap<String, report::Input>, String> {
    let verified = final_source.and_then(|review| review.verified.as_ref());
    let evidence = field(value, "phase_evidence")?;
    let mut evidence_keys = vec!["source_impact_review", "cli_builds"];
    if host.is_some() {
        evidence_keys.push("host_source_impact_review");
    }
    if error.is_some() {
        evidence_keys.push("error_position_source_impact_review");
    }
    if console.is_some() {
        evidence_keys.push("debug_console_source_impact_review");
    }
    if assert_warning.is_some() {
        evidence_keys.push("assert_warning_source_impact_review");
    }
    if exit.is_some() {
        evidence_keys.push("exit_source_impact_review");
    }
    if host_entry.is_some() {
        evidence_keys.push("host_entry_source_impact_review");
    }
    if gc.is_some() {
        evidence_keys.push("gc_source_impact_review");
    }
    if producer.is_some() {
        evidence_keys.push("producer_source_impact_review");
    }
    if debug_vm.is_some() {
        evidence_keys.push("debug_vm_source_impact_review");
    }
    if debug_hook.is_some() {
        evidence_keys.push("debug_hook_source_impact_review");
    }
    if final_source.is_some() {
        evidence_keys.push("final_source_impact_review");
    }
    object(evidence, &evidence_keys)?;
    let actual_review = input(field(evidence, "source_impact_review")?)?;
    if actual_review.path != review.path || actual_review.sha256 != review.sha256 {
        return Err("P17 phase CLI build source-impact review 不符".into());
    }
    if let Some(host) = host {
        let actual_host = input(field(evidence, "host_source_impact_review")?)?;
        if actual_host.path != host.input.path || actual_host.sha256 != host.input.sha256 {
            return Err("P17 phase CLI build host review 不符".into());
        }
    }
    if let Some(error) = error {
        let actual_error = input(field(evidence, "error_position_source_impact_review")?)?;
        if actual_error.path != error.input.path || actual_error.sha256 != error.input.sha256 {
            return Err("P17 phase CLI build error-position review 不符".into());
        }
    }
    if let Some(console) = console {
        let actual_console = input(field(evidence, "debug_console_source_impact_review")?)?;
        if actual_console.path != console.input.path
            || actual_console.sha256 != console.input.sha256
        {
            return Err("P17 phase Console review 不符".into());
        }
    }
    if let Some(repair) = assert_warning {
        let actual = input(field(evidence, "assert_warning_source_impact_review")?)?;
        if actual.path != repair.input.path || actual.sha256 != repair.input.sha256 {
            return Err("P17 phase Assert/Warning review 不符".into());
        }
    }
    if let Some(exit) = exit {
        let actual = input(field(evidence, "exit_source_impact_review")?)?;
        if actual.path != exit.input.path || actual.sha256 != exit.input.sha256 {
            return Err("P17 phase Exit v2 review 不符".into());
        }
    }
    if let Some(host_entry) = host_entry {
        let actual = input(field(evidence, "host_entry_source_impact_review")?)?;
        if actual.path != host_entry.input.path || actual.sha256 != host_entry.input.sha256 {
            return Err("P17 phase host-entry review 不符".into());
        }
    }
    if let Some(gc) = gc {
        let actual = input(field(evidence, "gc_source_impact_review")?)?;
        if actual.path != gc.input.path || actual.sha256 != gc.input.sha256 {
            return Err("P17 phase GC review 不符".into());
        }
    }
    if let Some(producer) = producer {
        let actual = input(field(evidence, "producer_source_impact_review")?)?;
        if actual.path != producer.input.path || actual.sha256 != producer.input.sha256 {
            return Err("P17 phase producer update review 不符".into());
        }
    }
    if let Some(debug_vm) = debug_vm {
        let actual = input(field(evidence, "debug_vm_source_impact_review")?)?;
        if actual.path != debug_vm.input.path || actual.sha256 != debug_vm.input.sha256 {
            return Err("P17 phase debug VM review 不符".into());
        }
    }
    if let Some(debug_hook) = debug_hook {
        let actual = input(field(evidence, "debug_hook_source_impact_review")?)?;
        if actual.path != debug_hook.input.path || actual.sha256 != debug_hook.input.sha256 {
            return Err("P17 phase debug hook review 不符".into());
        }
    }
    if let Some(final_source) = final_source {
        let actual = input(field(evidence, "final_source_impact_review")?)?;
        if actual.path != final_source.input.path || actual.sha256 != final_source.input.sha256 {
            return Err("P17 phase final source review 不符".into());
        }
    }
    let builds = array(evidence, "cli_builds")?;
    if builds.len() != 2 {
        return Err("P17 phase CLI build profile 數不符".into());
    }
    let mut binaries = BTreeMap::new();
    for (item, profile) in builds.iter().zip(manifest::PROFILES) {
        let mut build_keys = vec![
            "profile",
            "command",
            "cwd",
            "exit_code",
            "log",
            "artifact_path",
            "artifact_sha256",
            "executable",
            "post_sha256",
            "producer",
        ];
        if host.is_some() {
            build_keys.push("host_sources");
        }
        if error.is_some() {
            build_keys.push("error_source");
        }
        if console.is_some() {
            build_keys.push("console_sources");
        }
        if assert_warning.is_some() {
            build_keys.push("assert_warning_sources");
        }
        if producer.is_some() {
            build_keys.push("producer_update_sources");
        }
        if debug_vm.is_some() {
            build_keys.push("debug_vm_sources");
        }
        if final_source.is_some() {
            build_keys.push("final_source_sources");
        }
        object(item, &build_keys)?;
        let expected_command = runner::cli_build_command(profile);
        if string(item, "profile")? != profile.name
            || strings(item, "command")? != expected_command
            || string(item, "cwd")? != root.display().to_string()
            || integer(item, "exit_code")? != 0
        {
            return Err("P17 phase CLI build command/profile/exit 不符".into());
        }
        let log = input(field(item, "log")?)?;
        let executable = input(field(item, "executable")?)?;
        let log_path = Path::new(&log.path);
        let binary_path = Path::new(&executable.path);
        if !log_path.starts_with(&environment.evidence_dir)
            || log_path.file_name().and_then(|name| name.to_str())
                != Some(format!("build-{}-cli.log", profile.name).as_str())
            || binary_path.parent() != log_path.parent()
            || binary_path.file_name().and_then(|name| name.to_str())
                != Some(format!("{}-rivetlua", profile.name).as_str())
            || !binary_path
                .parent()
                .and_then(|path| path.file_name())
                .and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with("p17-phase-"))
            || fs::metadata(binary_path)
                .map_err(|error| error.to_string())?
                .permissions()
                .mode()
                & 0o777
                != 0o555
        {
            return Err("P17 phase CLI immutable snapshot 路徑／mode 不符".into());
        }
        report::mach_type(binary_path, "EXECUTE")?;
        let log_body = fs::read_to_string(log_path).map_err(|error| error.to_string())?;
        let artifact = runner::cargo_artifact(&log_body, "rivetlua", "bin")?;
        let canonical = fs::canonicalize(&artifact).map_err(|error| error.to_string())?;
        if !canonical.starts_with(&environment.target_dir)
            || string(item, "artifact_path")? != canonical.display().to_string()
            || string(item, "artifact_sha256")? != executable.sha256
            || string(item, "post_sha256")? != executable.sha256
        {
            return Err("P17 phase CLI Cargo JSON/artifact prepost SHA 不符".into());
        }
        let legacy_producer = input(field(item, "producer")?)?;
        if legacy_producer.path != root.join(PHASE_SOURCES[0].0).display().to_string() {
            return Err("P17 phase CLI producer input 不符".into());
        }
        if host.is_some() {
            let sources = array(item, "host_sources")?;
            if sources.len() != 2 {
                return Err("P17 phase CLI host producer input 數不符".into());
            }
            for (source, relative) in sources.iter().zip(&HOST_CHANGES[..2]) {
                if input(source)?.path != root.join(relative).display().to_string() {
                    return Err("P17 phase CLI host producer input 不符".into());
                }
            }
        }
        if error.is_some() {
            let source = input(field(item, "error_source")?)?;
            if source.path != root.join(ERROR_FILES[0].0).display().to_string() {
                return Err("P17 phase CLI Runtime producer input 不符".into());
            }
        }
        if console.is_some() {
            let sources = array(item, "console_sources")?;
            if sources.len() != CONSOLE_PRODUCERS.len() {
                return Err("P17 phase Console CLI producer 數不符".into());
            }
            for (source, relative) in sources.iter().zip(CONSOLE_PRODUCERS) {
                if input(source)?.path != root.join(relative).display().to_string() {
                    return Err(format!("P17 phase Console CLI producer 不符：{relative}"));
                }
            }
        }
        if assert_warning.is_some() {
            let sources = array(item, "assert_warning_sources")?;
            if sources.len() != 11 {
                return Err("P17 phase Assert/Warning CLI producer 數不符".into());
            }
            for (source, (relative, _)) in sources.iter().zip(&WARNING_FILES[..11]) {
                let expected = report::Input::from_path(&root.join(relative))?;
                let actual = input(source)?;
                if actual.path != expected.path || actual.sha256 != expected.sha256 {
                    return Err(format!(
                        "P17 phase Assert/Warning CLI producer 不符：{relative}"
                    ));
                }
            }
        }
        if let Some(producer) = producer {
            let sources = field(item, "producer_update_sources")?;
            object(sources, &["before", "after"])?;
            for key in ["before", "after"] {
                let rows = array(sources, key)?;
                if rows.len() != 2 {
                    return Err("P17 phase producer build source 數不符".into());
                }
                for (source, (relative, digest)) in rows.iter().zip([
                    (PRODUCER_STRING_PATH, &producer.after_hashes[0]),
                    (PRODUCER_NATIVE_PATH, &producer.after_hashes[1]),
                ]) {
                    let actual = input(source)?;
                    let expected_digest = if relative == PRODUCER_NATIVE_PATH
                        && final_source.is_some() {
                        current_repair_sha(relative,
                            final_debug_successor_sha(relative,
                                final_count_successor_sha(relative,
                                    final_successor_sha(relative, FINAL_NATIVE_SHA,
                                        final_source.is_some_and(|review| review.successor.is_some())),
                                    final_source.is_some_and(|review| review.count_successor.is_some())),
                                final_source.is_some_and(|review| review.debug_successor.is_some())),
                            verified.is_some_and(|verified| verified.repair_active),
                            verified.is_some_and(|verified| verified.core_successor_active),
                            verified.is_some_and(|verified| verified.heap_successor_active), verified.is_some_and(|verified| verified.product_successor_active))
                    } else {
                        digest.as_str()
                    };
                    if actual.path != root.join(relative).display().to_string()
                        || actual.sha256 != expected_digest
                    {
                        return Err(format!("P17 phase producer build {key} source 不符：{relative}"));
                    }
                }
            }
        }
        if debug_vm.is_some() {
            let sources = field(item, "debug_vm_sources")?;
            object(sources, &["before", "after"])?;
            let expected_sha = if final_source.is_some_and(|review| review.debug_successor.is_some()) {
                product_successor_sha(DEBUG_VM_PATH,
                    final_repair_sha(DEBUG_VM_PATH, FINAL_DEBUG_SUCCESSOR_VM_AFTER_SHA,
                        verified.is_some_and(|verified| verified.repair_active)),
                    verified.is_some_and(|context| context.product_successor_active))
            } else if debug_hook.is_some() {
                DEBUG_HOOK_VM_AFTER_SHA
            } else {
                DEBUG_VM_AFTER_SHA
            };
            for key in ["before", "after"] {
                let actual = input(field(sources, key)?)?;
                if actual.path != root.join(DEBUG_VM_PATH).display().to_string()
                    || actual.sha256 != expected_sha
                {
                    return Err(format!("P17 phase debug VM build {key} source 不符"));
                }
            }
        }
        if final_source.is_some() {
            let sources = field(item, "final_source_sources")?;
            object(sources, &["before", "after"])?;
            for key in ["before", "after"] {
                let rows = array(sources, key)?;
                if rows.len() != if verified.is_some_and(|context| context.heap_successor_active) { 5 } else { 4 } {
                    return Err("P17 phase final source build guard 數不符".into());
                }
                for (source, (relative, _, digest)) in rows.iter().zip(&FINAL_SOURCE_CHANGES[..4]) {
                    let actual = input(source)?;
                    if actual.path != root.join(relative).display().to_string()
                        || actual.sha256 != current_repair_sha(relative,
                            final_debug_successor_sha(relative,
                                final_count_successor_sha(relative,
                                    final_successor_sha(relative, digest,
                                        final_source.is_some_and(|review| review.successor.is_some())),
                                    final_source.is_some_and(|review| review.count_successor.is_some())),
                                final_source.is_some_and(|review| review.debug_successor.is_some())),
                            verified.is_some_and(|verified| verified.repair_active),
                            verified.is_some_and(|verified| verified.core_successor_active),
                            verified.is_some_and(|verified| verified.heap_successor_active), verified.is_some_and(|verified| verified.product_successor_active))
                    {
                        return Err(format!("P17 phase final source build {key} guard 不符：{relative}"));
                    }
                }
                if verified.is_some_and(|context| context.heap_successor_active) {
                    let module = input(rows.get(4).ok_or("P17 sparse GC build module 缺失")?)?;
                    if module.path != root.join(GC_MOD_PATH).display().to_string()
                        || module.sha256 != GC_MOD_AFTER_SHA
                        || verified.and_then(|context| context.source_shas.get(&root.join(GC_MOD_PATH)))
                            .map(String::as_str) != Some(GC_MOD_AFTER_SHA) {
                        return Err("P17 sparse GC build module 前後／current source 不符".into());
                    }
                }
            }
        }
        if binaries.insert(profile.name.into(), executable).is_some() {
            return Err("P17 phase CLI build 重複 profile".into());
        }
    }
    Ok(binaries)
}

fn validate_phase_platform_check(
    root: &Path,
    environment: &runner::Environment,
    registry: &Registry,
    check: &StrictJsonValue,
    profile: &str,
    binary: &report::Input,
    suite: &Path,
    host_active: bool,
    error_active: bool,
    console_active: bool,
) -> Result<(), String> {
    let platform_lua = root.join("tests/p17/stress/platform.lua");
    phase_platform_identity(check, profile, binary, suite, &platform_lua)?;
    phase_platform_environment(check)?;
    let work = Path::new(&binary.path)
        .parent()
        .ok_or("P17 phase platform CLI snapshot parent 缺失")?;
    let log = work.join(format!("platform-{profile}.log"));
    if !log.starts_with(&environment.evidence_dir)
        || string(check, "log_path")? != log.display().to_string()
    {
        return Err("P17 phase platform log path 不符".into());
    }
    sha(&log, string(check, "log_sha256")?)?;
    let body = fs::read_to_string(&log).map_err(|error| error.to_string())?;
    let marker = phase_platform_marker(&body, profile, registry)?;
    if string(check, "diagnostic")? != marker {
        return Err("P17 phase platform detail/log 不符".into());
    }
    let build_log = report::Input::from_path(&work.join(format!("build-{profile}-cli.log")))?;
    let expected_inputs = phase_platform_inputs(
        root,
        registry,
        binary,
        &build_log,
        host_active,
        error_active,
        console_active,
    )?;
    let observed_inputs = array(check, "inputs")?;
    if observed_inputs.len() != expected_inputs.len() {
        return Err("P17 phase platform input 數不符".into());
    }
    for (actual, expected) in observed_inputs.iter().zip(expected_inputs) {
        let actual = input(actual)?;
        if actual.path != expected.path || actual.sha256 != expected.sha256 {
            return Err("P17 phase platform input path/SHA 不符".into());
        }
    }
    Ok(())
}

fn phase_platform_environment(check: &StrictJsonValue) -> Result<(), String> {
    let observed_environment = array(check, "environment")?
        .iter()
        .map(|item| {
            object(item, &["name", "value"])?;
            Ok((
                string(item, "name")?.to_owned(),
                string(item, "value")?.to_owned(),
            ))
        })
        .collect::<Result<Vec<_>, String>>()?;
    if observed_environment != runner::effective_no_native_environment() {
        return Err("P17 phase platform no-grant environment 不符".into());
    }
    Ok(())
}

fn phase_platform_identity(
    check: &StrictJsonValue,
    profile: &str,
    binary: &report::Input,
    suite: &Path,
    platform_lua: &Path,
) -> Result<(), String> {
    if string(check, "case_id")? != "COMPLETE-004"
        || string(check, "facet")? != "platform"
        || string(check, "operation")? != "b03-platform-cli"
        || string(check, "execution_path")? != "cli-rust-vm"
        || string(check, "profile")? != profile
        || string(check, "status")? != "PASS"
        || integer(check, "exit_code")? != 0
        || integer(check, "matched")? != 1
        || integer(check, "passed")? != 1
        || integer(check, "failed")? != 0
        || integer(check, "ignored")? != 0
        || strings(check, "command")? != [binary.path.clone(), platform_lua.display().to_string()]
        || string(check, "cwd")? != suite.display().to_string()
        || !array(check, "negative_runs")?.is_empty()
    {
        return Err("P17 phase platform identity/command/count 不符".into());
    }
    Ok(())
}

pub(super) fn validate_phase(root: &Path, path: &Path) -> Result<(), String> {
    if path != root.join("target/rivetlua-reports/gate-P17.json") {
        return Err("P17 phase report path 不符".into());
    }
    receipt(path)?;
    let environment = runner::environment(root)?;
    let b01 = root.join("target/rivetlua-reports/gate-P17-B01.json");
    let b02_path = root.join("target/rivetlua-reports/gate-P17-B02.json");
    let b03_path = root.join("target/rivetlua-reports/gate-P17-B03.json");
    let phase_review = phase_review(root, &environment.evidence_dir)?;
    if let Some(phase) = &phase_review {
        assert_warning_batch_copies(root, &phase.original_root)?;
        validate_report_for_phase(
            &phase.original_root,
            &phase
                .original_root
                .join("target/rivetlua-reports/gate-P17-B03.json"),
            &phase.view,
        )?;
    } else {
        validate_report(root, &b03_path)?;
    }
    let historical_tooling = phase_review
        .as_ref()
        .map(|_| environment.evidence_dir.join("p17-phase-repair-baseline"));
    let review = validate_review(
        phase_review
            .as_ref()
            .map_or(root, |phase| phase.original_root.as_path()),
        &environment.evidence_dir,
        historical_tooling.as_deref(),
    )?;
    let registry = parse_registry(root, &environment.target)?;
    let value =
        StrictJsonParser::parse(&fs::read_to_string(path).map_err(|error| error.to_string())?)?;
    let mut expected_keys = vec![
        "schema",
        "phase",
        "batch",
        "status",
        "diagnostic",
        "scope",
        "source_inputs",
        "configuration",
        "dependencies",
        "checks",
    ];
    if phase_review.is_some() {
        expected_keys.push("phase_evidence");
    }
    object(&value, &expected_keys)?;
    if string(&value, "schema")? != "rivetlua-phase-gate-v1"
        || string(&value, "phase")? != "P17"
        || !matches!(field(&value, "batch")?, StrictJsonValue::Null)
        || string(&value, "status")? != "PASS"
    {
        return Err("P17 phase 主鍵非 PASS".into());
    }
    let scope = field(&value, "scope")?;
    object(
        scope,
        &[
            "phase",
            "batch",
            "declared_cases",
            "declared_facets",
            "selectors",
            "execution_paths",
        ],
    )?;
    if string(scope, "phase")? != "P17"
        || !matches!(field(scope, "batch")?, StrictJsonValue::Null)
        || strings(scope, "declared_cases")?
            != [
                "COMPLETE-001",
                "COMPLETE-002",
                "COMPLETE-003",
                "COMPLETE-004",
                "COMPLETE-005",
                "COMPLETE-006",
            ]
        || strings(scope, "declared_facets")?
            != if phase_review
                .as_ref()
                .is_some_and(|phase| phase.assert_warning.is_some())
            {
                vec!["batch-dependency", "full-suite", "platform"]
            } else {
                vec!["batch-dependency", "full-suite"]
            }
        || strings(scope, "selectors")? != ["P17-B01", "P17-B02", "P17-B03"]
        || strings(scope, "execution_paths")? != ["cli-rust-vm", "p17-evidence"]
    {
        return Err("P17 phase scope 不符".into());
    }
    report_config(&value, &environment, None)?;
    let host_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.host.is_some());
    let error_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.error.is_some());
    let console_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.console.is_some());
    let assert_warning_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.assert_warning.is_some());
    let exit_active = phase_review
        .as_ref()
        .is_some_and(|phase| phase.exit.is_some());
    source_inputs(
        root,
        &value,
        &registry,
        None,
        host_active,
        error_active,
        console_active,
        assert_warning_active,
        exit_active,
        phase_review.as_ref().and_then(|phase| phase.exit.as_ref())
            .is_some_and(|exit| exit.ctrl_c_updated),
        phase_review.as_ref().is_some_and(|phase| phase.gc.is_some()),
        phase_review.as_ref().is_some_and(|phase| phase.producer_update.is_some()),
        phase_review.as_ref().is_some_and(|phase| phase.debug_vm.is_some()),
        phase_review.as_ref().is_some_and(|phase| phase.debug_hook.is_some()),
        phase_review.as_ref().is_some_and(|phase| phase.final_source.is_some()),
        phase_review.as_ref().and_then(|phase| phase.final_source.as_ref())
            .is_some_and(|review| review.debug_successor.is_some()),
        phase_review.as_ref().and_then(|phase| phase.final_source.as_ref())
            .and_then(|review| review.verified.as_ref())
            .is_some_and(|context| context.heap_successor_active),
    )?;
    let mut expected_dependencies = vec![
        report::Input::from_path(&b01)?,
        report::Input::from_path(&b02_path)?,
        report::Input::from_path(&b03_path)?,
        review,
    ];
    if let Some(phase) = &phase_review {
        expected_dependencies.push(phase.input.clone());
        if let Some(host) = &phase.host {
            expected_dependencies.extend([
                host.baseline.clone(),
                host.accepted_review.clone(),
                host.accepted_reuse.clone(),
                host.input.clone(),
            ]);
        }
        if let Some(error) = &phase.error {
            expected_dependencies.extend([
                error.baseline.clone(),
                error.input.clone(),
                error.archive_manifest.clone(),
                error.archive_executables[0].clone(),
                error.archive_executables[1].clone(),
            ]);
        }
        if let Some(console) = &phase.console {
            expected_dependencies.extend(console.baselines.iter().cloned());
            expected_dependencies.extend([
                console.accepted_report.clone(),
                console.accepted_receipt.clone(),
                console.input.clone(),
            ]);
        }
        if let Some(repair) = &phase.assert_warning {
            expected_dependencies.extend(repair.baselines.iter().cloned());
            expected_dependencies.extend([
                repair.archive_manifest.clone(),
                repair.accepted_report.clone(),
                repair.accepted_receipt.clone(),
                repair.input.clone(),
            ]);
        }
        if let Some(exit) = &phase.exit {
            expected_dependencies.extend([
                exit.product_baseline.clone(),
                exit.proof_baseline.clone(),
                exit.warning_helper_baseline.clone(),
                exit.phase_archive.clone(),
                exit.safe_environment.clone(),
                exit.input.clone(),
            ]);
        }
        if let Some(host_entry) = &phase.host_entry {
            expected_dependencies.extend([
                host_entry.baseline.clone(),
                host_entry.coroutine_baseline.clone(),
                host_entry.unwind_baseline.clone(),
                host_entry.gate14_archive.clone(),
                host_entry.input.clone(),
            ]);
        }
        if let Some(gc) = &phase.gc {
            expected_dependencies.push(gc.input.clone());
        }
        if let Some(producer) = &phase.producer_update {
            expected_dependencies.push(producer.input.clone());
        }
        if let Some(debug_vm) = &phase.debug_vm {
            expected_dependencies.push(debug_vm.input.clone());
        }
        if let Some(debug_hook) = &phase.debug_hook {
            expected_dependencies.push(debug_hook.input.clone());
        }
        if let Some(final_source) = &phase.final_source {
            expected_dependencies.push(final_source.input.clone());
            if let Some(successor) = &final_source.successor {
                expected_dependencies.push(successor.clone());
                expected_dependencies.push(report::Input::from_path(
                    &environment.evidence_dir.join(FINAL_SUCCESSOR_FREEZE_FILE))?);
            }
            if let Some(successor) = &final_source.count_successor {
                expected_dependencies.push(successor.clone());
                expected_dependencies.push(report::Input::from_path(
                    &environment.evidence_dir.join(FINAL_COUNT_SUCCESSOR_FREEZE_FILE))?);
            }
            if let Some(successor) = &final_source.debug_successor {
                expected_dependencies.push(successor.clone());
                expected_dependencies.push(report::Input::from_path(
                    &environment.evidence_dir.join(FINAL_DEBUG_SUCCESSOR_ROOT_REVIEW_FILE))?);
                expected_dependencies.push(report::Input::from_path(
                    &environment.evidence_dir.join(FINAL_DEBUG_SUCCESSOR_FREEZE_FILE))?);
            }
        }
    }
    dependencies(&value, &expected_dependencies)?;
    let phase_builds = if let Some(phase) = &phase_review {
        validate_phase_builds(
            root,
            &environment,
            &value,
            &phase.input,
            phase.host.as_ref(),
            phase.error.as_ref(),
            phase.console.as_ref(),
            phase.assert_warning.as_ref(),
            phase.exit.as_ref(),
            phase.host_entry.as_ref(),
            phase.gc.as_ref(),
            phase.producer_update.as_ref(),
            phase.debug_vm.as_ref(),
            phase.debug_hook.as_ref(),
            phase.final_source.as_ref(),
        )?
    } else {
        BTreeMap::new()
    };
    let checks = array(&value, "checks")?;
    if checks.len() != if assert_warning_active { 4 } else { 2 } {
        return Err("P17 phase suite/platform 次數不符".into());
    }
    let mut seen = BTreeSet::new();
    for check in checks {
        object(
            check,
            &[
                "case_id",
                "facet",
                "operation",
                "execution_path",
                "profile",
                "command",
                "cwd",
                "exit_code",
                "matched",
                "passed",
                "failed",
                "ignored",
                "status",
                "log_path",
                "log_sha256",
                "inputs",
                "environment",
                "negative_runs",
                "diagnostic",
            ],
        )?;
        let profile = string(check, "profile")?;
        let facet = string(check, "facet")?;
        if !PROFILES.contains(&profile)
            || !["full-suite", "platform"].contains(&facet)
            || !seen.insert((profile.to_owned(), facet.to_owned()))
        {
            return Err("P17 phase profile/facet 範圍外／重複".into());
        }
        let artifact = b01_artifacts(root, profile)?;
        let binary = phase_builds
            .get(profile)
            .cloned()
            .unwrap_or_else(|| artifact.binary.clone());
        if facet == "platform" {
            if !assert_warning_active || !phase_builds.contains_key(profile) {
                return Err("P17 phase platform 無 fresh CLI build".into());
            }
            validate_phase_platform_check(
                root,
                &environment,
                &registry,
                check,
                profile,
                &binary,
                &artifact.suite,
                host_active,
                error_active,
                console_active,
            )?;
            continue;
        }
        if string(check, "case_id")? != "COMPLETE-001"
            || string(check, "facet")? != "full-suite"
            || string(check, "operation")? != "cli-all-lua"
            || string(check, "execution_path")? != "cli-rust-vm"
            || string(check, "status")? != "PASS"
            || integer(check, "exit_code")? != 0
            || integer(check, "matched")? != 1
            || integer(check, "passed")? != 1
            || integer(check, "failed")? != 0
            || integer(check, "ignored")? != 0
            || strings(check, "command")? != [binary.path.clone(), "all.lua".into()]
            || string(check, "cwd")? != artifact.suite.display().to_string()
            || !array(check, "negative_runs")?.is_empty()
        {
            return Err("P17 phase suite command/count 不符".into());
        }
        let expected_env = runner::effective_native_environment(Path::new(&artifact.grant.path));
        let observed_env = array(check, "environment")?
            .iter()
            .map(|item| {
                object(item, &["name", "value"])?;
                Ok((
                    string(item, "name")?.to_owned(),
                    string(item, "value")?.to_owned(),
                ))
            })
            .collect::<Result<Vec<_>, String>>()?;
        if observed_env != expected_env {
            return Err("P17 phase suite env 不符".into());
        }
        let inputs = array(check, "inputs")?;
        let expected_inputs = [
            binary,
            artifact.grant,
            report::Input::from_path(&artifact.suite.join("all.lua"))?,
        ];
        if inputs.len() != 3 {
            return Err("P17 phase suite inputs 數不符".into());
        }
        for (item, expected) in inputs.iter().zip(expected_inputs) {
            let actual = input(item)?;
            if actual.path != expected.path || actual.sha256 != expected.sha256 {
                return Err("P17 phase suite input 不符".into());
            }
        }
        let log = Path::new(string(check, "log_path")?);
        if !log.starts_with(&environment.evidence_dir) {
            return Err("P17 phase suite log 越界".into());
        }
        sha(log, string(check, "log_sha256")?)?;
        let body = fs::read_to_string(log).map_err(|error| error.to_string())?;
        if !body.lines().any(|line| line.trim() == "final OK !!!") || !body.contains("total time:")
        {
            return Err("P17 phase suite final marker 缺失".into());
        }
    }
    if !PROFILES.iter().all(|profile| {
        seen.contains(&(profile.to_string(), "full-suite".into()))
            && (!assert_warning_active || seen.contains(&(profile.to_string(), "platform".into())))
    }) {
        return Err("P17 phase suite/platform profile 缺失".into());
    }
    Ok(())
}

