    #[test]
    fn p17_phase_host_entry_review_rejects_unknown_or_missing_changes() {
        let body = format!(
            "{{\"schema\":\"rivetlua-p17-host-entry-impact-v1\",\"baseline_manifest_sha256\":\"{HOST_ENTRY_BASELINE_SHA}\",\"coroutine_baseline_sha256\":\"{HOST_ENTRY_COROUTINE_BASELINE_SHA}\",\"unwind_baseline_sha256\":\"{HOST_ENTRY_UNWIND_BASELINE_SHA}\",\"gate14_archive_sha256\":\"{HOST_ENTRY_GATE14_ARCHIVE_SHA}\",\"gate14_report_sha256\":\"{HOST_ENTRY_GATE14_REPORT_SHA}\",\"exit_review_sha256\":\"{}\",\"changes\":[],\"review_note\":\"固定 callback 前後態審查\"}}",
            "a".repeat(64)
        );
        let valid = StrictJsonParser::parse(&body).unwrap();
        assert!(host_entry_review_header(&valid, &"a".repeat(64)).is_ok());
        for invalid in [
            body.replace(HOST_ENTRY_BASELINE_SHA, &"0".repeat(64)),
            body.replace(HOST_ENTRY_COROUTINE_BASELINE_SHA, &"0".repeat(64)),
            body.replace(HOST_ENTRY_UNWIND_BASELINE_SHA, &"0".repeat(64)),
            body.replace(HOST_ENTRY_GATE14_REPORT_SHA, &"0".repeat(64)),
            body.replace("\"changes\":[]", "\"unknown\":[]"),
        ] {
            assert!(host_entry_review_header(
                &StrictJsonParser::parse(&invalid).unwrap(),
                &"a".repeat(64)
            )
            .is_err());
        }
        assert!(host_entry_review_header(&valid, &"b".repeat(64)).is_err());
        let changed = [(HOST_ENTRY_PATHS[0], "b".repeat(64))];
        let accepts = |names: &[&str]| {
            let body = format!(
                "{{\"changes\":[{}]}}",
                names
                    .iter()
                    .map(|name| format!("{{\"path\":{}}}", report::q(name)))
                    .collect::<Vec<_>>()
                    .join(",")
            );
            let value = StrictJsonParser::parse(&body).unwrap();
            host_entry_changed_rows(&changed, array(&value, "changes").unwrap()).is_ok()
        };
        assert!(accepts(&[HOST_ENTRY_PATHS[0]]));
        for bad in [
            &[][..],
            &[HOST_ENTRY_PATHS[1]][..],
            &[HOST_ENTRY_PATHS[0], HOST_ENTRY_PATHS[0]][..],
            &["crates/rivetlua-runtime/src/unrelated.rs"][..],
        ] {
            assert!(!accepts(bad));
        }
        let both = [
            (HOST_ENTRY_PATHS[0], "b".repeat(64)),
            (HOST_ENTRY_PATHS[1], "c".repeat(64)),
        ];
        let parsed = StrictJsonParser::parse(&format!(
            "{{\"changes\":[{{\"path\":{}}},{{\"path\":{}}}]}}",
            report::q(HOST_ENTRY_PATHS[0]),
            report::q(HOST_ENTRY_PATHS[1])
        ))
        .unwrap();
        assert!(host_entry_changed_rows(&both, array(&parsed, "changes").unwrap()).is_ok());
        let reversed = StrictJsonParser::parse(&format!(
            "{{\"changes\":[{{\"path\":{}}},{{\"path\":{}}}]}}",
            report::q(HOST_ENTRY_PATHS[1]),
            report::q(HOST_ENTRY_PATHS[0])
        ))
        .unwrap();
        assert!(host_entry_changed_rows(&both, array(&reversed, "changes").unwrap()).is_err());
        let all = [
            (HOST_ENTRY_PATHS[0], "b".repeat(64)),
            (HOST_ENTRY_PATHS[1], "c".repeat(64)),
            (HOST_ENTRY_PATHS[2], "d".repeat(64)),
        ];
        let parsed = StrictJsonParser::parse(&format!(
            "{{\"changes\":[{{\"path\":{}}},{{\"path\":{}}},{{\"path\":{}}}]}}",
            report::q(HOST_ENTRY_PATHS[0]),
            report::q(HOST_ENTRY_PATHS[1]),
            report::q(HOST_ENTRY_PATHS[2])
        ))
        .unwrap();
        assert!(host_entry_changed_rows(&all, array(&parsed, "changes").unwrap()).is_ok());
        let all_four = [
            (HOST_ENTRY_PATHS[0], "b".repeat(64)),
            (HOST_ENTRY_PATHS[1], "c".repeat(64)),
            (HOST_ENTRY_PATHS[2], "d".repeat(64)),
            (HOST_ENTRY_PATHS[3], "e".repeat(64)),
        ];
        let parsed = StrictJsonParser::parse(&format!(
            "{{\"changes\":[{{\"path\":{}}},{{\"path\":{}}},{{\"path\":{}}},{{\"path\":{}}}]}}",
            report::q(HOST_ENTRY_PATHS[0]),
            report::q(HOST_ENTRY_PATHS[1]),
            report::q(HOST_ENTRY_PATHS[2]),
            report::q(HOST_ENTRY_PATHS[3])
        ))
        .unwrap();
        assert!(host_entry_changed_rows(&all_four, array(&parsed, "changes").unwrap()).is_ok());
        let missing_unwind = StrictJsonParser::parse(&format!(
            "{{\"changes\":[{{\"path\":{}}},{{\"path\":{}}},{{\"path\":{}}}]}}",
            report::q(HOST_ENTRY_PATHS[0]),
            report::q(HOST_ENTRY_PATHS[1]),
            report::q(HOST_ENTRY_PATHS[2])
        ))
        .unwrap();
        assert!(host_entry_changed_rows(
            &all_four,
            array(&missing_unwind, "changes").unwrap()
        )
        .is_err());
        let callback_coroutine = [
            (HOST_ENTRY_PATHS[0], "b".repeat(64)),
            (HOST_ENTRY_PATHS[2], "d".repeat(64)),
        ];
        let parsed = StrictJsonParser::parse(&format!(
            "{{\"changes\":[{{\"path\":{}}},{{\"path\":{}}}]}}",
            report::q(HOST_ENTRY_PATHS[0]),
            report::q(HOST_ENTRY_PATHS[2])
        ))
        .unwrap();
        assert!(host_entry_changed_rows(
            &callback_coroutine,
            array(&parsed, "changes").unwrap()
        )
        .is_ok());
    }

    #[test]
    fn p17_phase_host_entry_overlay_requires_exact_old_endpoint() {
        let relative = HOST_ENTRY_PATHS[0];
        let mut old_sources = BTreeMap::new();
        old_sources.insert(
            relative.into(),
            report::HistoricalSource {
                before_sha256: HOST_ENTRY_CALLBACK_BEFORE_SHA.into(),
                snapshot: PathBuf::from("/fixed/immutable-callback"),
            },
        );
        let mut changed_after = BTreeMap::new();
        changed_after.insert(relative.into(), "b".repeat(64));
        let review = HostEntryReview {
            input: report::Input { path: "/fixed/review".into(), sha256: "a".repeat(64) },
            baseline: report::Input { path: "/fixed/baseline".into(), sha256: "a".repeat(64) },
            coroutine_baseline: report::Input { path: "/fixed/coroutine-baseline".into(), sha256: "a".repeat(64) },
            unwind_baseline: report::Input { path: "/fixed/unwind-baseline".into(), sha256: "a".repeat(64) },
            gate14_archive: report::Input { path: "/fixed/archive".into(), sha256: "a".repeat(64) },
            old_sources,
            changed_after,
        };
        let mut expected = BTreeMap::from([(PathBuf::from(relative), HOST_ENTRY_CALLBACK_BEFORE_SHA.into())]);
        assert!(host_entry_overlay_current_sources(&mut expected, &review).is_ok());
        assert_eq!(expected[Path::new(relative)], "b".repeat(64));
        for mut bad in [
            BTreeMap::new(),
            BTreeMap::from([(PathBuf::from(relative), "0".repeat(64))]),
        ] {
            assert!(host_entry_overlay_current_sources(&mut bad, &review).is_err());
        }
        let mut review = review;
        review.changed_after.insert("src/unknown.rs".into(), "c".repeat(64));
        let mut expected = BTreeMap::from([(PathBuf::from(relative), HOST_ENTRY_CALLBACK_BEFORE_SHA.into())]);
        assert!(host_entry_overlay_current_sources(&mut expected, &review).is_err());
    }

    #[test]
    fn p17_phase_b03_error_preserves_earlier_console_endpoint() {
        let root = std::env::temp_dir().join(format!(
            "p17-b03-errors-{}-{}",
            std::process::id(),
            SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()
        ));
        fs::create_dir_all(&root).unwrap();
        let relative = HOST_ENTRY_PATHS[1];
        let path = root.join(relative).display().to_string();
        let earliest_snapshot = root.join("console-errors.rs");
        let warning_snapshot = root.join("warning-errors.rs");
        fs::write(&earliest_snapshot, b"earliest errors\n").unwrap();
        fs::write(&warning_snapshot, b"warning errors\n").unwrap();
        let earliest = manifest::sha256(&earliest_snapshot).unwrap();
        let warning = manifest::sha256(&warning_snapshot).unwrap();
        let console = BTreeMap::from([(
            path.clone(),
            report::HistoricalSource {
                before_sha256: earliest.clone(),
                snapshot: earliest_snapshot.clone(),
            },
        )]);
        let host = BTreeMap::from([(
            relative.to_owned(),
            report::HistoricalSource {
                before_sha256: warning.clone(),
                snapshot: warning_snapshot.clone(),
            },
        )]);
        let mut view = report::PhaseSourceView::new();
        view.insert(
            path.clone(),
            report::HistoricalSource {
                before_sha256: earliest.clone(),
                snapshot: earliest_snapshot.clone(),
            },
        );
        let preserve = || {
            preserve_prior_error_historical_input(
                &root,
                relative,
                &earliest,
                &warning,
                &view,
                &console,
                Some(&host),
            )
        };
        assert_eq!(preserve().unwrap(), true);
        let observed = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&path),
            report::q(&earliest),
        ))
        .unwrap();
        assert_eq!(report::historical_input(&observed, &view).unwrap(), Some(path.clone()));
        assert!(!preserve_prior_error_historical_input(
            &root, relative, &earliest, &warning, &view, &console, None,
        ).unwrap());
        assert!(!preserve_prior_error_historical_input(
            &root, "other.rs", &earliest, &warning, &view, &console, Some(&host),
        ).unwrap());
        let bad_host = BTreeMap::from([(
            relative.to_owned(),
            report::HistoricalSource {
                before_sha256: "0".repeat(64),
                snapshot: warning_snapshot,
            },
        )]);
        assert!(preserve_prior_error_historical_input(
            &root, relative, &earliest, &warning, &view, &console, Some(&bad_host),
        ).is_err());
        assert!(preserve_prior_error_historical_input(
            &root, relative, &earliest, &warning, &view, &BTreeMap::new(), Some(&host),
        ).is_err());
        assert!(preserve_prior_error_historical_input(
            &root, relative, &"0".repeat(64), &warning, &view, &console, Some(&host),
        ).is_err());
        let mut wrong_view = report::PhaseSourceView::new();
        wrong_view.insert(
            path.clone(),
            report::HistoricalSource {
                before_sha256: warning.clone(),
                snapshot: host.get(relative).unwrap().snapshot.clone(),
            },
        );
        assert!(preserve_prior_error_historical_input(
            &root, relative, &earliest, &warning, &wrong_view, &console, Some(&host),
        ).is_err());
        fs::write(&host.get(relative).unwrap().snapshot, b"tampered host\n").unwrap();
        assert!(preserve().is_err());
        fs::write(&host.get(relative).unwrap().snapshot, b"warning errors\n").unwrap();
        fs::write(&earliest_snapshot, b"tampered\n").unwrap();
        assert!(preserve().is_err());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    #[ignore = "需固定P17外接證據；僅驗cached phase review，不執行suite或build"]
