    #[test]
    fn p17_phase_cli_binary_prefix_root_review_rejects_wrong_contract() {
        let original = Path::new("/fixed/repo");
        let directory = std::env::temp_dir().join(format!(
            "p17-cli-binary-review-shape-{}-{}",
            std::process::id(),
            SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos(),
        ));
        fs::create_dir(&directory).unwrap();
        let evidence = fs::canonicalize(&directory).unwrap();
        let terminal = evidence.join("synthetic-terminal.txt");
        fs::write(&terminal, b"schema fixture only\n").unwrap();
        let terminal_sha = manifest::sha256(&terminal).unwrap();
        let source_paths = [
            EXIT_CLI_BINARY_TEST_PATH,
            EXIT_CLI_BINARY_PATH,
            "crates/rivetlua-runtime/src/vm/mod.rs",
            "crates/rivetlua/src/lib.rs",
            EXIT_PARSER_PATH,
            "crates/rivetlua-core/src/bytecode/input.rs",
        ];
        let terminal_ref = format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&terminal.display().to_string()),
            report::q(&terminal_sha),
        );
        let valid_shape = format!(
            "{{\"schema\":\"rivetlua-p17-cli-binary-prefix-root-review-v1\",\"status\":\"PASS\",\"kind\":\"public\",\"repository_root\":{},\"cli_sha256\":{},\"source_paths\":[{}],\"terminal_records\":[{terminal_ref}],\"artifact_checks\":[\"checked\"],\"input_basis\":[\"checked\"],\"checks\":[\"checked\"],\"review_note\":\"合成schema測試，不是公開測試證據\"}}",
            report::q(&original.display().to_string()),
            report::q(EXIT_CLI_BINARY_AFTER_SHA),
            source_paths.iter().map(|path| report::q(path)).collect::<Vec<_>>().join(","),
        );
        let parsed = StrictJsonParser::parse(&valid_shape).unwrap();
        assert!(exit_cli_binary_root_review_shape(&parsed, original, &evidence, true, &source_paths).is_ok());
        let synthetic_unit = valid_shape.replace("\"kind\":\"public\"", "\"kind\":\"unit\"");
        assert!(exit_cli_binary_root_review_shape(
            &StrictJsonParser::parse(&synthetic_unit).unwrap(), original, &evidence, false, &source_paths,
        ).is_err());
        for invalid in [
            valid_shape.replace("rivetlua-p17-cli-binary-prefix-root-review-v1", "other"),
            valid_shape.replace("\"status\":\"PASS\"", "\"status\":\"FAIL\""),
            valid_shape.replace("\"kind\":\"public\"", "\"kind\":\"unit\""),
            valid_shape.replace("/fixed/repo", "/fixed/other"),
            valid_shape.replace(EXIT_CLI_BINARY_AFTER_SHA, EXIT_CLI_LIB_TEST_ONLY_SHA),
            valid_shape.replace(
                &format!("[{},{}", report::q(EXIT_CLI_BINARY_TEST_PATH), report::q(EXIT_CLI_BINARY_PATH)),
                &format!("[{},{}", report::q(EXIT_CLI_BINARY_PATH), report::q(EXIT_CLI_BINARY_TEST_PATH)),
            ),
            valid_shape.replace(&format!("[{terminal_ref}]"), "[]"),
            valid_shape.replace("\"artifact_checks\":[\"checked\"]", "\"artifact_checks\":[]"),
            valid_shape.replace("\"input_basis\":[\"checked\"]", "\"input_basis\":[]"),
            valid_shape.replace("\"checks\":[\"checked\"]", "\"checks\":[]"),
            valid_shape.replace("\"checks\":", "\"extra\":true,\"checks\":"),
            valid_shape.replace("\"sha256\":", "\"unknown\":"),
            valid_shape.replace("\"checks\":", "\"unknown\":"),
        ] {
            assert_ne!(invalid, valid_shape);
            assert!(exit_cli_binary_root_review_shape(
                &StrictJsonParser::parse(&invalid).unwrap(), original, &evidence, true, &source_paths,
            ).is_err());
        }
        fs::remove_dir_all(directory).unwrap();
    }

