    #[test]
    fn p17_phase_cli_version_banner_public_shape_profile_and_names_fail_closed() {
        let readiness = Path::new("/fixed/evidence/readiness.json");
        let root = Path::new("/fixed/repo");
        let names = [
            "p17_version_flag_with_execute_prints_full_banner_then_program_output",
            "p17_version_flag_does_not_execute_stdin",
            "p17_repl_eof_prints_full_banner_and_exact_prompt_termination",
        ];
        let command = [
            EXIT_SAFE_CARGO, "test", "--locked", "-p", "rivetlua-cli", "--no-default-features",
            "--features", "native-lua55", "--test", "p17_version_banner", "--", "--nocapture", "--test-threads=1",
        ];
        let row = format!(
            "{{\"profile\":\"lua55\",\"command\":[{}],\"cwd\":{},\"environment_mode\":\"env -i\",\"environment\":{{}},\"exit_code\":0,\"matched\":3,\"passed\":3,\"failed\":0,\"ignored\":0,\"filtered\":0,\"log_path\":\"/fixed/log\",\"log_sha256\":\"digest\",\"running_binary_path\":\"/fixed/driver\",\"snapshot_path\":\"/fixed/snapshot\",\"snapshot_sha256\":\"digest\",\"source_inputs\":[],\"cli_running_binary_path\":\"/fixed/cli\",\"cli_snapshot_path\":\"/fixed/cli-snapshot\",\"cli_snapshot_sha256\":\"digest\"}}",
            command.iter().map(|part| report::q(part)).collect::<Vec<_>>().join(","),
            report::q(&root.display().to_string()),
        );
        let parsed_row = StrictJsonParser::parse(&row).unwrap();
        let environment = StrictJsonParser::parse("{}").unwrap();
        assert!(exit_cli_version_row_identity(&parsed_row, "lua55", root, &environment).is_ok());
        assert!(exit_cli_version_row_identity(&parsed_row, "lua54", root, &environment).is_err());
        for bad in [
            row.replace("\"profile\":\"lua55\"", "\"profile\":\"lua54\""),
            row.replace("native-lua55", "native-lua54,default-lua54"),
            row.replace("\"matched\":3", "\"matched\":2"),
        ] {
            assert!(exit_cli_version_row_identity(
                &StrictJsonParser::parse(&bad).unwrap(), "lua55", root, &environment,
            ).is_err());
        }
        let proof = format!(
            "{{\"status\":\"PASS\",\"reported_by\":\"primary root\",\"root_review\":\"attested\",\"readiness_path\":{},\"readiness_sha256\":\"2aff15a88577e4871008b29a7ed039203f1d81ffad39d84487d3a66fbb382acb\",\"rows\":[{row},{row}]}}",
            report::q(&readiness.display().to_string()),
        );
        assert!(exit_cli_version_leaf_shape(&StrictJsonParser::parse(&proof).unwrap(), readiness).is_ok());
        for bad in [
            proof.replace("\"PASS\"", "\"FAIL\""),
            proof.replace("primary root", "worker"),
            proof.replacen("\"source_inputs\":", "\"unknown\":", 1),
            proof.replacen("\"rows\":", "\"extra\":true,\"rows\":", 1),
        ] {
            assert!(exit_cli_version_leaf_shape(&StrictJsonParser::parse(&bad).unwrap(), readiness).is_err());
        }
        let log = format!(
            "running 3 tests\n{}\ntest result: ok. 3 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out;\n",
            names.iter().map(|name| format!("test {name} ... ok")).collect::<Vec<_>>().join("\n"),
        );
        assert!(parse_named_log_with_filter(&log, &names, false).is_ok());
        assert!(parse_named_log_with_filter(&log.replace(names[0], "wrong_name"), &names, false).is_err());
        let evidence = Path::new("/fixed/evidence");
        let update = StrictJsonParser::parse(&format!(
            "{{\"public_proof_path\":{}}}",
            report::q(&evidence.join(EXIT_CLI_VERSION_PROOF_DIR).join("public/result.json").display().to_string()),
        )).unwrap();
        assert!(exit_cli_version_public_leaf(root, root, evidence, &update, false).is_err());
    }

    #[test]
    fn p17_phase_cli_version_banner_root_review_requires_terminal_attestation() {
        let directory = std::env::temp_dir().join(format!(
            "p17-version-banner-root-review-{}-{}",
            std::process::id(),
            SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos(),
        ));
        let terminal_dir = directory.join(EXIT_CLI_VERSION_PROOF_DIR);
        fs::create_dir_all(&terminal_dir).unwrap();
        let evidence = fs::canonicalize(&directory).unwrap();
        let terminal = evidence.join(EXIT_CLI_VERSION_PROOF_DIR).join("terminal-completion.json");
        fs::write(&terminal, b"synthetic attestation\n").unwrap();
        let terminal_sha = manifest::sha256(&terminal).unwrap();
        let original = Path::new("/fixed/repo");
        let source_paths = [
            EXIT_CLI_VERSION_TEST_PATH,
            EXIT_CLI_BINARY_PATH,
            "crates/rivetlua-runtime/src/vm/mod.rs",
            "crates/rivetlua/src/lib.rs",
            EXIT_PARSER_PATH,
            "crates/rivetlua-core/src/bytecode/input.rs",
        ];
        let valid = format!(
            "{{\"schema\":\"rivetlua-p17-cli-version-banner-root-review-v1\",\"status\":\"PASS\",\"kind\":\"public\",\"repository_root\":{},\"cli_sha256\":{},\"source_paths\":[{}],\"terminal_records\":[{{\"path\":{},\"sha256\":{}}}],\"artifact_checks\":[\"checked\"],\"input_basis\":[\"checked\"],\"checks\":[\"checked\"],\"review_note\":\"synthetic schema check only\"}}",
            report::q(&original.display().to_string()), report::q(EXIT_CLI_VERSION_AFTER_SHA),
            source_paths.iter().map(|path| report::q(path)).collect::<Vec<_>>().join(","),
            report::q(&terminal.display().to_string()), report::q(&terminal_sha),
        );
        assert!(exit_cli_version_root_review_shape(
            &StrictJsonParser::parse(&valid).unwrap(), original, &evidence,
            EXIT_CLI_VERSION_AFTER_SHA, &source_paths,
        ).is_ok());
        for bad in [
            valid.replace("rivetlua-p17-cli-version-banner-root-review-v1", "unknown"),
            valid.replace("\"status\":\"PASS\"", "\"status\":\"FAIL\""),
            valid.replace("\"kind\":\"public\"", "\"kind\":\"unit\""),
            valid.replace(&terminal.display().to_string(), "/fixed/other.json"),
            valid.replace(&terminal_sha, &"0".repeat(64)),
            valid.replace("\"artifact_checks\":[\"checked\"]", "\"artifact_checks\":[]"),
            valid.replacen("\"checks\":", "\"unknown\":", 1),
        ] {
            assert!(exit_cli_version_root_review_shape(
                &StrictJsonParser::parse(&bad).unwrap(), original, &evidence,
                EXIT_CLI_VERSION_AFTER_SHA, &source_paths,
            ).is_err());
        }
        fs::remove_dir_all(directory).unwrap();
    }

