    #[test]
    fn p17_phase_platform_identity_and_environment_are_closed() {
        let profile = PROFILES[0];
        let binary = report::Input {
            path: "/fixed/fresh-rivetlua".into(),
            sha256: "a".repeat(64),
        };
        let suite = Path::new("/fixed/suite");
        let platform = Path::new("/fixed/platform.lua");
        let environment = runner::effective_no_native_environment()
            .iter()
            .map(|(name, value)| {
                format!(
                    "{{\"name\":{},\"value\":{}}}",
                    report::q(name),
                    report::q(value)
                )
            })
            .collect::<Vec<_>>()
            .join(",");
        let good = format!(
            "{{\"case_id\":\"COMPLETE-004\",\"facet\":\"platform\",\"operation\":\"b03-platform-cli\",\"execution_path\":\"cli-rust-vm\",\"profile\":{},\"status\":\"PASS\",\"exit_code\":0,\"matched\":1,\"passed\":1,\"failed\":0,\"ignored\":0,\"command\":[{},{}],\"cwd\":{},\"negative_runs\":[],\"environment\":[{environment}]}}",
            report::q(profile),
            report::q(&binary.path),
            report::q(&platform.display().to_string()),
            report::q(&suite.display().to_string()),
        );
        let valid = StrictJsonParser::parse(&good).unwrap();
        assert!(phase_platform_identity(&valid, profile, &binary, suite, platform).is_ok());
        assert!(phase_platform_environment(&valid).is_ok());
        for bad in [
            good.replace("COMPLETE-004", "COMPLETE-001"),
            good.replace("\"facet\":\"platform\"", "\"facet\":\"full-suite\""),
            good.replace("b03-platform-cli", "cli-all-lua"),
            good.replace("lua55-i64f64", "lua54-i64f64"),
            good.replace("/fixed/fresh-rivetlua", "/fixed/old-rivetlua"),
            good.replace("/fixed/platform.lua", "/fixed/all.lua"),
            good.replace("/fixed/suite", "/fixed/other-suite"),
            good.replace("\"exit_code\":0", "\"exit_code\":1"),
            good.replace("\"matched\":1", "\"matched\":0"),
            good.replace("\"passed\":1", "\"passed\":0"),
            good.replace("\"failed\":0", "\"failed\":1"),
            good.replace("\"ignored\":0", "\"ignored\":1"),
            good.replace("\"negative_runs\":[]", "\"negative_runs\":[{}]"),
        ] {
            let value = StrictJsonParser::parse(&bad).unwrap();
            assert!(
                phase_platform_identity(&value, profile, &binary, suite, platform).is_err(),
                "{bad}"
            );
        }
        let changed_environment =
            StrictJsonParser::parse(&good.replacen("\"value\":\"unset\"", "\"value\":\"set\"", 1))
                .unwrap();
        assert!(phase_platform_environment(&changed_environment).is_err());
    }

    #[test]
    fn p17_phase_platform_report_requires_two_fresh_facets() {
        let make_check = |profile: &str, platform: bool| {
            let mut check = report::Check::pending(
                if platform { "platform" } else { "full-suite" },
                Some(profile),
                "已驗證",
            );
            check.case_id = if platform {
                "COMPLETE-004"
            } else {
                "COMPLETE-001"
            }
            .into();
            check.operation = if platform {
                "b03-platform-cli"
            } else {
                "cli-all-lua"
            };
            check.execution_path = "cli-rust-vm";
            check.status = "PASS";
            check.matched = 1;
            check.passed = 1;
            check.exit_code = Some(0);
            check
        };
        let mut report = report::Report::new(None);
        for profile in PROFILES {
            report.checks.push(make_check(profile, false));
        }
        assert!(report.pass());
        assert!(report
            .json()
            .contains("\"declared_facets\":[\"batch-dependency\",\"full-suite\"]"));
        report.phase = Some(PhaseEvidence {
            review: report::Input {
                path: "/fixed/review".into(),
                sha256: "a".repeat(64),
            },
            host_review: None,
            error_review: None,
            console_review: None,
            assert_warning_review: Some(report::Input {
                path: "/fixed/assert-warning-review".into(),
                sha256: "b".repeat(64),
            }),
            exit_review: None,
            host_entry_review: None,
            gc_review: None,
            producer_update_review: None,
            debug_vm_review: None,
            debug_hook_review: None,
            final_source_review: None,
            builds: Vec::new(),
        });
        assert!(!report.pass());
        assert!(report
            .json()
            .contains("\"declared_facets\":[\"batch-dependency\",\"full-suite\",\"platform\"]"));
        report.checks.push(make_check(PROFILES[0], true));
        assert!(!report.pass());
        report.checks.push(make_check(PROFILES[1], true));
        assert!(report.pass());
        report.checks[3].status = "FAIL";
        assert!(!report.pass());
    }

