    #[test]
    fn p17_b03_named_nocapture_layouts() {
        let same_line = "running 1 test\ntest p17_fuzz_parser ... P17_B03_CASE {\"case_id\":\"p17_fuzz_parser\"}\nok\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n";
        let (counts, outcomes) = parse_named_log(same_line, &["p17_fuzz_parser"]).unwrap();
        assert_eq!(
            counts,
            NamedCounts {
                matched: 1,
                passed: 1,
                failed: 0,
                ignored: 0
            }
        );
        assert_eq!(outcomes.get("p17_fuzz_parser"), Some(&"ok"));
        let separate = same_line.replace(
            "test p17_fuzz_parser ... P17_B03_CASE",
            "test p17_fuzz_parser ... \nP17_B03_CASE",
        );
        assert_eq!(
            parse_named_log(&separate, &["p17_fuzz_parser"]).unwrap().0,
            counts
        );
        let direct = same_line.replace(
            "test p17_fuzz_parser ... P17_B03_CASE {\"case_id\":\"p17_fuzz_parser\"}\nok",
            "test p17_fuzz_parser ... ok\nP17_B03_CASE {\"case_id\":\"p17_fuzz_parser\"}",
        );
        assert_eq!(
            parse_named_log(&direct, &["p17_fuzz_parser"]).unwrap().0,
            counts
        );
        let diagnostic = "running 1 test\ntest p17_fuzz_parser ... P17 GC2 起點：profile=Lua54\nmore diagnostics with ok text\nok\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n";
        assert_eq!(parse_named_log(diagnostic, &["p17_fuzz_parser"]).unwrap().0, counts);
    }

    #[test]
    fn p17_b03_named_fail_closed() {
        let ok = "test p17_fuzz_parser ... ok\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n";
        for body in [
            ok.replace("p17_fuzz_parser", "other_test"),
            ok.replace("test result: ok. 1 passed", "test result: ok. 0 passed"),
            ok.replace("0 filtered out", "1 filtered out"),
            ok.replace("test result: ok.", "test result: FAILED."),
            format!("test p17_fuzz_parser ... ok\n{ok}"),
            "test result: ok. 0 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n".into(),
            "test p17_fuzz_parser ... P17 GC2 起點\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n".into(),
            "test p17_fuzz_parser ... P17 GC2 起點\ntest p17_fuzz_parser ... ok\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n".into(),
            "test p17_fuzz_parser ... diagnostic says ok but no terminal\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n".into(),
            format!("ok\n{ok}"),
        ] { assert!(parse_named_log(&body,&["p17_fuzz_parser"]).is_err(),"{body}"); }
        let failed = "test p17_fuzz_parser ... FAILED\ntest result: FAILED. 0 passed; 1 failed; 0 ignored; 0 measured; 0 filtered out; finished in 0.01s\n";
        assert_eq!(
            parse_named_log(failed, &["p17_fuzz_parser"])
                .unwrap()
                .0
                .failed,
            1
        );
        let ignored = "test p17_fuzz_parser ... ignored\ntest result: ok. 0 passed; 0 failed; 1 ignored; 0 measured; 0 filtered out; finished in 0.01s\n";
        assert_eq!(
            parse_named_log(ignored, &["p17_fuzz_parser"])
                .unwrap()
                .0
                .ignored,
            1
        );
    }

