    #[test]
    fn p17_b03_platform_probe_distinguishes_availability() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let registry = parse_registry(root, "aarch64-apple-darwin").unwrap();
        let available = StrictJsonParser::parse("{\"case_id\":\"p17_platform_c\",\"profile\":\"lua55-i64f64\",\"seed\":0,\"iterations\":1,\"outcome\":\"PASS\",\"platform\":\"aarch64-apple-darwin\",\"compiler\":\"clang\",\"sizes\":{\"int\":4,\"long\":8,\"long_long\":8,\"pointer\":8,\"float\":4,\"double\":8,\"long_double\":16},\"capabilities\":{\"tmpnam\":\"available\",\"tmpnam_category\":\"name-returned\",\"tmpnam_errno\":0,\"tmpnam_diagnostic\":\"\"}}").unwrap();
        let spec = CASES
            .iter()
            .copied()
            .find(|item| item.id == "p17_platform_c")
            .unwrap();
        assert!(validate_record(&available, spec, "lua55-i64f64", &registry, false).is_ok());
        let unsupported = StrictJsonParser::parse(
            &canonical_json(&available)
                .replace("\"available\"", "\"unsupported\"")
                .replace("\"name-returned\"", "\"C_TMPNAM_UNAVAILABLE\"")
                .replace(
                    "\"tmpnam_diagnostic\":\"\"",
                    "\"tmpnam_diagnostic\":\"tmpnam returned NULL\"",
                ),
        )
        .unwrap();
        assert!(validate_record(&unsupported, spec, "lua55-i64f64", &registry, false).is_ok());
        let false_success = StrictJsonParser::parse(
            &canonical_json(&available).replace("\"name-returned\"", "\"C_TMPNAM_UNAVAILABLE\""),
        )
        .unwrap();
        assert!(validate_record(&false_success, spec, "lua55-i64f64", &registry, false).is_err());
    }

    #[test]
    fn p17_b03_platform_cli_time_policy_is_closed() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let registry = parse_registry(root, "aarch64-apple-darwin").unwrap();
        let body = "{\"case_id\":\"p17_platform_cli\",\"profile\":\"lua55-i64f64\",\"seed\":0,\"iterations\":1,\"outcome\":\"PASS\",\"capabilities\":{\"os_tmpname\":\"denied\",\"os_tmpname_error\":\"E_HOST_POLICY_OS\",\"os_time\":\"available\",\"os_time_result_type\":\"number\",\"os_execute\":\"denied\",\"os_execute_error\":\"E_HOST_POLICY_OS\",\"os_difftime\":\"available\",\"package_loadlib\":\"denied\",\"package_loadlib_error\":\"native-grant: preflight\",\"package_loadlib_when\":\"open\"}}";
        let spec = CASES
            .iter()
            .copied()
            .find(|item| item.id == "p17_platform_cli")
            .unwrap();
        let valid = StrictJsonParser::parse(body).unwrap();
        assert!(validate_record(&valid, spec, "lua55-i64f64", &registry, false).is_ok());
        for changed in [
            body.replace("\"os_time\":\"available\"", "\"os_time\":\"denied\""),
            body.replace(
                "\"os_time_result_type\":\"number\"",
                "\"os_time_result_type\":\"string\"",
            ),
            body.replace("\"os_tmpname\":\"denied\"", "\"os_tmpname\":\"available\""),
            body.replace("\"os_execute\":\"denied\"", "\"os_execute\":\"available\""),
            body.replace(
                "\"os_tmpname_error\":\"E_HOST_POLICY_OS\"",
                "\"os_tmpname_error\":\"other\"",
            ),
            body.replace(
                "\"os_execute_error\":\"E_HOST_POLICY_OS\"",
                "\"os_execute_error\":\"other\"",
            ),
            body.replace(
                "\"os_difftime\":\"available\"",
                "\"os_difftime\":\"denied\"",
            ),
            body.replace(
                "\"package_loadlib_error\":\"native-grant: preflight\"",
                "\"package_loadlib_error\":\"other\"",
            ),
            body.replace("\"os_time_result_type\":\"number\",", ""),
        ] {
            let value = StrictJsonParser::parse(&changed).unwrap();
            assert!(
                validate_record(&value, spec, "lua55-i64f64", &registry, false).is_err(),
                "{changed}"
            );
        }
    }

    #[test]
    fn p17_phase_historical_view_rejects_unlisted_or_wrong_sha() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let evidence = runner::environment(root).unwrap().evidence_dir;
        let relative = PHASE_SOURCES[0].0;
        let path = root.join(relative);
        let mut view = report::PhaseSourceView::new();
        view.insert(
            path.display().to_string(),
            report::HistoricalSource {
                before_sha256: PHASE_SOURCES[0].1.into(),
                snapshot: evidence
                    .join("p17-phase-repair-baseline")
                    .join(relative.replace('/', "__")),
            },
        );
        let valid = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&path.display().to_string()),
            report::q(PHASE_SOURCES[0].1),
        ))
        .unwrap();
        assert_eq!(
            report::historical_input(&valid, &view).unwrap(),
            Some(path.display().to_string())
        );
        let wrong = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&path.display().to_string()),
            report::q(&"0".repeat(64)),
        ))
        .unwrap();
        assert!(report::historical_input(&wrong, &view).is_err());
        let unlisted = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&root.join("Cargo.lock").display().to_string()),
            report::q(PHASE_SOURCES[0].1),
        ))
        .unwrap();
        assert_eq!(report::historical_input(&unlisted, &view).unwrap(), None);
    }

    #[test]
    fn p17_final_manifest_report_view_maps_three_archived_inputs() {
        let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap();
        let evidence = runner::environment(root).unwrap().evidence_dir;
        let original_root = assert_warning_original_root(root, &evidence).unwrap();
        let verified = FinalVerifiedContext::verify(root, &evidence).unwrap().unwrap();
        let path = original_root.join("xtask/src/p17/manifest.rs").display().to_string();
        let old_sha = "3a90b8ce8e04e4323f7ba828abf708fa89c9060002f7bbf7194f05501c1c7155";
        let mut view = report::PhaseSourceView::new();
        assert!(bind_final_manifest_report_view(
            &original_root, root, &evidence, &mut view, None,
        ).is_err());
        bind_final_manifest_report_view(
            &original_root, root, &evidence, &mut view, Some(&verified),
        ).unwrap();
        assert!(bind_final_manifest_report_view(
            &original_root, root, &evidence, &mut view, Some(&verified),
        ).is_err());
        for name in ["gate-P17-B01.json", "gate-P17-B02.json", "gate-P17-B03.json"] {
            let report_path = root.join("target/rivetlua-reports").join(name);
            let report_value = StrictJsonParser::parse(
                &fs::read_to_string(&report_path).unwrap(),
            ).unwrap();
            let rows: Vec<_> = array(&report_value, "source_inputs").unwrap().iter()
                .filter(|row| string(row, "path").unwrap() == path)
                .collect();
            assert_eq!(rows.len(), 1, "{name}");
            assert_eq!(string(rows[0], "sha256").unwrap(), old_sha, "{name}");
            assert_eq!(report::historical_input(rows[0], &view).unwrap(), Some(path.clone()));
        }
        let wrong_sha = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}", report::q(&path), report::q(&"0".repeat(64)),
        )).unwrap();
        assert!(report::historical_input(&wrong_sha, &view).is_err());
        let wrong_path = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&original_root.join("xtask/src/p17/report.rs").display().to_string()),
            report::q(old_sha),
        )).unwrap();
        assert!(final_manifest_historical_input(
            &original_root, root, &evidence, &wrong_path, Some(&verified),
        ).unwrap().is_none());
    }

    #[test]
    fn p17_phase_regression_requires_two_real_named_passes() {
        let good = "test p17_native_open_call_pending_values_roundtrip ... ok\ntest p17_official_main_chunk_export ... ok\ntest result: ok. 2 passed; 0 failed; 0 ignored; 0 measured; 27 filtered out; finished in 0.01s\n";
        assert!(phase_regression_log(good).is_ok());
        assert!(parse_named_log(
            good,
            &[
                "p17_native_open_call_pending_values_roundtrip",
                "p17_official_main_chunk_export"
            ]
        )
        .is_err());
        for bad in [
            good.replace("p17_official_main_chunk_export", "unknown"),
            good.replace("test p17_official_main_chunk_export ... ok\n", ""),
            format!("test p17_official_main_chunk_export ... ok\n{good}"),
            good.replace("2 passed", "1 passed"),
            good.replace("... ok\ntest result", "... ignored\ntest result"),
            good.replace("... ok\ntest result", "... FAILED\ntest result"),
            "test result: ok. 0 passed; 0 failed; 0 ignored; 0 measured; 27 filtered out; finished in 0.01s\n".into(),
        ] {
            assert!(phase_regression_log(&bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn p17_phase_related_runtime_proof_is_required_and_closed() {
        let record = "{\"command\":[],\"cwd\":\"\",\"exit_code\":0,\"matched\":1,\"passed\":1,\"failed\":0,\"ignored\":0,\"log_path\":\"\",\"log_sha256\":\"\",\"source_inputs\":[],\"selectors\":[]}";
        let valid = StrictJsonParser::parse(&format!("{{\"related\":[{record}]}}")).unwrap();
        assert!(phase_related_record(&valid).is_ok());
        for bad in [
            "{}".to_owned(),
            "{\"related\":[]}".into(),
            format!("{{\"related\":[{record},{record}]}}"),
            "{\"related\":[{}]}".into(),
            format!(
                "{{\"related\":[{}]}}",
                record.replace("\"selectors\":[]", "\"selectors\":[],\"unexpected\":true")
            ),
        ] {
            let value = StrictJsonParser::parse(&bad).unwrap();
            assert!(phase_related_record(&value).is_err(), "{bad}");
        }
        let good = "test p17_export_open_call_runtime_semantics ... ok\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 13 filtered out; finished in 0.01s\n";
        assert!(phase_runtime_regression_log(good).is_ok());
        assert!(parse_named_log(good, &["p17_export_open_call_runtime_semantics"]).is_err());
        for bad in [
            good.replace("p17_export_open_call_runtime_semantics", "unknown"),
            good.replace("1 passed", "0 passed"),
            good.replace("... ok", "... ignored"),
            good.replace("... ok", "... FAILED"),
            format!("test p17_export_open_call_runtime_semantics ... ok\n{good}"),
            "test result: ok. 0 passed; 0 failed; 0 ignored; 0 measured; 13 filtered out; finished in 0.01s\n".into(),
        ] {
            assert!(phase_runtime_regression_log(&bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn p17_phase_host_review_header_and_sources_are_closed() {
        let good = format!(
            "{{\"schema\":\"rivetlua-p17-phase-host-impact-v1\",\"baseline_manifest_sha256\":{},\"accepted_export_review_sha256\":{},\"accepted_export_reuse_log_sha256\":{},\"b01_report_sha256\":{},\"b02_report_sha256\":{},\"b03_report_sha256\":{},\"changes\":[],\"regressions\":[],\"review_note\":\"審查已完成\"}}",
            report::q(HOST_BASELINE_SHA),
            report::q(ACCEPTED_EXPORT_REVIEW_SHA),
            report::q(ACCEPTED_EXPORT_REUSE_SHA),
            report::q(B01_SHA),
            report::q(B02_SHA),
            report::q(B03_SHA),
        );
        assert!(host_review_header(&StrictJsonParser::parse(&good).unwrap()).is_ok());
        for bad in [
            good.replace(HOST_BASELINE_SHA, &"0".repeat(64)),
            good.replace("\"baseline_manifest_sha256\":", "\"missing_sha\":"),
            good.replace("\"審查已完成\"", "\"\""),
            good.replace("\"changes\":[]", "\"changes\":[],\"unexpected\":true"),
        ] {
            assert!(host_review_header(&StrictJsonParser::parse(&bad).unwrap()).is_err());
        }
        let root = Path::new("/tmp/p17-host-source-schema");
        let sources = [
            HOST_BASELINE_FILES[0].0,
            HOST_BASELINE_FILES[1].0,
            HOST_BASELINE_FILES[2].0,
            HOST_BASELINE_FILES[3].0,
            HOST_BASELINE_FILES[4].0,
            HOST_CHANGES[1],
            HOST_CHANGES[2],
        ]
        .iter()
        .map(|relative| {
            format!(
                "{{\"path\":{},\"sha256\":{}}}",
                report::q(&root.join(relative).display().to_string()),
                report::q(&"0".repeat(64))
            )
        })
        .collect::<Vec<_>>();
        let record = |parts: &[String]| {
            StrictJsonParser::parse(&format!("{{\"source_inputs\":[{}]}}", parts.join(",")))
                .unwrap()
        };
        assert!(host_source_schema(root, &record(&sources[..6]), false).is_ok());
        assert!(host_source_schema(root, &record(&sources), true).is_ok());
        assert!(host_source_schema(root, &record(&sources[..5]), false).is_err());
        let mut duplicate = sources.clone();
        duplicate[5] = duplicate[4].clone();
        assert!(host_source_schema(root, &record(&duplicate[..6]), false).is_err());
        let mut missing_hash = sources.clone();
        missing_hash[0] = missing_hash[0].replace(",\"sha256\":", ",\"missing_sha\":");
        assert!(host_source_schema(root, &record(&missing_hash[..6]), false).is_err());
        assert!(host_source_schema(root, &record(&sources[..6]), true).is_err());
        let mut historical = report::PhaseSourceView::new();
        let added = root.join(HOST_CHANGES[1]).display().to_string();
        historical.mark_old_absent(added.clone());
        let claimed = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&added),
            report::q(&"0".repeat(64))
        ))
        .unwrap();
        assert!(report::historical_input(&claimed, &historical).is_err());
    }

    #[test]
    fn p17_phase_host_named_logs_require_real_fixed_passes() {
        for names in [HOST_UNIT_SELECTORS, HOST_PUBLIC_SELECTORS] {
            let lines = names
                .iter()
                .map(|name| format!("test {name} ... ok\n"))
                .collect::<String>();
            let good = format!(
                "running {} tests\n{}test result: ok. {} passed; 0 failed; 0 ignored; 0 measured; 19 filtered out; finished in 0.01s\n",
                names.len(),
                lines,
                names.len()
            );
            assert!(host_regression_log(&good, names).is_ok());
            assert!(parse_named_log(&good, names).is_err());
            for bad in [
                good.replace(&format!("test {} ... ok\n", names[0]), ""),
                good.replace(names[0], "p17_host_unknown"),
                format!("test {} ... ok\n{good}", names[0]),
                good.replace(&format!("{} passed", names.len()), "0 passed"),
                good.replace(&format!("test {} ... ok", names[0]), &format!("test {} ... ignored", names[0])),
                good.replace(&format!("test {} ... ok", names[0]), &format!("test {} ... FAILED", names[0])),
                "test result: ok. 0 passed; 0 failed; 0 ignored; 0 measured; 19 filtered out; finished in 0.01s\n".into(),
            ] {
                assert!(host_regression_log(&bad, names).is_err(), "{bad}");
            }
        }
    }

    #[test]
    fn p17_phase_error_position_runtime_command_switch_is_closed() {
        let old = phase_runtime_command(false);
        let current = phase_runtime_command(true);
        assert_eq!(old.len() + 1, current.len());
        assert_eq!(current[9], "--exact");
        let record = |command: &[&str]| {
            StrictJsonParser::parse(&format!(
                "{{\"command\":[{}]}}",
                command
                    .iter()
                    .map(|arg| report::q(arg))
                    .collect::<Vec<_>>()
                    .join(",")
            ))
            .unwrap()
        };
        assert!(phase_runtime_command_matches(&record(&old), false).unwrap());
        assert!(phase_runtime_command_matches(&record(&current), true).unwrap());
        assert!(!phase_runtime_command_matches(&record(&old), true).unwrap());
        assert!(!phase_runtime_command_matches(&record(&current), false).unwrap());
        let mut wrong = current.clone();
        wrong[7] = "wrong_selector";
        assert!(!phase_runtime_command_matches(&record(&wrong), true).unwrap());
        let mut duplicate = current.clone();
        duplicate.insert(10, "--exact");
        assert!(!phase_runtime_command_matches(&record(&duplicate), true).unwrap());
        assert!(phase_runtime_command_matches(
            &StrictJsonParser::parse("{\"missing_command\":[]}").unwrap(),
            true
        )
        .is_err());
    }

    #[test]
    fn p17_phase_error_position_host_chain_requires_exact_current_sources() {
        let root = Path::new("/tmp/p17-error-host-root");
        let evidence = Path::new("/tmp/p17-error-host-evidence");
        let mut host = HostReview {
            input: report::Input {
                path: evidence
                    .join("p17-phase-host-source-impact-review.json")
                    .display()
                    .to_string(),
                sha256: "a".repeat(64),
            },
            baseline: report::Input {
                path: String::new(),
                sha256: String::new(),
            },
            accepted_review: report::Input {
                path: String::new(),
                sha256: String::new(),
            },
            accepted_reuse: report::Input {
                path: String::new(),
                sha256: String::new(),
            },
            current_sources: HOST_CHANGES.map(|relative| report::Input {
                path: root.join(relative).display().to_string(),
                sha256: "b".repeat(64),
            }),
        };
        assert!(error_host_sources(root, evidence, Some(&host)).is_ok());
        assert!(error_host_sources(root, evidence, None).is_err());
        host.input.path = evidence.join("other-review.json").display().to_string();
        assert!(error_host_sources(root, evidence, Some(&host)).is_err());
        host.input.path = evidence
            .join("p17-phase-host-source-impact-review.json")
            .display()
            .to_string();
        host.current_sources.swap(1, 2);
        assert!(error_host_sources(root, evidence, Some(&host)).is_err());
        host.current_sources.swap(1, 2);
        host.current_sources[1].path = root.join("unrelated.rs").display().to_string();
        assert!(error_host_sources(root, evidence, Some(&host)).is_err());
        host.current_sources[1].path = root.join(HOST_CHANGES[1]).display().to_string();
        host.current_sources[1].sha256 = "bad".into();
        assert!(error_host_sources(root, evidence, Some(&host)).is_err());
    }

    #[test]
    fn p17_phase_b02_archive_schema_requires_two_fixed_artifacts() {
        let mut header = [0u8; 16];
        header[..4].copy_from_slice(&[0xcf, 0xfa, 0xed, 0xfe]);
        header[4..8].copy_from_slice(&0x0100_000c_u32.to_le_bytes());
        header[12..16].copy_from_slice(&2_u32.to_le_bytes());
        assert!(b02_archive_mach_execute_header(&header));
        header[12] = 6;
        assert!(!b02_archive_mach_execute_header(&header));
        header[12] = 2;
        header[4] = 7;
        assert!(!b02_archive_mach_execute_header(&header));
        let target = Path::new("/tmp/p17-archive-target");
        let archive = Path::new("/tmp/p17-archive-evidence/p17-b02-artifact-baseline");
        let artifact = |(_, filename, digest): (&str, &str, &str)| {
            format!(
                "{{\"original_path\":{},\"snapshot_path\":{},\"sha256\":{}}}",
                report::q(
                    &target
                        .join("debug/deps")
                        .join(filename)
                        .display()
                        .to_string()
                ),
                report::q(&archive.join(filename).display().to_string()),
                report::q(digest),
            )
        };
        let first = artifact(B02_ARCHIVE_BINARIES[0]);
        let second = artifact(B02_ARCHIVE_BINARIES[1]);
        let good = format!(
            "{{\"schema\":\"rivetlua-p17-artifact-archive-v1\",\"batch\":\"P17-B02\",\"report_sha256\":{},\"artifacts\":[{first},{second}]}}",
            report::q(B02_SHA),
        );
        assert!(
            b02_archive_schema(&StrictJsonParser::parse(&good).unwrap(), target, archive).is_ok()
        );
        for bad in [
            format!("{{\"schema\":\"rivetlua-p17-artifact-archive-v1\",\"batch\":\"P17-B02\",\"report_sha256\":{},\"artifacts\":[{first}]}}", report::q(B02_SHA)),
            good.replace(B02_SHA, &"0".repeat(64)),
            good.replace(B02_ARCHIVE_BINARIES[0].2, &"0".repeat(64)),
            good.replace(B02_ARCHIVE_BINARIES[1].1, B02_ARCHIVE_BINARIES[0].1),
            good.replace("/tmp/p17-archive-target/debug/deps", "/tmp/wrong-target/debug/deps"),
            good.replace("p17-b02-artifact-baseline", "wrong-archive"),
            good.replace("\"artifacts\":", "\"missing_artifacts\":"),
        ] {
            assert!(b02_archive_schema(&StrictJsonParser::parse(&bad).unwrap(), target, archive).is_err(), "{bad}");
        }
    }

    #[test]
    fn p17_phase_error_position_review_and_sources_are_closed() {
        let good = format!(
            "{{\"schema\":\"rivetlua-p17-error-position-impact-v1\",\"baseline_manifest_sha256\":{},\"accepted_export_review_sha256\":{},\"accepted_host_review_sha256\":{},\"b01_report_sha256\":{},\"b02_report_sha256\":{},\"b03_report_sha256\":{},\"changes\":[],\"builds\":[],\"regressions\":[],\"review_note\":\"來源與回歸均已審查\"}}",
            report::q(ERROR_BASELINE_SHA), report::q(ACCEPTED_ERROR_EXPORT_SHA),
            report::q(ACCEPTED_ERROR_HOST_SHA), report::q(B01_SHA),
            report::q(B02_SHA), report::q(B03_SHA),
        );
        assert!(error_review_header(&StrictJsonParser::parse(&good).unwrap()).is_ok());
        for bad in [
            good.replace(ERROR_BASELINE_SHA, &"0".repeat(64)),
            good.replace(ACCEPTED_ERROR_HOST_SHA, &"0".repeat(64)),
            good.replace("\"baseline_manifest_sha256\":", "\"missing_sha\":"),
            good.replace(
                "\"review_note\":\"來源與回歸均已審查\"",
                "\"review_note\":\"\"",
            ),
            good.replace("\"changes\":[]", "\"changes\":[],\"unexpected\":true"),
        ] {
            assert!(
                error_review_header(&StrictJsonParser::parse(&bad).unwrap()).is_err(),
                "{bad}"
            );
        }
        let change = |path: &str, before: &str| {
            format!(
            "{{\"path\":{},\"before_sha256\":{},\"after_sha256\":{},\"diff_path\":\"/tmp/proof.diff\",\"diff_sha256\":{}}}",
            report::q(path), before, report::q(&"a".repeat(64)), report::q(&"b".repeat(64)),
        )
        };
        let old = change(ERROR_CHANGES[0], &report::q(ERROR_FILES[0].1));
        let added = change(ERROR_CHANGES[1], "null");
        let changes = format!("{{\"changes\":[{old},{added}]}}");
        assert!(error_change_schema(&StrictJsonParser::parse(&changes).unwrap()).is_ok());
        for bad in [
            format!("{{\"changes\":[{old}]}}"),
            changes.replace(ERROR_CHANGES[1], "unknown.rs"),
            changes.replace("\"before_sha256\":null", "\"before_sha256\":\"0\""),
            changes.replace(&"b".repeat(64), "bad"),
        ] {
            assert!(
                error_change_schema(&StrictJsonParser::parse(&bad).unwrap()).is_err(),
                "{bad}"
            );
        }
        let root = Path::new("/tmp/p17-error-position-schema");
        let paths = [ERROR_FILES[0].0, ERROR_FILES[1].0, ERROR_NEW_TEST];
        let sources = paths
            .iter()
            .map(|relative| {
                format!(
                    "{{\"path\":{},\"sha256\":{}}}",
                    report::q(&root.join(relative).display().to_string()),
                    report::q(&"c".repeat(64)),
                )
            })
            .collect::<Vec<_>>();
        let record = |items: &[String]| {
            StrictJsonParser::parse(&format!("{{\"source_inputs\":[{}]}}", items.join(",")))
                .unwrap()
        };
        assert!(error_source_schema(root, &record(&sources), &paths).is_ok());
        assert!(error_source_schema(root, &record(&sources[..2]), &paths).is_err());
        let mut duplicate = sources.clone();
        duplicate[2] = duplicate[1].clone();
        assert!(error_source_schema(root, &record(&duplicate), &paths).is_err());
        let mut missing_hash = sources.clone();
        missing_hash[0] = missing_hash[0].replace("\"sha256\":", "\"missing\":");
        assert!(error_source_schema(root, &record(&missing_hash), &paths).is_err());
        let mut wrong_control = sources.clone();
        wrong_control[1] = wrong_control[1].replace(&"c".repeat(64), "invalid");
        assert!(error_source_schema(root, &record(&wrong_control), &paths).is_err());
    }

    #[test]
    fn p17_phase_error_position_named_and_build_logs_fail_closed() {
        let names = [
            "p17_error_position_basic",
            "p17_error_position_dispatch_lifecycle",
        ];
        let good = format!(
            "running 2 tests\ntest {} ... ok\ntest {} ... ok\ntest result: ok. 2 passed; 0 failed; 0 ignored; 0 measured; 7 filtered out; finished in 0.01s\n",
            names[0], names[1],
        );
        assert!(error_named_log(&good, &names).is_ok());
        for bad in [
            good.replace("running 2 tests", "running 0 tests"),
            good.replace(&format!("test {} ... ok\n", names[0]), ""),
            good.replace(names[1], "p17_unknown"),
            good.replace("2 passed", "1 passed"),
            good.replace("7 filtered out", "bad filtered out"),
            good.replace("... ok", "... ignored"),
            good.replace("... ok", "... FAILED"),
            format!("test {} ... ok\n{good}", names[0]),
            "running 0 tests\ntest result: ok. 0 passed; 0 failed; 0 ignored; 0 measured; 7 filtered out; finished in 0.01s\n".into(),
        ] {
            assert!(error_named_log(&bad, &names).is_err(), "{bad}");
        }
        let artifact = |name: &str| {
            format!(
            "{{\"reason\":\"compiler-artifact\",\"target\":{{\"name\":{},\"kind\":[\"test\"]}},\"executable\":\"/tmp/fresh\"}}\n",
            report::q(name),
        )
        };
        let builds = format!(
            "{}{}",
            artifact("p17_internal_replacements"),
            artifact("p17_lifecycle")
        );
        assert_eq!(error_artifacts(&builds).unwrap().len(), 2);
        for bad in [
            artifact("p17_lifecycle"),
            format!("{builds}{}", artifact("p17_lifecycle")),
            builds.replace("\"kind\":[\"test\"]", "\"kind\":[\"bin\"]"),
            builds.replace("p17_internal_replacements", "p17_unknown"),
        ] {
            assert!(error_artifacts(&bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn p17_phase_error_position_lifecycle_marker_requires_real_metrics() {
        let marker = "{\"case_id\":\"p17_stress_gc_long_run\",\"profile\":\"lua55-i64f64\",\"seed\":1519619,\"iterations\":128,\"outcome\":\"PASS\",\"guest_operations\":8192,\"normal_operations\":4096,\"error_operations\":4096,\"gc_cycles\":384,\"root_count\":0,\"ledger_committed\":0,\"ledger_reserved\":0,\"peak_committed\":1}";
        let body = format!(
            "running 1 test\ntest p17_stress_gc_long_run ... {MARKER}{marker}\nok\ntest result: ok. 1 passed; 0 failed; 0 ignored; 0 measured; 1 filtered out; finished in 0.01s\n"
        );
        assert!(error_named_log(&body, &["p17_stress_gc_long_run"]).is_ok());
        let values = marker_records(&body, &["p17_stress_gc_long_run"], true).unwrap();
        let registry = Registry {
            corpus: report::Input {
                path: String::new(),
                sha256: String::new(),
            },
            capabilities: report::Input {
                path: String::new(),
                sha256: String::new(),
            },
            families: Vec::new(),
        };
        let spec = CASES
            .iter()
            .copied()
            .find(|spec| spec.id == "p17_stress_gc_long_run")
            .unwrap();
        assert!(
            validate_record(values.get(spec.id).unwrap(), spec, PROFILES[0], &registry, false).is_ok()
        );
        for bad in [
            marker.replace("1519619", "0"),
            marker.replace("\"iterations\":128", "\"iterations\":0"),
            marker.replace("\"root_count\":0", "\"root_count\":1"),
            marker.replace("\"ledger_committed\":0", "\"ledger_committed\":1"),
            marker.replace("\"ledger_reserved\":0", "\"ledger_reserved\":1"),
            marker.replace("\"guest_operations\":8192", "\"guest_operations\":0"),
        ] {
            let value = StrictJsonParser::parse(&bad).unwrap();
            assert!(
                validate_record(&value, spec, PROFILES[0], &registry, false).is_err(),
                "{bad}"
            );
        }
        let coroutine = "{\"case_id\":\"p17_stress_coroutine_debug\",\"profile\":\"lua55-i64f64\",\"seed\":1519619,\"iterations\":128,\"outcome\":\"PASS\",\"guest_operations\":640,\"gc_cycles\":384,\"root_count\":1,\"ledger_committed\":0,\"ledger_reserved\":0,\"peak_committed\":1}";
        let coroutine_spec = CASES.iter().copied()
            .find(|case| case.id == "p17_stress_coroutine_debug").unwrap();
        let current = StrictJsonParser::parse(coroutine).unwrap();
        assert!(validate_record(&current, coroutine_spec, PROFILES[0], &registry, false).is_ok());
        assert!(validate_record(&current, coroutine_spec, PROFILES[0], &registry, true).is_err());
        for bad in [
            coroutine.replace("\"root_count\":1", "\"root_count\":0"),
            coroutine.replace("\"root_count\":1", "\"root_count\":2"),
            coroutine.replace("\"ledger_committed\":0", "\"ledger_committed\":1"),
            coroutine.replace("\"ledger_reserved\":0", "\"ledger_reserved\":1"),
        ] {
            let value = StrictJsonParser::parse(&bad).unwrap();
            assert!(validate_record(&value, coroutine_spec, PROFILES[0], &registry, false).is_err(), "{bad}");
        }
        let historical = StrictJsonParser::parse(
            &coroutine.replace("\"root_count\":1", "\"root_count\":0")).unwrap();
        assert!(validate_record(&historical, coroutine_spec, PROFILES[0], &registry, true).is_ok());
        assert!(marker_records(
            &body.replace("p17_stress_gc_long_run", "unknown"),
            &["p17_stress_gc_long_run"],
            true
        )
        .is_err());
    }

    #[test]
    fn p17_phase_debug_console_header_and_diff_are_closed() {
        let value = format!(
            "{{\"schema\":\"rivetlua-p17-debug-console-impact-v1\",\"main_baseline_manifest_sha256\":{},\"pending_baseline_manifest_sha256\":{},\"heap_baseline_manifest_sha256\":{},\"tools_baseline_manifest_sha256\":{},\"accepted_phase_report_sha256\":{},\"accepted_phase_receipt_sha256\":{},\"accepted_export_review_sha256\":{},\"accepted_host_review_sha256\":{},\"accepted_error_review_sha256\":{},\"b01_report_sha256\":{},\"b02_report_sha256\":{},\"b03_report_sha256\":{},\"changes\":[],\"builds\":[],\"regressions\":[],\"reuse_basis\":\"固定 compiler、fuzz、platform 的未變輸入\",\"review_note\":\"逐項檢視實際差異與回歸\"}}",
            report::q(CONSOLE_MAIN_BASELINE_SHA), report::q(CONSOLE_PENDING_BASELINE_SHA),
            report::q(CONSOLE_HEAP_BASELINE_SHA), report::q(CONSOLE_TOOLS_BASELINE_SHA), report::q(CONSOLE_ACCEPTED_PHASE_SHA),
            report::q(CONSOLE_ACCEPTED_RECEIPT_SHA), report::q(CONSOLE_EXPORT_SHA),
            report::q(CONSOLE_HOST_SHA), report::q(CONSOLE_ERROR_SHA),
            report::q(B01_SHA), report::q(B02_SHA), report::q(B03_SHA),
        );
        let parsed = StrictJsonParser::parse(&value).unwrap();
        assert!(console_review_header(&parsed).is_ok());
        for invalid in [
            value.replace(CONSOLE_MAIN_BASELINE_SHA, &"0".repeat(64)),
            value.replace(CONSOLE_HEAP_BASELINE_SHA, &"0".repeat(64)),
            value.replace("\"changes\":[]", "\"extra\":1,\"changes\":[]"),
            value.replace("rivetlua-p17-debug-console-impact-v1", "unknown"),
        ] {
            assert!(console_review_header(&StrictJsonParser::parse(&invalid).unwrap()).is_err());
        }
        let change = "{\"path\":\"a.rs\",\"before_sha256\":\"before\",\"after_sha256\":\"after\",\"diff_path\":\"/diff\",\"diff_sha256\":\"digest\"}";
        let change_value = StrictJsonParser::parse(change).unwrap();
        assert!(console_change_identity(
            &change_value,
            "a.rs",
            Some("before"),
            "after",
            Path::new("/diff")
        )
        .is_ok());
        assert!(console_change_identity(
            &change_value,
            "other.rs",
            Some("before"),
            "after",
            Path::new("/diff")
        )
        .is_err());
        assert!(console_change_identity(
            &change_value,
            "a.rs",
            Some("wrong"),
            "after",
            Path::new("/diff")
        )
        .is_err());
        assert!(console_change_identity(
            &change_value,
            "a.rs",
            Some("before"),
            "wrong",
            Path::new("/diff")
        )
        .is_err());
        assert!(console_change_identity(
            &change_value,
            "a.rs",
            Some("before"),
            "after",
            Path::new("/wrong")
        )
        .is_err());
        assert!(
            console_change_identity(&change_value, "a.rs", None, "after", Path::new("/diff"))
                .is_err()
        );
        let added = StrictJsonParser::parse(&change.replace("\"before\"", "null")).unwrap();
        assert!(console_change_identity(&added, "a.rs", None, "after", Path::new("/diff")).is_ok());
        assert!(console_baseline_absence(Some(0), b"").is_ok());
        assert!(console_baseline_absence(
            Some(0),
            b"crates/rivetlua-runtime/tests/p17_debug_console.rs\n"
        )
        .is_err());
        assert!(console_baseline_absence(Some(128), b"").is_err());
        assert!(console_baseline_absence(None, b"").is_err());
        let before = Path::new("/before.rs");
        let current = Path::new("/current.rs");
        let effective = Path::new("/snapshot.rs");
        let generated = b"diff --git a/before.rs b/snapshot.rs\nindex 0000001..0000002 100644\n--- a/before.rs\n+++ b/snapshot.rs\n@@ -1 +1 @@\n-old\n+new\n";
        let stored = "diff --git a/before.rs b/current.rs\nindex 0000001..0000002 100644\n--- a/before.rs\n+++ b/current.rs\n@@ -1 +1 @@\n-old\n+new\n";
        assert!(
            console_old_diff_matches(generated, stored.as_bytes(), before, current, effective)
                .unwrap()
        );
        assert!(!console_old_diff_matches(
            generated,
            stored.replace("+new\n", "+wrong\n").as_bytes(),
            before,
            current,
            effective
        )
        .unwrap());
        assert!(console_old_diff_matches(
            generated,
            stored
                .replace("+++ b/current.rs", "+++ b/other.rs")
                .as_bytes(),
            before,
            current,
            effective
        )
        .is_err());
        let added_generated = b"diff --git a/snapshot.rs b/snapshot.rs\nnew file mode 100644\nindex 0000000..1234567\n--- /dev/null\n+++ b/snapshot.rs\n@@ -0,0 +1 @@\n+new\n";
        let added_stored = b"diff --git a/current.rs b/current.rs\nnew file mode 100644\nindex 0000000..1234567\n--- /dev/null\n+++ b/current.rs\n@@ -0,0 +1 @@\n+new\n";
        assert!(console_old_diff_matches(
            added_generated,
            added_stored,
            Path::new("/dev/null"),
            current,
            effective
        )
        .unwrap());
    }

    #[test]
    fn p17_phase_assert_historical_diff_endpoint() {
        let before = Path::new("/e/assert-before.rs");
        let middle = Path::new("/e/warning-middle.rs");
        let current = Path::new("/r/vm.rs");
        let generated = b"diff --git a/e/assert-before.rs b/e/warning-middle.rs\nindex 0000001..0000002 100644\n--- a/e/assert-before.rs\n+++ b/e/warning-middle.rs\n@@ -1 +1 @@\n-old\n+new\n";
        assert!(
            assert_warning_diff_matches("assert", generated, generated, before, current, middle)
                .unwrap()
        );
        for stored in [
            String::from_utf8_lossy(generated).replace("b/e/warning-middle.rs", "b/r/vm.rs"),
            String::from_utf8_lossy(generated).replace("b/e/warning-middle.rs", "b/e/other.rs"),
            String::from_utf8_lossy(generated).replace("+new\n", "+wrong\n"),
            String::from_utf8_lossy(generated).replace("0000002", "0000003"),
        ] {
            assert!(
                !assert_warning_diff_matches(
                    "assert",
                    generated,
                    stored.as_bytes(),
                    before,
                    current,
                    middle,
                )
                .unwrap()
            );
        }
        let warning_recorded = String::from_utf8_lossy(generated)
            .replace("b/e/warning-middle.rs", "b/r/vm.rs");
        assert!(
            assert_warning_diff_matches(
                "warning",
                generated,
                warning_recorded.as_bytes(),
                before,
                current,
                middle,
            )
            .unwrap()
        );
        assert!(
            !assert_warning_diff_matches(
                "warning",
                generated,
                warning_recorded.replace("+new\n", "+wrong\n").as_bytes(),
                before,
                current,
                middle,
            )
            .unwrap()
        );
    }

    #[test]
    fn p17_phase_host_exit_endpoint_shared_mapping() {
        let base = std::env::temp_dir().join(format!(
            "p17-host-exit-endpoint-{}-{}",
            std::process::id(),
            SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()
        ));
        let root = base.join("repo");
        let current = root.join(HOST_CHANGES[1]);
        fs::create_dir_all(current.parent().unwrap()).unwrap();
        fs::write(&current, b"Exit current source").unwrap();
        let snapshot = base.join("trusted-host-before.rs");
        fs::write(&snapshot, b"Host recorded source").unwrap();
        let digest = manifest::sha256(&snapshot).unwrap();
        let current_digest = manifest::sha256(&current).unwrap();
        let source = report::HistoricalSource {
            before_sha256: digest.clone(),
            snapshot: snapshot.clone(),
        };
        let host_change = |after: &str, path: &str| {
            StrictJsonParser::parse(&format!(
                "{{\"path\":{},\"before_sha256\":null,\"after_sha256\":{},\"diff_path\":\"/fixed/host.diff\",\"diff_sha256\":\"{}\"}}",
                report::q(path), report::q(after), "0".repeat(64)
            ))
            .unwrap()
        };
        let empty = report::Input {
            path: String::new(),
            sha256: String::new(),
        };
        let fresh = || ConsoleReview {
            input: empty.clone(),
            baselines: std::array::from_fn(|_| empty.clone()),
            accepted_report: empty.clone(),
            accepted_receipt: empty.clone(),
            old_sources: BTreeMap::new(),
            original_root: root.clone(),
            current_root: root.clone(),
            ctrl_c_updated: false,
            verified: None,
        };
        let current_record = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&current.display().to_string()), report::q(&current_digest)
        ))
        .unwrap();
        let historic_record = StrictJsonParser::parse(&format!(
            "{{\"path\":{},\"sha256\":{}}}",
            report::q(&current.display().to_string()), report::q(&digest)
        ))
        .unwrap();
        let mut console = fresh();
        assert_eq!(console.endpoint(&root, HOST_CHANGES[1]), current);
        assert!(console.historical_input(&current_record).is_ok());
        bind_host_exit_endpoint(
            &root,
            &mut console,
            Some(&source),
            &host_change(&digest, HOST_CHANGES[1]),
        )
        .unwrap();
        assert_eq!(console.endpoint(&root, HOST_CHANGES[1]), snapshot);
        assert!(console.historical_input(&historic_record).is_ok());
        assert!(console.historical_input(&current_record).is_err());

        assert!(bind_host_exit_endpoint(
            &root, &mut fresh(), None, &host_change(&digest, HOST_CHANGES[1])
        )
        .is_err());
        let wrong_sha = report::HistoricalSource {
            before_sha256: "0".repeat(64),
            snapshot: snapshot.clone(),
        };
        assert!(bind_host_exit_endpoint(
            &root, &mut fresh(), Some(&wrong_sha), &host_change(&digest, HOST_CHANGES[1])
        )
        .is_err());
        let wrong_snapshot = base.join("wrong.rs");
        fs::write(&wrong_snapshot, b"Different source").unwrap();
        let wrong_snapshot_source = report::HistoricalSource {
            before_sha256: digest.clone(),
            snapshot: wrong_snapshot,
        };
        assert!(bind_host_exit_endpoint(
            &root, &mut fresh(), Some(&wrong_snapshot_source), &host_change(&digest, HOST_CHANGES[1])
        )
        .is_err());
        assert!(bind_host_exit_endpoint(
            &root, &mut fresh(), Some(&source), &host_change(&"0".repeat(64), HOST_CHANGES[1])
        )
        .is_err());
        assert!(bind_host_exit_endpoint(
            &root, &mut fresh(), Some(&source), &host_change(&digest, HOST_CHANGES[0])
        )
        .is_err());
        let mut conflict = fresh();
        conflict.old_sources.insert(
            current.display().to_string(),
            report::HistoricalSource {
                before_sha256: current_digest,
                snapshot: current.clone(),
            },
        );
        assert!(bind_host_exit_endpoint(
            &root, &mut conflict, Some(&source), &host_change(&digest, HOST_CHANGES[1])
        )
        .is_err());
        assert_eq!(conflict.endpoint(&root, HOST_CHANGES[1]), current);
        fs::remove_dir_all(base).unwrap();
    }

    #[test]
