    #[test]
    fn p17_core_debug_successor_typed_edge_rejects_missing_wrong_duplicate() {
        let root = fs::canonicalize(Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap()).unwrap();
        let evidence = PathBuf::from(std::env::var("RIVETLUA_P17_EVIDENCE_DIR").unwrap());
        let proof = StrictJsonParser::parse(&fs::read_to_string(
            evidence.join(CORE_SUCCESSOR_PROOF_FILE)).unwrap()).unwrap();
        let edge = field(&proof, "core_edge").unwrap();
        let core_path = root.join(PRODUCER_NATIVE_PATH);
        let old_snapshot = evidence.join(FINAL_REPAIR_CHILD_FILE).parent().unwrap()
            .join("30-crates-rivetlua-core-src-bytecode-official_native.rs");
        let successor_dir = evidence.join(CORE_SUCCESSOR_SOURCE_FILE).parent().unwrap().to_path_buf();
        let new_snapshot = successor_dir.join("official-native-f0fa7dbb2b6d.rs");
        let diff = successor_dir.join("official-native-31013-to-f0fa7.diff");
        assert!(core_successor_edge_shape(edge, &core_path,
            &old_snapshot, &new_snapshot, &diff).is_ok());
        assert!(field(&proof, "missing_core_edge").is_err());
        let wrong = "0".repeat(64);
        let edge_json = canonical_json(edge);
        for bad in [
            edge_json.replace(CORE_SUCCESSOR_BEFORE_SHA, &wrong),
            edge_json.replace(CORE_SUCCESSOR_AFTER_SHA, &wrong),
            edge_json.replace(&old_snapshot.display().to_string(), "/wrong/old.rs"),
            edge_json.replace(&new_snapshot.display().to_string(), "/wrong/new.rs"),
        ] {
            let bad_edge = StrictJsonParser::parse(&bad).unwrap();
            assert!(core_successor_edge_shape(&bad_edge, &core_path,
                &old_snapshot, &new_snapshot, &diff).is_err());
        }
        assert!(core_successor_edge_shape(edge, &core_path,
            &old_snapshot, &successor_dir.join("wrong.rs"), &diff).is_err());
        assert!(core_successor_edge_shape(edge, &core_path,
            &old_snapshot, &new_snapshot, &successor_dir.join("wrong.diff")).is_err());
        assert_eq!(core_successor_sha(PRODUCER_NATIVE_PATH, CORE_SUCCESSOR_BEFORE_SHA, true),
            CORE_SUCCESSOR_AFTER_SHA);
        assert_eq!(core_successor_sha(PRODUCER_NATIVE_PATH, CORE_SUCCESSOR_BEFORE_SHA, false),
            CORE_SUCCESSOR_BEFORE_SHA);
        assert_eq!(core_successor_sha(PRODUCER_NATIVE_PATH, &wrong, true), wrong);
        assert_eq!(core_successor_sha("xtask/src/p17/b02.rs", CORE_SUCCESSOR_BEFORE_SHA, true),
            CORE_SUCCESSOR_BEFORE_SHA);
        let verified = FinalVerifiedContext::verify(&root, &evidence).unwrap().unwrap();
        assert!(verified.repair_active && verified.core_successor_active);
        assert_eq!(verified.source_shas.get(&core_path).map(String::as_str),
            Some(PRODUCT_CORE_AFTER_SHA));
        let historical_root = root.join("phase-historical");
        let recorded = historical_root.join(PRODUCER_NATIVE_PATH).display().to_string();
        let (_, before, _) = FINAL_REPAIR_PRODUCT_CHANGES[0];
        assert_eq!(final_source_relocated_source_with_verified(
            &historical_root, &root, &evidence, &recorded, before, Some(&verified)).unwrap(),
            PathBuf::from(PRODUCER_NATIVE_PATH));
        let mut no_proof = verified.clone();
        no_proof.core_successor_active = false;
        assert!(final_source_relocated_source_with_verified(
            &historical_root, &root, &evidence, &recorded, before, Some(&no_proof)).is_err());
        let mut wrong_after = verified.clone();
        wrong_after.source_shas.insert(core_path.clone(), wrong.clone());
        assert!(final_source_relocated_source_with_verified(
            &historical_root, &root, &evidence, &recorded, before, Some(&wrong_after)).is_err());
        assert!(final_source_relocated_source_with_verified(
            &historical_root, &root, &evidence, &recorded, &wrong, Some(&verified)).is_err());
        let mut changed = FINAL_REPAIR_PRODUCT_CHANGES.iter()
            .map(|(path, _, _)| (*path).to_owned())
            .chain([FINAL_CODEC_PATH.to_owned(), FINAL_COUNT_TEST_PATH.to_owned(),
                DEBUG_VM_TEST_PATH.to_owned(), GC_TOOL_PATH.to_owned()]).collect::<Vec<_>>();
        changed.push(PRODUCER_NATIVE_PATH.to_owned());
        assert!(final_repair_changed_paths(&changed, true).is_err());
    }

    #[test]
    fn p17_heap_successor_rows_reject_missing_wrong_duplicate_and_multi_change() {
        let evidence = PathBuf::from(std::env::var("RIVETLUA_P17_EVIDENCE_DIR").unwrap());
        let parent_path = evidence.join(CORE_SUCCESSOR_FORMAL_FILE);
        let state_path = evidence.join(HEAP_SUCCESSOR_SOURCE_FILE);
        let parent = StrictJsonParser::parse(&fs::read_to_string(&parent_path).unwrap()).unwrap();
        let state = StrictJsonParser::parse(&fs::read_to_string(&state_path).unwrap()).unwrap();
        let root = Path::new(string(&state, "repository_root").unwrap());
        let heap = root.join(GC_HEAP_PATH);
        let before = parent_path.parent().unwrap().join("36-crates-rivetlua-runtime-src-heap.rs");
        let after = state_path.parent().unwrap().join("heap.rs");
        let gc = root.join(GC_MOD_PATH);
        let gc_after = state_path.parent().unwrap().join("gc-mod.rs");
        assert!(heap_successor_rows(&parent, &state, &heap, &before, &after, &gc, &gc_after).is_ok());
        assert_eq!(heap_successor_sha(GC_HEAP_PATH, HEAP_SUCCESSOR_BEFORE_SHA, true),
            HEAP_SUCCESSOR_AFTER_SHA);
        assert_eq!(heap_successor_sha(GC_HEAP_PATH, HEAP_SUCCESSOR_BEFORE_SHA, false),
            HEAP_SUCCESSOR_BEFORE_SHA);
        let wrong = "0".repeat(64);
        assert_eq!(heap_successor_sha(GC_HEAP_PATH, &wrong, true), wrong);
        assert_eq!(heap_successor_sha(PRODUCER_NATIVE_PATH, HEAP_SUCCESSOR_BEFORE_SHA, true),
            HEAP_SUCCESSOR_BEFORE_SHA);
        let raw = array(&state, "source_files").unwrap().iter()
            .map(canonical_json).collect::<Vec<_>>();
        let shaped = |rows: &[String]| {
            StrictJsonParser::parse(&format!("{{\"source_files\":[{}]}}", rows.join(","))).unwrap()
        };
        let mut missing = raw.clone();
        missing.remove(0);
        assert!(heap_successor_rows(&parent, &shaped(&missing), &heap, &before, &after, &gc, &gc_after).is_err());
        let mut duplicate = raw.clone();
        duplicate[1] = duplicate[0].clone();
        assert!(heap_successor_rows(&parent, &shaped(&duplicate), &heap, &before, &after, &gc, &gc_after).is_err());
        let mut wrong_heap = raw.clone();
        let index = array(&state, "source_files").unwrap().iter().position(|row|
            string(row, "path").unwrap() == heap.display().to_string()).unwrap();
        wrong_heap[index] = wrong_heap[index].replace(HEAP_SUCCESSOR_AFTER_SHA, &wrong);
        assert!(heap_successor_rows(&parent, &shaped(&wrong_heap), &heap, &before, &after, &gc, &gc_after).is_err());
        let mut wrong_gc = raw.clone();
        let gc_index = array(&state, "source_files").unwrap().iter().position(|row|
            string(row, "path").unwrap() == gc.display().to_string()).unwrap();
        wrong_gc[gc_index] = wrong_gc[gc_index].replace(GC_MOD_AFTER_SHA, &wrong);
        assert!(heap_successor_rows(&parent, &shaped(&wrong_gc), &heap, &before, &after,
            &gc, &gc_after).is_err());
        let mut multi = raw;
        let first = string(&array(&state, "source_files").unwrap()[0], "sha256").unwrap();
        multi[0] = multi[0].replace(first, &wrong);
        assert_ne!(multi[0], canonical_json(&array(&state, "source_files").unwrap()[0]));
        assert!(heap_successor_rows(&parent, &shaped(&multi), &heap, &before, &after, &gc, &gc_after).is_err());
    }

